COPLAS_PIEZA(9, [["lafuente_madrid-p0024-04",15,"De Oriente salen tres reyes\nPara adorar al Dios niño;\nUna estrella los guiaba\nPara seguir su camino.",210,0,-1,191,"",0,4,"io",-1,0,-1,0,24,24,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0024-05",15,"Quien quisiese comprar pan\nMás blanco que la azucena,\nEn el portal de Belen\nLa Vírgen es panadera.",210,0,-1,191,"",0,4,"ea",-1,0,-1,0,24,24,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0024-06",15,"Cuando la Virgen fué á misa\nAl templo de Salomon,\nEl vestido que llevaba\nEra de rayos de sol.",210,0,-1,191,"",0,4,"o",-1,0,-1,0,24,24,"","",0,"rm_t4, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0024-07",15,"San José era carpintero,\nY la Vírgen costurera,\nY el Niño labra la cruz,\nPorque ha de morir en ella.",210,0,-1,191,"",0,4,"ea",-1,0,-1,0,24,24,"","",0,"rm_t4, fernan_caballero","","",4,0,0,[],"",""],["lafuente_madrid-p0025-01",15,"No hay hombre como Manuel,\nNi mujer como María,\nAmor como amor de madre,\nNi luz como la del dia.",210,0,-1,191,"",0,4,"ia",0,0,-1,0,25,25,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0025-02",15,"El sol se vistió de luto,\nY la luna se eclipsó,\nLas piedras se quebrantaron\nCuando el Señor espiró.",210,0,-1,191,"",0,4,"o",2,0,-1,0,25,25,"","",0,"rm_t4","","",3,0,0,[],"",""],["lafuente_madrid-p0025-03",15,"La tierra sintió su muerte,\nY los cielos se nublaron,\nLas sepulturas se abrieron,\nLos muertos resucitaron.",210,0,-1,191,"",0,4,"ao",41,0,-1,0,25,25,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0025-04",15,"Un árbol hay en la Iglesia,\nCon espinas y sin flor;\nEn cada ramita, un ángel;\nEn medio, nuestro Señor.",210,0,-1,191,"",0,4,"o",72,0,-1,0,25,25,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0025-05",15,"Alza los ojos y mira\nEse Señor soberano,\nQue si estás arrepentido,\nEl remedio está en la mano.",210,0,-1,191,"",0,4,"ao",81,0,-1,0,25,25,"","",0,"","","",4,0,0,[],"",""],["lafuente_madrid-p0025-06",15,"No volvamos á ofender\nÁ Cristo crucificado,\nÁ aquel que por nuestro sér\nEs tanto lo que ha pasado.",210,0,-1,191,"",1,4,"ao",14,0,-1,0,25,25,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0026-01",15,"En el portal de Belen\nHay una piedra redonda\nDonde Jesus puso el pié\nPara subir á la gloria.",210,0,-1,191,"",0,4,"oa",-1,0,-1,0,26,26,"","",0,"","","",32,0,0,[],"",""],["lafuente_madrid-p0026-02",15,"Al pié de Sierra-Nevada\nTengo de hacer un convento\nTodo de piedra labrada\nPara el Santo Sacramento.",210,0,-1,191,"",1,4,"eo",94,0,-1,0,26,26,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0026-03",15,"Todos los santos son buenos,\nY san Juan es el mejor,\nPorque ese tuvo la dicha\nDe bautizar al Señor.",210,0,-1,191,"",0,4,"o",72,0,-1,0,26,26,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0026-04",15,"San Francisco es más que Dios,\nEn cuanto á las llagas, digo,\nQue al santo se las dió Dios,\nY á Dios se las dió un judio.",210,0,-1,191,"",0,4,"io",-1,0,-1,0,26,26,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0026-05",15,"Los profetas y patriarcas,\nY los mártires queremos,\nQue son nuestros protectores,\nY de Dios los mensajeros.",210,0,-1,191,"",0,4,"eo",-1,0,-1,0,26,26,"","",0,"rm_t4, palau_cantares, fernan_caballero","","",4,0,0,[],"",""],["lafuente_madrid-p0026-06",15,"¿Qué tienes con san Antonio\nQue tanto te acuerdas de él?\n-San Antonio está en el cielo,\n¡Quién estuviera con él!",210,0,-1,191,"",0,4,"e",-1,0,-1,0,26,26,"","",0,"rm_t4, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0026-07",15,"Válganme san Agustin,\nSanta Rita y santa Clara,\nY tambien válgame Aquel\nQue con el dedo señala.",210,0,-1,191,"",0,4,"aa",-1,0,-1,0,26,26,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0027-01",15,"Los sacerdotes en misa\nDicen: santo, santo, santo:\nLos ángeles en el cielo\nRepiten el mismo canto",210,0,-1,191,"",0,4,"ao",30,0,-1,0,27,27,"","",0,"rm_t4, palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0027-02",15,"Los sacerdotes en misa\nDicen: Ite, missa est;\nLos ángeles en el cielo\nDicen: Deo gratias, amen.",210,0,-1,191,"",0,4,"e",-1,0,-1,0,27,27,"","",0,"palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0027-03",15,"Si las ánimas benditas\nFueran á pedir limosna,\nHasta los reyes les dieran\nLos cetros y las coronas.",210,0,-1,191,"",0,4,"oa",-1,0,-1,0,27,27,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0027-04",15,"Si te quemas una mano,\n¿Qué dolor no pasarás?\nAcuérdate de las ánimas\nQue en el purgatorio están.",210,0,-1,191,"",0,4,"a",-1,0,-1,0,27,27,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0027-05",15,"Á las ánimas benditas\nNadie les cierre la puerta;\nCon decirles que perdonen,\nVan las ánimas contentas.",210,0,-1,191,"",0,4,"ea",-1,0,-1,0,27,27,"","",0,"rm_t4, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0027-06",15,"A san Antonio le pido\nQue me dé conformidad,\nQue los bienes de este mundo\nDios los quita y Dios los da.",210,0,-1,191,"",0,4,"a",-1,0,-1,0,27,27,"","",0,"rm_t4, palau_cantares, fernan_caballero","","",6,0,0,[],"",""],["lafuente_madrid-p0028-01",15,"En abril llueve bastante,\nLas aguas no son dañinas,\nQue las manda el Criador\nPara que salga la espiga.",210,0,-1,191,"",0,4,"ia",-1,0,-1,0,28,28,"","",0,"palau_cantares, fernan_caballero","","",4,0,0,[],"",""],["lafuente_madrid-p0028-02",15,"El primer dia de mayo,\nEn punto de medio dia,\nÁ visitar los sembrados\nSalen Jesus y María.",210,0,-1,191,"",0,4,"ia",0,0,-1,0,28,28,"","",0,"fernan_caballero","","",3,0,0,[],"",""],["lafuente_madrid-p0028-03",15,"Se paran de trecho en trecho,\nLes echan su bendicion,\nMandan que corran los vientos\nPara dar la granazon.",210,0,-1,191,"",5,4,"ao",-1,0,-1,0,28,28,"","",0,"palau_cantares, fernan_caballero","","",3,0,0,[],"",""],["lafuente_madrid-p0028-04",15,"En llegando el mes de junio\nMe da mi Dios la licencia,\nPara que pueda segar\nDe los campos la cosecha.",210,0,-1,191,"",0,4,"ea",-1,0,-1,0,28,28,"","",0,"palau_cantares, fernan_caballero","","",3,0,0,[],"",""],["lafuente_madrid-p0028-05",15,"Por la voluntad divina,\nLa que á todos nos mantiene,\nY la ayuda de los hombres,\nSon recogidas las mieses.",210,0,-1,191,"",0,4,"ee",-1,0,-1,0,28,28,"","",0,"palau_cantares, fernan_caballero","","",3,0,0,[],"",""],["lafuente_madrid-p0028-06",15,"Ya no quiero más fandango\nPara mi condenacion,\nPor la mañana, mi misa,\nPor la tarde, mi sermon.",210,0,-1,191,"",0,4,"o",31,0,-1,0,28,28,"","",0,"rm_t4","","",2,0,0,[],"",""],["lafuente_madrid-p0028-07",15,"Si te vas á confesar,\nNo dejes ningun pecado,\nQue harás mala confesion,\nY morirás condenado.",210,0,-1,191,"",0,4,"ao",14,0,-1,0,28,28,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0029-01",15,"No adelantes el discurso\nSino para pensar bien,\nPorque á veces discurrimos\nLo que no ha sido, ni es.",210,0,-1,192,"",0,4,"e",-1,0,-1,0,29,29,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0029-02",15,"¡Has dejado que tu padre\nAnde pidiendo limosna!\nEsa mancha no se quita\nNi con agua de Colonia.",210,0,-1,192,"",0,4,"oa",-1,0,-1,0,29,29,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0029-03",15,"Tú merecias que Dios,\nPor su providencia justa,\nNo te dejara llegar\nÁ la edad de que te burlas.",210,0,-1,192,"",0,4,"ua",-1,0,-1,0,29,29,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0029-04",15,"Nunca pidas, nunca debas,\nNunca á nadie le hagas mal,\nSiempre mira, siempre calla\nY las gracias me darás.",210,0,-1,192,"",0,4,"a",-1,0,-1,0,29,29,"","",0,"rm_t4, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0029-05",15,"Nadie murmure de nadie,\nQue somos de carne humana,\nY no hay pellejo de aceite\nQue no tenga su botana.",210,0,-1,192,"",0,4,"aa",4,0,-1,0,29,29,"","",0,"rm_t4, palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0029-06",15,"Nunca acostumbres tu cuerpo\nÁ lo que no es menester,\nPorque es una enfermedad\nCada vicio que le des.",210,0,-1,192,"",0,4,"e",-1,0,-1,0,29,30,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0030-01",15,"Con los de malas costumbres\nNunca trato has de tener,\nQue un hombre malo y vicioso\nÁ ciento suele perder.",210,0,-1,192,"",0,4,"e",20,0,-1,0,30,30,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0030-02",15,"Hablas muy mal de lo bueno,\nY Dios te ha de castigar;\nCuando hablas mal de lo bueno,\nDe lo malo ¿qué será?",210,0,-1,192,"",0,4,"a",-1,0,-1,0,30,30,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0030-03",15,"Más mata una mala lengua\nQue las manos del verdugo;\nEl verdugo mata á un hombre,\nY una mala lengua á muchos.",210,0,-1,192,"",0,4,"uo",-1,0,-1,0,30,30,"","",0,"rm_t4, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0030-04",15,"Á tí te lo digo, espada;\nEntiéndelo tú, rodela;\nEl hombre que ha de ser hombre\nNo ha de ser largo de lengua.",210,0,-1,192,"",0,4,"ea",-1,0,-1,0,30,30,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0030-05",15,"Más vale saber que haber,\nDice la comun sentencia;\nQue el pobre puede ser rico,\nY el rico no compra ciencia.",210,0,-1,192,"",0,4,"ea",46,0,-1,0,30,30,"","",0,"rm_t4, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0031-01",15,"Fortuna te dé Dios, hijo,\nQue el saber poco te basta.\n¿De qué te sirve el saber,\nSi la fortuna te falta?",210,0,-1,192,"",0,4,"aa",-1,0,-1,0,31,31,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0031-02",15,"Logra el tonto por influjo\nLo que al sabio no le dan,\nQue el premio y las buenas mozas\nSiempre se destinan mal.",210,0,-1,192,"",0,4,"a",-1,0,-1,0,31,31,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0031-03",15,"La conversacion del necio\nEs el martirio del sabio;\nMas como el número es corto,\nPocos hay martirizados.",210,0,-1,192,"",0,4,"ao",-1,0,-1,0,31,31,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0031-04",15,"Con saber y no tener\nNo prevalece ninguno;\nQue lo que le sobra al sabio\nSon muchos dias de ayuno.",210,0,-1,192,"",0,4,"uo",230,0,-1,0,31,31,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0031-05",15,"El tiempo y el desengaño\nSon dos amigos leales,\nQue despiertan al que duerme,\nY enseñan al que no sabe.",210,0,-1,192,"",0,4,"ae",-1,0,-1,0,31,31,"","",0,"rm_t4, palau_cantares, leonesas_diez, huambachano","","",10,0,0,[],"",""],["lafuente_madrid-p0031-06",15,"Grande tontería es\nPonerle calas á un muerto,\nMachacar en hierro frio,\nY predicar en desierto.",210,0,-1,192,"",0,4,"eo",88,0,-1,0,31,31,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0031-07",15,"Quien mal masca, mal digiere;\nQuien mal habla, mal persuade;\nQuien mal tose, mal escupe;\nQuien mal concibe, mal pare.",210,0,-1,192,"",0,4,"ae",-1,0,-1,0,31,31,"","",0,"rm_t4, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0032-01",15,"Sufre, si quieres gozar;\nBaja, si quieres subir;\nPierde, si quieres ganar;\nMuere, si quieres vivir.",210,0,-1,192,"",1,4,"i",157,0,-1,0,32,32,"","",0,"rm_t4, palau_cantares, fernan_caballero","","",3,0,0,[],"",""],["lafuente_madrid-p0032-02",15,"Todo lo vence el amor,\nTodo lo alcanza el dinero,\nTodo acaba con la muerte,\nTodo lo consume el tiempo.",210,0,-1,192,"",0,4,"eo",-1,0,-1,0,32,32,"","",0,"rm_t4, palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0032-03",15,"Las cuatro más necesarias\nUrgencias del hombre son,\nÁ mi corto parecer:\nHambre, sueño, sed y amor.",210,0,-1,192,"",0,4,"o",-1,0,-1,0,32,32,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0032-04",15,"Ninguno cante victoria,\nAunque en el estribo esté,\nQue muchos en el estribo\nSe suelen quedar á pié.",210,0,-1,192,"",0,4,"e",77,0,-1,0,32,32,"","",0,"rm_t4, palau_cantares, fernan_caballero","","",7,0,0,[],"",""],["lafuente_madrid-p0032-05",15,"Muchos hay que se figuran\nTener la sarten del mango,\nY cuanto más se aseguran.\nLlevan mejor sartenazo.",210,0,-1,192,"",0,4,"ao",-1,0,-1,0,32,32,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0032-06",15,"Aquel que empieza una obra\nRazon será que la acabe,\nPara que nunca se diga\nQue la dejó por cobarde.",210,0,-1,192,"",0,4,"ae",-1,0,-1,0,32,32,"","",0,"rm_t4, palau_cantares, fernan_caballero","","",4,0,0,[],"",""],["lafuente_madrid-p0033-01",15,"Aquel que más alto sube,\nMás grande porrazo da.\n¡Mira la puente de Arcos\nEn lo que vino á parar!.",210,0,-1,192,"",0,4,"a",-1,0,-1,0,33,33,"","",0,"rm_t4, palau_cantares, fernan_caballero","","",6,0,0,[],"",""],["lafuente_madrid-p0033-02",15,"Nadie diga en este mundo:\nDe este agua no beberé;\nPor muy turbia que la vea,\nLe puede apretar la sed.",210,0,-1,192,"",0,4,"e",-1,0,-1,0,33,33,"","",0,"fernan_caballero","","",4,0,0,[],"",""],["lafuente_madrid-p0033-03",15,"El que presume de honra\nEs porque carece de ella;\nAquel que no tiene capa\nSe acuerda de Grazalema",210,0,-1,192,"",0,4,"ea",-1,0,-1,0,33,33,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0033-04",15,"Males que el tiempo acarrea,\n¡Quién pudiera penetrarlos,\nPara poner el remedio\nAntes que llegara el daño!",210,0,-1,192,"",0,4,"ao",-1,0,-1,0,33,33,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0034-01",15,"El hombre que nunca ha visto,\nY no sabe lo que es ver,\nNunca tiene tanta pena\nComo el que ha visto y no ve",210,0,-1,192,"",0,4,"e",-1,0,-1,0,34,34,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0034-02",15,"Compañerito del alma,\n¿Sabe usted lo que yo digo?\nQue el que no sabe leer,\n¿Para qué quiere los libros?",210,0,-1,192,"",0,4,"io",-1,0,-1,0,34,34,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0034-03",15,"Aquel que nunca fué cosa,\nY que cosa llega á ser,\nQuiere ser tan grande cosa,\nQue no hay cosa como él.",210,0,-1,192,"",0,4,"e",-1,0,-1,0,34,34,"","",0,"rm_t4, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0034-04",15,"Deja correr el caballo,\nNo le tires de la rienda,\nQue puede ser que algun dia\nQuieras correrlo, y no puedas.",210,0,-1,192,"",0,4,"ea",-1,0,-1,0,34,34,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0034-05",15,"Ya mi caballo no anda,\nYa mi caballo paró;\nTodo pára en este mundo,\nY tambien pararé yo.",210,0,-1,192,"",0,4,"o",2,0,-1,0,34,34,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0034-06",15,"Las tertulias, que eran antes.\nPasatiempo regular,\nSon hoy alcahuetería,\nY ocasion de murmurar.",210,0,-1,192,"",0,4,"a",21,0,-1,0,34,34,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0035-01",15,"Un pretendiente en la corte,\nY en Valencia un estudiante,\nY un cómico en la cuaresma,\nSon las tres necesidades.",210,0,-1,192,"",0,4,"ae",-1,0,-1,0,35,35,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0035-02",15,"Un estudiante sin capa,\nUn cómico sin funciones,\nUna muchacha sin novio,\nTodas son cavilaciones.",210,0,-1,192,"",0,4,"oe",34,0,-1,0,35,35,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0035-03",15,"Un loquito del hospicio\nMe dijo en cierta ocasion:\nNi son todos los que están,\nNi están todos los que son.",210,0,-1,192,"",0,4,"o",31,0,-1,0,35,35,"","",0,"rm_t4, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0035-04",15,"De las potencias del alma,\nLa memoria es la cruel,\nPues me causa el mayor mal,\nRecordando el mayor bien.",210,0,-1,192,"",0,4,"e",-1,0,-1,0,35,35,"","",0,"","","",5,0,0,[],"",""],["lafuente_madrid-p0035-05",15,"El feliz y el desdichado\nSuspiran con diferencia;\nUno publica sus glorias,\nY otro publica sus penas.",210,0,-1,192,"",0,4,"ea",-1,0,-1,0,35,35,"","",0,"rm_t4, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0035-06",15,"Nunca compres mula coja\nPensando que sanará;\nPues si las sanas cojean,\nLas cojas ¿qué es lo que harán?",210,0,-1,192,"",0,4,"a",-1,0,-1,0,35,35,"","",0,"rm_t4, palau_cantares, fernan_caballero","","",4,0,0,[],"",""],["lafuente_madrid-p0035-07",15,"No te fies de consejos,\nAunque te los quieran dar;\nGuíate de lo que salga\nDe tu propio natural.",210,0,-1,192,"",0,4,"a",-1,0,-1,0,35,35,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0036-01",15,"Ninguno por cantar bien\nHable mal de aquel que canta;\nUnos cantan lo que saben,\nY otros saben lo que cantan.",210,0,-1,192,"",0,4,"aa",-1,0,-1,0,36,36,"","",0,"rm_t4, palau_cantares, fernan_caballero","","",5,0,0,[],"",""],["lafuente_madrid-p0036-02",15,"Nadie diga: bien estoy;\nPorque yo he solido estar\nEn casa de balconaje,\nY ahora vivo en un solar.",210,0,-1,192,"",3,4,"a",21,0,-1,0,36,36,"","",0,"fernan_caballero, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0036-03",15,"Hasta la leña en el bosque\nTiene su separacion;\nUna sirve para santos,\nY otra para hacer carbon.",210,0,-1,192,"",0,4,"ao",-1,0,-1,0,36,36,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0036-04",15,"Desgraciado el arbolito\nQue solo en el campo nace,\nTodos los aires del mundo\nContra sus ramas combaten.",210,0,-1,192,"",0,4,"ae",-1,0,-1,0,36,36,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0036-05",15,"La libertad y salud\nSon prendas de gran valía,\nNinguno las reconoce\nHasta que las ve perdidas.",210,0,-1,192,"",0,4,"ia",-1,0,-1,0,36,36,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0036-06",15,"Le pueden quitar al Rey\nSu corona y sus estados;\nPero no pueden quitarle\nLa gloria de haber reinado.",210,0,-1,192,"",0,4,"ao",-1,0,-1,0,36,36,"","",0,"rm_t4","","",2,0,0,[],"",""],["lafuente_madrid-p0037-01",15,"Si quieres que viva mucho,\nPídele á Dios que me muera;\nPorque siempre vive mucho\nÁ quien la muerte desean.",210,0,-1,192,"",0,4,"ea",-1,0,-1,0,37,37,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0037-02",15,"En la puerta de un molino\nMe puse á considerar\nLas vueltas que ha dado el mundo,\nY las que tiene que dar.",210,0,-1,192,"",0,4,"a",21,0,-1,0,37,37,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0037-03",15,"Piedra que ha sido rodada\nNo es buena para cimiento,\nQue suele desmoronarse\nCon la frescura del tiempo.",210,0,-1,192,"",0,4,"eo",-1,0,-1,0,37,37,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0037-04",15,"Busca el pobre su acomodo,\nBusca el borracho el cristal,\nEl jugador el tesoro,\nY el ladron donde robar.",210,0,-1,192,"",0,4,"a",-1,0,-1,0,37,37,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0037-05",15,"Toma el huevo de una hora,\nEl pan de aquel mismo dia,\nEl vino que tenga un año,\nY algo menos la gallina.",210,0,-1,192,"",0,4,"ia",-1,0,-1,0,37,37,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0037-06",15,"Estamos en un mundillo\nTan lleno de indignidad,\nQue no tenemos más honra\nQue la que nos quieren dar.",210,0,-1,192,"",0,4,"a",-1,0,-1,0,37,37,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0037-07",15,"Molino que estás moliendo\nEl trigo con tanto afan,\n¡Tú estás haciendo la harina,\nY otros se comen el pan!:",210,0,-1,192,"",0,4,"a",147,0,-1,0,37,37,"","",0,"rm_t4, carrizo_salta, palau_cantares, andina_t2","","",5,0,0,[],"",""],["lafuente_madrid-p0038-01",15,"Aquel que se pasa al moro\nPor su propia voluntad,\nY no procura rescate,\nEs que quiso renegar.",210,0,-1,192,"",0,4,"a",-1,0,-1,0,38,38,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0038-02",15,"¡Ay! desgraciado de aquel\nQue pone su cara en tierra,\nQue el que queda por acá\nTarde ó temprano se alegra!",210,0,-1,192,"",0,4,"ea",-1,0,-1,0,38,38,"","",0,"rm_t4, palau_cantares, fernan_caballero","","",4,0,0,[],"",""],["lafuente_madrid-p0038-03",15,"Nadie descubra su pecho\nPor dar alivio á su pena,\nQue el que su pecho descubre\nPor su boca se condena.",210,0,-1,192,"",0,4,"ea",59,0,-1,0,38,38,"","",0,"rm_t4, palau_cantares, machado_venezuela, andina_t2","","",5,0,0,[],"",""],["lafuente_madrid-p0038-04",15,"El secreto de tu pecho\nNo se lo digas á nadie;\nMejor te lo guardará\nAquel que no te lo sabe.",210,0,-1,192,"",0,4,"ae",-1,0,-1,0,38,38,"","",0,"rm_t4, palau_cantares","","",7,0,0,[],"",""],["lafuente_madrid-p0038-05",15,"Amiga, la más amiga,\nLa más amiga la pega;\nNo hay más amigo que Dios,\nY un duro en la faltriquera.",210,0,-1,192,"",0,4,"ea",-1,0,-1,0,38,38,"","",0,"palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0039-01",15,"No hay más amigo que Dios,\nComo es claro y evidente;\nEl más amigo es traidor,\nY el más verdadero miente.",210,0,-1,192,"",0,4,"ee",15,0,-1,0,39,39,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0039-02",15,"Á mi amigo lo llevé\nÁ casa de la que amaba,\nY luego á los pocos dias\nMi amigo á mi me llevaba.",210,0,-1,192,"",0,4,"aa",28,0,-1,0,39,39,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0039-03",15,"Mis amigos me desprecian\nPorque me ven abatido;\n¡Todo el mundo corta leña\nDel árbol que está caido!",210,0,-1,192,"",0,4,"io",101,0,-1,0,39,39,"","",0,"rm_t4, palau_cantares, preciso_coleccion","","",6,0,0,[],"",""],["lafuente_madrid-p0039-04",15,"A las yerbitas del campo\nLes cuento lo que me pasa,\nPorque no encuentro en el mundo\nPersona de confianza.",210,0,-1,192,"",0,4,"aa",-1,0,-1,0,39,39,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0039-05",15,"Si porque me ves caido,\nMe señalas con el dedo,\nNo atiendas á lo que soy,\nSino á lo que fuí primero.",210,0,-1,192,"",0,4,"eo",-1,0,-1,0,39,39,"","",0,"rm_t4, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0039-06",15,"No hay quien levante al caido,\nNi quien la mano le dé,\nQue como lo ven caido,\nTodos le dan con el pié.",210,0,-1,192,"",1,4,"e",77,0,-1,0,39,39,"","",0,"rm_t4, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0040-01",15,"Á mi corazon lo eché\nÁ pedir por esas calles,\nY como lo ven tan pobre,\nLimosna no le da nadie.",210,0,-1,192,"",0,4,"ae",-1,0,-1,0,40,40,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0040-02",15,"Cuando camina un feliz,\nSe adorna con aparato\nToda la tierra de flores,\nY todo el cielo de raso.",210,0,-1,192,"",0,4,"ao",-1,0,-1,0,40,40,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0040-03",15,"En el cielo manda Dios,\nLos diablos en el infierno,\nY en este pícaro mundo\nEl que manda es el dinero.",210,0,-1,192,"",0,4,"eo",-1,0,-1,0,40,40,"","",0,"rm_t4, palau_cantares, machado_venezuela","","",8,0,0,[],"",""],["lafuente_madrid-p0040-04",15,"Cuando tenia dinero,\nMe llamaban Don Tomás;\nAhora que no lo tengo,\nMe llaman Tomás no más.",210,0,-1,192,"",0,4,"a",51,0,-1,0,40,40,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0040-05",15,"¡Mal haya sea el dinero,\nEn apartando las cruces,\nQue el que no tiene dinero\nEn ninguna parte luce!",210,0,-1,192,"",0,4,"ue",-1,0,-1,0,40,40,"","",0,"rm_t4","","",3,0,0,[],"",""],["lafuente_madrid-p0040-06",15,"Hombre pobre huele á muerto,\nÁ la hoyanca con él;\nQue el que no tiene pesetas\nRequiescat in pace amen.",210,0,-1,192,"",0,4,"e",-1,0,-1,0,40,40,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0041-01",15,"El que no tiene parné,\nCon el viento es comparado;\nQue nadie se arrima á él,\nNo le pegue un resfriado.",210,0,-1,192,"",0,4,"ao",14,0,-1,0,41,41,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0041-02",15,"Hombre pobre, ¿quién te ha muerto?\n-La propia necesidad;\nQue es capaz un hombre pobre\nDe apestar una ciudad.",210,0,-1,192,"",0,4,"a",16,0,-1,0,41,41,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0041-03",15,"Todo lo puede el dinero,\nPorque es mucho su poder;\nNingun hombre jornalero\nPuede guardar la mujer.",210,0,-1,192,"",1,4,"e",20,0,-1,0,41,41,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0041-04",15,"Ya no puede un hombre pobre\nTener la mujer bonita,\nQue como le falta el cobre,\nViene el rico y se la quita.",210,0,-1,192,"",1,4,"ia",50,0,-1,0,41,41,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0041-05",15,"Tanto valor tiene el pobre,\nComo el que tiene caudal;\n¡Á cuántos ricos se han visto\nDe puerta en puerta llegar!",210,0,-1,192,"",0,4,"a",-1,0,-1,0,41,41,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0041-06",15,"Cuando se emborracha un pobre,\nTodos dicen: ¡borrachon!\nCuando se emborracha un rico:\n¡Qué alegrito va el señor!.",210,0,-1,192,"",0,4,"o",-1,0,-1,0,41,41,"","",0,"rm_t4, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0042-01",15,"Por grande que sea una viña,\nY mucho fruto que dé,\nEn teniendo muchos amos\nÁ poco podrán caber.",210,0,-1,192,"",0,4,"e",-1,0,-1,0,42,42,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0042-02",15,"Los pleitos y las sangrías\nLo mismo vienen á ser:\nEvítalos cuanto puedas,\nSi no quieres padecer.",210,0,-1,192,"",0,4,"e",20,0,-1,0,42,42,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0042-03",15,"Los años y las mudanzas\nDejan á muchos sugetos,\nÁ unos, calvos de cabeza,\nY á otros, calvos de dinero.",210,0,-1,192,"",0,4,"eo",-1,0,-1,0,42,42,"","",0,"","","",4,0,0,[],"",""],["lafuente_madrid-p0042-04",15,"Considera, considera,\nY siempre considerando,\nLos mayores imposibles\nSe suelen vencer callando.",210,0,-1,192,"",0,4,"ao",33,0,-1,0,42,42,"","",0,"rm_t4, palau_cantares, fernan_caballero","","",5,0,0,[],"",""],["lafuente_madrid-p0042-05",15,"En la isla de Leon\nSe pesca con hilo y caña;\nPor la boca muere el pez,\nCuenta con lo que se habla.",210,0,-1,192,"",0,4,"aa",-1,0,-1,0,42,42,"","",0,"rm_t4, palau_cantares, fernan_caballero","","",4,0,0,[],"",""],["lafuente_madrid-p0042-06",15,"Desgraciada tortolilla,\nQue de todas aguas bebes,\nMira no bebas de alguna\nQue la corriente te lleve.",210,0,-1,192,"",0,4,"ee",-1,0,-1,0,42,42,"","",0,"rm_t4","","",2,0,0,[],"",""],["lafuente_madrid-p0042-07",15,"El castillito más fuerte,\nSi no le ponen puntales,\nSerá fácil que se caiga\nÁ fuerza de temporales.",210,0,-1,192,"",0,4,"ae",26,0,-1,0,42,42,"","",0,"rm_t4","","",2,0,0,[],"",""],["lafuente_madrid-p0043-01",15,"Al empezar el diluvio\nAndaban todos alegres,\nDiciéndose unos á otros:\n¡Qué buen año será este!",210,0,-1,192,"",0,4,"ee",-1,0,-1,0,43,43,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0043-02",15,"Entre mi oficial y yo\nHicimos este retablo:\nSi está bueno, lo hice yo,\nY mi oficial, si está malo.",210,0,-1,192,"",0,4,"ao",-1,0,-1,0,43,43,"","",0,"rm_t4, palau_cantares, fernan_caballero","","",4,0,0,[],"",""],["lafuente_madrid-p0043-03",15,"En la mar hay mil peligros,\nEn la tierra mil tropiezos,\nY en la vida de los hombres\nSe juntan todos los riesgos.",210,0,-1,192,"",0,4,"eo",-1,0,-1,0,43,43,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0044-01",15,"El amor es una cosa...\n¡Dios nos libre, y Dios nos guarde\nQue hace perder los sentidos\nAl que los tiene cabales.",210,0,-1,193,"",0,4,"ae",-1,0,-1,0,44,44,"","",0,"rm_t4, palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0044-02",15,"El amor es un bichito\nQue por los ojos se mete\nY en llegando al corazon,\nDa fatiguillas de muerte.",210,0,-1,193,"",0,4,"ee",-1,0,-1,0,44,44,"","",0,"rm_t4, palau_cantares","","",10,0,0,[],"",""],["lafuente_madrid-p0044-03",15,"El amor es como el niño,\nQue se enoja y tira el pan,\nY en haciéndole cariños,\nCalla, y lo vuelve á tomar.",210,0,-1,193,"",0,4,"a",-1,0,-1,0,44,44,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0044-04",15,"Entra el amor por los ojos,\nSe deposita en el pecho,\nLe alimentan los oidos,\nY le matan los desprecios.",210,0,-1,193,"",0,4,"eo",-1,0,-1,0,44,44,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0044-05",15,"Nace amor como una planta\nEn amante corazon,\nLo alimenta la esperanza,\nDespues lo seca el rigor.",210,0,-1,193,"",0,4,"o",-1,0,-1,0,44,44,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0045-01",15,"Querer por solo querer,\nSin esperanza de premio,\nEs un querer desdichado,\nPero es querer verdadero.",210,0,-1,193,"",0,4,"eo",-1,0,-1,0,45,45,"","",0,"rm_t4, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0045-02",15,"Es de tal modo el amor,\nY son sus efectos tales,\nQue lo declaran los ojos,\nAunque la boca lo calle.",210,0,-1,193,"",0,4,"ae",-1,0,-1,0,45,45,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0045-03",15,"El dinero y los amores\nNo pueden estar cubiertos;\nEl dinero, porque suena;\nLos amores, por inquietos.",210,0,-1,193,"",0,4,"eo",-1,0,-1,0,45,45,"","",0,"rm_t4, palau_cantares, machado_venezuela","","",4,0,0,[],"",""],["lafuente_madrid-p0045-04",15,"Piensan los enamorados,\nPiensan, y no piensan bien,\nPiensan que nadie los mira,\nY todo el mundo los ve.",210,0,-1,193,"",0,4,"e",-1,0,-1,0,45,45,"","",0,"rm_t4, palau_cantares, frenk_t2, andina_t2","","",7,0,0,[],"",""],["lafuente_madrid-p0045-05",15,"Es una gloria el querer,\nCuando es querer deseado,\nY en llegándose á perder,\nEs un infierno abreviado.",210,0,-1,193,"",1,4,"ao",14,0,-1,0,45,45,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0045-06",15,"Entre la tierra y el cielo\nSe oyó una voz por el aire:\nQuien quiera vivir tranquilo\nNo ponga su amor en nadie.",210,0,-1,193,"",0,4,"ae",-1,0,-1,0,45,45,"","",0,"rm_t4, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0045-07",15,"El tiempo con el querer\nHicieron una contrata,\nY lo que el querer dispone,\nEl tiempo lo desbarata.",210,0,-1,193,"",0,4,"aa",74,0,-1,0,45,45,"","",0,"rm_t4, palau_cantares, fernan_caballero","","",4,0,0,[],"",""],["lafuente_madrid-p0046-01",15,"¿Te quieres poner conmigo?\nLe dijo el tiempo al querer,\nEsa soberbia que gastas\nYo te la castigaré.",210,0,-1,193,"",0,4,"e",-1,0,-1,0,46,46,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0046-02",15,"De lo profundo del alma\nSuspiraba una morena,\nY en el suspiro decia:\nQuien tiene amor, tiene penas.",210,0,-1,193,"",0,4,"ea",-1,0,-1,0,46,46,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0046-03",15,"La cadena del amor\nLlévala contigo un año,\nY verás qué peso tiene\nEl que vive enamorado.",210,0,-1,193,"",0,4,"ao",-1,0,-1,0,46,46,"","",0,"rm_t4, palau_cantares","","",8,0,0,[],"",""],["lafuente_madrid-p0046-04",15,"La cadena del amor\nTiene fuertes eslabones,\nY aquel que en ella se mete\nTarde sale de prisiones.",210,0,-1,193,"",0,4,"oe",34,0,-1,0,46,46,"","",0,"fernan_caballero, palau_cantares","","",8,0,0,[],"",""],["lafuente_madrid-p0046-05",15,"Es amor como el pleitista,\nCuando dinero no tiene;\nNi el escribano le escucha,\nNi el abogado le atiende.",210,0,-1,193,"",0,4,"ee",-1,0,-1,0,46,46,"","",0,"rm_t4, palau_cantares, fernan_caballero","","",4,0,0,[],"",""],["lafuente_madrid-p0047-01",15,"El amor ha de ser uno,\nEso bien lo sabeis vos;\nNo tiene amor con ninguno\nLa mujer que quiere á dos.",210,0,-1,193,"",1,4,"o",87,0,-1,0,47,47,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0047-02",15,"Nace la perla en el mar,\nEn los jardines la flor,\nEntre riscos el diamante,\nEntre amantes el amor.",210,0,-1,193,"",0,4,"o",72,0,-1,0,47,47,"","",0,"palau_cantares, frenk_t2","","",3,0,0,[],"",""],["lafuente_madrid-p0047-03",15,"Las fatigas de la muerte,\nGrandes fatiguillas son;\nPero con las del querer\nNo tienen comparacion.",210,0,-1,193,"",0,4,"o",31,0,-1,0,47,47,"","",0,"rm_t4, palau_cantares, fernan_caballero","","",4,0,0,[],"",""],["lafuente_madrid-p0047-04",15,"No hay amor como el primero,\nY los demás son fingidos;\nEl primer amor que tuve\nSe llevó el corazon mio.",210,0,-1,193,"",0,4,"io",-1,0,-1,0,47,47,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0047-05",15,"No hay amante sin amante,\nNo hay amor sin pena fuerte,\nNo hay firmeza sin amor,\nNi vida sin tener muerte.",210,0,-1,193,"",0,4,"ee",134,0,-1,0,47,47,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0047-06",15,"Dícese que nos queremos;\nYo no sé si desearlo:\nLa risa de amor es dulce,\nPero su llanto es amargo.",210,0,-1,193,"",0,4,"ao",-1,0,-1,0,47,47,"","",0,"palau_cantares, fernan_caballero","","",3,0,0,[],"",""],["lafuente_madrid-p0047-07",15,"Al amor lo pintan niño,\nY á la firmeza mujer;\nEntre una mujer y un niño,\n¿Qué amor firme puede haber?",210,0,-1,193,"",1,4,"e",20,0,-1,0,47,47,"","",0,"rm_t4, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0048-01",15,"Pedernal que no echa lumbre,\nY cuchillo que no corta,\nY el amor que no es constante,\nQue se pierdan poco importa.",210,0,-1,193,"",0,4,"oa",265,0,-1,0,48,48,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0048-02",15,"El árbol del querer bien\nNo tiene más que una rama,\nY para subir á él\nEs menester que otro caiga.",210,0,-1,193,"",0,4,"aa",-1,0,-1,0,48,48,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0048-03",15,"Amor con amor se paga,\nY con otra cosa no;\nLó que no tuviere cuenta,\nOlvidarlo es lo mejor.",210,0,-1,193,"",0,4,"o",-1,0,-1,0,48,48,"","",0,"palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0048-04",15,"Pasan las dichas del mundo,\nPasa la vida y el tiempo;\nLo que no pasa jamás\nEs el amor verdadero.",210,0,-1,193,"",0,4,"eo",-1,0,-1,0,48,48,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0048-05",15,"Amores de largo tiempo\n¡Qué malos de olvidar son,\nPorque han echado raices\nEn medio del corazon!",210,0,-1,193,"",0,4,"o",31,0,-1,0,48,48,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0049-01",15,"Quien ama correspondido\nNo deje de recelarse,\nQue son los dias de gusto\nVísperas de los pesares.",210,0,-1,193,"",0,4,"ae",-1,0,-1,0,49,49,"","",0,"rm_t4, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0049-02",15,"Amor, no pongas amor\nDonde no hay correspondencia,\nMira que te quedarás\nÁ la luna de Valencia.",210,0,-1,193,"",0,4,"ea",46,0,-1,0,49,49,"","",0,"rm_t4, palau_cantares, fernan_caballero","","",4,0,0,[],"",""],["lafuente_madrid-p0049-03",15,"¿Cuál será el dolor más fuerte,\nÓ la pena más sensible,\nEl batallar con la muerte,\nÓ el querer un imposible?",210,0,-1,193,"",1,4,"ie",259,0,-1,0,49,49,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0049-04",15,"En contiendas amorosas\nAconseja cierto autor\nHerrar, ó quitar el banco;\nY yo sigo su opinion.",210,0,-1,193,"",0,4,"o",-1,0,-1,0,49,49,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0049-05",15,"Quien diga que ha enamorado\nSin sufrir, ni padecer,\nÓ siempre ha sido muy necio,\nÓ nunca ha querido bien.",210,0,-1,193,"",0,4,"e",-1,0,-1,0,49,49,"","",0,"rm_t4, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0049-06",15,"Quien diga que los amantes\nEstán divertidos siempre,\nNo debió de tener celos,\nNi estuvo jamás ausente.",210,0,-1,193,"",0,4,"ee",-1,0,-1,0,49,49,"","",0,"rm_t4","","",3,0,0,[],"",""],["lafuente_madrid-p0049-07",15,"Dicen algunos autores\nQue la ausencia causa olvido;\nEso lo dirán los necios\nQue amores no hayan tenido.",210,0,-1,193,"",0,4,"io",101,0,-1,0,49,49,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0050-01",15,"Una pena quita pena,\nUn dolor quita dolor,\nUn clavo saca otro clavo,\nPero amor no quita amor.",210,0,-1,193,"",0,4,"o",72,0,-1,0,50,50,"","",0,"rm_t4, palau_cantares, preciso_coleccion","","",4,0,0,[],"",""],["lafuente_madrid-p0050-02",15,"No ama mucho quien lo dice,\nSino quien mucho padece,\nPorque amor sin penas y obras\nDe amor solo el nombre tiene.",210,0,-1,193,"",0,4,"ee",-1,0,-1,0,50,50,"","",0,"palau_cantares, fernan_caballero","","",4,0,0,[],"",""],["lafuente_madrid-p0050-03",15,"Desde aquel primer instante\nQue abre el corazon sus puertas,\nAunque las burle un amante,\nLas suele tener abiertas.",210,0,-1,193,"",1,4,"ea",251,0,-1,0,50,50,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0050-04",15,"Alza la voz, pregonero,\nY en el primer renglon di:\nNo hay plazo que no se cumpla,\nNi amor que no tenga fin.",210,0,-1,193,"",0,4,"i",-1,0,-1,0,50,50,"","",0,"rm_t4, palau_cantares","","",9,0,0,[],"",""],["lafuente_madrid-p0050-05",15,"Aquel si viene ó no viene,\nAquel si sale ó no sale,\nEn los amores no tiene\nContento que se le iguale.",210,0,-1,193,"",1,4,"ae",202,0,-1,0,50,50,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0050-06",15,"Amantes que siempre riñen,\nY que jamás escarmientan,\nEn llegando á conformarse,\n¡Dios nos la depare buena!",210,0,-1,193,"",0,4,"ea",-1,0,-1,0,50,50,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0051-01",15,"Cuando dos se quieren bien,\nCon los ojos se saludan;\nQue tambien los ojos hablan\nCuando la lengua está muda.",210,0,-1,193,"",0,4,"ua",-1,0,-1,0,51,51,"","",0,"rm_t4, palau_cantares, huambachano","","",9,0,0,[],"",""],["lafuente_madrid-p0051-02",15,"A toda mujer que vieres\nAmarilla y con ojeras,\nNo le preguntes qué tiene,\nPorque es que quiere de veras.",210,0,-1,193,"",0,4,"ea",103,0,-1,0,51,51,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0051-03",15,"Á aquel que quiere de veras,\nUn tiro le habian de dar;\nNi come, ni bebe á gusto,\nNi lo dejan sosegar.",210,0,-1,193,"",0,4,"a",21,0,-1,0,51,51,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0051-04",15,"Una vela se consume\nÁ fuerza de mucho arder;\nAsí se consume un hombre\nAl lado de una mujer.",210,0,-1,193,"",0,4,"e",20,0,-1,0,51,51,"","",0,"rm_t4, palau_cantares, fernan_caballero","","",7,0,0,[],"",""],["lafuente_madrid-p0051-05",15,"Esperar y no venir,\nQuerer y que no lo quieran,\nAcostarse y no dormir,\n¿Cuál será la mayor pena?",210,0,-1,193,"",0,4,"ea",-1,0,-1,0,51,51,"","",0,"rm_t4, palau_cantares, fernan_caballero","","",4,0,0,[],"",""],["lafuente_madrid-p0051-06",15,"Á la luz de la razon\nHe venido á conocer\nQue son fatigas de muerte\nEl querer y no poder.",210,0,-1,193,"",0,4,"e",20,0,-1,0,51,51,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0052-01",15,"La fundacion del querer\nNo tiene comparacion;\nQue le parece al que ama\nQue lo suyo es lo mejor.",210,0,-1,193,"",0,4,"o",-1,0,-1,0,52,52,"","",0,"rm_t4","","",6,0,0,[],"",""],["lafuente_madrid-p0052-02",15,"La mañana de San Juan\nCuaja la almendra y la nuez;\nAsí cuajan los amores\nCuando dos se quieren bien.",210,0,-1,193,"",0,4,"e",-1,0,-1,0,52,52,"","",0,"fernan_caballero","","",3,0,0,[],"",""],["lafuente_madrid-p0052-03",15,"Mañanita de San Juan,\nMadruga, niña, temprano,\nPara darle el corazon\nAl galan que puso el ramo.",210,0,-1,193,"",0,4,"ao",-1,0,-1,0,52,52,"","",0,"rm_t4","","",4,0,0,[],"",""],["lafuente_madrid-p0052-04",15,"Porfía, y conseguirás\nDel amor lo que quisieres;\nNo son duros pedernales\nLos pechos de las mujeres.",210,0,-1,193,"",0,4,"ee",55,0,-1,0,52,52,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0052-05",15,"Se levanta el rey furioso,\nToma la pluma y escribe,\nY en el primer renglon pone:\nQuien tiene amores, no vive.",210,0,-1,193,"",0,4,"ie",190,0,-1,0,52,52,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0052-06",15,"Dejad llorar á las nubes,\nDejad alumbrar al sol,\nDejad al viejo quejarse,\nY al mozo gozar su amor,",210,0,-1,193,"",0,4,"o",-1,0,-1,0,52,52,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0053-01",15,"El más sabio se atribula,\nQuien tiene razon, la pierde,\nPrevarica del sentido\nAquel que quiere y no puede.",210,0,-1,193,"",0,4,"ee",-1,0,-1,0,53,53,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0053-02",15,"De los sabios de este mundo\nÁ aquel que supiere más,\nSi lo metes en querer,\nLo verás prevaricar.",210,0,-1,193,"",0,4,"a",-1,0,-1,0,53,53,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0053-03",15,"Es tanto lo que apasiona\nUna muchacha bonita,\nQue al hombre de más valor\nEl corazon le palpita.",210,0,-1,193,"",0,4,"ia",50,0,-1,0,53,53,"","",0,"rm_t4, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0053-04",15,"Nadie se ponga á querer,\nQue el querer quita el sentido;\nLo digo por experiencia,\nPorque á mí me ha sucedido.",210,0,-1,193,"",0,4,"io",101,0,-1,0,53,53,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0053-05",15,"El pimiento ha de ser verde,\nY el tomate colorado,\nLa berengena espinosa,\nY los amores callados.",210,0,-1,193,"",0,4,"ao",-1,0,-1,0,53,53,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0054-01",15,"Yo le he preguntado á un sabio\nCómo se olvida un amor;\nY el sabio me ha contestado:\n¡Ay, si lo supiera yo!.",210,0,-1,193,"",0,4,"o",-1,0,-1,0,54,54,"","",0,"rm_t4","","",5,0,0,[],"",""],["lafuente_madrid-p0054-02",15,"Todas las mañanas voy\nÁ preguntarle al romero\nSi el mal de amor tiene cura\nPorque yo de amores muero.",210,0,-1,193,"",0,4,"eo",38,0,-1,0,54,54,"","",0,"palau_cantares","","",12,0,0,[],"",""],["lafuente_madrid-p0054-03",15,"El mal de amor tiene cura\nEn sabiéndolo curar,\nEn queriendo ó no queriendo\nOlvidar ó no olvidar.",210,0,-1,193,"",0,4,"a",21,0,-1,0,54,54,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0054-04",15,"Al hombre que se enamora\nY tiene poca prudencia,\nLe vienen luego á dejar\nÁ la luna de Valencia.",210,0,-1,193,"",0,4,"ea",46,0,-1,0,54,54,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0054-05",15,"Por más que reine el cariño;\nEn llegándose á perder,\nNo es fácil que se recobre;\nSi Dios no pone el poder.",210,0,-1,193,"",0,4,"e",20,0,-1,0,54,54,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0054-06",15,"Para el dolor de un ausente\nNo hay alivio, ni consuelo,\nPorque tiene cerca el daño,\nY distantes los remedios.",210,0,-1,193,"",0,4,"eo",-1,0,-1,0,54,54,"","",0,"rm_t4, preciso_coleccion","","",4,0,0,[],"",""],["lafuente_madrid-p0055-01",15,"Cuando dos quieren á una,\nY los dos están presentes,\nEl uno cierra los ojos,\nY el otro aprieta los dientes.",210,0,-1,193,"",0,4,"ee",252,0,-1,0,55,55,"","",0,"rm_t4, palau_cantares, frenk_t2","","",8,0,0,[],"",""],["lafuente_madrid-p0055-02",15,"Cuando uno quiere á una,\nY esta una no lo quiere,\nEs lo mismo que si un calvo\nSe encuentra en la calle un peine.",210,0,-1,193,"",0,4,"ee",-1,0,-1,0,55,55,"","",0,"rm_t4","","",5,0,0,[],"",""],["lafuente_madrid-p0055-03",15,"Cuando en la calle se encuentran\nPersonas que se han querido,\nÓ se les muda el color,\nÓ se les quita el sentido.",210,0,-1,193,"",0,4,"io",101,0,-1,0,55,55,"","",0,"rm_t4","","",3,0,0,[],"",""],["lafuente_madrid-p0055-04",15,"¿Qué harán dos que amando se hallan\nHeridos de una centella?\nElla de vergüenza calla,\nY él calla de temor de ella.",210,0,-1,193,"",0,4,"ea",6,0,-1,0,55,55,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0055-05",15,"Anoche soñé un ensueño,\nQue yo tengo por verdad;\nEn estando un hombre ausente,\nOtro ocupa su lugar.",210,0,-1,193,"",0,4,"a",-1,0,-1,0,55,55,"","",0,"palau_cantares","","",7,0,0,[],"",""],["lafuente_madrid-p0055-06",15,"El que se retira y vuelve\nNo tiene ningun delito,\nQue el águila se remonta,\nY vuelve á su mismo sitio.",210,0,-1,193,"",0,4,"io",-1,0,-1,0,55,55,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0055-07",15,"El amor que se va y vuelve\nLo tengo yo comparado\nCon los niños de la escuela,\nQue siempre van disgustados.",210,0,-1,193,"",0,4,"ao",-1,0,-1,0,55,55,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0056-01",15,"El amor del forastero\nEs como la golondrina,\nQue así que llega el verano\nÁ su tierra se encamina.",210,0,-1,193,"",0,4,"ia",11,0,-1,0,56,56,"","",0,"rm_t4, fernan_caballero","","",5,0,0,[],"",""],["lafuente_madrid-p0056-02",15,"Mujer, llora y vencerás,\nSi tu amante te desdeña,\nQue hay un adagio que dice:\nLágrimas quebrantan peñas.",210,0,-1,193,"",0,4,"ea",-1,0,-1,0,56,56,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0056-03",15,"Aprovecha el tiempo, niña,\nY no juegues con la suerte,\nQue la vejez viene luego,\nY luego viene la muerte.",210,0,-1,193,"",0,4,"ee",134,0,-1,0,56,56,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0056-04",15,"Todos quieren á la Antonia;\nAntonia no quiere á nadie;\nÁ lo mejor quedará\nComo el pájaro en el aire.",210,0,-1,193,"",0,4,"ae",-1,0,-1,0,56,56,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0056-05",15,"Un rosal cria una rosa,\nUna maceta un clavel,\nUn padre cria una hija,\nY no sabe para quien.",210,0,-1,193,"",0,4,"e",-1,0,-1,0,56,56,"","",0,"","","",8,0,0,[],"",""],["lafuente_madrid-p0056-06",15,"No quiero que me dé nadie\nValía de un alfiler,\nPorque todo en este mundo\nSe da por el interés.",210,0,-1,193,"",0,4,"e",-1,0,-1,0,56,56,"","",0,"rm_t4, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0056-07",15,"Celos son unos recelos\nDe la mente acalorada,\nSi son algo, no son celos,\nSi son celos, no son nada.",210,0,-1,193,"",1,4,"aa",49,0,-1,0,56,56,"","",0,"rm_t4","","",3,0,0,[],"",""],["lafuente_madrid-p0057-01",15,"¡Qué bien dijo aquel que dijo,\nQuejándose de los celos:\nNo hay cosa para el olvido\nQue otro amor, ó tierra en medio!",210,0,-1,193,"",0,4,"eo",-1,0,-1,0,57,57,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0057-02",15,"Al que lo quieren de balde\nNo venga pidiendo celos,\nQue harto favor se le hace\nCon quererlo pelo á pelo.",210,0,-1,193,"",0,4,"eo",-1,0,-1,0,57,57,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0057-03",15,"Una me dijo que sí,\nOtra me dijo que no;\nLa del sí queria ella,\nLa del no queria yo.",210,0,-1,193,"",0,4,"o",2,0,-1,0,57,57,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0057-04",15,"Cuando se ve que van juntos\nUna mujer con un hombre,\nLes han de achacar aquello\nQue cada cual se supone.",210,0,-1,193,"",0,4,"oe",-1,0,-1,0,57,57,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0057-05",15,"Compadre que á su comadre\nNo le dice á donde va,\nNi es compadre, ni es comadre\nNi se tienen voluntad.",210,0,-1,193,"",0,4,"a",-1,0,-1,0,57,57,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0057-06",15,"Una mujer fué la causa\nDe la perdicion primera;\nNo hay perdicion en el mundo\nQue por mujeres no venga.",210,0,-1,193,"",0,4,"ea",-1,0,-1,0,57,57,"","",0,"rm_t4, carrizo_salta, palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0058-01",15,"Ya no hay padre santo en Roma,\nNi en España cristiandad,\nNi en las mujeres firmeza,\nNi en los hombres lealtad.",210,0,-1,193,"",0,4,"a",16,0,-1,0,58,58,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0058-02",15,"Es la mujer en rigor\nComo manjar con veneno,\nQue lo dulce está por fuera,\nY lo amargo está por dentro.",210,0,-1,193,"",0,4,"eo",-1,0,-1,0,58,58,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0058-03",15,"Son los hombres arcas nuevas\nCon su cerraja y su llave;\nPor fuera están muy bonitas,\nY por dentro... ¡Dios lo sabe!",210,0,-1,193,"",0,4,"ae",131,0,-1,0,58,58,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0058-04",15,"Si la mar fuera de tinta,\nY el cielo fuera papel,\nNo se pudiera escribir\nLo falsa que es la mujer.",210,0,-1,193,"",0,4,"e",-1,0,-1,0,58,58,"","",0,"palau_cantares","","",11,0,0,[],"",""],["lafuente_madrid-p0058-05",15,"Si la mar fuera de tinta,\nY el cielo de papel doble,\nNo se pudiera escribir\nLo falsos que son los hombres.",210,0,-1,193,"",0,4,"oe",-1,0,-1,0,58,58,"","",0,"rm_t4, palau_cantares","","",11,0,0,[],"",""],["lafuente_madrid-p0058-06",15,"La mujer que encuentre un hombre\nFino, constante y leal,\nLlévelo por cosa rara\nÁ la Historia natural",210,0,-1,193,"",0,4,"a",1,0,-1,0,58,58,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0059-01",15,"Quien se fie de las hembras,\nY en sus halagos creyere,\nSi no se ahorcase á sí mismo,\nSerá porque ellas lo hicieren.",210,0,-1,193,"",0,4,"ee",-1,0,-1,0,59,59,"","",0,"palau_cantares, preciso_coleccion","","",4,0,0,[],"",""],["lafuente_madrid-p0059-02",15,"No te fies de los hombres,\nAunque lleren á tus plantas,\nQue son como los pepinos,\nQue vienen á temporadas.",210,0,-1,193,"",0,4,"aa",-1,0,-1,0,59,59,"","",0,"","","",16,0,0,[],"",""],["lafuente_madrid-p0059-03",15,"No te fies de los hombres.\nQue tienen poca firmeza,\nY se mudan la camisa\nLo mismo que las culebras.",210,0,-1,193,"",0,4,"ea",-1,0,-1,0,59,59,"","",0,"rm_t4, palau_cantares","","",16,0,0,[],"",""],["lafuente_madrid-p0059-04",15,"No te fies de mujeres\nAunque las veas llorar,\nQue con sus lágrimas riegan\nLas calabazas que dan.",210,0,-1,193,"",0,4,"a",-1,0,-1,0,59,59,"","",0,"rm_t4, carrizo_salta, palau_cantares, fernan_caballero","","",6,0,0,[],"",""],["lafuente_madrid-p0059-05",15,"Á el hombre falso y sin ley\nTrátalo con segundilla (1);\nPor si acaso te echa el rey,\nJuégale tú la malilla.",210,0,-1,193,"",1,4,"ia",162,0,-1,0,59,59,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0060-01",15,"La mujer es una nave\nQue á todo el mundo atropella;\nMuy poco del mundo sabe\nAquel que se embarca en ella.",210,0,-1,193,"",1,4,"ea",6,0,-1,0,60,60,"","",0,"rm_t4","","",2,0,0,[],"",""],["lafuente_madrid-p0060-02",15,"Comparadilla la tengo\nLa mujer con la tormenta;\nDespues que pierden á un hombre,\nLuego le dan la contenta.",210,0,-1,193,"",0,4,"ea",229,0,-1,0,60,60,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0060-03",15,"Como maestra en amores,\nPondré un letrero en mi escuela:\nNadie se fie de hombres,\nPorque á lo mejor la pegan.",210,0,-1,193,"",0,4,"ea",-1,0,-1,0,60,60,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0060-04",15,"Si de mujeres te prendas,\nDarás fin á tu caudal;\nNo hay cosa que valga menos,\nNi cosa que cueste más.",210,0,-1,193,"",0,4,"a",-1,0,-1,0,60,60,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0060-05",15,"Cuando un hombre está queriendo,\nSolicita y galantea;\nY así que logra su intento,\nAborrece, olvida y niega.",210,0,-1,193,"",0,4,"ea",-1,0,-1,0,60,60,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0060-06",15,"Cuando intentan las mujeres\nConquistar algun galan,\nHumildes se manifiestan;\nPero despues... ¡Dios dirá!",210,0,-1,193,"",0,4,"a",-1,0,-1,0,60,60,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0060-07",15,"¡Qué triste que va la luna,\nY el lucero en su compaña!\n¡Qué triste se queda un hombre\nCuando una mujer lo engaña!",210,0,-1,193,"",0,4,"aa",213,0,-1,0,60,60,"","",0,"palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0061-01",15,"Si las mujeres tuvieran\nLa libertad de los hombres,\nÁ los caminos salieran\nÁ robar los corazones.",210,0,-1,193,"",0,4,"oe",-1,0,-1,0,61,61,"","",0,"rm_t4, carrizo_salta, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0061-02",15,"El amor que siente el hombre\nEs como la leña verde,\nQue llena la casa de humo,\nY luego desaparece.",210,0,-1,193,"",0,4,"ee",-1,0,-1,0,61,61,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0061-03",15,"El amor de las mujeres\nEs como dia nublado,\nQue tiene más pareceres\nQue leyes un abogado.",210,0,-1,193,"",1,4,"ao",14,0,-1,0,61,61,"","",0,"palau_cantares","","",18,0,0,[],"",""],["lafuente_madrid-p0061-04",15,"El amor de las mujeres\nSuele ser como el del perro,\nQue aunque le sacudan palos,\nNunca desampara al dueño.",210,0,-1,193,"",0,4,"eo",-1,0,-1,0,61,61,"","",0,"rm_t4, palau_cantares","","",18,0,0,[],"",""],["lafuente_madrid-p0061-05",15,"Á la mujer la comparo\nCon el águila real;\nEn acercándose á ella,\nElla se remonta más.",210,0,-1,193,"",0,4,"a",-1,0,-1,0,61,61,"","",0,"rm_t4, palau_cantares, fernan_caballero","","",5,0,0,[],"",""],["lafuente_madrid-p0061-06",15,"Las mujeres son ladronas,\nQue les quitan á los hombres\nLa luz del entendimiento,\nAunque la razon les sobre.",210,0,-1,193,"",0,4,"oe",-1,0,-1,0,61,61,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0062-01",15,"El que de una dama bella\nQuisiera ser bien querido,\nQue haga poco caso de ella\nQue yo lo tengo advertido.",210,0,-1,193,"",1,4,"io",101,0,-1,0,62,62,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0062-02",15,"Más quisiera en una plaza\nÁ un toro bravo esperar,\nQue no á una mujer que diga:\n¿Qué cuidado se me da?.",210,0,-1,193,"",0,4,"a",-1,0,-1,0,62,62,"","",0,"rm_t4, fernan_caballero, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0062-03",15,"La que quiere ser amada\nSin tener correspondencia,\nQuiere conservar el fuego\nSin la pension de echar leña.",210,0,-1,193,"",0,4,"ea",-1,0,-1,0,62,62,"","",0,"rm_t4, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0062-04",15,"La niña que tiene uno,\nY pretende tener das,\nSe quedará sin ninguno,\nQue así lo dispone Dios.",210,0,-1,193,"",5,4,"o",-1,0,-1,0,62,62,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0062-05",15,"La dama que quiere á dos\nNo es tonta, que es entendida\nSi una vela se le apaga,\nOtra le queda encendida,",210,0,-1,193,"",0,4,"ia",37,0,-1,0,62,62,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0062-06",15,"La mujer que se enamora\nDe la ropa y no del hombre,\nNo tiene vergüenza en cara,\nPorque la ropa se rompe.",210,0,-1,193,"",0,4,"oe",-1,0,-1,0,62,62,"","",0,"rm_t4, fernan_caballero, palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0063-01",15,"Ámujer que sale mala,\nNo reñirle, ni pegarle;\nLa cabra que tira al monte,\nNo hay cabrero que la guarde.",210,0,-1,193,"",0,4,"ae",-1,0,-1,0,63,63,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0063-02",15,"Dice el sabio Salomon\nQue el que engaña á una doncella,\nNo tiene perdon de Dios,\nSi no se casa con ella ().",210,0,-1,193,"",0,4,"ea",6,0,-1,0,63,63,"","",0,"rm_t4, palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0063-03",15,"La mujer que á un hombre adora\nPor su gusto solamente,\nLos intereses desprecia,\nAunque ricos la cortejen.",210,0,-1,193,"",0,4,"ee",-1,0,-1,0,63,63,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0063-04",15,"En tu vida te enamores\nDe mozo que no ha rondado,\nQue el que no ronda de mozo,\nRonda despues de casado.",210,0,-1,193,"",0,4,"ao",14,0,-1,0,63,63,"","",0,"rm_t4, palau_cantares","","",7,0,0,[],"",""],["lafuente_madrid-p0063-05",15,"En ningun hombre casado\nPongas nunca tu querer,\nPorque al fin y á la partida\nSe lo lleva su mujer.",210,0,-1,193,"",0,4,"e",20,0,-1,0,63,63,"","",0,"palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0063-06",15,"Enamoré á una casada,\nY luego-me arrepenti;\nComo olvidó á su marido,\nMe olvidará luego á mi.",210,0,-1,193,"",5,4,"i",-1,0,-1,0,63,63,"","",0,"rm_t4","","",2,0,0,[],"",""],["lafuente_madrid-p0064-01",15,"No quiero amor con casada,\nQue me ha dicho una viuda\nQue á quien de ajeno se viste\nEn la calle lo desnudan.",210,0,-1,193,"",0,4,"ua",-1,0,-1,0,64,64,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0064-02",15,"No quiero más amistades,\nQuiero seguir mi opinion,\nQue de pasion con extremos\nResulta una perdicion.",210,0,-1,193,"",0,4,"io",31,0,-1,0,64,64,"","",0,"preciso_coleccion, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0064-03",15,"Si te se apaga el cigarro,\nNo lo vuelvas á encender;\nSi te despide la novia,\nNo la vuelvas á querer.",210,0,-1,193,"",0,4,"e",20,0,-1,0,64,64,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0064-04",15,"No te enamores, serrana,\nDe niño de poca edad,\nQue como le falta el tiempo,\nLe falta la volumtad.",210,0,-1,193,"",0,4,"a",16,0,-1,0,64,64,"","",0,"","","",5,0,0,[],"",""],["lafuente_madrid-p0064-05",15,"No te enamores, mi niña,\nDe mocito forastero,\nQue en volviendo las espaldas,\nSi te he visto, no me acuerdo.",210,0,-1,193,"",0,4,"eo",-1,0,-1,0,64,64,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0064-06",15,"No elijas mujer ni tela\nÁ la luz artificial,\nPorque la una y la otra\nGrandes chascos suelen dar.",210,0,-1,193,"",0,4,"a",-1,0,-1,0,64,64,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0064-07",15,"No te cases, no te cases,\nEstáte siempre bonita,\nQue las rosas de tu cara\nCon los besos se marchitan.",210,0,-1,193,"",0,4,"ia",-1,0,-1,0,64,64,"","",0,"","","",4,0,0,[],"",""],["lafuente_madrid-p0065-01",15,"No vayas solita al campo\nCuando sople el aire recio,\nPorque las niñas son flores\nQue hasta las deshoja el viento.",210,0,-1,193,"",0,4,"eo",-1,0,-1,0,65,65,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0065-02",15,"No te enamores, mozuela,\nDe pájaro volanton,\nQue anda de olivo en olivo\nBuscando la mejor flor.",210,0,-1,193,"",0,4,"o",-1,0,-1,0,65,65,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0065-03",15,"Si los hombres se calaran,\nComo se cala el melon,\nMás de cuatro muchachitas\nNo vivieran con dolor.",210,0,-1,193,"",0,4,"o",-1,0,-1,0,65,65,"","",0,"rm_t4, palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0065-04",15,"Ninguna, por ser bonita,\nÁ ningun galan desprecie,\nQue un cordon de oro torcido\nDa una vuelta y se destuerce.",210,0,-1,193,"",0,4,"ee",-1,0,-1,0,65,65,"","",0,"rm_t4, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0065-05",15,"Morena tiene que ser\nLa tierra para claveles,\nY la mujer para el hombre,\nMorenita y con desdenes.",210,0,-1,193,"",0,4,"ee",-1,0,-1,0,65,65,"","",0,"rm_t2, fernan_caballero","","",9,0,0,[],"",""],["lafuente_madrid-p0065-06",15,"Morenita debe ser\nLa tierra para ser buena,\nY la mujer para el hombre\nBlanca como la azucena.",210,0,-1,193,"",0,4,"ea",59,0,-1,0,65,65,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0066-01",15,"Compañero, si te casas,\nBusca una mujer morena,\nQue entre las blancas y rubias\nDe ciento sale una buena.",210,0,-1,193,"",0,4,"ea",59,0,-1,0,66,66,"","",0,"palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0066-02",15,"Sino me quieres, me mato\nDicen unos ojos negros;\nY dicen unos azules:\nSi no me quieres, me muero.",210,0,-1,193,"",0,4,"eo",-1,0,-1,0,66,66,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0066-03",15,"No te fies de ojos negros,\nQue ojos negros son traidores,\nUnos ojos negros fueron\nCausa de mis perdiciones.",210,0,-1,193,"",0,4,"oe",-1,0,-1,0,66,66,"","",0,"rm_t4, palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0066-04",15,"Ojos verdes son la mar,\nOjos azules el cielo,\nOjos garzos purgatorio,\nOjos negros el infierno.",210,0,-1,193,"",0,4,"eo",-1,0,-1,0,66,66,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0066-05",15,"Más la quiero pobre y fea\nQue bonita y con dinero,\nLa pobre me mira á mí,\nY la bonita al espejo.",210,0,-1,193,"",0,4,"eo",-1,0,-1,0,66,66,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0066-06",15,"Lástima les tengo yo\nÁ toditas las mujeres,\nCuanto más bonitas son,\nMás mala fortuna tienen.",210,0,-1,193,"",0,4,"ee",-1,0,-1,0,66,66,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0067-01",15,"Aunque me digan la fea,\nNo me tengo de enfadar,\nPorque siempre la más fea\nSe lleva el mejor galan.",210,0,-1,193,"",0,4,"a",-1,0,-1,0,67,67,"","",0,"rm_t4, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0067-02",15,"Todo el hombre que no cao\nÁ los primeros revuelos,\nEn llegando á veinticinco\nNecesita lazo nuevo.",210,0,-1,193,"",0,4,"eo",-1,0,-1,0,67,67,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0067-03",15,"Todo el que quiere casarse (1)\nAjusta la cuenta alegre;\nLuego despues de casado\nLa repasa, y no la entiende.",210,0,-1,193,"",0,4,"ee",-1,0,-1,0,67,67,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0067-04",15,"Perlita, cásate á gusto,\nQue tus padres morirán,\nNo vendran del otro mundo\nÁ ver si lo pasas mal.",210,0,-1,193,"",0,4,"a",-1,0,-1,0,67,67,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0067-05",15,"Cásate, bella madama,\nY te dirán parabienes,\nY luego irás á comer\nÁ tu casa, si la tienes.",210,0,-1,193,"",0,4,"ee",120,0,-1,0,67,67,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0067-06",15,"Cásate, Juan, en domingo,\nLunes estarás casado,\nY el martes preguntarás\nDonde dan el pan fiado.",210,0,-1,193,"",0,4,"ao",14,0,-1,0,67,67,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0067-07",15,"No quieras casa caida,\nNi paredes derrumbadas,\nNi casamiento á disgusto,\nDonde no hay gusto, no hay nada.",210,0,-1,193,"",0,4,"aa",-1,0,-1,0,67,67,"","",0,"palau_cantares, fernan_caballero","","",4,0,0,[],"",""],["lafuente_madrid-p0068-01",15,"Yo le pregunté á un casado:\n-¿Casado, como te va?\nY él me respondió: soltero,\nCásate tú, y lo verás.",210,0,-1,193,"",0,4,"a",-1,0,-1,0,68,68,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0068-03",15,"¿Fuiste tú la que dijiste\nQue no no te casabas nunca?\nNo hay San Martin que no llegue,\nNi plazo que no se cumpla.",210,0,-1,193,"",0,4,"ua",-1,0,-1,0,68,68,"","",0,"","","",5,0,0,[],"",""],["lafuente_madrid-p0068-04",15,"Cásate y tendrás mujer,\nSi es bonita, que guardar,\nSi es fea, que aborrecer,\nSi es rica, que contentar,\nSi es pobre, que mantener",210,0,-1,193,"",7,5,"e",20,0,-1,0,68,68,"","",0,"rm_t4, palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0068-05",15,"Cásate y disfrutarás\nDe los tres meses primeros,\nY luego desearás\nLa vida de los solteros.",210,0,-1,193,"",1,4,"eo",22,0,-1,0,68,68,"","",0,"rm_t4, carrizo_salta","","",3,0,0,[],"",""],["lafuente_madrid-p0068-06",15,"De los mayores trabajos\nQue el hombre puede tener,\nEs tener la mujer fea,\nY no tener que comer.",210,0,-1,193,"",0,4,"e",20,0,-1,0,68,68,"","",0,"rm_t4","","",2,0,0,[],"",""],["lafuente_madrid-p0068-07",15,"Por el sí que dió la niña\nEn la puerta de la iglesia,\nPor el sí que dió la niña,\nEntró libre y salió presa.",210,0,-1,193,"",0,4,"ea",-1,0,-1,0,68,68,"","",0,"rm_t4, fernan_caballero","","",3,0,0,[],"",""],["lafuente_madrid-p0069-01",15,"¡Qué linda moza te has hecho!\n¡Que alta y qué gallardona!\nEl mismo rey coronado\nSe merece tu persona.",210,0,-1,194,"",0,4,"oa",7,0,-1,0,69,69,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0069-02",15,"Eres reina y más que reina,\nY en lo dicho me mantengo,\nDesde la punta del pié\nHasta el último cabello.",210,0,-1,194,"",0,4,"eo",-1,0,-1,0,69,69,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0069-03",15,"Empiezo por los cabellos,\nQue son hebras de oro fino,\nQue adornan en tu cabeza,\nY á mis piés les echan grillos.",210,0,-1,194,"",0,4,"io",-1,0,-1,0,69,69,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0069-05",15,"Bendita sea la madre\nQue te parió y te echó al mundo,\nPara encanto de los hombres,\nCon ese pelito rubio.",210,0,-1,194,"",0,4,"uo",-1,0,-1,0,69,69,"","",0,"rm_t2","","",5,0,0,[],"",""],["lafuente_madrid-p0070-01",15,"Eres rubia como el sol,\nY en tus cabellos hay fuego,\nQue abrasa los corazones,\nAunque parezcan de hielo",210,0,-1,194,"",0,4,"eo",-1,0,-1,0,70,70,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0070-02",15,"Tienes el pelo rubito\nDe perlas claveteado;\nAsí me tienes á mí\nEl corazon traspasado.",210,0,-1,194,"",0,4,"ao",14,0,-1,0,70,70,"","",0,"rm_t2","","",3,0,0,[],"",""],["lafuente_madrid-p0070-03",15,"Con esos rizos hermosos\nQue te cuelgan por la cara\nPareces la Magdalena,\nCuando por el mundo andaba.",210,0,-1,194,"",0,4,"aa",-1,0,-1,0,70,70,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0070-04",15,"Los cabellos de mi rubia\nSe los ha robado al sol;\nÁ mí me ha robado el alma,\nLa vida y el corazon.",210,0,-1,194,"",0,4,"o",-1,0,-1,0,70,70,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0070-05",15,"Esos rizos que te adornan\nEsa peregrina cara,\nSon flechas con que me has hecho\nHerida que nunca sana.",210,0,-1,194,"",0,4,"aa",-1,0,-1,0,70,70,"","",0,"palau_cantares, fernan_caballero","","",3,0,0,[],"",""],["lafuente_madrid-p0070-06",15,"Con ese pelito rubio\nY esa cara tan divina\nEs usté la encantadora\nDe toda la estudiantina.",210,0,-1,194,"",0,4,"ia",11,0,-1,0,70,70,"","",0,"rm_t2","","",4,0,0,[],"",""],["lafuente_madrid-p0071-01",15,"Con esa mata de pelo\nY esa cara de sandunga\nTiene usted muertos más hombres,\nQue tiene Isabel segunda.",210,0,-1,194,"",0,4,"ua",-1,0,-1,0,71,71,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0071-02",15,"Los cabellos de las rubias\nDicen que tienen veneno,\nHe de casarme con una,\nAunque me mate con ellos.",210,0,-1,194,"",0,4,"eo",-1,0,-1,0,71,71,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0071-03",15,"De tu pelito, rubita,\nCorté, rubita, un cabello,\nY hice una cadenita,\nRubita, y me la eché al cuello.",210,0,-1,194,"",1,4,"eo",12,0,-1,0,71,71,"","",0,"rm_t2","","",3,0,0,[],"",""],["lafuente_madrid-p0071-04",15,"Del cabello más sutil\nQue tienes en tu trenzado\nHe de hacer una cadena,\nPara traerte á mi lado.",210,0,-1,194,"",0,4,"ao",14,0,-1,0,71,71,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0071-05",15,"Dicen que la reina inglesa\nTiene los cabellos rubios;\nY yo te digo: princesa,\nNingunos como los tuyos.",210,0,-1,194,"",0,4,"uo",-1,0,-1,0,71,71,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0071-06",15,"Las estrellas y luceros\nQue salen por el oriente\nLos tengo comparaditos\nCon los rizos de tu frente.",210,0,-1,194,"",0,4,"ee",15,0,-1,0,71,71,"","",0,"palau_cantares","","",10,0,0,[],"",""],["lafuente_madrid-p0072-01",15,"Tu frente es plaza de armas,\nY tu nariz el cañon,\nY tus ojitos disparan\nFlechas á mi corazon. (1)",210,0,-1,194,"",0,4,"ao",31,0,-1,0,72,72,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0072-02",15,"¿Que es aquello que reluce\nPor detras del campanario?\n¿Es estrella? ¿Son tus ojos?\n¿Ó es la Vírgen del Rosario?",210,0,-1,194,"",0,4,"ao",25,0,-1,0,72,72,"","",0,"","","",8,0,0,[],"",""],["lafuente_madrid-p0072-03",15,"Ni son chicos, ni son grandes\nLos ojos de mi amadora,\nSon como quesos de Flandes,\nQue entran dos en cada arroba.",210,0,-1,194,"",0,4,"oa",-1,0,-1,0,72,72,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0072-04",15,"Tienes ojos de paloma,\nCarita de leche y sangre,\nY los cabellitos rubios,\nComo la Vírgen del Cármen.",210,0,-1,194,"",0,4,"ae",-1,0,-1,0,72,72,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0072-05",15,"Esos ojitos azules\nSe los has robado al cielo,\nY al cielo le darás cuenta\nDel mal que hiciste con ellos.",210,0,-1,194,"",0,4,"eo",-1,0,-1,0,72,72,"","",0,"rm_t2, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0072-06",15,"Los ojos de mi morena\nSon lo mismo que mis males:\nGrandes, como mis fatigas,\nNegros, como mis pesares.",210,0,-1,194,"",0,4,"ae",-1,0,-1,0,72,72,"","",0,"palau_cantares","","",23,0,0,[],"",""],["lafuente_madrid-p0073-01",15,"Los ojos de mi morena\nTienen un mirar extraño, (1)\nQue matan en una hora\nMás que la muerte en un año.",210,0,-1,194,"",0,4,"ao",40,0,-1,0,73,73,"","",0,"","","",23,0,0,[],"",""],["lafuente_madrid-p0073-02",15,"Á todos los ojos negros\nLos aprisionan mañana,\nBien puedes tú, que los tienes,\nEchar empeño á la Sala.",210,0,-1,194,"",0,4,"aa",-1,0,-1,0,73,73,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0073-03",15,"Son tus ojos dos luceros,\nTu boca un clavel de mayo,\nSon tus mejillas dos rosas;\nHázme dueño de ese ramo.",210,0,-1,194,"",0,4,"ao",-1,0,-1,0,73,73,"","",0,"palau_cantares","","",8,0,0,[],"",""],["lafuente_madrid-p0073-04",15,"Los ojos de mi morena\nSon un tren de artillería,\nQue nada dejan derecho,\nCuando hacen la puntería.",210,0,-1,194,"",0,4,"ia",0,0,-1,0,73,73,"","",0,"rm_t2, palau_cantares","","",23,0,0,[],"",""],["lafuente_madrid-p0073-05",15,"Tus ojos tienen la culpa,\nCuando los flechas, indina,\nDe que yo tenga este cuerpo\nLo mismo que jaletina.",210,0,-1,194,"",0,4,"ia",11,0,-1,0,73,73,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0073-06",15,"Los ojos de mi morena\nMe parecieron ayer\nEse lucero que sale\nÁ eso del amanecer.",210,0,-1,194,"",0,4,"e",20,0,-1,0,73,73,"","",0,"rm_t2, palau_cantares","","",23,0,0,[],"",""],["lafuente_madrid-p0074-01",15,"Tienes cierto no sé qué,\nQue me haces perder el tino\nCon el mirar halagüeño\nDe tus ojos peregrinos.",210,0,-1,194,"",0,4,"io",-1,0,-1,0,74,74,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0074-02",15,"Son tus ojos dos cañones\nCargados de municion,\nY tus palabras son balas\nQue pasan mi corazon.",210,0,-1,194,"",0,4,"o",31,0,-1,0,74,74,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0074-03",15,"Son tus ojos dos señores\nJueces de chancillería,\nLos que sentencian el pleito,\nY á mí me quitan la vida.",210,0,-1,194,"",0,4,"ia",-1,0,-1,0,74,74,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0074-04",15,"Salga el sol, si ha de salir,\nY si no, que nunca salga,\nQue para alumbrarme á mí\nLa luz de tus ojos basta.",210,0,-1,194,"",0,4,"aa",-1,0,-1,0,74,74,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0074-05",15,"Para todos en el mundo\nSale el sol por la mañana,\nPara mí sale tan so'o\nCuando contemplo tu cara.",210,0,-1,194,"",0,4,"aa",-1,0,-1,0,74,74,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0074-06",15,"Con las estrellas del norte\nSe guian los marineros;\nYo me guio con tus ojos,\nQue parecen dos luceros.",210,0,-1,194,"",0,4,"eo",22,0,-1,0,74,74,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0074-07",15,"Eres la estrella del norte\nQue á los marineros guia,\nDesde que se hace de noche\nHasta que se hace de dia.",210,0,-1,194,"",0,4,"a",0,0,-1,0,74,74,"","",0,"rm_t2","","",2,0,0,[],"",""],["lafuente_madrid-p0075-01",15,"En el anchuroso mar\nNavegando me perdí,\nY con la luz de tus ojos\nUn puerto de España vi.",210,0,-1,194,"",0,4,"i",23,0,-1,0,75,75,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0075-02",15,"Tienes unos ojos, niña,\nQue si los dieras á censo,\nNo faltara quien te diera\nUn veinticinco por ciento.",210,0,-1,194,"",0,4,"eo",-1,0,-1,0,75,75,"","",0,"rm_t2, palau_cantares","","",13,0,0,[],"",""],["lafuente_madrid-p0075-03",15,"Tienes unos ojos, niña,\nTan hechos á la humildad,\nQue cuando vas por la calle,\nPareces la Soledad.",210,0,-1,194,"",0,4,"a",16,0,-1,0,75,75,"","",0,"rm_t2, palau_cantares","","",13,0,0,[],"",""],["lafuente_madrid-p0075-04",15,"Todos los aragoneses\nHan salido de Aragon\nEn busca de unos ladrones,\nMorena, tus ojos son.",210,0,-1,194,"",0,4,"o",31,0,-1,0,75,75,"","",0,"rm_t2, palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0075-05",15,"Tus ojos, bella paloma,\nLlevan pleito con el sol;\nPorque el sol es uno solo,\nTus ojos dos soles son.",210,0,-1,194,"",0,4,"o",-1,0,-1,0,75,75,"","",0,"rm_t2, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0075-06",15,"Tus ojos son de esmeralda,\nY tu boca de carmin;\nSon tus mejillas dos rosas\nQue se comienzan á abrir.",210,0,-1,194,"",0,4,"i",-1,0,-1,0,75,75,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0075-07",15,"Son tus ojos dos espejos;\nEn ellos me miro yo.\n¡No los cierres, que me matas!\n¡No los cierres, ábrelos!",210,0,-1,194,"",5,4,"ao",-1,0,-1,0,75,75,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0076-02",15,"Á la salida de un cármen\nUnos ojos negros ví;\nDe quien eran, no lo sé,\nQue me cautivaron, sí.",210,0,-1,194,"",0,4,"i",23,0,-1,0,76,76,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0076-04",15,"Ojos negros y risueños,\nBoquita de serafin,\nEstoy soñando contigo,\nDesde el dia en que te vi.",210,0,-1,194,"",0,4,"i",-1,0,-1,0,76,76,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0076-05",15,"Toda mi vida en el mar,\nNo me cautivaron moros,\nY una vez que entré en tu casa\nMe cautivaron tus ojos.",210,0,-1,194,"",0,4,"oo",-1,0,-1,0,76,76,"","",0,"rm_t2, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0076-06",15,"Tus ojos me cautivaron,\nBlanca paloma sin hiel,\nTus ojos me cautivaron,\nQue no los moros de Argel.",210,0,-1,194,"",1,4,"e",32,0,-1,0,76,76,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0077-01",15,"Para pasear tu calle\nNo necesito farol;\nSon tus ojos dos luceros,\nQue relumbran más que el sol.",210,0,-1,194,"",0,4,"o",24,0,-1,0,77,77,"","",0,"palau_cantares","","",8,0,0,[],"",""],["lafuente_madrid-p0077-02",15,"Tus cejas son medias lunas,\nTus ojos son dos luceros,\nQue alumbran de noche y dia,\nSiendo más que los del cielo.",210,0,-1,194,"",0,4,"eo",-1,0,-1,0,77,77,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0077-03",15,"Con esos ojos gachones,\nSerrana, con que me miras,\nEl corazon me lo partes,\nY el alma me la lastimas.",210,0,-1,194,"",0,4,"ia",-1,0,-1,0,77,77,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0077-04",15,"La luna en el Oceano\nCon sus rayos argentinos\nNo da tanta luz al mundo,\nComo tus ojos divinos.",210,0,-1,194,"",0,4,"io",206,0,-1,0,77,77,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0077-05",15,"Son tus ojos dos luceros\nPuestos en tan alta estima,\nQue en solo haberlos mirado\nSe me ha turbado la vista.",210,0,-1,194,"",0,4,"ia",-1,0,-1,0,77,77,"","",0,"rm_t2, palau_cantares","","",8,0,0,[],"",""],["lafuente_madrid-p0077-06",15,"Manojitos de alfileres\nMe parecen tus pe tañas,\nQue cada vez que me miras,\nMe los clavas en el alma.",210,0,-1,194,"",0,4,"aa",-1,0,-1,0,77,77,"","",0,"","","",5,0,0,[],"",""],["lafuente_madrid-p0078-01",15,"Tus ojos son dos tinteros,\nTu nariz, pluma cortada,\nTus dientes, letra menuda,\nTu boca, carta cerrada.",210,0,-1,194,"",0,4,"aa",49,0,-1,0,78,78,"","",0,"rm_t2, carrizo_salta, palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0078-02",15,"Tienes unos ojos, niña,\nMás negros que el azabache,\nY una carita más blanca\nQue la leche que mamaste.",210,0,-1,194,"",0,4,"ae",-1,0,-1,0,78,78,"","",0,"rm_t2, palau_cantares","","",13,0,0,[],"",""],["lafuente_madrid-p0078-03",15,"Unos ojos negros ví,\nY dije: ¡válgame el cielo!\n¡Tanto luto para mi!\nNo sé como no me muero.",210,0,-1,194,"",0,4,"eo",-1,0,-1,0,78,78,"","",0,"rm_t2, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0078-04",15,"Échame, niña bonita,\nLágrimas en un pañuelo,\nY las llevaré á Granada\nQue las engarce un platero",210,0,-1,194,"",0,4,"eo",-1,0,-1,0,78,78,"","",0,"rm_t2, palau_cantares, fernan_caballero","","",4,0,0,[],"",""],["lafuente_madrid-p0078-05",15,"Tienes una boca, niña,\nComo un capullo cerrado;\nDe buena gana lo abriera\nCon el soplo de mis labios.",210,0,-1,194,"",0,4,"ao",-1,0,-1,0,78,78,"","",0,"rm_t2, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0078-06",15,"Los dientes de tu boquita\nMe tienen cautivo y preso;\nEn mi vida he visto yo\nCadenas hechas de hueso.",210,0,-1,194,"",0,4,"eo",48,0,-1,0,78,78,"","",0,"rm_t2, palau_cantares, suspiros_amor","","",6,0,0,[],"",""],["lafuente_madrid-p0079-01",15,"Dáme un diente de tu boca\nDe los que tienes en medio,\nY lo engarzaré en diamante,\nPara colgarmelo al cuello.",210,0,-1,194,"",0,4,"eo",-1,0,-1,0,79,79,"","",0,"","","",5,0,0,[],"",""],["lafuente_madrid-p0079-02",15,"En el hoyo de tu barba\nEstoy mandado enterrar.\n¡Ay qué muerte tan dichosa!\n¡Quien se hubiera muerto ya!",210,0,-1,194,"",0,4,"a",-1,0,-1,0,79,79,"","",0,"rm_t2","","",7,0,0,[],"",""],["lafuente_madrid-p0079-03",15,"Copos de nieve en tu cara\nParece que van cayendo;\nMientras más te voy mirando,\nMejor me vas pareciendo.",210,0,-1,194,"",0,4,"eo",52,0,-1,0,79,79,"","",0,"rm_t2","","",2,0,0,[],"",""],["lafuente_madrid-p0079-04",15,"¿Qué pinceles dibujaron,\nQuerida, tu hermoso rostro,\nY tan fino lo sacaron,\nQue á mi no me gusta otro?",210,0,-1,194,"",0,4,"oo",-1,0,-1,0,79,79,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0079-05",15,"Eres más rubia que el sol,\nY más blanca que la nieve;\nEres rosa alejandrina,\nQue todo el año florece.",210,0,-1,194,"",0,4,"ee",-1,0,-1,0,79,79,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0079-06",15,"Vale más la sal que tienes\nEn esa cara morena,\nQue la torre de Serrano\nY el martinete de Heredia.",210,0,-1,194,"",0,4,"ea",-1,0,-1,0,79,79,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0080-01",15,"Por los colores de rosa\nQue tienes cuando te veo,\nPor lo mismo, niña hermosa\nEn el corazon te llevo.",210,0,-1,194,"",0,4,"eo",-1,0,-1,0,80,80,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0080-02",15,"Entre la nieve y la grana\nSe formaron tus mejillas,\nY como la nieve es blanca,\nLo encarnado es lo que brilla.",210,0,-1,194,"",0,4,"ia",-1,0,-1,0,80,80,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0080-03",15,"Muchas veces estoy viendo\nLas rosas de tu ventana,\nY muchas veces me engaño,\nCreyendo que son tu cara.",210,0,-1,194,"",0,4,"aa",-1,0,-1,0,80,80,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0080-04",15,"Las rosas y los claveles\nSe dieron una batalla,\nY los claveles ganaron,\nPorque reinan en tu cara.",210,0,-1,194,"",0,4,"aa",-1,0,-1,0,80,80,"","",0,"rm_t2, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0080-05",15,"Mira si he corrido tierras,\nQue he estado en Benamejí.\nNo he visto cara más bella,\nQue la de este serafin.",210,0,-1,194,"",0,4,"i",-1,0,-1,0,80,80,"","",0,"palau_cantares","","",15,0,0,[],"",""],["lafuente_madrid-p0080-06",15,"Tienes en tu cara pecas,\nY en tus carrillos colores,\nY en tu cuello gargantillas,\nY en tu corazon amores.",210,0,-1,194,"",0,4,"oe",5,0,-1,0,80,80,"","",0,"rm_t2, palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0080-07",15,"Hoyos tienes en la cara\nDe viruelas que te han dado,\nEn cada hoyo una rosa\nY un clavel disciplinado.",210,0,-1,194,"",0,4,"ao",14,0,-1,0,80,80,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0081-01",15,"Tienes la cara pecosa,\nComo huevo de pe: diz;\nEn cada peca una rosa,\nY en medio una flor de lis.",210,0,-1,194,"",1,4,"i",58,0,-1,0,81,81,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0081-02",15,"Tienes pecas en la cara;\nPero no te dé cuidado,\nQue mejor parece el cielo\nCuando está más estrellado.",210,0,-1,194,"",0,4,"ao",14,0,-1,0,81,81,"","",0,"rm_t2, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0081-03",15,"Tienes en tu cara pecas,\nY en tu garganta lunares,\nY en tu pecho más virtudes,\nQue rosas en los rosales.",210,0,-1,194,"",0,4,"ae",-1,0,-1,0,81,81,"","",0,"rm_t2, palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0081-04",15,"Tiene la prenda que adoro\nUn lunar en un carrillo,\nY en el otro lado tiene\nLa estrella del cielo empíreo.",210,0,-1,194,"",0,4,"io",-1,0,-1,0,81,81,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0081-05",15,"¿Con qué te lavas la cara,\nOjitos de palomita?\n¿Con qué te lavas la cara,\nQue la tienes tan bonita?",210,0,-1,194,"",1,4,"ia",50,0,-1,0,81,81,"","",0,"rm_t2, palau_cantares","","",9,0,0,[],"",""],["lafuente_madrid-p0081-06",15,"¿Con qué te lavas la cara\nQue tan colorada estás?\n-Me lavo con agua clara,\nY Dios pone lo demas.",210,0,-1,194,"",1,4,"ea",51,0,-1,0,81,81,"","",0,"rm_t2, palau_cantares","","",9,0,0,[],"",""],["lafuente_madrid-p0082-01",15,"Asi como corre el agua\nPor debajo de la adelfa,\nAsí corre por tu cara\nLa gracia de Dios, morena.",210,0,-1,194,"",0,4,"ea",-1,0,-1,0,82,82,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0082-02",15,"En enero no hay claveles,\nPorque los marchita el hielo;\nEn tu cara los hay siempre,\nPorque lo permite el cielo.",210,0,-1,194,"",0,4,"eo",10,0,-1,0,82,82,"","",0,"rm_t2, carrizo_salta, palau_cantares, fernan_caballero","","",5,0,0,[],"",""],["lafuente_madrid-p0082-03",15,"De tu cara sale el sol,\nDe tu garganta la luna:\nMorenas he visto yo,\nPero como tú ninguna.",210,0,-1,194,"",0,4,"ua",56,0,-1,0,82,82,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0082-04",15,"Con lo blanco de tu cuello,\nSalada, me cautivaste;\nÁtame con tu cabello\nHasta que venga el rescate.",210,0,-1,194,"",0,4,"ae",-1,0,-1,0,82,82,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0082-05",15,"Rubita, sol de los soles,\nTu cara es una custodia,\nY tu pecho la escalera\nPara subir á la gloria.",210,0,-1,194,"",0,4,"oa",-1,0,-1,0,82,82,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0082-06",15,"Tienes cuello de marfil,\nCinturita de campana;\nCatorce leguas de aquí\nTiene tu hermosura fama.",210,0,-1,194,"",0,4,"aa",-1,0,-1,0,82,82,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0082-07",15,"Dicen que la golondrina\nTiene la pechuga blanca,\nY mi serranilla tiene\nLa pechuga y la garganta.",210,0,-1,194,"",0,4,"aa",-1,0,-1,0,82,82,"","",0,"rm_t2, palau_cantares, suspiros_amor","","",12,0,0,[],"",""],["lafuente_madrid-p0083-01",15,"Es tu pecho una alcobita\nHecha con tanto primor,\nQue me parece á la vista\nDe la gloria el resplandor.",210,0,-1,194,"",0,4,"o",72,0,-1,0,83,83,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0083-02",15,"Son tus manos palmas reales,\nTus dedos diez azucenas,\nTus labios finos corales,\nTus dientes menudas perlas.",210,0,-1,194,"",0,4,"ea",-1,0,-1,0,83,83,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0083-03",15,"¡Ay, qué dedos para anillos!\n¡Qué pecho para un diamante!\n¡Qué orejas para zarzillos!\n¡Qué niña para un amante!",210,0,-1,194,"",1,4,"ae",47,0,-1,0,83,83,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0083-04",15,"¡Que manitas para guantes!\nPara sortijas ¡qué dedos!\n¡Qué cuello para collares!\n¡Qué boquita para un beso!",210,0,-1,194,"",0,4,"eo",-1,0,-1,0,83,83,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0083-05",15,"María se fué á lavar\nAl rio de Manzanares:\n¿Para qué quiere jabon,\nSi sus manos son cristales?",210,0,-1,194,"",0,4,"ae",-1,0,-1,0,83,83,"","",0,"rm_t2","","",2,0,0,[],"",""],["lafuente_madrid-p0083-06",15,"Ese cuerpo y ese talle,\nY esa delgada cintura\nSon buenos para un enfermo:\nYa tengo yo calentura.",210,0,-1,194,"",0,4,"ua",17,0,-1,0,83,83,"","",0,"rm_t2","","",2,0,0,[],"",""],["lafuente_madrid-p0084-02",15,"Eres delgada de talle,\nComo junco de ribera,\nDe las niñas de tu calle,\nTú te llevas la bandera.",210,0,-1,194,"",1,4,"ea",44,0,-1,0,84,84,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0084-03",15,"Delgadita de cintura,\nComo junco marinero,\nNi eres alta, ni eres baja,\nQue eres como yo te quiero.",210,0,-1,194,"",0,4,"eo",38,0,-1,0,84,84,"","",0,"rm_t2, palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0084-04",15,"Tienes una cinturita\nQue parece contrabando;\nYo, como contrabandista,\nPor ella vengo penando.",210,0,-1,194,"",0,4,"ao",33,0,-1,0,84,84,"","",0,"rm_t2, palau_cantares","","",14,0,0,[],"",""],["lafuente_madrid-p0084-05",15,"Tienes una cinturita\nTan delgada y tan donosa,\nQue la vengo á comparar\nAl capullo de la rosa.",210,0,-1,194,"",0,4,"oa",63,0,-1,0,84,84,"","",0,"rm_t2","","",14,0,0,[],"",""],["lafuente_madrid-p0084-06",15,"Tienes una cinturita\nTan delgada, que parece\nUn clavel en la maceta,\nQue con el aire se mece.",210,0,-1,194,"",0,4,"ee",64,0,-1,0,84,84,"","",0,"palau_cantares","","",14,0,0,[],"",""],["lafuente_madrid-p0084-07a",15,"Tienes una cinturita\nDe justillo madrileño.\n¡Viva quien tiene sandunga,\nY la gasta con salero!",210,0,-1,194,"",0,4,"eo",-1,0,-1,0,85,85,"","",0,"rm_t2","","",14,0,0,[],"",""],["lafuente_madrid-p0084-07b",15,"Tienes una cinturita....!\nAnoche te la medí;\nCon vara y media de cinta\nCatorce vueltas le dí.",210,0,-1,194,"",0,4,"i",23,0,-1,0,85,85,"","",0,"","","",14,0,0,[],"",""],["lafuente_madrid-p0085-01",15,"Parece tu cuerpo un junco,\nTu cabeza una naranja,\nTu pecho un jardin de flores.\nDonde descansa mi alma.",210,0,-1,194,"",0,4,"aa",-1,0,-1,0,85,85,"","",0,"rm_t2","","",2,0,0,[],"",""],["lafuente_madrid-p0085-02",15,"En el valle no hay un talle\nComo el que tiene mi prima,\nNi cuerpo más sandunguero,\nNi cara más peregrina.",210,0,-1,194,"",0,4,"ia",-1,0,-1,0,85,85,"","",0,"rm_t2","","",2,0,0,[],"",""],["lafuente_madrid-p0085-03",15,"Dos columnas de alabastro\nHechas con arquitectura,\nEstán sosteniendo el garbo\nDe tu pulida cintura.",210,0,-1,194,"",0,4,"ua",17,0,-1,0,85,85,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0085-04",15,"Los zapatos que mantienen\nEl garbo de esa deidad\nDebieran de ser de oro\nEn lugar de cordoban.",210,0,-1,194,"",5,4,"oa",-1,0,-1,0,85,85,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0086-01",15,"Con ese pié pulidito\nY ese modito de andar\nTiene usté más hombres muertos\nQue arenas tiene la mar.",210,0,-1,194,"",0,4,"a",21,0,-1,0,86,86,"","",0,"rm_t2","","",3,0,0,[],"",""],["lafuente_madrid-p0086-02",15,"Con ese delantal blanco\nY esas naguas de indianilla\nEl corazon me has robado,\nPicara retrecherilla.",210,0,-1,194,"",0,4,"ia",162,0,-1,0,86,86,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0086-03",15,"La campana de la Vela\nNo tiene tanta balumba,\nComo tienes tú, morena,\nCon ese cuerpo sandunga.",210,0,-1,194,"",0,4,"ua",-1,0,-1,0,86,86,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0086-04",15,"Eres como el trigo rubio\nEscogido grano á grano;\nEres tú la más hermosa\nQue mis ojos han mirado.",210,0,-1,194,"",0,4,"ao",-1,0,-1,0,86,86,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0086-05",15,"De todas las de tu calle\nEres tú la más hermosa\n¿Cómo no pones bandera,\nCapitana generosa?",210,0,-1,194,"",0,4,"oa",63,0,-1,0,86,86,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0087-01",15,"Eres más apañadita\nQue la nieve en el barranco,\nQue el clavel en la maceta\nY la azucena en el campo",210,0,-1,194,"",0,4,"ao",-1,0,-1,0,87,87,"","",0,"rm_t2","","",2,0,0,[],"",""],["lafuente_madrid-p0087-02",15,"No he visto rosa más bella,\nNi clavel más encarnado,\nNi mujer más á mi gusto,\nQue esta que tengo á mi lado.",210,0,-1,194,"",0,4,"ao",14,0,-1,0,87,87,"","",0,"rm_t2","","",2,0,0,[],"",""],["lafuente_madrid-p0087-03",15,"De los piés á la cabeza\nEres un ramo de flores.\n¡Bendita sea la madre\nQue por tí pasó dolores!",210,0,-1,194,"",0,4,"oe",5,0,-1,0,87,87,"","",0,"rm_t2","","",3,0,0,[],"",""],["lafuente_madrid-p0087-04",15,"La madre que te parió\nEra una rosa temprana,\nY se le cayó una hoja,\nQue eres tú, bella serrana.",210,0,-1,194,"",0,4,"aa",4,0,-1,0,87,87,"","",0,"","","",6,0,0,[],"",""],["lafuente_madrid-p0087-05",15,"La madre que te parió,\nMereciera parir veinte,\nY que yo fuera el diezmero,\nY me tocaras en suerte.",210,0,-1,194,"",0,4,"ee",-1,0,-1,0,87,87,"","",0,"","","",6,0,0,[],"",""],["lafuente_madrid-p0088-01",15,"Mal hizo en tenerte sola\nLa bendita de tu madre;\nAngelitos como tú\nSe deben tener á pares.",210,0,-1,194,"",0,4,"ae",-1,0,-1,0,88,88,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0088-02",15,"¡Qué contentita estará\nLa madre de esa doncella!\nEstando el cielo tan alto,\nTiene en su casa una estrella.",210,0,-1,194,"",0,4,"ea",6,0,-1,0,88,88,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0088-03",15,"Ayer tarde en el paseo,\nNiña, de azul te vestiste;\nQue tambien hay en la tierra\nÁngel que de azul se viste.",210,0,-1,194,"",0,4,"ie",153,0,-1,0,88,88,"","",0,"palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0088-04",15,"En el cielo de tu casa\nTe vi, salada, ayer tarde;\nBien puede llamarse cielo,\nPorque en ella vive un ángel.",210,0,-1,194,"",0,4,"ae",-1,0,-1,0,88,88,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0088-05",15,"No llores, ángel humano,\nAunque veas que me muero;\nPorque si te ven llorar,\nPensarán que me condeno.",210,0,-1,194,"",0,4,"eo",-1,0,-1,0,88,88,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0088-06",15,"En la puerta de tu casa\nHe de poner un letrero\nCon letras de oro, que diga:\nPor aquí se sube al cielo.",210,0,-1,194,"",0,4,"eo",-1,0,-1,0,88,88,"","",0,"suspiros_amor","","",13,0,0,[],"",""],["lafuente_madrid-p0089-01",15,"Bendita sea tu casa\nY el albañil que la hizo,\nQue por dentro está la gloria,\nY por fuera el paraiso.",210,0,-1,194,"",0,4,"io",92,0,-1,0,89,89,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0089-02",15,"Eres tú la que le quitas\nEl color á la manzana,\nY la blancura á la nieve,\nY la frescura á las aguas.",210,0,-1,194,"",0,4,"aa",-1,0,-1,0,89,89,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0089-03",15,"Eres como la verbena\nQue en el campo verde nace,\nEres como el caramelo\nQue en la boca se deshace.",210,0,-1,194,"",0,4,"ae",84,0,-1,0,89,89,"","",0,"rm_t2","","",3,0,0,[],"",""],["lafuente_madrid-p0089-04",15,"Su color te dió la rosa,\nEl cielo su azul turquí,\nTe dió su talle la palma,\nY su blancura el jazmin.",210,0,-1,194,"",0,4,"i",-1,0,-1,0,89,89,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0089-05",15,"Siempreviva te diré\nY lirio del campo no;\nPorque el lirio se marchita,\nY la siempreviva no.",210,0,-1,194,"",0,4,"o",-1,0,-1,0,89,89,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0089-06",15,"El dia que tú naciste,\nNacieron todas las flores,\nY en la pila del bautismo\nCantaban los ruiseñores.",210,0,-1,194,"",0,4,"oe",5,0,-1,0,89,89,"","",0,"palau_cantares","","",16,0,0,[],"",""],["lafuente_madrid-p0090-01",15,"El dia que tú naciste\n¡Qué triste quedaria el sol,\nAl ver que otro sol salia\nCon mucho más resplandor!",210,0,-1,194,"",0,4,"o",-1,0,-1,0,90,90,"","",0,"","","",16,0,0,[],"",""],["lafuente_madrid-p0090-02",15,"El naranjo de tu patio,\nCuando te acercas á él,\nSe desprende de sus flores,\nY te las echa á los piés.",210,0,-1,194,"",0,4,"e",-1,0,-1,0,90,90,"","",0,"rm_t2, palau_cantares, fernan_caballero","","",5,0,0,[],"",""],["lafuente_madrid-p0090-03",15,"Tus colchones son jazmines,\nY tus sábanas mosquetas,\nAzucena tu almohada,\nY tú, rosa que te acuestas.",210,0,-1,194,"",0,4,"ea",-1,0,-1,0,90,90,"","",0,"rm_t2, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0090-04",15,"Rosa, clavellina y dalia\nMe has parecido al mirarte,\nY tambien me has parecido\nPerla engastada en diamantes.",210,0,-1,194,"",0,4,"ae",-1,0,-1,0,90,90,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0090-05",15,"Eres mosqueta olorosa,\nEres el fresco jazmin,\nEres la rosa fragante\nEn la floresta de abril.",210,0,-1,194,"",0,4,"i",-1,0,-1,0,90,90,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0090-06",15,"Eres el mejor clavel\nDe las orillas del Darro,\nQue se abrió con el rocio\nDe las mañanas de mayo.",210,0,-1,194,"",0,4,"ao",-1,0,-1,0,90,90,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0090-07",15,"Eres la palma gallarda\nY hermosísimo laurel;\nEres azucena blanca\nY bellisimo clavel.",210,0,-1,194,"",0,4,"e",32,0,-1,0,90,90,"","",0,"rm_t2, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0091-01",15,"Tú eres el clavel de abril\nY la rosita de mayo,\nLa hermosa luna de enero,\nQue me tienes hechizado.",210,0,-1,194,"",0,4,"ao",-1,0,-1,0,91,91,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0091-02",15,"Eres una clavellina\nRodeada de claveles,\nComo eres tan peregrina,\nHechizadito me tienes.",210,0,-1,194,"",0,4,"ee",-1,0,-1,0,91,91,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0091-03",15,"Eres la flor de las flores,\nEres rosa entre las rosas,\nEres la que estimo y amo,\nEres tú la más hermosa.",210,0,-1,194,"",0,4,"oa",-1,0,-1,0,91,91,"","",0,"rm_t2, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0091-04",15,"Eres más apetecible\nQue el fresco de la mañana,\nY más hermosa y más bella\nQue rosa de abril temprana.",210,0,-1,194,"",0,4,"aa",4,0,-1,0,91,91,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0091-05",15,"Al verte las flores lloran\nCuando entras en tu jardin,\nPorque las flores quisieran\nTodas parecerse á tí.",210,0,-1,194,"",0,4,"i",-1,0,-1,0,91,91,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0091-06",15,"Á tu puerta llamo puerta,\nY á tu ventana, ventana,\nÁ tu madre, jardinera,\nY á tí, rosita encarnada.",210,0,-1,194,"",0,4,"aa",-1,0,-1,0,91,91,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0091-07",15,"Cuando va mi niña á misa\nLa iglesia se resplandece,\nHasta la yerba que pisa,\nSi está seca, reverdecc.",210,0,-1,194,"",5,4,"e",-1,0,-1,0,91,91,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0092-01",15,"Cuando mi niña se pone\nLa saya para ir á misa,\nSale el sol y se oscurece,\nSale la luna y se eclipsa.",210,0,-1,194,"",0,4,"ia",-1,0,-1,0,92,92,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0092-02",15,"Á la flor de la violeta\nMezclada con el jazmin,\nÁ eso me huele tu cuerpo,\nCuando estoy cerca de tí.",210,0,-1,194,"",0,4,"i",-1,0,-1,0,92,92,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0092-03",15,"Clavellina colorada\nNacida en el mes de enero,\n¿Quién ha visto cortar flores\nEn el rigor del invierno?",210,0,-1,194,"",0,4,"eo",-1,0,-1,0,92,92,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0092-04",15,"Ya viene marzo con flores,\nY con sus rosas abril,\nY mayo con sus claveles\nPara coronarte á ti.",210,0,-1,194,"",0,4,"i",-1,0,-1,0,92,92,"","",0,"rm_t2, palau_cantares, fernan_caballero","","",4,0,0,[],"",""],["lafuente_madrid-p0092-05",15,"Debajo de tu ventana,\nPor pintarte á ti, pinté,\nUna rosa catalana\nY un clavel aragonés.",210,0,-1,194,"",0,4,"e",-1,0,-1,0,92,92,"","",0,"rm_t2, palau_cantares, fernan_caballero","","",29,0,0,[],"",""],["lafuente_madrid-p0092-06",15,"¡Qué linda clavellinera\nQue estoy viendo desde aqui!\n¡Como soy forasterito,\nNo hay un clavel para mí!",210,0,-1,194,"",0,4,"i",23,0,-1,0,92,92,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0093-01",15,"En la mar se crian peces,\nY en la orilla caracoles,\nY en el jardin de mi dama\nClavellinas á montones.",210,0,-1,194,"",0,4,"oe",-1,0,-1,0,93,93,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0093-02",15,"Eres paloma torcaz\nY tórtola en el arrullo,\nPor donde quiera que vas.\nNo hay salero como el tuyo.",210,0,-1,194,"",1,4,"uo",78,0,-1,0,93,93,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0093-03",15,"¡Salero, viva el salero,\nCarita de serafin!\n¡Cuántas horitas de sueño\nTengo perdidas por tí!",210,0,-1,194,"",0,4,"i",-1,0,-1,0,93,93,"","",0,"rm_t2, palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0093-04",15,"Salero, viva el salero,\nSalero, viva la sal,\nQue tiene usté más salero,\nQue el salero universal.",210,0,-1,194,"",1,4,"a",1,0,-1,0,93,93,"","",0,"rm_t2","","",6,0,0,[],"",""],["lafuente_madrid-p0093-05",15,"Vivan las mozas juncales\nQue se pasean con rumbo,\nLas que quieren sus amantes.\nCon el salero del mundo..",210,0,-1,194,"",0,4,"uo",-1,0,-1,0,93,93,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0094-01",15,"Ande usté, prenda morena,\nCabellos de soberana,\nCuerpecito malagueño,\nCintura de valenciana.",210,0,-1,194,"",0,4,"aa",4,0,-1,0,94,94,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0094-02",15,"Ande usté, almacen de gracia,\nCuerpo de corregidora,\nSi yo fuera rey de Holanda\nLe pusiera una corona.",210,0,-1,194,"",0,4,"oa",-1,0,-1,0,94,94,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0094-03",15,"Los ángeles te coronen.\nY te lleven á la gloria,\nY te pongan á los piés\nDe la divina pastora.",210,0,-1,194,"",0,4,"oa",-1,0,-1,0,94,94,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0094-04",15,"No te diré sol ni luna,\nPero te diré diamante;\nQue la luna crece y mengua,\nY en ti no cabe menguante.",210,0,-1,194,"",0,4,"ae",47,0,-1,0,94,94,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0094-05",15,"Si la luna no menguara,\nTe comparara con ella;\nPero te compararé\nCon el sol y las estrellas.",210,0,-1,194,"",0,4,"ea",-1,0,-1,0,94,94,"","",0,"rm_t2, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0094-06",15,"En frente del sol saliente\nTiene mi niña el balcon:\nSale el sol, sale mi niña,\nSalen mi niña y el sol.",210,0,-1,194,"",0,4,"o",-1,0,-1,0,94,94,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0094-07",15,"El marco de tu ventan\nTodo está lleno de estrellas,\nY así que te asomas tú,\nSale el sol, y se van ellas.",210,0,-1,194,"",0,4,"ea",89,0,-1,0,94,94,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0095-01",15,"Más hermosa eres que el sol\nCuando sus rayos dispara;\nMás hermosa que la luna\nCuando va serena y clara.",210,0,-1,194,"",0,4,"aa",57,0,-1,0,95,95,"","",0,"rm_t2, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0095-02",15,"El sol se quedó eclipsado,\nEnternecido de amores;\nCuando el sol se ha enamorado,\nNiña, ¿qué serán los hombres?",210,0,-1,194,"",0,4,"oe",-1,0,-1,0,95,95,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0095-03",15,"En la ciudad de Alicante,\nNiña, me acordé de tí,\nQue relumbraba una estrella,\nY se parecia á tí.",210,0,-1,194,"",0,4,"i",-1,0,-1,0,95,95,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0095-04",15,"Las estrellas he contado,\nY la de Venus dejé,\nY por ser la más hermosa,\nContigo la comparé.",210,0,-1,194,"",0,4,"e",77,0,-1,0,95,95,"","",0,"","","",5,0,0,[],"",""],["lafuente_madrid-p0095-05",15,"Eres hermana del sol,\nPrima hermana de la luna,\nSobrina del alabastro,\nDe el alba prima segunda",210,0,-1,194,"",0,4,"ua",-1,0,-1,0,95,95,"","",0,"","","",4,0,0,[],"",""],["lafuente_madrid-p0095-06",15,"La luna clara salió,\nY viendo que le ganabas,\nTras un nublo se metió\nCorrida y avergonzada.",210,0,-1,194,"",0,4,"aa",-1,0,-1,0,95,95,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0095-07",15,"¿Sabes á quién te pareces?\n¿Sabes á quién le das aire?\nAl sol cuando resplandece,\nY á la luna cuando sale.",210,0,-1,194,"",0,4,"ae",-1,0,-1,0,95,95,"","",0,"rm_t2","","",3,0,0,[],"",""],["lafuente_madrid-p0096-01",15,"Sale el sol por la mañana\nY oscurece las estrellas;\nY tú oscureces al sol,\nCuando sales á tu puerta.",210,0,-1,194,"",0,4,"ea",-1,0,-1,0,96,96,"","",0,"rm_t2","","",5,0,0,[],"",""],["lafuente_madrid-p0096-02",15,"Serrana, tu perfeccion\nLa dibujé con tal arte,\nQue la luna se eclipsó,\nY el sol se paró á mirarte.",210,0,-1,194,"",0,4,"ae",8,0,-1,0,96,96,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0096-03",15,"Si quieres que salga el sol\nTres horas antes del dia,\nVété á la plaza Mayor\nY pregunta por María.",210,0,-1,194,"",0,4,"ia",0,0,-1,0,96,96,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0096-04",15,"Si te digo sol, te ofendo;\nY si luna, te maltrato,\nY si te digo lucero,\nMe parece que te mato.",210,0,-1,194,"",0,4,"ao",19,0,-1,0,96,96,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0096-05",15,"Te comparo con la luna,\nCon el sol y los luceros,\nY si no fuera pecado,\nCon la reina de los cielos.",210,0,-1,194,"",0,4,"eo",-1,0,-1,0,96,96,"","",0,"rm_t2, carrizo_salta, palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0096-06",15,"Al sol de los siete soles\nY á la luna de Aragon\nComparo yo tus colores,\nCuando sales al balcon.",210,0,-1,194,"",0,4,"ao",31,0,-1,0,96,96,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0097-01",15,"En la ventana te ví,\nNiña, como el sol que sale;\nMe quité el sombrero, y dije.\nMorenilla, Dios te guarde.",210,0,-1,194,"",0,4,"ae",-1,0,-1,0,97,97,"","",0,"rm_t2","","",2,0,0,[],"",""],["lafuente_madrid-p0097-02",15,"Es tanta la claridad\nQue por tu ventana sale,\nQue creí que era la luna,\nY eran las dos de la tarde.",210,0,-1,194,"",0,4,"ae",-1,0,-1,0,97,97,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0097-03",15,"Una estrella se ha perdido,\nY en el cielo no parece;\nEn tu cuarto se ha metido\nY en tu cara resplandece.",210,0,-1,194,"",1,4,"ee",64,0,-1,0,97,97,"","",0,"rm_t2","","",6,0,0,[],"",""],["lafuente_madrid-p0097-04",15,"Abre, niña, esa ventana,\nAbre la mitad siquiera,\nY entrará la media luna\nDonde está la luna entera.",210,0,-1,194,"",0,4,"ea",44,0,-1,0,97,97,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0097-05",15,"Apenas entré en tu calle\nCuando me dió el resplandor;\nLe dije á un amigo mio:\nEn esta calle está sol.",210,0,-1,194,"",0,4,"o",-1,0,-1,0,97,97,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0098-01",15,"Yo pensé que era la luna\nLa que estaba en el balcon,\nY salió la capitana\nDe Navarra y Aragon.",210,0,-1,194,"",0,4,"ao",31,0,-1,0,98,98,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0098-02",15,"La luz del amanecer,\nAl verte, se quedó tibia,\nY atras se quiso volver\nPorque le has causado envidia.",210,0,-1,194,"",0,4,"ia",-1,0,-1,0,98,98,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0098-03",15,"¿Cómo quieres que el sol salga,\nSi lo tienes en prisiones,\nHasta que tú te levantes\nY á la ventana te asomes?",210,0,-1,194,"",0,4,"oe",-1,0,-1,0,98,98,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0098-04",15,"Yo soy blanco, y te diré\nLa causa de estar moreno:\nEstoy adorando á un sol,\nY con sus rayos me quemo.",210,0,-1,194,"",0,4,"eo",-1,0,-1,0,98,98,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0098-05",15,"Con la luz te he comparado\n¡Mira qué comparacion!\nQue sin la luz no se puede\nDecir la misa mayor.",210,0,-1,194,"",0,4,"o",-1,0,-1,0,98,98,"","",0,"rm_t2, palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0098-06",15,"Tan solo en el mundo hay una\nCon quien poder compararte,\nY la encontré por fortuna\nPintada en un estandarte.",210,0,-1,194,"",1,4,"ae",8,0,-1,0,98,98,"","",0,"rm_t2, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0099-01",15,"Te quisiera comparar.....\nPero no, que me condeno,\nCon la Virgen del Pilar;\nEres un poquito menos.",210,0,-1,194,"",0,4,"eo",-1,0,-1,0,99,99,"","",0,"rm_t2, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0099-02",15,"Unos dicen que lo blanco,\nY otros dicen que lo negro,\nOtros que lo colorado;\nYo digo que lo moreno.",210,0,-1,194,"",0,4,"eo",-1,0,-1,0,99,99,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0099-03",15,"En la soledad del campo\nMe puse á considerar\nLos pesos duros que vale\nUna morena con sal.",210,0,-1,194,"",0,4,"a",-1,0,-1,0,99,99,"","",0,"palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0099-05",15,"Puede una mujer morena,\nCon una mirada que eche,\nPoner á un hombre en la cama\nY en un hospital diez meses.",210,0,-1,194,"",0,4,"ee",-1,0,-1,0,99,99,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0099-06",15,"Vivan los aires morenos,\nVivan los morenos aires,\nVivan los de mi morena,\nQue son como los de nadie.",210,0,-1,194,"",0,4,"ae",-1,0,-1,0,99,99,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0099-07",15,"Sosas eran en lo antiguo\nTodas las aguas del mar,\nPero escupió mi morena,\nY se volvieron salás.",210,0,-1,194,"",0,4,"a",-1,0,-1,0,99,99,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0100-01",15,"De la rama de un espino\nVi yo salir un clavel,\nPorque le tocó mi niña\nCon la puntilla del pié.",210,0,-1,194,"",0,4,"e",-1,0,-1,0,100,100,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0100-02",15,"No importa, niña, que seas\nMorenita de color,\nSi tienes en esa cara\nToda la gracia de Dios.",210,0,-1,194,"",0,4,"o",-1,0,-1,0,100,100,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0100-03",15,"Eres como la avellana,\nChiquita y llena de carne,\nChiquita y apañadita,\nComo te quiere tu amante.",210,0,-1,194,"",0,4,"ae",-1,0,-1,0,100,100,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0100-04",15,"Eres chiquita y bonita,\nEres como yo te quiero,\nPareces campanillita\nHecha á mano de un platero.",210,0,-1,194,"",1,4,"eo",38,0,-1,0,100,100,"","",0,"rm_t2, palau_cantares","","",12,0,0,[],"",""],["lafuente_madrid-p0100-05",15,"En la montaña de Jaca\nMe acordé de tí, sa'ero;\nPorque me faltó la sal,\nCuando estaba de ranchero.",210,0,-1,194,"",0,4,"eo",38,0,-1,0,100,100,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0100-06",15,"Viva todo lo serrano,\nQue por lo serrano muero,\nPorque serranito soy,\nY á una serrana camelo.",210,0,-1,194,"",0,4,"eo",-1,0,-1,0,100,100,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0100-07",15,"Vivan los cuerpos variles,\nViva la murmuracion,\nY tambien digo que viva\nTu salero, Encarnacion.",210,0,-1,194,"",0,4,"ao",714,0,-1,0,100,100,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0101-01",15,"Viva el lujo y quien lo trujo,\nY tambien quien lo mantiene,\nY tambien digo que viva\nEl salero y quien lo tiene.",210,0,-1,194,"",0,4,"ee",70,0,-1,0,101,101,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0101-02",15,"Cuando en ances de mi potro\nYo te lleve á Gibraltar,\nDirán los mozos al verte:\n¡Ay qué moza tan salá!",210,0,-1,194,"",0,4,"a",-1,0,-1,0,101,101,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0101-03",15,"Para guisar esta liebre\nSolo me falta la sal,\nUsté, que de sobra tiene,\n¿Me la quiere usté prestar?",210,0,-1,194,"",0,4,"a",-1,0,-1,0,101,101,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0101-04",15,"Eres Valle, en lo bonita,\nY en lo garbosa, Dolores,\nY en lo lozana y alegre\nEres un ramo de flores..",210,0,-1,194,"",3,4,"oe",5,0,-1,0,101,101,"","",0,"palau_cantares, fernan_caballero","","",3,0,0,[],"",""],["lafuente_madrid-p0101-05",15,"De lo más alto del cielo\nCayeron nueve claveles,\nTres Anas y tres Marias,\nTres pulidas Isabeles.",210,0,-1,194,"",0,4,"ee",97,0,-1,0,101,101,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0101-06",15,"De la raiz de la palma.\nNacieron las Isabeles,\nDelgaditas de cintura,\nY de corazon alegres.",210,0,-1,194,"",0,4,"ee",-1,0,-1,0,101,101,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0101-07",15,"Cuando te pusieron Ana\nEstaba borracho el cura,\nPorque debieron ponerte\nRamillete de hermosura.",210,0,-1,194,"",0,4,"ua",17,0,-1,0,101,101,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0102-01",15,"Quien te dió por nombre Paca\nNo te supo poner nombre,\nQue debió de haberte puesto\nLa perdicion de los hombres.",210,0,-1,194,"",0,4,"oe",-1,0,-1,0,102,102,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0102-02",15,"María sé que te llamas,\nY por apellido Luna,\nAlúmbrame con tus rayos,\nPorque está la noche oscura.",210,0,-1,194,"",0,4,"ua",-1,0,-1,0,102,102,"","",0,"rm_t2","","",6,0,0,[],"",""],["lafuente_madrid-p0102-03",15,"Dolores, flor de las flores,\nMaravilla de las indias,\nCara de quita-pesares,\nRamillete de celindas.",210,0,-1,194,"",0,4,"ia",-1,0,-1,0,102,102,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0102-04",15,"Házme, María, una torta,\nAunque sea de centeno,\nPorque en siendo de tu mano,\nSe volverá trigo bueno.",210,0,-1,194,"",0,4,"eo",76,0,-1,0,102,102,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0102-05",15,"En el bazar hay un vaso,\nY en el vaso una bebida,\nEn la bebida una rosa,\nY en la rosa una María.",210,0,-1,194,"",0,4,"ia",-1,0,-1,0,102,102,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0102-06",15,"Entre los árboles todos\nSe señorea el laurel,\nEntre las mujeres, Ana,\nY entre flores, el clavel.",210,0,-1,194,"",0,4,"e",32,0,-1,0,102,102,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0102-07",15,"Toda la calle Mayor\nHe venido preguntando\nDonde habita la hermosura;\nY aquí me han encaminado.",210,0,-1,194,"",3,4,"ao",-1,0,-1,0,102,102,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0103-01",15,"Aunque seas chiquitita,\nÁ mí no me da cuidado,\nPorque el árbol chiquitito\nCria fruto regalado.",210,0,-1,194,"",0,4,"ao",14,0,-1,0,103,103,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0103-02",15,"Aunque vives en rincon,\nNo vives arrinconada,\nQue en los rincones se crian\nLas mejores ensaladas.",210,0,-1,194,"",0,4,"aa",-1,0,-1,0,103,103,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0103-03",15,"De dos hermanas que son\nNo hay diferencia ninguna,\nEs la una como el sol,\nLa otra como la luna.",210,0,-1,194,"",0,4,"ua",56,0,-1,0,103,103,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0103-04",15,"Señor Alcalde mayor\nNo prenda usté á los ladrones,\nPorque tiene usté una hija\nQue roba los corazones.",210,0,-1,194,"",0,4,"oe",34,0,-1,0,103,103,"","",0,"rm_t2, fernan_caballero, palau_cantares","","",8,0,0,[],"",""],["lafuente_madrid-p0103-05",15,"En la corte de Madrid,\nSalada, vi tu retrato;\nEra un cuerpo tan gentil,\nQue hiciera pecar á un santo.",210,0,-1,194,"",0,4,"ao",-1,0,-1,0,103,103,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0103-06",15,"No sé como no florece\nLa escoba con que tú barres,\nSiendo tú tan bien nacida,\nHija de tan buenos padres.",210,0,-1,194,"",0,4,"ae",-1,0,-1,0,103,103,"","",0,"rm_t2","","",3,0,0,[],"",""],["lafuente_madrid-p0104-01",15,"En la puerta de tu casa\nCatorce muertos vi un dia,\nPorque los mató la pena\nViendo que no los querias.",210,0,-1,194,"",0,4,"ia",-1,0,-1,0,104,104,"","",0,"","","",13,0,0,[],"",""],["lafuente_madrid-p0104-02",15,"Por amores ha venido\nUn forastero al lugar;\nPor amores ha venido,\nY amores se ha de llevar.",210,0,-1,195,"",1,4,"a",21,0,-1,0,104,104,"","",0,"rm_t2","","",2,0,0,[],"",""],["lafuente_madrid-p0104-03",15,"Desde Madrid he venido\nPisando espinas y abrojos,\nSolo por llegar á verte,\nClavellina de mis ojos.",210,0,-1,195,"",0,4,"oo",99,0,-1,0,104,104,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0104-04",15,"Aquí me pongo á cantar\nÁ la sombra de la luna,\nPor ver si puedo alcanzar\nDe las dos hermanas, una.",210,0,-1,195,"",1,4,"ua",56,0,-1,0,104,104,"","",0,"palau_cantares","","",18,0,0,[],"",""],["lafuente_madrid-p0104-05",15,"La menor no tiene el tiempo,\nLa mayor pasa la edad,\nLa de en medio es la que quiero,\nSi su padre me la da.",210,0,-1,195,"",0,4,"a",-1,0,-1,0,104,104,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0105-01",15,"Al alt cielo subí\nÁpreguntar por tu nombre,\nY me dijo un serafin.\nQue te llamabas Dolores.",210,0,-1,195,"",0,4,"oe",-1,0,-1,0,105,105,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0105-02",15,"María sé que te llamas,\nTu apellido no lo sé;\nSi por la calle te encuentro,\nMaría te llamaré.",210,0,-1,195,"",0,4,"e",77,0,-1,0,105,105,"","",0,"rm_t2, palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0105-03",15,"Pregunté si eres casada,\nQue tu garbo me embelesa;\nEl preguntar no es errar,\nSi la pregunta no es necia.",210,0,-1,195,"",0,4,"ea",-1,0,-1,0,105,105,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0105-04",15,"Como soy forasterito,\nÁ todo el mundo pregunto:\n¿Quién es esa morenita\nQue está vestida de luto?",210,0,-1,195,"",0,4,"uo",-1,0,-1,0,105,105,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0105-05",15,"¡Tan chiquita y tienes luto!\nDíme, ¿quién te se murió?\nSi te se ha muerto tu amante,\nNo llores, que aquí estoy yo.",210,0,-1,195,"",0,4,"o",2,0,-1,0,105,105,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0105-06",15,"Morenita y enlutada,\n¡Qué bien que te sienta el luto!\nNos casaremos los dos,\nY Dios perdone al difunto.",210,0,-1,195,"",0,4,"uo",-1,0,-1,0,105,105,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0106-01",15,"¿Serrana, quién te camela?\nDíme la verdad, por Dios;\nSi no te camela nadie,\nQuiero camelarte yo.",210,0,-1,195,"",0,4,"o",-1,0,-1,0,106,106,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0106-02",15,"La reina Doña Isabel\nPuso sus tiros en Baza,\nY yo los he puesto en ti,\nPorque me haces mucha gracia.",210,0,-1,195,"",0,4,"aa",-1,0,-1,0,106,106,"","",0,"rm_t2","","",2,0,0,[],"",""],["lafuente_madrid-p0106-03",15,"Gracias á Dios que he llegado\nÁ declarar mi pasion\nÁ una dama tan hermosa\nComo los rayos del sol.",210,0,-1,195,"",0,4,"o",-1,0,-1,0,106,106,"","",0,"rm_t2, palau_cantares","","",10,0,0,[],"",""],["lafuente_madrid-p0106-04",15,"Eres rosita en capullo,\nSin acabar de salir;\nSi todavía no amas,\nÁmame primero á mí.",210,0,-1,195,"",0,4,"i",-1,0,-1,0,106,106,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0106-05",15,"¡Ay, qué ventana tan alta!\n¡Ay, qué balcon tan dorado!\n¡Ay, qué niña tan bonita!\n¿Quién será su enamorado?",210,0,-1,195,"",0,4,"ao",14,0,-1,0,106,106,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0106-06",15,"Ya no me alegran á mi\nLas rosas ni los jardines,\nLo que me alegra es tu cara,\nDime, niña, ¿dónde vives?",210,0,-1,195,"",0,4,"ie",-1,0,-1,0,106,106,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0107-01",15,"Díme, niña, dónde vives,\nQue te quiero conocer,\nY si no tienes amante,\nYo te vengo á pretender.",210,0,-1,195,"",0,4,"e",20,0,-1,0,107,107,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0107-02",15,"El clavel que tú me diste\nEl dia de la Ascension,\nNo fué clavel, sino clavo,\nQue clavó mi corazon.",210,0,-1,195,"",0,4,"o",-1,0,-1,0,107,107,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0107-03",15,"Estudiante quise ser,\nY así que ví tu hermosura,\nÁ los infiernos tiré\nTintero, papel y pluma.",210,0,-1,195,"",0,4,"ua",-1,0,-1,0,107,107,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0107-04",15,"Cuando yo te ví venir,\nLe dije á mi corazon:\n¡Qué bonita piedrecita\nPara dar un tropezon!",210,0,-1,195,"",0,4,"o",31,0,-1,0,107,107,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0107-05",15,"Compañerillá del alma,\nCuando mis ojos te vieron,\nSe me arrancó el corazon\nDe fatigas que me dieron.",210,0,-1,195,"",0,4,"eo",105,0,-1,0,107,107,"","",0,"rm_t2, palau_cantares","","",10,0,0,[],"",""],["lafuente_madrid-p0107-06",15,"Una mañanita, apenas\nSalió el sol por el oriente,\nMe echastes una cadena\nCon los rizos de tu frente.",210,0,-1,195,"",0,4,"ee",15,0,-1,0,107,107,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0107-07",15,"Desde que te ví, morena,\nEn la calle de Mesones,\nMe echastes una cadena\nCon veinte y cinco eslabones.",210,0,-1,195,"",1,4,"oe",34,0,-1,0,107,107,"","",0,"","","",5,0,0,[],"",""],["lafuente_madrid-p0108-01",15,"Desde aquella vez primera\nQue en tu presencia me ví,\nEl corazon, vida y alma\nA tu obediencia rendí.",210,0,-1,195,"",0,4,"i",23,0,-1,0,108,108,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0108-02",15,"Desde que te ví, rubita,\nEse rostro tan sereno,\nLas alas del corazon\nÁ los piés se me cayeron.",210,0,-1,195,"",0,4,"eo",-1,0,-1,0,108,108,"","",0,"rm_t2, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0108-03",15,"Desde que te vi, te amé,\nDesde que te amé, me muero,\nY si me muero por tí,\nDichoso me considero.",210,0,-1,195,"",0,4,"eo",38,0,-1,0,108,108,"","",0,"rm_t2, palau_cantares, fernan_caballero","","",17,0,0,[],"",""],["lafuente_madrid-p0108-04",15,"Desde que te vi, te amé,\nPésame que ha sido tarde,\nQue yo quisiera, bien mio,\nDesde que nací adorarte.",210,0,-1,195,"",0,4,"ae",-1,0,-1,0,108,108,"","",0,"rm_t2, palau_cantares, suspiros_amor","","",17,0,0,[],"",""],["lafuente_madrid-p0108-05",15,"Verte, quererte y amarte,\nTodo ha sido de improviso;\nY no sé qué fué primero,\nAmarte, ó haberte visto.",210,0,-1,195,"",0,4,"io",-1,0,-1,0,108,108,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0108-06",15,"Hermosísima paloma,\nCara de cielo español,\nCon tu mirar retrechero\nMe robas el corazon.",210,0,-1,195,"",0,4,"o",-1,0,-1,0,108,108,"","",0,"rm_t2, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0109-01",15,"Quisiera ser por un rato\nDe tu zarcillo el arete,\nPara decirte al oido\nLo que este corazon siente.",210,0,-1,195,"",0,4,"ee",-1,0,-1,0,109,109,"","",0,"palau_cantares","","",9,0,0,[],"",""],["lafuente_madrid-p0109-02",15,"A la orilla del mar fuí,\nY me senté en la ribera,\nY empecé á considerar:\n¡Si esta niña me quisiera!",210,0,-1,195,"",0,4,"ea",44,0,-1,0,109,109,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0109-03",15,"Maria, no eres María,\nQue eres ramo de virtud,\nÁ tu puerta hay un enfermo,\nDále por Dios la salud.",210,0,-1,195,"",0,4,"u",278,0,-1,0,109,109,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0109-04",15,"Mariquita, tú solita\nReinas en mi corazon.\nSi yo reinara en el tuyo,\n¡Qué dichoso fuera yo!",210,0,-1,195,"",0,4,"o",-1,0,-1,0,109,109,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0109-05",15,"Son tus labios dos cortinas\nDe tafetan carmesi,\nY entre cortina y cortina\nEstoy esperando el sí..",210,0,-1,195,"",3,4,"i",23,0,-1,0,109,109,"","",0,"rm_t2, palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0109-06",15,"Las estrellas y luceros\nTodos se rinden al dia,\nY yo me rindo á tus plantas,\nMorena del alma mia.",210,0,-1,195,"",0,4,"a",0,0,-1,0,109,109,"","",0,"rm_t2, palau_cantares","","",10,0,0,[],"",""],["lafuente_madrid-p0110-01",15,"Las campanas de la iglesia\nEstan doblando por mí:\nDíme, niña, si me quieres,\nResucitaré por tí.",210,0,-1,195,"",0,4,"i",23,0,-1,0,110,110,"","",0,"rm_t2, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0110-02",15,"Bien sabe Dios que te diera\nPor ese color moreno\nLos ojitos de mi cara,\nAunque me quedara ciego.",210,0,-1,195,"",0,4,"eo",-1,0,-1,0,110,110,"","",0,"rm_t2, palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0110-03",15,"Si por hazañas de monta\nSe pudiera usté ganar,\nTomara yo por asalto\nEl peñon de Gibraltar.",210,0,-1,195,"",0,4,"a",21,0,-1,0,110,110,"","",0,"rm_t2","","",4,0,0,[],"",""],["lafuente_madrid-p0110-04",15,"Si el garbo de tu persona\nSe ganara peleando,\nVieras á un hombre en la guerra\nCon una espada en la mano.",210,0,-1,195,"",0,4,"ao",-1,0,-1,0,110,110,"","",0,"rm_t2, fernan_caballero","","",3,0,0,[],"",""],["lafuente_madrid-p0110-05",15,"Serrana, tú eres la lima,\nY tu padre es el limon,\nY tu madre la naranja;\nLa lima la quiero yo.",210,0,-1,195,"",0,4,"o",-1,0,-1,0,110,110,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0110-06",15,"Si supiera, pimpollito,\nQue para mí te criabas,\nTodos los bienes del mundo\nPor tí los abandonara.",210,0,-1,195,"",0,4,"aa",-1,0,-1,0,110,110,"","",0,"rm_t2","","",2,0,0,[],"",""],["lafuente_madrid-p0111-01",15,"Haré por tí una fineza,\nLa que tú por mí no harás;\nQuererte aunque no me quieras,\n¿Qué más quieres? ¿Quieres más?",210,0,-1,195,"",0,4,"a",51,0,-1,0,111,111,"","",0,"rm_t2, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0111-02",15,"Sí supiera que por flores\nTe habia de conseguir,\nTe trajera yo más flores\nQue tienen mayo y abril.",210,0,-1,195,"",0,4,"i",-1,0,-1,0,111,111,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0111-03",15,"Si usté me quisiera á mí,\nComo yo la quiero á usté,\nNos llamaran á los dos\nLa fundacion del querer.",210,0,-1,195,"",0,4,"e",-1,0,-1,0,111,111,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0111-04",15,"Socorro pide en el mar\nEl marinero perdido,\nY yo que estoy en la tierra,\nSocorro, socorro pido.",210,0,-1,195,"",0,4,"io",101,0,-1,0,111,111,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0111-05",15,"Tengo vergüenza, y me callo,\nTengo amor, y no lo digo,\nNo sé cómo te dijera:\n¿Te quieres casar conmigo?",210,0,-1,195,"",0,4,"io",106,0,-1,0,111,111,"","",0,"rm_t2, palau_cantares, fernan_caballero","","",6,0,0,[],"",""],["lafuente_madrid-p0111-06",15,"Estoy adorando á un sol,\nY venerando á una imágen,\nNo siento sino una cosa,\nQue la quiero y no lo sabe.",210,0,-1,195,"",0,4,"ae",-1,0,-1,0,111,111,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0112-01",15,"Mucho tengo que decirte,\nPero lo digo al silencio;\nMucho te digo callando,\nSi tienes entendimiento.",210,0,-1,195,"",0,4,"eo",-1,0,-1,0,112,112,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0112-02",15,"Muchos hay que te dirán:\nSalero, por tí me muero;\n¡Y yo no te digo nada,\nY soy el que más te quiero!",210,0,-1,195,"",0,4,"eo",38,0,-1,0,112,112,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0112-03",15,"Como que sale de tí,\nPregúntale si me quiere,\nY si te dice que no,\nDíle qué motivos tiene.",210,0,-1,195,"",0,4,"ee",-1,0,-1,0,112,112,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0112-04",15,"Á mi triste camarada\nQuiérelo, que bien te quiere,\nDelante de mí ha jurado,\nSerrana, que por tí muere.",210,0,-1,195,"",0,4,"ee",115,0,-1,0,112,112,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0112-05",15,"Ole, con ole, con ole,\nOle de tí para mí,\nQuiéreme, chachita mia,\nComo yo te quiero á tí.",210,0,-1,195,"",0,4,"i",23,0,-1,0,112,112,"","",0,"","","",7,0,0,[],"",""],["lafuente_madrid-p0112-06",15,"Yo no pretendo, serrana,\nQue me quieras á la fuerza;\nPero sí quiero que mires\nLas penillas que me cuestas.",210,0,-1,195,"",0,4,"ea",-1,0,-1,0,112,112,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0113-01",15,"Por fuerza me has de querer,\nPor justicia me has de amar,\nCariño me has de tener,\nÓ el diablo te ha de llevar.",210,0,-1,195,"",1,4,"a",21,0,-1,0,113,113,"","",0,"rm_t2, carrizo_salta, palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0113-02",15,"Toma, niña, esta naranja,\nTe la doy porque te quiero;\nNo la partas con cuchillo,\nQue mi corazon va dentro.",210,0,-1,195,"",0,4,"eo",-1,0,-1,0,113,113,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0113-04",15,"Determínate á quererme,\nNo me seas temerosa;\nDe los riesgos que vinieren\nTe sacaré victoriosa.",210,0,-1,195,"",0,4,"oa",63,0,-1,0,113,113,"","",0,"rm_t2, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0113-05",15,"Palomita amartelada\nDel palomar de Cupido,\nNo sientas levantar vuelo,\nY vénte á volar conmigo.",210,0,-1,195,"",0,4,"io",-1,0,-1,0,113,113,"","",0,"rm_t2, palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0113-06",15,"Ya se acabaron las chanzas,\nY entra la formalidad;\nSi me qu'eres, yo te quiero,\nVamos á ver la verdad.",210,0,-1,195,"",0,4,"a",16,0,-1,0,113,113,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0114-01",15,"Si me quieres, dímelo,\nY si no, dáme veneno;\nNo serás tú la primera (1)\nQue ha dado muerte á su dueño.",210,0,-1,195,"",0,4,"eo",-1,0,-1,0,114,114,"","",0,"","","",17,0,0,[],"",""],["lafuente_madrid-p0114-02",15,"Quiéreme y adórame,\nQue me aborrezcas no quiero,\nY si me has de aborrecer,\nDáme la muerte primero.",210,0,-1,195,"",0,4,"eo",38,0,-1,0,114,114,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0114-03",15,"Desde aquí te estoy mirando\nCara á cara y frente á frente,\n¡Y no te puedo decir\nLo que este corazon siente!",210,0,-1,195,"",0,4,"ee",15,0,-1,0,114,114,"","",0,"palau_cantares","","",20,0,0,[],"",""],["lafuente_madrid-p0114-04",15,"Considera tú, por tí,\nMi alma cómo estaria\nEstando en frente de tí,\nQuise hablarte, y no podia.",210,0,-1,195,"",1,4,"oa",0,0,-1,0,114,114,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0114-05",15,"Hermanita, tú solita\nReinas en mi corazon,\nSi yo en el tuyo reinara,\nMi dicha fuera mayor.",210,0,-1,195,"",0,4,"o",-1,0,-1,0,114,114,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0114-06",15,"¡Válgame Dios de los cielos,\nQué penosillo es mi mal!\nTe estoy queriendo á montones.\nY tú no me quieres náa.",210,0,-1,195,"",5,4,"aa",-1,0,-1,0,114,114,"","",0,"","","",33,0,0,[],"",""],["lafuente_madrid-p0114-07",15,"Viendo que no me querias.\nÁ un arroyuelo bajé;\nOi cantar un gilguero,\nCon su voz me consolé..",210,0,-1,195,"",0,4,"e",77,0,-1,0,114,114,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0115-01",15,"Le dije, gilguero mio.\n¿Qué remedio me darás\nPara una mujer que quiero,\nY no la puedo olvidar?",210,0,-1,195,"",0,4,"a",-1,0,-1,0,115,115,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0115-02",15,"El gilguero me responde:\nQuiérela tu con firmeza,\nPorque al fin ella es mujer,\nY ablandará su dureza.",210,0,-1,195,"",0,4,"ea",108,0,-1,0,115,115,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0115-03",15,"Tú tienes mi corazon,\nEl tuyo me lo has de dar,\nQue el que roba corazones\nCon el suyo ha de pagar.",210,0,-1,195,"",0,4,"a",21,0,-1,0,115,115,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0115-04",15,"Si me quieres, dímelo,\nY si no, dí que me vaya:\nNo me tengas al sereno,\nQue no soy jarro de agua.",210,0,-1,195,"",0,4,"aa",-1,0,-1,0,115,115,"","",0,"","","",17,0,0,[],"",""],["lafuente_madrid-p0115-05",15,"Yo me llamo si hay lugar,\nPariente si hay ocasion,\nPrimo hermano de si puedes,\nAguardando el sí ó el no.",210,0,-1,195,"",0,4,"o",-1,0,-1,0,115,115,"","",0,"rm_t2, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0115-06",15,"Te diera porque me dieras\nDe tu linda boca el sí,\nLas alfombras de Turquía\nY el oro del Potosí",210,0,-1,195,"",0,4,"i",23,0,-1,0,115,115,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0116-01",15,"Tantas letras tiene el si,\nComo letras tiene el no;\nCon el sí me das la vida,\nY la muerte con el no.",210,0,-1,195,"",0,4,"o",-1,0,-1,0,116,116,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0116-02",15,"Yo me muero no sé cómo,\nY mi mal es no sé qué;\nYo sanaré bien sé cuando,\nSi me cura quien yo sé.",210,0,-1,195,"",0,4,"e",77,0,-1,0,116,116,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0116-03",15,"Yo quisiera y no quisiera,\nQue son cosas diferentes:\nQuisiera que me quisieras,\nY quisiera no quererte.",210,0,-1,195,"",0,4,"ee",-1,0,-1,0,116,116,"","",0,"palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0116-04",15,"Una gotera continua\nAblanda un duro peñon:\n¡Y mis suspiros no pueden\nAblandar tu corazon!",210,0,-1,195,"",5,4,"ao",31,0,-1,0,116,116,"","",0,"rm_t2, carrizo_salta, palau_cantares, fernan_caballero","","",6,0,0,[],"",""],["lafuente_madrid-p0116-05",15,"Si me desprecia tu amor,\nDesgraciado viviré,\nY para mayor dolor\nMe verás, y te veré.",210,0,-1,195,"",1,4,"e",77,0,-1,0,116,116,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0116-06",15,"Á la cueva más profunda\nQue tiene el mar en su centr\nMe tengo de ir á vivir,\nSi no logro lo que intento.",210,0,-1,195,"",5,4,"eo",-1,0,-1,0,116,116,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0117-02",15,"No me mires de reojo,\nQue es mirada de traidor;\nMírame así, cara á cara,\nQue es miradita de amor.",210,0,-1,195,"",0,4,"o",72,0,-1,0,117,117,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0117-03",15,"Mi corazon á tus piés\nLo ves, y no lo levantas:\n¡Lástima de corazon,\nQue no duerme, ni descansa!",210,0,-1,195,"",0,4,"aa",-1,0,-1,0,117,117,"","",0,"palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0117-04",15,"Una tórtola te traigo,\nEn el campo la cogi;\nSu madre llora por ella,\nComo lloro yo por ti.",210,0,-1,195,"",0,4,"i",23,0,-1,0,117,117,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0117-05",15,"Detras de ti, dueño mio,\nMis ojos llorando van,\nComo soldado á la guerra\nDetras de su capitan.",210,0,-1,195,"",0,4,"a",147,0,-1,0,117,117,"","",0,"rm_t2","","",2,0,0,[],"",""],["lafuente_madrid-p0117-06",15,"Tienes unos ojos, niña,\nEnseñados á vivir;\nCariñosos para todos,\nY tiranos para mí.",210,0,-1,195,"",0,4,"i",-1,0,-1,0,117,117,"","",0,"rm_t2, palau_cantares","","",13,0,0,[],"",""],["lafuente_madrid-p0118-01",15,"La pena de un ciego es grande\nQue no ve por donde va;\nPero más grande es la mia,\nQue no sé tu voluntad.",210,0,-1,195,"",0,4,"a",-1,0,-1,0,118,118,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0118-02",15,"Las piedras duras quebranto,\nÁ los álamos blandeo,\nA las fieras muevo á llanto;\nY á ti, serrana, no puedo.",210,0,-1,195,"",0,4,"eo",-1,0,-1,0,118,118,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0118-03",15,"Las estrellitas del cielo\nCada cual tiene su nombre;\nLa mia se llama Rita,\nLa llamo, y no me responde.",210,0,-1,195,"",0,4,"oe",-1,0,-1,0,118,118,"","",0,"rm_t2, palau_cantares, fernan_caballero","","",25,0,0,[],"",""],["lafuente_madrid-p0118-04",15,"Contigo me dan matraca.\n¡Ojalá fuera verdad!\nQue nunca los rayos caen\nDonde la tormenta está.",210,0,-1,195,"",0,4,"a",-1,0,-1,0,118,118,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0118-05",15,"Aunque me digas que no,\nÁ tu casa siempre acudo,\nQue al cabo saca limosna\nEl pobre que es importuno.",210,0,-1,195,"",0,4,"uo",-1,0,-1,0,118,118,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0118-06",15,"Los pensamientos me animan\nDe querer á esta serrana:\nSolo llegaré á sentir\nQue me deje con la gana.",210,0,-1,195,"",0,4,"aa",4,0,-1,0,118,118,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0118-07",15,"Si me das un ramillete\nCompuesto con tu cariño,\nYo te daré el corazon,\nLa prenda que más estimo.",210,0,-1,195,"",0,4,"io",-1,0,-1,0,118,118,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0119-01",15,"Te dije si me querias,\nY me dijiste: veré.\nBastante tiempo has tenido\nPara tomar parecer.",210,0,-1,195,"",0,4,"e",-1,0,-1,0,119,119,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0119-02",15,"Ya me despido, mi vida,\nDe tu hermosura y belleza,\nPara vivir ó morir,\nSolo aguardo tu respuesta.",210,0,-1,195,"",0,4,"ea",-1,0,-1,0,119,119,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0119-03",15,"Tú eres el juez de mi causa,\nY yo soy el delincuente;\nAcaba de sentenciar\nSi soy de vida, ó de muerte.",210,0,-1,195,"",0,4,"ee",-1,0,-1,0,119,119,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0119-04",15,"No te quiero dar el si,\nHasta ver cómo te portas,\nQue no muy lejos de aquí,\nMe han dicho que tienes otra",210,0,-1,195,"",0,4,"oa",-1,0,-1,0,119,119,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0119-05",15,"Si supiera que era yo\nLa causa de tu tristeza,\nDejaria padre y madre,\nY te amara con firmeza.",210,0,-1,195,"",0,4,"ea",108,0,-1,0,119,119,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0119-06",15,"Si eres galan dulce y fino\nSiempre firme en la pasion,\nYo hallaré en tí mi destino,\nY te daré el corazon.",210,0,-1,195,"",1,4,"ao",31,0,-1,0,119,119,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0119-07",15,"Amor, si tú fueras firme\nComo la palma en verano,\nYo te entregara las llaves\nDe mi pecho soberano.",210,0,-1,195,"",0,4,"ao",81,0,-1,0,119,119,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0120-01",15,"Hasta la última gota\nDe sangre diera por tí,\nSolo porque te mantengas\nSiempre diciendo que sí.",210,0,-1,195,"",0,4,"i",23,0,-1,0,120,120,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0120-02",15,"Supongo que tú me quieres,\nSiempre constante serás;\n¡Dios nos libre de una vieja\nQue nos comience á enredar!",210,0,-1,195,"",0,4,"a",-1,0,-1,0,120,120,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0120-03",15,"Solo te encargo que guardes\nEl secreto, hasta que quiera\nDarnos el cielo ocasion\nDe lograr la dicha nuestra.",210,0,-1,195,"",0,4,"ea",-1,0,-1,0,120,120,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0120-04",15,"Si viniera san Francisco\nÁ pedirme el corazon,\nÁ el santo se lo negara\nY á una de su nombre no.",210,0,-1,195,"",0,4,"o",-1,0,-1,0,120,120,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0120-05",15,"Si san Rafael me diera\nLicencia para quererte,\nToda mi vida estuviera\nVestida de azul celeste.",210,0,-1,195,"",0,4,"ee",-1,0,-1,0,120,120,"","",0,"palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0120-06",15,"Si tu madre te regaña\nPorque me piensas querer,\nDíle que ya no me quieres,\nY con eso quedas bien.",210,0,-1,195,"",0,4,"e",-1,0,-1,0,120,120,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0121-01",15,"Si tu madre no quisiere\nY la mia fuera necia,\nPara eso hay un vicario\nY una católica Iglesia.",210,0,-1,195,"",0,4,"ea",139,0,-1,0,121,121,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0121-02",15,"Si tu madre no me quiere,\nLe echaré una maldicion:\nQue se le pierda su hija,\nY que me la encuentre yo.",210,0,-1,195,"",0,4,"o",-1,0,-1,0,121,121,"","",0,"palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0121-03",15,"Entra corriendo, y no temas,\nEntra y díselo á mi madre,\nQue no te dirá que no,\nQue mi corazon lo sabe.",210,0,-1,195,"",0,4,"ae",-1,0,-1,0,121,121,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0121-04",15,"Á tu madre se lo dije,\nÁ tu padre no me atrevo,\nEn sabiéndolo tu madre,\nTu padre lo sabrá luego.",210,0,-1,195,"",0,4,"eo",-1,0,-1,0,121,121,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0121-05",15,"¡Válgame Dios! ¿No conoces\nQue en tí tengo mi amor puesto?\n¡Válgame Dios, y qué falto\nEres de conocimiento!",210,0,-1,195,"",0,4,"eo",-1,0,-1,0,121,121,"","",0,"rm_t2","","",4,0,0,[],"",""],["lafuente_madrid-p0121-06",15,"Salero, que me miraste,\nSalero, que te miré,\nSalero, que me gustaste,\nSalero, que te gusté.",210,0,-1,195,"",1,4,"e",77,0,-1,0,121,121,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0122-01",15,"Mi amor me dice de usted,\nY yo lo mismo le digo,\nY en estando los dos solos,\nDe tú por tú nos decimos.",210,0,-1,196,"",0,4,"io",-1,0,-1,0,122,122,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0122-02",15,"Ya no se estila decir:\n¡Viva el oro! viva el oro!\nQue solo se dice ahora:\n¡Viva la prenda que adoro!",210,0,-1,196,"",0,4,"oo",85,0,-1,0,122,122,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0122-03",15,"Viva Cádiz, viva el Puerto,\nViva quien sabe querer,\nViva quien pasa en el mundo\nPenas por una mujer.",210,0,-1,196,"",0,4,"e",20,0,-1,0,122,122,"","",0,"palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0122-04",15,"He estado en el purgatorio,\nY he visto todas las penas,\nY he visto que por querer\nNingun alma se condena.",210,0,-1,196,"",0,4,"ea",-1,0,-1,0,122,122,"","",0,"palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0122-05",15,"Yo quiero bien, y no puedo\nDecir á quién quiero bien;\nTan solo diré que quiero\nSolo por solo querer.",210,0,-1,196,"",0,4,"e",-1,0,-1,0,122,122,"","",0,"rm_t2, preciso_coleccion, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0122-06",15,"Canta tú y cantaré yo,\nPajarito en verde rama,\nCanta tú y cantaré yo,\nCante quien amores ama.",210,0,-1,196,"",1,4,"aa",90,0,-1,0,122,122,"","",0,"rm_t2, palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0123-01",15,"Amores, amores tengo,\nNo los quisiera tener,\nQue un hombre se pone tonto\nEn queriendo á una mujer.",210,0,-1,196,"",0,4,"e",20,0,-1,0,123,123,"","",0,"rm_t2, palau_cantares, fernan_caballero","","",5,0,0,[],"",""],["lafuente_madrid-p0123-02",15,"Si supiera que en el mundo\nSe vendian corazones,\nPara mí comprara uno,\nPorque el mio está en prisiones.",210,0,-1,196,"",0,4,"oe",34,0,-1,0,123,123,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0123-03",15,"Corazon enamorado,\nDime, ¿quién te enamoró?\n-Una niña de quince años,\nQue á diez y seis no llegó.",210,0,-1,196,"",0,4,"o",2,0,-1,0,123,123,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0123-04",15,"Una mora me enamora,\nUna blanca me da pena,\nUna descoloridita\nMe tiene preso en cadena",210,0,-1,196,"",0,4,"ea",59,0,-1,0,123,123,"","",0,"palau_cantares","","",8,0,0,[],"",""],["lafuente_madrid-p0123-05",15,"Una mora me enamora,\nY no es mora de nacion;\nEs mora porque ella mora\nDentro de mi corazon.",210,0,-1,196,"",1,4,"ao",31,0,-1,0,123,123,"","",0,"palau_cantares","","",8,0,0,[],"",""],["lafuente_madrid-p0123-06",15,"Una morena me mata,\nUna rubia me hace el hoyo,\nY una muchacha de á quince\nMe saca del purgatorio.",210,0,-1,196,"",0,4,"oo",-1,0,-1,0,123,123,"","",0,"rm_t2, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0123-07",15,"Dichoso es aquel que tiene\nAmores en el lugar,\nQue yo, que los tengo fuera,\nLos tenga que ir á buscar.",210,0,-1,196,"",0,4,"a",21,0,-1,0,123,123,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0124-01",15,"Mis amores son del campo\nY no vienen al lugar;\nMis suspiros son correos,\nQue unos vienen, y otros van.",210,0,-1,196,"",0,4,"a",-1,0,-1,0,124,124,"","",0,"palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0124-02",15,"Del hueso de una aceituna\nTengo que hacer una nave\nPara que vayan y vengan\nMis suspiros por el aire.",210,0,-1,196,"",0,4,"ae",-1,0,-1,0,124,124,"","",0,"rm_t3, palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0124-03",15,"Las estrellas he contado\nPara ver la que me sigue,\nÁ mi me sigue una estrella\nChiquitita, pero firme.",210,0,-1,196,"",0,4,"ie",-1,0,-1,0,124,124,"","",0,"palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0124-04",15,"Tengo una puñaladita\nQue me la dió una mozuela;\nEn mi vida he visto yo\nPuñalada que más duela.",210,0,-1,196,"",0,4,"ea",167,0,-1,0,124,124,"","",0,"rm_t3","","",6,0,0,[],"",""],["lafuente_madrid-p0124-05",15,"La primer vez que te vi\nMe pareciste lucero,\nY ahora me has parecido\nÁngel bajado del cielo.",210,0,-1,196,"",0,4,"eo",-1,0,-1,0,124,124,"","",0,"","","",7,0,0,[],"",""],["lafuente_madrid-p0124-06",15,"Todas las Marías son\nDulces como el caramelo,\nY yo, como soy goloso,\nPor una de ellas me muero",210,0,-1,196,"",0,4,"eo",-1,0,-1,0,124,124,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0124-07",15,"Tengo una puñaladita\nQue me la dió una mujer;\nEn toda mi vida he visto\nPuñalada más cruel.",210,0,-1,196,"",0,4,"e",-1,0,-1,0,124,124,"","",0,"palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0125-01",15,"María del alma mia,\nIman de mi corazon,\nSerafin de mi albedrio\nY norte de mi pasion.",210,0,-1,196,"",0,4,"ao",31,0,-1,0,125,125,"","",0,"palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0125-02",15,"María, tu enamorado\nRonda la calle á deshora,\nY de ver que tú no sales,\nGotitas de sangre llora.",210,0,-1,196,"",0,4,"oa",107,0,-1,0,125,125,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0125-03",15,"Dáme una rosa, María,\nY cógela con tu mano,\nPorque me han dicho que tienes\nUn rosalito temprano.",210,0,-1,196,"",0,4,"ao",81,0,-1,0,125,125,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0125-04",15,"Bien de mi vida, María,\nConsuelo de mi dolor,\nFlor la más bella y más pura\nDe un fragantisimo olor.",210,0,-1,196,"",0,4,"o",72,0,-1,0,125,125,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0125-05",15,"La sirena de la mar\nEmbelesa á quien la oye;\nTambien me embelesa á mí,\nMaria, tu dulce nombre.",210,0,-1,196,"",0,4,"oe",-1,0,-1,0,125,125,"","",0,"palau_cantares","","",7,0,0,[],"",""],["lafuente_madrid-p0125-06",15,"María, para paloma\nSolo te faltan las alas,\nY á mí para gavilan\nLas patitas coloradas.",210,0,-1,196,"",0,4,"aa",-1,0,-1,0,125,125,"","",0,"rm_t2","","",2,0,0,[],"",""],["lafuente_madrid-p0126-01",15,"Si quereis saber, señores,\nCómo se llama mi majo,\nAcordaos de aquel ángel\nQue tiene al diablo debajo.",210,0,-1,196,"",0,4,"ao",168,0,-1,0,126,126,"","",0,"palau_cantares","","",9,0,0,[],"",""],["lafuente_madrid-p0126-02",15,"Si quereis saber, señores,\nEl nombre de mi querido,\nAcordaos de aquel santo\nQue lleva un ramo florido.",210,0,-1,196,"",0,4,"io",101,0,-1,0,126,126,"","",0,"palau_cantares","","",9,0,0,[],"",""],["lafuente_madrid-p0126-03",15,"Pepe quiero, Pepe adoro,\nPepe tengo en la memoria;\nCada vez que digo ¡Pepe!\nParece que digo ¡gloria!",210,0,-1,196,"",0,4,"oa",126,0,-1,0,126,126,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0126-04",15,"La cartilla del amor\nLa pasé letra por letra,\nY así que llegué á la Pe,\nMe quedé diciendo: ¡Pepa!",210,0,-1,196,"",0,4,"ea",-1,0,-1,0,126,126,"","",0,"","","",5,0,0,[],"",""],["lafuente_madrid-p0126-05",15,"Por una Pepita muero,\nPepita y no de melon,\nQue es Pepita que yo tengo\nDentro de mi corazon.",210,0,-1,196,"",0,4,"o",31,0,-1,0,126,126,"","",0,"rm_t2, palau_cantares, fernan_caballero","","",4,0,0,[],"",""],["lafuente_madrid-p0126-06",15,"Cada vez que digo ramo,\nSe me alegra el corazon,\nPorque Ramona se llama\nLa prenda que adoro yo.",210,0,-1,196,"",0,4,"o",-1,0,-1,0,126,126,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0127-01",15,"Hágame usté un san Joaquin\nQue sea de plata fina,\nQue la prenda que yo adoro\nTambien se llama Joaquina.",210,0,-1,196,"",0,4,"ia",11,0,-1,0,127,127,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0127-02",15,"Tomaré una calavera\nY un Santo Cristo de estambre\nY me iré á hacer penitencia\nCon Mariquita del Cármen.",210,0,-1,196,"",0,4,"ae",-1,0,-1,0,127,127,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0127-03",15,"San Antonio está en el cielo,\nEso no lo ignoro yo,\nY tambien está en la tierra\nLa Antonia que adoro yo.",210,0,-1,196,"",0,4,"o",-1,0,-1,0,127,127,"","",0,"rm_t2, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0127-04",15,"La estampa de san Antonio\nSiempre la llevo en el pecho,\nCuando me acuerdo de Antonio,\nSaco la estampa, y la beso.",210,0,-1,196,"",0,4,"eo",-1,0,-1,0,127,127,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0127-05",15,"Por un Pepe diera un cuarto,\nPor un Francisco un doblon,\nY por un Antonio diera\nAlma, vida y corazon.",210,0,-1,196,"",5,4,"ao",31,0,-1,0,127,127,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0127-06",15,"Mucho quiero á san Francisco,\nPorque tiene cinco llagas;\nPero más te quiero á tí,\nPorque Francisca te llamas.",210,0,-1,196,"",0,4,"aa",-1,0,-1,0,127,127,"","",0,"fernan_caballero, palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0127-07",15,"Mucho quiero á san Vicente,\nPorque es patron de Valencia,\nPero más te quiero á tí,\nPorque te llamas Vicenta.",210,0,-1,196,"",0,4,"ea",-1,0,-1,0,127,127,"","",0,"rm_t2","","",2,0,0,[],"",""],["lafuente_madrid-p0128-01",15,"San Antonio lleva el niño,\nSanto Domingo la estrella,\nY san Juan lleva la palma:\nEntiéndame quien me entienda",210,0,-1,196,"",0,4,"ea",-1,0,-1,0,128,128,"","",0,"fernan_caballero, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0128-02",15,"Eres Ana de las Anas,\nY por ser Ana te atreves\nÁ robar los corazones,\nY el mio preso lo tienes.",210,0,-1,196,"",0,4,"ee",-1,0,-1,0,128,128,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0128-03",15,"Esta mañana temprano\nÁ la huerta fuí por flores,\nMe hice el entretenido\nPor hablar con mi Dolores.",210,0,-1,196,"",0,4,"oe",5,0,-1,0,128,128,"","",0,"","","",4,0,0,[],"",""],["lafuente_madrid-p0128-04",15,"Mi corazon se perdió\nEn un vallado de flores;\nLa dama que se lo halló\nTiene por nombre Dolores.",210,0,-1,196,"",1,4,"oe",5,0,-1,0,128,128,"","",0,"rm_t2","","",2,0,0,[],"",""],["lafuente_madrid-p0128-05",15,"Las vecinas y comadres\nSe juntan á murmurar,\nQue se las come la envidia\nDe ver que me quiere Juan.",210,0,-1,196,"",0,4,"a",-1,0,-1,0,128,128,"","",0,"rm_t2","","",2,0,0,[],"",""],["lafuente_madrid-p0128-06",15,"Por la calle abajo vengo\nRodando como un melon,\nSolo por llegar á verte,\nAngustias del corazon.",210,0,-1,196,"",0,4,"o",31,0,-1,0,128,128,"","",0,"","","",4,0,0,[],"",""],["lafuente_madrid-p0129-01",15,"El nombre de mi moreno\nEso no lo diré yo,\nPorque no quiero que sepan\nDonde tengo mi aficion.",210,0,-1,196,"",0,4,"o",-1,0,-1,0,129,129,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0129-02",15,"Enamoradita estoy,\nPero no lo sabe nadie,\nTengo el amor forastero,\nY no meronda la calle.",210,0,-1,196,"",0,4,"ae",-1,0,-1,0,129,129,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0129-03",15,"Todos me dicen que tengo\nOjitos de religiosa,\nY yo digo que los tengo\nDe casada cariñosa.",210,0,-1,196,"",1,4,"oa",63,0,-1,0,129,129,"","",0,"rm_t2, carrizo_salta, palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0129-04",15,"No soy bonita que asombre,\nNi fea que cause miedo,\nSoy morenita y con gracia,\nY así me quiere mi dueño.",210,0,-1,196,"",0,4,"eo",-1,0,-1,0,129,129,"","",0,"rm_t2","","",3,0,0,[],"",""],["lafuente_madrid-p0129-05",15,"Esta calle está medida\nCon cien varas de liston,\nEn cada esquina una rosa,\nY en medio mi corazon.",210,0,-1,196,"",0,4,"o",31,0,-1,0,129,129,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0129-06",15,"La pimienta es chica y pica,\nY sazona los guisados,\nY tú, como pequeñita,\nHasta el alma me has picado.",210,0,-1,196,"",0,4,"ao",-1,0,-1,0,129,129,"","",0,"palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0129-07",15,"Una rubia como tú\nY de tu propio salero\nMe tiene robada el alma\nY el corazon prisionero.",210,0,-1,196,"",0,4,"eo",38,0,-1,0,129,129,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0130-01",15,"Todos los cuerpos chiquitos\nLos miro con aficion,\nPorque es chiquita la prenda\nQue adora mi corazon.",210,0,-1,196,"",0,4,"o",31,0,-1,0,130,130,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0130-02",15,"Digo que no hay en el mundo\nHombre que mi gusto tenga,\nQue estoy queriendo á una niña\nMás chiquita que una almendra.",210,0,-1,196,"",0,4,"ea",-1,0,-1,0,130,130,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0130-03",15,"Mi amante es alto y delgado,\nCon un corbatin al cuello,\nY soldado miliciano,\n¡Que es la pena que yo tengo!",210,0,-1,196,"",0,4,"eo",-1,0,-1,0,130,130,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0130-04",15,"De lo que viste la noche,\nViste la prenda que estimo;\nLa noche viste de negro,\nY mi prenda de lo mismo.",210,0,-1,196,"",0,4,"io",-1,0,-1,0,130,130,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0130-05",15,"Todas las morenas son\nDulces como el caramelo,\nY yo, como soy goloso,\nPor una morena muero.",210,0,-1,196,"",0,4,"eo",-1,0,-1,0,130,130,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0130-06",15,"Moreno pintan á Cristo,\nMorena á la Magdalena,\nMoreno es el bien que adoro,\n¡Viva la gente morena!",210,0,-1,196,"",0,4,"ea",59,0,-1,0,130,130,"","",0,"palau_cantares, frenk_t1, machado_venezuela, andina_t1, fernan_caballero, huambachano","","",10,0,0,[],"",""],["lafuente_madrid-p0130-07",15,"Moreno es el bien que adoro,\nPor eso lo quiero tanto,\nPorque la tierra morena\nSe señorea en el campo.",210,0,-1,196,"",0,4,"ao",-1,0,-1,0,130,130,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0131-01",15,"Lo moreno lo hizo Dios,\nLo blanco lo hizo un platero,\nViva la gente morena,\nQue yo por moreno muero.",210,0,-1,196,"",0,4,"eo",38,0,-1,0,131,131,"","",0,"machado_venezuela","","",6,0,0,[],"",""],["lafuente_madrid-p0131-02",15,"Morena, morena eres,\nMal haya tu morenura,\nQue me tienes en la cama\nSin frio y con calentura.",210,0,-1,196,"",0,4,"ua",17,0,-1,0,131,131,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0131-03",15,"No desprecies lo moreno\nQue vale más que la plata,\nPorque morenita es\nLa prenda que á mí me mata",210,0,-1,196,"",0,4,"aa",74,0,-1,0,131,131,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0131-04",15,"¡Válgame Dios, qué dolores,\nQué fatigas y qué penas\nPasan á veces los hombres\nPor una cara morena!",210,0,-1,196,"",0,4,"ea",-1,0,-1,0,131,131,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0131-05",15,"En el rio la encontré\nAsentadita en la arena;\nElla no me dijo nada;\nYo le dije: abur, morena.",210,0,-1,196,"",0,4,"ea",59,0,-1,0,131,131,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0131-06",15,"Mira si he corrido tierras\nQue he estado en la Gran Turquía,\nEn ninguna parte vi\nMorena como la mia.",210,0,-1,196,"",0,4,"ia",0,0,-1,0,131,131,"","",0,"rm_t2, palau_cantares","","",15,0,0,[],"",""],["lafuente_madrid-p0131-07",15,"Ay, que se me lleva el aire,\nAy, que el aire se me lleva\nAy, que se me lleva el aire,\nEl aire de mi morena.",210,0,-1,196,"",0,4,"ea",-1,0,-1,0,131,131,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0132-01",15,"Morena, si bien me quieres,\nNo se lo digas á nadie,\nPónte la mano en el pecho,\nDile al corazon que calle.",210,0,-1,196,"",0,4,"ae",-1,0,-1,0,132,132,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0132-02",15,"María, si bien me quieres,\nNo se lo digas al cura,\nQue los secretos de amor\nSon para la sepultura.",210,0,-1,196,"",0,4,"ua",17,0,-1,0,132,132,"","",0,"rm_t2, fernan_caballero","","",3,0,0,[],"",""],["lafuente_madrid-p0132-03",15,"Por tres cosas te he querido:\nPor morena, por alegre,\nY por los ojos dormidos\nQue aprisionado me tienen.",210,0,-1,196,"",0,4,"ee",-1,0,-1,0,132,132,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0132-04",15,"No te quiero por bonita,\nQue bonita no lo eres;\nTe quiero por morenita\nY por la gracia que tienes.",210,0,-1,196,"",0,4,"ee",-1,0,-1,0,132,132,"","",0,"rm_t2, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0132-05",15,"Los mocitos de mi barrio\nDicen que no soy valiente;\nContéstales tú, morena,\nQue me he atrevido á quererte.",210,0,-1,196,"",0,4,"ee",-1,0,-1,0,132,132,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0132-06",15,"Entre Úbeda y Baeza\nHay un molino que muele\nAzúcar, canela y clavo,\nLo que mi morena tiene.",210,0,-1,196,"",0,4,"ee",-1,0,-1,0,132,132,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0132-07",15,"Ojos negros y ojos pardos\nDicen que son los comunes,\nY yo me muero, mi vida,\nPor unos ojos azules.",210,0,-1,196,"",0,4,"ue",-1,0,-1,0,132,132,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0133-01",15,"Ojos de color de cielo,\nAzules comolos mios,\nNo perdais las esperanzas,\nQue yo no las he perdido.",210,0,-1,196,"",0,4,"io",-1,0,-1,0,133,133,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0133-02",15,"Mi madre piensa que estoy\nEstudiando en Salamanca,\nY estoy queriendo á una niña\nComo la nieve de blanca.",210,0,-1,196,"",0,4,"aa",75,0,-1,0,133,133,"","",0,"rm_t2","","",2,0,0,[],"",""],["lafuente_madrid-p0133-03",15,"Á san Nicólas me voy,\nDe san Nicólas me vengo,\nÁ pedirle al santo mio\nPor una novia que tengo.",210,0,-1,196,"",0,4,"eo",124,0,-1,0,133,133,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0133-04",15,"De los juncos sale el agua,\nDe los álamos el viento,\nY del pecho de mi dama\nMemoria y entendimiento.",210,0,-1,196,"",0,4,"eo",94,0,-1,0,133,133,"","",0,"","","",4,0,0,[],"",""],["lafuente_madrid-p0133-05",15,"En la placita del Puente\nHay dós hijas desa madre,\nYo festejo á la pequeña,\nMi compañero á la grande.",210,0,-1,196,"",0,4,"ae",-1,0,-1,0,133,133,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0134-01",15,"San Antonio Portugués,\nDevoto de lo perdido,\nMi amante se perdió anoche,\n¡Buscádmelo, santo mio!",210,0,-1,196,"",0,4,"io",-1,0,-1,0,134,134,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0134-02",15,"Gracias á Dios, madre mia,\nQue ya pareció el perdido;\nNunca se puede perder\nPájaro que tiene nido.",210,0,-1,196,"",0,4,"io",101,0,-1,0,134,134,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0134-03",15,"¡Mira con qué disimulo\nTe vas esa calle arriba,\nSin reparar que te dejas\nÁ una serrana cautiva!",210,0,-1,196,"",0,4,"ia",53,0,-1,0,134,134,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0134-04",15,"La noche que tronó tanto\nFuí á buscar á mi novia,\nPor si se acababa el mundo\nIrme arrimando á la gloria.",210,0,-1,196,"",0,4,"oa",-1,0,-1,0,134,134,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0134-05",15,"Por el camino real\nVa una doncellita triste\nEn busca de sus amores,\nNo hay mata que no registre",210,0,-1,196,"",0,4,"ie",-1,0,-1,0,134,134,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0134-06",15,"Santa Teresita tiene\nLa paloma en el oido,\nY yo quisiera tener\nDe mi amante el apellido.",210,0,-1,196,"",0,4,"io",101,0,-1,0,134,134,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0134-07",15,"Á san José pido el ramo,\nÁ san Francisco el cordon\nÁ santa Rita la espina,\nY á mi amante el corazon.",210,0,-1,196,"",0,4,"o",31,0,-1,0,134,134,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0135-01",15,"Tengo yo una prima hermana\nQue la quiero tanto y cuanto,\nY la he de llevar á Roma\nQue la vea el Padre santo.",210,0,-1,196,"",0,4,"ao",30,0,-1,0,135,135,"","",0,"rm_t2","","",3,0,0,[],"",""],["lafuente_madrid-p0135-02",15,"Sobre gusto no hay disgusto,\nYo quiero á aquel caballero\nQue está vestido de luto,\nQue á mi me gusta lo negro.",210,0,-1,196,"",0,4,"eo",-1,0,-1,0,135,135,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0135-03",15,"Todos me dicen que adoro\nUn clavel de mal color,\nDiga el mundo lo que quiera,\nÁ mí me parece un sol.",210,0,-1,196,"",0,4,"o",-1,0,-1,0,135,135,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0135-04",15,"Todo el mundo me da vaya\nPorque quiero a un hombre chico;\nYo digo que por el aire\nSe compran los abanicos.",210,0,-1,196,"",0,4,"io",-1,0,-1,0,135,135,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0135-05",15,"Me dices que Pedro es feo,\nQue no lo debo querer;\nYo no le miro á la cara,\nSino á su buen proceder.",210,0,-1,196,"",0,4,"e",20,0,-1,0,135,135,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0135-06",15,"Dicen que mi amante es feo;\nPara mí es el sol dorado;\nEn estando yo gustosa,\nTodo el mundo está pagado.",210,0,-1,196,"",0,4,"ao",14,0,-1,0,135,135,"","",0,"rm_t2, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0136-01",15,"Una corona me ponen\nDe plata sobredorada\nCuando me dicen que estoy\nDe mi amante apasionada.",210,0,-1,196,"",0,4,"aa",49,0,-1,0,136,136,"","",0,"rm_t2","","",2,0,0,[],"",""],["lafuente_madrid-p0136-02",15,"El retrato de mi amante\nLo llevo siempre en el pecho,\nCuando no está junto á mí,\nSaco el retrato y lo beso.",210,0,-1,196,"",0,4,"eo",-1,0,-1,0,136,136,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0136-03",15,"Con esa gorrita negra\nMe pareces un ladron,\nQue aunque no robas á nadie,\nMe robas el corazon.",210,0,-1,196,"",0,4,"ao",31,0,-1,0,136,136,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0136-04",15,"Si me volviera paloma,\n¡Qué gustosa que quedara!\nDentro de tu corazon\nAlli mi nido formara.",210,0,-1,196,"",0,4,"aa",57,0,-1,0,136,136,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0136-05",15,"Tengo pleito con mi madre;\nSi no lo gano, me muero,\nPorque quiere que me case\nCon uno que yo no quiero.",210,0,-1,196,"",0,4,"eo",38,0,-1,0,136,136,"","",0,"rm_t3, carrizo_salta, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0136-06",15,"El sentido se me pierde\nCuando con ella platico,\nEn ver que tengo una novia\nCantadora y con buen pico.",210,0,-1,196,"",0,4,"io",141,0,-1,0,136,136,"","",0,"palau_cantares, fernan_caballero","","",3,0,0,[],"",""],["lafuente_madrid-p0136-07",15,"En los jardines del Conde\nDe una maceta cogi\nUn clavel para mi amante,\nY una rosa para mí.",210,0,-1,196,"",0,4,"i",23,0,-1,0,136,136,"","",0,"rm_t2","","",2,0,0,[],"",""],["lafuente_madrid-p0137-01",15,"La primera clavellina\nQue eche mi clavellinero\nSe la tengo de poner\nÁ mi amante en el sombrero.",210,0,-1,196,"",0,4,"eo",38,0,-1,0,137,137,"","",0,"fernan_caballero","","",3,0,0,[],"",""],["lafuente_madrid-p0137-02",15,"Ojos de blanca paloma,\nSerafin idolatrado,\nBenditas tus perfecciones,\nQue me tienes hechizado.",210,0,-1,196,"",0,4,"ao",14,0,-1,0,137,137,"","",0,"rm_t2","","",3,0,0,[],"",""],["lafuente_madrid-p0137-03",15,"Eres el sol que yo adoro,\nY la luna que venero,\nEres cadena de amor\nQue me tiene prisionero.",210,0,-1,196,"",0,4,"eo",38,0,-1,0,137,137,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0137-04",15,"Las estrellas en el cielo\nEstán alumbrando á Dios,\nY tú, como eres mi estrella,\nAlumbras mi corazon.",210,0,-1,196,"",0,4,"o",-1,0,-1,0,137,137,"","",0,"palau_cantares","","",18,0,0,[],"",""],["lafuente_madrid-p0137-05",15,"Toma esa rosa encarnadá,\nAbrela, que está en capullo,\nY verás mi corazon\nAbrazado con el tuyo.",210,0,-1,196,"",0,4,"uo",78,0,-1,0,137,137,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0137-06",15,"Debajo de tu ventana\nMe puse á atar una liga,\nQuien bien ata, mal desata,\nQuien bien quiere, tarde olvida.",210,0,-1,196,"",0,4,"ia",-1,0,-1,0,137,137,"","",0,"palau_cantares","","",29,0,0,[],"",""],["lafuente_madrid-p0137-07",15,"Debajo de tu ventana\nMe puse á contar dinero;\nAsí que llegué á los quince\nMe acordé de tu salero",210,0,-1,196,"",0,4,"eo",38,0,-1,0,137,137,"","",0,"","","",29,0,0,[],"",""],["lafuente_madrid-p0138-01",15,"En los llanos de Motril\nMe puse á echar un cigarro,\nY acordándome de tí,\nSe me cayó de la mano.",210,0,-1,196,"",0,4,"ao",-1,0,-1,0,138,138,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0138-02",15,"Cuando me dieron el tiro\nEn los montes de Llerena,\nCon las ánsias de la muerte\nMe acorde de ti, morena.",210,0,-1,196,"",0,4,"ea",59,0,-1,0,138,138,"","",0,"rm_t2, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0138-03",15,"No sé qué estrella es la tuya\nQue domina sobre mí:\nÁ nadie me he sujetado,\nY me sujeto ahora á ti.",210,0,-1,196,"",0,4,"i",23,0,-1,0,138,138,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0138-04",15,"El dia que me dijiste\nQue era tuya el alma mia,\nLas lágrimas de los ojos\nDe gozo se me caian.",210,0,-1,196,"",0,4,"a",-1,0,-1,0,138,138,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0138-05",15,"Cuando me dijeron que era\nTrabajo en balde el quererto\nMe pareció que llegaba\nEl tránsito de mi muerte.",210,0,-1,196,"",5,4,"ee",-1,0,-1,0,138,138,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0138-06",15,"Acuérdate que te di\nLa llave de mi pechito,\nAlgunos la pretendieron,\nY á tí te la di solito.",210,0,-1,196,"",0,4,"io",119,0,-1,0,138,138,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0138-07",15,"Eché un candado á mi pecho\nDesde que ví tu belleza,\nPorque ninguna éntre en él\nSin que tú le des licencia.",210,0,-1,196,"",0,4,"ea",-1,0,-1,0,138,138,"","",0,"preciso_coleccion","","",2,0,0,[],"",""],["lafuente_madrid-p0139-01",15,"Ahí te entrego el corazon\nCon grillo, cadena y llave,\nÁbrelo y métete dentro,\nQue tú solamente cabes.",210,0,-1,196,"",0,4,"ae",-1,0,-1,0,139,139,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0139-02",15,"Toma allá mi corazon,\nÉchalo en esa candela;\nMas no agarres las cenizas,\nQue te has de quemar con ellas",210,0,-1,196,"",0,4,"ea",-1,0,-1,0,139,139,"","",0,"rm_t2, palau_cantares, fernan_caballero","","",7,0,0,[],"",""],["lafuente_madrid-p0139-03",15,"Ahí tienes mi corazon\nEntre dos flechas metido,\nY para mayor dolor,\nEntre cadenas y grillos.",210,0,-1,196,"",0,4,"io",-1,0,-1,0,139,139,"","",0,"rm_t2, palau_cantares","","",7,0,0,[],"",""],["lafuente_madrid-p0139-04",15,"Entre grillos y cadenas\nTengo yo mi corazon;\nEntre cadenas y grillos,\nComo si fuera un ladron.",210,0,-1,196,"",0,4,"ao",31,0,-1,0,139,139,"","",0,"rm_t2","","",3,0,0,[],"",""],["lafuente_madrid-p0140-01",15,"Dentro de mi pecho tengo\nUna sala de cristal\nY una antesala de oro,\nDonde habita esa deidad.",210,0,-1,196,"",0,4,"a",-1,0,-1,0,140,140,"","",0,"rm_t2, palau_cantares","","",32,0,0,[],"",""],["lafuente_madrid-p0140-02",15,"Desde aquel feliz instante\nQue alma y vida te rendí,\nHice voto de adorarte,\nY no adorar más que á tí",210,0,-1,196,"",0,4,"i",23,0,-1,0,140,140,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0140-03",15,"Esta guitarra que toco\nMe sirva de sepultura,\nSi á otra quiero más que á ti,\nDespues de la Virgen pura.",210,0,-1,196,"",0,4,"ua",17,0,-1,0,140,140,"","",0,"rm_t2, palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0140-04",15,"Entra en mi pecho, y registra\nHasta el último rincon\nY verás como tú reinas\nDonde ninguno reinó",210,0,-1,196,"",0,4,"o",-1,0,-1,0,140,140,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0140-05",15,"Ven acá, luz de mi cara,\nVen aqui, prenda querida,\nEres clavel encarnado,\nPor tí perderé la vida.",210,0,-1,196,"",0,4,"ia",37,0,-1,0,140,140,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0140-06",15,"El corazon te daré,\nTambien te daré la vida;\nEl alma no te la doy,\nPorque no es tuya ni mia.",210,0,-1,196,"",0,4,"ia",-1,0,-1,0,140,140,"","",0,"palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0140-07",15,"Yo te quiero como á Dios,\nY de eso no hay que admirarse;\nÁ Dios como á Dios lo quiero,\nY á tí como fino amante.",210,0,-1,196,"",0,4,"ae",-1,0,-1,0,140,140,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0141-01",15,"Te quiero más que al vivir,\nMás que á la tierra y al cielo.\nMás que á mi padre y mi madre,\nY más quererte no puedo.",210,0,-1,196,"",0,4,"eo",-1,0,-1,0,141,141,"","",0,"rm_t2, palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0141-02",15,"Ni tu padre, ni tu madre,\nNi los que vayan naciendo.\nTe pueden á ti querer,\nComo yo te estoy queriendo.",210,0,-1,196,"",0,4,"eo",52,0,-1,0,141,141,"","",0,"rm_t2, palau_cantares","","",10,0,0,[],"",""],["lafuente_madrid-p0141-03",15,"Ayer en misa mayor\nHice un pecado mortal-\nPuse los ojos en tí,\nY los quité del altar.",210,0,-1,196,"",0,4,"a",-1,0,-1,0,141,141,"","",0,"rm_t2, palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0141-04",15,"Ayer en misa mayor\nMe miraste y te reiste,\nY me pareciste un sol,\nCuando la cara volviste.",210,0,-1,196,"",5,4,"ie",-1,0,-1,0,141,141,"","",0,"rm_t2","","",5,0,0,[],"",""],["lafuente_madrid-p0141-05",15,"Ya te he dicho que no vayas\nÁ misa donde voy yo,\nNi tú rezas, ni yo rezo,\nNi estamos con devocion.",210,0,-1,196,"",0,4,"o",-1,0,-1,0,141,141,"","",0,"palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0141-06",15,"En mi alma manda Dios,\nEn mi persona mis padres,\nPero en cuanto á mi gustito,\nEn ese no manda nadie.",210,0,-1,196,"",0,4,"ae",-1,0,-1,0,141,141,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0141-07",15,"Mi padre y mi madre son\nDueños de lo que yo gano,\nPero de mi personita\nYo soy el único amo.",210,0,-1,196,"",0,4,"ao",-1,0,-1,0,141,142,"","",0,"palau_cantares","","",7,0,0,[],"",""],["lafuente_madrid-p0142-01",15,"Á mi padre y á mi madre\nLos quiero como es debido;\nPero en llegando á mi amante,\nPierdo los cinco sentidos.",210,0,-1,196,"",0,4,"io",-1,0,-1,0,142,142,"","",0,"fernan_caballero","","",4,0,0,[],"",""],["lafuente_madrid-p0142-02",15,"Si me mandaras morir,\nAl momento me muriera.\n¿Qué me mandarás tú á mí,\nSalero, que yo no hiciera?",210,0,-1,196,"",0,4,"ea",44,0,-1,0,142,142,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0143-01",15,"Si la sangre de mis venas\nLa hubieras de menester,\nBien puedes contar con ella,\nQue yo me la sacaré.",210,0,-1,196,"",0,4,"e",-1,0,-1,0,143,143,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0143-02",15,"Al peligro de la muerte\nPor mi querer te has expuesto:\nYo sacaré de mi sangre\nCaldo para tu alimento.",210,0,-1,196,"",0,4,"eo",-1,0,-1,0,143,143,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0143-03",15,"Para rey nació David,\nPara sabio Salomon,\nPara llorar Jeremías,\nY para quererte yo.",210,0,-1,196,"",0,4,"o",-1,0,-1,0,143,143,"","",0,"palau_cantares, machado_venezuela","","",4,0,0,[],"",""],["lafuente_madrid-p0143-04",15,"Yo soñaba que en un trono\nReinando, mi bien, estabas\nSentenciándome á morir\nTan solo porque te amaba.",210,0,-1,196,"",0,4,"aa",-1,0,-1,0,143,143,"","",0,"rm_t2","","",2,0,0,[],"",""],["lafuente_madrid-p0143-05",15,"Si porque te quiero, quieres\nQue yo la muerte reciba,\nCúmplase tu voluntad,\nMuera yo, porque otro viva.",210,0,-1,196,"",0,4,"ia",53,0,-1,0,143,143,"","",0,"palau_cantares","","",11,0,0,[],"",""],["lafuente_madrid-p0143-06",15,"No me mates con cuchillo,\nQue tiene el acero fuerte,\nMátame con un suspiro,\nY te perdono la muerte. (1)",210,0,-1,196,"",0,4,"ee",134,0,-1,0,143,143,"","",0,"","","",7,0,0,[],"",""],["lafuente_madrid-p0144-01",15,"Dicen que me has de matar\nCon un puñal valenciano,\nYo te perdono la muerte\nSi me matas mano á mano.",210,0,-1,196,"",0,4,"ao",81,0,-1,0,144,144,"","",0,"rm_t2","","",3,0,0,[],"",""],["lafuente_madrid-p0144-02",15,"Te quiero más que á la sangre\nQue me corre por las venas,\nY en estando tú delante\nNadie me verá con pena.",210,0,-1,196,"",0,4,"ea",-1,0,-1,0,144,144,"","",0,"rm_t2","","",3,0,0,[],"",""],["lafuente_madrid-p0144-03",15,"Te quiero más que me quieres,\nMis obras te lo dirán;\nY si no, déjalo al tiempo,\nQue es padre de la verdad.",210,0,-1,196,"",0,4,"a",-1,0,-1,0,144,144,"","",0,"rm_t2, palau_cantares","","",8,0,0,[],"",""],["lafuente_madrid-p0144-04",15,"Te quiero más que me quieres,\nEn eso no admitas duda;\nQue una mujer arrestada\nNo teme cosa ninguna.",210,0,-1,196,"",0,4,"ua",-1,0,-1,0,144,144,"","",0,"rm_t2, palau_cantares","","",8,0,0,[],"",""],["lafuente_madrid-p0144-05",15,"Te quiero sin que me quieras,\nQue es verdadero querer;\nQue querer porque nos quieran\nEs querer por interés.",210,0,-1,196,"",0,4,"e",-1,0,-1,0,144,144,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0144-06",15,"La fundacion del querer\nÁ mí me pueden llamar,\nPorque he sido en tus amores\nLa piedra fundamental",210,0,-1,196,"",0,4,"a",-1,0,-1,0,144,144,"","",0,"palau_cantares, preciso_coleccion","","",6,0,0,[],"",""],["lafuente_madrid-p0145-01",15,"Yo no sabia querer,\nDueño de mi corazon,\nY contigo me enseñé;\nYa te puedo dar leccion.",210,0,-1,196,"",0,4,"o",31,0,-1,0,145,145,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0145-02",15,"Si se pudiera escribir\nLo que te quiero, morena,\nNo habria papel bastante\nEn el reino de Valencia.",210,0,-1,196,"",0,4,"ea",-1,0,-1,0,145,145,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0145-03",15,"Si la mar fuera de tinta,\nY de papel fuera el cielo,\nNo te pudiera escribir\nLo mucho que yo te quiero.",210,0,-1,196,"",0,4,"eo",-1,0,-1,0,145,145,"","",0,"palau_cantares","","",11,0,0,[],"",""],["lafuente_madrid-p0145-04",15,"Es tanto lo que te quiero,\nY lo que te quiero es tanto,\nQue el dia que no te veo\nNo le rezo á ningun santo.",210,0,-1,196,"",0,4,"ao",30,0,-1,0,145,145,"","",0,"rm_t2, palau_cantares, fernan_caballero","","",26,0,0,[],"",""],["lafuente_madrid-p0145-05",15,"Es tanto lo que te quiero,\nSerrana, que te matara,\nY con sangre de mis venas\nLuego te resucitara.",210,0,-1,196,"",0,4,"aa",57,0,-1,0,145,145,"","",0,"rm_t2, palau_cantares","","",26,0,0,[],"",""],["lafuente_madrid-p0145-06",15,"Aunque te subas al cielo,\nY te sientes junto á Dios,\nNo te han de querer los santos\nComo á ti te quiero yo.",210,0,-1,196,"",0,4,"o",-1,0,-1,0,145,145,"","",0,"palau_cantares","","",8,0,0,[],"",""],["lafuente_madrid-p0146-01",15,"Si alguna vez se perdiere\nEl retrato de tu cara,\nBúscalo, y lo encontrarás\nEn el fondo de mi alma.",210,0,-1,196,"",0,4,"aa",-1,0,-1,0,146,146,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0146-02",15,"Madrileñita graciosa,\nTe quiero con más calor\nQue número de cesantes\nHay en la Puerta del sol.",210,0,-1,196,"",0,4,"o",-1,0,-1,0,146,146,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0146-03",15,"Mal haya quien no te quiere,\nMal haya quien no te ama,\nMal haya quien no se fuere\nContigo de buena gana.",210,0,-1,196,"",0,4,"aa",-1,0,-1,0,146,146,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0146-04",15,"Es tanto lo que te quiero,\nQue te quisiera llevar\nMetido en la faldriquera\nComo pedazo de pan.",210,0,-1,196,"",0,4,"a",-1,0,-1,0,146,146,"","",0,"","","",26,0,0,[],"",""],["lafuente_madrid-p0146-05",15,"En un relicario hermoso\nTe quisiera retratar,\nPara llevarte en mi pecho\nComo Virgen del Pilar.",210,0,-1,196,"",0,4,"a",21,0,-1,0,146,146,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0146-06",15,"Si el Rey de España me diera\nEl mando de su corona, (1)\nNo lo apreciara yo tanto\nComo aprecio tu persona.",210,0,-1,196,"",0,4,"oa",7,0,-1,0,146,146,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0147-01",15,"Yo no necesito verte\nPara tenerte aficion,\nPues antes de conocerte,\nTe amaba mi corazon.",210,0,-1,196,"",1,4,"ao",31,0,-1,0,147,147,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0147-02",15,"La otra noche en la ventana\nCinco claveles te di,\nY eran los cinco sentidos,\nSerrana, que puse en tí.",210,0,-1,196,"",0,4,"i",23,0,-1,0,147,147,"","",0,"rm_t2","","",2,0,0,[],"",""],["lafuente_madrid-p0147-03",15,"Yo no sé lo que me has dado\nPara que tanto te quiera,\nQue me has hecho que me olvide\nDe mi familia y mi tierra.",210,0,-1,196,"",0,4,"ea",-1,0,-1,0,147,147,"","",0,"rm_t2, palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0147-04",15,"Á esa niña de mis ojos\nNo me la pongas delante,\nQue como la quiero tanto,\nEl corazon se me parte.",210,0,-1,196,"",0,4,"ae",-1,0,-1,0,147,147,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0147-05",15,"Bendita sea la hora\nQue te comencé á querer,\nBenditos tu padre y madre,\nY tú bendita tambien.",210,0,-1,196,"",0,4,"e",-1,0,-1,0,147,147,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0147-06",15,"Como la campana tiene\nFundidos siete metales,\nAsí tengo tu cariño\nEn la masa de la sangre.",210,0,-1,196,"",0,4,"ae",-1,0,-1,0,147,147,"","",0,"palau_cantares, fernan_caballero","","",4,0,0,[],"",""],["lafuente_madrid-p0148-01",15,"De la uva sale el vino,\nDe la aceituna el aceite,\nY de mi pechito sale\nCariño para quererte.",210,0,-1,196,"",0,4,"ee",-1,0,-1,0,148,148,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0148-02",15,"Toma este puñal dorado,\nY ábreme el pecho con él,\nPor el co'or de la sangre\nVerás si te quiero bien.",210,0,-1,196,"",0,4,"e",-1,0,-1,0,148,148,"","",0,"","","",6,0,0,[],"",""],["lafuente_madrid-p0148-03",15,"Quitarme de que te quiera\nEs quitarme la salud,\nPorque á la chita callando\nMi vida la tienes tú.",210,0,-1,196,"",0,4,"u",-1,0,-1,0,148,148,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0148-04",15,"Á la mar van á parar,\nMaría, todos los rios,\nY allí se irán á juntar\nTus amores y los mios.",210,0,-1,196,"",1,4,"o",135,0,-1,0,148,148,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0148-05",15,"Me dices que no me quieres,\nY es mentira, que me engañas;\nQue estoy leyendo en tus ojos\nLo que me quiere tu alma.",210,0,-1,196,"",0,4,"aa",-1,0,-1,0,148,148,"","",0,"rm_t2, palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0148-06",15,"Me preguntas si te quiero,\nEscusada es la pregunta,\nSi sabes que por tu causa\nNinguna mujer me gusta.",210,0,-1,196,"",0,4,"ua",-1,0,-1,0,148,148,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0148-07",15,"Hasta el alma me ha llegado\nLa raiz de tu querer,\nSi no es verdad lo que digo,\nMala puñalá me den.",210,0,-1,196,"",0,4,"e",-1,0,-1,0,148,148,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0149-01",15,"No me hables de comida,\nNi me mientes el comer,\nQue yo estoy alimentado\nTan solo con tu querer.",210,0,-1,196,"",0,4,"e",20,0,-1,0,149,149,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0149-02",15,"Cuando me siento en la mesa,\nDe pensar en tí no como,\nTus palabras me alimentan,\nTus labios me dan socorro.",210,0,-1,196,"",0,4,"oo",-1,0,-1,0,149,149,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0149-03",15,"Con hablarte como y bebo,\nY solo el verte me engorda,\nY el dia que no te veo\nLas fatiguillas me ahogan.",210,0,-1,196,"",0,4,"oa",-1,0,-1,0,149,149,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0149-04",15,"Eres para mí el reposo,\nEres para mí el recreo,\nEres clavel oloroso,\nEres el bien que poseo.",210,0,-1,196,"",1,4,"eo",66,0,-1,0,149,149,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0149-05",15,"Por tí me muero de amor,\nPor tí deliro y suspiro,\nPor ti se abrasa mi pecho,\nPor tí muero, y por tí vivo.",210,0,-1,196,"",0,4,"io",-1,0,-1,0,149,149,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0149-07",15,"Bien sabe Dios que te quiero\nSin interés, ni maldad,\nY por tus buenas partidas\nTe tengo de querer más.",210,0,-1,196,"",0,4,"a",-1,0,-1,0,149,149,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0150-01",15,"Dicen que no nos queremos,\nPorque no nos ven hablar;\nÁ tu corazon y al mio\nSe lo pueden preguntar.",210,0,-1,196,"",0,4,"a",21,0,-1,0,150,150,"","",0,"rm_t2, murciano_antiguo, barcenas_marinera, palau_cantares","","",11,0,0,[],"",""],["lafuente_madrid-p0150-02",15,"Dicen que no nos queremos,\nPorque no nos visitamos;\nLas visitas son de noche\nPara los enamorados.",210,0,-1,196,"",0,4,"ao",-1,0,-1,0,150,150,"","",0,"rm_t2, palau_cantares","","",11,0,0,[],"",""],["lafuente_madrid-p0150-03",15,"Fuentecilla cristalina,\nAgua y rio caudaloso,\nPara dos que bien se quieren,\nLargos caminos son cortos.",210,0,-1,196,"",0,4,"oo",-1,0,-1,0,150,150,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0150-04",15,"Quisiera darte á leer\nEscritos del corazon,\nPara que pudieras ver\nLo fino de mi aficion.",210,0,-1,196,"",1,4,"io",31,0,-1,0,150,150,"","",0,"rm_t2","","",2,0,0,[],"",""],["lafuente_madrid-p0150-05",15,"Fui anoche a Capuchinos,\nÁ rezarle á Cristo un credo;\nPor decir: creo en Dios padre,\nDije: creo en la que quiero.",210,0,-1,196,"",0,4,"eo",-1,0,-1,0,150,150,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0150-06",15,"Este querer tuyo y mio\nParece que está de Dios;\nCuanto más nos lo murmuran,\nMás nos queremos los dos.",210,0,-1,196,"",0,4,"o",87,0,-1,0,150,150,"","",0,"","","",4,0,0,[],"",""],["lafuente_madrid-p0150-07",15,"Mis padres dicen que quiera\nÁ una que tenga doblones;\nYo no quiero la moneda,\nQue en ti he puesto mis amores.",210,0,-1,196,"",0,4,"oe",-1,0,-1,0,150,150,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0151-01",15,"En el mirar solamente\nConocerás que te quiero;\nY tambien conocerás\nQue quiero hablarte, y no puedo.",210,0,-1,196,"",0,4,"eo",-1,0,-1,0,151,151,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0151-02",15,"Tus ojitos y los mios\nSe miran con aficion,\nY parece que se dicen\nLo que siente el corazon.",210,0,-1,196,"",0,4,"o",31,0,-1,0,151,151,"","",0,"rm_t2, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0151-03",15,"Si las piedras de tu calle\nSe volvieran Migueletes,\nTodos los atropellara\nSolo por venir á verte.",210,0,-1,196,"",0,4,"ee",-1,0,-1,0,151,151,"","",0,"rm_t2","","",6,0,0,[],"",""],["lafuente_madrid-p0151-04",15,"Al que me estorba quererte\nEn tu calle mataré;\nSi al salir ves una cruz,\nNo preguntes por quién es.",210,0,-1,196,"",0,4,"e",-1,0,-1,0,151,151,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0151-05",15,"Salero, por tu salero\nÁ la mar me arrojaria;\nPero por otro salero\nEn mi casa me estaria.",210,0,-1,196,"",1,4,"aa",79,0,-1,0,151,151,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0151-06",15,"Si mi madre fuera mora,\nY me pariera en Argel,\nRenegara de Mahoma\nSolo por venirte á ver.",210,0,-1,196,"",0,4,"e",-1,0,-1,0,151,151,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0152-01",15,"Á los moros que te vayas\nÁ renegar de la fé,\nTengo de marchar contigo\nÁ renegar yo tambien.",210,0,-1,196,"",0,4,"e",-1,0,-1,0,152,152,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0152-02",15,"Si supiera que eras diosa,\nY que estabas endiosada,\nTe mandara hacer un templo,\nY como á Dios te adorara.",210,0,-1,196,"",0,4,"aa",-1,0,-1,0,152,152,"","",0,"rm_t2","","",2,0,0,[],"",""],["lafuente_madrid-p0152-03",15,"Más humilde que la tierra\nMe parió mi madre á mi;\nDíme, niña, quien te ofende,\nVerás á un leon reñir.",210,0,-1,196,"",0,4,"i",-1,0,-1,0,152,152,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0152-04",15,"Si supiera ó entendiera\nQue el sol que sale te ofende,\nCon el sol me peleara,\nAunque el sol me diera muerte.",210,0,-1,196,"",0,4,"ee",-1,0,-1,0,152,152,"","",0,"palau_cantares, fernan_caballero","","",11,0,0,[],"",""],["lafuente_madrid-p0152-05",15,"¿Sabes á lo que me atrevo,\nMozuela, por tu querer?\nÁ meterme en los infiernos,\nY hablar con el Lucifer.",210,0,-1,196,"",0,4,"e",20,0,-1,0,152,152,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0152-06",15,"Al infierno que te vayas,\nTengo de irme contigo,\nPorque yendo en tu compaña,\nLlevo la gloria conmigo.",210,0,-1,196,"",0,4,"io",106,0,-1,0,152,152,"","",0,"rm_t2","","",2,0,0,[],"",""],["lafuente_madrid-p0152-07",15,"Mándame, niña, que vaya\nÁ la Gran Constantinopla,\nY verás cómo te traigo\nDel gran turco la corona.",210,0,-1,196,"",0,4,"oa",-1,0,-1,0,152,152,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0153-01",15,"Si yo abiyelara el mando\nQue un divé le dió á la muerte,\nYo quitara de este mundo\nÁ quien me estorba quererte.",210,0,-1,196,"",0,4,"ee",134,0,-1,0,153,153,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0153-02",15,"Desde tu casa á la iglesia\nHe de plantar una parra,\nPara que vayas á misa\nSin darte el sol en la cara.",210,0,-1,196,"",0,4,"aa",-1,0,-1,0,153,153,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0153-03",15,"Tengo que empedrar tu calle\nCon realillos de á ocho cuartos,\nPara que vayas á misa\nSin romperte los zapatos.",210,0,-1,196,"",0,4,"ao",-1,0,-1,0,153,153,"","",0,"rm_t2","","",2,0,0,[],"",""],["lafuente_madrid-p0153-04",15,"Si mi Soledad quisiera\nLe regalara un pañuelo\nCon cuatro borlitas de oro\nY mi corazou en medio.",210,0,-1,196,"",0,4,"eo",-1,0,-1,0,153,153,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0153-05",15,"El verte me da la muerte;\nEl no verte me da vida; (2)\nMás quiero morir y verte,\nQue no verte y tener vida.",210,0,-1,196,"",1,4,"ia",-1,0,-1,0,153,153,"","",0,"","","",5,0,0,[],"",""],["lafuente_madrid-p0153-06",15,"Por donde quiera que voy\nParece que te voy viendo,\nY es la sombra del querer\nQue me viene persiguiendo.",210,0,-1,196,"",0,4,"eo",52,0,-1,0,153,153,"","",0,"rm_t2, carrizo_salta","","",4,0,0,[],"",""],["lafuente_madrid-p0154-01",15,"Se me oprime el corazon\nAl ver tu vestido negro,\nQue la sombra de tu pena\nÁ mí me da sentimiento.",210,0,-1,196,"",0,4,"eo",-1,0,-1,0,154,154,"","",0,"palau_cantares, fernan_caballero","","",4,0,0,[],"",""],["lafuente_madrid-p0154-02",15,"Mal haya la ropa negra\nY el sastre que la cortó;\nQue mi niña tiene luto\nSin haberme muerto yo.",210,0,-1,196,"",0,4,"o",2,0,-1,0,154,154,"","",0,"palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0154-03",15,"Dime por quién tienes luto\nPara echarlo yo tambien;\nPorque tú triste, y yo alegre,\nEso no parece bien.",210,0,-1,196,"",0,4,"e",242,0,-1,0,154,154,"","",0,"rm_t3","","",3,0,0,[],"",""],["lafuente_madrid-p0154-04",15,"Cuando te veo con pena,\nEn mí no cabe alegría,\nPues como te quiero tanto,\nSiento la tuya y la mia.",210,0,-1,196,"",0,4,"ia",0,0,-1,0,154,154,"","",0,"palau_cantares","","",8,0,0,[],"",""],["lafuente_madrid-p0154-05",15,"Si con vender yo mis carnes\nLe diera alivio á tus penas,\nA la voz de un pregonero\nPor las calles las vendiera.",210,0,-1,196,"",0,4,"ea",-1,0,-1,0,154,154,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0154-06",15,"Al que espiró en el madero\nLe pido de corazon\nQue no te cases con nadie\nHasta que me muera yo.",210,0,-1,196,"",0,4,"o",-1,0,-1,0,154,154,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0154-07",15,"Hasta que vea tu fin\nEn lo que viene á parar,\nNi le doy palabra á nadie,\nNi menos me he de casar.",210,0,-1,196,"",0,4,"a",21,0,-1,0,154,154,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0155-01",15,"A Jesus triste le rezo,\n¿Y sabes lo que le pido?\nQue el dia que tú te mueras\nTambien me muera contigo.",210,0,-1,196,"",0,4,"io",-1,0,-1,0,155,155,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0155-02",15,"Dueño mio, si te vieres\nEn la presencia de Dios,\nLe pedirás que me muera,\nQue sin tí no vivo yo.",210,0,-1,196,"",0,4,"o",-1,0,-1,0,155,155,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0155-03",15,"El dia que tú naciste,\nAquel dia nací yo;\nEl dia que tú te mueras\nNos morirémos los dos.",210,0,-1,196,"",0,4,"o",-1,0,-1,0,155,155,"","",0,"palau_cantares","","",16,0,0,[],"",""],["lafuente_madrid-p0155-04",15,"Si con el mirar te ofendo,\nY con el hablar te agravio,\nYo me vendaré los ojos,\nY me coseré los labios.",210,0,-1,196,"",0,4,"ao",-1,0,-1,0,155,155,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0155-05",15,"Si con el mirar te ofendo,\nMe lo mandas á decir,\nY me vendaré los ojos,\nPor no darte que sentir.",210,0,-1,196,"",0,4,"i",157,0,-1,0,155,155,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0155-06",15,"Cuando te encuentro en la calle\nLa sangre se me rebota,\nY se me quiere salir\nEl corazon por la boca.",210,0,-1,196,"",0,4,"oa",-1,0,-1,0,155,155,"","",0,"rm_t2, palau_cantares","","",13,0,0,[],"",""],["lafuente_madrid-p0155-07",15,"Cuando te encuentro en la calle\nY no me dices adios,\nNi las ánimas benditas\nPenan tanto como yo.",210,0,-1,196,"",0,4,"o",-1,0,-1,0,155,155,"","",0,"palau_cantares","","",13,0,0,[],"",""],["lafuente_madrid-p0156-01",15,"Si te veo, me aturrullo,\nY si en la calle te encuentro,\nHace un movimiento el alma\nPara salirse del cuerpo.",210,0,-1,196,"",0,4,"eo",-1,0,-1,0,156,156,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0156-02",15,"Cuando te encuentro en la calle\nEl sentido se me quita,\nY me agarro á las paredes\nHasta perderte de vista.",210,0,-1,196,"",0,4,"ia",-1,0,-1,0,156,156,"","",0,"palau_cantares","","",13,0,0,[],"",""],["lafuente_madrid-p0156-03",15,"Si me quieres ver morir\nSin calentura y sin mal,\nNo tienes más que decir\nQue me quieres olvidar.",210,0,-1,196,"",0,4,"a",-1,0,-1,0,156,156,"","",0,"rm_t2, palau_cantares","","",7,0,0,[],"",""],["lafuente_madrid-p0156-04",15,"Anoche soñé un ensueño,\nY en el ensueño soñé\nQue me habias olvidado.\n¡Si vieras cuánto lloré!",210,0,-1,196,"",0,4,"e",77,0,-1,0,156,156,"","",0,"palau_cantares","","",7,0,0,[],"",""],["lafuente_madrid-p0156-05",15,"Anoche, mi bien, soñé;\nSoñé que contigo estaba.\nSoñaba el ciego que via,\nY era que lo deseaba.",210,0,-1,196,"",0,4,"aa",28,0,-1,0,156,156,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0156-06",15,"Compañerita del alma,\nEl sueño no me alimenta,\nDuermo soñando contigo,\nY tu querer me despierta.",210,0,-1,196,"",0,4,"ea",-1,0,-1,0,156,156,"","",0,"palau_cantares","","",20,0,0,[],"",""],["lafuente_madrid-p0157-01",15,"Tu padre y tu madre dicen\nQue no los dejo dormir;\nDentro de la casa tienen\nLa que no me deja á mí.",210,0,-1,196,"",0,4,"i",-1,0,-1,0,157,157,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0157-02",15,"Pensando en tí, me dormi,\nBello clavel encarnado;\nDespierto, y me hallo sin tí,\n¡Qué sueño tan desgraciado!",210,0,-1,196,"",1,4,"ao",14,0,-1,0,157,157,"","",0,"","","",9,0,0,[],"",""],["lafuente_madrid-p0157-03",15,"Estoy durmiendo y soñando\nQue estás á la vera mia;\nDespierto, y me hallo sin ti,\nVuelvo á la misma fatiga.",210,0,-1,196,"",0,4,"ia",-1,0,-1,0,157,157,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0157-04",15,"Jamas pensé, vida mia,\nQuererte como te quiero;\nCuando me voy á acostar\nNo puedo cuajar el sueño.",210,0,-1,196,"",0,4,"eo",-1,0,-1,0,157,157,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0157-05",15,"Las campanas de maitines\nTodas las noches las cuento,\nY pensando en tu querer\nPierdo las horas del sueño.",210,0,-1,196,"",0,4,"eo",-1,0,-1,0,157,157,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0157-06",15,"¿Hasta cuando, dueño mio,\nMe tengo de estar así,\nLas horitas de la noche\nPasándolas sin dormir?",210,0,-1,196,"",0,4,"i",-1,0,-1,0,157,157,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0158-01",15,"El leon con ser leon\nDicen que lo rinde el sueño,\nYo, que soy criatura humana,\nDe pensar en tí, no duermo.",210,0,-1,196,"",0,4,"eo",-1,0,-1,0,158,158,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0158-02a",15,"Si lo que de noche sueño,\nDe dia lo ejecutara,\nA la casa de los locos\nDe seguro me llevaran.",210,0,-1,196,"",0,4,"aa",-1,0,-1,0,158,158,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0158-02b",15,"Cuando me ha'lo solita\nLloro mi solicitud;\nTodas las sombras que veo\nMe parece que eres tú.",210,0,-1,196,"",0,4,"u",-1,0,-1,0,158,158,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0158-03",15,"Ni comiendo, ni bebiendo,\nNi andando, ni trabajando,\nTiene mi penita alivio,\nSino que te estoy mirando",210,0,-1,196,"",0,4,"ao",33,0,-1,0,158,158,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0158-04",15,"Las fatigas de un enfermo\nCuando está para morir,\nSon las que paso, bien mio,\nCuando me acuerdo de ti.",210,0,-1,196,"",0,4,"i",-1,0,-1,0,158,158,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0158-05",15,"En un castillo me vi\nPrisionero entre cadenas,\nY acordándome de tí\nSe me quitaban las penas.",210,0,-1,196,"",1,4,"ea",62,0,-1,0,158,158,"","",0,"rm_t2, palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0159-01",15,"Cuando yo estaba en prisiones\nEn lo que me divertia\nEra en escribir tu nombre\nEn los ladrillos que habia.",210,0,-1,196,"",0,4,"ia",0,0,-1,0,159,159,"","",0,"palau_cantares","","",10,0,0,[],"",""],["lafuente_madrid-p0159-02",15,"Cuando voy á la besana,\nLlevo los bueyes arando,\nCon la mano en la mancéra,\nY en tí, serrana, pensando.",210,0,-1,196,"",0,4,"ao",33,0,-1,0,159,159,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0159-04",15,"Al que se muere lo entierran,\nDice un antiguo refran;\nA mí, que por tí me muero,\n¿No me vendrán á enterrar?",210,0,-1,196,"",0,4,"a",-1,0,-1,0,159,159,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0159-05",15,"Aunque padezca fatigas,\nY sienta mi corazon,\nMás quiero en ti la esperanza,\nQue en otra la posesion.",210,0,-1,196,"",0,4,"o",31,0,-1,0,159,159,"","",0,"palau_cantares, preciso_coleccion","","",3,0,0,[],"",""],["lafuente_madrid-p0159-06",15,"Si las estrellas del cielo\nTodas se volvieran lanzas\nPunta abajo para el suelo,\nNo pierdo las esperanzas.",210,0,-1,196,"",1,4,"aa",110,0,-1,0,159,159,"","",0,"palau_cantares, fernan_caballero","","",3,0,0,[],"",""],["lafuente_madrid-p0160-01",15,"Serrana, si te murieras.....\n(Pero más vale que no),\nLas serranas se asombraran\nDel luto que echara yo.",210,0,-1,196,"",0,4,"o",-1,0,-1,0,160,160,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0160-02",15,"Permita el cielo que un rayo....\nPero no..... ¡Detente, lengua\nQue no quiero que por mí\nDaño á mi amante le venga.",210,0,-1,196,"",0,4,"ea",-1,0,-1,0,160,160,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0160-03",15,"¡Qué triste que va la luna\nCuando no lleva lucero!\nAsí está mi corazon\nEl dia que no te veo.",210,0,-1,196,"",0,4,"eo",-1,0,-1,0,160,160,"","",0,"rm_t2, palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0160-04",15,"Aquel lucero que sale\nPor detras de las cabrillas\nEs el que á mi me acompaña\nCuando voy á verte, niña.",210,0,-1,196,"",0,4,"ia",-1,0,-1,0,160,160,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0160-05",15,"No sé qué para mí tienes,\nQue cada vez que te veo\nMe quedo como San Juan,\nSeñalando con el dedo.",210,0,-1,196,"",0,4,"eo",-1,0,-1,0,160,160,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0160-06",15,"Cada vez que paso y miro\nLos umbrales de tu puerta,\nMe arrodillo y los venero,\nComo si fuera la iglesia.",210,0,-1,196,"",0,4,"ea",-1,0,-1,0,160,160,"","",0,"rm_t2","","",25,0,0,[],"",""],["lafuente_madrid-p0160-07",15,"Cuando por tu puerta paso,\nY te veo en la ventana,\nSe me alegra el corazon\nPara toda la semana.",210,0,-1,196,"",0,4,"aa",4,0,-1,0,160,160,"","",0,"palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0161-01",15,"Quisiera verte, bien mio,\nTreinta dias cada mes,\nSiete dias en semana,\nCada minuto una vez.",210,0,-1,196,"",0,4,"e",150,0,-1,0,161,161,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0161-02",15,"Fatigas me dan de muerte\nEn no viéndote en un dia;\nSi no te viera en un año,\nPienso que me moriria.",210,0,-1,196,"",0,4,"ia",0,0,-1,0,161,161,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0161-03",15,"El dia que no te veo\nTengo yo mi corazon\nComo un jardin sin recreo,\nComo una flor sin olor.",210,0,-1,196,"",0,4,"o",-1,0,-1,0,161,161,"","",0,"rm_t2, palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0161-04",15,"¡Válgame Dios, Padre Adan,\nLo que quiero á esta mujer!\nEl dia que no la veo\nLa retrato en la pared.",210,0,-1,196,"",0,4,"e",-1,0,-1,0,161,161,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0161-05",15,"Amarillo sale el sol\nEl dia que no te veo;\nNi mis ojos tienen luz,\nNi mi corazon consuelo.",210,0,-1,196,"",0,4,"eo",-1,0,-1,0,161,161,"","",0,"rm_t2","","",2,0,0,[],"",""],["lafuente_madrid-p0161-06",15,"Como barquillo en el mar,\nQue va pegando vaivenes,\nSe queda mi corazon,\nCuando te vas y no vienes.",210,0,-1,196,"",0,4,"ee",120,0,-1,0,161,161,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0162-01",15,"Todas las enfermedades\nSe me curan si me miras,\nSin duda tus ojos son\nBálsamo de mis heridas,",210,0,-1,196,"",0,4,"ia",-1,0,-1,0,162,162,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0162-02",15,"Tendido sobre una estera,\nVestido con la mortaja,\nSi te viera entrar á ti,\nDe fé que resucitaba.",210,0,-1,196,"",0,4,"aa",-1,0,-1,0,162,162,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0162-03",15,"Más quisiera verte, niña,\nEmbarcadita en la mar,\nQue no verte en la ventana\nPara no poderte hablar.",210,0,-1,196,"",0,4,"a",21,0,-1,0,162,162,"","",0,"rm_t2","","",6,0,0,[],"",""],["lafuente_madrid-p0162-04",15,"Es preciso que soñando\nTe hable con el deseo,\nMis fatigas son tan grandes\nQue estoy durmiendo y te veo.",210,0,-1,196,"",0,4,"eo",66,0,-1,0,162,162,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0162-05",15,"Todas las horas del dia\nLe estoy pidiendo á Jesus\nQue por su pasion y muerte\nMe lleve donde estás tú.",210,0,-1,196,"",0,4,"u",-1,0,-1,0,162,162,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0162-06",15,"Tengo yo mi corazon\nMás negro que el terciopelo\nDe ver que no puedo hablarte.\nTodas las horas que quiero.",210,0,-1,196,"",0,4,"eo",-1,0,-1,0,162,162,"","",0,"rm_t2, palau_cantares","","",14,0,0,[],"",""],["lafuente_madrid-p0163-01",15,"Tanto me alimenta el verte\nCómo el agua al macetero,\nComo la ropa al desnudo\nY la salud al enfermo.",210,0,-1,196,"",0,4,"eo",-1,0,-1,0,163,163,"","",0,"rm_t2","","",2,0,0,[],"",""],["lafuente_madrid-p0163-02",15,"¿Para qué me diste ojos,\nSeñora Santa Lucía,\nSi no veo lo que quiero\nTodas las horas del dia?",210,0,-1,196,"",0,4,"ia",0,0,-1,0,163,163,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0163-03",15,"Si me acuesto, pienso en tí;\nSi me levanto, en tí pienso;\nTe quisiera preguntar\nSi te pasa á ti lo mesmo.",210,0,-1,196,"",0,4,"eo",-1,0,-1,0,163,163,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0163-04",15,"Por tus quereles, serrana,\nMe voy quedando en la espina;\nEstoy que me lleva el viento\nAl revolver de una esquina.",210,0,-1,196,"",0,4,"ia",11,0,-1,0,163,163,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0163-05",15,"Si me encuentras en la calle\nNo me debes conocer,\nQue estoy hecho un esqueleto\nDe pensar en tu querer.",210,0,-1,196,"",0,4,"e",20,0,-1,0,163,163,"","",0,"rm_t3, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0163-06",15,"Como el panal de la cera\nTengo yo mi propia carne,\nQue me ha puesto tu querer\nQue no me conoce nadie.",210,0,-1,196,"",0,4,"ae",-1,0,-1,0,163,163,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0163-07",15,"Suspiritos menuditos\nSalen de mi pecho triste,\nY se meten en el tuyo,\nComo granitos de alpiste.",210,0,-1,196,"",0,4,"ie",153,0,-1,0,163,163,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0164-01",15,"Sombra le pedí á una fuente,\nAgua le pedí á un olivo;\nQue me ha puesto tu querer\nQue no sé lo que me digo.",210,0,-1,196,"",0,4,"io",-1,0,-1,0,164,164,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0164-02",15,"Suspiros del corazon\nSalen de mi pecho ardiendo,\nY se van á aposentar\nDonde está mi amor durmiendo.",210,0,-1,196,"",0,4,"eo",52,0,-1,0,164,164,"","",0,"rm_t2, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0164-03",15,"De tu corazon al mio\nHay una larga cadena\nToda llena de suspiros,\nDe suspiros toda llena.",210,0,-1,196,"",0,4,"ea",59,0,-1,0,164,164,"","",0,"rm_t2, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0164-04",15,"Suspiros, salid, salid,\nY trasminad las paredes,\nY mirad si está dormida\nLa reina de las mujeres.",210,0,-1,196,"",0,4,"ee",-1,0,-1,0,164,164,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0164-05",15,"Si á media noche sintieres\nEn tu cara un aire frio,\nNo te muestres enojada,\nQue son los suspiros mios.",210,0,-1,196,"",0,4,"o",-1,0,-1,0,164,164,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0164-06",15,"Vuela, pensamiento mio,\nAl lecho de mis amores,\nY la estancia de su dueño\nPerfúmala con olores.",210,0,-1,196,"",0,4,"oe",5,0,-1,0,164,164,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0165-01",15,"Sin vida tu amor me tiene,\nSin salud voy por la tierra:\nCuando la muerte me busque,\nSin duda que no me encuentra.",210,0,-1,196,"",0,4,"ea",-1,0,-1,0,165,165,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0165-02",15,"Por ti no tengo camisa,\nPor ti no tengo capote,\nPor ti no he cantado misa,\nPor ti no soy sacerdote.",210,0,-1,196,"",1,4,"oe",292,0,-1,0,165,165,"","",0,"rm_t4, palau_cantares, frenk_t2","","",4,0,0,[],"",""],["lafuente_madrid-p0165-03",15,"Nacen en el campo flores,\nNace la perla en el mar,\nY tú naciste, bien mio,\nPara hacerme á mí penar.",210,0,-1,196,"",0,4,"a",21,0,-1,0,165,165,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0165-04",15,"Tengo pena si te veo,\nY si no te veo, doble;\nNo tengo más alegría\nQue cuando escucho tu nombre",210,0,-1,196,"",0,4,"oe",-1,0,-1,0,165,165,"","",0,"rm_t2, palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0165-05",15,"Al Peñon de la Gomera\nTu madre quiere llevarme\nPorque te quiero de veras.\n¡Vaya unos motivos grandes!",210,0,-1,196,"",0,4,"ae",-1,0,-1,0,165,165,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0165-06",15,"Más veces de ti me acuerdo\nQue hojas tienen los laureles,\nY botes un boticario,\nY un escribano papeles.",210,0,-1,196,"",0,4,"ee",97,0,-1,0,165,165,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0166-01",15,"Los presos cuentan los dias,\nLos presidiarios los años,\nY yo cuento, vida mia,\nLas horas que no te hablo.",210,0,-1,196,"",0,4,"ao",-1,0,-1,0,166,166,"","",0,"rm_t2","","",5,0,0,[],"",""],["lafuente_madrid-p0166-02",15,"Las estrellitas del cielo\nSe visten de colorado,\nY yo me visto de negro,\nPorque mi amante es soldado.",210,0,-1,196,"",0,4,"ao",14,0,-1,0,166,166,"","",0,"rm_t3","","",25,0,0,[],"",""],["lafuente_madrid-p0166-03",15,"Bien sabe Dios que te diera\nLo que merecido tienes:\nUna corona imperial\nQue coronara tus sienes.",210,0,-1,196,"",0,4,"ee",120,0,-1,0,166,166,"","",0,"palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0166-04",15,"Si sabes los mandamientos,\nEl primero es el amar;\nEs tanto lo que te quiero,\nQue no te puedo olvidar.",210,0,-1,196,"",0,4,"a",21,0,-1,0,166,166,"","",0,"rm_t2, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0166-05",15,"«Los sacramentos son siete,\nY te los vengo á explicar:\nEscucha con atencion,\nSi me quieres escuchar.",210,0,-1,196,"",0,4,"a",21,0,-1,0,166,166,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0166-06",15,"De todos los sacramentos\nEl primero es el bautismo.\nYa sé que estás bautizada,\nPodrás casarte conmigo.",210,0,-1,196,"",0,4,"io",-1,0,-1,0,166,166,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0166-07",15,"Segundo, confirmacion.\nTe ha confirmado el obispo,\nY cada vez que te veo,\nYo en tu querer me confirmo.",210,0,-1,196,"",0,4,"io",-1,0,-1,0,166,166,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0167-01",15,"El tercero, penitencia.\nY por ella el otro dia\nMe han mandado que te olvide,\nY no he podido cumplirla.",210,0,-1,196,"",0,4,"ia",-1,0,-1,0,167,167,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0167-02",15,"El cuarto, la comunion.\nRecibela con anhelo;\nSi estás en gracia de Dios,\nSeguro tienes el cielo.",210,0,-1,196,"",0,4,"eo",10,0,-1,0,167,167,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0167-03",15,"El quinto, la extrema-uncion.\nExtremo es lo que te quiero,\nY á la hora de mi muerte\nSerás mi solo consuelo.",210,0,-1,196,"",0,4,"eo",-1,0,-1,0,167,167,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0167-04",15,"El sexto, el sacerdotal.\nSacerdote no he de ser;\nHasta la hora de mi muerte\nSeré firme en tu querer.",210,0,-1,196,"",0,4,"e",20,0,-1,0,167,167,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0167-05",15,"El séptimo, matrimonio.\nEso vengo yo á buscar,\nY aunque tu padre no quiera,\nContigo me he de casar.» (1)",210,0,-1,196,"",0,4,"a",21,0,-1,0,167,167,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0167-06",15,"Quiéreme poquito á poco,\nSalero, no te apresures;\nQue este cariñito nuestro,\nSalero, quiero que dure.",210,0,-1,196,"",0,4,"ue",-1,0,-1,0,167,167,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0168-01",15,"Hágame usté unos zapatos\nCon el tacon que levante;\nQue soy chiquita, y no alcanzo\nA los brazos de mi amante.",210,0,-1,196,"",0,4,"ae",47,0,-1,0,168,168,"","",0,"rm_t2, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0168-02",15,"Envidia tengo á la tierra,\nY tambien á los gusanos\nQue te tienen de comer\nEse cuerpo tan gitano.",210,0,-1,196,"",0,4,"ao",-1,0,-1,0,168,168,"","",0,"fernan_caballero","","",6,0,0,[],"",""],["lafuente_madrid-p0168-03",15,"Quisiera ser poderoso,\nY mantenerte en el aire,\nY ya que yo no te gozo,\nQue no te gozara nadie.",210,0,-1,196,"",0,4,"ae",-1,0,-1,0,168,168,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0168-04",15,"Si yo fuera basilisco,\nCon la vista te matara,\nY te sacara del mundo,\nPorque nadie te gozara.",210,0,-1,196,"",0,4,"aa",57,0,-1,0,168,168,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0168-05",15,"Cuatro esquinas tiene el horno,\nCuatro la panadería,\nCuatro pilares la cama\nDonde duerme el alma mía.",210,0,-1,196,"",0,4,"ia",0,0,-1,0,168,168,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0168-06",15,"Las cortinas de tu cama\nSon de seda y algodon,\nY entre cortina y cortina\nDescansa mi corazon.",210,0,-1,196,"",3,4,"ao",31,0,-1,0,168,168,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0168-07",15,"Átame con un cabello\nÁ los bancos de tu cama,\nQue aunque el cabello se rompa\nSeguro está que me vaya.",210,0,-1,196,"",0,4,"aa",-1,0,-1,0,168,168,"","",0,"rm_t2, palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0169-01",15,"Toda mi vida estuviera\nPreso en la cárcel de amor,\nSiendo tú la carcelera,\nY yo el alguacil mayor.",210,0,-1,196,"",1,4,"o",72,0,-1,0,169,169,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0169-02",15,"Una alcarraza en tu casa,\nSeñora, quisiera ser,\nPara besarte los labios\nCuando fueras á beber.",210,0,-1,196,"",0,4,"e",20,0,-1,0,169,169,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0169-03",15,"Si tu casa fuera cárcel,\nY tu cuarto calabozo,\nY tus brazos la cadena,\nYo prisionero gustoso.",210,0,-1,196,"",0,4,"oo",160,0,-1,0,169,169,"","",0,"rm_t2, palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0169-04",15,"Si tu casa fuera iglesia,\nY tu cuarto fuera altar,\nY tu cama sepultura,\nVivo me fuera á enterrar.",210,0,-1,196,"",0,4,"a",21,0,-1,0,169,169,"","",0,"carrizo_salta, palau_cantares, ortiz_ecuador","","",4,0,0,[],"",""],["lafuente_madrid-p0169-05",15,"¡Quién tuviera un cordon de oro\nTan largo como esta calle,\nPara sacar á una niña\nDel dominio de su padre!",210,0,-1,196,"",0,4,"ae",-1,0,-1,0,169,169,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0169-06",15,"Envidia le tengo al oro\nQue tienes en los zarcillos,\nPorque siempre estan tocando\nEsos divinos carrillos.",210,0,-1,196,"",0,4,"io",161,0,-1,0,169,169,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0169-07",15,"¡Ay, quién fuera clavo de oro\nDonde cuelgas el candil,\nPara ver tus dos ojitos\nCuando te vas á dormir!",210,0,-1,196,"",0,4,"i",-1,0,-1,0,169,170,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0170-01",15,"¡Qué consuelo y qué dulzura\nSerá tenerte á mi lado!\n¿Cuándo llegará ese dia\nPara mi tan deseado?",210,0,-1,196,"",0,4,"ao",14,0,-1,0,170,170,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0170-02",15,"¿Cuándo querrá Dios del cielo,\nY la Virgen de allá arriba,\nQue te coja de la mano,\nY diga: esta prenda es mia?",210,0,-1,196,"",0,4,"ia",-1,0,-1,0,170,170,"","",0,"","","",11,0,0,[],"",""],["lafuente_madrid-p0170-03",15,"¿Cuando llegará aquel dia\nY aquella feliz mañana,\nQue nos lleven á los dos\nEl chocolate á la cama?",210,0,-1,196,"",0,4,"aa",-1,0,-1,0,170,170,"","",0,"rm_t2","","",2,0,0,[],"",""],["lafuente_madrid-p0170-04",15,"Como triste mariposa\nCamino de noche y dia,\nHasta que los cielos quieran\nQue te publiquen por mia.",210,0,-1,196,"",0,4,"a",0,0,-1,0,170,170,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0171-01",15,"¿Cuándo querrá Dios del cielo\nQue yo te encuentre en la calle,\nY te diga: mira, oyes,\nDónde pusiste la llave?",210,0,-1,196,"",0,4,"ae",-1,0,-1,0,171,171,"","",0,"","","",11,0,0,[],"",""],["lafuente_madrid-p0171-02",15,"En el hoyo de tu barba\nQuisiera verme dormido,\nPara ver de cuando en cuando\nSi dabas algun suspiro.",210,0,-1,196,"",0,4,"io",-1,0,-1,0,171,171,"","",0,"rm_t2","","",7,0,0,[],"",""],["lafuente_madrid-p0171-03",15,"Tengo yo mi corazon\nHechito cuatro pedazos;\nPero me queda el consuelo\nQue he de morir en tus brazos.",210,0,-1,196,"",0,4,"ao",132,0,-1,0,171,171,"","",0,"rm_t2, palau_cantares","","",14,0,0,[],"",""],["lafuente_madrid-p0171-04",15,"¿Sabes por qué no me caso\nConsiderándote á tí?\nPorque en viéndome en tus brazos\nPienso que me he de morir.",210,0,-1,196,"",0,4,"i",-1,0,-1,0,171,171,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0171-05",15,"Mirando estoy desde aquí\nLa que tiene que ser mia,\nLa que tiene que juntar\nSu carita con la mia.",210,0,-1,196,"",0,4,"a",-1,0,-1,0,171,171,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0171-06",15,"Encimita de tu frente\nTe lo tengo de escribir:\nPondré una a y una m,\nY entre las dos una i.",210,0,-1,196,"",0,4,"i",-1,0,-1,0,171,171,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0172-01",15,"Échame una maldicion,\nUna maldicion gitana:\nQue los ángeles me lleven\nEn procesion á tu cama.",210,0,-1,196,"",0,4,"aa",-1,0,-1,0,172,172,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0172-02",15,"Todas las mañanas voy\nÁ la orillita del rio\nÁ preguntar á las olas\nSi han visto al cariño mio.",210,0,-1,196,"",0,4,"o",3,0,-1,0,172,172,"","",0,"","","",12,0,0,[],"",""],["lafuente_madrid-p0172-03",15,"Ya sabes que estoy á gusto\nCuando te tengo á mi vera;\nLas fatigas de Dios paso\nCuando te vas y me dejas.",210,0,-1,196,"",0,4,"ea",-1,0,-1,0,172,172,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0172-04",15,"Siéntate á la vera mia,\nSiquiera por un minuto,\nY le darás á mi cuerpo\nEse ratillo de gusto.",210,0,-1,196,"",0,4,"uo",-1,0,-1,0,172,172,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0172-05",15,"Ya que no te puedo hablar,\nPónte donde yo te vea;\nLe daré gusto á mis ojos,\nYa que otra cosa no sea.",210,0,-1,196,"",0,4,"ea",54,0,-1,0,172,172,"","",0,"rm_t2, palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0172-06",15,"Ya que no te puedo hablar\nEn tu casa, ni en la calle,\nMe contento con mirar\nDe tu puerta los umbrales",210,0,-1,196,"",0,4,"ae",-1,0,-1,0,172,172,"","",0,"","","",6,0,0,[],"",""],["lafuente_madrid-p0173-01",15,"Si quieres venirte, vénte,\nSi quieres estarte, estále;\nNos quedaremos á solas,\nQue tengo que platicarte.",210,0,-1,196,"",0,4,"ae",-1,0,-1,0,173,173,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0173-02",15,"Valientemente, muchachs,\nDios te dió sabiduría;\nUna palabra que hablas\nVale por doscientas mias.",210,0,-1,196,"",0,4,"ia",-1,0,-1,0,173,173,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0173-03",15,"¡Qué triste, y qué pensativa\nEstá la prenda que adoro!\n¿Qué cariñito le haré\nPara quitarle el enojo?",210,0,-1,196,"",0,4,"oo",-1,0,-1,0,173,173,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0173-04",15,"Mi morena se ha enojado\nPorque no le dije adios.\nAdios, morena del alma,\nAdios, morenita, adios.",210,0,-1,196,"",0,4,"ao",-1,0,-1,0,173,173,"","",0,"carrizo_salta","","",4,0,0,[],"",""],["lafuente_madrid-p0173-05",15,"Dije que no te queria,\nY otra vez vuelvo á buscarte\nCon el corazon partido,\nLlorando gotas de sangre.",210,0,-1,196,"",0,4,"ae",-1,0,-1,0,173,173,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0173-06",15,"Dáme la manita, irémos\nAl sitio donde lloraste,\nY entre los dos cogerémos\nLas perlas que derramaste.",210,0,-1,196,"",1,4,"ae",212,0,-1,0,173,173,"","",0,"fernan_caballero","","",3,0,0,[],"",""],["lafuente_madrid-p0173-07",15,"Si con hechizos pudiera\nEsta noche hablar contigo,\nBien sabe Dios que lo hiciera\nPor dar á mi pena alivio.",210,0,-1,196,"",0,4,"io",-1,0,-1,0,173,173,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0174-01",15,"Por la mañana temprano\nIré á hacerte una visita:\nSiempre te encuentro con gente\nY yo te quiero solita.",210,0,-1,196,"",0,4,"ia",50,0,-1,0,174,174,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0174-02",15,"Cuando paso por tu puerta,\nSi estas solilla, te hablo,\nSi acompañadilla estás,\nAgacho la vista y callo.",210,0,-1,196,"",0,4,"ao",-1,0,-1,0,174,174,"","",0,"","","",17,0,0,[],"",""],["lafuente_madrid-p0174-03",15,"Baja, niña, al cuarto bajo,\nHablarémos por la reja\nDos palabritas de amor,\nSin que lo sepa la vieja.",210,0,-1,196,"",0,4,"ea",165,0,-1,0,174,174,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0174-04",15,"Con mi puro y mi guitarra\nMe tendrás todas las noches\nAl frente de tu ventana\nAntes que suenen las doce.",210,0,-1,196,"",0,4,"oe",-1,0,-1,0,174,174,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0174-05",15,"Marinero, boga, boga,\nY que vuele la barquilla,\nQue al otro lado del rio\nMe espera el bien de mi vida.",210,0,-1,196,"",0,4,"ia",-1,0,-1,0,174,174,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0174-06",15,"Cuando te veo venir\nHasta el alma se me alegra;\nNo te salgo á recibir\nPor causa de malas lenguas.",210,0,-1,196,"",0,4,"ea",-1,0,-1,0,174,174,"","",0,"palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0174-07",15,"Amor mio, ven temprano,\nNo me vengas á deshora,\nQue la vecina de en frento\nEs algo murmuradora.",210,0,-1,196,"",0,4,"oa",107,0,-1,0,174,174,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0175-01",15,"Anoche me dió la una\nPlaticando con mi amor;\nEsta noche, si Dios quiere,\nMe dan lo menos las dos.",210,0,-1,196,"",0,4,"o",-1,0,-1,0,175,175,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0175-02",15,"Aunque tu madre te meta\nEn un castillo de bronce,\nHemos de pelar la pava\nEntre la una y las doce.",210,0,-1,196,"",0,4,"oe",-1,0,-1,0,175,175,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0175-03",15,"Contando voy los minutos\nQue faltan hasta las nueve,\nPor ser la hora de cita\nQue mi amante viene á verme.",210,0,-1,196,"",0,4,"ee",-1,0,-1,0,175,175,"","",0,"rm_t2","","",2,0,0,[],"",""],["lafuente_madrid-p0175-04",15,"¿Qué tenias ayer tarde,\nAmante mio moreno,\nQue tan aprisa llamabas\nÁ Jesus el Nazareno?",210,0,-1,196,"",0,4,"eo",76,0,-1,0,175,175,"","",0,"palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0175-05",15,"Cada vez que paso y miro,\nY á la ventana no estás,\nAcortando voy los pasos,\nPor ver si te asomarás.",210,0,-1,196,"",0,4,"a",51,0,-1,0,175,175,"","",0,"","","",25,0,0,[],"",""],["lafuente_madrid-p0175-06",15,"Hermoso sol de los soles,\n¿En dónde estuviste ayer,\nQue te buscaron mis ojos\nY no te pudieron ver?",210,0,-1,196,"",0,4,"e",20,0,-1,0,175,175,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0176-01",15,"Como carnerillo manso\nSales al campo á buscarme,\nY yo te estoy aguardando,\nSangrecilla de mi sangre.",210,0,-1,196,"",0,4,"ae",-1,0,-1,0,176,176,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0176-02",15,"Pide á Dios por mi salud,\nMorena, que si me muero,\nLa casilla de los locos\nHa de ser tu paradero.",210,0,-1,196,"",0,4,"eo",38,0,-1,0,176,176,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0176-03",15,"Compañerita del alma,\nArrimate á mi querer,\nComo las salamanquesas\nSe arriman á la pared.",210,0,-1,196,"",0,4,"e",-1,0,-1,0,176,176,"","",0,"palau_cantares","","",20,0,0,[],"",""],["lafuente_madrid-p0176-04",15,"Mañana voy á cabildo\nÁ ver echar el sorteo,\nY si le toca á mi amante,\nDiré que por él me quedo.",210,0,-1,196,"",0,4,"eo",-1,0,-1,0,176,176,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0176-05",15,"Debajo de tu ventana\nMe quisieron dar la muerte,\nLucero de la mañana,\nSolo por venir á verte.",210,0,-1,196,"",1,4,"ee",134,0,-1,0,176,176,"","",0,"rm_t2, palau_cantares","","",29,0,0,[],"",""],["lafuente_madrid-p0176-06",15,"Compañerita del alma,\nHázme con los ojos señas,\nQue en algunas ocasiones\nLos ojos sirven de lengua.",210,0,-1,196,"",0,4,"ea",-1,0,-1,0,176,176,"","",0,"palau_cantares","","",20,0,0,[],"",""],["lafuente_madrid-p0176-07",15,"Mi amante me dijo anoche\nQue cantara y no llorara,\nQue echara penas al aire,\nPero que no lo olvidara.",210,0,-1,196,"",0,4,"aa",57,0,-1,0,176,176,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0177-01",15,"No me chifles en la calle\nPorque salga á la ventana,\nQue si mi padre se entera,\nMe zurrará la badana.",210,0,-1,196,"",0,4,"aa",4,0,-1,0,177,177,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0177-02",15,"Á mí me llaman silencio,\nY el silencio es el que vale;\nAnoche estuve en tu puerta,\nY no me sintió tu madre.",210,0,-1,196,"",0,4,"ae",-1,0,-1,0,177,177,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0177-03",15,"Si en tu casa te regañan,\nDí á voces que no me quieres,\nCon esto quedarás bien,\nY háblame cuando pudieres.",210,0,-1,196,"",0,4,"ee",55,0,-1,0,177,177,"","",0,"rm_t2, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0177-04",15,"Aunque para mí no seas,\nSiempre te tendré aficion,\nPorque eres disimulada\nCuando llega la ocasion.",210,0,-1,196,"",0,4,"o",31,0,-1,0,177,177,"","",0,"rm_t2, carrizo_salta, palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0177-05",15,"Me quieren quitar á mi\nEl que yo tu cara vea;\nPor cima de quien lo estorbe\nHe de hacer una vereda.",210,0,-1,196,"",0,4,"ea",-1,0,-1,0,177,177,"","",0,"rm_t2, palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0177-06",15,"Me quieren quitar á mí\nEl ir á misa por verte;\nNo le echo la culpa á nadie,\nSino es á mi mala suerte.",210,0,-1,196,"",0,4,"ee",134,0,-1,0,177,177,"","",0,"rm_t3","","",5,0,0,[],"",""],["lafuente_madrid-p0177-07",15,"Me han quitado el ir á misa,\nMe han quitado el confesar,\nMe han quitado que te quiera:\n¿Qué más me pueden quitar?",210,0,-1,196,"",0,4,"a",21,0,-1,0,177,177,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0178-01",15,"Bien puedes, majito mio,\nSacarme manifestada,\nPorque mis padres no quieren\nVerme contigo casada.",210,0,-1,196,"",0,4,"aa",49,0,-1,0,178,178,"","",0,"rm_t2","","",3,0,0,[],"",""],["lafuente_madrid-p0178-02",15,"Serrana, díle á tu madre\nQue si te quiere vender,\nEn la mano está el dinero,\nY en la puerta el mercader.",210,0,-1,196,"",0,4,"e",20,0,-1,0,178,178,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0178-03",15,"Aunque nos vayan celando\nPor balcones y ventanas,\nLograrémos nuestro intento,\nNo tengas pena por nada.",210,0,-1,196,"",0,4,"aa",-1,0,-1,0,178,178,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0178-04",15,"Me dicen que si te quiero,\nY yo digo que ni verte.\nEs menester disimulo\nPor el hablar de las gentes.",210,0,-1,196,"",0,4,"ee",-1,0,-1,0,178,178,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0178-05",15,"Si tu madre te pregunta\nQue si me quieres á mi,\nDi con la boca que no,\nCon el corazon que si.",210,0,-1,196,"",0,4,"i",23,0,-1,0,178,178,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0178-07",15,"Dueño y amante querido,\nSabrás que estoy vigilada,\nPorque mis padres no quieren, etc.\nPasionera, pasionera,\nDisimula tu pasion,\nComo yo la disimulo\nDentro de mi corazon.",210,0,-1,196,"",4,7,"ao",31,0,-1,0,178,179,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0179-01",15,"Mucho te quiero callando,\nY tu callar agradezco,\nQue para un firme querer\nNo hay cosa como el silencio.",210,0,-1,196,"",0,4,"eo",-1,0,-1,0,179,179,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0179-02",15,"Cuando paso por tu puerta,\nY me miras con desprecio,\nMe dejas la sangre helada,\nY el corazon sin consuelo.",210,0,-1,196,"",0,4,"eo",-1,0,-1,0,179,179,"","",0,"rm_t3, palau_cantares","","",17,0,0,[],"",""],["lafuente_madrid-p0179-03",15,"Ya sé que por mi querer\nTus padres te dan pesares;\nQuédate con Dios, perlita,\nNo quiero que tú lo pagues.",210,0,-1,196,"",0,4,"ae",-1,0,-1,0,179,179,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0179-04",15,"Quisiera que Dios me diera\nUn olvidar cariñoso,\nQue te pudiera olvidar,\nY tú quedaras gustoso.",210,0,-1,196,"",0,4,"oo",160,0,-1,0,179,179,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0179-05",15,"Quédate con Dios, salada;\nMucho me duele el dejarte;\nPero tambien considero\nQue siempre no puedo hablarte.",210,0,-1,196,"",0,4,"ae",8,0,-1,0,179,179,"","",0,"rm_t3, palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0179-06",15,"Dáme un besito, y adios,\nSalero, véte á la cama,\nQue no quiero que por mi\nPases frio en la ventana.",210,0,-1,196,"",0,4,"aa",-1,0,-1,0,179,179,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0180-01",15,"No me digas que me vaya\nPor Dios no me digas: véte;\nPorque se me representan\nLas fatigas de la muerte.",210,0,-1,196,"",0,4,"ee",-1,0,-1,0,180,180,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0180-02",15,"Siempre que te vas, me dices:\n«Adios hasta la primera.»\nComo no me dices cuándo,\nSiempre me dejas con pena.",210,0,-1,196,"",0,4,"ea",-1,0,-1,0,180,180,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0180-03",15,"Amor, no digas adios\nCuando por la calle vas,\nQue parece que me dices:\n¡Adios para nunca más!",210,0,-1,196,"",0,4,"a",51,0,-1,0,180,180,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0180-04",15,"Bailad, muchachas, bailad,\nY romped muchos zapatos;\nQue mañana os casareis,\nY os llenareis de muchachos.",210,0,-1,196,"",0,4,"ao",-1,0,-1,0,180,180,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0180-05",15,"Cuerpo bueno con sandunga,\nMenéate poco á poco,\nQue los bienes de fortuna\nCuestan mucho, y duran poco.",210,0,-1,196,"",0,4,"oo",-1,0,-1,0,180,180,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0180-06",15,"Jaléate, cuerpo bueno,\nQue te vas aniquilando\nCon la calor del invierno\nY los frios del verano.",210,0,-1,196,"",0,4,"ao",-1,0,-1,0,180,180,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0181-01",15,"Dicen que la reina ha muerto;\nTodos dicen que es verdad;\nY yo digo que es mentira,\nPorque ha salido á bailar.",210,0,-1,196,"",0,4,"a",-1,0,-1,0,181,181,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0181-02",15,"La bailadora es la luna,\nEl bailador es el sol;\nÁ los rayos de la luna\nMe voy arrimando yo.",210,0,-1,196,"",0,4,"o",-1,0,-1,0,181,181,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0181-03",15,"Cuando sales á bailar\nCon ese garbo y salero,\nUna campana de plata\nDejas pintada en el suelo.",210,0,-1,196,"",0,4,"eo",-1,0,-1,0,181,181,"","",0,"","","",5,0,0,[],"",""],["lafuente_madrid-p0181-04",15,"Tienes un baile tan chulo,\nY una vuelta tan galana,\nQue dejas en ese suelo\nPintadita una campana.",210,0,-1,196,"",0,4,"aa",4,0,-1,0,181,181,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0181-05",15,"La guitarra es de caoba,\nY las cuerdas de marfil,\nEl que la toca es un ángel,\nLa que baila un serafin.",210,0,-1,196,"",0,4,"i",-1,0,-1,0,181,181,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0181-06",15,"Ya salió mi niña al baile,\nYa salió la resalada,\nYa salió la que me tiene\nTodita el alma robada.",210,0,-1,196,"",0,4,"aa",49,0,-1,0,181,181,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0181-07",15,"Una mudanza por bajo\nBaile usté, seo bailador,\nPorque aunque cueste trabajo\nSe la merece esa flor.",210,0,-1,196,"",1,4,"o",72,0,-1,0,181,181,"","",0,"rm_t4","","",2,0,0,[],"",""],["lafuente_madrid-p0182-01",15,"Pulido bailadorcito,\nÁtate los alpargates,\nNo vayas á tropezar,\nY á esa niña me la mates.",210,0,-1,196,"",0,4,"ae",283,0,-1,0,182,182,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0182-02",15,"Pulido bailadorcito,\nBáilala bien, que es mi hermana\nY si no la bailas bien,\nSaldrá su hermano á bailarla.",210,0,-1,196,"",0,4,"aa",-1,0,-1,0,182,182,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0182-03",15,"¿Qué tiene ese bailador\nQue no menea los brazos,\nY parece un avion,\nQue le han dado taramazo?",210,0,-1,196,"",0,4,"ao",-1,0,-1,0,182,182,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0182-04",15,"Esa señora que baila\nSe parece á san Miguel,\nY el bailador que la baila\nAl que está debajo de él.",210,0,-1,196,"",1,4,"e",32,0,-1,0,182,182,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0182-05",15,"La niña que está bailando\nMe la comiera yo solo,\nY al bailador que la baila\nQue se lo coman los lobos.",210,0,-1,196,"",0,4,"oo",-1,0,-1,0,182,182,"","",0,"rm_t4, palau_cantares","","",19,0,0,[],"",""],["lafuente_madrid-p0182-06",15,"La niña que está bailando\nParece una altramucera.\n¡Altramuces, dulces, dulces,\nSerrana, quién te comiera!",210,0,-1,196,"",0,4,"ea",44,0,-1,0,182,182,"","",0,"palau_cantares","","",19,0,0,[],"",""],["lafuente_madrid-p0182-07",15,"La niña que está bailando\nParece una clavellina,\nY el bailador que la baila\nParece un Juan de las Viñas.",210,0,-1,196,"",0,4,"ia",-1,0,-1,0,182,182,"","",0,"rm_t4, palau_cantares","","",19,0,0,[],"",""],["lafuente_madrid-p0182-08",15,"La niña que está bailando\nParece un pimpollo de oro;\nPregúntale, compañero,\nSi es casada, ó tiene novio.",210,0,-1,196,"",0,4,"oo",-1,0,-1,0,182,183,"","",0,"palau_cantares, fernan_caballero","","",19,0,0,[],"",""],["lafuente_madrid-p0183-01",15,"La dama que está bailando\nSe parece á santa Rita,\nY el galan que está cantando\nErmitaño de su ermita.",210,0,-1,196,"",1,4,"ia",50,0,-1,0,183,183,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0183-02",15,"Esos dos que están bailando\n¡Qué parejitos que son!\nSi yo fuera Padre Cura\nLes diera la bendicion.",210,0,-1,196,"",0,4,"o",31,0,-1,0,183,183,"","",0,"rm_t4, palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0183-03",15,"Cuando vayas á la fiesta,\nY te pongas á bailar,\nNo me seas retrechera,\nQue me harás prevaricar.",210,0,-1,196,"",0,4,"a",21,0,-1,0,183,183,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0183-04",15,"Cuando te veo bailar\nCon tanta gracia y salero,\nDigo: ¿Quién se llevará\nEse cuerpo sandunguero?",210,0,-1,196,"",0,4,"eo",38,0,-1,0,183,183,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0183-05",15,"Con ese andar tan ligero\nY ese modo de bailar,\nHas revuelto á los mozuelos\nDe todito este lugar.",210,0,-1,196,"",0,4,"a",21,0,-1,0,183,183,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0184-01",15,"¡Válgame Dios, qué serena\nEs usté para bailar!\nSi para todo es lo mismo,\n¡Vaya una serenidad!",210,0,-1,196,"",0,4,"a",-1,0,-1,0,184,184,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0184-02",15,"Gracias á Dios que he llegado\nDonde no pensé llegar,\nÁ darte las buenas noches,\nPaloma, en tu palomar.",210,0,-1,197,"",0,4,"a",21,0,-1,0,184,184,"","",0,"palau_cantares","","",10,0,0,[],"",""],["lafuente_madrid-p0184-03",15,"Gracias á Dios que he llegado\nAl palacio donde habita\nEsta paloma zurita,\nDesvelo de mi cuidado.",210,0,-1,197,"",11,4,"ao",14,0,-1,0,184,184,"","",0,"palau_cantares","","",10,0,0,[],"",""],["lafuente_madrid-p0184-04",15,"El galan que aquí cantare\nEn la puerta de esta dama\nAlce un poquito la voz,\nPorque está lejos la cama.",210,0,-1,197,"",0,4,"aa",90,0,-1,0,184,184,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0184-05",15,"Á mi me tocó la suerte,\nComo mejor director,\nDe venir á despertar\nDel barrio la mejor flor",210,0,-1,197,"",0,4,"o",72,0,-1,0,184,184,"","",0,"rm_t2, palau_cantares, fernan_caballero","","",4,0,0,[],"",""],["lafuente_madrid-p0185-01",15,"En el nombre sea de Dios\nY del Espíritu-Santo;\nEsta es la primera copla\nQue á tu puerta, niña, canto.",210,0,-1,197,"",0,4,"ao",30,0,-1,0,185,185,"","",0,"rm_t2, fernan_caballero","","",7,0,0,[],"",""],["lafuente_madrid-p0185-02",15,"Coplillas y más coplillas,\nCoplillas he de cantar,\nPorque tengo un arca llena\nY un costal por desatar.",210,0,-1,197,"",0,4,"a",21,0,-1,0,185,185,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0185-03",15,"En el campo nada importa\nCantar bien, ó cantar mal;\nMas llegando donde hay gente,\nCantar bien, ó no cantar.",210,0,-1,197,"",0,4,"a",-1,0,-1,0,185,185,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0185-04",15,"La luna para salir\nLe pide al cielo licencia;\nY para cantar yo aquí\nLa pido con reverencia.",210,0,-1,197,"",0,4,"ea",46,0,-1,0,185,185,"","",0,"rm_t2, carrizo_salta, palau_cantares","","",14,0,0,[],"",""],["lafuente_madrid-p0185-05",15,"Á la puerta de mi novia\nMi compañero cantó;\nÁ la puerta de la suya\nEs razon que cante yo.",210,0,-1,197,"",0,4,"o",2,0,-1,0,185,185,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0185-06",15,"Si quieres saber, hermosa,\nQuién te ha venido á cantar,\nUn mocito aragonés,\nQue te tiene voluntad.",210,0,-1,197,"",0,4,"a",-1,0,-1,0,185,185,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0185-07",15,"Si tuviera el pecho claro,\nTe cantara la Rondeña;\nPero como no lo tengo,\nTe canto la Malagueña.",210,0,-1,197,"",0,4,"ea",291,0,-1,0,185,185,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0186-01",15,"Aquí me tienes penando,\nDueño de mi corazon,\nPues vengo de contrabando,\nY no puedo alzar la voz.",210,0,-1,197,"",0,4,"o",-1,0,-1,0,186,186,"","",0,"rm_t2, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0186-02",15,"Ahora sí que canto claro,\nQue he tomado caramelo,\nQue me lo dió una gitana\nCon muchisimo salero.",210,0,-1,197,"",0,4,"eo",-1,0,-1,0,186,186,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0186-03",15,"Ocho coplas en tu abono,\nSeñora, te vengo á echar;\nLo primero que te digo:\nEres la flor de Graná.",210,0,-1,197,"",0,4,"a",-1,0,-1,0,186,186,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0186-04",15,"Una coplilla en tu abono\nMe han mandado que te eche\nEres más rubia que el oro,\nY más blanca que la leche.",210,0,-1,197,"",0,4,"ee",180,0,-1,0,186,186,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0186-05",15,"Si supiera, vida mia,\nQue me estabas escuchando\nToda la noche estaria\nComo un ruiseñor cantando.",210,0,-1,197,"",1,4,"ao",33,0,-1,0,186,186,"","",0,"rm_t2, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0186-06",15,"La primera por el amo,\nLa segunda por la dueña,\nTercera por la criada,\nQue es la que á mí me da pena.",210,0,-1,197,"",0,4,"ea",-1,0,-1,0,186,186,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0186-07",15,"Aunque no canta, aquí viene,\nSalada, tu enamorado;\nAunque no canta, aqui viene,\nAquí le tengo á mi lado.",210,0,-1,197,"",1,4,"ao",14,0,-1,0,186,186,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0187-01",15,"Yo no canto porque sé,\nNi porque escuchen mi voz;\nCanto porque no se junte\nLa pena con el dolor.",210,0,-1,197,"",0,4,"o",-1,0,-1,0,187,187,"","",0,"palau_cantares","","",7,0,0,[],"",""],["lafuente_madrid-p0187-02",15,"No canto porque me escuchen,\nNi tampoco porque sé;\nCanto porque soy mandado,\nY es preciso obedecer.",210,0,-1,197,"",0,4,"e",-1,0,-1,0,187,187,"","",0,"carrizo_salta, palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0187-03",15,"Por la calle abajo viene\nUna guitarra de plata,\nY la prima va diciendo:\nUna morena me mata.",210,0,-1,197,"",0,4,"aa",74,0,-1,0,187,187,"","",0,"rm_t2, palau_cantares, fernan_caballero","","",4,0,0,[],"",""],["lafuente_madrid-p0187-04",15,"La guitarra es de marfil,\nDe oro las cuerdas y el puente\nY el tañedor que la tañe,\nSalada, tu pretendiente.",210,0,-1,197,"",0,4,"ee",15,0,-1,0,187,187,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0187-05",15,"Dáme de tu pelo rubio\nCuerdas para mi vihuela,\nQue se me ha roto la prima,\nCuarta, segunda y tercera.",210,0,-1,197,"",0,4,"ea",-1,0,-1,0,187,187,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0188-01",15,"Si supiera que cantando\nDaba gusto á mi morena,\nToda la noche cantara,\nY á la mañana durmiera.",210,0,-1,197,"",0,4,"ea",-1,0,-1,0,188,188,"","",0,"rm_t2, palau_cantares","","",10,0,0,[],"",""],["lafuente_madrid-p0188-02",15,"Despierta, calandria hermosa,\nQue en tu puerta hay un gilguero,\nEn tu garganta una rosa,\nY en tu pecho un prisionero.",210,0,-1,197,"",1,4,"eo",38,0,-1,0,188,188,"","",0,"rm_t2","","",3,0,0,[],"",""],["lafuente_madrid-p0188-03",15,"Ya sé que estas en la cama,\nYa sé que no duermes, no,\nYa sé que estas escuchando\nLas coplas que canto yo.",210,0,-1,197,"",0,4,"o",2,0,-1,0,188,188,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0188-04",15,"Asómate á esa ventana,\nNiña, si quieres oir\nLas coplas de un firme amante,\nQue las canta un serafin.",210,0,-1,197,"",0,4,"i",-1,0,-1,0,188,188,"","",0,"rm_t2, palau_cantares","","",50,0,0,[],"",""],["lafuente_madrid-p0188-05",15,"Asómate á esa ventana,\nBella dama, y te verémos,\nY con la luz de tus ojos\nLa vihuela templarémos.",210,0,-1,197,"",0,4,"eo",127,0,-1,0,188,188,"","",0,"palau_cantares","","",50,0,0,[],"",""],["lafuente_madrid-p0188-06",15,"Asómate á esa ventana,\nCara de piñon de oro,\nQuiero encender un cigarro\nEn las niñas de tus ojos.",210,0,-1,197,"",0,4,"oo",-1,0,-1,0,188,188,"","",0,"palau_cantares","","",50,0,0,[],"",""],["lafuente_madrid-p0188-07",15,"Asómate á esa ventana,\nHermosísima diadema,\nQue aunque está la noche oscura,\nTú de claridad la llenas.",210,0,-1,197,"",0,4,"ea",-1,0,-1,0,188,188,"","",0,"rm_t2","","",50,0,0,[],"",""],["lafuente_madrid-p0189-01",15,"Asómate á esa ventana,\nCara de luna redonda,\nLucero de la mañana\nY espejo de quien te ronda.",210,0,-1,197,"",1,4,"oa",182,0,-1,0,189,189,"","",0,"palau_cantares","","",50,0,0,[],"",""],["lafuente_madrid-p0189-02",15,"Asómate á esa ventana,\nCara de luna brillante,\nQue aunque yo no te pretendo.\nConmigo viene tu amante.",210,0,-1,197,"",0,4,"ae",47,0,-1,0,189,189,"","",0,"rm_t2, palau_cantares","","",50,0,0,[],"",""],["lafuente_madrid-p0189-03",15,"La luna se va, se va,\nDéjela usted que se vaya;\nLa luna que á mí me alumbra\nEstá en aquella ventana.",210,0,-1,197,"",0,4,"aa",-1,0,-1,0,189,189,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0189-04",15,"Asómate á ese balcon,\nAsómate, luz divina,\nVerás con tu resplandor\nTu amante que está en la esquina",210,0,-1,197,"",0,4,"ia",11,0,-1,0,189,189,"","",0,"rm_t2, palau_cantares","","",7,0,0,[],"",""],["lafuente_madrid-p0189-05",15,"Asómate á esa ventana,\nSi te quieres asomar,\nVerás tu calle barrida\nCon la capa de un galan.",210,0,-1,197,"",0,4,"a",-1,0,-1,0,189,189,"","",0,"palau_cantares","","",50,0,0,[],"",""],["lafuente_madrid-p0189-06",15,"Asómate á esa ventana,\nCara de limon florido,\nY échale una bendicion\nAl que ha de ser tu marido.",210,0,-1,197,"",0,4,"io",-1,0,-1,0,189,189,"","",0,"palau_cantares","","",50,0,0,[],"",""],["lafuente_madrid-p0189-07",15,"Asómate á ese balcon,\nY si no, á la ventanilla,\nY si no tienes ventana,\nA la puerta, vida mia.",210,0,-1,197,"",0,4,"ia",-1,0,-1,0,189,189,"","",0,"rm_t2, carrizo_salta, palau_cantares","","",7,0,0,[],"",""],["lafuente_madrid-p0190-02",15,"Asómate á esa ventana,\nSi te quieres asomar;\nTen cuidado no te rompas\nEse pecho de cristal.",210,0,-1,197,"",0,4,"a",-1,0,-1,0,190,190,"","",0,"palau_cantares","","",50,0,0,[],"",""],["lafuente_madrid-p0190-03",15,"Asómate á esa ventana,\nHermosura de la tierra,\nY verás en el instante\nAl sol parar su carrera.",210,0,-1,197,"",0,4,"ea",-1,0,-1,0,190,190,"","",0,"rm_t2, palau_cantares","","",50,0,0,[],"",""],["lafuente_madrid-p0190-04",15,"La luna se va á poner;\nYa hacen sombra los tejados.\n¿Cómo me despediré\nDe estos claveles dorados?",210,0,-1,197,"",0,4,"ao",18,0,-1,0,190,190,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0190-05",15,"Vámonos, compañeritos,\nQue las cabrillas van altas,\nY la luz del dia viene\nDescubriendo nuestras faltas.",210,0,-1,197,"",0,4,"aa",183,0,-1,0,190,190,"","",0,"palau_cantares","","",11,0,0,[],"",""],["lafuente_madrid-p0190-06",15,"Echemos la despedida\nAl uso de mi lugar:\nMás vale poquito y bueno,\nQue no mucho y enfadar.",210,0,-1,197,"",0,4,"a",21,0,-1,0,190,190,"","",0,"palau_cantares","","",18,0,0,[],"",""],["lafuente_madrid-p0191-01",15,"Echemos la despedida,\nEchémosla con dolor:\nEn los hierros de tu reja\nSe queda mi corazon.",210,0,-1,197,"",0,4,"o",-1,0,-1,0,191,191,"","",0,"palau_cantares","","",18,0,0,[],"",""],["lafuente_madrid-p0191-02",15,"Echemos la despedida\nAl uso de caballeros,\nCon el sombrero en la mano:\nQuede V. con Dios, salero.",210,0,-1,197,"",0,4,"eo",-1,0,-1,0,191,191,"","",0,"","","",18,0,0,[],"",""],["lafuente_madrid-p0191-03",15,"Echemos la despedida\nAl uso de Barcelona:\nLa madre que te parió\nMerece palma y corona",210,0,-1,197,"",0,4,"oa",7,0,-1,0,191,191,"","",0,"palau_cantares","","",18,0,0,[],"",""],["lafuente_madrid-p0191-04",15,"Te echaré la despedida,\nComo hacen los carreteros,\nCon la zurriaga en la mano:\nQuédate con Dios, salero.",210,0,-1,197,"",0,4,"eo",-1,0,-1,0,191,191,"","",0,"palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0191-05",15,"Echemos la despedida\nCon un ramito de nueces,\nQue la música no ha sido\nComo tú te la mereces.",210,0,-1,197,"",0,4,"ee",196,0,-1,0,191,191,"","",0,"palau_cantares","","",18,0,0,[],"",""],["lafuente_madrid-p0191-06",15,"La despedida te doy,\nLa despedida voy dando:\nEsta si que es despedida,\nQue me despido cantando.",210,0,-1,197,"",0,4,"ao",33,0,-1,0,191,191,"","",0,"rm_t2, palau_cantares","","",9,0,0,[],"",""],["lafuente_madrid-p0192-01",15,"Echemos la despedida,\nEchémosla muy corteses,\nQue es hija de buenos padres,\nY ella bien se lo merece.",210,0,-1,197,"",0,4,"ee",-1,0,-1,0,192,192,"","",0,"rm_t2, palau_cantares","","",18,0,0,[],"",""],["lafuente_madrid-p0192-02",15,"Te echaré la despedida\nDe rositas y claveles,\nY un ramito de albahaca,\nPara que de mí te acuerdes.",210,0,-1,197,"",0,4,"ee",-1,0,-1,0,192,192,"","",0,"rm_t2, palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0192-03",15,"De todas las despedidas\nEs la mia la más alta:\nAdios, clavel; adios, rosa;\nAdios, mata de albahaca.",210,0,-1,197,"",0,4,"aa",-1,0,-1,0,192,192,"","",0,"palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0192-04",15,"Si tuviera una naranja,\nContigo la partiria;\nPero como no la tengo,\nTe canto la despedida.",210,0,-1,197,"",0,4,"ia",-1,0,-1,0,192,192,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0192-05",15,"Ahí te va la despedida\nCon corona, ramo y palma;\nEsta sí que es despedida\nDe dos amantes del alma.",210,0,-1,197,"",1,4,"aa",125,0,-1,0,192,192,"","",0,"rm_t2, palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0192-06",15,"Mis amiguitos me dicen\nQue no me sé despedir:\nAdios, clavel; adios, rosa;\nAdios, precioso jazmin.",210,0,-1,197,"",0,4,"i",-1,0,-1,0,192,192,"","",0,"rm_t2, palau_cantares, fernan_caballero","","",4,0,0,[],"",""],["lafuente_madrid-p0193-01",15,"Aunque me voy, no me voy,\nAunque me voy, no me ausento,\nAunque me voy de palabra,\nNo me voy de pensamiento.",210,0,-1,197,"",0,4,"eo",94,0,-1,0,193,193,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0193-02",15,"Me despido de tu puerta\nComo el sol de las paredes,\nQue por las tardes se va,\nY por las mañanas vuelve.",210,0,-1,197,"",0,4,"ee",-1,0,-1,0,193,193,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0193-03",15,"Adios, corazon amado;\nAdios, palma de hermosura;\nAdios, clavel; adios, rosa;\nAdios, hermosa pintura.",210,0,-1,197,"",0,4,"ua",17,0,-1,0,193,193,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0193-04",15,"Adios, dueño de mi vida;\nAdios, hechizo del alma;\nAdios, norte de mi amor;\nAdios, mar de mi esperanza.",210,0,-1,197,"",0,4,"aa",-1,0,-1,0,193,193,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0193-05",15,"Con esta copla, señores,\nDe mi niña me despido;\nQue mi madre ya dirá\n¿Dónde estará ese perdido?",210,0,-1,197,"",0,4,"io",101,0,-1,0,193,193,"","",0,"palau_cantares, fernan_caballero","","",5,0,0,[],"",""],["lafuente_madrid-p0193-06",15,"Señores, ustés perdonen\nDe lo poco y mal cantado,\nQue soy del oficio nuevo\nY no estoy examinado.",210,0,-1,197,"",0,4,"ao",14,0,-1,0,193,193,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0194-01",15,"¡Ay, mal haya mi fortuna,\nY tambien mi mala suerte!\nQue el galan que yo idolatro\nQuieren que de mi se ausente.",210,0,-1,197,"",0,4,"ee",-1,0,-1,0,194,194,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0194-02",15,"Mi corazon pena y muere\nEn diciendo que te vas;\nPara que tanto no pene,\nDime cuándo volverás.",210,0,-1,197,"",0,4,"a",51,0,-1,0,194,194,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0194-03",15,"Quédate con Dios, salada,\nTú te quedas, yo me voy;\nEl aire que éntre en tu cuarto\nSon suspiros que yo doy.",210,0,-1,197,"",0,4,"o",112,0,-1,0,194,194,"","",0,"palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0194-04",15,"Nunca me digas adios,\nQue es una palabra triste:\nCorazones que se aman,\nNunca deben despedirse..",210,0,-1,197,"",0,4,"ie",-1,0,-1,0,194,194,"","",0,"rm_t2, palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0194-05",15,"Adios, mi adorado bien,\nNo me olvides por tu vida,\nQue yo no te olvidaré\nSi la muerte no me priva.",210,0,-1,197,"",0,4,"ia",-1,0,-1,0,194,194,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0194-06",15,"Adios, mi estrella y mi gloria\nNo pongas en mi lugar\nOtro galan en memoria,\nNi me llegues á olvidar.",210,0,-1,197,"",1,4,"a",21,0,-1,0,194,194,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0194-07",15,"¡Cuántas veces, vida mia,\nTe asomarás al balcon,\nY te quitarás llorando\nDe ver que no paso yo",210,0,-1,197,"",0,4,"o",-1,0,-1,0,194,194,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0195-01",15,"Dicen que te vas mañana;\nNo te vayas hasta el martes,\nQue tiene mi corazon\nMuchos consejos que darte.",210,0,-1,197,"",0,4,"ae",-1,0,-1,0,195,195,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0195-02",15,"El sábado es esperanza,\nEl domingo es alegría;\nMas el lunes es tristeza,\nPues se va la prenda mia,",210,0,-1,197,"",0,4,"ia",0,0,-1,0,195,195,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0195-03",15,"Dicen que te vas el lunes,\nVénte á mi puerta á embarcar,\nMis brazos serán los remos,\nY mis lágrimas el mar.",210,0,-1,197,"",0,4,"a",21,0,-1,0,195,195,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0195-04",15,"Dicen que te vas, te vas,\nY muy pronto, dueño mio;\nMira, no bebas el agua\nDe la fuente del Olvido.",210,0,-1,197,"",0,4,"io",-1,0,-1,0,195,195,"","",0,"palau_cantares, fernan_caballero","","",3,0,0,[],"",""],["lafuente_madrid-p0195-05",15,"No estaré jamas sin tí;\nQue solo podrá el rigor\nSepararte de mis ojos,\nMas no de mi corazon.",210,0,-1,197,"",0,4,"o",-1,0,-1,0,195,195,"","",0,"palau_cantares, preciso_coleccion","","",6,0,0,[],"",""],["lafuente_madrid-p0195-06",15,"Lucero de la mañana,\nPréstame tu claridad\nPara seguirle los pasos\nÁ mi amor, que se me va.",210,0,-1,197,"",0,4,"a",-1,0,-1,0,195,195,"","",0,"palau_cantares","","",22,0,0,[],"",""],["lafuente_madrid-p0195-07",15,"Tengo yo mi corazon\nComo el de san Agustin,\nLlorando gotas de sangre,\nCuando me aparto de tí.",210,0,-1,197,"",0,4,"i",-1,0,-1,0,195,195,"","",0,"","","",14,0,0,[],"",""],["lafuente_madrid-p0196-01",15,"Suspiros que de mí salgan,\nY otros que de ti saldrán,\nSi en el camino se encuentran,\n¡Qué de cosas se diran!",210,0,-1,197,"",0,4,"a",147,0,-1,0,196,196,"","",0,"rm_t2, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0196-02",15,"Adios, adios, que me voy,\nY no me quisiera ir:\nDáme los brazos del alma,\nQue me vengo á despedir.",210,0,-1,197,"",0,4,"i",157,0,-1,0,196,196,"","",0,"rm_t2, carrizo_salta, palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0196-03",15,"Adios, quédate con Dios;\nAdios, el cielo te guarde,\nUna estrella que te guie\nY un ángel que te acompañe.",210,0,-1,197,"",0,4,"ae",-1,0,-1,0,196,196,"","",0,"rm_t2","","",3,0,0,[],"",""],["lafuente_madrid-p0196-04",15,"Adios, vida de mi vida;\nAdios, corazon amado;\nAdios, que me voy sin verte,\nPorque la ausencia ha llegado.",210,0,-1,197,"",0,4,"ao",14,0,-1,0,196,196,"","",0,"rm_t2, palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0196-05",15,"Adios, adorada prenda,\nQue me vengo á despedir,\nY las piedras se quebrantan\nAl ausentarme de ti.",210,0,-1,197,"",0,4,"i",-1,0,-1,0,196,196,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0196-06",15,"El que quiera ver dolores,\nVaya á la orilla del mar,\nY verá dos corazones\nQue se quieren separar,",210,0,-1,197,"",0,4,"a",21,0,-1,0,196,196,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0197-01",15,"Precipicio cauteloso,\nMañana voy de partida,\nSi la ausencia causa muerte,\n¡Qué corta será mi vida!",210,0,-1,197,"",0,4,"ia",37,0,-1,0,197,197,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0197-02",15,"Amor mio, si te vas,\nEn tu ausencia yo me muero;\nCuando vuelvas me hallarás\nMuerto y sin tener consuelo.",210,0,-1,197,"",0,4,"eo",-1,0,-1,0,197,197,"","",0,"rm_t2, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0197-03",15,"Si de tu ausencia no muero,\nY con ella he de morir,\nDigan que soy en el mundo\nLa mujer más infeliz.",210,0,-1,197,"",0,4,"i",-1,0,-1,0,197,197,"","",0,"rm_t2, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0197-04",15,"Si oyes que tocan á muerto,\nNo preguntes quién murió;\nPorque, ausente de tu vista,\n¿Quién puede ser sino yo?",210,0,-1,197,"",0,4,"o",2,0,-1,0,197,197,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0197-05",15,"Por en medio de esos mares\nMe voy á buscar la vida;\nAcuérdate, si no vuelvo,\nDe quien tanto te queria.",210,0,-1,197,"",0,4,"ia",-1,0,-1,0,197,197,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0197-06",15,"Se fué mi dueño querido,\nY solito me ha dejado,\nComo pajarito triste\nDe rama en rama volando.",210,0,-1,198,"",0,4,"ao",-1,0,-1,0,197,197,"","",0,"rm_t3, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0198-01",15,"Cuando sali de Marbella,\nHasta el caballo lloraba,\nQue me dejé una doncella,\nQue al sol los rayos quitaba.",210,0,-1,198,"",1,4,"aa",28,0,-1,0,198,198,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0198-02",15,"El dia que me aparté\nDe tu presencia divina,\nMás lágrimas derramé\nQue lleva el Guadalmedina.",210,0,-1,198,"",1,4,"ia",11,0,-1,0,198,198,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0198-03",15,"Mi amante cuando se fué\nMe dijo que no llorara,\nQue echara penas á un lado,\nPero que no lo olvidara.",210,0,-1,198,"",0,4,"aa",57,0,-1,0,198,198,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0198-04",15,"Ya tu dueño se ausentó,\nTe ha dejado sin compaña;\nSe ha llevado tus sentidos,\nLas tres potencias del alma.",210,0,-1,198,"",0,4,"aa",-1,0,-1,0,198,198,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0198-05",15,"Ojos que te vieron ir\nPor aquellos olivares,\n¿Cuándo te verán volver\nPara alivio de mis males?",210,0,-1,198,"",0,4,"ae",-1,0,-1,0,198,198,"","",0,"rm_t3, palau_cantares","","",12,0,0,[],"",""],["lafuente_madrid-p0199-01",15,"Ya no voy ni vengo al muelle,\nPorque no tengo á quien ver;\nQue un amante que tenia\nTendió la vela, y se fué..",210,0,-1,198,"",0,4,"e",-1,0,-1,0,199,199,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0199-02",15,"Mal haya quien hizo el barco,\nY el que lo arrojó á la mar,\nY el que cortó la madera,\nY el que la mandó cortar.",210,0,-1,198,"",0,4,"a",21,0,-1,0,199,199,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0199-03",15,"Triste está mi corazon,\nY no sabe lo que tiene,\nQue está muy lejos de aquí\nEl que consolarlo puede.",210,0,-1,198,"",0,4,"ee",-1,0,-1,0,199,199,"","",0,"palau_cantares, fernan_caballero","","",5,0,0,[],"",""],["lafuente_madrid-p0199-04",15,"Si san Rafael me diera\nLas alas para volar,\nDonde tengo el pensamiento\nFuera de un vuelo á parar.",210,0,-1,198,"",0,4,"a",21,0,-1,0,199,199,"","",0,"","","",5,0,0,[],"",""],["lafuente_madrid-p0199-05",15,"Si mi corazon volara,\nY fuera donde lo envio,\n¡Qué bien recibido fuera,\nSi supieran que era mio!",210,0,-1,198,"",0,4,"io",3,0,-1,0,199,199,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0199-06",15,"Dicen que el águila real\nPasa volando los mares.\n¡Ay, quién pudiera volar\nComo las águilas reales!",210,0,-1,198,"",0,4,"ae",-1,0,-1,0,199,199,"","",0,"rm_t3, palau_cantares, machado_venezuela","","",5,0,0,[],"",""],["lafuente_madrid-p0200-01",15,"En una cama de ausencia\nCayó mala mi esperanza;\nLágrimas, tened paciencia,\nQue el tiempo todo lo alcanza.",210,0,-1,198,"",1,4,"aa",163,0,-1,0,200,200,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0200-02",15,"Marinero, sube al palo,\nY díle á mi compañera\nQue si se acuerda de mi,\nComo yo me acuerdo de ella.",210,0,-1,198,"",0,4,"ea",-1,0,-1,0,200,200,"","",0,"rm_t3, palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0200-03",15,"Ausente del bien que adoro,\n¿Qué dicha podré tener?\nEn mi no reina alegría\nHasta que la vuelva á ver.",210,0,-1,198,"",0,4,"e",20,0,-1,0,200,200,"","",0,"","","",10,0,0,[],"",""],["lafuente_madrid-p0200-04",15,"Acaba de dar, acaba,\nReloj de la Catedral,\nQue quiero contar las horas\nQue ausente mi amor está.",210,0,-1,198,"",0,4,"a",-1,0,-1,0,200,200,"","",0,"palau_cantares","","",8,0,0,[],"",""],["lafuente_madrid-p0200-05",15,"Si por esos andurriales\nTe encuentras á mi morena,\nDile que estoy trabajando\nPara sacarla de penas.",210,0,-1,198,"",0,4,"ea",-1,0,-1,0,200,200,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0201-01",15,"Sirigores de la ausencia\nTuvieran fuerza en tu pecho,\nNi tú estuvieras sin mí,\nNi yo estuviera con ellos.",210,0,-1,198,"",0,4,"eo",-1,0,-1,0,201,201,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0201-02",15,"¿Cómo ha de ser la memoria\nEl correo en las ausencias,\nSi no lleva los recados,\nNi vuelve con las respuestas?",210,0,-1,198,"",0,4,"ea",-1,0,-1,0,201,201,"","",0,"rm_t3, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0201-03",15,"Lucero del mes de abril,\nEstrella del mes de mayo,\nDí, ¿cómo te va sin mí,\nPues yo sin tí no me hallo?",210,0,-1,198,"",0,4,"ao",102,0,-1,0,201,201,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0201-04",15,"Ausente del bien que adoro,\nSin esperanza de verle,\nNo puede haber para mí\nMás consuelo que la muerte.",210,0,-1,198,"",0,4,"ee",-1,0,-1,0,201,201,"","",0,"palau_cantares, preciso_coleccion","","",10,0,0,[],"",""],["lafuente_madrid-p0201-05",15,"Con la pena de no verte\nEstoy viviendo en la tierra,\nY cuando yo no me he muerto,\nNadie se muere de pena.",210,0,-1,198,"",0,4,"ea",-1,0,-1,0,201,201,"","",0,"palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0201-06",15,"Estrelita relumbrante,\n¿Cuándo será tu venida,\nQue yo te estoy aguardando\nPara la Pascua florida?",210,0,-1,198,"",0,4,"ia",37,0,-1,0,201,201,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0202-01",15,"Ausente estoy de tu vista,\nPero no del pensamiento,\nQue con los ojos del alma\nTe veo á cada momento.",210,0,-1,198,"",0,4,"eo",94,0,-1,0,202,202,"","",0,"rm_t3, palau_cantares","","",7,0,0,[],"",""],["lafuente_madrid-p0202-02",15,"¿Qué importa que no te vea,\nSi yo tengo un gran alivio?\nYo tengo mi corazon\nTodas las horas contigo.",210,0,-1,198,"",0,4,"io",-1,0,-1,0,202,202,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0202-03",15,"Aun hay autores que dicen:\nAusencias causan olvido;\nYo estoy ausente, y no puedo\nOlvidarte, dueño mio.",210,0,-1,198,"",0,4,"o",-1,0,-1,0,202,202,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0202-04",15,"El dia que te ausentaste\nLe eché un candado á mi pecho,\nY á mi corazon le dije:\nTú quedarás satisfecho.",210,0,-1,198,"",0,4,"eo",60,0,-1,0,202,202,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0202-05",15,"Viudo me considero,\nPorque de tí vivo ausente;\nQue la ausencia del amor,\nLa comparo con la muerte.",210,0,-1,198,"",0,4,"ee",-1,0,-1,0,202,202,"","",0,"rm_t3","","",2,0,0,[],"",""],["lafuente_madrid-p0202-06",15,"Hasta el muelle fuí con ella,\nEn el muelle la dejé;\n¡Allí fueron los lamentos,\nCuando de ella me aparté!",210,0,-1,198,"",0,4,"e",77,0,-1,0,202,202,"","",0,"rm_t3, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0203-01",15,"¡Ay! ¡quién tuviera la pluma\nDe santo Tomás de Aquino,\nPara escribirle una carta\nÁ mi amante con cariño!",210,0,-1,198,"",0,4,"io",-1,0,-1,0,203,203,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0203-02",15,"Anda, papel venturoso,\nQue á manos de un ángel vas,\nNo digas que yo te envio,\nSino que tú solo vas.",210,0,-1,198,"",0,4,"a",-1,0,-1,0,203,203,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0203-03",15,"Te la escribí con la pluma,\nTe la noté con el alma,\nNo preguntes de quién es,\nYa sabes cómo se llama.",210,0,-1,198,"",0,4,"aa",-1,0,-1,0,203,203,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0203-04",15,"¡Papelito venturoso,\nQuién fuera dentro de tí,\nPara darle mil abrazos\nÁ el ángel que te ha de abrir!",210,0,-1,198,"",0,4,"i",-1,0,-1,0,203,203,"","",0,"","","",4,0,0,[],"",""],["lafuente_madrid-p0203-05",15,"Porque mi letra no ves,\nPiensas que de tí me olvido;\nY en el fondo de mi pecho\nÁ cada instante te escribo.",210,0,-1,198,"",0,4,"io",-1,0,-1,0,203,203,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0203-06",15,"Llorando te la escribí;\nLlorando te la mandé;\nLas lágrimas de mis ojos\nNo me la dejaron ver.",210,0,-1,198,"",0,4,"e",-1,0,-1,0,203,203,"","",0,"rm_t3, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0203-07",15,"Una carta tengo escrita,\nNo tengo quien se la lleve\nAl amante de mi vida,\nY en su mano se la entregue.",210,0,-1,198,"",0,4,"ee",77,0,-1,0,203,203,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0204-01",15,"Dáme esa carta, serrana\nQue yo se la llevaré\nÁ el amante de tu vida,\nY en su mano la pondré.",210,0,-1,198,"",0,4,"e",77,0,-1,0,204,204,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0204-02",15,"«Pajarito, que volando\nCruzas el aire ligero,\nAquí te estoy aguardando;\nQue has de ser el mensajero\nDe un alma que está penando.",210,0,-1,198,"",7,5,"ao",33,0,-1,0,204,204,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0204-03",15,"Este papel con cuidado\nHas de llevar en el pico\nÁ mi dueño idolatrado;\nY advierte que te suplico\nQue lo des disimulado.",210,0,-1,198,"",7,5,"ao",14,0,-1,0,204,204,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0204-04",15,"Y si acaso te dijere:\n¿Quién ha escrito estos renglones?\nDíle que el amante suyo,\nQue está metido en prisiones.»",210,0,-1,198,"",0,4,"oe",34,0,-1,0,204,204,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0204-05",15,"He recibido tu carta\nCon mucho gusto y placer;\nSi no me pongo en camino,\nNo dudes que moriré.",210,0,-1,198,"",0,4,"e",-1,0,-1,0,204,204,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0204-06",15,"Cuando á mis manos llegó\nTu carta, dueño querido,\nTodo el pesar que tenia\nSe convirtió en regocijo.",210,0,-1,198,"",0,4,"io",-1,0,-1,0,204,204,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0205-01",15,"Aunque en mil años no vuelvas,\nYo seré como la mimbre,\nQue la bambolea el aire,\nPero se mantiene firme.",210,0,-1,199,"",0,4,"ie",-1,0,-1,0,205,205,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0205-02",15,"El alma que tengo es tuya,\nEn una conformidad,\nQue si presente te quiero,\nAusente te quiero más.",210,0,-1,199,"",0,4,"a",-1,0,-1,0,205,205,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0205-03",15,"Más firme soy en quererte\nQue las horas del reloj:\nEl reloj muda las horas,\nPero mi firmeza no.",210,0,-1,199,"",0,4,"o",-1,0,-1,0,205,205,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0205-04",15,"Los árboles de Aranjuez\nUnidos de siete en siete\nNo tienen tanta firmeza\nComo yo para quererte.",210,0,-1,199,"",0,4,"ee",-1,0,-1,0,205,205,"","",0,"rm_t2, palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0206-01",15,"Aunque me ves encogida,\nY que tengo pocos años,\nEn tocando á la firmeza,\nNi la cruzde San Fernando.",210,0,-1,199,"",0,4,"ao",-1,0,-1,0,206,206,"","",0,"","","",4,0,0,[],"",""],["lafuente_madrid-p0206-02",15,"Tengo de quererte á tí,\nAunque otra me solicite;\nQue un hombre puesto á querer\nEs un barco echado á pique.",210,0,-1,199,"",0,4,"ie",-1,0,-1,0,206,206,"","",0,"rm_t2","","",2,0,0,[],"",""],["lafuente_madrid-p0206-03",15,"Yo te quiero y te requiero,\nY no habrá quien me lo quite;\nQue una mujer arrestada\nEs un barco echado á pique.",210,0,-1,199,"",0,4,"ie",-1,0,-1,0,206,206,"","",0,"rm_t2","","",6,0,0,[],"",""],["lafuente_madrid-p0206-04",15,"Soy más firme que un navío\nCuando lo estan carenando;\nMientras más golpes le dan,\nMás firme se va quedando.",210,0,-1,199,"",0,4,"ao",33,0,-1,0,206,206,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0206-05",15,"Seré para tí más firme\nQue la Isla de Leon,\nQue el año del terremoto\nTembló, pero no cayó.",210,0,-1,199,"",0,4,"o",-1,0,-1,0,206,206,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0206-06",15,"Mi corazon en quererte\nEs un monte de espesura;\nMientras más ramas le cortan,\nTiene la raiz más dura.",210,0,-1,199,"",0,4,"ua",17,0,-1,0,206,206,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0206-07",15,"Cuanto más hondillo un pozo,\nMás fresquita sale el agua;\nCuanto más retiradito,\nMás firmes son mis palabras.",210,0,-1,199,"",0,4,"aa",-1,0,-1,0,206,206,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0207-01",15,"Se me puso en la cabeza\nQue te habia de querer,\nAunque hubiera más contrarios\nQue moros hay en Argel.",210,0,-1,199,"",0,4,"e",-1,0,-1,0,207,207,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0207-02",15,"Si por tu querer me expongo\nÁ riesgo de que me maten,\nVaya el mundo en hora mala,\nQue yo no quiero olvidarte.",210,0,-1,199,"",0,4,"ae",-1,0,-1,0,207,207,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0207-03",15,"Por tu querer quebranté\nLas leyes de la obediencia,\nY atrás no me he de volver,\nPorque me llamo firmeza.",210,0,-1,199,"",0,4,"ea",-1,0,-1,0,207,207,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0207-04",15,"Firma tú y firmaré yo,\nY se juntarán dos firmas;\nVerémos cuál de los dos\nCon más firmeza camina.",210,0,-1,199,"",0,4,"ia",-1,0,-1,0,207,207,"","",0,"rm_t2, palau_cantares, fernan_caballero","","",4,0,0,[],"",""],["lafuente_madrid-p0207-05",15,"Aunque me ves niña, tengo\nLas palabritas muy firmes;\nSi tus promesas son falsas,\nLas mias nunca se rinden.",210,0,-1,199,"",0,4,"ie",-1,0,-1,0,207,207,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0207-06",15,"Estrellas del alto cielo,\nBajad y firmad por mí;\nQue cumpliré la palabra\nQue al que está ausente le di.",210,0,-1,199,"",0,4,"i",23,0,-1,0,207,207,"","",0,"palau_cantares, fernan_caballero","","",6,0,0,[],"",""],["lafuente_madrid-p0207-07",15,"Tú sola reinas en mi:\nTelo dije, y no receles;\nPorque no ha de reinar nadie,\nBien mio, donde tú reines.",210,0,-1,199,"",0,4,"ee",-1,0,-1,0,207,207,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0208-01",15,"Desecha todo temor,\nVive alegre y placentero;\nQue el que fué primer amor\nSiempre ha sido verdadero.",210,0,-1,199,"",1,4,"eo",38,0,-1,0,208,208,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0208-02",15,"El castillo de Figueras\nCon veinticinco cañones\nNo ha podido derribar\nNuestros primeros amores.",210,0,-1,199,"",0,4,"oe",-1,0,-1,0,208,208,"","",0,"rm_t2","","",2,0,0,[],"",""],["lafuente_madrid-p0208-03",15,"Corazon de filigrana\nEmbutido en fino acero,\n¿Cómo quieres que te olvide\nSi has sido mi amor primero?",210,0,-1,199,"",0,4,"eo",38,0,-1,0,208,208,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0208-04",15,"¿Cómo quieres que te olvide,\nSi has sido mi compañera,\nY el amor echa raices\nComo la planta en la tierra?",210,0,-1,199,"",0,4,"ea",-1,0,-1,0,208,208,"","",0,"rm_t2, palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0208-05",15,"Por aquellas estrellitas\nQue están en el cielo azul,\nQue te tengo de querer,\nAunque no me quieras tú.",210,0,-1,199,"",0,4,"u",-1,0,-1,0,208,208,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0208-06",15,"Dulce iman de mi querer,\nRegalo de mi esperanza,\nNo tienes de qué temer,\nQue en mi no cabe mudanza.",210,0,-1,199,"",1,4,"aa",163,0,-1,0,208,208,"","",0,"rm_t2","","",2,0,0,[],"",""],["lafuente_madrid-p0209-01",15,"Tu querer y mi querer,\nTu pensamiento y el mio,\nSon como el agua del rio,\nQue atrás no puede volver.",210,0,-1,199,"",11,4,"e",20,0,-1,0,209,209,"","",0,"palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0209-02",15,"Dáme tu sangre, serrana,\nQue yo te daré la mia,\nY harémos una contrata\nQue dure toda la vida.",210,0,-1,199,"",0,4,"ia",-1,0,-1,0,209,209,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0209-03",15,"Aunque toquen á rebato\nLas campanas del olvido,\nNo podré apagar el fuego\nQue esta gitana ha encendido.",210,0,-1,199,"",0,4,"io",101,0,-1,0,209,209,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0209-04",15,"Con la sangre de mis venas\nTe firmára una escritura\nDe no dejar tu querer\nNi en la misma sepultura.",210,0,-1,199,"",0,4,"ua",17,0,-1,0,209,209,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0209-05",15,"Yo no te puedo olvidar,\nPorque es mi querer muy grande\nYo te tengo á tí metida\nEn la masa de la sangre.",210,0,-1,199,"",0,4,"ae",-1,0,-1,0,209,209,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0209-06",15,"Yo te quiero y te requiero,\nY te tengo de querer,\nHasta mudar el pellejo\nComo san Bartolomé.",210,0,-1,199,"",0,4,"e",-1,0,-1,0,209,209,"","",0,"palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0209-07",15,"Yo te tengo de querer,\nAunque le pese á mi estrella,\nAunque contra mí se opongan\nAire, fuego, mar y tierra.",210,0,-1,199,"",0,4,"ea",-1,0,-1,0,209,209,"","",0,"palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0210-01",15,"Aunque las piedras den gritos,\nY el sol deje de correr,\nY el agua del mar se acabe,\nYo te tengo de querer.",210,0,-1,199,"",0,4,"e",20,0,-1,0,210,210,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0210-02",15,"Mi fortuna ó mi desgracia\nHizo que te conociera,\nPara ser esclavo tuyo\nTodo el tiempo que viviera.",210,0,-1,199,"",0,4,"ea",44,0,-1,0,210,210,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0210-03",15,"Si yo te faltara en algo\nDe lo que te prometí,\nQue me vuelva piedra mármol,\nMi cuerpo tenga mal fin.",210,0,-1,199,"",0,4,"i",-1,0,-1,0,210,210,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0210-04",15,"Primero faltará el vino\nPara la misa mayor,\nQue faltará la palabra\nQue de mi pecho salió.",210,0,-1,199,"",0,4,"o",-1,0,-1,0,210,210,"","",0,"rm_t2","","",2,0,0,[],"",""],["lafuente_madrid-p0210-05",15,"Una palabra te he dado;\nY primero he de morir,\nY faltarle al sol sus rayos,\nQue dejarla de cumplir.",210,0,-1,199,"",0,4,"i",157,0,-1,0,210,210,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0210-06",15,"La cruz que llevas al pecho\nEs de plata, y durará;\nMás durará la palabra\nQue de mi pecho saldrá.",210,0,-1,199,"",0,4,"a",9,0,-1,0,210,210,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0210-07",15,"Permita Dios, si me olvidas,.\nTe trague la mar serena;\nY si yo te olvido á tí,\nPase por la misma pena..",210,0,-1,199,"",0,4,"ea",59,0,-1,0,210,210,"","",0,"rm_t2, palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0211-01",15,"Yo no sé lo que me has dado,\nQue no te puedo olvidar;\nParece que me has tocado\nCon la piedrecilla iman.",210,0,-1,199,"",0,4,"a",-1,0,-1,0,211,211,"","",0,"","","",5,0,0,[],"",""],["lafuente_madrid-p0211-02",15,"Á las plantas de la Virgen\nQuiero llegar á hacer voto\nDe no olvidarte en la vida,\nNi dejarte á tí por otro.",210,0,-1,199,"",0,4,"oo",-1,0,-1,0,211,211,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0211-03",15,"Agua me nieguen las fuentes,\nEl cielo me desampare,\nLluevan las plagas de Egipto,\nSerrana, si te olvidare.",210,0,-1,199,"",0,4,"ae",175,0,-1,0,211,211,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0211-04",15,"Mientras más ausente estoy,\nMás firme estoy en amar;\nLa luz del cielo me falte\nSi yo te llego á olvidar.",210,0,-1,199,"",0,4,"a",21,0,-1,0,211,211,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0211-05",15,"Tan imposible lo hallo\nEl olvidar tu querer,\nComo tomar un caballo,\nY pasar la mar con él.",210,0,-1,199,"",0,4,"e",-1,0,-1,0,211,211,"","",0,"rm_t2","","",13,0,0,[],"",""],["lafuente_madrid-p0211-06",15,"Tan imposible lo hallo\nEl olvidar tu cariño,\nComo llegar á quitarle\nÁ san Antonio su niño.",210,0,-1,199,"",0,4,"io",176,0,-1,0,211,211,"","",0,"rm_t2, palau_cantares","","",13,0,0,[],"",""],["lafuente_madrid-p0212-01",15,"Tan imposible lo hallo\nQue tú puedas olvidarme,\nComo escribir en el agua,\nY echar una piedra sangre.",210,0,-1,199,"",0,4,"ae",-1,0,-1,0,212,212,"","",0,"palau_cantares","","",13,0,0,[],"",""],["lafuente_madrid-p0212-02",15,"Tan imposible lo hallo,\nDueño mio, el olvidarte\nComo llegar y partir\nEl cielo de parte á parte.",210,0,-1,199,"",0,4,"ae",8,0,-1,0,212,212,"","",0,"","","",13,0,0,[],"",""],["lafuente_madrid-p0212-03",15,"Primero que yo te olvide,\n¡Mira qué comparacion!\nHa de calentar la luna,\nY ha de refrescar el sol.",210,0,-1,199,"",0,4,"o",-1,0,-1,0,212,212,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0212-04",15,"No pienses, dueño querido,\nQue yo te podré olvidar;\nLo que en mi pecho se encierra\nMis obras te lo dirán.",210,0,-1,199,"",0,4,"a",-1,0,-1,0,212,212,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0212-05",15,"Por darle gusto á mis padres,\nY á mi corazon pesar,\nDije que no te queria,\n¡Y no te puedo olvidar!",210,0,-1,199,"",0,4,"a",21,0,-1,0,212,212,"","",0,"rm_t2","","",2,0,0,[],"",""],["lafuente_madrid-p0213-01",15,"Mi padre me tiene dicho\nQue me tiene que sacar\nLos ojos con que te miro,\nY yo que te he de mirar.",210,0,-1,199,"",0,4,"a",21,0,-1,0,213,213,"","",0,"palau_cantares, fernan_caballero","","",4,0,0,[],"",""],["lafuente_madrid-p0213-02",15,"Mi padre, porque te quiero,\nMe castiga con rigor:\nMucho puede la obediencia;\nPero más puede el amor.",210,0,-1,199,"",0,4,"o",72,0,-1,0,213,213,"","",0,"rm_t2, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0213-03",15,"Ni mi padre, ni mi madre,\nNi san Antonio bendito,\nMe pueden á mi quitar\nQue yo te quiera un poquito.",210,0,-1,199,"",0,4,"io",119,0,-1,0,213,213,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0213-04",15,"Ni tu padre, ni tu madre,\nNi el que dispone en los cielos,\nMe apartan de tu querer,\nMientras tú me estés queriendo.",210,0,-1,199,"",0,4,"eo",-1,0,-1,0,213,213,"","",0,"rm_t2, palau_cantares","","",10,0,0,[],"",""],["lafuente_madrid-p0213-05",15,"Ni los padres misioneros,\nNi los misioneros padres,\nMe pueden á mí quitar\nQue te quiera y que te ame.",210,0,-1,199,"",0,4,"ae",-1,0,-1,0,213,213,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0213-06",15,"Aunque pase más penitas\nQue Cádiz tiene alfileres,\nNó te he de olvidar, bien mio,\nPor ver el fin que esto tiene:",210,0,-1,199,"",0,4,"ee",-1,0,-1,0,213,213,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0213-07",15,"Aunque todos se opusieran,\nContigo me he de casar;\nQue más estimo mi gusto,\nQue cuanto me puedan dar.",210,0,-1,199,"",0,4,"a",21,0,-1,0,213,213,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0214-01",15,"Lo mismo es decirme à mí\nQue te olvide y no te quiera,\nQue decirle al sol que pare\nEn medio de su carrera.",210,0,-1,199,"",0,4,"ea",44,0,-1,0,214,214,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0214-02",15,"Hasta el confesor me ha dicho\nQue te olvide, y digo yo\nQue primero olvidaria\nLa madre que me parió.",210,0,-1,199,"",0,4,"o",2,0,-1,0,214,214,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0214-03",15,"Los confesores me mandan\nQue te olvide, Manolillo;\nLos confesores no saben\nLo que vale un buen cariño.",210,0,-1,199,"",0,4,"io",-1,0,-1,0,214,214,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0214-04",15,"Arrepentida me eché\nÁ los piés de un confesor,\nMe dijo que te olvidara;\nComo un insulto me dió.",210,0,-1,199,"",0,4,"o",-1,0,-1,0,214,214,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0214-05",15,"El Padre santo de Roma\nMe dijo que te olvidara;\nYo le dije: Padre mio,\nAunque me recondenara.",210,0,-1,199,"",0,4,"aa",57,0,-1,0,214,214,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0214-06",15,"Hombre, olvida á esa mujer\nPadre mio, yo no puedo;\nEchadme otra penitencia,\nQue cumplir esa no quiero.",210,0,-1,199,"",0,4,"eo",-1,0,-1,0,214,214,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0215-01",15,"El decirme que te olvide\nEs predicar en desierto,\nMachacar en hierro frio,\nY platicar con un muerto.",210,0,-1,199,"",0,4,"eo",88,0,-1,0,215,215,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0215-02",15,"Los cuatro elementos juntos,\nAgua, tierra, viento y fuego,\nNo podrán hacer que olvide\nLo mucho que yo te quiero.",210,0,-1,199,"",0,4,"eo",-1,0,-1,0,215,215,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0215-03",15,"Al alto cielo subí,\nY hablé con un divé,\nY me echó por penitencia\nQue olvidara tu querer.",210,0,-1,199,"",0,4,"e",-1,0,-1,0,215,215,"","",0,"","","",6,0,0,[],"",""],["lafuente_madrid-p0215-04",15,"Para olvidar tu querer,\nHe de ver yo dos señales:\nQue se caigan las estrellas,\nY que se sequen los mares.",210,0,-1,199,"",0,4,"ae",-1,0,-1,0,215,215,"","",0,"rm_t2, carrizo_salta, palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0215-05",15,"Todo el tiempo de mi vida\nAmándote pasaré,\nY si me olvidas por otro,\nEn tí y en Dios pensaré.",210,0,-1,199,"",0,4,"e",77,0,-1,0,215,215,"","",0,"palau_cantares, fernan_caballero","","",4,0,0,[],"",""],["lafuente_madrid-p0215-07",15,"Aunque me digan que eres\nMujer de mala conducta\nY de malos procederes,\nTe quiero porque me gustas.",210,0,-1,199,"",0,4,"ua",-1,0,-1,0,215,215,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0216-01",15,"Aunque me digan de ti\nLo que dicen del demonio,\nYo te tengo de querer,\nCarita de san Antonio.",210,0,-1,199,"",0,4,"oo",169,0,-1,0,216,216,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0216-02",15,"Me dicen que te despida,\nNo soy de tal parecer;\nMe daré muerte primero\nQue tal cosa llegue á hacer.",210,0,-1,199,"",0,4,"e",20,0,-1,0,216,216,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0216-03",15,"Aquel que me aconsejare\nQue yo deje tu amistad\nSepa que tiene en el mundo\nUn enemigo mortal.",210,0,-1,199,"",0,4,"a",-1,0,-1,0,216,216,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0216-04",15,"Todo el mundo me lo dice,\nQue qué saco yo de ti;\nY yo le respondo al mundo:\nNadie me gobierna á mí.",210,0,-1,199,"",0,4,"i",23,0,-1,0,216,216,"","",0,"rm_t2","","",14,0,0,[],"",""],["lafuente_madrid-p0216-05",15,"Me aconsejan que te olvide:\n¡Mira qué barbaridad!\n¡Como no saben querer,\nNo saben aconsejar!",210,0,-1,199,"",0,4,"a",-1,0,-1,0,216,216,"","",0,"rm_t2, palau_cantares","","",7,0,0,[],"",""],["lafuente_madrid-p0216-06",15,"Me aconsejan que te olvide:\n¡Qué consejos dan las gentes!\nJuramento tengo hecho\nDe olvidarte con lamuerte.",210,0,-1,199,"",0,4,"ee",-1,0,-1,0,216,216,"","",0,"","","",7,0,0,[],"",""],["lafuente_madrid-p0217-01",15,"Consejillos que me daban,\nY cuenta no me tenian,\nPor un oido me entraban,\nY por otro me salian.",210,0,-1,199,"",1,4,"aa",-1,0,-1,0,217,217,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0217-02",15,"Todos me dicen á mí\nQue te olvide, que te olvide;\nY el olvidarte será\nTenerte el amor más firme.",210,0,-1,199,"",0,4,"ie",-1,0,-1,0,217,217,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0217-03",15,"Todos los santos del cielo,\nAngeles y serafines\nMe aconsejan que te deje,\nY yo cada vez más firme.",210,0,-1,199,"",0,4,"ie",-1,0,-1,0,217,217,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0217-04",15,"Todo el mundo me aconseja\nQue deje yo tu amistad;\nY yo les digo: señores,\n¿Es envidia ó caridad?",210,0,-1,199,"",0,4,"a",16,0,-1,0,217,217,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0217-05",15,"Aunque me dieran más palos\nQue le dan al martinete,\nNo te tengo de olvidar,\nPorque es mi gusto quererte.",210,0,-1,199,"",0,4,"ee",-1,0,-1,0,217,217,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0217-06",15,"Aunque pase más trabajos\nQue arenas tienen los rios,\nY pinos tienen los montes,\nNo te he de olvidar, bien mio.",210,0,-1,199,"",0,4,"o",-1,0,-1,0,217,217,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0217-07",15,"Aunque tu querer me mate,\nNo he de dejar de quererte;\nQue te quiero con el alma,\nY el alma nunca se muere.",210,0,-1,199,"",0,4,"ee",-1,0,-1,0,217,218,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0218-01",15,"Todo el mundo en contra mia,\nSerrana, porque te quiero;\nTodo el mundo en contra mia,\nY yo contra el mundo entero.",210,0,-1,199,"",1,4,"eo",38,0,-1,0,218,218,"","",0,"rm_t2, palau_cantares, fernan_caballero","","",4,0,0,[],"",""],["lafuente_madrid-p0218-02",15,"Sentenciado estoy a muerte\nSi me ven hablar contigo;\n¡Mira si te quiero bien\nQue no le temo al castigo!",210,0,-1,199,"",0,4,"io",106,0,-1,0,218,218,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0218-03",15,"Sentenciado estoy á muerte\nSi me ven hablar contigo;\nYa pueden los matadores\nAprevenir los cuchillos.",210,0,-1,199,"",0,4,"io",-1,0,-1,0,218,218,"","",0,"fernan_caballero","","",4,0,0,[],"",""],["lafuente_madrid-p0218-04",15,"Dicen que me han de matar\nSi me ven hablar contigo;\nYa le pueden levantar\nÁ la escopeta el martillo",210,0,-1,199,"",0,4,"io",-1,0,-1,0,218,218,"","",0,"rm_t2","","",20,0,0,[],"",""],["lafuente_madrid-p0219-01",15,"Si el querer bien es delito,\nPadre mio, que me prendan,\nY me lleven à la cárcel,\nQue en mi querer no hay enmienda",210,0,-1,199,"",0,4,"ea",-1,0,-1,0,219,219,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0219-02",15,"Subi á la sala del Crímen,\nY le dije al presidente:\nSi el querer es un delito,\nQue me sentencien á muerte.",210,0,-1,199,"",0,4,"ee",-1,0,-1,0,219,219,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0219-03",15,"Porque te quiero me echan\nÁ la garganta un cordel,\nY á los piés una cadena;\nAhora te quiero más bien.",210,0,-1,199,"",0,4,"e",-1,0,-1,0,219,219,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0219-04",15,"Á los presidios de Oran\nMe llevan porque te olvide;\nAunque me lleven á Ceuta,\nOlvidarte es imposible.",210,0,-1,199,"",0,4,"ie",-1,0,-1,0,219,219,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0219-05",15,"Aunque me vea en dos palos,\nY un Capuchino á los piés,\nY un dogal á la garganta,\nYo siempre te he de querer.",210,0,-1,199,"",0,4,"e",-1,0,-1,0,219,219,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0219-06",15,"Aunque me veas cadáver\nÁ la puerta de una ermita,\nÁ tí no te dé cuidado,\nQue los muertos resucitan.",210,0,-1,199,"",0,4,"ia",-1,0,-1,0,219,219,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0219-07",15,"Aunque te vea difunta\nCon cuatro velas ardiendo,\nHasta la sepulturita\nTe tengo que estar queriendo.",210,0,-1,199,"",0,4,"eo",52,0,-1,0,219,219,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0220-01",15,"«Al pié del suplicio estuve\nCon la sentencia leida:\nSi olvidaba tu querer,\nMe perdonaban la vida.",210,0,-1,199,"",0,4,"ia",-1,0,-1,0,220,220,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0220-02",15,"Y yo le dije al verdugo:\nCompadre, aprieta de firme,\nQue olvidar á esa mujer\nEs una cosa imposible.»",210,0,-1,199,"",0,4,"ie",-1,0,-1,0,220,220,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0220-03",15,"Hasta la sepulturita\nTe tengo de estar queriendo,\nPorque has tenido conmigo\nPartidas de caballero.",210,0,-1,199,"",0,4,"eo",-1,0,-1,0,220,220,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0220-04",15,"Á la sepultura irémos,\nTú detrás y yo delante;\nYo no me aparto de tí,\nHasta que Dios nos aparte.",210,0,-1,199,"",0,4,"ae",-1,0,-1,0,220,220,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0220-05",15,"Al pié de la sepultura\nLa muerte me preguntó\nSi ya te habia olvidado;\nY yo le dije que no.",210,0,-1,199,"",0,4,"o",2,0,-1,0,220,220,"","",0,"rm_t2","","",5,0,0,[],"",""],["lafuente_madrid-p0220-06",15,"Al pié de la sepultura,\nYa para echarme ó no echarme\nNo pudo la ingrata muerte\nDe tu querer apartarme.",210,0,-1,199,"",0,4,"ae",35,0,-1,0,220,220,"","",0,"palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0221-01",15,"Diez años despues de muerto\nY de gusanos comido,\nLetreros tendrán mis huesos,\nDiciendo que te han querido.",210,0,-1,199,"",0,4,"io",101,0,-1,0,221,221,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0221-02",15,"Dicen que los celos matan,\nYo digo que no es así;\nQue sí los celos mataran,\nMe hubieran matado á mí.",210,0,-1,200,"",0,4,"i",23,0,-1,0,221,221,"","",0,"machado_venezuela, palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0221-03",15,"Desempedraré tu calle,\nY la cubriré de arena,\nPara mirar las pisadas\nDe los que rondan tu reja.",210,0,-1,200,"",0,4,"ea",-1,0,-1,0,221,221,"","",0,"rm_t2, rm_t3, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0221-04",15,"Tengo un clavel encarnado\nÁ la sombra y bajo llave,\nPara que el sol no lo vea,\nY con mirarlo lo aje.",210,0,-1,200,"",0,4,"ae",-1,0,-1,0,221,221,"","",0,"rm_t3, palau_cantares, fernan_caballero","","",4,0,0,[],"",""],["lafuente_madrid-p0221-05",15,"Si yo supiera las piedras\nQue mi amor pisa en la calle,\nLas volviera del revés,\nQue no las pisara nadie.",210,0,-1,200,"",0,4,"ae",-1,0,-1,0,221,221,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0221-06",15,"No quiero que hables con nadie\nSino con el confesor,\nCon tu padre y con tu madre,\nCon tus hermanos y yo.",210,0,-1,200,"",0,4,"o",-1,0,-1,0,221,221,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0222-01",15,"No quiero que á misa vayas,\nNi á la ventana te asomes,\nNi tomes agua bendita\nDonde la toman los hombres.",210,0,-1,200,"",0,4,"oe",-1,0,-1,0,222,222,"","",0,"palau_cantares, machado_venezuela, huambachano, tompkins_negros","","",7,0,0,[],"",""],["lafuente_madrid-p0222-02",15,"Quítate de esa ventana,\nNo me seas ventanera;\nQue la cuba de buen vino\nNo necesita bandera.",210,0,-1,200,"",0,4,"ea",44,0,-1,0,222,222,"","",0,"rm_t3, palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0222-03",15,"En sabiendo tú que estoy\nEn tierra de Andalucía,\nEl gachó que te camele\nBien puede buscar su vida.",210,0,-1,200,"",0,4,"ia",-1,0,-1,0,222,222,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0222-04",15,"Por pillar uno en tu puerta\nAndo que bebo los vientos,\nComo lo llegue á pillar,\nTienes en tu puerta un muerto.",210,0,-1,200,"",0,4,"eo",-1,0,-1,0,222,222,"","",0,"rm_t3","","",2,0,0,[],"",""],["lafuente_madrid-p0222-05",15,"Si te veo hablar con otro,\nTe lo juro por Jesus,\nQue á la puerta de tu casa\nTiene de haber una cruz.",210,0,-1,200,"",0,4,"u",109,0,-1,0,222,222,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0222-06",15,"Si la mujer que camelo,\nOtro me la came'ara,\nSacara yo mi cuchillo,\nY á los piés me lo dejara.",210,0,-1,200,"",0,4,"aa",57,0,-1,0,222,222,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0223-01",15,"Si supiera ó entendiera\nQue otro mozo te procura,\nDebajo de tu ventana\nLe abriera la sepultura.",210,0,-1,200,"",0,4,"ua",17,0,-1,0,223,223,"","",0,"rm_t3","","",11,0,0,[],"",""],["lafuente_madrid-p0223-02",15,"Si supiera ó entendiera\nQue á otro quieres más que á mí\nNi te mirara á la cara,\nNi me acordara de ti.",210,0,-1,200,"",0,4,"i",23,0,-1,0,223,223,"","",0,"","","",11,0,0,[],"",""],["lafuente_madrid-p0223-03",15,"El que te quiero soy yo,\nY el que te lleva en el pecho;\nPero no quiero que quieras\nÁ ese que yo me sospecho.",210,0,-1,200,"",0,4,"eo",60,0,-1,0,223,223,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0223-04",15,"En tu casa y con idea\nEntra y sale cierto amigo.\n¿Cómo quieres que yo crea\nQue nada tiene contigo?",210,0,-1,200,"",1,4,"io",106,0,-1,0,223,223,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0223-05",15,"¿Qué tenias ayer tarde,\nQue en la ventana llorabas?\n¿Te habia dicho que no\nAquel que en la esquina estaba?",210,0,-1,200,"",0,4,"aa",-1,0,-1,0,223,223,"","",0,"palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0223-06",15,"Una peseta le mando\nÁ las ánimas benditas,\nPorque no ronde tu puerta\nAquel que te solicita.",210,0,-1,200,"",0,4,"ia",-1,0,-1,0,223,223,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0224-01",15,"Yo vivo de lo que como,\nY bebo lo que me dan;\nPero masco algunas cosas\nQue no las puedo tragar.",210,0,-1,200,"",0,4,"a",-1,0,-1,0,224,224,"","",0,"rm_t3, palau_cantares, leonesas_diez","","",5,0,0,[],"",""],["lafuente_madrid-p0224-02",15,"El corazon tengo herido,\nY la sangre la provoco\nDesde que te ví ayer tardo\nPelar la pava con otro.",210,0,-1,200,"",0,4,"oo",-1,0,-1,0,224,224,"","",0,"","","",6,0,0,[],"",""],["lafuente_madrid-p0224-03",15,"Más quisiera verte, niña,\nEmbarcadita en la mar,\nQue no pasar por tu puerta,\nY verte con otro hablar.",210,0,-1,200,"",0,4,"a",21,0,-1,0,224,224,"","",0,"","","",6,0,0,[],"",""],["lafuente_madrid-p0224-04",15,"Aunque me veas hablar\nCon el lucero del dia,\nÁ tí no te dé cuidado,\nQue es conversacion perdida.",210,0,-1,200,"",0,4,"ia",-1,0,-1,0,224,224,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0224-05",15,"Aunque me veas con otras,\nNo tomes celos por mí;\nTodas me parecen feas,\nCuando me acuerdo de ti.",210,0,-1,200,"",0,4,"i",23,0,-1,0,224,224,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0224-06",15,"Quisiera abrir en tu pecho\nUna pequeña ventana,\nPara ver tu corazon\nCon quién comunica y trata.",210,0,-1,200,"",0,4,"aa",-1,0,-1,0,224,224,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0225-01",15,"Bien sé que vas á funciones:\nTe aseguro que lo siento;\nPorque suelen decir muchos\nQue siempre á rio revuelto....",210,0,-1,200,"",0,4,"eo",-1,0,-1,0,225,225,"","",0,"palau_cantares, preciso_coleccion","","",3,0,0,[],"",""],["lafuente_madrid-p0225-02",15,"Mucho se para en tu puerta\nEl sereno de esta calle,\nYo le diré que se vaya\nCon la música á otra parte.",210,0,-1,200,"",0,4,"ae",-1,0,-1,0,225,225,"","",0,"rm_t3","","",3,0,0,[],"",""],["lafuente_madrid-p0225-03",15,"El sereno de mi calle\nMe quiere quitar la novia;\nYo se lo diré esta noche\nCon el chuzo y las pistolas.",210,0,-1,200,"",0,4,"oa",-1,0,-1,0,225,225,"","",0,"","","",4,0,0,[],"",""],["lafuente_madrid-p0225-04",15,"Serrana, si tú me quieres,\nY me tienes voluntad,\nAl gachon que te camele\nDile que no vuelva más.",210,0,-1,200,"",0,4,"a",-1,0,-1,0,225,225,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0225-05",15,"Si quieres que yo te quiera,\nHas de olvidar á quien amas;\nQue sopitas añadidas\nLas como de mala gana.",210,0,-1,200,"",0,4,"aa",-1,0,-1,0,225,225,"","",0,"rm_t3, palau_cantares","","",23,0,0,[],"",""],["lafuente_madrid-p0225-06",15,"Por Dios te pido, bien mio,\nQue cuando con otra estes,\nNo le hagas los cariños\nQue á mí me sueles hacer.",210,0,-1,200,"",0,4,"e",-1,0,-1,0,225,225,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0225-07",15,"Mi amante es un veleidoso,\nQue no lo veo venir:\n¿Si se estará divirtiendo\nCon floresde otro jardin?",210,0,-1,200,"",0,4,"i",-1,0,-1,0,225,225,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0226-01",15,"Si á mi me estuviera bien\nEl andar de noche sola,\nYo sabria si mi amante\nGalantea á otra persona.",210,0,-1,200,"",0,4,"oa",-1,0,-1,0,226,226,"","",0,"rm_t3","","",2,0,0,[],"",""],["lafuente_madrid-p0226-02",15,"Esperando estoy las doce\nPara salir disfrazada,\nPor ver si hallaré á mi amante\nHablando con otra dama.",210,0,-1,200,"",0,4,"aa",-1,0,-1,0,226,226,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0226-03",15,"Porque te quiero, te celo,\nQue si no, no te celara;\nQue si yo no te quisiera,\nAunque el diablo te llevara.",210,0,-1,200,"",0,4,"aa",57,0,-1,0,226,226,"","",0,"rm_t3, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0226-04",15,"Tengo un vestido en el arca,\nQue tiene cuatro colores:\nLa ilusion y la esperanza,\nLos celos y los amores.",210,0,-1,200,"",0,4,"oe",5,0,-1,0,226,226,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0226-05",15,"«De tres colores se viste,\nSeñora, mi corazon:\nEncarnado, azul y verde,\nQue son tres flechas de amor.",210,0,-1,200,"",0,4,"o",-1,0,-1,0,226,226,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0226-06",15,"Encarnado, con que rabio:\nContra tan duro rigor,\nDesde el punto, niña hermosa,\nQue en ti puse mi aficion.",210,0,-1,200,"",0,4,"o",-1,0,-1,0,226,226,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0226-07",15,"Azul, que me matan celos,\nCuando me acuerdo de tí;\nTe suplico, dueño amado,\nTengas compasion de mi.",210,0,-1,200,"",0,4,"i",23,0,-1,0,226,226,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0227-01",15,"Y lo verde es esperanza,\nPorque alcanzarte pretendo;\nPues por tí, prenda del alma,\nNo vivo sino muriendo.»",210,0,-1,200,"",0,4,"eo",52,0,-1,0,227,227,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0227-02",15,"«Diga V., señor platero:\n¿Cuánta plata es menester\nPara engarzar unos celos\nQue me ha dado una mujer?",210,0,-1,200,"",0,4,"e",20,0,-1,0,227,227,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0227-03",15,"-Y le responde el platero.\nSi esa mujer fuera mia,\nYo le engarzara los celos\nCon palos y mala vida.»",210,0,-1,200,"",0,4,"ia",-1,0,-1,0,227,227,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0227-04",15,"Mi marido es mi marido,\nQue no es marido de nadie:\nLa que quisiere marido,\nVaya á la guerra y lo gane.",210,0,-1,200,"",0,4,"ae",-1,0,-1,0,227,227,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0227-05",15,"Á servir al rey me voy\nCon intencion de volver,\nY si te encuentro casada,\nDe tu sangre he de beber.",210,0,-1,200,"",0,4,"e",20,0,-1,0,227,227,"","",0,"palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0227-06",15,"Debajo de tu ventana\nTengo un puñal escondido,\nPara clavarlo en tu pecho\nSi no te casas conmigo.",210,0,-1,200,"",0,4,"io",-1,0,-1,0,227,227,"","",0,"rm_t3, palau_cantares","","",29,0,0,[],"",""],["lafuente_madrid-p0227-07",15,"¿Para qué vienes á verme,\nSi tienes quien te lo estorbe?\nDále gusto á esa persona,\nY ten partidas de hombre.",210,0,-1,200,"",0,4,"oe",-1,0,-1,0,227,227,"","",0,"palau_cantares, fernan_caballero","","",3,0,0,[],"",""],["lafuente_madrid-p0228-01",15,"Por esta calle, que es larga,\nMe tengo de pasear,\nPor darle gusto á una dama,\nY á un majito en qué pensar.",210,0,-1,200,"",0,4,"a",21,0,-1,0,228,228,"","",0,"rm_t3","","",3,0,0,[],"",""],["lafuente_madrid-p0228-02",15,"Si me quieres á mí solo,\nSeré una muralla firmé;\nPero si quieres á otro,\nSeré un rayo para irme.",210,0,-1,200,"",5,4,"ie",-1,0,-1,0,228,228,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0228-03",15,"Si es que piensas darme enojos\nCon esos amores nuevos,\nAunque soy niña y criatura,\nNo me acobardan los celos.",210,0,-1,200,"",0,4,"eo",-1,0,-1,0,228,228,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0228-04",15,"Si usted me quiso de golpe,\nYo lo quise de quedito;\nSi usted tiene su pichona,\nYo tengo mi pichoncito.",210,0,-1,200,"",0,4,"io",119,0,-1,0,228,228,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0228-05",15,"Soy constante y soy mudable,\nPero con tal distincion:\nConstante con quien me ama,\nY mudable con quien no.",210,0,-1,200,"",0,4,"o",-1,0,-1,0,228,228,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0228-06",15,"Si por beber de una fuente,\nHas dejado secar otra,\nOlvidar para querer,\nEsa es ignorancia loca.",210,0,-1,200,"",0,4,"oa",-1,0,-1,0,228,228,"","",0,"palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0228-07",15,"Si por querer á un paisano,\nOlvidas á un militar,\nHázte cuenta que has cambiado\nOro fino por metal.",210,0,-1,200,"",0,4,"a",-1,0,-1,0,228,228,"","",0,"rm_t3, palau_cantares, fernan_caballero","","",4,0,0,[],"",""],["lafuente_madrid-p0229-01",15,"Te diviertes con quien quieres,\nLuego vienes con achaques\nÁ recobrar lo perdido:\nEso..... ni con chocolate.",210,0,-1,200,"",0,4,"ae",-1,0,-1,0,229,229,"","",0,"rm_t3","","",5,0,0,[],"",""],["lafuente_madrid-p0229-02",15,"Te diviertes con quien quieres,\nLuego vienes, me lo niegas,\nY quieres con tu saber\nHacer á la gente ciega.",210,0,-1,200,"",0,4,"ea",-1,0,-1,0,229,229,"","",0,"rm_t3, palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0229-03",15,"Si piensas que nada sé,\nTe advierto que nada ignoro;\nQue no das paso en la calle\nQue no me lo cuenten todo.",210,0,-1,200,"",0,4,"oo",-1,0,-1,0,229,229,"","",0,"rm_t3, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0229-04",15,"Yo sé los pasos que traes,\nAunque me lo niegas siempre,\nÁndate en ese camino:\nCántaro que va á la fuente.....",210,0,-1,200,"",0,4,"ee",-1,0,-1,0,229,229,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0229-05",15,"Te quiero más que si fueras\nHijito de mis entrañas;\nPero si quieres á otra,\n¿Porqué no me désengañas?",210,0,-1,200,"",5,4,"ea",-1,0,-1,0,229,229,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0229-06",15,"Tú tienes amor con otra,\nY quieres amor conmigo;\nTú quieres partir amor,\nYo no quiero amor partido.",210,0,-1,200,"",0,4,"io",-1,0,-1,0,229,229,"","",0,"rm_t3, palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0229-07",15,"Tú tienes amor con otra,\nY conmigo las chancitas;\nSi te quieres divertir,\nCompra un trompo y una guila.",210,0,-1,200,"",0,4,"ia",-1,0,-1,0,229,229,"","",0,"","","",5,0,0,[],"",""],["lafuente_madrid-p0230-01",15,"Todo el mundo me lo dice;\nDigo que tienen razon:\nQue hombre que trata con mucha\nÁninguna tiene amor.",210,0,-1,200,"",0,4,"o",-1,0,-1,0,230,230,"","",0,"","","",14,0,0,[],"",""],["lafuente_madrid-p0230-02",15,"Todo el mundo me lo dice,\nYo acredito esta verdad:\nEn estando un hombre ausente,\nOtro ocupa su lugar.",210,0,-1,200,"",0,4,"a",-1,0,-1,0,230,230,"","",0,"palau_cantares","","",14,0,0,[],"",""],["lafuente_madrid-p0230-03",15,"Causa de mi perdicion,\nQuiero apartarme de tí:\nLa mujer que quiere á dos\nNo puede tener buen fin.",210,0,-1,200,"",0,4,"i",-1,0,-1,0,230,230,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0230-04",15,"Yo pensé que era á mi solo,\nSerrana, á quien tú querias,\n¡Y te diviertes con otro\nTodas las horas del dia!",210,0,-1,200,"",0,4,"ia",-1,0,-1,0,230,230,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0230-05",15,"En el jardin de mi reina\nEra jardinero yo,\nY en tiempo de coger rosas\nOtro jardinero entró.",210,0,-1,200,"",0,4,"o",2,0,-1,0,230,230,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0230-07",15,"Si piensas que son ganancias\nEl tener á muchos ley,\nEs tan solo una ignorancia\nQue las mujeres teneis.",210,0,-1,200,"",0,4,"e",-1,0,-1,0,230,230,"","",0,"rm_t3","","",2,0,0,[],"",""],["lafuente_madrid-p0231-01",15,"¿Para qué me diste el si,\nTraidora, teniendo dueño,\nSi sabes que no se logra\nCon gusto lo que es ajeno?",210,0,-1,200,"",0,4,"eo",-1,0,-1,0,231,231,"","",0,"rm_t3, palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0231-02",15,"¿Para qué me andas diciendo\nQue me quieres y me adoras,\nSi en volviendo las espaldas\nDe cualquiera te enamoras?",210,0,-1,200,"",0,4,"oa",198,0,-1,0,231,231,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0231-03",15,"Ingrata, mala mujer,\nDe Dios te venga el castigo:\n¿Si te has te casar con otro,\nPara qué tratas conmigo?",210,0,-1,200,"",0,4,"io",106,0,-1,0,231,231,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0231-04",15,"Yo te quise, no pensando\nQue me habias de olvidar;\nTú juegas con dos barajas,\nY yo con una no más.",210,0,-1,200,"",0,4,"a",-1,0,-1,0,231,231,"","",0,"rm_t3, palau_cantares, fernan_caballero","","",5,0,0,[],"",""],["lafuente_madrid-p0231-05",15,"¿Cómo quieres que una luz\nAlumbre á dos aposentos?\n¿Cómo quieres que yo quiera\nDos corazones á un tiempo?",210,0,-1,200,"",0,4,"eo",-1,0,-1,0,231,231,"","",0,"palau_cantares","","",7,0,0,[],"",""],["lafuente_madrid-p0231-06",15,"Yo pensé que de tu pecho\nYo solo tenia llave;\nMas he llegado á entender\nQue todo el que quiere abre.",210,0,-1,200,"",0,4,"ae",-1,0,-1,0,231,231,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0232-01",15,"Plato de segunda mesa\nNunca en mi vida lo he sido;\nSi ahora quieres que lo sea,\nEstás muy mal entendido.",210,0,-1,200,"",0,4,"io",101,0,-1,0,232,232,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0232-02",15,"Cuando por tu puerta paso,\nEl corazon se me enluta\nDe ver que no hay más que un árbol,\nY hay muchos para la fruta.",210,0,-1,200,"",0,4,"ua",197,0,-1,0,232,232,"","",0,"rm_t3, palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0232-03",15,"Tú desprecias mis trapitos,\nY te vas con los galones;\n¡Un remiendo mal pegado\nSe lleva las atenciones!",210,0,-1,200,"",0,4,"oe",34,0,-1,0,232,232,"","",0,"rm_t3","","",2,0,0,[],"",""],["lafuente_madrid-p0232-04",15,"«Capitana de ingenieros\nPensaste que ibas á ser;\nTus gentes te lo dijeron,\nY el capitan te se fué.",210,0,-1,200,"",0,4,"e",-1,0,-1,0,232,232,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0232-05",15,"¡Con qué dolor lo refiero!\n¡Con qué penilla lo digo!\n¡El capitan de ingenieros\nYa no se casa contigo!»",210,0,-1,200,"",0,4,"io",106,0,-1,0,232,232,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0232-06",15,"Cuando me dieron la nueva\nDe que tú no me querias,\nHasta el gato de mi casa\nMe miraba y se reia.",210,0,-1,200,"",0,4,"ia",-1,0,-1,0,232,232,"","",0,"palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0232-07",15,"Gitanilla como yo\nNo la tienes de encontrar,\nAunque gitana se vuelva\nTodita la cristiandad.",210,0,-1,200,"",0,4,"a",-1,0,-1,0,232,232,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0233-01",15,"Si todo el mundo corrieras,\nFácil te será encontrar\nOtro amante á quien tú quieras,\nMas no que te quiera más.",210,0,-1,200,"",0,4,"a",-1,0,-1,0,233,233,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0233-02",15,"¿De qué te sirve llorar,\nY dar vueltas como un loco,\nSi tú te mueres por ella,\nY ella se muere por otro?",210,0,-1,200,"",0,4,"oo",-1,0,-1,0,233,233,"","",0,"palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0233-03",15,"Un rayo caiga del cielo,\nY me parta por mitad,\nAntes de verte, morena,\nEn manos de otro galan.",210,0,-1,200,"",0,4,"a",-1,0,-1,0,233,233,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0233-04",15,"Haré un hoyito en la arena,\nY vivo me enterraré,\nPor no ver en mano ajena\nPrenda que tanto adoré.",210,0,-1,200,"",1,4,"e",77,0,-1,0,233,233,"","",0,"palau_cantares, andina_t2","","",5,0,0,[],"",""],["lafuente_madrid-p0233-05",15,"Dicen que te casas pronto,\nY yo pretendo saber\nEl cómo, con quién y cuándo,\nEl cuándo, cómo y con quién.",210,0,-1,200,"",0,4,"e",-1,0,-1,0,233,233,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0233-06",15,"«Me han dicho que tú te casas;\nAsí lo dice la gente;\nY todo será en un dia,\nTu casamiento y mi muerte.",210,0,-1,200,"",0,4,"ee",-1,0,-1,0,233,233,"","",0,"palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0235-01",15,"Te llevarán á la iglesia\nLa madrina y el padrino,\nY á mí me estarán llevando\nEn hombros de cuatro amigos.",210,0,-1,200,"",0,4,"io",-1,0,-1,0,235,235,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0235-02",15,"Te llevarán á acostar\nCon alegría y contento,\nY á mí me estarán echando\nEn la tierra con los muertos.»",210,0,-1,200,"",0,4,"eo",-1,0,-1,0,235,235,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0235-03",15,"¡Cuántas veces pasarás\nPor donde yo esté enterrado,\nY ni siquiera dirás:\n¡Qué Dios te haya perdonado!",210,0,-1,200,"",1,4,"ao",14,0,-1,0,235,235,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0235-04",15,"Cada vez que considero\nQue te has casado por fin,\nLlamo á la muerte, y le digo:\n¿Cuándo has de venir por mi?",210,0,-1,200,"",0,4,"i",-1,0,-1,0,235,235,"","",0,"rm_t3, palau_cantares","","",14,0,0,[],"",""],["lafuente_madrid-p0235-05",15,"Eres como el gallo inglés\nQue á todos les haces cara;\nHázte, niña, mesonera,\nY á todos darás posada.",210,0,-1,200,"",0,4,"aa",-1,0,-1,0,235,235,"","",0,"rm_t3","","",4,0,0,[],"",""],["lafuente_madrid-p0235-06",15,"¿Cómo quieres que te tenga\nUna firme voluntad,\nSi eres venta de camino\nQue á todos les das posá?",210,0,-1,200,"",0,4,"a",-1,0,-1,0,235,235,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0236-01",15,"¿Cómo quieres que te quiera,\nNi ponga mi amor en tí,\nSi eres como la veleta,\nHoy aqui, mañana allí?",210,0,-1,200,"",0,4,"i",23,0,-1,0,236,236,"","",0,"","","",16,0,0,[],"",""],["lafuente_madrid-p0236-02",15,"Eres como la veleta\nQue está encima de la torre:\nViene un viento y otro viento,\nY á todos les corresponde.",210,0,-1,200,"",0,4,"oe",-1,0,-1,0,236,236,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0236-03",15,"Tu querer es como el toro,\nQue á donde lo llaman va;\nEl mio como la piedra,\nDonde la ponen se está.",210,0,-1,200,"",0,4,"a",9,0,-1,0,236,236,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0236-04",15,"Como los torillos bravos\nTienes, gitana, el arranque;\nQue no te acuerdas de mi\nSino cuando estoy delante.",210,0,-1,200,"",0,4,"ae",-1,0,-1,0,236,236,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0236-05",15,"Tu querer es como el charco,\nEl mio como la fuente.\nSale el sol, se seca el charco,\nY la fuente permanece.",210,0,-1,200,"",0,4,"ee",-1,0,-1,0,236,236,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0236-06",15,"Tu querer lo he comparado\nCon los pesos de la carne,\nQue aunque los den muy corridos,\nNunca resultan cabales.",210,0,-1,200,"",0,4,"ae",-1,0,-1,0,236,236,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0236-07",15,"Tu querer lo he comparado\nCon el correo de Vélez,\nQue en cayendo cuatro gotas,\nSe le mojan los papeles.",210,0,-1,200,"",0,4,"ee",97,0,-1,0,236,236,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0237-01",15,"Tienes nubes como el cielo,\nMareas como la mar,\nMudanzas como los vientos,\nY luego te ha de pesar.",210,0,-1,200,"",0,4,"a",21,0,-1,0,237,237,"","",0,"rm_t3, palau_cantares, fernan_caballero","","",4,0,0,[],"",""],["lafuente_madrid-p0237-02",15,"Al barquillo que en la mar\nEstá pegando vaivenes,\nTengo yo comparadita\nLa voluntad que me tienes.",210,0,-1,200,"",0,4,"ee",120,0,-1,0,237,237,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0237-03",15,"Mi amor está en tenguerengue\nComo el navío en la mar;\nY como está en tenguerengue,\nYa se viene, ya se va.",210,0,-1,200,"",0,4,"a",-1,0,-1,0,237,237,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0237-04",15,"Á la mar tengo de irme\nÁ llorar mi sentimiento,\nPues que puse mi querer\nEn un molino de viento.",210,0,-1,200,"",0,4,"eo",94,0,-1,0,237,237,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0237-05",15,"Puse al cielo una querella,\nY respondieron los aires\nQue mi querer no lo ponga\nDonde firmeza no halle.",210,0,-1,200,"",0,4,"ae",-1,0,-1,0,237,237,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0237-06",15,"Estándote yo queriendo\nCon la voluntad que sabes,\nCon una llave maestra\nDescubri tus falsedades.",210,0,-1,200,"",0,4,"ae",-1,0,-1,0,237,237,"","",0,"rm_t3","","",2,0,0,[],"",""],["lafuente_madrid-p0237-07",15,"Eres hermosa en extremo;\nPero tienes una falta:\nQue en el campo hay varias flores,\nY tú tambien eres varia.",210,0,-1,200,"",0,4,"aa",-1,0,-1,0,237,237,"","",0,"rm_t3, palau_cantares","","",7,0,0,[],"",""],["lafuente_madrid-p0238-01",15,"De la retama la rama,\nDel saúco la corteza,\nNo son cosas más amargas\nQue amor donde no hay firmeza.",210,0,-1,200,"",0,4,"ea",108,0,-1,0,238,238,"","",0,"fernan_caballero, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0238-02",15,"Entre todos sus vasallos\nNo ha conocido el amor\nMujer más falsa que tú,\nNi hombre más firme que yo.",210,0,-1,200,"",0,4,"o",-1,0,-1,0,238,238,"","",0,"rm_t3, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0238-03",15,"Eres una y eres dos,\nEres tres y eres cuarenta,\nEres iglesia mayor\nDonde todo el mundo entra.",210,0,-1,200,"",0,4,"ea",-1,0,-1,0,238,238,"","",0,"palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0238-04",15,"Porque te ví desde lejos,\nPor eso te quiero tanto;\nHaces bien en no acercarte,\nDe cerca pierde lo falso.",210,0,-1,200,"",0,4,"ao",-1,0,-1,0,238,238,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0238-05",15,"Una serrana me ha dicho,\nDe tu misma serranía,\nQue ningun hombre pequeño\nPuede hacer buenas partidas.",210,0,-1,200,"",0,4,"ia",-1,0,-1,0,238,238,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0238-06",15,"Á mi no me queman chispas\nDe la más ardiente fragua,\nLas que me queman á mi\nSon tus partidas serranas.",210,0,-1,200,"",0,4,"aa",-1,0,-1,0,238,238,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0239-01",15,"En los libros del olvido\nManda mi Dios que te ponga,\nPorque tu querer ha sido\nComo cangilon de noria.",210,0,-1,200,"",0,4,"oa",-1,0,-1,0,239,239,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0239-02",15,"Como cangilon de noria\nSon tus partidas, serrana;\nQue unos suben agua buena,\nY otros suben agua mala.",210,0,-1,200,"",0,4,"aa",-1,0,-1,0,239,239,"","",0,"rm_t3","","",3,0,0,[],"",""],["lafuente_madrid-p0239-03",15,"Yo soy serranita buena\nPor todos cuatro costados;\nSi tengo malas partidas,\nDe tí se me habrán pegado.",210,0,-1,200,"",0,4,"ao",-1,0,-1,0,239,239,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0239-04",15,"Tan fácil es ver un hombre\nQue tenga buenas partidas,\nComo el hacer un bautismo\nEn tierra de morería.",210,0,-1,200,"",0,4,"ia",-1,0,-1,0,239,239,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0240-01",15,"Si quieres que te lo diga,\nTe lo diré en dos razones:\nEres hombre de dos caras\nY de malas condiciones.",210,0,-1,200,"",0,4,"oe",34,0,-1,0,240,240,"","",0,"rm_t3, carrizo_salta, palau_cantares","","",9,0,0,[],"",""],["lafuente_madrid-p0240-02",15,"Aunque te pongas en cruz,\nNo te tengo de creer;\nPorque ya sé lo que valen\nJuramentos de mujer.",210,0,-1,200,"",0,4,"e",20,0,-1,0,240,240,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0240-03",15,"El querer que me tenias\nEn una rama quedó;\nVino un fuerte remolino,\nRama y tronco se llevó.",210,0,-1,200,"",0,4,"o",2,0,-1,0,240,240,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0240-04",15,"Si me quieres escribir,\nYo te diré donde vivo:\nEn la calle de Firmeza,\nDonde tú nunca has vivido.",210,0,-1,200,"",0,4,"io",-1,0,-1,0,240,240,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0240-05",15,"Ya yo no vivo en la calle\nDonde usté me conoció;\nAhora vivo en la plazuela\nDel Desengaño mayor.",210,0,-1,200,"",0,4,"o",-1,0,-1,0,240,240,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0240-06",15,"Pareces una paloma\nCuando por la calle vas;\nCon el meneo que llevas\n¡Á cuántos engañarás!",210,0,-1,200,"",0,4,"a",51,0,-1,0,240,240,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0241-01",15,"Si yo me hubiera sabido\nQue era tu pecho traidor,\nNo me hubiera yo embarcado\nEn tan mala embarcacion.",210,0,-1,200,"",0,4,"o",-1,0,-1,0,241,241,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0241-02",15,"Una escopeta, en que yo\nTenia mi confianza,\nAl fin me dió gatillazo.\n¿Qué será las que son falsas?",210,0,-1,200,"",0,4,"aa",-1,0,-1,0,241,241,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0241-03",15,"Tengo que hacer un castillo\nEncima de un alfiler,\nY ha de tener más firmeza,\nQue ha tenido tu querer.",210,0,-1,200,"",0,4,"e",20,0,-1,0,241,241,"","",0,"palau_cantares, fernan_caballero","","",3,0,0,[],"",""],["lafuente_madrid-p0241-04",15,"De la torre de mis gustos\nEn lo más alto me vi;\nFueron los cimientos falsos,\nY en lo profundo caí.",210,0,-1,200,"",0,4,"i",23,0,-1,0,241,241,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0241-05",15,"Las apariencias de Judas,\nSerrana, me estás haciendo:\nPor delante buena cara,\nPor detrás me estás vendiendo.",210,0,-1,200,"",0,4,"eo",52,0,-1,0,241,241,"","",0,"rm_t3","","",2,0,0,[],"",""],["lafuente_madrid-p0241-06",15,"De los hábitos de Judas\nHe de hacerte un delantal,\nPara que lleves delante\nInsignias de falsedad.",210,0,-1,200,"",0,4,"a",-1,0,-1,0,241,241,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0242-01",15,"Ven acá, falsa y refalsa;\nFalsa, te vuelvo á decir,\nEl dia que me vendiste\n¿Cuánto te dieron por mi?",210,0,-1,200,"",0,4,"i",-1,0,-1,0,242,242,"","",0,"rm_t3, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0242-02",15,"Me dijistes «¡agua va!»\nAl tiempo que me la echaste;\nNo me dejaste mirar\nLa falsedad con que hablaste.",210,0,-1,200,"",0,4,"ae",212,0,-1,0,242,242,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0242-03",15,"«El pañuelo que me diste\nDe puntillas de alamares,\nYo pensé que eran firmezas,\nY eran puras falsedades.",210,0,-1,200,"",0,4,"ae",-1,0,-1,0,242,242,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0242-04",15,"Si eran puras falsedades,\nSeñora, perdone usté;\nQue yo he caido en mi yerro,\nY sé que me enmendaré.",210,0,-1,200,"",0,4,"e",77,0,-1,0,242,242,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0242-05",15,"Dijiste que te enmendabas,\nNo te has querido enmendar;\nDaré cuenta á la justicia\nPara alivio de mi mal.",210,0,-1,200,"",0,4,"a",-1,0,-1,0,242,242,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0242-06",15,"No des cuenta á la justicia,\nMírame con caridad;\nQue si prenden á tu amante\nLágrimas te ha de costar.",210,0,-1,200,"",0,4,"a",-1,0,-1,0,242,242,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0242-07",15,"Si es que lágrimas me cuesta,\nTe lo juro por mi nombre,\nEs el haberte querido,\nPicaro, traidor, mal hombre.",210,0,-1,200,"",0,4,"oe",220,0,-1,0,242,242,"","",0,"rm_t3","","",2,0,0,[],"",""],["lafuente_madrid-p0243-01",15,"Picaro, traidor, mal hombre.\nSeñora, sé que lo he sido;\nÁ tus plantas muy humilde\nPor eso perdon te pido.",210,0,-1,200,"",0,4,"io",101,0,-1,0,243,243,"","",0,"rm_t3","","",2,0,0,[],"",""],["lafuente_madrid-p0243-02",15,"Por mí, ya estás perdonado,\nPor mi padre, no lo sé;\nVen mañana á la oracion,\nLa respuesta te daré.",210,0,-1,200,"",0,4,"e",77,0,-1,0,243,243,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0243-03",15,"Aquí me teneis, señora,\nCon muchisima humildad\nEsperando la respuesta\nQue me tenias que dar.",210,0,-1,200,"",0,4,"a",-1,0,-1,0,243,243,"","",0,"rm_t3","","",2,0,0,[],"",""],["lafuente_madrid-p0243-04",15,"La respuesta que te doy\nEs que mi padre no quiere\nQue yo me case contigo,\nPor la condicion que tienes. »",210,0,-1,200,"",0,4,"ee",-1,0,-1,0,243,243,"","",0,"rm_t3","","",2,0,0,[],"",""],["lafuente_madrid-p0243-05",15,"Desciendes de mala rama,\nNo lo puedes remediar:\nLas mujeres y caballos\nPor casta se han de buscar.",210,0,-1,200,"",0,4,"a",21,0,-1,0,243,243,"","",0,"fernan_caballero, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0243-06",15,"Del jardin salen las rosas,\nDe la marina los peces,\nDe mi corazon traiciones\nPara tí que las mereces.",210,0,-1,200,"",0,4,"ee",196,0,-1,0,243,243,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0243-07",15,"Dentro de mi pecho tengo\nUna mesa de cristal,\nDonde juegan á los naipes\nMi amor y tu falsedad.",210,0,-1,200,"",0,4,"a",-1,0,-1,0,243,243,"","",0,"rm_t3, palau_cantares","","",32,0,0,[],"",""],["lafuente_madrid-p0244-01",15,"Á mí no me gustan plantas,\nMozo bueno, escuche usté,\nLo que me gustan son obras,\nY esas no las tiene usté.",210,0,-1,200,"",0,4,"e",-1,0,-1,0,244,244,"","",0,"","","",4,0,0,[],"",""],["lafuente_madrid-p0244-02",15,"Una palabra me diste\nQue nunca me cumplirás;\nYo sí cumpliré la mia\nDe no olvidarte jamás.",210,0,-1,200,"",0,4,"a",-1,0,-1,0,244,244,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0244-03",15,"Aunque en una cruz te pongas\nVestido de Nazareno,\nY las tres caidas des,\nEn tus palabras no creo.",210,0,-1,200,"",0,4,"eo",-1,0,-1,0,244,244,"","",0,"palau_cantares","","",7,0,0,[],"",""],["lafuente_madrid-p0244-04",15,"La palabra que me diste\nÁ la orilla de la fuente,\nComo fué cerca del agua,\nSe la llevó la corriente.",210,0,-1,200,"",0,4,"ee",15,0,-1,0,244,244,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0244-05",15,"La vara de san José\nTodos los años florece:\nLa palabra de los hombres\nSe ha perdido, y no parece.",210,0,-1,200,"",0,4,"ee",64,0,-1,0,244,244,"","",0,"rm_t4, fernan_caballero","","",5,0,0,[],"",""],["lafuente_madrid-p0244-06",15,"Todos los hombres son falsos,\nZalameros y embusteros.\nAl que le toque esa china\nQue se la eche en el sombrero.",210,0,-1,200,"",0,4,"eo",-1,0,-1,0,244,244,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0244-07",15,"Todo el que no fuese hombre\nPara cumplir su palabra,\nQue se quite los calzones,\nY que se ponga unas naguas.",210,0,-1,200,"",0,4,"aa",-1,0,-1,0,244,244,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0245-01",15,"En los arcos de Toledo\nHan hecho una cárcel nueva\nPara los enamorados\nQue dan palabra, y la niegan.",210,0,-1,200,"",0,4,"ea",-1,0,-1,0,245,245,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0245-02",15,"Si en tu casa no me quieren,\nÁ tí tampoco en la mia;\nNos iremos á una cueva,\nComo santa Rosalía.",210,0,-1,200,"",0,4,"ia",0,0,-1,0,245,245,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0245-03",15,"¿De qué le sirve á tu madre\nMachacar en hierro frio,\nSi ha de tener á sú lado\nLo que tiene aborrecido?",210,0,-1,200,"",0,4,"io",-1,0,-1,0,245,245,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0245-04",15,"Se pone tu madre y dice:\nQue se alegra de mi mal;\nSi la lengua se le balda,\nYo tambien me he de alegrar.",210,0,-1,200,"",0,4,"a",-1,0,-1,0,245,245,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0245-05",15,"Tu gente no está gustosa\nDe que me quieras á mí;\nNo es ninguna penitencia\nQue se tenga que cumplir.",210,0,-1,200,"",0,4,"i",-1,0,-1,0,245,245,"","",0,"rm_t3","","",3,0,0,[],"",""],["lafuente_madrid-p0245-06",15,"Cada cual siente su pena\nYo siento la mia doble:\nNo me quieren en tu casa,\nPorque dicen que soy pobre.",210,0,-1,200,"",0,4,"oe",-1,0,-1,0,245,245,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0246-01",15,"Si tu madre me desprecia,\nPorque dice que soy pobre,\nEl mundo da muchas vueltas:\nAyer se cayó una torre.",210,0,-1,200,"",0,4,"oe",-1,0,-1,0,246,246,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0246-02",15,"Anda diciendo tu madre\nQue conmigo estás perdiendo,\nY estás ganando conmigo\nUn veinticinco por ciento.",210,0,-1,200,"",0,4,"eo",-1,0,-1,0,246,246,"","",0,"rm_t3","","",23,0,0,[],"",""],["lafuente_madrid-p0246-03",15,"Déjame, prenda, por Dios,\nPlaticar, aunque sea pobre;\nQue un grillo vale dos cuartos,\nY con todo, se le oye,",210,0,-1,200,"",0,4,"oe",-1,0,-1,0,246,246,"","",0,"rm_t2, palau_cantares, fernan_caballero","","",4,0,0,[],"",""],["lafuente_madrid-p0246-04",15,"Corre, ve, y dile á tu madre\nQue no hable mal de mí,\nQue pérdidas y ganancias\nTodas caerán sobre tí.",210,0,-1,200,"",0,4,"i",23,0,-1,0,246,246,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0246-05",15,"Contigo, siempre contigo,\nContigo y hasta morir;\nPero con tu madre no,\nPorque ha hablado mal de mi.",210,0,-1,200,"",0,4,"i",-1,0,-1,0,246,246,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0246-06",15,"Me han dicho que andas haciendo\nPesquisas de mi linaje;\n¡Como si tú descendieras\nDe algunos Abencerrajes!",210,0,-1,200,"",0,4,"ae",-1,0,-1,0,246,246,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0247-01",15,"Yo te estoy queriendo á ti\nSin saber lo que me hago;\nLo que llegaré á sentir\nQue luego me des mal pago.",210,0,-1,200,"",0,4,"ao",207,0,-1,0,247,247,"","",0,"","","",4,0,0,[],"",""],["lafuente_madrid-p0247-02",15,"Que te quiero no lo ignores,\nQue te adoro, sol divino;\nLo que llegaré á sentir\nQue yo sirva de interino.",210,0,-1,200,"",0,4,"io",199,0,-1,0,247,247,"","",0,"rm_t3","","",2,0,0,[],"",""],["lafuente_madrid-p0247-03",15,"Si mi amante fuera amante\nQue me supiera estimar,\nTengo yo para mi amante\nUn corazon muy leal.",210,0,-1,200,"",0,4,"a",-1,0,-1,0,247,247,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0247-04",15,"La yerba buena se cria\nEn la corriente del agua.\n¿Para qué me quieres hoy,\nSi me has de olvidar mañana?",210,0,-1,200,"",0,4,"aa",-1,0,-1,0,247,247,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0247-05",15,"Si me has de olvidar mañana,\nOlvídame luego al punto,\nPorque yo quiero que sea\nEl llanto sobre el difunto.",210,0,-1,200,"",0,4,"uo",36,0,-1,0,247,247,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0247-06",15,"No sé como tienes manos\nPara lavarte la cara,\nNi peinarte los cabellos\nSabiendo lo que me pasa",210,0,-1,200,"",0,4,"aa",-1,0,-1,0,247,247,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0248-01",15,"Yo te quiero, tú á mí no;\nYo te amo, tú me aborreces,\nYo te trato con cariño,\nY tú á mí con esquiveces.",210,0,-1,200,"",0,4,"ee",196,0,-1,0,248,248,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0248-02",15,"Te quise porque te vi,\nY te vi porque Dios quiso,\nY al ver cuán poco me quieres,\nMe pesa de haberte visto.",210,0,-1,200,"",0,4,"io",-1,0,-1,0,248,248,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0248-03",15,"Mi vida la escribiré,\nY la llevaré á la imprenta,\nY á voces publicaré\nLo que tu querer me cuesta.",210,0,-1,200,"",0,4,"ea",-1,0,-1,0,248,248,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0248-04",15,"En el fuego en que me abraso\nTe quisiera ver arder,\nPara que sepas, ingrata,\nLo que cuesta un buen querer",210,0,-1,200,"",0,4,"e",20,0,-1,0,248,248,"","",0,"carrizo_salta, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0248-05",15,"¡Ya no te acuerdas de mi,\nCorazon de piedra dura,\nSabiendo que yo por tí\nPaso ratos de amargura!",210,0,-1,200,"",1,4,"ua",17,0,-1,0,248,248,"","",0,"rm_t3, carrizo_salta, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0248-06",15,"¡Lo que he pasado por tí!\n¡Tu querer cómo me ha puesto!\nQue con un aguamanil\nMe están dando el alimento!",210,0,-1,200,"",0,4,"eo",-1,0,-1,0,248,248,"","",0,"rm_t3","","",2,0,0,[],"",""],["lafuente_madrid-p0249-01",15,"Por tu querer, chachipé,\nMe veo de esta manera:\nArriado y sin parné,\nY sin tener quien me quiera.",210,0,-1,200,"",1,4,"ea",44,0,-1,0,249,249,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0249-02",15,"Compadécete de mi,\nQue tienes el corazon\nMás duro que las columnas\nDel templo de Salomon.",210,0,-1,200,"",0,4,"o",31,0,-1,0,249,249,"","",0,"palau_cantares, fernan_caballero","","",3,0,0,[],"",""],["lafuente_madrid-p0249-03",15,"Tengo pasadas por tí\nMás penas y más fatigas,\nQue pasan los marineros\nEn el Callao de Lima.",210,0,-1,200,"",0,4,"ia",-1,0,-1,0,249,249,"","",0,"palau_cantares, fernan_caballero","","",4,0,0,[],"",""],["lafuente_madrid-p0249-04",15,"Por tí no tengo sosiego.\nPor tí no duermo ni como,\nY aunque ves que estoy muriendo,\nTe desentiendes de todo.",210,0,-1,200,"",0,4,"oo",-1,0,-1,0,249,249,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0249-05",15,"La guitarra y la escopeta\nLas acabo de vender;\nDe todo tiene la culpa\nEl querer á esa mujer.",210,0,-1,200,"",0,4,"e",20,0,-1,0,249,249,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0250-01",15,"Si fueras serrana pura,\nY tuvieras buena la sangre,\nTe pusieras la mantilla,\nY vinieras á buscarme.",210,0,-1,200,"",0,4,"ae",-1,0,-1,0,250,250,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0250-02",15,"Si de mi cuerpo sacaran\nLa sangre por cuarterones,\nNo lo sentiria tanto\nComo siento tus razones.",210,0,-1,200,"",0,4,"oe",34,0,-1,0,250,250,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0250-03",15,"Yo no sé lo que hacerme\nAtento de tu querer,\nSi lo deje por la mano,\nO si me pierda por él.",210,0,-1,200,"",0,4,"e",-1,0,-1,0,250,250,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0250-04",15,"Yo te iré sobrellevando\nHasta que no pueda más;\nQue muchas gotas de cera\nHacen un cirio pascual.",210,0,-1,200,"",0,4,"a",-1,0,-1,0,250,250,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0250-05",15,"Anda, véte, que no quiero\nPasar por ti mas fatigas;\nTe portas como quien eres:\n¿Qué más quieres que te diga?",210,0,-1,200,"",0,4,"ia",-1,0,-1,0,250,250,"","",0,"rm_t3, palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0250-06",15,"Si porque te ves querida,\nMe niegas la voluntad,\nYo he visto una casa nueva\nDerribarla un vendaval.",210,0,-1,200,"",0,4,"a",-1,0,-1,0,250,250,"","",0,"palau_cantares","","",7,0,0,[],"",""],["lafuente_madrid-p0250-07",15,"Si porque te ves querida,\nHaces de mí lo que haces,\nMira que Dios no es tan viejo,\nQue todos los años nace.",210,0,-1,200,"",0,4,"ae",-1,0,-1,0,250,250,"","",0,"rm_t3, palau_cantares","","",7,0,0,[],"",""],["lafuente_madrid-p0251-01",15,"Como ves que yo me esmero\nEn adorarte y quererte,\nPor eso, claro lucero,\nMe pagas tan malamente.",210,0,-1,200,"",0,4,"ee",-1,0,-1,0,251,251,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0251-02",15,"Si el querer bien se pagara,\n¡Cuánto me fueras debiendo!\nPero como no se paga,\nNi me debes, ni te debo.",210,0,-1,200,"",0,4,"eo",-1,0,-1,0,251,251,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0251-03",15,"Como sabes, ángel bello,\nQue yo me muero por ti,\nTienes el gusto cifrado\nEn darme á mí que sentir",210,0,-1,200,"",0,4,"i",-1,0,-1,0,251,251,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0251-04",15,"Mi querer y tu querer\nSon dos quereres en uno;\nY siempre estamos riñendo\nPor si es mio ó por si es tuyo.",210,0,-1,200,"",0,4,"uo",-1,0,-1,0,251,251,"","",0,"rm_t3, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0251-05",15,"De las tres flores de lis\nÁ mi amante le dí un ramo;\nComo no supo querer,\nSe le ha secado en la mano.",210,0,-1,200,"",0,4,"ao",-1,0,-1,0,251,251,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0251-06",15,"Tú estas jugando conmigo\nComo si fuera al billar,\nY tengo de hacer contigo\nUna que ha de ser soná.",210,0,-1,200,"",0,4,"a",-1,0,-1,0,251,251,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0251-07",15,"Anda, ve, y dile al maestro,\nAl que te enseñó á querer,\nQue te vuelva tu dinero,\nPorque no te enseñó bien.",210,0,-1,200,"",0,4,"e",-1,0,-1,0,251,251,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0252-01",15,"Camaradita del alma,\nUsté no sabe querer:\nLas mujeres se manejan\nCon la puntilla del pié.",210,0,-1,200,"",0,4,"e",-1,0,-1,0,252,252,"","",0,"","","",4,0,0,[],"",""],["lafuente_madrid-p0252-02",15,"De noche me bajo al patio,\nY me harto de llorar\nDe ver que te quiero tanto,\nY tú no me quieres naa.",210,0,-1,200,"",5,4,"aa",-1,0,-1,0,252,252,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0252-03",15,"Con mucho gusto te miro,\nCon poco gusto me ves;\nMira, pues, si hay diferencia\nDe tu amor á mi querer.",210,0,-1,200,"",0,4,"e",-1,0,-1,0,252,252,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0252-04",15,"Si tienes un corazon\nPara amarme tan de hielo,\nAcércate, ingrata, al mio,\nY verás como es de fuego.",210,0,-1,200,"",0,4,"eo",-1,0,-1,0,252,252,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0252-05",15,"Mi corazon se derrite\nDe pena y de sentimiento\nDe ver que tú no me quieres\nTanto como yo te quiero.",210,0,-1,200,"",0,4,"eo",-1,0,-1,0,252,252,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0253-01",15,"De tu ventana á la mia\nMe tirastes un limon,\nEl limon cayó en el suelo,\nEl agrio en mi corazon.",210,0,-1,200,"",0,4,"o",31,0,-1,0,253,253,"","",0,"palau_cantares","","",10,0,0,[],"",""],["lafuente_madrid-p0253-02",15,"Dentro de mi pecho tengo\nDos escaleras de vidrio;\nPor una baja el amor,\nPor otra sube el olvido.",210,0,-1,200,"",0,4,"io",-1,0,-1,0,253,253,"","",0,"palau_cantares","","",32,0,0,[],"",""],["lafuente_madrid-p0253-03",15,"En medio de mis fatigas\nUna maldicion te eché:\nLa sal no te llegue al agua,\nSi olvidas á tu querer.",210,0,-1,200,"",0,4,"e",-1,0,-1,0,253,253,"","",0,"palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0253-04",15,"No me seas retrechera,\nQue te habré de comparar\nCon el reloj de Pamplona,\nQue apunta, pero no da.",210,0,-1,200,"",0,4,"a",-1,0,-1,0,253,253,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0253-05",15,"Si me pagas con desdenes,\nSeré como el ruiseñor,\nQue me pondré entre las hojas\nÁ llorar mi perdicion.",210,0,-1,200,"",0,4,"o",-1,0,-1,0,253,253,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0253-06",15,"Permita Dios de los cielos\nQue como me matas mueras,\nY que te vean mis ojos\nQuerer sin que á tí te quieran.",210,0,-1,200,"",0,4,"ea",-1,0,-1,0,253,253,"","",0,"palau_cantares, preciso_coleccion","","",6,0,0,[],"",""],["lafuente_madrid-p0254-01",15,"Los martirios que le dieron\nLos judíos á un divé,\nEsos te mereces tú,\nPorque no sabes querer.",210,0,-1,200,"",0,4,"e",-1,0,-1,0,254,254,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0254-02",15,"Quiera Dios que en donde pongas\nTodos tus cinco sentidos,\nLe paguen á tu querer\nComo tú pagas al mio.",210,0,-1,200,"",0,4,"io",-1,0,-1,0,254,254,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0254-03",15,"¡Á qué precio tan costoso\nDispones de mi amistad!\nSi una hora me das de gusto,\nMe das ciento de pesar.",210,0,-1,200,"",0,4,"a",-1,0,-1,0,254,254,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0254-04",15,"Compañerilla del alma,\nEsta gitanilla perra\nMe trae mortificado\nQueriendo que no la quiera.",210,0,-1,200,"",0,4,"ea",-1,0,-1,0,254,254,"","",0,"palau_cantares","","",10,0,0,[],"",""],["lafuente_madrid-p0254-05",15,"Compañerita del alma,\nYo no sé por qué motivo\nLo hace tan malamente\nEsta gitana conmigo.",210,0,-1,200,"",0,4,"io",-1,0,-1,0,254,254,"","",0,"palau_cantares","","",20,0,0,[],"",""],["lafuente_madrid-p0254-06",15,"Á ninguna en este mundo\nHe querido más que á tí;\nQue tú no lo reconozcas,\nEse es mi mayor sentir.",210,0,-1,200,"",0,4,"i",-1,0,-1,0,254,254,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0254-07",15,"Tu persona no es persona,\nTu persona es un castigo,\nTu persona no se enmienda,\nSi no se viene conmigo.",210,0,-1,200,"",0,4,"io",106,0,-1,0,254,254,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0255-01",15,"Algun dia era yo rey,\nY ahora soy un mal vasallo;\nPudiendo yo gobernar,\nMe están á mi gobernando.",210,0,-1,200,"",3,4,"ao",-1,0,-1,0,255,255,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0255-02",15,"¿Cómo quieres que te quiera,\nSi me estás amenazando\nQue el dia que yo sea tuya\nLa muerte me está aguardando?",210,0,-1,200,"",0,4,"ao",33,0,-1,0,255,255,"","",0,"","","",16,0,0,[],"",""],["lafuente_madrid-p0255-03",15,"Todavía no soy tuya,\nPicarillo, ¿y me amenazas\nMira que tengo en mi huerto\nLa flor de la calabaza.",210,0,-1,200,"",0,4,"aa",-1,0,-1,0,255,255,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0255-04",15,"¿Cómo quieres que le diga\nA tu madre mad e mia,\nNi á tus hermanas cuñadas,\nSi tú no quieres ser mia?",210,0,-1,200,"",0,4,"a",-1,0,-1,0,255,255,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0255-05",15,"¿Cuándo querrá Dios del cielo\nQue mis deseos se cumplan?\nSegun lo que yo voy viendo,\nSerá tarde, mal ó nunca.",210,0,-1,200,"",0,4,"ua",-1,0,-1,0,255,255,"","",0,"palau_cantares","","",11,0,0,[],"",""],["lafuente_madrid-p0255-06",15,"Cuando te llamo, no vienes,\nCuando vienes, no hay lugar;\nAsí se nos pasa el tiempo,\nAsí se nos pasará.",210,0,-1,200,"",0,4,"a",-1,0,-1,0,255,255,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0255-07",15,"Que si, que no, que seria,\nQue hoy, que mañana, que ayer,\nQue ahora, que luego, que cuándo.....\n¿Quién diablos te ha de entender?",210,0,-1,200,"",0,4,"e",20,0,-1,0,255,255,"","",0,"carrizo_salta, palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0256-01",15,"Ayer me dijiste que hoy,\nHoy me dices que mañana,\nY mañana me dirás:\nYa se me quito la gana.",210,0,-1,200,"",0,4,"aa",4,0,-1,0,256,256,"","",0,"palau_cantares","","",11,0,0,[],"",""],["lafuente_madrid-p0256-02",15,"Estoy, como san Alejo,\nDebajo de la escalera,\nEsperando la ocasion,\nY la ocasion nunca llega.",210,0,-1,200,"",0,4,"ea",-1,0,-1,0,256,256,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0256-03",15,"Yo le he preguntado al tiempo,\nY el tiempo me contestó:\nYa vendrá tiempo, en que tenga\nTiempo, lugar y ocasion.",210,0,-1,200,"",0,4,"o",-1,0,-1,0,256,256,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0256-04",15,"Dáme un besito.-No quiero.\n-Dáme un abrazo.-Tampoco.\n-Dáme una puñaladilla,\nDámela poquito á poco.",210,0,-1,200,"",0,4,"oo",152,0,-1,0,256,256,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0256-05",15,"Siempre me echabas achaques\nPara no salirme á hablar;\nLo que es tiempo te sobraba,\nTe faltaba voluntad.",210,0,-1,200,"",0,4,"a",-1,0,-1,0,256,256,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0257-01",15,"¿Cómo quieres que te quiera,\nSi no me vienes á ver,\nY tengo yo quien me haga\nVisitas al dia tres?",210,0,-1,200,"",0,4,"e",-1,0,-1,0,257,257,"","",0,"rm_t3","","",16,0,0,[],"",""],["lafuente_madrid-p0257-02",15,"Amor mio, vienes tarde,\nY luego te vas temprano.\n¿De qué me sirven á mí\nVisitas de cirujano?",210,0,-1,200,"",0,4,"ao",81,0,-1,0,257,257,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0257-03",15,"Toda la noche al sereno\nCantando porque te asomes,\nY no he podido lograr\nQue respondas á mis sones.",210,0,-1,200,"",0,4,"oe",-1,0,-1,0,257,257,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0257-04",15,"Me dijiste: luego bajo,\nY te fuistes á dormir:\nTe esperé toda la noche,\nY no quisiste venir.",210,0,-1,200,"",0,4,"i",157,0,-1,0,257,257,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0257-05",15,"Resaladita del alma,\nAnoche en tu puerta estuve,\nEstabas á la ventana,\nY no me dijiste: sube.",210,0,-1,200,"",0,4,"ue",208,0,-1,0,257,257,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0257-06",15,"La ceniza del cigarro\nPuede servir de testigo,\nQue anoche estuve en tu puerta,\nY no pude hablar contigo.",210,0,-1,200,"",0,4,"io",106,0,-1,0,257,257,"","",0,"rm_t3","","",2,0,0,[],"",""],["lafuente_madrid-p0258-01",15,"Anoche estuve en tu puerta;\nTres golpes di en el candado;\nPara tener amor, niña,\nTienes el sueño pesado.",210,0,-1,200,"",0,4,"ao",14,0,-1,0,258,258,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0258-02",15,"Eres la madre del sueño,\nHermosísima María;\nSiempre que te vengo á ver,\nHe de encontrarte dormida.",210,0,-1,200,"",0,4,"ia",-1,0,-1,0,258,258,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0258-03",15,"Una vez que vengo á vérte\nAl cabo de la semana,\nTe encuentro triste y llorosa,\nY me pones mala cara.",210,0,-1,200,"",0,4,"aa",-1,0,-1,0,258,258,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0258-04",15,"Si no sale usté esta noche\nÁ lá reja á hablar conmigo,\nDesde el dia de mañana\nNo cuente usté ya conmigo.",210,0,-1,200,"",0,4,"io",-1,0,-1,0,258,258,"","",0,"rm_t3","","",2,0,0,[],"",""],["lafuente_madrid-p0258-05",15,"El amor todo lo puede,\nDice un refran, y es así;\nTú me dices que no puedes,\nLuego no hay amor en tí.",210,0,-1,200,"",0,4,"i",23,0,-1,0,258,258,"","",0,"rm_t3, preciso_coleccion, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0258-06",15,"Si estas en la puerta, cierras,\nSi en la ventana, te escondes;\nDíme qué te he hecho yo,\nQue tan mal me correspondes",210,0,-1,200,"",0,4,"oe",209,0,-1,0,258,258,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0258-07",15,"Toda la noche me tienes\nEn conversaciones varias,\nY luego al amanecer\nCon un suspiro me engañas.",210,0,-1,200,"",0,4,"aa",-1,0,-1,0,258,258,"","",0,"rm_t3, palau_cantares","","",7,0,0,[],"",""],["lafuente_madrid-p0259-01",15,"Oras veces, vida mia,\nEn escuchando mis voces\nTe asomabas á la puerta;\nPero ya no me conoces.",210,0,-1,200,"",0,4,"oe",205,0,-1,0,259,259,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0259-02",15,"Estoy predicando en tí\nComo padre misionero,\nY no te puedo traer\nÁ camino verdadero.",210,0,-1,200,"",0,4,"eo",38,0,-1,0,259,259,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0259-03",15,"En el mundo no se ha visto\nMujer de mi caliá;\nQue tengo el semblante alegre\nY la sangre achicharrá.",210,0,-1,200,"",0,4,"a",9,0,-1,0,259,259,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0259-04",15,"Toda la noche me tienes\nAl sereno y al rocío,\nY luego por la mañana\nMe preguntas si he dormido.",210,0,-1,200,"",0,4,"io",-1,0,-1,0,259,259,"","",0,"palau_cantares","","",7,0,0,[],"",""],["lafuente_madrid-p0259-05",15,"Si piensas que porque callo\nTus sinrazones no entiendo,\nAdvierte que aquel que calla\nHablará en llegando el tiempo.",210,0,-1,200,"",0,4,"eo",-1,0,-1,0,259,259,"","",0,"rm_t3, palau_cantares, preciso_coleccion","","",4,0,0,[],"",""],["lafuente_madrid-p0259-06",15,"Acuérdate, falsa, ingrata,\nDel tiempo de cuando entonces\nBajabas descalza á abrirme,\n¡Y ahora no me conoces!",210,0,-1,200,"",0,4,"oe",-1,0,-1,0,259,259,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0260-01",15,"Te enojas cuando te miro,\nSi no te miro te ofendes;\nDe parte de amor te pido\nQue me digas lo que quieres.",210,0,-1,200,"",0,4,"ee",-1,0,-1,0,260,260,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0260-02",15,"Ven acá, mala gitana,\n¿Qué es lo que quieres de mí,\nSi ando pidiendo limosna\nPorque no te falte á tí?",210,0,-1,200,"",0,4,"i",23,0,-1,0,260,260,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0260-03",15,"Si tienes quejas de mi,\nMátame, si te parece;\nPero no vuelvas la cara\nCuando en la calle me encuentres.",210,0,-1,200,"",0,4,"ee",-1,0,-1,0,260,260,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0260-04",15,"«Tienes, niña, una mañita,\nQue te la vengo á reñir:\nQue te quitas de la puerta\nEn cuanto me ves venir..",210,0,-1,200,"",0,4,"i",157,0,-1,0,260,260,"","",0,"palau_cantares, fernan_caballero","","",3,0,0,[],"",""],["lafuente_madrid-p0260-05",15,"-Si has notado que me quito,\nYo no me quito por tí,\nSino por tus amiguitos,\nQue no tengan que decir.",210,0,-1,200,"",0,4,"i",-1,0,-1,0,260,260,"","",0,"palau_cantares, fernan_caballero","","",3,0,0,[],"",""],["lafuente_madrid-p0260-06",15,"-Ya mis amigos lo saben\nQue yo adoro tu persona;\nQue tú te estés en la puerta\nEs para mi una corona.»",210,0,-1,200,"",0,4,"oa",7,0,-1,0,260,260,"","",0,"palau_cantares, fernan_caballero","","",3,0,0,[],"",""],["lafuente_madrid-p0260-07",15,"Si te haces marinero\nCon intencion de dejarme,\nPermita el divino cielo\nQue el agua del mar te falte.",210,0,-1,200,"",0,4,"ae",-1,0,-1,0,260,260,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0261-01",15,"Á mi corazon le he dicho\nQue no suspire, ni llore;\nQue si se ve despreciado,\nNo faltará quien le adore.",210,0,-1,200,"",0,4,"oe",77,0,-1,0,261,261,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0261-02",15,"Si la Inquisicion supiera\nLo mucho que te he querido,\nCastigaran á mi cuerpo,\nComo si fuera un judío.",210,0,-1,200,"",0,4,"io",-1,0,-1,0,261,261,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0261-03",15,"Si olvidarte fuera fácil,\nBien te olvidaria yo;\nMi corazon gozaria\nLa libertad que perdió.",210,0,-1,200,"",0,4,"o",2,0,-1,0,261,261,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0261-04",15,"Pues los cariños te ofenden,\nLe pido á Dios de los cielos\nQue de aquel á quien estimas\nTengas que sufrir desprecios.",210,0,-1,200,"",0,4,"eo",-1,0,-1,0,261,261,"","",0,"rm_t3, palau_cantares, preciso_coleccion","","",4,0,0,[],"",""],["lafuente_madrid-p0261-05",15,"Todo el mundo me lo dice,\nQue yo me tengo la culpa\nDe amar á quien no me ama,\nBuscar á quien no me busca.",210,0,-1,200,"",0,4,"ua",-1,0,-1,0,261,261,"","",0,"palau_cantares","","",14,0,0,[],"",""],["lafuente_madrid-p0261-06",15,"Es el querer que me tienes\nPiedra que cae de lo alto,\nQue en una parte da el golpe,\nY á mí viene de rechazo.",210,0,-1,200,"",0,4,"ao",-1,0,-1,0,261,261,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0261-07",15,"El ave fría en el campo\nClaramente dice: nieve;\nY eso lo dice por tí,\nSabiendo que á nadie quieres.",210,0,-1,200,"",0,4,"ee",-1,0,-1,0,261,261,"","",0,"fernan_caballero","","",2,0,0,[],"",""],["lafuente_madrid-p0262-01",15,"¿Cómo quieres que navegue\nUn barco que está en la playa?\n¿Cómo quieres que yo quiera\nUn cuerpo que está sin alma?",210,0,-1,200,"",0,4,"aa",-1,0,-1,0,262,262,"","",0,"rm_t3, palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0262-02",15,"Me solicitas cobarde;\nMe amas y te retíras;\nTiras la piedra, y escondes\nLa mano con que la tiras.",210,0,-1,200,"",0,4,"ia",295,0,-1,0,262,262,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0262-03",15,"Yo no te solicité;\nRecuerda que me buscaste,\nTe marchaste por tu gusto,\nY volviste sin llamarte.-",210,0,-1,200,"",0,4,"ae",-1,0,-1,0,262,262,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0262-04",15,"Fuiste mi primer amor,\nTú me enseñaste á querer;\nNo me enseñes á olvidar,\nQue no lo quiero aprender.",210,0,-1,200,"",0,4,"e",20,0,-1,0,262,262,"","",0,"rm_t2, palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0262-05",15,"Como estoy ciego por ti,\nMe estás poniendo con maña\nTus encantos por delante\nPara que tropiece y caiga.",210,0,-1,200,"",0,4,"aa",-1,0,-1,0,262,262,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0262-06",15,"Mi corazon es leal\nPara la persona tuya;\nEl tuyo para mi no,\nQue siempre vas con segunda",210,0,-1,200,"",0,4,"ua",-1,0,-1,0,262,262,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0262-07",15,"En el jardin de tu pecho\nJardinero soy de amor,\nY cuando yo le cultivo,\nTodo el fruto quéda en flor.",210,0,-1,200,"",0,4,"o",72,0,-1,0,262,262,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0263-01",15,"Muchachos, apedreadme;\nSalid, perros, y mordedme,\nQue una niña de esta calle\nMe ha dicho que no me quiere.",210,0,-1,200,"",0,4,"ee",-1,0,-1,0,263,263,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0263-02",15,"Á todos les da claveles\nLa morena de la plaza;\nÁ todos les da claveles,\nY á mi me da calabazas.",210,0,-1,200,"",0,4,"aa",-1,0,-1,0,263,263,"","",0,"rm_t3, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0263-03",15,"La flor de la calabaza\nEs una maldita flor\nQue se la dan á los hombr\nÁ la mejor ocasion.",210,0,-1,200,"",0,4,"o",-1,0,-1,0,263,263,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0263-04",15,"Las calabazas de mayo\nDicen que son las tempranas,\nY yo se las di á mi amante\nEn abril una mañana.",210,0,-1,200,"",0,4,"aa",-1,0,-1,0,263,263,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0263-05",15,"Si me diste calabazas,\nMe las comí con pan tierno;\nMás quiero las calabazas,\nQue una mujer sin gobierno",210,0,-1,200,"",1,4,"eo",225,0,-1,0,263,263,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0263-06",15,"Por la calle venden juicio;\nDi á tu madre que te compre,\nPorque más falta te hace\nQue á una ventana los goznes",210,0,-1,200,"",0,4,"oe",-1,0,-1,0,263,263,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0263-07",15,"Mi padre y mi madre son\nLos dueños de mi persona;\nSi te he dado calabazas,\nAmante mio, perdona.",210,0,-1,200,"",0,4,"oa",7,0,-1,0,263,263,"","",0,"rm_t3, palau_cantares","","",7,0,0,[],"",""],["lafuente_madrid-p0264-01",15,"Dicen que te has alabado\nQue me diste calabazas;\nYo tambien me alabaré\nDe lo que comí en tu casa",210,0,-1,200,"",0,4,"aa",-1,0,-1,0,264,264,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0264-02",15,"Si me has dado calabazas,\nMe las comí con vinagre;\nPero los besos y abrazos\nQue te los quite tu padre.",210,0,-1,200,"",0,4,"ae",-1,0,-1,0,264,264,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0264-03",15,"Te tengo comparadita\nCon las piedras de la calle,\nQue las pisa todo el mundo,\nY no se quejan de nadie.",210,0,-1,200,"",0,4,"ae",-1,0,-1,0,264,264,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0264-04",15,"Ya te lo dije, tronera,\nQue te miraras en éllo;\nY te has venido á mirar\nCuando no tiene remedio.",210,0,-1,200,"",0,4,"eo",-1,0,-1,0,264,264,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0264-05",15,"Jugandillo te lo dije\nNo vinieras á mi casa;\nTan de veras lo has tomado\nQue por mi calle no pasas.",210,0,-1,200,"",0,4,"aa",-1,0,-1,0,264,264,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0264-06",15,"Me dijiste que era fea;\nMe pusiste una corona:\nMás vale fea y con gracia,\nQue no bonita y bobona.",210,0,-1,200,"",0,4,"oa",7,0,-1,0,264,264,"","",0,"rm_t3","","",5,0,0,[],"",""],["lafuente_madrid-p0264-07",15,"Me dijiste que era fea;\nAl espejo me miré:\nAlgun salerillo tengo,\nÁ algun tonto engañaré.",210,0,-1,200,"",0,4,"e",77,0,-1,0,264,264,"","",0,"palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0265-01",15,"Déjame pasar, que voy\nPor agua á la mar serena,\nPara lavarme la cara,\nQue dicen que soy morena.",210,0,-1,200,"",0,4,"ea",59,0,-1,0,265,265,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0265-02",15,"Si quieres que yo te diga\nLa pura de la verdad,\nMucho tienes de bonita,\nPero más de vanidad.",210,0,-1,200,"",0,4,"a",16,0,-1,0,265,265,"","",0,"rm_t3, carrizo_salta, palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0265-03",15,"Eres Ana y eres vana,\nEres cardo, eres jazmin,\nEres buena y eres mala,\nEres diablo y serafin.",210,0,-1,200,"",0,4,"ai",211,0,-1,0,265,265,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0265-04",15,"Eres una alabanciosa,\nQue cuando vas á comprar\nTodo te cuesta más caro,\nY dices que te lo dan.",210,0,-1,200,"",0,4,"a",-1,0,-1,0,265,265,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0265-05",15,"No digas que me has querido,\nNo digas que me has dejado\nPorque se reirá la gente,\nY dirá que estás quemado.",210,0,-1,200,"",0,4,"ao",14,0,-1,0,265,265,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0265-06",15,"Tú has hablado mal de mí,\nYo de ti no he dicho ná,\nQue las campanillas suenan\nSegun tienen el metal.",210,0,-1,200,"",0,4,"a",-1,0,-1,0,265,265,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0265-07",15,"Eres como la perdiz\nQue por el pico se pierde,\nQue te has dejado decir,\nSalada, que no me quieres.",210,0,-1,200,"",0,4,"ee",-1,0,-1,0,265,265,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0266-01",15,"Tú me estás dando lugar\nÁ que eche la capa al toro,\nY que tire de la manta,\nY que se descubra todo.",210,0,-1,200,"",0,4,"oo",-1,0,-1,0,266,266,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0266-02",15,"Tú pensabas engañarme\nCon palabras melositas;\nPero me parió mi madre\nMás pícara que bonita.",210,0,-1,200,"",0,4,"ia",-1,0,-1,0,266,266,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0266-03",15,"Esta gitana está loca,\nLoca que la van á atar,\nQue lo que sueña de noche\nQuiere que salga verdad.",210,0,-1,200,"",0,4,"a",-1,0,-1,0,266,266,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0266-04",15,"Como al Marqués de Villena\nTe tiene de suceder:\nQue se picó en la redoma,\nY no le valió el saber.",210,0,-1,200,"",0,4,"e",20,0,-1,0,266,266,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0266-05",15,"Tú vienes de mala rama,\nNo lo puedes remediar,\nNacida en malos pañales,\nHecha en pecado mortal.",210,0,-1,200,"",0,4,"a",-1,0,-1,0,266,266,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0266-06",15,"Tres castigos merecia\nTodo el hombre que se alaba,\nSe pone en la esquina, y dice:\nAnochehablé con fulana.",210,0,-1,200,"",0,4,"aa",-1,0,-1,0,266,266,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0266-07",15,"Yo te estoy queriendo á tí\nCon el mas grande silencio,\nY tú me vas pregonando,\nComo aquel que vende lienzo.",210,0,-1,200,"",0,4,"eo",-1,0,-1,0,266,266,"","",0,"rm_t3, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0267-01",15,"Anda y pregúntale á un sabio\nCuál de los dos perdió más:\nTú perdiste la vergüenza,\nYo perdi mi libertad.",210,0,-1,200,"",0,4,"a",-1,0,-1,0,267,267,"","",0,"palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0267-02",15,"Tú me dices que soy loco,\nYo te confieso que si;\nQue si loco no estuviera\n¿Cómo te quisiera á tí?",210,0,-1,200,"",0,4,"i",23,0,-1,0,267,267,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0267-03",15,"Ya no te quiero, no, no;\nYa no te quiero, ni verte;\nQue has de ser mi perdicion\nY la causa de mi muerte.",210,0,-1,200,"",0,4,"ee",134,0,-1,0,267,267,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0267-04",15,"Tu falsa correspondencia\nPuso fin á mi alegría.\nEs verdad que no te quiero;\nNo me hables más en tu vida.",210,0,-1,200,"",0,4,"ia",-1,0,-1,0,267,267,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0267-05",15,"Porque sabes que te quiero,\nTú te haces de rogar:\nTanto tiras de la cuerda,\nQue al fin se vendrá á quebrar,",210,0,-1,200,"",0,4,"a",21,0,-1,0,267,267,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0267-06",15,"Si me quieres, dímelo,\nY sí no, desengañarme:\nComo se mudan los tiempos,\nSe mudan las voluntades.",210,0,-1,200,"",0,4,"ae",-1,0,-1,0,267,267,"","",0,"palau_cantares","","",17,0,0,[],"",""],["lafuente_madrid-p0267-07",15,"Ven acá y harémos paces,\nQue no es razon, vida mia,\nQue entre dos finos amantes\nEsté la amistad perdida.",210,0,-1,200,"",0,4,"ia",-1,0,-1,0,267,267,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0268-01",15,"No serás tú el primer hombre,\nNi yo la primer mujer,\nQue se quieran y se olviden,\nY se vuelvan á querer.",210,0,-1,200,"",0,4,"e",20,0,-1,0,268,268,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0268-02",15,"Piedra fuí, perdi mi centro,\nY me tiraron al mar;\nMas con la fuerza del tiempo\nMi centro volví á buscar.",210,0,-1,200,"",0,4,"a",21,0,-1,0,268,268,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0268-03",15,"Está mi amor tan gachon,\nQue lo tengo comparado\nCon los niños en la escuela,\nQue siempre están enojados.",210,0,-1,200,"",0,4,"ao",-1,0,-1,0,268,268,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0268-04",15,"¿Dime, no eras tú mi bien?\n¿No eras tú mi cielecito?\n¿Dime qué te he hecho yo,\nQue estás tan enojadito?",210,0,-1,200,"",0,4,"io",119,0,-1,0,268,268,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0268-05",15,"Por Dios te pido, mi bien,\nQue no me propongas medio:\nÓ mátame de una vez,\nÓ haz por mudar ese genio.",210,0,-1,200,"",0,4,"eo",-1,0,-1,0,268,268,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0268-06",15,"Si mi corazon pudiera\nHablar con tu corazon,\nEn breve rato te diera\nDe todo satisfaccion.",210,0,-1,200,"",1,4,"ao",31,0,-1,0,268,268,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0268-07",15,"Si me quisieras de nuevo,\nHabias de conocer\nQue tengo distinto genio\nY otro modo de querer.",210,0,-1,200,"",0,4,"e",20,0,-1,0,268,268,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0269-01",15,"Por entre espinos y abrojos\nDescalzo me atrevo á entrar,\nSolo por quitarte enojos,\nY volver á tu amistad.",210,0,-1,200,"",0,4,"a",-1,0,-1,0,269,269,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0269-02",15,"Hasta los árboles sienten\nQue se les caiga la hoja:\n¿Cómo quieres que no sienta,\nMorena, cuando te enojas?",210,0,-1,200,"",0,4,"oa",-1,0,-1,0,269,269,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0269-03",15,"Por aquella cruz bendita\nQue hay en aquel campanario,\nQue me vuelvas á querer,\nQue con otra no me apaño.",210,0,-1,200,"",0,4,"ao",-1,0,-1,0,269,269,"","",0,"palau_cantares","","",9,0,0,[],"",""],["lafuente_madrid-p0269-04",15,"Hasta el corazon mé duele\nDe rogarte con la paz;\nPero tú quieres la guerra,\nY luego te ha de pesar.",210,0,-1,200,"",0,4,"a",-1,0,-1,0,269,269,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0269-05",15,"Yo no sé lo que tú tienes,\nNi si te han dado consejos;\nQue no encuentro tu querer\nComo estaba de primero.",210,0,-1,200,"",0,4,"eo",-1,0,-1,0,269,269,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0269-06",15,"Del cielo caiga una piedra,\nQue pese cien mil quintales,\nY le rompa la cabeza\nA quien quiebra voluntades.",210,0,-1,200,"",0,4,"ae",-1,0,-1,0,269,269,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0269-07",15,"Ya vienen las aguas turbias,\nMañana se aclararán:\nEl amor que ha sido firme\nÁ su tiempo volverá.",210,0,-1,200,"",0,4,"a",-1,0,-1,0,269,269,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0270-01",15,"Es-preciso, compañera,\nQue nuestro querer se acabe;\nPongamos tierra por medio\nPara que la gente no hable.",210,0,-1,200,"",0,4,"ae",-1,0,-1,0,270,270,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0270-02",15,"De aquí tengo que ausentarme,\nMi querer está en peligro,\nRaices va ya criando,\nComo en el suelo el olivo.",210,0,-1,200,"",0,4,"io",-1,0,-1,0,270,270,"","",0,"rm_t3, palau_cantares, fernan_caballero","","",4,0,0,[],"",""],["lafuente_madrid-p0270-03",15,"He sabido ya quien eres,\nCon que cesen mis pesares;\nDe mi devocion no esperes\nMás incienso en tus altares.",210,0,-1,200,"",1,4,"ae",164,0,-1,0,270,270,"","",0,"","","",4,0,0,[],"",""],["lafuente_madrid-p0270-04",15,"La camisa de mi cuerpo\nPídela y te la daré;\nPero no por eso esperes\nQue te vuelva mi querer.",210,0,-1,200,"",0,4,"e",-1,0,-1,0,270,270,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0270-05",15,"Ya no quiero querer mas,\nQuiero seguir tu opinion,\nQue un querer con mucho estremo\nEs causa de perdicion.",210,0,-1,200,"",0,4,"io",31,0,-1,0,270,270,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0270-06",15,"Dicen que tú no me quieres,\nPorque me ves chiquitico:\nPues mira, la gente compra\nPor el aire el abanico.",210,0,-1,200,"",0,4,"io",141,0,-1,0,270,270,"","",0,"","","",11,0,0,[],"",""],["lafuente_madrid-p0271-01",15,"Dicen que tú no me quieres,\nPorque no tengo que dar;\nCásate con el reloj,\nQue á todas las horas da.",210,0,-1,200,"",0,4,"a",-1,0,-1,0,271,271,"","",0,"palau_cantares","","",11,0,0,[],"",""],["lafuente_madrid-p0271-02",15,"El amor y el interés\nSalieron al campo un dia;\nPudo más el interés,\nQue el amor que me tenias",210,0,-1,200,"",0,4,"ia",-1,0,-1,0,271,271,"","",0,"palau_cantares","","",9,0,0,[],"",""],["lafuente_madrid-p0271-03",15,"Por interés del dinero\nTe fuiste de la cabeza;\nDijiste que eras gitana,\nTe volviste montañesa.",210,0,-1,200,"",0,4,"ea",201,0,-1,0,271,271,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0271-04",15,"Por interés del dinero\nTe fuiste con un gachó;\n¡Y luego vienes diciendo\nQue la pasion te cegó!",210,0,-1,200,"",0,4,"o",2,0,-1,0,271,271,"","",0,"","","",4,0,0,[],"",""],["lafuente_madrid-p0271-05",15,"Por interés del dinero\nTe fuistes y me dejastes;\n¿Te echastes en el bolsillo\nLa ganancia que sacastes?",210,0,-1,200,"",0,4,"ae",142,0,-1,0,271,271,"","",0,"","","",4,0,0,[],"",""],["lafuente_madrid-p0272-01",15,"¡Reniego de la persona\nQue se lleva del dinero,\nY no se sabe llevar\nDe unos buenos ojos negros!",210,0,-1,200,"",0,4,"eo",-1,0,-1,0,272,272,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0272-02",15,"Á la cuenta, tú pensabas\nQue era yo algun caballero\nQue venia de la Habana\nCon muchísimo dinero.",210,0,-1,200,"",0,4,"eo",38,0,-1,0,272,272,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0272-03",15,"Yo ya te voy á dejar,\nPorque no tengo que darte:\nConsidera, compañera,\nSi mis fatigas son grandes.",210,0,-1,200,"",0,4,"ae",-1,0,-1,0,272,272,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0272-04",15,"La maldicion que te echo\nDesde hoy en adelante,\nEs que el dinero te sobre,\nPero que el gusto te falte.",210,0,-1,200,"",0,4,"ae",-1,0,-1,0,272,272,"","",0,"rm_t3, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0272-05",15,"Por aquella cruz bendita\nQue está en aquella pared,\nQue te has de quedar en blanco,\nComo pliego de papel.",210,0,-1,200,"",0,4,"e",-1,0,-1,0,272,272,"","",0,"palau_cantares","","",9,0,0,[],"",""],["lafuente_madrid-p0272-06",15,"Mi corazon enfermó\nDe la pena que le dieron;\nLa pena y quien se la dió\nLa penará en los infiernos.",210,0,-1,200,"",0,4,"eo",-1,0,-1,0,272,272,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0272-07",15,"Cuando más firme te quiero,\nTú aborreciéndome vas;\nYa que así me has olvidado,\nComo pagas cobrarás.",210,0,-1,200,"",0,4,"a",51,0,-1,0,272,272,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0273-01",15,"Si preguntas por quién muero,\nTú eres quien me va matando;\nPues soy tu amor verdadero,\nY tú me vas olvidando.",210,0,-1,200,"",1,4,"ao",33,0,-1,0,273,273,"","",0,"rm_t3","","",2,0,0,[],"",""],["lafuente_madrid-p0273-02",15,"¿Constante no te adoré?\n¿Y fino no te servi?\nNo hice cuanto fué tu gusto?\n¿Pues por qué me olvidas, di?",210,0,-1,200,"",0,4,"i",23,0,-1,0,273,273,"","",0,"rm_t3, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0273-03",15,"Yo no sé por qué motivo\nMe olvidas á sangre fria,\nCuando se le toma ley\nÁ un perrillo que se cria.",210,0,-1,200,"",0,4,"a",0,0,-1,0,273,273,"","",0,"palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0273-04",15,"Camaradita del alma,\nUsté no sabe querer:\nPor una cosa tan leve\nNo se olvida á una mujer.",210,0,-1,200,"",0,4,"e",20,0,-1,0,273,273,"","",0,"","","",4,0,0,[],"",""],["lafuente_madrid-p0273-04-e2",15,"¡Al cabo de tanto tiempo\nQue mi corazon te amé,\nHas tenido atrevimiento\nPara decirme que no!",210,0,-1,200,"",5,4,"o",-1,0,-1,0,273,273,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0273-05",15,"! Ay por Dios, que eso és matarme,\nEso es quitarme la vida;\nEso es echarme á la calle,\nComo cosilla perdida!",210,0,-1,200,"",0,4,"ia",37,0,-1,0,273,273,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0274-02",15,"Por haberte yo querido,\nQuisiera que te casaras\nCon otra mejor que yo,\nY de mi no te acordaras.",210,0,-1,200,"",0,4,"aa",143,0,-1,0,274,274,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0274-03",15,"Permita Dios que te vea\nEn un calabozo oscuro,\nY que pase por mi mano\nTodo el alimento tuyo.",210,0,-1,200,"",0,4,"uo",-1,0,-1,0,274,274,"","",0,"preciso_coleccion","","",3,0,0,[],"",""],["lafuente_madrid-p0274-04",15,"Aunque pase más fatigas\nQue clavos tiene una puerta,\nAnda con Dios, compañero,\nQue el mundo da muchas vueltas.",210,0,-1,200,"",0,4,"ea",-1,0,-1,0,274,274,"","",0,"palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0274-05",15,"En el querer no hay venganza,\nY te has vengado de mí;\nSi no hay castigo en la tierra,\nDel cielo te ha de venir.",210,0,-1,200,"",0,4,"i",-1,0,-1,0,274,274,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0274-06",15,"Quisiera que Dios me oyera,\nY que las piedras hablaran,\nY que el castigo viniera\nComo yo lo deseara.",210,0,-1,200,"",0,4,"aa",-1,0,-1,0,274,274,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0274-07",15,"Por quererte, mala hembra,\nEché mi cuerpo á perder:\nEl que en mala tierra siembra,\nMal fruto puede coger.",210,0,-1,200,"",1,4,"e",20,0,-1,0,274,274,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0275-01",15,"Mal haya quien me dió á mí\nTanto amor para quererte,\nY ahora para olvidarte\nSon mis penillas de muerte.",210,0,-1,200,"",0,4,"ee",134,0,-1,0,275,275,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0275-02",15,"Toma, niña, esos dos cuartos,\nY llámame á esa mujer;\nQuiero despedirme de ella,\nPorque la he querido bien.",210,0,-1,200,"",0,4,"e",-1,0,-1,0,275,275,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0275-03",15,"Toma, niño, estos dos cuartos,\nY dile á aquella mujer\nQue quiero darla un consejo,\nPorque la he querido bien.",210,0,-1,200,"",0,4,"e",-1,0,-1,0,275,275,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0275-04",15,"Si en adelante no quieres\nHacer más caso de mí,\nLa vida que me has robado\nMe debes restituir.",210,0,-1,200,"",0,4,"i",-1,0,-1,0,275,275,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0275-05",15,"Aunque ahora me desprecias.\nEn algun tiempo fuí bueno;\nCalla tú, y callaré yo,\nY así los dos callarémos.",210,0,-1,200,"",0,4,"eo",-1,0,-1,0,275,275,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0275-06",15,"Ya yo he caido en desgracia.\n¡Paciencia! ¡cómo ha de ser!\nAunque yo santos pintara,\nDiablos te han de parecer.",210,0,-1,200,"",0,4,"e",20,0,-1,0,275,275,"","",0,"palau_cantares, fernan_caballero","","",3,0,0,[],"",""],["lafuente_madrid-p0275-07",15,"Otras veces era yo\nEn tu casa el más querido,\nY ahora por mi desgracia\nSoy el más aborrecido.",210,0,-1,200,"",0,4,"io",101,0,-1,0,275,275,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0276-01",15,"Otras veces mi capote\nAndaba en el contrabando\nArropándote de noche;\n¡Y ahora me preguntas cuándo!",210,0,-1,200,"",3,4,"ao",33,0,-1,0,276,276,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0276-02",15,"En mi vida solicito\nAl que de mí se retira;\nQue he tomado por venganza,\nOlvidar á quien me olvida.",210,0,-1,200,"",0,4,"ia",-1,0,-1,0,276,276,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0276-03",15,"Me quisistes, y te quise;\nMe olvidaste, y te olvidé;\nLos dos tuvimos la culpa,\nTú primero y yo despues.",210,0,-1,200,"",0,4,"e",-1,0,-1,0,276,276,"","",0,"rm_t3, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0276-04",15,"Por querer á un serafin,\nOlvidé á un hermoso cielo:\nDos glorias no puede haber,\nVolvamos á lo primero.",210,0,-1,200,"",0,4,"eo",-1,0,-1,0,276,276,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0276-05",15,"Anda con Dios, mala sangre,\nYa te se ha cumplido el gusto\nDe encontrarme por la calle\nTodo vestido de luto.",210,0,-1,200,"",0,4,"uo",-1,0,-1,0,276,276,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0276-06",15,"«Debajo de tu ventana\nHay un ramito de olivo,\nUn manojito de esparto\nY un sarmiento florecijo.",210,0,-1,200,"",0,4,"io",-1,0,-1,0,276,276,"","",0,"","","",29,0,0,[],"",""],["lafuente_madrid-p0277-01",15,"El esparto es que me aparto;\nEl olivo que te olvido;\nEl sarmiento me arrepiento\nDel tiempo que te he querido,»",210,0,-1,200,"",0,4,"io",101,0,-1,0,277,277,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0277-02",15,"Allá va mi corazon\nMetido en un azafate:\nNo me lo niegues, traidora,\nQue algun dia fuí tu amanto.",210,0,-1,200,"",5,4,"ao",-1,0,-1,0,277,277,"","",0,"","","",4,0,0,[],"",""],["lafuente_madrid-p0277-03",15,"Si en el transcurso del tiempo\nEn la calle me encontrares\nÁ Dios te pido, alma mia\nQue te pares, y me hables.",210,0,-1,200,"",0,4,"ae",-1,0,-1,0,277,277,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0277-04",15,"Aunque vayas y te bañes\nEn el agua del romero,\nNo te se quita la mancha\nDe los amores primeros.",210,0,-1,200,"",0,4,"eo",-1,0,-1,0,277,277,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0277-05",15,"Anda, véte por el mundo,\nHombre que ya me dejaste;\nYa no tienes que pedirme,\nNi yo tampoco que darte.",210,0,-1,200,"",0,4,"ae",-1,0,-1,0,277,277,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0277-06",15,"Cuando te veo con pena,\nTe digo: bien empleado;\nQue no has querido tomar\nLos consejos que te he dado..",210,0,-1,200,"",0,4,"ao",14,0,-1,0,277,277,"","",0,"rm_t3, palau_cantares","","",8,0,0,[],"",""],["lafuente_madrid-p0277-07",15,"Anda, véte, pero advierte\nQue si para mí hay castigo,\nTambien para ti le habrá\nMás rigoroso que el mio.",210,0,-1,200,"",0,4,"o",-1,0,-1,0,277,277,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0278-01",15,"Yo me enamoré del aire,\nDel aire de una mujer;\nComo la mujer es aire,\nEn el aire me quedé.",210,0,-1,200,"",0,4,"e",-1,0,-1,0,278,278,"","",0,"rm_t3, palau_cantares, isaacs_colombia, murciano_antiguo, fernan_caballero","","",9,0,0,[],"",""],["lafuente_madrid-p0278-02",15,"Corazoncito leal,\nBien te lo decia yo,\nQue te habian de olvidar,\nY tú decias que no.",210,0,-1,200,"",0,4,"o",2,0,-1,0,278,278,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0278-03",15,"Corazon, te lo decia,\nQue vivias engañado,\nY vives aborrecido\nPudiendo ser estimado.",210,0,-1,200,"",0,4,"ao",14,0,-1,0,278,278,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0278-04",15,"Mi corazon tú lo tienes,\nDámelo, si no te sirve,\nSe lo daré á otra paloma,\nQue con su calor lo abrigue.",210,0,-1,200,"",0,4,"ie",-1,0,-1,0,278,278,"","",0,"rm_t2, palau_cantares, fernan_caballero","","",4,0,0,[],"",""],["lafuente_madrid-p0278-05",15,"Alza la voz, pregonero,\nY di lo que yo dijere:\n¿Quién me compra un corazon\nDespreciado de mujeres?",210,0,-1,200,"",0,4,"ee",-1,0,-1,0,278,278,"","",0,"palau_cantares","","",9,0,0,[],"",""],["lafuente_madrid-p0278-06",15,"Á la una y á las dos,\nÁ las tres, que se remata!\n¿Quién me compra un corazon\nDespreciado de una ingrata?",210,0,-1,200,"",0,4,"aa",74,0,-1,0,278,278,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0278-07",15,"Si mi corazon llegase\nÁ pedirte una limosna,\nY no tuvieras que dárle,\nDile con amor: perdona.",210,0,-1,200,"",0,4,"oa",-1,0,-1,0,278,278,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0279-01",15,"El quérer que puse en ti\nTan firme y tan verdadero,\nSi lo hubiera puesto en Dios,\nHubiera ganado el cielo.",210,0,-1,200,"",0,4,"eo",-1,0,-1,0,279,279,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0279-02",15,"Con venderte no me pagas\nLo mucho que te he querido,\nAunque tu cuerpo valiera\nValor de treinta navíos.",210,0,-1,200,"",0,4,"io",-1,0,-1,0,279,279,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0279-03",15,"No quiero que me des gloria,\nPorque no la he merecido;\nLo que quiero es que me pagues\nEl tiempo que te he querido.",210,0,-1,200,"",0,4,"io",101,0,-1,0,279,279,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0279-04",15,"Vamos á ajustar la cuenta\nDel tiempo que te he querido,\nMe darás carta de pago,\nY yo te daré recibo.",210,0,-1,200,"",0,4,"io",-1,0,-1,0,279,279,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0279-05",15,"No tengas que comparar\nTu voluntad con la mia,\nQue es sin fin mi voluntad,\nY la tuya duró un dia.",210,0,-1,200,"",0,4,"a",-1,0,-1,0,279,279,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0279-06",15,"Escribistes en la arena,\nY firmastes en la mar,\nEl viento fué tu correo;\n¡Vaya una seguridad!",210,0,-1,200,"",0,4,"a",-1,0,-1,0,279,279,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0279-07",15,"Aquella firmeza tanta\nY aquel ponderar amor,\nAquel no vivir sin verme,\n¡Qué pronto te se acabó!",210,0,-1,200,"",0,4,"o",-1,0,-1,0,279,279,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0280-01",15,"¡Bien me dijeron á mi\nQue tu querer era vano,\nY que por fin pasaria\nComo nube de verano!",210,0,-1,200,"",0,4,"ao",81,0,-1,0,280,280,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0280-02",15,"¿Te acuerdas cuando pusiste\nTu mano sobre la mia,\nY llorando me dijiste\nQue nunca me olvidarias?",210,0,-1,200,"",0,4,"ia",-1,0,-1,0,280,280,"","",0,"","","",5,0,0,[],"",""],["lafuente_madrid-p0280-03",15,"¿Te acuerdas cuando dijiste\nEn cierta conversacion,\nQue los montes se mudaban,\nPero tufirmeza no?",210,0,-1,200,"",0,4,"o",-1,0,-1,0,280,280,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0280-04",15,"¿Te acuerdas que estando un dia\nEn mi pecho reclinado,\nDe mi corazon sentiste\nLos golpes acompasados?",210,0,-1,200,"",0,4,"ao",-1,0,-1,0,280,280,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0280-05",15,"Un amor tenia yo\nQue me decia llorando,\nQue nunca me olvidaría\n¡Y ya me estaba olvidando!",210,0,-1,200,"",0,4,"ao",33,0,-1,0,280,280,"","",0,"rm_t3, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0280-06",15,"¿De qué te sirve tener\nEsa cara tan hermosa,\nSi tiene tu corazon\nEspinas como la rosa?",210,0,-1,200,"",0,4,"oa",63,0,-1,0,280,280,"","",0,"rm_t3, fernan_caballero","","",8,0,0,[],"",""],["lafuente_madrid-p0281-01",15,"¡Mal haya el amor, mal haya,\nY quien del amor se fia,\nQue pase yo mi querer\nEn quien no lo merecia!",210,0,-1,200,"",0,4,"ia",0,0,-1,0,281,281,"","",0,"","","",7,0,0,[],"",""],["lafuente_madrid-p0281-02",15,"Yo tuve un árbol sembrado\nY regado con querer,\nY á lo mejor se ha secado:\n¡Mal haya quien quiere bien!",210,0,-1,200,"",0,4,"e",-1,0,-1,0,281,281,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0281-03",15,"Arbolito, te secaste\nTeniendo el agua en el pié,\nEn el tronco la firmeza,\nY en las ramas el querer.",210,0,-1,200,"",0,4,"e",-1,0,-1,0,281,281,"","",0,"palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0281-04",15,"Cuando bien te parecí,\n¡Con qué ojitos me miraste!\n¿Quién te ha hablado mal de mi\nQue tan pronto me olvidaste?",210,0,-1,200,"",1,4,"ae",212,0,-1,0,281,281,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0281-05",15,"¡Mal haya este pecho tierno\nQue tanto te ha idolatrado;\nMientras más enternecido,\nHa sido más despreciado!",210,0,-1,200,"",0,4,"ao",14,0,-1,0,281,281,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0281-06",15,"Te fuistes, y me dejastes\nCuando yo mas te queria:\nNo hubieran hecho otro tanto\nLos moros de Berbería.",210,0,-1,200,"",0,4,"ia",0,0,-1,0,281,281,"","",0,"rm_t3","","",3,0,0,[],"",""],["lafuente_madrid-p0281-07",15,"Creo que no tienes alma,\nNi naciste en este reino,\nSino que en la morería\nTuviste tu nacimiento.",210,0,-1,200,"",0,4,"eo",-1,0,-1,0,281,281,"","",0,"rm_t3","","",3,0,0,[],"",""],["lafuente_madrid-p0282-01",15,"Tú dejaste mi amistad\nPor querer seguir tu rumbo:\nAnda, que pronto verás\nEl pago que te da el mundo.",210,0,-1,200,"",0,4,"uo",-1,0,-1,0,282,282,"","",0,"rm_t3, carrizo_salta","","",3,0,0,[],"",""],["lafuente_madrid-p0282-02",15,"El pago que te da el mundo\nTe está muy bien empleado,\nQue siempre la ingratitud\nHa merecido este pago.",210,0,-1,200,"",0,4,"ao",-1,0,-1,0,282,282,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0282-03",15,"Compañera de mi alma,\nAlgun dia querrá Dios\nQue la fortuna se vuelva,\nY pases por mi dolor.",210,0,-1,200,"",0,4,"o",-1,0,-1,0,282,282,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0282-05",15,"Ya sé yo que en este mundo\nDe estorbo te estoy sirviendo:\nAnda con Dios, compañera,\nQue ya me echarás de menos.",210,0,-1,200,"",0,4,"eo",-1,0,-1,0,282,282,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0282-06",15,"Déjala que vaya y venga\nAl pilarillo por agua,\nQue puede ser que algun dia\nEn el pilarillo caiga.",210,0,-1,200,"",0,4,"aa",-1,0,-1,0,282,282,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0282-07",15,"Echale tú á mi caballo\nHojitas de limon verde,\nQue puede ser que algun dia,\nSerrana, de mí te acuerdes.",210,0,-1,200,"",0,4,"ee",-1,0,-1,0,282,282,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0283-01",15,"Déjala que cante y ria\nY de mis penas se goce,\nQue puede ser que algun día\nLágrimas de sangre llore.",210,0,-1,200,"",1,4,"oe",-1,0,-1,0,283,283,"","",0,"palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0283-02",15,"Algun día tú caerás\nEn aquel yerro que hiciste;\nCuando quieras no podrás\nRecobrar lo que perdiste.",210,0,-1,200,"",1,4,"ie",153,0,-1,0,283,283,"","",0,"carrizo_salta, palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0283-03",15,"Con el corazon partido\nLlorando gotas de sangre,\nY arrastrando por los suelos\nHas de venir á buscarme.",210,0,-1,200,"",0,4,"ae",-1,0,-1,0,283,283,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0283-04",15,"Como el agua busca al rio,\nY el rio busca la mar,\nAntes de que pase un año,\nMe has de venir á buscar.",210,0,-1,200,"",0,4,"a",21,0,-1,0,283,283,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0284-01",15,"Dicen que la mar es grando\nY caben muchos navíos,\n¡En ese pecho no puede\nCaber un recuerdo mio!",210,0,-1,200,"",0,4,"io",-1,0,-1,0,284,284,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0284-02",15,"Válganme las tres Marías,\nY el Cristo del Gran poder:\n¡Tanto como me querias,\nY ya no me puedes ver!",210,0,-1,200,"",1,4,"e",20,0,-1,0,284,284,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0284-03",15,"Quise bien y aborrecí,\nQue no es delito en quien ama;\nQue cuando yo aborrecí,\nMás que aborrecido estaba.",210,0,-1,200,"",0,4,"aa",-1,0,-1,0,284,284,"","",0,"rm_t3, palau_cantares, fernan_caballero","","",4,0,0,[],"",""],["lafuente_madrid-p0284-04",15,"Cuando hables de mi persona,\nNo digas que me has querido;\nDi que fué un capricho solo\nQue los dos hemos tenido.",210,0,-1,200,"",0,4,"io",101,0,-1,0,284,284,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0284-05",15,"Compañerilla del alma,\nPor la salud de tu madre,\nLo que pasó entre los dos\nNo se lo cuentes á nadie.",210,0,-1,200,"",0,4,"ae",-1,0,-1,0,284,284,"","",0,"palau_cantares","","",10,0,0,[],"",""],["lafuente_madrid-p0284-06",15,"No me mires, que me matas,\nCon esos ojos tan tristes,\nPorque se me representa\nEl mal pago que me diste.",210,0,-1,200,"",0,4,"ie",-1,0,-1,0,284,284,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0284-07",15,"Como la memoria es frágil\nNo recuerdo si te quise;\nPero recuerdo, serrana,\nEl mal pago que me diste.",210,0,-1,200,"",0,4,"ie",-1,0,-1,0,284,284,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0285-01",15,"Bajo por la calle abajo,\nPaso por tu puerta y digo:\nAquí vive la morena\nQue algun tiempo me ha querido.",210,0,-1,200,"",0,4,"io",-1,0,-1,0,285,285,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0285-02",15,"Cada vez que paso y miro\nDonde mi amante vivió,\nMe contento con la jaula,\nQue el pájaro ya voló.",210,0,-1,200,"",0,4,"o",2,0,-1,0,285,285,"","",0,"palau_cantares","","",25,0,0,[],"",""],["lafuente_madrid-p0285-03",15,"Por agravios que me hagas,\nDe tí no me vengaré,\nPorque te vale el sagrado\nDe haberte querido bien.",210,0,-1,200,"",0,4,"e",-1,0,-1,0,285,285,"","",0,"rm_t2, rm_t3, fernan_caballero, palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0285-04",15,"Cuando te encuentro en la calle\nSe me alegra el corazon;\nDonde candela se hizo,\nSiempre ceniza quedó.",210,0,-1,200,"",0,4,"o",-1,0,-1,0,285,285,"","",0,"palau_cantares","","",13,0,0,[],"",""],["lafuente_madrid-p0285-05",15,"Ojos mios, no lloreis;\nLágrimas, tened paciencia;\nQue el que nace desgraciado,\nDesde pequeñito empieza.",210,0,-1,201,"",0,4,"ea",-1,0,-1,0,285,285,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0286-01",15,"Tengo un vestido de penas\nCon mangas de sentimiento,\nY los faralares son\nPenillas que trae el tiempo.",210,0,-1,201,"",0,4,"eo",-1,0,-1,0,286,286,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0286-02",15,"Tengo una pena conmigo\nQue á nadie se la diré,\nEn el fondo de mi pecho\nSu sepulcro labraré.",210,0,-1,201,"",0,4,"e",77,0,-1,0,286,286,"","",0,"palau_cantares","","",7,0,0,[],"",""],["lafuente_madrid-p0286-03",15,"Dentro de mi pecho tengo\nUna arquita con dos llaves,\nY en ella tengo metidas\nCositas que nadie sabe.",210,0,-1,201,"",0,4,"ae",-1,0,-1,0,286,286,"","",0,"palau_cantares","","",32,0,0,[],"",""],["lafuente_madrid-p0286-04",15,"No hay corazon como el mio,\nQue calle y sienta su pena;\nCorazon que siente y calla,\nNo se encuentra donde quiera.",210,0,-1,201,"",0,4,"ea",-1,0,-1,0,286,286,"","",0,"","","",9,0,0,[],"",""],["lafuente_madrid-p0287-01",15,"¡Ay de mí, que triste estoy\nY triste siempre estaré!\n¡Yo nací para estar triste,\nY triste me moriré!",210,0,-1,201,"",0,4,"e",77,0,-1,0,287,287,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0287-02",15,"Con el dolor que yo vivo\nEs imposible vivir;\nSi el mundo no da otra vuelta,\nDará de mi vida fin.",210,0,-1,201,"",0,4,"i",-1,0,-1,0,287,287,"","",0,"rm_t3, palau_cantares, preciso_coleccion","","",5,0,0,[],"",""],["lafuente_madrid-p0287-03",15,"Siempre que miro al cangrejo,\nMe pongo á considerar,\nQue se parece á mis dichas,\nQue caminan hácia atras.",210,0,-1,201,"",0,4,"a",-1,0,-1,0,287,287,"","",0,"rm_t3, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0287-04",15,"Dicen que tras la alegría\nSuele venir el dolor;\nYo conozco los dolores,\nPero la alegría no.",210,0,-1,201,"",0,4,"o",-1,0,-1,0,287,287,"","",0,"rm_t3, carrizo_salta, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0287-05",15,"De dolor y sentimiento\nDicen que no muere nadie.\nYo me tengo de morir\nPor ver si se muere alguien.",210,0,-1,201,"",0,4,"ae",-1,0,-1,0,287,287,"","",0,"palau_cantares, fernan_caballero","","",3,0,0,[],"",""],["lafuente_madrid-p0287-06",15,"Siempre que miro hacia el cielo\nLas lágrimas se me saltan,\nNo sé de qué, ni por qué....\nPero lloro con el alma.",210,0,-1,201,"",0,4,"aa",-1,0,-1,0,287,287,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0288-01",15,"Penita sobre penita;\nSobre penita, más pena:\nVengan, vengan sobre mí,\nQue yo soy la madre de ellas",210,0,-1,201,"",0,4,"ea",-1,0,-1,0,288,288,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0288-02",15,"Estoy tan hecho á la pena\nQue me sirve de compaña,\nY el dia que no la tengo\nMe parece cosa extraña.",210,0,-1,201,"",0,4,"aa",213,0,-1,0,288,288,"","",0,"rm_t3, carrizo_salta","","",5,0,0,[],"",""],["lafuente_madrid-p0288-03",15,"Quien canta, su mal espanta,\nY aquel que llora lo aumenta:\nYo canto por divertir\nEl dolor que me atormenta",210,0,-1,201,"",0,4,"ea",229,0,-1,0,288,288,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0288-04",15,"Las penillas que se cantan,\nSon las penillas más grandes,\nPorque se cantan llorando,\nY las lágrimas no salen.",210,0,-1,201,"",0,4,"ae",-1,0,-1,0,288,288,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0288-05",15,"Si piensas que porque canto\nTengo el corazon alegre,\nYo soy como el gallo inglés,\nQue canta cuando se muere.",210,0,-1,201,"",0,4,"ee",-1,0,-1,0,288,288,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0288-06",15,"Dicen que la mar divierte,\nQue quita pena y fatiga;\nYo me arrimaré á una fuente\nPor ver si el agua me anima.",210,0,-1,201,"",0,4,"ia",-1,0,-1,0,288,288,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0288-07",15,"Pienso, y no sé lo que pienso;\nPienso y no soy desgraciado,\nPienso que siempre la soga\nQuiebra por lo mas delgado.",210,0,-1,201,"",0,4,"ao",14,0,-1,0,288,288,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0289-01",15,"Yo voy á la fuente y bebo\nY el agua no la aminoro,\nQue se aumentan las corrientes\nCon las lágrimas que lloro.",210,0,-1,201,"",0,4,"oo",85,0,-1,0,289,289,"","",0,"rm_t3","","",2,0,0,[],"",""],["lafuente_madrid-p0289-02",15,"Los ojitos de mi cara,\n¿Quién los compra, que los vendo?\nTan pobre me voy quedando\nQue hasta los ojitos vendo.",210,0,-1,201,"",0,4,"eo",-1,0,-1,0,289,289,"","",0,"palau_cantares","","",13,0,0,[],"",""],["lafuente_madrid-p0289-03",15,"Cada vez que paso y miro\nLa puerta del hospital,\nLe digo á mi cuerpecito:\nAqui vendrás á parar.",210,0,-1,201,"",0,4,"a",-1,0,-1,0,289,289,"","",0,"rm_t3, palau_cantares","","",25,0,0,[],"",""],["lafuente_madrid-p0289-04",15,"Cada vez que paso y miro\nLa puerta del campo santo,\nLe digo á mi cuerpecillo:\nAquí tendrás tú descanso.",210,0,-1,201,"",0,4,"ao",-1,0,-1,0,289,289,"","",0,"palau_cantares","","",25,0,0,[],"",""],["lafuente_madrid-p0289-05",15,"Yo no deseo la muerte,\nPorque es pecado mortal;\nPero sé que hasta que muera,\nDescanso no he de encontrar.",210,0,-1,201,"",0,4,"a",-1,0,-1,0,289,289,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0290-01",15,"Todo el mundo está empeñado\nEn dar tormento á mi cuerpo;\nNo sé qué motivo ha dado,\nPorque yo no se lo encuentro.",210,0,-1,201,"",0,4,"eo",-1,0,-1,0,290,290,"","",0,"rm_t3","","",2,0,0,[],"",""],["lafuente_madrid-p0290-02",15,"Aquel que tiene la culpa\nDe que yo fatigas pase,\nSe vea en Argel cautivo\nSin tener ningun rescate...",210,0,-1,201,"",0,4,"ae",-1,0,-1,0,290,290,"","",0,"fernan_caballero, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0290-03",15,"La piedra, con ser la piedra\nAl golpe del eslabon\nEcha lágrimas de fuego:.\n¡Qué será mi corazon!",210,0,-1,201,"",0,4,"ao",-1,0,-1,0,290,290,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0290-04",15,"Á un Santo Cristo de acero\nLe hice yo que llorara;\nCuando de acero lloró,\n¿Qué fuera de carne humana?",210,0,-1,201,"",0,4,"aa",-1,0,-1,0,290,290,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0290-05",15,"¿Á qué santo llamaré\nPara aliviar esta pena,\nQue me ahoga la garganta,\nCual si fuera una cadena?",210,0,-1,201,"",0,4,"ea",59,0,-1,0,290,290,"","",0,"rm_t3, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0290-06",15,"En un pozo muy profundo\nDe penas estoy nadando,\nY yo solo me confundo\nDe ver lo que estoy pasando.",210,0,-1,201,"",1,4,"ao",33,0,-1,0,290,290,"","",0,"palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0290-07",15,"Más valiera que mi madre,\nAl punto que me parió,\nMe hubiera dado la muerte,\nY no padeciera yo.",210,0,-1,201,"",0,4,"o",2,0,-1,0,290,290,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0291-01",15,"Á la mar fuera y me echara,\nPero ¿qué dirá la gente?\nQue vivo desesperado,\nY ando buscando la muerte.",210,0,-1,201,"",0,4,"ee",-1,0,-1,0,291,291,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0291-02",15,"El sueño tengo perdido\nY no sé donde buscarlo;\nLo buscaré en el olvido...\nY el olvido ¿dónde hallarlo?",210,0,-1,201,"",1,4,"ao",236,0,-1,0,291,291,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0291-03",15,"Vámonos de aquí, que corre\nLa mala fortuna nuestra:\nAyer se cayó la torre,\nMañana caerá la iglesia.",210,0,-1,201,"",0,4,"ea",-1,0,-1,0,291,291,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0291-04",15,"Tengo una pena conmigo\nY una congoja mortal:\nMe encuentro con dos caminos,\nSin saber por cual tomar.",210,0,-1,201,"",0,4,"a",-1,0,-1,0,291,291,"","",0,"rm_t3, palau_cantares","","",7,0,0,[],"",""],["lafuente_madrid-p0291-05",15,"¡Válgame D'os de los cielos\nQué desgraciado nací!\nEn la pila del bautismo\nFaltó la sal para mí.",210,0,-1,201,"",0,4,"i",23,0,-1,0,291,291,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0291-06",15,"¡Válgame Dios de los cielos\nQué grande es la pena mia!\nQue me he caido en un pozo,\nY no encuentro la salida.",210,0,-1,201,"",0,4,"ia",-1,0,-1,0,291,291,"","",0,"palau_cantares, murciano_antiguo","","",33,0,0,[],"",""],["lafuente_madrid-p0291-07",15,"Rosa me puso mi madre\nPara ser más desgraciada,\nQue no hay rosa en el rosal\nQue no muera deshojada.",210,0,-1,201,"",0,4,"aa",49,0,-1,0,291,291,"","",0,"rm_t3, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0292-01",15,"De chiquita ya lloraba,\nY de grande tambien lloro,\nCuando chiquita por teta,\nY ahora por el bien que adoro.",210,0,-1,201,"",3,4,"oo",85,0,-1,0,292,292,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0292-02",15,"Retírate al campo y llora,\nQue bien tienes que llorar;\nQue eres muy niña, y no sabes,\nQuién te quiere bien ó mal.",210,0,-1,201,"",0,4,"a",-1,0,-1,0,292,292,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0292-03",15,"Sola soy, sola nací,\nSola me parió mi madre,\nSola tengo de morir,\n¡La Soledad me acompañe!",210,0,-1,201,"",0,4,"ae",-1,0,-1,0,292,292,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0292-04",15,"Soy una pobre doncella\nQue no me meto con nadie,\nY por una mala lengua\nTengo mi honor en el aire.",210,0,-1,201,"",0,4,"ae",-1,0,-1,0,292,292,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0292-05",15,"Por causa de malas lenguas\nQue hablan lo que no es,\nTengo mi fama perdida:\n¡Cuándo la recobraré!",210,0,-1,201,"",0,4,"e",-1,0,-1,0,292,292,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0292-06",15,"¡Puñaladas en mi puerta!\n¡Cielos! qué sucede aquí!\nLos hombres se están matando,\n¿Madre, si será por mi?",210,0,-1,201,"",0,4,"i",23,0,-1,0,292,292,"","",0,"rm_t3","","",4,0,0,[],"",""],["lafuente_madrid-p0293-01",15,"¡Ay de mí, que siendo niña,\nLe di palabra á un mancebo,\nY por temor á mi padre\nÁ cumplirla no me atrevo!",210,0,-1,201,"",0,4,"eo",240,0,-1,0,293,293,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0293-02",15,"Empecemos, corazon,\nÁ padecer y penar,\nPues adoro un imposible\nQue no he de poder lograr.",210,0,-1,201,"",0,4,"a",21,0,-1,0,293,293,"","",0,"rm_t3, palau_cantares, preciso_coleccion","","",4,0,0,[],"",""],["lafuente_madrid-p0293-03",15,"Un imposible me mata,\nPor un imposible muero;\nImposible es alcanzar\nEl imposible que quiero.",210,0,-1,201,"",0,4,"eo",38,0,-1,0,293,293,"","",0,"rm_t2, palau_cantares, fernan_caballero","","",4,0,0,[],"",""],["lafuente_madrid-p0293-04",15,"¡Compañerita del alma!\n¡Qué penas que pasa aquel\nQue tiene el agua en los labios,\nY no la puede beber!",210,0,-1,201,"",0,4,"e",-1,0,-1,0,293,293,"","",0,"palau_cantares","","",20,0,0,[],"",""],["lafuente_madrid-p0293-05",15,"Soy pájaro que en el agua\nTengo el alimento mio:\nMe estoy muriendo de sed,\nSiendo del agua nacido.",210,0,-1,201,"",0,4,"io",-1,0,-1,0,293,293,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0293-06",15,"Dentro de mi pecho tengo\nUna penilla mortal,\nPorque quiero á una {morena\nrubita.\nY no me la quieren dar.",210,0,-1,201,"",7,5,"a",-1,0,-1,0,293,293,"","",0,"","","",32,0,0,[],"",""],["lafuente_madrid-p0294-01",15,"Yo me arrimé á un árbol verde,\nY se le secó la flor.\n¡Mal haya quien se enamora\nPara vivir con dolor!",210,0,-1,201,"",0,4,"o",72,0,-1,0,294,294,"","",0,"rm_t3","","",2,0,0,[],"",""],["lafuente_madrid-p0294-01-e2",15,"El pobre más afligido\nŞacó del pecho una estátua,\nDe aquella divina imágen\nQue el corazon le quebranta.",210,0,-1,201,"",0,4,"aa",-1,0,-1,0,294,294,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0294-01-e3",15,"Yo pensé que el querer bien\nEra cosa de juguete;\nY se pasa pena negra\nQueriéndose firmemente.",210,0,-1,201,"",0,4,"ee",-1,0,-1,0,294,294,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0294-02a",15,"Yo pensé que un querer bien\nEra fácil de olvidar;\nY es callejon tan estrecho\nQue el que entra no sale más.",210,0,-1,201,"",0,4,"a",-1,0,-1,0,294,294,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0294-02b",15,"Santa Teresa en la cueva\nDe cilicios se vistió;\nY yo tengo que vestirme\nDe los cilicios de amor..",210,0,-1,201,"",0,4,"o",-1,0,-1,0,294,294,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0295-01",15,"Yo me enamoré, pensando\nQue el amor era ligero;\nNo ví carga más pesada,\nNi que más me quite el sueño.",210,0,-1,201,"",0,4,"eo",-1,0,-1,0,295,295,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0295-02",15,"Yo me metí en el querer,\nMuchachito criatura:\nCuando vine á abrir los ojos\nMe encontré en la sepultura.",210,0,-1,201,"",0,4,"ua",17,0,-1,0,295,295,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0295-03",15,"Todos cuantos van á verme\nMe dicen: ¡Ay qué dolor,\nMuchachito criatura,\nPreso en la cárcel de amor!",210,0,-1,201,"",0,4,"o",72,0,-1,0,295,295,"","",0,"rm_t3","","",2,0,0,[],"",""],["lafuente_madrid-p0295-04",15,"Mal haya el amor, mal haya,\nY quien me lo dió á entender;\nQue habiendo nacido libre,\nYo mismo me cautivé!",210,0,-1,201,"",0,4,"e",-1,0,-1,0,295,295,"","",0,"rm_t3, palau_cantares","","",7,0,0,[],"",""],["lafuente_madrid-p0295-05",15,"Mi corazon lo prendieron,\nY á la cárcel lo llevaron,\nY sin delito ninguno\nÁ muerte lo sentenciaron.",210,0,-1,201,"",0,4,"ao",41,0,-1,0,295,295,"","",0,"rm_t3","","",2,0,0,[],"",""],["lafuente_madrid-p0295-06",15,"Corazon, ¿dónde me llevas\nQue no te puedo seguir?\nTen cuidado no te metas\nDonde no puedas salir!",210,0,-1,201,"",0,4,"i",157,0,-1,0,295,295,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0295-07",15,"Mi corazon dió un suspiro,\nY el alma le preguntó:\n-Corazon, ¿por qué suspiras?\n-Alma, porque tengo amor.",210,0,-1,201,"",0,4,"o",-1,0,-1,0,295,295,"","",0,"rm_t3, palau_cantares, fernan_caballero","","",4,0,0,[],"",""],["lafuente_madrid-p0296-01",15,"El corazon dió un suspiro\nY el alma le dijo: cesa,\nNo suspires, corazon,\nQue nadie de tí se acuerda,",210,0,-1,201,"",0,4,"ea",-1,0,-1,0,296,296,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0296-02",15,"Triste el corazon se queja,\nY yo le pregunto triste:\nCorazon, ¿por qué te has muerto?\nY él responde: porque quise.",210,0,-1,201,"",0,4,"ie",-1,0,-1,0,296,296,"","",0,"rm_t3, palau_cantares, preciso_coleccion","","",4,0,0,[],"",""],["lafuente_madrid-p0296-03",15,"¿Quéme importa que florezca\nEl árbol de mi esperanza,\nSi se marchitan las flores,\nY jamás el fruto cuaja?",210,0,-1,201,"",0,4,"aa",-1,0,-1,0,296,296,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0296-04",15,"¡En qué confusion me hallo,\nTriste, sin saber qué hacer!\nAborrecerlo..... no puedo,\nAmarlo..... no puede ser.",210,0,-1,201,"",0,4,"e",20,0,-1,0,296,296,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0296-05",15,"Ya mi mal no tiene cura\nComo del cielo no venga,\nQue me ba puesto tu querer\nQue me va á tragar la tierra.",210,0,-1,201,"",0,4,"ea",-1,0,-1,0,296,296,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0296-06",15,"¿De qué sirve que yo quiera\nDisimular mi dolor,\nSi en los ojos y en la cara\nLlevo escrita la pasion?",210,0,-1,201,"",0,4,"o",-1,0,-1,0,296,296,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0296-07",15,"Una vela de dos onzas\nParece este cuerpo mio,\nQue de puro sentir penas\nSe ha quedado consumido.",210,0,-1,201,"",0,4,"io",-1,0,-1,0,296,296,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0297-01",15,"Si quieres cambiar, cambiemos\nCorazones á llorar:\nDáme el tuyo, y toma el mio,\nVerémos quién llora más.",210,0,-1,201,"",0,4,"a",-1,0,-1,0,297,297,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0297-02",15,"Anda, ve á Santa María,\nY encomiéndate á un divé,\nQue el que no pasa fatigas,\nNo sabe lo que es querer.",210,0,-1,201,"",0,4,"e",-1,0,-1,0,297,297,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0297-03",15,"Desde que paso tu calle\nEnamorado de tí,\nEstán llorando las piedras\nDe verme llorar á mí.",210,0,-1,201,"",0,4,"i",23,0,-1,0,297,297,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0297-04",15,"¡Desgraciado labrador,\nQue siembra y no coge trigo!\nMás desgraciado soy yo,\nQue no puedo hablar contigo.",210,0,-1,201,"",0,4,"io",106,0,-1,0,297,297,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0297-06",15,"Este vivir no es vivir:\n¡Verte y no poderte hablar!\nEsto, mi bien, es morir:\n¿Para qué tanto penar?",210,0,-1,201,"",1,4,"a",21,0,-1,0,297,297,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0297-07",15,"¡Válgame Dios de los cielos,\nQué desgraciado he nacido:\nPara todos sale el sol,\nY para mí no ha salido!",210,0,-1,201,"",0,4,"io",101,0,-1,0,297,297,"","",0,"rm_t3, palau_cantares","","",33,0,0,[],"",""],["lafuente_madrid-p0298-01",15,"¡Ay de mi, que me han quítado\nUna rosa, siendo mia,\nY la veo en otras manos\nMarchita y descolorida!",210,0,-1,201,"",0,4,"ia",-1,0,-1,0,298,298,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0298-02",15,"Nacimos para querernos,\nCon mala estrella nacimos;\nNi tú puedes olvidarme,\nNi yo olvidarte consigo.",210,0,-1,201,"",0,4,"io",-1,0,-1,0,298,298,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0298-03",15,"Quisiera verte y no verte,\nQuisiera hablarte y no hablarte,\nQuisiera no conocerte,\nPara poder olvidarte.",210,0,-1,201,"",1,4,"ae",8,0,-1,0,298,298,"","",0,"rm_t3, carrizo_salta, palau_cantares","","",12,0,0,[],"",""],["lafuente_madrid-p0298-04",15,"Más quisiera haberme muerto\nQue no haberte conocido,\nY no reinara la pena\nQue está reinando conmigo.",210,0,-1,201,"",0,4,"io",-1,0,-1,0,298,298,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0298-05",15,"Más valiera que mis ojos\nNunca te hubieran mirado,\nY con eso no viviera\nEn sino tan desgraciado",210,0,-1,201,"",0,4,"ao",14,0,-1,0,298,298,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0298-06",15,"¡Más quisiera haber nacido\nArbol silvestre en el campo,\nQue no haberte conocido\nPara sentir ahora tanto!",210,0,-1,201,"",0,4,"ao",-1,0,-1,0,298,298,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0298-07",15,"No me digas que te olvide,\nQue me lo dices llorando;\nToma tú misma el consejo,\nY podrás venir á darlo.",210,0,-1,201,"",0,4,"ao",-1,0,-1,0,298,298,"","",0,"rm_t3, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0299-01",15,"Ni contigo, ni sin tí\nTienen mis males remedio;\nContigo..... porque me matas,\nY sin ti..... porque me muero.",210,0,-1,201,"",0,4,"eo",-1,0,-1,0,299,299,"","",0,"rm_t3, palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0299-02",15,"La pena y la que no es pena,\nTodo es pena para mí:\nAyer penaba por verte,\nHoy peno porque te ví.",210,0,-1,201,"",0,4,"i",23,0,-1,0,299,299,"","",0,"palau_cantares","","",9,0,0,[],"",""],["lafuente_madrid-p0299-03",15,"Compañerita del alma,\n¿Qué quieres que yo te diga?\nQue con penillas me acuesto,\nMe levanto con penillas.",210,0,-1,201,"",0,4,"ia",-1,0,-1,0,299,299,"","",0,"rm_t3, palau_cantares","","",20,0,0,[],"",""],["lafuente_madrid-p0299-04",15,"Ya te he dicho, compañera,\nNo me vengas á buscar;\nDéjame solo en mi casa\nCon mi bien, ó con mi mal.",210,0,-1,201,"",0,4,"a",-1,0,-1,0,299,299,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0299-05",15,"Triste estoy de verte triste,\nAlégrate, vida mia;\nQue algun dia querrá Dios\nQue tengamos alegría.",210,0,-1,201,"",0,4,"ia",0,0,-1,0,299,299,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0299-06",15,"Un corazon de madera\nTengo que mandar hacer,\nQue ni sienta, ni padezca,\nNi sepa lo que es querer.",210,0,-1,201,"",0,4,"e",20,0,-1,0,299,299,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0300-01",15,"El corazon se me parte\nDe dolor y sentimiento,\nDe ver que estás en el mundo,\nY ya para mí te has muerto.",210,0,-1,201,"",0,4,"eo",-1,0,-1,0,300,300,"","",0,"palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0300-02",15,"Dejadme, pensamientillos,\nNo me esteis atormentando:\nSi la quise ó no la quise,\nNo me lo esteis recordando.",210,0,-1,201,"",0,4,"ao",33,0,-1,0,300,300,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0300-03",15,"Por Dios te lo pido, niña,\nY te lo pido llorando,\nQue no le cuentes á nadie\nLo que á mí me está pasando.",210,0,-1,201,"",0,4,"ao",33,0,-1,0,300,300,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0300-04",15,"Si mi corazon tuviera\nVidrieras de cristal,\nTe asomaras, y lo vieras\nCon cuánta penilla está!",210,0,-1,201,"",0,4,"a",-1,0,-1,0,300,300,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0300-05",15,"¡Válgame Dios de los cielos!\n¡Virgen del mayor dolor!\n¡Como una bayeta negra\nTengo yo mi corazon!",210,0,-1,201,"",0,4,"o",-1,0,-1,0,300,300,"","",0,"rm_t3, palau_cantares","","",33,0,0,[],"",""],["lafuente_madrid-p0301-01",15,"Cualquiera que me mirase,\nDirá que no tengo penas,\nY tengo mi corazon\nComo una bayeta negra.",210,0,-1,201,"",0,4,"ea",-1,0,-1,0,301,301,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0301-02",15,"Como una morcilla negra\nTengo yo mi corazon,\nSerranilla, si lo vieras,\nTe habia de dar dolor.",210,0,-1,201,"",0,4,"o",-1,0,-1,0,301,301,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0301-03",15,"Comunicame tu pena,\nYo te diré mi dolor,\nQue penas comunicadas.\nPenas con alivio son.",210,0,-1,201,"",0,4,"o",-1,0,-1,0,301,301,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0301-04",15,"Dentro de mi corazon\nTengo yo una llaga viva,\nQueme ha hecho tu querer\nDe pasar puras fatigas.",210,0,-1,201,"",0,4,"ia",-1,0,-1,0,301,301,"","",0,"","","",7,0,0,[],"",""],["lafuente_madrid-p0301-05",15,"Te pido por los cordeles\nQue tiene mi Dios al cuello,\nQue no me des más penillas;\nQue ya no tiene remedio.",210,0,-1,201,"",0,4,"eo",-1,0,-1,0,301,301,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0301-06",15,"Por aquella cruz bendita\nQue en Capuchinos está,\nQue no me des más penitas,\nQue no las puedo llevar.",210,0,-1,201,"",0,4,"a",-1,0,-1,0,301,301,"","",0,"rm_t3, palau_cantares","","",9,0,0,[],"",""],["lafuente_madrid-p0302-02",15,"Niña mia, no más penas,\nMira que no soy de bronce;\nQue una piedra se quebranta\nÁ fuerza de darle golpes.",210,0,-1,201,"",0,4,"oe",-1,0,-1,0,302,302,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0302-03",15,"¿Hasta cuándo, vida mia,\nTengo de vivir penando?\nLas horitas de la noche\nMe las paso suspirando.",210,0,-1,201,"",0,4,"ao",33,0,-1,0,302,302,"","",0,"palau_cantares","","",11,0,0,[],"",""],["lafuente_madrid-p0302-04",15,"¿Dónde estás, prenda querida,\nCielo de mis pensamientos:\nEn dónde estás, que no escuchas\nMis suspiros y lamentos?",210,0,-1,201,"",0,4,"eo",234,0,-1,0,302,302,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0302-05",15,"Entre la hostia y el cáliz\nÁ mi Dios se lo pedi,\nQue no te maten las penas,\nQue me estan matando á mí.",210,0,-1,201,"",0,4,"i",23,0,-1,0,302,302,"","",0,"palau_cantares, fernan_caballero","","",3,0,0,[],"",""],["lafuente_madrid-p0302-06",15,"Si lágrimas fueran piedras,\nLas que por ti he derramado,\nUn fuerte castillo hiciera\nEn medio del mar salado.",210,0,-1,201,"",0,4,"ao",14,0,-1,0,302,302,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0302-07",15,"Compañera de mi vida,\nYa no me conocerás,\nQue acaba más una pena,\nQue una larga enfermedad.",210,0,-1,201,"",0,4,"a",-1,0,-1,0,302,302,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0303-01",15,"Hasta la cama en que duermo\nTiene lástima de mí,\nDe ver lo que gimo y lloro,\nCuando me acuerdo de tí.",210,0,-1,201,"",0,4,"i",23,0,-1,0,303,303,"","",0,"","","",7,0,0,[],"",""],["lafuente_madrid-p0303-02",15,"Aunque tengo mal color,\nNo te pienses cosa mala;\nSon penas del corazon,\nQue me salen á la cara.",210,0,-1,201,"",0,4,"aa",-1,0,-1,0,303,303,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0303-03",15,"No sé cómo no estoy loco\nCon esta pena que tengo,\nQue me ha puesto tu querer,\nTonto, sordo, mudo y ciego.",210,0,-1,201,"",0,4,"eo",-1,0,-1,0,303,303,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0303-04",15,"¿No hay quien me ayude á una pena\nPagándole su jornal?\nComo mi pena es tan grande,\nNadie me quiere ayudar.",210,0,-1,201,"",0,4,"a",-1,0,-1,0,303,303,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0303-05",15,"¿Qué saco yo de quererte,\nNi vivir por ti penando,\nSi tú no puedes ser mia,\nComo Dios no haga un milagro?",210,0,-1,201,"",0,4,"ao",-1,0,-1,0,303,303,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0303-06",15,"¿Qué importa que tú me quieras\nY que yo te quiera á tí,\nSi lo que yo solicito\nNo lo puedo conseguir?",210,0,-1,201,"",0,4,"i",-1,0,-1,0,303,303,"","",0,"rm_t3, palau_cantares, preciso_coleccion","","",4,0,0,[],"",""],["lafuente_madrid-p0304-01",15,"Olvidé á Dios por quererte,\nPor tí la gloria perdí.....\nY ahora me vengo á quedar\nSin Dios, sin gloria y sin tí.",210,0,-1,201,"",3,4,"i",23,0,-1,0,304,304,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0304-02",15,"Suspiros, ¿por qué quereis\nSalir del corazon triste,\nSi sabeis que adonde vais\nNunca jamas os reciben?",210,0,-1,201,"",0,4,"ie",-1,0,-1,0,304,304,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0304-03",15,"Quise bien, fuí aborrecido;\nAdoré, fuí despreciado;\nMe lamenté, no fuí oido;\nPorfié, no fuí escuchado.",210,0,-1,201,"",1,4,"ao",14,0,-1,0,304,304,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0304-04",15,"Entre fatigas y luchas\nMi alma es la que batalla,\nComo son mis penas muchas,\nMi amor lo sufre y lo calla.",210,0,-1,201,"",1,4,"aa",249,0,-1,0,304,304,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0304-05",15,"Desde que aquella morena\nMe dió penillas tan grandes,\nNadie quiero que me quiera,\nNi quiero querer á nadie.",210,0,-1,201,"",0,4,"ae",-1,0,-1,0,304,304,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0304-06",15,"Á llorar mi triste suerte\nEn la cama me senté,\nConsiderando tan lejos\nLo que tan cerca soñé.",210,0,-1,201,"",0,4,"e",77,0,-1,0,304,304,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0304-07",15,"Yo subí como la yedra\nHasta el último elemento:\nY luego volvi á bajar\nComo la piedra á su centro.",210,0,-1,201,"",0,4,"eo",-1,0,-1,0,304,304,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0305-01",15,"Soñé la dicha de hallarme\nEn los brazos de mi dueño,\nY al despertar sin la dicha,\nHallé que la dicha es sueño.",210,0,-1,201,"",0,4,"eo",138,0,-1,0,305,305,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0305-02",15,"Soñaba yo que tenia\nContento mi corazon;\nPero ¿es verdad, madre mia,\nQue los sueños, sueños son?",210,0,-1,201,"",1,4,"o",31,0,-1,0,305,305,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0305-03",15,"Por culpa de malas lenguas\nPerdi la prenda que amaba,\nQue me la encuentro en la calle.\nNi me mira, ni me habla.",210,0,-1,201,"",0,4,"aa",-1,0,-1,0,305,305,"","",0,"rm_t3","","",3,0,0,[],"",""],["lafuente_madrid-p0305-04",15,"Ya te he dicho, corazon,\nSegunda y tercera vez,\nQue no llames á esa puerta,\nQue no te han de responder.",210,0,-1,201,"",0,4,"e",-1,0,-1,0,305,305,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0305-05",15,"Ya no tengo yo en mi pecho\nPaciencia para sufrir;\nSiempre me estoy acordando\nDe quien se olvida de mí.",210,0,-1,201,"",0,4,"i",-1,0,-1,0,305,305,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0305-06",15,"Tres dias há que no como\nMás que lágrimas y pan:\nEstos son los alimentos\nQue tus amores me dan.",210,0,-1,201,"",0,4,"a",147,0,-1,0,305,305,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0305-07",15,"Nadie se duela de mi,\nSólo mis tormentos pase;\nQue el que busca el mal por si,\nÁ nadie debe quejarse.",210,0,-1,201,"",0,4,"ae",-1,0,-1,0,305,305,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0306-01",15,"Si piensas que duermo, velo,\nY me suelo despertar;\nSobre la cama me siento,\nY te comienzo á llamar.",210,0,-1,201,"",0,4,"a",21,0,-1,0,306,306,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0306-02",15,"Si las piedras de tu calle\nTuvieran conocimiento,\nCuando me vieran venir\nLloraran de sentimiento.",210,0,-1,201,"",0,4,"eo",94,0,-1,0,306,306,"","",0,"rm_t3","","",6,0,0,[],"",""],["lafuente_madrid-p0306-03",15,"Pájaro que vas volando,\nY en el pico llevas hilo,\nDámelo para coser\nMi corazon que está herido.",210,0,-1,201,"",0,4,"io",-1,0,-1,0,306,306,"","",0,"rm_t3, palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0306-04",15,"Me dicen que soy hermosa;\nMas me retiro del mundo,\nQue tengo mi corazon\nDentro del pecho difunto.",210,0,-1,201,"",0,4,"uo",-1,0,-1,0,306,306,"","",0,"palau_cantares, fernan_caballero","","",3,0,0,[],"",""],["lafuente_madrid-p0306-05",15,"Más quisiera que al principio\nMe hubieras aborrecido,\nQue no verme aprisionado\nDe un bien que lloro perdido.",210,0,-1,201,"",0,4,"io",101,0,-1,0,306,306,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0306-06",15,"Las sábanas de mi cama\nTodas las noches las lavo,\nCon lágrimas de mis ojos\nAl ver que me has olvidado.",210,0,-1,201,"",0,4,"ao",-1,0,-1,0,306,306,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0306-07",15,"Es un fuego de alquitran\nEste en que me estoy ardiendo,\nQue más se aviva la llama\nMientras más lágrimas vierto.",210,0,-1,201,"",0,4,"eo",-1,0,-1,0,306,306,"","",0,"palau_cantares, preciso_coleccion","","",3,0,0,[],"",""],["lafuente_madrid-p0307-01",15,"Las penas que por ti paso,\nNo se pueden numerar;\nDáme veneno en un vaso,\nY acábame de matar.",210,0,-1,201,"",1,4,"a",21,0,-1,0,307,307,"","",0,"rm_t3, palau_cantares","","",7,0,0,[],"",""],["lafuente_madrid-p0307-02",15,"Si me quieres ver morir,\nDáme un vaso de veneno,\nY luego podrás decir:\nYo maté á mi dulce dueño.",210,0,-1,201,"",0,4,"eo",-1,0,-1,0,307,307,"","",0,"","","",7,0,0,[],"",""],["lafuente_madrid-p0307-03",15,"Dicen que me quieres dar\nSoliman para que muera;\nBien sé yo que tú no quieres\nQue á mi me trague la tierra.",210,0,-1,201,"",0,4,"ea",-1,0,-1,0,307,307,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0307-04",15,"No me mates, no me mates,\nDéjame que viva, viva;\nDéjame que pase, pase,\nEn este mundo fatigas.",210,0,-1,201,"",0,4,"ia",-1,0,-1,0,307,307,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0307-05",15,"En tu maceta sembré\nLa semilla del encanto:\nCon lágrimas la regué:\n¡Mal haya quien quiere tanto!",210,0,-1,201,"",1,4,"ao",30,0,-1,0,307,307,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0307-06",15,"Aquel que tiene fatigas,\nSe le conoce en la cara:\nÁ mí me están ahogando,\nY no me conoces nada.",210,0,-1,201,"",0,4,"aa",-1,0,-1,0,307,307,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0307-07",15,"En medio de mis fatigas\nEl morirme estoy sintiendo,\nPor no dejar en el mundo\nPersona que estoy queriendo.",210,0,-1,201,"",0,4,"eo",52,0,-1,0,307,307,"","",0,"palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0308-01",15,"El corazon de mi amante\nLo van á sacramentar,\nY el mio se está muriendo\nDe la misma enfermedad.",210,0,-1,201,"",0,4,"a",-1,0,-1,0,308,308,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0308-02",15,"El cenador de mi huerto\nLleno está de mustias flores,\nVenid, muchachas, y ved\nLa imágen de mis amores.",210,0,-1,201,"",0,4,"oe",5,0,-1,0,308,308,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0308-03",15,"Yo soy una triste losa,\nTestigo de todo luto;\nTú serás juez de mi causa,\nY de mi muerte verdugo.",210,0,-1,201,"",0,4,"uo",-1,0,-1,0,308,308,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0308-04",15,"Ya mi muerte decretada\nTe dije con sentimiento;\nLa súplica es escusada,\nPorque me muero contento.",210,0,-1,201,"",1,4,"eo",94,0,-1,0,308,308,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0308-05",15,"Gitana, si oyes doblar,\nNo preguntes quien ha muerto,\nQue ha sido mi corazon\nDe penilla y sentimiento.",210,0,-1,201,"",0,4,"eo",-1,0,-1,0,308,308,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0308-06",15,"Dile al sacristan que doble\nY ponga negras cortinas,\nPorque ya murió aquel hombre\nQue rondaba tus esquinas",210,0,-1,201,"",0,4,"ia",243,0,-1,0,308,308,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0309-01",15,"Cuándo muera, por letrero\nMe pondrás en el sepulcro:\nAquí yace un desdichado,\nQue de veras querer supo.",210,0,-1,201,"",0,4,"uo",-1,0,-1,0,309,309,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0309-02",15,"Si el campo santo visitas,\nPronto me hallarás alli,\nY habrá en mi losa un letrero,\nQue solo diga: ¡ay de mi!",210,0,-1,201,"",0,4,"i",23,0,-1,0,309,309,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0309-03",15,"Si vas á mi sepultura,\nPon un pié en la losa y di:\nAqui yace un desdichado\nQue murió de amor por mí.",210,0,-1,201,"",0,4,"i",23,0,-1,0,309,309,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0309-04",15,"Yase murió mi marido,\nYa se murió mi consuelo,\nYa no tengo quien me diga:\nOjillos de terciopelo.",210,0,-1,201,"",0,4,"eo",10,0,-1,0,309,309,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0309-05",15,"Ya mi padre se murió;\nSoy hijo y debo llorar:\nUn bien como el que he perdido,\nNo lo volveré á encontrar.",210,0,-1,201,"",0,4,"a",21,0,-1,0,309,309,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0309-06",15,"Hermanita de mi vida,\nPadre y madre ya muriéron;\nYa nos quedamos los dos\nÁ la clemencia del cielo.",210,0,-1,201,"",0,4,"eo",-1,0,-1,0,309,309,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0310-01",15,"Ya se me murió mi madre,\n¡Mal haya mi desventura!\nNinguno pasa fatigas\nMientras su madre le dura.",210,0,-1,201,"",0,4,"ua",17,0,-1,0,310,310,"","",0,"","","",5,0,0,[],"",""],["lafuente_madrid-p0310-02",15,"Me han dicho que estás malita\nY que te sangran mañana;\nÁ tí te sangran del pié,\nY á mí me sangran del alma.",210,0,-1,201,"",0,4,"aa",-1,0,-1,0,310,310,"","",0,"rm_t3, palau_cantares, fernan_caballero","","",6,0,0,[],"",""],["lafuente_madrid-p0310-03",15,"¿Quién ha sido el cirujano\nQue te ha mandado sangrar?\n¿Siendo tú un ángel humano,\nQué sangre tienes de dar?",210,0,-1,201,"",1,4,"a",21,0,-1,0,310,310,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0310-04",15,"En el carro de los muertos\nHa pasado por aquí;\nLlevaba la mano fuera.....\n¡Por eso la conoci!",210,0,-1,201,"",0,4,"i",23,0,-1,0,310,310,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0310-05",15,"Llorad, llorad, ojos mios,\nLlorad, que teneis por qué;\nQue no es vergüenza en un hombre\nLlorar por una mujer.",210,0,-1,201,"",0,4,"e",-1,0,-1,0,310,310,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0310-06",15,"Ya mi madre se murió,\n¡Ay de mí, qué desventura!\nDichoso puede llamarse\nEl que su madre le dura.",210,0,-1,201,"",0,4,"ua",17,0,-1,0,310,310,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0311-01",15,"De llorar me quedé ciego\nCuando supe que era muerta.\n¡De qué me sirven los ojos\nSi no he de volver á verla!",210,0,-1,201,"",0,4,"ea",-1,0,-1,0,311,311,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0311-02",15,"¡Anda con Dios, fortunilla,\nQue por fin me la pegastes!\n¡Á la mejor ocasion\nTe fuistes, y me dejastes!",210,0,-1,201,"",0,4,"ae",142,0,-1,0,311,311,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0311-03",15,"Ya no vivo yo con gusto,\nYa mi suerte se trocó;\nQuien perdió lo que bien quiso,\nCuanto hay que perder perdió",210,0,-1,201,"",0,4,"o",2,0,-1,0,311,311,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0311-04",15,"¡Virgen del Carmen, valedme!\nQue yo me muero de pena;\nQue perdí las esperanzas,\nComo aquel que se condena.",210,0,-1,201,"",0,4,"ea",59,0,-1,0,311,311,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0311-05",15,"Doblen, doblen las campanas,\nY que toquen á silencio;\nVistan las flores de luto,\nQue mi corazon ha muerto.",210,0,-1,201,"",0,4,"eo",-1,0,-1,0,311,311,"","",0,"rm_t3, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0311-06",15,"La alegría en mi no reina,\nMuerto tengo el corazon:\n¡Madre mia del Amparo,\nValedme en esta ocasion!",210,0,-1,201,"",0,4,"ao",-1,0,-1,0,311,311,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0311-07",15,"Si no fuera por las gentes\nMe vestiria de luto,\nPorque tengo el corazon\nDentro del pecho difunto.",210,0,-1,201,"",0,4,"uo",-1,0,-1,0,311,311,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0312-01",15,"De pura bayeta negra\nMi cuerpo se ha de vestir;\nQue este es el propio vestido\nDe aquel que sabe sentir.",210,0,-1,201,"",0,4,"i",157,0,-1,0,312,312,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0312-02",15,"Una soledad deseo\nPara aliviar mis fatigas,\nQue allí regarán mis ojos\nPlantas y flores marchitas.",210,0,-1,201,"",0,4,"ia",-1,0,-1,0,312,312,"","",0,"preciso_coleccion","","",3,0,0,[],"",""],["lafuente_madrid-p0312-03",15,"Soy el herido sin sangre,\nSoy el muerto sin acero,\nSoy el que penando vivo,\nSoy el que penando muero.",210,0,-1,201,"",0,4,"eo",38,0,-1,0,312,312,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0312-04",15,"Tengo el corazon mas duro\nQue las piedras de la calle,\nY son tan grandes mis penas,\nQue llora gotas de sangre.",210,0,-1,201,"",0,4,"ae",-1,0,-1,0,312,312,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0312-05",15,"En lo profundo del mar\nVoy á sepultar mi pena,\nPorque mi pena es tan grande,\nQue ya no cabe en la tierra.",210,0,-1,201,"",0,4,"ea",-1,0,-1,0,312,312,"","",0,"palau_cantares","","",7,0,0,[],"",""],["lafuente_madrid-p0312-06",15,"Lágrimas pedi á una fuente\nPara llorar mi tormento,\nPorque es tan grande mi pena,\nQue ya ni lágrimas tengo.",210,0,-1,201,"",0,4,"eo",-1,0,-1,0,312,312,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0312-07",15,"Ya no soy yo quien he sido,\nNi quien yo solia ser;\nSoy un cuadro de tristeza\nArrimado á una pared.",210,0,-1,201,"",0,4,"e",-1,0,-1,0,312,312,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0313-01",15,"De pena y de sentimiento\nNo me trato con las gentes;\nEn los rincones me meto,\nY á voces llamo á la muerte.",210,0,-1,201,"",0,4,"ee",-1,0,-1,0,313,313,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0313-02",15,"Yo no sé lo que me pasa,\nNi tampoco lo que quiero;\nDigo y no sé lo que digo,\nSiento y no sé lo que siento.",210,0,-1,201,"",0,4,"eo",-1,0,-1,0,313,313,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0313-03",15,"¿Qué importa que mis amigos\nMe saquen á divertir,\nSi en volviendo yo á mi casa\nVuelvo de nuevo á sentir?",210,0,-1,201,"",0,4,"i",157,0,-1,0,313,313,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0313-04",15,"En medio de mi fatiga\nPor vivir quise dormirme,\nQue el que vive como yo,\nCuando duerme es cuando vive.",210,0,-1,201,"",0,4,"ie",-1,0,-1,0,313,313,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0313-05",15,"El dia paso con pena\nY la noche con dolor;\nSuspirando me anochece,\nLlorando me sale el sol.",210,0,-1,201,"",0,4,"o",-1,0,-1,0,313,313,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0313-06",15,"Cuando me siento en la cama,\nY repaso mi memoria,\nLos ojos del corazon\nLágrimas de sangre lloran.",210,0,-1,201,"",0,4,"oa",-1,0,-1,0,313,313,"","",0,"rm_t3","","",4,0,0,[],"",""],["lafuente_madrid-p0314-01",15,"En la soledad del campo\nMe puse á llorar mis penas,\nY fué tan grande mi llanto,\nQue florecieron las yerbas.",210,0,-1,201,"",0,4,"ea",-1,0,-1,0,314,314,"","",0,"","","",5,0,0,[],"",""],["lafuente_madrid-p0314-02",15,"Á una piedra de la calle\nLe contaba mi dolor;\n¡Mira lo que le diria,\nQue la piedra se partió,",210,0,-1,201,"",0,4,"o",-1,0,-1,0,314,314,"","",0,"palau_cantares, fernan_caballero","","",5,0,0,[],"",""],["lafuente_madrid-p0314-03",15,"Me puse á llorar mis penas\nEn un monte de espesura,\nY se secaron las ramas\nQuedando raices puras.",210,0,-1,201,"",0,4,"ua",-1,0,-1,0,314,314,"","",0,"rm_t3","","",3,0,0,[],"",""],["lafuente_madrid-p0314-04",15,"Ayer tarde fuí al campo\nÁ llorar por mi sentir:\nY á un árbol que me escuchaba\nSe le secó la raiz.",210,0,-1,201,"",0,4,"i",-1,0,-1,0,314,314,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0314-05",15,"Á orillas del mar me siento,\nÁ voces llamo á quien amo,\nY como no me responde,\nMuchas lágrimas derramo.",210,0,-1,201,"",0,4,"ao",100,0,-1,0,314,314,"","",0,"palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0314-06",15,"¡Ay, pobrecito de mí,\nQue echo suspiros al aire!\n¡Ay, que se los lleva el viento,\nY no me responde nadie!",210,0,-1,201,"",0,4,"ae",-1,0,-1,0,314,314,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0315-01",15,"¡Válgame Dios de los cielos,\nQué penoso que es mi mal!\n¡Suspirando tengo alivio,\nY no puedo suspirar!",210,0,-1,201,"",0,4,"a",-1,0,-1,0,315,315,"","",0,"palau_cantares","","",33,0,0,[],"",""],["lafuente_madrid-p0315-02",15,"¿Cómo quieres que yo salga\nAl campo de la alegría,\nSi se marchitan las flores\nAl ver esta pena mia?",210,0,-1,201,"",0,4,"ia",0,0,-1,0,315,315,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0315-03",15,"¡Oh! cristalina corriente,\nQue vas á buscar tu centro,\nLlévate á un hombre infeliz\nQue vive, pero muriendo!",210,0,-1,201,"",0,4,"eo",-1,0,-1,0,315,315,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0315-04",15,"Ni en Italia, ni en España,\nNien Francia, ni en Berberia,\nNi en todo lo que elsol baña,\nHay pena como la mia.",210,0,-1,201,"",1,4,"a",0,0,-1,0,315,315,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0315-05",15,"La soledad me acompaña,\nLa música me entristece,\nAborreciendo la vida,\nApeteciendo la muerte.",210,0,-1,201,"",0,4,"ee",-1,0,-1,0,315,315,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0315-06",15,"Todas las penas del mundo\nNo igualan con esta mia,\nQue se me pasa llorando\nToda la flor de mi vida.",210,0,-1,201,"",0,4,"ia",-1,0,-1,0,315,315,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0316-01",15,"Los pajarillos y yo\nNos levantamos á un tiempo;\nEllos á cantar al alba,\nYo á llorar mi sentimiento.",210,0,-1,201,"",0,4,"eo",-1,0,-1,0,316,316,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0316-02",15,"¿Qué importa que la calandria\nEl ruiseñor y el gilguero,\nCanten para divertirme,\nSi en mí no cabe consuelo?",210,0,-1,201,"",0,4,"eo",-1,0,-1,0,316,316,"","",0,"rm_t3","","",3,0,0,[],"",""],["lafuente_madrid-p0316-03",15,"Ni la tortolilla triste,\nNi el canario mas sonoro,\nNi la fuente cristalina\nLlorarán, como yo lloro.",210,0,-1,201,"",0,4,"oo",85,0,-1,0,316,316,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0316-04",15,"Calla, ruiseñor, no cantes,\nAcompaña mi dolor:\n¡Que no es razon que tú cantes,\nEstando tan triste yo!",210,0,-1,201,"",0,4,"o",-1,0,-1,0,316,316,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0316-05",15,"Yo pensé que con el tiempo\nMis penas se acabarian,\nY se me van aumentando\nComo las horas del dia.",210,0,-1,201,"",5,4,"a",-1,0,-1,0,316,316,"","",0,"rm_t3, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0317-01",15,"Áaquel pajarito, madre,\nQue canta en el árbol verde,\nDecidle por Dios que calle,\nPorque su canto me ofende.",210,0,-1,201,"",0,4,"ee",-1,0,-1,0,317,317,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0317-02",15,"¡Válgame san Sebastian,\nPatron de Villamartin!\nTodas las penas se acaban,\nLa mia no tiene fin.",210,0,-1,201,"",5,4,"i",-1,0,-1,0,317,317,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0317-03",15,"Angustia, pena, pesar,\nUn terrible sentimiento\nEn mi reina sin parar,\nY ya me falta el aliento.",210,0,-1,201,"",1,4,"eo",94,0,-1,0,317,317,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0317-04",15,"Son tan grandes mis fatigas\nQue me tiran á ahogar;\nUnas se van, y otras vienen,\nComo las olas del mar.",210,0,-1,201,"",0,4,"a",21,0,-1,0,317,317,"","",0,"","","",4,0,0,[],"",""],["lafuente_madrid-p0318-01",15,"¿No hay quién me pegue un tirillo\nQue me parta el corazon;\nQue estoy viviendo en el mundo\nCon muchísimo dolor?",210,0,-1,201,"",0,4,"o",-1,0,-1,0,318,318,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0318-02",15,"Acaba, penita, acaba,\nDáme muerte de una vez;\nQue con la muerte se acaba\nLa pena y el padecer.",210,0,-1,201,"",0,4,"e",-1,0,-1,0,318,318,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0318-03",15,"Horitas tengo en el dia\nDe sentimiento y de pena;\nSi me viniera la muerte,\nPor Dios que no lo sintiera.",210,0,-1,201,"",0,4,"ea",-1,0,-1,0,318,318,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0318-04",15,"¡Cuántas personillas grandes\nViene la muerte y se lleva,\nY á mí no quiere llevarme\nQue se lo pido de veras!",210,0,-1,201,"",0,4,"ea",-1,0,-1,0,318,318,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0318-05",15,"Nadie se acerque á mi cama,\nQue estoy malito de pena,\nY á quien muere de este mal,\nHasta la ropa le quema.",210,0,-1,201,"",0,4,"ea",-1,0,-1,0,318,318,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0318-06",15,"No te aflijas, corazon,\nY cese ya tu quebranto,\nQue vendrá un tiempo mejor\nY se acabará tu llanto.",210,0,-1,201,"",0,4,"ao",30,0,-1,0,318,318,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0318-07",15,"Se acabará mi querer,\nSe acabará mi llorar,\nSe acabará mi tormento,\nY todo se acabará.",210,0,-1,201,"",0,4,"a",-1,0,-1,0,318,318,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0319-01",15,"Á la sierra me he de ir\nÁ buscar una morena,\nQue las chicas de mi pueblo\nNinguna me da ya pena.",210,0,-1,202,"",0,4,"ea",59,0,-1,0,319,319,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0319-02",15,"Eres avellana vana,\nEres almendro sin flor,\nEres rosa sin capullo,\nEres clavel sin olor.",210,0,-1,202,"",0,4,"o",72,0,-1,0,319,319,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0319-03",15,"Debajo de tu ventana\nMe encontré un pañuelo azul\nCon un letrero que dice:\n¡Qué poco me gustas tú!",210,0,-1,202,"",0,4,"u",-1,0,-1,0,319,319,"","",0,"palau_cantares","","",29,0,0,[],"",""],["lafuente_madrid-p0319-04",15,"Cuando paso por tu puerta\nLlevo la capa arrastrando,\nPorque no diga tu madre\nQue te voy enamorando.",210,0,-1,202,"",0,4,"ao",33,0,-1,0,319,319,"","",0,"","","",17,0,0,[],"",""],["lafuente_madrid-p0319-05",15,"Cuando paso por tu puerta\nCompro pan y voy comiendo,\nPorque no diga tu madre\nQue del aire me mantengo.",210,0,-1,202,"",0,4,"eo",-1,0,-1,0,319,319,"","",0,"","","",17,0,0,[],"",""],["lafuente_madrid-p0319-06",15,"Anda diciendo tu madre\nQue yo á tí te he entretenido;\nY te tengo yo apuntada\nEn el libro del olvido.",210,0,-1,202,"",0,4,"io",101,0,-1,0,319,319,"","",0,"palau_cantares","","",23,0,0,[],"",""],["lafuente_madrid-p0320-01",15,"Se puso tu madre, y dijo\nQue eras tú mejor que yo;\nAnda, ve y dile á tu madre,\nQue durmiendo lo soñó.",210,0,-1,202,"",0,4,"o",2,0,-1,0,320,320,"","",0,"","","",8,0,0,[],"",""],["lafuente_madrid-p0320-02",15,"Se puso tu madre, y dijo\nQue la reina para tí;\nAnda, ve y dile á tu madre\nQue la reina está en Madrid.",210,0,-1,202,"",0,4,"i",-1,0,-1,0,320,320,"","",0,"palau_cantares","","",8,0,0,[],"",""],["lafuente_madrid-p0320-03",15,"Anda diciendo tu madre\nQue te mereces la reina;\nAnda, ve y dile á ese trapo\nQue vaya á Madrid por ella.",210,0,-1,202,"",0,4,"ea",-1,0,-1,0,320,320,"","",0,"palau_cantares","","",23,0,0,[],"",""],["lafuente_madrid-p0320-04",15,"Niña de los veinte novios,\nQue con ninguno te casas,\nSi te guardas para un rey,\nCuatro tiene la baraja.",210,0,-1,202,"",0,4,"aa",-1,0,-1,0,320,320,"","",0,"rm_t3, palau_cantares","","",11,0,0,[],"",""],["lafuente_madrid-p0320-05",15,"Si tu madre quiere un rey,\nCuatro tiene la baraja:\nRey de bastos, rey de oros,\nRey de copas, rey de espadas.",210,0,-1,202,"",0,4,"aa",-1,0,-1,0,320,320,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0321-01",15,"Niña de los veinte novios,\nY conmigo veinte y uno;\nSi todos son como yo,\nNunca has tenido ninguno.",210,0,-1,202,"",0,4,"uo",230,0,-1,0,321,321,"","",0,"","","",11,0,0,[],"",""],["lafuente_madrid-p0321-02",15,"Me han dicho que tiene usté\nCatorce novios contados,\nConmigo no cuente usté,\nQue tengo el hato aviado.",210,0,-1,202,"",0,4,"ao",-1,0,-1,0,321,321,"","",0,"rm_t3","","",2,0,0,[],"",""],["lafuente_madrid-p0321-04",15,"Cuando yo te quise á tí,\nNo estaba yo en mi sentido;\nPorque si lo hubiera estado,\nOtra cosa hubiera sido.",210,0,-1,202,"",0,4,"io",101,0,-1,0,321,321,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0321-05",15,"Si piensas que yo te quiero,\nPorque te miro y me rio;\nSoy un poquillo burlona,\nY tú no lo has conocido.",210,0,-1,202,"",0,4,"io",-1,0,-1,0,321,321,"","",0,"palau_cantares","","",7,0,0,[],"",""],["lafuente_madrid-p0321-06",15,"Si piensas que yo te quiero,\nPorque te miro á la cara;\nEs como el que va á la feria,\nÁ ver y no comprar nada.",210,0,-1,202,"",0,4,"aa",-1,0,-1,0,321,321,"","",0,"palau_cantares","","",7,0,0,[],"",""],["lafuente_madrid-p0322-02",15,"Que tenga la boca grande,\nO tenga la boca chica;\n¿Si no has de ser mi marido,\nÁ qué me tomas medida?",210,0,-1,202,"",0,4,"ia",-1,0,-1,0,322,322,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0322-03",15,"Pensabas que te queria,\nY era por entretenerme;\nMientras otro me salia,\nMe servias de juguete.",210,0,-1,202,"",0,4,"ee",-1,0,-1,0,322,322,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0322-04",15,"¡Qué bien te habrás divertido\nEn el tiempo de mi ausencia!\nYo tambien hice lo mismo,\nPor descargar tu conciencia.",210,0,-1,202,"",0,4,"ea",46,0,-1,0,322,322,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0322-05",15,"Echale trigo á la era\nY conmigo no platiques,\nQue tengo yo quien me quiera\nDesde el dia que te fuiste.",210,0,-1,202,"",0,4,"ie",-1,0,-1,0,322,322,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0322-06",15,"Pensaba el tonto, pensaba,\nQue yo por él me moria;\nÉl pensaba, y yo pensaba\nCómo se la pegaria.",210,0,-1,202,"",1,4,"aa",-1,0,-1,0,322,322,"","",0,"rm_t3","","",3,0,0,[],"",""],["lafuente_madrid-p0322-07",15,"Se pensaba el mozo vano\nQue yo por él me moria;\nDesde que no hablo con él,\nSe me ha alargado la vida.",210,0,-1,202,"",0,4,"ia",-1,0,-1,0,322,322,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0323-01",15,"Una vez tuve una novia,\nY ella pretendió dejarme,\nY yo tomé pan con tiempo,\nAntes que me diera hambre.",210,0,-1,202,"",0,4,"ae",-1,0,-1,0,323,323,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0323-02",15,"Anda, véte, no te quiero,\nQue ya me cansé de amarte,\nQue eres farol encendido\nQue alumbras á todas partes.",210,0,-1,202,"",0,4,"ae",-1,0,-1,0,323,323,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0323-03",15,"Pensabas tú que tenias\nEl pájaro de la cola,\nY luego que te se ha ido,\nTe has quedado como boba.",210,0,-1,202,"",0,4,"oa",-1,0,-1,0,323,323,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0323-04",15,"De san Juan quiero la palma,\nDe Santiago la cruz,\nDe tu cuerpo, compañera,\nNo quiero ni la salud.",210,0,-1,202,"",0,4,"u",-1,0,-1,0,323,323,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0323-05",15,"Cuando quise, no quisiste,\nAhora que quieres, no quiero;\nPasa tú la vida triste,\nQue yo la pasé primero.",210,0,-1,202,"",1,4,"eo",38,0,-1,0,323,323,"","",0,"palau_cantares","","",8,0,0,[],"",""],["lafuente_madrid-p0323-06",15,"Aunque tu padre me diera\nLa mula y el carreton,\nNo me casara contigo\nPor tu mala condicion.",210,0,-1,202,"",0,4,"o",-1,0,-1,0,323,323,"","",0,"","","",7,0,0,[],"",""],["lafuente_madrid-p0324-01",15,"No quiero comer contigo\nGallinas ni pavos reales;\nQuiero pan de municion\nCon persona que me agrade.",210,0,-1,202,"",0,4,"ae",-1,0,-1,0,324,324,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0324-02",15,"Anda, véte en hora mala,\nY en tu cara te lo digo:\nQue eres tú muy poca cosa\nPara casarte conmigo.",210,0,-1,202,"",0,4,"io",106,0,-1,0,324,324,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0324-03",15,"No quiero que tú me quieras,\nQue yo quien me quiera tengo,\nY de tu vida y milagros\nMuy largas noticias tengo.",210,0,-1,202,"",0,4,"eo",-1,0,-1,0,324,324,"","",0,"rm_t3, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0324-04",15,"Aunque me ves tan chiquita,\nHuérfana de padre y madre,\nNo se cria la lechuga\nPara tan flojo vinagre.",210,0,-1,202,"",0,4,"ae",-1,0,-1,0,324,324,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0324-05",15,"Yo me enamoré de noche,\nY la luna me engañó:\nOtra vez que me enamoro,\nSerá de dia y con sol.",210,0,-1,202,"",0,4,"o",-1,0,-1,0,324,324,"","",0,"","","",9,0,0,[],"",""],["lafuente_madrid-p0325-01",15,"Tienes el amor trampero,\nComo se suele decir;\nCuantas veo, tantas quiero.....\nNo me engañarás á mí.",210,0,-1,202,"",0,4,"i",-1,0,-1,0,325,325,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0325-02",15,"Eres como el gallo inglés,\nQue á todos les haces cara,\nY á mí no me la has de hacer,\nPorque te conozco, pava.",210,0,-1,202,"",0,4,"aa",-1,0,-1,0,325,325,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0325-03",15,"Poco me importan á mí\nTu amor ó tu mal-querencia;\nPorque el que está sin pecado,\nNo teme la penitencia.",210,0,-1,202,"",0,4,"ea",46,0,-1,0,325,325,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0325-04",15,"Haz cuenta que me mori,\nY estuvistes en mi entierro,\nme vistes enterrar,\nY asististes á mi duelo.",210,0,-1,202,"",0,4,"eo",-1,0,-1,0,325,325,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0325-05",15,"Anda, véte que no quiero\nPasar por tí mas fatigas;\nTe digo que no te quiero:\n¿Qué más quieres que te diga?",210,0,-1,202,"",0,4,"ia",-1,0,-1,0,325,325,"","",0,"","","",5,0,0,[],"",""],["lafuente_madrid-p0325-06",15,"Anda, que ya no te quiero,\nQue ya se me fué el amor;\nYa te barri con la escoba\nDentro de mi corazon.",210,0,-1,202,"",0,4,"o",-1,0,-1,0,325,325,"","",0,"rm_t3, palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0326-01",15,"Algun dia te queria,\nY ahora ya no te quiero;\nPorque he encontrado paloma,\nQue remonta más el vuelo.",210,0,-1,202,"",0,4,"eo",-1,0,-1,0,326,326,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0326-02",15,"Que te quise, cierto fué;\nQue te olvidé, no es mentira:\nQue en los árboles las hojas\nNo duran toda la vida.",210,0,-1,202,"",0,4,"ia",-1,0,-1,0,326,326,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0326-03",15,"Yo te quise por el tiempo\nDe las castañas cocidas;\nSe acabaron las castañas,\nY conversacion perdida.",210,0,-1,202,"",0,4,"ia",-1,0,-1,0,326,326,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0326-04",15,"Aunque me ves que me caigo,\nCon un pié me voy teniendo;\nSi tú tienes quien te quiera,\nMira que yo tambien tengo.",210,0,-1,202,"",0,4,"eo",-1,0,-1,0,326,326,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0326-05",15,"El querer que puse en ti\nUn cuervo se lo llevó,\nY en medio de aquellos mares\nAbrió el pico, y lo soltó.",210,0,-1,202,"",0,4,"o",2,0,-1,0,326,326,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0327-01",15,"El amor que tú me diste\nLo metí en un agujero,\nY lo tapé con estopa,\nY luego le pegué fuego.",210,0,-1,202,"",0,4,"eo",-1,0,-1,0,327,327,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0327-02",15,"El quererte fué un antojo,\nY el hablarte fantasía;\nSi eres tonta, abre los ojos,\nYo logré lo que queria.",210,0,-1,202,"",0,4,"ia",0,0,-1,0,327,327,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0327-03",15,"Es cierto que te he querido,\nQue te he querido y te quiero;\nPero casarme contigo,\nNo lo permitan los cielos.",210,0,-1,202,"",0,4,"eo",-1,0,-1,0,327,327,"","",0,"rm_t3, palau_cantares","","",7,0,0,[],"",""],["lafuente_madrid-p0327-04",15,"Otros más altos que tú,\nPajarillos de mas cuenta,\nMe están mirando á la cara\nPara ver si estoy contenta.",210,0,-1,202,"",0,4,"ea",229,0,-1,0,327,327,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0328-01",15,"Si tuvieras olivares,\nComo tienes fantasía,\nEl rio de Manzanares\nPor tu puerta pasaria.",210,0,-1,202,"",1,4,"aa",0,0,-1,0,328,328,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0328-02",15,"Gasta usté más fantesía\nQue el coche del Intendente,\nY no vale usté un cigarro,\nNi ninguno de su gente.",210,0,-1,202,"",0,4,"ee",15,0,-1,0,328,328,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0328-03",15,"Es tanta la vanidad\nQue tu cuerpo representa,\nQue es menester para hablarte\nDoscientos duros de renta.",210,0,-1,202,"",0,4,"ea",229,0,-1,0,328,328,"","",0,"rm_t3","","",2,0,0,[],"",""],["lafuente_madrid-p0328-04",15,"Desde que usté se pasea\nPor las calles del lugar,\nEstá perdida la venta\nDe las cañas de pescar.",210,0,-1,202,"",0,4,"a",21,0,-1,0,328,328,"","",0,"rm_t3","","",2,0,0,[],"",""],["lafuente_madrid-p0328-05",15,"De qué te sirve tener\nBaston de quiquiricaña,\nSi te dicen las mozuelas,\n¡Buen mozo, pero no apaña!",210,0,-1,202,"",0,4,"aa",213,0,-1,0,328,328,"","",0,"rm_t3, palau_cantares","","",8,0,0,[],"",""],["lafuente_madrid-p0328-06",15,"Aunque seas buena moza,\nNo te lo presumas tanto,\nQue tambien las buenas mozas\nSe suelen quedar en blanco.",210,0,-1,202,"",0,4,"ao",-1,0,-1,0,328,328,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0328-07",15,"Compañerita del alma,\n¿Por dónde la llevas tú?\nYo camino por la arena,\nY tú por el cielo azul.",210,0,-1,202,"",0,4,"u",-1,0,-1,0,328,328,"","",0,"rm_t3, palau_cantares","","",20,0,0,[],"",""],["lafuente_madrid-p0329-01",15,"Los amores se me han ido,\nLa causa yo no la sé;\nPiensan que me han agraviado;\nY me han hecho gran merced.",210,0,-1,202,"",0,4,"e",-1,0,-1,0,329,329,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0329-02",15,"Cuando me dieron la nueva\nDe que tú no me querias,\nSe me quedó el corazon.....\nLo mismo que lo tenia.",210,0,-1,202,"",0,4,"ea",-1,0,-1,0,329,329,"","",0,"palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0329-03",15,"Tú pensarás que me has hecho\nAgravio con enojarte;\nY me has hecho un beneficio\nQue no sé con qué pagarte.",210,0,-1,202,"",0,4,"ae",8,0,-1,0,329,329,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0329-04",15,"Todas las mañanas voy\nÁ misa á San Agustin,\nÁ darle gracias al santo\nQue me ha librado de tí.",210,0,-1,202,"",0,4,"i",-1,0,-1,0,329,329,"","",0,"rm_t3, palau_cantares","","",12,0,0,[],"",""],["lafuente_madrid-p0329-05",15,"¿Fuiste tú la que dijiste\nAyer en el lavadero\nQue te casabas conmigo?\nEso será si yo quiero.",210,0,-1,202,"",0,4,"eo",38,0,-1,0,329,329,"","",0,"palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0329-06",15,"Dueño mio, este es mi genio,\nYo no me muero por tí;\nQue en otro papel mas fino\nMe enseñaron á escribir.",210,0,-1,202,"",0,4,"i",-1,0,-1,0,329,329,"","",0,"palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0330-01",15,"Yo tengo sal, aunque poca,\nPero has de saber, y escucha:\nQue la gasto con quien quiero,\nCon personas que me gustan.",210,0,-1,202,"",0,4,"ua",-1,0,-1,0,330,330,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0330-02",15,"Deja de escandalizar\nLa calle con tus paseos,\nQue los suspiros que das\nNi los oigo, ni los creo.",210,0,-1,202,"",0,4,"eo",-1,0,-1,0,330,330,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0330-03",15,"Dueño mio, este es mi genio,\nYo no memuero por nadie;\nSi vienes, bien te recibo,\nY si te vas, buen viaje.",210,0,-1,202,"",0,4,"ae",-1,0,-1,0,330,330,"","",0,"","","",5,0,0,[],"",""],["lafuente_madrid-p0330-04",15,"Me quisiste, me olvidaste,\nY me volviste á querer:\nZapato que yo desecho,\nNo me lo vuelvo á poner.",210,0,-1,202,"",0,4,"e",20,0,-1,0,330,330,"","",0,"palau_cantares, isaacs_colombia","","",8,0,0,[],"",""],["lafuente_madrid-p0330-05",15,"Zapato que yo desecho\nY lo tiro al muladar,\nQue otro venga y se lo ponga.\n¿Qué cuidado se me da?",210,0,-1,202,"",0,4,"a",-1,0,-1,0,330,330,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0330-06",15,"De la lechuga romana\nEl cogollo me comi;\nQue otros se coman las hojas,\n¿Qué cuidado me da á mí?",210,0,-1,202,"",0,4,"i",23,0,-1,0,330,330,"","",0,"rm_t3","","",3,0,0,[],"",""],["lafuente_madrid-p0331-01",15,"Mi Currillo está enojado\nY me ha mandado decir:\nQue busque novio, si quiero,\nPorque él no piensa venir.",210,0,-1,202,"",0,4,"i",157,0,-1,0,331,331,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0331-02",15,"Permita Dios de los cielos\nQue cuando vuelva á quererte,\nSe me salten los ojillos\nDe un dolor de clavo fuerte.",210,0,-1,202,"",0,4,"ee",134,0,-1,0,331,331,"","",0,"palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0331-03",15,"Satisfacciones me pides,\nYo no te las quiero dar;\nQue darte satisfacciones\nEs volver á la amistad.",210,0,-1,202,"",0,4,"a",-1,0,-1,0,331,331,"","",0,"palau_cantares, preciso_coleccion","","",4,0,0,[],"",""],["lafuente_madrid-p0331-04",15,"Si esta mujer no me quiere,\n¿Qué hago yo con afligirme?\n¡Á mí no me ha de faltar\nOtra con quien divertirme!",210,0,-1,202,"",0,4,"ie",184,0,-1,0,331,331,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0331-05",15,"Si piensas darme pesares\nCon decir que tienes otra,\nYo tengo para ganarte\nCaballo, malilla y sota.",210,0,-1,202,"",0,4,"oa",-1,0,-1,0,331,331,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0331-06",15,"Dicen que tú no me quieres,\nAunque doblones me sobran;\nLos doblones son doblones\nAquí y en Constantinopla.",210,0,-1,202,"",3,4,"oa",-1,0,-1,0,331,331,"","",0,"rm_t3","","",11,0,0,[],"",""],["lafuente_madrid-p0331-07",15,"Si piensas que con halagos\nMe derrito como cera,\nSoy yo de tal calidad\nQue el mismo fuego me hiela.",210,0,-1,202,"",0,4,"ea",-1,0,-1,0,331,331,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0332-01",15,"Si la ocasion se presenta\nDe verte en alguna parte,\nTe he de volver las espaldas,\nMe he de marchar sin hablarte.",210,0,-1,202,"",0,4,"ae",8,0,-1,0,332,332,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0332-02",15,"Si te mueres, lloraré\nPor la falta que me haces,\nY otro en tu lugar pondré,\nQue todo lo nuevo place.",210,0,-1,202,"",0,4,"ae",-1,0,-1,0,332,332,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0332-03",15,"Si piensas que han de volver\nLas nueces al cantarillo,\nÁ tí te se fué el amor,\nÁ mí el amor y el cariño.",210,0,-1,202,"",0,4,"io",-1,0,-1,0,332,332,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0332-04",15,"Si me quieren, sé querer;\nSi me olvidan, olvidar;\nSi me desprecian, desprecio,\nPorque este es mi natural.",210,0,-1,202,"",0,4,"a",-1,0,-1,0,332,332,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0332-05",15,"Si vienes, bien te recibo,\nY si no, no me haces falta:\nHas de saber, dueño mio,\nQue yo no contemplo gaitas.",210,0,-1,202,"",0,4,"aa",-1,0,-1,0,332,332,"","",0,"rm_t3, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0332-06",15,"Te pones por todas partes\nÁ publicar que te quiero,\nY hasta al santo de tu nombre\nAborrecido lo tengo.",210,0,-1,202,"",0,4,"eo",-1,0,-1,0,332,332,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0332-07",15,"Aunque en una cruz te pongas,\nPara mí acabaste ya,\nPor haber querido á un tiempo\nCon dos barajas jugar.",210,0,-1,202,"",0,4,"a",-1,0,-1,0,332,332,"","",0,"palau_cantares","","",7,0,0,[],"",""],["lafuente_madrid-p0333-01",15,"Aunque el rey te coronara,\nYa sabes que no te quiero:\nLo que nos pasa á los dos,\nLo vas pregonando luego.",210,0,-1,202,"",0,4,"eo",-1,0,-1,0,333,333,"","",0,"rm_t3","","",2,0,0,[],"",""],["lafuente_madrid-p0333-02",15,"Ya no me queman á mí\nLas llamas de tu candela,\nQue lo que ha sido y no es,\nComo si en la vida fuera.",210,0,-1,202,"",0,4,"ea",-1,0,-1,0,333,333,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0333-03",15,"Ya no quiero más pan tuyo\nQue me amarga la corteza,\nNi conversacion contigo;\nLa que he tenido me pesa.",210,0,-1,202,"",0,4,"ea",201,0,-1,0,333,333,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0333-04",15,"¿De qué te sirve que andes\nPor la calle como un loco,\nSi el dia menos pensado\nTe dejo y me voy con otro?",210,0,-1,202,"",0,4,"oo",-1,0,-1,0,333,333,"","",0,"","","",4,0,0,[],"",""],["lafuente_madrid-p0333-05",15,"Ya te he dicho, compañera,\nNo vengas en busca mia,\nQue va mucha diferencia\nDe tu persona á la mia.",210,0,-1,202,"",0,4,"a",-1,0,-1,0,333,333,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0333-06",15,"Acaba de partir nueces,\nY echa las piedras al rio:\nLo que ha sido y ya no es,\nComo si no hubiera sido.",210,0,-1,202,"",0,4,"io",-1,0,-1,0,333,333,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0333-07",15,"Quitate de mi presencia\nQue no te quiero mirar,\nQue te tengo aborrecido\nComo al pecado mortal.",210,0,-1,202,"",0,4,"a",-1,0,-1,0,333,333,"","",0,"rm_t3, palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0334-01",15,"Tan ofendida me tienes\nCon obras y con palabras,\nQue aunque difunto te viera,\nNi agua bendita te echara.",210,0,-1,202,"",0,4,"aa",-1,0,-1,0,334,334,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0334-02",15,"Tantas hojas como tiene\nLa alameda de Genil,\nTantos demonios te lleven\nCuando te acuerdes de mí.",210,0,-1,202,"",0,4,"i",-1,0,-1,0,334,334,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0334-03",15,"Dicen que usté no me quiere,\nSe me dan tres caracoles;\nMás arriba ó más abajo,\nMe están queriendo á montones.",210,0,-1,202,"",0,4,"oe",-1,0,-1,0,334,334,"","",0,"rm_t3","","",4,0,0,[],"",""],["lafuente_madrid-p0334-04",15,"Dicen que ya no me quieres,\nNo me da pena maldita,\nQue la mancha de la mora\nCon otra verde se quita.",210,0,-1,202,"",0,4,"ia",50,0,-1,0,334,334,"","",0,"","","",9,0,0,[],"",""],["lafuente_madrid-p0334-05",15,"Dicen que usté no me quiere;\nÁ mí no me da cuidado;\nMañana me pongo luto\nDe tafetan encarnado.",210,0,-1,202,"",0,4,"ao",14,0,-1,0,334,334,"","",0,"rm_t3","","",4,0,0,[],"",""],["lafuente_madrid-p0334-06",15,"Grandes fatigas pasé,\nCuando te estuve olvidando;\nAsí que lo conseguí,\nDe contento no me hallo.",210,0,-1,202,"",0,4,"ao",-1,0,-1,0,334,334,"","",0,"rm_t3","","",2,0,0,[],"",""],["lafuente_madrid-p0334-07",15,"¿Qué cuidado le da al rey\nDe que se muera un soldado?\nLo mismo que me da á mí\nDe que me hayas olvidado.",210,0,-1,202,"",0,4,"ao",14,0,-1,0,334,334,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0335-01",15,"¿Qué cuidado me da á mi\nQue pases y no me hables,\nSi sabes que yo no como\nCon buenos dias de nadie?",210,0,-1,202,"",0,4,"ae",-1,0,-1,0,335,335,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0335-02",15,"Yo como y bebo sin ti,\nTu querer no me hace falta;\nNi el mundo se encierra en tí,\nNi los hombres se rematan.",210,0,-1,202,"",0,4,"aa",-1,0,-1,0,335,335,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0335-03",15,"Anda con Dios, bien te logres,\nNo te deseo mal ninguno:\nHora de salud no tengas\nMientras vivas en el mundo.",210,0,-1,202,"",0,4,"uo",-1,0,-1,0,335,335,"","",0,"","","",4,0,0,[],"",""],["lafuente_madrid-p0335-04",15,"Si quieres darme pesares\nCon querer á otra deidad,\nQuiérela tú sin recelo,\nQue á mí nada se me da.",210,0,-1,202,"",0,4,"a",-1,0,-1,0,335,335,"","",0,"rm_t3","","",2,0,0,[],"",""],["lafuente_madrid-p0335-05",15,"Una caña de pescar\nTengo para mi consuelo,\nSi un amante se me va,\nOtro queda en el anzuelo.",210,0,-1,202,"",0,4,"eo",10,0,-1,0,335,335,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0335-06",15,"Toda la calle á lo largo\nLa he sembrado de melones,\nMe han salido calabazas\nPara darlas á los hombres.",210,0,-1,202,"",0,4,"oe",-1,0,-1,0,335,335,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0335-07",15,"Piensas que me vuelven loca\nTus patillas y cuchillo,\nY yo no quiero galanes\nQue escupen por el colmillo.",210,0,-1,202,"",0,4,"io",228,0,-1,0,335,335,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0336-01",15,"Coge la rama de un roble\nY tírala á mi tejado;\nCuando la rama eche flores\nTe daré entonces la mano.",210,0,-1,202,"",0,4,"ao",-1,0,-1,0,336,336,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0336-02",15,"Siempre me anda usté diciendo\nQue se muere usté por mí;\nMuérase usté, lo verémos,\nY despues diré que si.",210,0,-1,202,"",0,4,"i",23,0,-1,0,336,336,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0337-01",15,"Tengo yo una cantarilla\nDe coplillas y cantares;\nCuando quiero divertirme\nTiro de la cuerda y salen.",210,0,-1,203,"",0,4,"ae",-1,0,-1,0,337,337,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0337-02",15,"¿Pues no es grande bobería\nEl vivir siempre penando,\nPudiéndonos divertir,\nMi vida, de cuándo en cuándo?",210,0,-1,203,"",0,4,"ao",33,0,-1,0,337,337,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0337-03",15,"Ya no quiero sufrir más,\nQue estoy harto de sufrir,\nQue quiero tomar el tiempo\nComo lo vea venir.",210,0,-1,203,"",0,4,"i",157,0,-1,0,337,337,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0337-04",15,"Sangre vivita, vivita,\nSangre vivita la quiero;\nPorque la sangre vivita\nTiene sandunga y salero.",210,0,-1,203,"",1,4,"eo",38,0,-1,0,337,337,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0337-06",15,"Ya no quiero yo apurarme,\nApúrese quien quisiere,\nPorque tengo conocido,\nQue el que se apura, se muere.",210,0,-1,203,"",0,4,"ee",115,0,-1,0,337,337,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0338-01",15,"Quien tiene penas, se muere;\nQuien no las tiene tambien;\nYo quiero vivir alegre,\nMañana me moriré.",210,0,-1,203,"",0,4,"e",-1,0,-1,0,338,338,"","",0,"rm_t4, andina_t1, leonesas_diez","","",4,0,0,[],"",""],["lafuente_madrid-p0338-02",15,"Este mundo es una bola,\nY el que se muere es un tonto,\nQue lo llevan á enterrar,\nY le cantan un responso.",210,0,-1,203,"",0,4,"oo",-1,0,-1,0,338,338,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0338-03",15,"Yo me llamo poca pena,\nPariente de mala gana.\nY por apellido tengo\nÁmí no se me da nada.",210,0,-1,203,"",0,4,"aa",-1,0,-1,0,338,338,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0338-04",15,"Aunque me digan que calle\nNo por eso he de callar.\nTodito lo he de decir,\nSalga bien ó salga mal.",210,0,-1,203,"",0,4,"a",-1,0,-1,0,338,338,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0338-05",15,"Canta claro me han llamado\nLas niñas de mi lugar,\nY tienen mucha razon\nPorque no puedo callar.",210,0,-1,203,"",0,4,"a",21,0,-1,0,338,338,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0338-06",15,"No soy rio, que me enturbio,\nAunque caiga una tormenta,\nQue soy mas claro que el agua\nDe la fuente de la yedra.",210,0,-1,203,"",0,4,"ea",-1,0,-1,0,338,338,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0338-07",15,"Á la que me quiere, quiero;\nÁ la que me habla, hablo;\nComo me las dan las tomo,\nY al son que me tocan bailo.",210,0,-1,203,"",0,4,"ao",-1,0,-1,0,338,338,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0339-01",15,"Cada vez que considero\nQue me tengo que morir,\nTiendo una capa en el suelo,\nY me harto de dormir.",210,0,-1,203,"",0,4,"i",157,0,-1,0,339,339,"","",0,"palau_cantares","","",14,0,0,[],"",""],["lafuente_madrid-p0339-02",15,"Cada vez que considero\nQue tengo un amor ingrato,\nNo sé como no me tiro.....\nContra un colchon, y me mato.",210,0,-1,203,"",0,4,"ao",2,0,-1,0,339,339,"","",0,"palau_cantares, fernan_caballero","","",14,0,0,[],"",""],["lafuente_madrid-p0339-03",15,"Las cositas de este mundo\nMuchos las toman á pecho;\nYo las tomo con la mano,\nY á la espalda me las echo.",210,0,-1,203,"",0,4,"eo",60,0,-1,0,339,339,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0339-04",15,"Á mí me llaman el tonto,\nEl tonto de mi lugar;\nTodos comen trabajando,\nYo como sin trabajar.",210,0,-1,203,"",0,4,"a",21,0,-1,0,339,339,"","",0,"rm_t4, palau_cantares, machado_venezuela","","",8,0,0,[],"",""],["lafuente_madrid-p0339-05",15,"A mí me llaman el tonto\nPorque miro á los tejados;\nSoy tonto de conveniencia\nPorque voy á mi cuidado.",210,0,-1,203,"",0,4,"ao",-1,0,-1,0,339,339,"","",0,"rm_t4","","",8,0,0,[],"",""],["lafuente_madrid-p0339-06",15,"Soy currito en el andar\nY en ponerme la montera,\nY en esto de trabajar\nTengo muy mala madera.",210,0,-1,203,"",1,4,"ea",44,0,-1,0,339,339,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0340-01",15,"Tengo pan y tengo vino,\nY sardinas en la mar.\nTengo la mujer bonita,\nY no quiero trabajar. (1)",210,0,-1,203,"",0,4,"a",21,0,-1,0,340,340,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0340-02",15,"Yo no sé cavar ni arar,\nNi tampoco coger yerba;\nLa que se case conmigo,\n¡Qué buena prenda se lleva!",210,0,-1,203,"",0,4,"ea",-1,0,-1,0,340,340,"","",0,"","","",5,0,0,[],"",""],["lafuente_madrid-p0340-03",15,"Mi padre, porque soy malo,\nA presidio quiere echarme;\nYo le digo: Padre mio,\n¿Dónde irá el buey que no are?",210,0,-1,203,"",0,4,"ae",-1,0,-1,0,340,340,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0340-04",15,"Cuando salgo de mi casa,\nMi madre se echa á llorar:\n¡Qué lástima de mi niño,\nQue me lo van á engañar!",210,0,-1,203,"",0,4,"a",21,0,-1,0,340,340,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0340-05",15,"Soy maestro examinado\nDe las cucharas de pan;\nTengo el oficio parado\nPor falta de material.",210,0,-1,203,"",0,4,"a",-1,0,-1,0,340,340,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0340-06",15,"Yo no tengo ningun vicio,\nSino que fumo tabaco,\nSuelo jugar un rentoy,\nY alguna vez me emborracho.",210,0,-1,203,"",0,4,"ao",-1,0,-1,0,340,340,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0341-01",15,"Cuando me parió mi madre,\nDijo una verdad mi abuela:\nComo este muchacho viva,\nSeguro está que se muera.",210,0,-1,203,"",0,4,"ea",-1,0,-1,0,341,341,"","",0,"","","",8,0,0,[],"",""],["lafuente_madrid-p0341-02",15,"Tengo yo un tio cadete\nEn las guardias españolas,\nQue en pidiéndole dinero,\nEcha mano á las pistolas.",210,0,-1,203,"",0,4,"oa",317,0,-1,0,341,341,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0341-03",15,"Tengo una tia, y me quiere\nComo si fuera mi madre;\nSiempre que compra ensalada\nMe da las hojas mas grandes.",210,0,-1,203,"",0,4,"ae",-1,0,-1,0,341,341,"","",0,"rm_t4","","",2,0,0,[],"",""],["lafuente_madrid-p0341-04",15,"Yo tenia una zambomba,\nY me la rompió mi abuela.\n¡No puede un hombre de bien\nTener una cosa buena!",210,0,-1,203,"",0,4,"ea",-1,0,-1,0,341,341,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0341-05",15,"Si juego al tresillo, pierdo;\nSi juego al cané, no gano;\nSi juego á la treinta y una,\nHago treinta y dos de mano.",210,0,-1,203,"",0,4,"ao",81,0,-1,0,341,341,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0341-06",15,"De que yo fuera soldado,\nTuvo mi madre la culpa,\nQue le dijo al coronel:\n¡Tengo un muchacho que asusta!",210,0,-1,203,"",0,4,"ua",-1,0,-1,0,341,341,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0341-07",15,"Mi madre tuvo la culpa\nDe que yo tan feo fuera,\nQue por cuatro ó cinco reales\nNo me quitó las viruelas.",210,0,-1,203,"",0,4,"ea",-1,0,-1,0,341,341,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0342-01",15,"Yo tenia un agnus Dei\nAl cuello, como es costumbré;\nMelo quitaron, diciendo:\nQui tollis peccata mundi.",210,0,-1,203,"",5,4,"ui",-1,0,-1,0,342,342,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0342-02",15,"Échame un cigarro, primo,\nQue yo no tengo tabaco,\nY hay un perrito que muerde\nÁ la puerta del estanco.",210,0,-1,203,"",0,4,"ao",-1,0,-1,0,342,342,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0342-03",15,"En la calle no só dónde,\nMataron yo no sé á quién;\nEl vivo cayó en el suelo,\nY el muerto apretó á correr.",210,0,-1,203,"",0,4,"e",-1,0,-1,0,342,342,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0342-04",15,"En la calle no sé dónde\nSe encuentra no sé qué santo,\nQue en rezando no sé qué,\nSe gana yo no sé cuánto.",210,0,-1,203,"",0,4,"ao",30,0,-1,0,342,342,"","",0,"palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0342-05",15,"Mi madre me dijo un dia\nQue á qué santo le rezaba;\nYo le dije: madre mia,\nÁ aquel que me da la gana.",210,0,-1,203,"",0,4,"aa",-1,0,-1,0,342,342,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0342-06",15,"Santa Rita la llorona\nFué tanto lo que lloró,\nQue el alma de su marido\nDel infierno la sacó.",210,0,-1,203,"",0,4,"o",2,0,-1,0,342,342,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0343-01",15,"Santa Rita fué casada\nCon un hombre labrador,\nQue se comia los huevos\nY dejaba el cascaron.",210,0,-1,203,"",5,4,"ao",-1,0,-1,0,343,343,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0343-02",15,"En San Miguelito el alto\nUn albañil se cayó:\nEl santo hizo un milagro,\nQue del suelo no pasó.",210,0,-1,203,"",0,4,"o",2,0,-1,0,343,343,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0343-03",15,"En la tienda del barbero\n¿Sabe usté lo que se dice?\nQue el Señor le da pañuelo\nAl que no tiene narices.",210,0,-1,203,"",0,4,"ie",-1,0,-1,0,343,343,"","",0,"rm_t4","","",3,0,0,[],"",""],["lafuente_madrid-p0343-04",15,"Á san Pedro que era calvo\nLe picaban los mosquitos,\nY su madre le decia:\nPónte el gorro, Periquito!",210,0,-1,203,"",0,4,"io",-1,0,-1,0,343,343,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0343-05",15,"Ya se murieron los diablos,\nYa el infierno se acabó,\nYa no nos condenarémos,\nSerrana, ni tú ni yo.",210,0,-1,203,"",0,4,"o",2,0,-1,0,343,343,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0343-06",15,"Con una mujer bonita\nTiene un hombre el pan ganado,\nSin más trabajo que hacerse\nUn poco el disimulado.",210,0,-1,203,"",0,4,"ao",14,0,-1,0,343,343,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0343-07",15,"Vivan las claras estrellas,\nViva el sol, viva la luna,\nVivan las niñas bonitas,\nY el amor y la fortuna.",210,0,-1,203,"",0,4,"ua",56,0,-1,0,343,343,"","",0,"fernan_caballero","","",3,0,0,[],"",""],["lafuente_madrid-p0344-01",15,"Por un besito ni dos\nEcha penitencia el cura;\nPero en llegando á los diez\nLa penitencia es segura.",210,0,-1,203,"",0,4,"ua",17,0,-1,0,344,344,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0344-02",15,"Si los besitos salieran\nComo sale el perejil,\nMás de una niña tuviera\nLa cara como un jardin.",210,0,-1,203,"",0,4,"i",-1,0,-1,0,344,344,"","",0,"palau_cantares, machado_venezuela","","",3,0,0,[],"",""],["lafuente_madrid-p0344-03",15,"Hombre feo y sin dinero,\nEnamorado y celoso,\nÁ esto llaman en mi tierra\nLa carabina de Ambrosio.",210,0,-1,203,"",0,4,"oo",-1,0,-1,0,344,344,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0344-04",15,"Los cortejos y las viejas\nSiguen una paridad,\nQue en faltándoles el oro\nNo valen ni la mitad.",210,0,-1,203,"",0,4,"a",16,0,-1,0,344,344,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0344-05",15,"Á los árboles frutales\nSe parecen los cortejos,\nQue en cayéndose la hoja\nSon espantajos del huerto.",210,0,-1,203,"",0,4,"eo",-1,0,-1,0,344,344,"","",0,"palau_cantares, preciso_coleccion","","",3,0,0,[],"",""],["lafuente_madrid-p0344-06",15,"El que corteja y no sabe\nLa cuerda que ha de tocar,\nPor muy sacristan que sea\nNunca llega á repicar.",210,0,-1,203,"",0,4,"a",21,0,-1,0,344,344,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0345-01",15,"Por comer una manzana\nAdan su reino perdió:\nMuchos, segun fuera el árbol,\nPerdieran por media, dos.",210,0,-1,203,"",0,4,"o",-1,0,-1,0,345,345,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0345-02",15,"¿Es posible, padre Adan,\nQue siendo vuestra merced\nEl primer hombre del mundo,\nLo engañara una mujer?",210,0,-1,203,"",0,4,"e",-1,0,-1,0,345,345,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0345-03",15,"De una costilla de Adan\nFormó Dios á la mujer,\nPara dejarle á los hombres\nEse hueso que roer.",210,0,-1,203,"",0,4,"e",20,0,-1,0,345,345,"","",0,"","","",4,0,0,[],"",""],["lafuente_madrid-p0345-04",15,"El que quiera en este mundo\nEstar de arañazos libre,\nNo haga tiestas á los gatos\nNi á las mujeres se arrime.",210,0,-1,203,"",0,4,"ie",-1,0,-1,0,345,345,"","",0,"","","",5,0,0,[],"",""],["lafuente_madrid-p0345-05",15,"El que quiera en este mundo\nTener paz con su mujer,\nPor muchas cosas que vea\nHa de hacer que no las ve.",210,0,-1,203,"",0,4,"e",-1,0,-1,0,345,345,"","",0,"","","",5,0,0,[],"",""],["lafuente_madrid-p0345-06",15,"El que quiera vivir mucho\nHa de huir lo más que pueda\nDe médicos, boticarios,\nPepinos, melones y hembras.",210,0,-1,203,"",0,4,"ea",-1,0,-1,0,345,345,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0345-07",15,"En el andar se conoce\nLa que es mala y la que es buena;\nEn echando el paso largo\n¡Santa Bárbara, que truena!",210,0,-1,203,"",0,4,"ea",59,0,-1,0,345,345,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0346-01",15,"Las mozuelas son de oro,\nLas casadas son de plata,\nLas viudas son de cobre\nY las viejas de hojalata.",210,0,-1,203,"",0,4,"aa",74,0,-1,0,346,346,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0346-02",15,"Una vieja vale un real,\nY una muchacha dos cuartos,\nY yo, como soy tan pobre.\nMe voy á lo más barato.",210,0,-1,203,"",0,4,"ao",-1,0,-1,0,346,346,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0346-03",15,"Una vieja muy revieja\nLe estába diciendo á ótra:\nLuego que yo me compongo,\nNo me pongo muy malota.",210,0,-1,203,"",0,4,"oa",-1,0,-1,0,346,346,"","",0,"palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0346-04",15,"¡Mal haya del arrebol\nQue venden en las boticas,\nQue se quieren comparar\nLas feas con las bonitas!",210,0,-1,203,"",0,4,"ia",-1,0,-1,0,346,346,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0346-05",15,"Todas las feas del mundo\nSe juntaron una tarde,\nÁ pedirle á san Antonio\nQue las bonitas se acaben.",210,0,-1,203,"",0,4,"ae",-1,0,-1,0,346,346,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0346-06",15,"Las morenas hizo Dios,\nY las blancas un platero,\nLas coloradas un sastre,\nLas negras un zapatero.",210,0,-1,203,"",0,4,"eo",38,0,-1,0,346,346,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0347-01",15,"Las mozuelas no me quieren\nNi yo á las viejas tampoco;\nIrémos así pasando\nCon esta vena de loco.",210,0,-1,203,"",0,4,"oo",152,0,-1,0,347,347,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0347-02",15,"Las mujeres de hoy en día\nSon lo mismo que palmitos;\nEmpezando á quitar hojas\nSolo quedan desperdicios.",210,0,-1,203,"",0,4,"io",-1,0,-1,0,347,347,"","",0,"palau_cantares","","",7,0,0,[],"",""],["lafuente_madrid-p0347-03",15,"Las mujeres que hay ahora\nSon como las cañas verdes;\nPor cima tienen la pompa,\nDebajo los arambeles.",210,0,-1,203,"",0,4,"ee",-1,0,-1,0,347,347,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0347-04",15,"Las mujeres de estos tiempos\nSon como las avellanas;\nDe ciento sale una buena\nY noventa y nueve vanas.",210,0,-1,203,"",0,4,"aa",263,0,-1,0,347,347,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0347-05",15,"Las mujeres que hoy se buscan\nHan de tener buena cara,\nMucho mimo y mucho embuste,\nTomar mucho, y no dar nada.",210,0,-1,203,"",0,4,"aa",-1,0,-1,0,347,347,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0347-06",15,"Todaslas mujeres son\nMedrosas, como se sabe,\nQue se asustan de un raton\nY no se asustan de un fraile,",210,0,-1,203,"",0,4,"ae",-1,0,-1,0,347,347,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0348-01",15,"Las muchachas de estos tiempos\nSon como las aceitunas;\nLa que parece más verde,\nSuele ser la más madura.",210,0,-1,203,"",0,4,"ua",-1,0,-1,0,348,348,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0348-02",15,"Más la quiero blanca y sosa\nQue no morena y. con gracia;\nPorque antes de que anochezca\nEstá lo oscuro en la casa.",210,0,-1,203,"",0,4,"aa",-1,0,-1,0,348,348,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0348-03",15,"No quiero mujer bonita\nNi viña en camino real,\nQue para coger el fruto\nEs menester madrugar.",210,0,-1,203,"",0,4,"a",-1,0,-1,0,348,348,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0348-04",15,"Todo el hombre que se muere\nSin querer á una morena,\nSe va de este mundo al otro\nSin saber lo que es canela.",210,0,-1,203,"",0,4,"ea",-1,0,-1,0,348,348,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0348-05",15,"No quiero mujer bonita\nPara vivir con recelo;\nNo quiero que á mi me pille\nLa media luna de enero.",210,0,-1,203,"",0,4,"eo",-1,0,-1,0,348,348,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0349-01",15,"Todo el hombre que se casa\nCon una mujer bonita,\nHasta que ella llega á vieja\nEl susto no se le quita.",210,0,-1,203,"",0,4,"ia",50,0,-1,0,349,349,"","",0,"","","",5,0,0,[],"",""],["lafuente_madrid-p0349-02",15,"Todo el hombre que se casa\nCon una mujer muy niña,\nPrevenga una vara verde,\nQue el miedo guarda la viña.",210,0,-1,203,"",0,4,"ia",170,0,-1,0,349,349,"","",0,"","","",5,0,0,[],"",""],["lafuente_madrid-p0349-03",15,"Á aquella mujer que quiere\nMandar más que su marido,\n¡Santo Cristo del garrote,\nLeña del Verbo Divino!",210,0,-1,203,"",0,4,"io",-1,0,-1,0,349,349,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0349-04",15,"Toda la mujer que quiere\nDe su marido el dinero,\nLe toma la cara y dice:\n¡Ay chacho, cuánto te quiero!",210,0,-1,203,"",0,4,"eo",38,0,-1,0,349,349,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0349-05",15,"Catalina, mi vecina,\nMujer de mucha aparato,\nSe come la longaniza,\nY le echa la culpa al gato.",210,0,-1,203,"",0,4,"ao",19,0,-1,0,349,349,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0349-06",15,"Los hombres en este tiempo\nSon como el melocoton,\nTienen la cáscara buena\nY dañado el corazon.",210,0,-1,203,"",5,4,"ao",-1,0,-1,0,349,349,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0349-07",15,"No son todos cazadores\nLos que por el monte van:\nUnos cazan las perdices,\nY otros las hijas de Adan.",210,0,-1,203,"",0,4,"a",147,0,-1,0,349,349,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0350-01",15,"Los hombres son el demonio,\nParientes del Antecristo,\nY nosotras las mujeres\nSomos unos angelitos.",210,0,-1,203,"",0,4,"io",-1,0,-1,0,350,350,"","",0,"rm_t4","","",4,0,0,[],"",""],["lafuente_madrid-p0350-02",15,"Se parecen á la araña\nLas mujeres y las mozas,\nPorque es su mayor cuidado\nAndar buscando la mosca.",210,0,-1,203,"",0,4,"oa",-1,0,-1,0,350,350,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0350-03",15,"La mujer y el perro dogo\nSon de la misma madera,\nQue en haciéndoles halagos\nSe van detras de cualquiera.",210,0,-1,203,"",0,4,"ea",44,0,-1,0,350,350,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0350-04",15,"Dice el sabio Salomon\nQue el que engaña á una mujer,\nNo tiene perdon de Dios......\nSi no la engaña otra vez.",210,0,-1,203,"",0,4,"e",-1,0,-1,0,350,350,"","",0,"","","",5,0,0,[],"",""],["lafuente_madrid-p0350-05",15,"Dicen algunos autores,\nY con ellos Sancho Panza,\nQue un gato y una mujer\nLa limpieza de una casa.",210,0,-1,203,"",0,4,"aa",-1,0,-1,0,350,350,"","",0,"","","",4,0,0,[],"",""],["lafuente_madrid-p0350-06",15,"El pájaro y la mujer\nNo se deben dejar solos;\nEl primero con el gato,\nLa segunda con el novio.",210,0,-1,203,"",0,4,"oo",-1,0,-1,0,350,350,"","",0,"machado_venezuela","","",2,0,0,[],"",""],["lafuente_madrid-p0350-07",15,"Segun dice quien lo sabe,\nTodas las mujeres son\nAmigas de los tomates,\nMas de los dátiles no.",210,0,-1,203,"",0,4,"o",-1,0,-1,0,350,350,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0351-01",15,"¿Dónde irá el buey que no are,\nY la yegua que no trille,\nY el caballo que no corra,\nY la mujer que no chille?",210,0,-1,203,"",0,4,"ie",504,0,-1,0,351,351,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0351-02",15,"En casa de doña Justa\nHa entrado un hombre á deshora;\nSi esto hace doña Justa,\n¿Que hará doña Pecadora?",210,0,-1,203,"",1,4,"oa",107,0,-1,0,351,351,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0351-03",15,"¡Á cuántas conozco yo\nQue se tienen por santitas,\nY suelen pegarle un chasco\nÁ las ánimas benditas!",210,0,-1,203,"",0,4,"ia",258,0,-1,0,351,351,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0351-04",15,"Son las Pepas presumidas\nY las Antonias son vanas,\nInteresadas las Rosas\nY melindrosas las Juanas.",210,0,-1,203,"",0,4,"aa",263,0,-1,0,351,351,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0351-05",15,"Son las Vicentas muy sosas\nY muy falsas las Jacintas,\nTodas las Anas celosas\nY todas las Claras, tintas.",210,0,-1,203,"",1,4,"ia",716,0,-1,0,351,351,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0351-06",15,"Ya no se puede en invierno\nLas salitas esterar,\nPorque con los miriñaques\nSe concluyó el material.",210,0,-1,203,"",0,4,"a",-1,0,-1,0,351,351,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0351-07",15,"Una niña de mi calle\nPor un balcon se cayó,\nY el vuelo del miriñaque\nLa vida le libertó.",210,0,-1,203,"",0,4,"o",2,0,-1,0,351,351,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0352-01",15,"En mi vida tomaré\nDe mi amante ni un cintillo,\nPorque luego se figuran\nQue todo el monte es tomillo.",210,0,-1,203,"",0,4,"io",228,0,-1,0,352,352,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0352-03",15,"Con los musiquitos, niña,\nPoquita conversacion,\nPorque siempre están pensando\nEn el do, re, mi, fa, sol.",210,0,-1,203,"",0,4,"o",-1,0,-1,0,352,352,"","",0,"rm_t4","","",2,0,0,[],"",""],["lafuente_madrid-p0352-04",15,"No te cases con herrero\nQue te puede suceder,\nTirarte con el martillo\nY hacerte coja de un pié.",210,0,-1,203,"",0,4,"e",-1,0,-1,0,352,352,"","",0,"rm_t4","","",4,0,0,[],"",""],["lafuente_madrid-p0352-05",15,"No te enamores, mi vida,\nDe ningun chico pedante;\nPréciate de algun buen mozo,\nYa que no mate, que espante.",210,0,-1,203,"",0,4,"ae",47,0,-1,0,352,352,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0352-06",15,"Si quieres vivir alegre\nCásate con un corneta;\nPor la mañana diana,\nPor la noche la retreta.",210,0,-1,203,"",0,4,"ea",200,0,-1,0,352,352,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0352-07",15,"No te cases con herrero,\nDama de cuerpo gentil,\nQue del golpe del martillo\nNo te dejará dormir.",210,0,-1,203,"",0,4,"i",-1,0,-1,0,352,352,"","",0,"rm_t4","","",4,0,0,[],"",""],["lafuente_madrid-p0353-01",15,"Una niña de este barrio\nTrata con un practicante,\nSi tira de las lancetas.....\n¡Ten cuidado no se enfade!",210,0,-1,203,"",0,4,"ae",-1,0,-1,0,353,353,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0353-02",15,"Para monja no naci,\nQue nací para casada,\nRecorreré los oficios,\nPor ver si alguno me agrada.",210,0,-1,203,"",0,4,"aa",49,0,-1,0,353,353,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0353-03",15,"Al sacristan lo aborrezco,\nPorque siempre anda de prisa,\nY enfadado puede darme\nCon lo que tocan á misa.",210,0,-1,203,"",0,4,"ia",68,0,-1,0,353,353,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0353-04",15,"Al tejedor lo aborrezco,\nPorque este, aunque yo no quiera,\nPuede urdirme alguna trama\nY echarme la lanzadera",210,0,-1,203,"",0,4,"ea",44,0,-1,0,353,353,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0353-05",15,"Un platero bien vestido\nViene, y sus galas me luce;\nPero veo que no es oro\nTodo aquello que reluce.",210,0,-1,203,"",0,4,"ue",508,0,-1,0,353,353,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0353-06",15,"Aunque sea millonario,\nNo lo quiero mercader;\nPorque así como me compra,\nTambien me puede vender.",210,0,-1,203,"",0,4,"e",20,0,-1,0,353,353,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0354-01",15,"Un cerero me desea,\nCuando me ve tan bonita;\nMas no creo que por él\nMi corazon se derrita.",210,0,-1,203,"",0,4,"ia",50,0,-1,0,354,354,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0354-02",15,"Un tintorero me ronda\nCon mucho salero y garbo;\nPero yo no quiero oficio\nQue vuelve lo negro blanco.",210,0,-1,203,"",0,4,"ao",-1,0,-1,0,354,354,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0354-03",15,"Un pastelero pretende\nQue yo me case con él;\nMas si yo gusto le diera\nSi que haria buen pastel!",210,0,-1,203,"",0,4,"e",32,0,-1,0,354,354,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0354-04",15,"Un sastre toma medidas\nPara echarme la tijera;\nPero en no siendo en mi paño\nQue corte por donde quiera.",210,0,-1,203,"",0,4,"ea",44,0,-1,0,354,354,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0354-05",15,"Un cordelero queria\nQue me casara con él,\nY si yo le diera gusto,\nBien merecia un cordel.",210,0,-1,203,"",0,4,"e",32,0,-1,0,354,354,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0354-06",15,"Zapatero no lo quiero,\nSastre no lo puedo ver;\nUno me da con la mano,\nOtro me da con el pié.",210,0,-1,203,"",0,4,"e",-1,0,-1,0,354,354,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0354-07",15,"Un jorobado me ronda\nLas tapias de mi corral;\n¿Si pensará el jorobado\nQue á mí me ha de jorobar?",210,0,-1,203,"",0,4,"a",-1,0,-1,0,354,354,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0355-01",15,"Que no nací para monja\nAl principio declaré;\nPero ya desengañada\nMonja por fuerza he de ser.",210,0,-1,203,"",0,4,"e",-1,0,-1,0,355,355,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0355-02",15,"Torta me da un panadero,\nY otra vez al horno va;\nPero temo que algun dia\nMe cueste la torta un pan.",210,0,-1,203,"",0,4,"a",-1,0,-1,0,355,355,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0355-03",15,"No quiero á Juan, porque es tonto,\nNi á Pedro por majadero,\nNi á Francisco por celoso;\nDe los tres ninguno quiero",210,0,-1,203,"",0,4,"eo",38,0,-1,0,355,355,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0355-04",15,"Carpinterito es mi padre,\nCarpinterito es mi hermano;\nCarpinterito ha de ser,\nAquel á quien dé mi mano.",210,0,-1,203,"",0,4,"ao",81,0,-1,0,355,355,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0355-05",15,"Los sargentos para mí,\nLos cabos para mi hermana,\nY los soldaditos rasos,\nEsos para mi cuñada.",210,0,-1,203,"",0,4,"aa",-1,0,-1,0,355,355,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0355-06",15,"Más quiero labrador, madre,\nCon tierra en las alpargatas,\nQue no de esos currutacos,\nCon charreteras de plata.",210,0,-1,203,"",0,4,"aa",-1,0,-1,0,355,355,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0355-07",15,"El primer amor que tenga\nHa de ser un estudiante;\nYa que no tenga dinero,\nQue me alegre cuando cante.",210,0,-1,203,"",0,4,"ae",47,0,-1,0,355,355,"","",0,"palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0356-01",15,"El primer amor que tenga\nHa de ser un andaluz;\nYa que no tenga dinero\nTenga la sal de Jesus.",210,0,-1,203,"",0,4,"u",270,0,-1,0,356,356,"","",0,"palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0356-02",15,"El primer amor que tenga\nHa de ser un maragato;\nYa que no tenga dinero,\nTenga los calzones anchos.",210,0,-1,203,"",0,4,"ao",-1,0,-1,0,356,356,"","",0,"","","",6,0,0,[],"",""],["lafuente_madrid-p0356-03",15,"No lo quiero zapatero,\nQue me tirará la horma,\nQue lo quiero molinero,\nQue me ponga blanca y gorda.",210,0,-1,203,"",0,4,"oa",-1,0,-1,0,356,356,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0356-04",15,"Contrabandista lo quiero,\nAunque lo maten mañana,\nQue si acaso lo mataren\nMe queda caballo y carga.",210,0,-1,203,"",0,4,"aa",-1,0,-1,0,356,356,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0356-05",15,"Á un viejo quiero y á un mozo,\nAunque con distinta ley;\nQuiero al mozo por su cara,\nY al viejo por la del rey.",210,0,-1,203,"",0,4,"e",133,0,-1,0,356,356,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0356-06",15,"La que se casa con viejo\nTiene penitencia entera;\nDe dia cruz y calvario,\nY de noche calavera.",210,0,-1,203,"",0,4,"ea",44,0,-1,0,356,356,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0356-07",15,"Una niña me engañó,\nPorque me encontró sencillo:\n¿Cuándo volverá la niña\nÁ tener chanzas conmigo?",210,0,-1,203,"",0,4,"io",-1,0,-1,0,356,356,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0357-01",15,"Yo me arrimé á una morena\nPor ver si la camelaba,\nY ella me cameló á mí\nEl dinero que llevaba.",210,0,-1,203,"",0,4,"aa",28,0,-1,0,357,357,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0357-02",15,"Madre, digale usté á padre\nQue le riña á Sebastian,\nQue me quiere hacer cosquillas,\nY no las puedo aguantar.",210,0,-1,203,"",0,4,"a",-1,0,-1,0,357,357,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0357-03",15,"Soy un pobre forastero,\nQue á una mujer quise bien,\nY pensando cazar gangas,\nMe pescaron en la red.",210,0,-1,203,"",0,4,"e",-1,0,-1,0,357,357,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0357-04a",15,"Mozuelas, si quereis novio\nHacedlo de pan y queso,\nQue los mozuelos de ahora\nDicen que no están por eso.",210,0,-1,203,"",0,4,"eo",48,0,-1,0,357,357,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0357-04b",15,"Muchachas, si quereis novios,\nPintadlos en la pared,\nQue los mocitos de España\nSon de la reina Isabel.",210,0,-1,203,"",0,4,"e",-1,0,-1,0,357,357,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0357-05",15,"¿Fuiste tú la que metiste\nÁ san Antonio en un pozo,\nY lo hartaste de agua,\nPorque te saliera un novio?",210,0,-1,203,"",0,4,"oo",-1,0,-1,0,357,357,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0358-01",15,"Mi padre me pega palos,\nPorque le pido marido;\nVengan palos y más palos,\nY déme le que le pido.",210,0,-1,203,"",1,4,"io",101,0,-1,0,358,358,"","",0,"","","",12,0,0,[],"",""],["lafuente_madrid-p0358-02",15,"Mi padre me pega palos,\nPorque quiero á un albañil,\nY al son de los palos digo:\n¡Cuándo le veré venir!",210,0,-1,203,"",0,4,"i",-1,0,-1,0,358,358,"","",0,"palau_cantares","","",12,0,0,[],"",""],["lafuente_madrid-p0358-03",15,"Mi padre me pega palos,\nY mi madre me pellizca,\nY al son de los palos digo:\nSarna con gusto no pica.",210,0,-1,203,"",0,4,"ia",-1,0,-1,0,358,358,"","",0,"palau_cantares, fernan_caballero","","",12,0,0,[],"",""],["lafuente_madrid-p0358-04",15,"No quiero querer á nadie,\nNi que me quieran á mí;\nQuiero andar entre las flores,\nHoy aquí, mañana allí.",210,0,-1,203,"",0,4,"i",23,0,-1,0,358,358,"","",0,"palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0358-05",15,"El amor y la cotilla\nTodo lo he dejado á un tiempo;\nPorque no quiero apretones\nEn el alma, ni en el cuerpo.",210,0,-1,203,"",0,4,"eo",-1,0,-1,0,358,358,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0358-06",15,"Yo conocí á un don José,\nQue era un hombre muy cabal;\nY se metió en el querer,\nY murió en un hospital.",210,0,-1,203,"",0,4,"a",1,0,-1,0,358,358,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0358-07",15,"Querer una no es ninguna,\nQuerer dos es voluntad,\nQuerer tres, y engañar cuatro,\nEs maña y habilidad.",210,0,-1,203,"",0,4,"a",16,0,-1,0,358,358,"","",0,"","","",7,0,0,[],"",""],["lafuente_madrid-p0359-01",15,"Tengo mi amor repartido\nEntre cuatro ó cinco damas;\nYo con ellas me divierto,\nY ellas conmigo se engañan.",210,0,-1,203,"",0,4,"aa",-1,0,-1,0,359,359,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0359-02",15,"Yo tuve cierto cariño\nHasta que me dió la gana;\nPero luego me cansé,\nY la dije: abur, salada.",210,0,-1,203,"",0,4,"aa",-1,0,-1,0,359,359,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0359-03",15,"Á la Virgen del Pilar\nLe estoy pidiendo de veras,\nQue me quite este querer\nQue le tengo á las mozuelas.",210,0,-1,203,"",0,4,"ea",-1,0,-1,0,359,359,"","",0,"","","",5,0,0,[],"",""],["lafuente_madrid-p0359-04",15,"Cuando veo una mujer,\nTodo me vuelvo veneno,\nY la vida perderia\nSolo por un cuerpo bueno.",210,0,-1,203,"",0,4,"eo",76,0,-1,0,359,359,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0359-05",15,"Porque le dije á una niña,\nBenditos tus perejiles;\nMe llevaron á la cárcel\nLos ministros y alguaciles.",210,0,-1,203,"",0,4,"ie",698,0,-1,0,359,359,"","",0,"","","",4,0,0,[],"",""],["lafuente_madrid-p0359-06",15,"Yo fui soldado blanquillo,\nQuerido de mi sargento,\nY por enamoradillo\nMe echaron del regimiento.",210,0,-1,203,"",1,4,"eo",94,0,-1,0,359,359,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0359-07",15,"Paraíso de los tontos\nDicen que son las muchachas;\nYo me voy al paraíso,\nAunque de tonto me caiga.",210,0,-1,203,"",0,4,"aa",-1,0,-1,0,359,359,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0360-01",15,"Permita Dios castigarme\nCon un plato de perdices,\nUna botella de vino,\nY una muchacha de á quince.",210,0,-1,203,"",0,4,"ie",-1,0,-1,0,360,360,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0360-02",15,"Si yo fuera cazador,\nY tuviera una escopeta,\nCazaria una perdiz\nDe las que gastan peineta.",210,0,-1,203,"",0,4,"ea",200,0,-1,0,360,360,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0360-03",15,"Marujilla, Marujilla,\nNo vayas por agua al rio,\nQue detras de aquella piedra\nEstá el Marujo escondido.",210,0,-1,203,"",0,4,"io",-1,0,-1,0,360,360,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0360-04",15,"El médico me ha mandado\nUna muchacha de á treinta,\nY yo quiero dos de á quince,\nQue me sale mejor cuenta.",210,0,-1,203,"",0,4,"ea",-1,0,-1,0,360,360,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0360-05",15,"Tengo yo un caballo bayo\nQue se muere por las yeguas,\nY yo, como soy su amo,\nMe muero por las mozuelas.",210,0,-1,203,"",0,4,"ea",-1,0,-1,0,360,360,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0360-06",15,"En teniendo tantos años\nComo palos una silla,\nSi no te quiere tu madre,\nVénte conmigo, chiquilla.",210,0,-1,203,"",0,4,"ia",162,0,-1,0,360,360,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0360-07",15,"Vénte conmigo, serrana,\nSerrana, vénte conmigo;\nQue no ha de faltarte nada\nPara andar en cueros vivos.",210,0,-1,203,"",0,4,"io",-1,0,-1,0,360,360,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0361-01",15,"Si yo tuviera un chinito\nSe lo tirara á esa higuera;\nQue buena falta me hace\nQue me cayera esa breva.",210,0,-1,203,"",0,4,"ea",-1,0,-1,0,361,361,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0361-02",15,"Yo se lo dije á una alta;\nMe respondió que era chico;\nLe repliqué con cachaza:\nMe subiré en un borrico\nPor ver si alcanzo á la marca",210,0,-1,203,"",7,5,"aa",-1,0,-1,0,361,361,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0361-03",15,"Las mozuelas no me gustan,\nÁ quererlas no me apaño,\nY ando buscando una vieja\nDe catorce ó quince años.",210,0,-1,203,"",0,4,"ao",-1,0,-1,0,361,361,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0361-04",15,"Estoy buscando una vieja\nDe catorce ó quince años;\nY aunque tenga diez y seis,\nQue en piquillos no reparo.",210,0,-1,203,"",0,4,"ao",-1,0,-1,0,361,361,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0361-05",15,"Por esta calle me voy,\nY por otra doy la vuelta;\nLa niña que me quisiere\nQue tenga la puerta abierta.",210,0,-1,203,"",0,4,"ea",-1,0,-1,0,361,361,"","",0,"palau_cantares","","",8,0,0,[],"",""],["lafuente_madrid-p0361-06",15,"Señora, yo soy un pobre,\nPobre, pero cariñoso;\nMe parezco al espinazo,\nPelado, pero sabroso.",210,0,-1,203,"",0,4,"oo",160,0,-1,0,361,361,"","",0,"palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0361-07",15,"Señora, yo soy un pobre\nQue no tengo que comer;\nDéme usted una limosna,\nQue yo se lo pagaré.",210,0,-1,203,"",0,4,"e",-1,0,-1,0,361,361,"","",0,"palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0362-01",15,"Quiéreme, que soy buen mozo\nY escribo en la Mayoría,\nY soy sargento primero,\nY corro con compañía.",210,0,-1,203,"",0,4,"ia",0,0,-1,0,362,362,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0362-02",15,"Cásate, niña, conmigo;\nMira que tengo tres capas,\nY soy sobrino del cura,\n¡Verás qué vida te rapas!",210,0,-1,203,"",0,4,"aa",717,0,-1,0,362,362,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0362-03",15,"Quiéreme, que soy torrero\nDe la torre de la mar,\nY aunque tu madre no quiera\nContigo me he de casar.",210,0,-1,203,"",0,4,"a",21,0,-1,0,362,362,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0362-04",15,"Si ves á la de los tufos,\nQue le des muchas memorias,\nY le dices de camino\nQue si quiere ser mi novia.",210,0,-1,203,"",0,4,"oa",-1,0,-1,0,362,362,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0362-05",15,"Si quieres que yo te quiera,\nHa de ser con condicion:\nQue lo tuyo ha de ser mio,\nY lo mio tuyo no,",210,0,-1,203,"",0,4,"o",2,0,-1,0,362,362,"","",0,"rm_t4, palau_cantares","","",23,0,0,[],"",""],["lafuente_madrid-p0362-06",15,"Si quieres que yo te quiera,\nTe has de peinar de rodete,\nCon el pelito á la Fuoco,\n¡Y entonces verás quererte!",210,0,-1,203,"",0,4,"ee",-1,0,-1,0,362,362,"","",0,"palau_cantares","","",23,0,0,[],"",""],["lafuente_madrid-p0363-01",15,"Quiérela, que bien te quiere,\nQuiérela, que es bordadora,\nQuiérela, y te bordará\nUn camison à la moda.",210,0,-1,203,"",0,4,"oa",-1,0,-1,0,363,363,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0363-02",15,"Quiérela, que bien te quiere,\nQue tiene mucho dinero,\nQue al cabo de la semana\nGana tres cuartos y medio.",210,0,-1,203,"",0,4,"eo",-1,0,-1,0,363,363,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0363-03",15,"Aunque te peines los rizos,\nY te pongas la peineta,\nNo te pueden dar tus padres\nDe dote media peseta.",210,0,-1,203,"",0,4,"ea",200,0,-1,0,363,363,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0363-04",15,"Si quieres que yo te quiera,\nDáme huevos con tocino,\nY buenas pesetas blancas,\nY muchos tragos de vino.",210,0,-1,203,"",0,4,"io",199,0,-1,0,363,363,"","",0,"palau_cantares","","",23,0,0,[],"",""],["lafuente_madrid-p0363-05",15,"Mariquita, tu rodete\nUn fraile se lo encontró;\nPensando que era un rosquete,\nEn la manga se lo echó.",210,0,-1,203,"",1,4,"o",2,0,-1,0,363,363,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0363-06",15,"Caballero, si usté quiere\nSer dueño de mi persona,\nDe todo cuanto le pida\nNo ha de faltar ni una cosa.",210,0,-1,203,"",0,4,"oa",-1,0,-1,0,363,363,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0363-07",15,"La sala donde yo habite\nEnladrillada de oro,\nLas paredes plateadas,\nPara darme gusto en todo.",210,0,-1,203,"",0,4,"oo",-1,0,-1,0,363,363,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0364-01",15,"En lo mas alto del patio\nDebe de haber un jardin\nCon cuatro fuentes saltando,\nPara darme gusto á mi.",210,0,-1,203,"",0,4,"i",-1,0,-1,0,364,364,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0364-02",15,"Cuatro mozas, que me sirvan\nCon lealtad y con firmeza:\nDos para servirme á mí,\nDos para servir la mesa.",210,0,-1,203,"",0,4,"ea",201,0,-1,0,364,364,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0364-03",15,"Cuatro negros en la puerta\nVestidos con mil primores;\nPara cuando vaya á misa,\nIr infundiendo temores.",210,0,-1,203,"",0,4,"oe",5,0,-1,0,364,364,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0364-04",15,"Un coche con cuatro mulas\nTambien me debes traer;\nPorque soy cachigordita,\nY no puedo andar á pié.",210,0,-1,203,"",0,4,"e",-1,0,-1,0,364,364,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0364-05",15,"-Quédate con Dios, gran loca,\nQue mañana volvere;\nQue no es mucho lo que pides,\nSi encuentras quien te lo dé.",210,0,-1,203,"",0,4,"e",77,0,-1,0,364,364,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0364-06",15,"¿Cómo quieres que te quiera,\nSi soy un pobre cadete?\n¿He de vender los cordones,\nNiña, para mantenerte?",210,0,-1,203,"",0,4,"ee",-1,0,-1,0,364,364,"","",0,"","","",16,0,0,[],"",""],["lafuente_madrid-p0364-07",15,"Tienes el moño de á arroba\nLos rizos de á cuarteron;\nCon esos ojillos negros\nMe robas el corazon.",210,0,-1,203,"",5,4,"ao",-1,0,-1,0,364,364,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0365-01",15,"¿Cómo quieres que te quiera,\nSi soy un triste oficial?\n¿Cómo quieres que mantenga\nSalero con tanta sal?",210,0,-1,203,"",0,4,"a",1,0,-1,0,365,365,"","",0,"","","",16,0,0,[],"",""],["lafuente_madrid-p0365-02",15,"Con ese pañuelo blanco\nVas publicando la guerra;\nY yo, como buen soldado,\nSiento plaza en tu bandera.",210,0,-1,203,"",0,4,"ea",-1,0,-1,0,365,365,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0365-03",15,"Es tanto lo que me gusta\nEl garbo de mi Manuela,\nQue le prestaria un pan,\nAunque no me lo volviera.",210,0,-1,203,"",0,4,"ea",-1,0,-1,0,365,365,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0365-04",15,"Yo me enamoré del garbo\nDe una pulida hortelana,\nY me comí media huerta\nDe lechuguillas tempranas.",210,0,-1,203,"",0,4,"aa",-1,0,-1,0,365,365,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0365-05",15,"Yo me enamoré del garbo\nDe una rubia panadera;\nY con el humo del horno\nSe va poniendo morena.",210,0,-1,203,"",0,4,"ea",-1,0,-1,0,365,365,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0366-01",15,"Anoche me enamoré\nDe una muchacha bonita:\nEsta mañana la ví,\n¡Y era tuerta la maldita!",210,0,-1,203,"",0,4,"ia",50,0,-1,0,366,366,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0366-02",15,"Dicen que mi amante es chico;\nEsa no es falta en un hombre,\nQue en el tiempo de la leva\nTras una mata se esconde.",210,0,-1,203,"",0,4,"oe",-1,0,-1,0,366,366,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0366-03",15,"Aunque tu padre me diera\nLa muleta y el buey cojo,\nNo te tengo de querer\nPorque eres tuerta de un ojo.",210,0,-1,203,"",0,4,"oo",400,0,-1,0,366,366,"","",0,"","","",7,0,0,[],"",""],["lafuente_madrid-p0366-04",15,"Por querer á una sosona,\nQue tenia el pelo rubio,\nOlvidé una morenilla,\nQue valia medio mundo.",210,0,-1,203,"",0,4,"uo",-1,0,-1,0,366,366,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0366-05",15,"La primer vez que te vi\nMe pareciste muy guapa;\nMas luego me pareciste\nUn saco lleno de paja.",210,0,-1,203,"",0,4,"aa",-1,0,-1,0,366,366,"","",0,"palau_cantares","","",7,0,0,[],"",""],["lafuente_madrid-p0366-06",15,"Eres alta como un huevo\nDerecha como una hoz,\nBlanca como el azabache;\n¡Buenas noches nos dé Dios!",210,0,-1,203,"",0,4,"o",87,0,-1,0,366,366,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0366-07",15,"Eres alta como un sapo,\nY rubia como un caldero;\nOjos de garza pelada,\nY escapada del infierno.",210,0,-1,203,"",0,4,"eo",-1,0,-1,0,366,366,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0367-01",15,"Eres más fea que el hambre,\nMás negra que la morcilla;\nEl dia que tú naciste\nNació la sarna y la tiña.",210,0,-1,203,"",0,4,"ia",-1,0,-1,0,367,367,"","",0,"palau_cantares, murciano_antiguo","","",3,0,0,[],"",""],["lafuente_madrid-p0367-02",15,"Son tus brazos tan hermosos,\nQue parecen dos morcillas,\nDe aquellas que están colgadas\nEl invierno en las cocinas.",210,0,-1,203,"",0,4,"ia",-1,0,-1,0,367,367,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0367-03",15,"Levántate la basquiña,\nQue te quiero ver el pié:\nZapatito á la cachucha,\nMedias á la virulé.",210,0,-1,203,"",0,4,"e",77,0,-1,0,367,367,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0367-04",15,"¡Qué bonita que no eres!\n¡Qué gracia que no me haces!\nPor Dios te pido, mozuela,\nQue por mi puerta no pases.",210,0,-1,203,"",0,4,"ae",287,0,-1,0,367,367,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0367-05",15,"Tengo una novia, señores,\nQue es una mujer cabal;\nTiene el hocico de perro\nY partidas de animal.",210,0,-1,203,"",0,4,"a",1,0,-1,0,367,367,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0367-06",15,"Señores, tengo una novia\nBonita, si Dios quisiera;\nBlanca, si la blanquearan;\nVestida, si la vistieran.",210,0,-1,203,"",0,4,"ea",-1,0,-1,0,367,367,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0368-01",15,"Como aquel refran que dice:\nPierde el pan y pierde el perro,\nLo mismo me pasa á mí\nCon una novia que tengo.",210,0,-1,203,"",0,4,"eo",-1,0,-1,0,368,368,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0368-02",15,"El amor de esta muchacha\nNo lo puedo comprender:\nUnas veces no me quiere,\nY otras no me puede ver.",210,0,-1,203,"",0,4,"e",20,0,-1,0,368,368,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0368-03",15,"Antes de anoche caí\nEn la puerta de mi novia,\nY ella dijo desde adentro:\n¡Si fuera el Tajo de ronda!",210,0,-1,203,"",0,4,"oa",-1,0,-1,0,368,368,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0368-04",15,"En Cádiz tengo mi Pepa,\nY en Sevilla mi tia Antonia,\nY en el barrio de Triana\nTengo y retengo mi novia.",210,0,-1,203,"",0,4,"oa",-1,0,-1,0,368,368,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0368-05",15,"Yo tengo un novio cadete,\nY otro tengo capitan,\nOtro que ronda mi puerta,\nY otro que á mi casa va.",210,0,-1,203,"",0,4,"a",-1,0,-1,0,368,368,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0368-06",15,"Á mí me ha salido un novio\nVestido de terciopelo;\nOlla grande y carne poca,\nFachenda y poco dinero.",210,0,-1,203,"",0,4,"eo",-1,0,-1,0,368,368,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0368-07",15,"Tienes la cara de plana,\nLa nariz de berengena,\nEl andar de burra enana,\nY el cuerpo de una colmena.",210,0,-1,203,"",1,4,"ea",59,0,-1,0,368,368,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0369-01",15,"Parece tu cuerpo un saco,\nTu cintura una talega,\nTu pecho dos celemines,\nTu boca una cebadera.",210,0,-1,203,"",0,4,"ea",-1,0,-1,0,369,369,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0369-02",15,"Te tienes por buena moza,\nY buena moza no eres;\nTe tienes por muy graciosa,\nMaldita la gracia tienes.",210,0,-1,203,"",0,4,"ee",-1,0,-1,0,369,369,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0369-03",15,"Desde que te ví el cogote,\nMás negro que una zalea,\nNo me asusto de la noche,\nPor mas oscura que sea.",210,0,-1,203,"",0,4,"ea",54,0,-1,0,369,369,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0369-04",15,"Hoy dudo al verte con tantos\nFlecos, cintajos y moños;\nSi eres mujer, ó eres mula\nDe las que sacan los toros.",210,0,-1,203,"",0,4,"oo",-1,0,-1,0,369,369,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0369-05",15,"Tienes el andar de pava,\nY los ojillos modestos;\nEstas, que callan y apañan,\nSe la pegan al más diestro.",210,0,-1,203,"",0,4,"eo",-1,0,-1,0,369,369,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0369-06",15,"El cuco y la cogujada\nCantan en el mes de mayo,\nY tú, cara de lechuza,\nNo puedes cantar ogaño.",210,0,-1,203,"",0,4,"ao",-1,0,-1,0,369,369,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0370-01",15,"Cuando mi maja se pone\nLa mantilla de franela,\nVa diciendo por la calle:\nEste cuerpo pide guerra.",210,0,-1,203,"",0,4,"ea",-1,0,-1,0,370,370,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0370-02",15,"Majo, si vienes á verme,\nÁtate las alpargatas,\nPorque tengo una vecina\nQue á todo le pone faltas.",210,0,-1,203,"",0,4,"aa",-1,0,-1,0,370,370,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0370-04",15,"Esto de pelar la pava\nTiene mucho que entender;\nUnos la pelan sentados,\nY otros la pelan de pié.",210,0,-1,203,"",0,4,"e",-1,0,-1,0,370,370,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0370-05",15,"¿Te acuerdas cuándo te dí\nLa mano por la gatera,\nY tu madre, que lo supo,\nDe rabia mató la perra?",210,0,-1,203,"",0,4,"ea",-1,0,-1,0,370,370,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0370-06",15,"Tu me dijiste que sí,\nY tu madre no quisió;\nEl demonio de la vieja\nToitico lo escompusió.",210,0,-1,203,"",0,4,"o",2,0,-1,0,370,370,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0370-07",15,"Yo te quisiera querer,\nY tu madre no me deja:\n¡En todo se ha de meter\nEl démonio de la vieja!",210,0,-1,203,"",1,4,"ea",165,0,-1,0,370,370,"","",0,"palau_cantares, machado_venezuela","","",8,0,0,[],"",""],["lafuente_madrid-p0371-01",15,"Tu madre se puso y dijo:\nPor ahí va calzones rotos.\n¿Por qué no se puso y dijo:\nQue por tí perdí los otros?",210,0,-1,203,"",0,4,"oo",-1,0,-1,0,371,371,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0371-02",15,"Si yo no te hubiera dado\nEl pañuelo de manzanas,\nNo hubiera dicho tu madre,\nSi eran buenas, ó eran malas.",210,0,-1,203,"",0,4,"aa",-1,0,-1,0,371,371,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0371-03",15,"Si yo no te hubiera dado\nEl pañuelo de las uvas,\nNo hubiera dicho tu madre,\nSi eran verdes ó maduras.",210,0,-1,203,"",0,4,"ua",-1,0,-1,0,371,371,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0371-04",15,"Aquí me tienes presente\nVestido de pantalon:\nGracias á Dios que á tu gente\nEl gusto se le cumplió.",210,0,-1,203,"",0,4,"o",-1,0,-1,0,371,371,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0371-05",15,"Por la mañana te quiero,\nAl medio dia no es tanto;\nPero en llegando la noche,\nCrece mi amor otro tanto.",210,0,-1,203,"",0,4,"ao",-1,0,-1,0,371,371,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0371-06",15,"Adios, que me voy del mundo,\nPorque la muerte me llama:\nEn el testamento dejo.....\nQue me entierren en tu cama.",210,0,-1,203,"",0,4,"aa",90,0,-1,0,371,371,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0371-07",15,"Échale pan á tu perro,\nDescolorida de cara;\nÉchale pan á tu perro,\nQue siempre que paso ladra.",210,0,-1,203,"",0,4,"aa",-1,0,-1,0,371,371,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0372-01",15,"Si usté me quisiera dar\nLo que la voy á pedir.....\nYa se ve,..... usté no querra.....\nPero vamos al decir.",210,0,-1,203,"",0,4,"i",157,0,-1,0,372,372,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0372-02",15,"¡Quién fuera gato montés,\nQue por tu ventana entrara! (1)\nÁ tí te diera un besito,\nY á tu madre la arañara.",210,0,-1,203,"",0,4,"aa",57,0,-1,0,372,372,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0372-03",15,"No quisiera más ventura,\nNi más gloria merecer,\nQue de tu boca á la mia\nNo cupiera un alfiler.",210,0,-1,203,"",0,4,"e",20,0,-1,0,372,372,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0372-04",15,"Tú eres palomita blanca,\nY yo palomito azul;\nJuntarémos los piquitos,\nY harémos cucurrucú.",210,0,-1,203,"",0,4,"u",-1,0,-1,0,372,372,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0372-05",15,"Mariquita, dáme un beso,\nQue me voy á confesar;\nY si el cura me regaña,\nYo te lo volveré á dar.",210,0,-1,203,"",0,4,"a",21,0,-1,0,372,372,"","",0,"rm_t2, palau_cantares","","",7,0,0,[],"",""],["lafuente_madrid-p0372-06",15,"-Mariquita, dáme un beso,\nQue tu madre lo mandó.\n-Mi madre manda en lo suyo,\nQue en lo mio mando yo.",210,0,-1,203,"",0,4,"o",2,0,-1,0,372,372,"","",0,"palau_cantares","","",7,0,0,[],"",""],["lafuente_madrid-p0373-01",15,"En tu puerta puse un guindo,\nEn tu ventana un cerezo:\nPor cada guinda un abrazo,\nPor cada cereza un beso.",210,0,-1,203,"",0,4,"eo",48,0,-1,0,373,373,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0373-02",15,"De Santo Domingo vengo\nDe cumplir una promesa:\nAhora, pues, que vengo santo,\nDáme un abrazo, Teresa.",210,0,-1,203,"",0,4,"ea",201,0,-1,0,373,373,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0373-03",15,"¡Si en tu aposento me viera\nContigo, y la llave echada,\nY el cerrajero muriera,\nY la llave se quebrara!....",210,0,-1,203,"",0,4,"aa",-1,0,-1,0,373,373,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0373-04",15,"Quisiera volverme aire,\nY traspasar las paredes,\nY entrar en tu cuarto, niña,\nPor ver el dormir que tienes.",210,0,-1,203,"",0,4,"ee",-1,0,-1,0,373,373,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0373-05",15,"¿Cuándo querrá Dios del cielo\nQue la Pascua caiga en viernes,\nY la luna en tu tejado,\nY yo en el cuarto en que duermes?",210,0,-1,203,"",0,4,"ee",-1,0,-1,0,373,373,"","",0,"palau_cantares","","",11,0,0,[],"",""],["lafuente_madrid-p0373-06",15,"Serrana, si yo te pillo\nEn callejon sin salida,\nBien puedes decir á voces:\n¡Me cayó la lotería!",210,0,-1,203,"",0,4,"ia",-1,0,-1,0,373,373,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0374-01",15,"Cuando me dice mi madre\nQue vaya y cierre la puerta,\nLe doy vueltas á la llave,\nY siempre la dejo abierta.",210,0,-1,203,"",0,4,"ea",267,0,-1,0,374,374,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0374-02",15,"Entra tú, que estoy solita,\nQue mi madre ya vendrá;\nY si no viniera pronto,\nTú á mí no me comerás.",210,0,-1,203,"",0,4,"a",-1,0,-1,0,374,374,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0374-03",15,"Éntre usté, que estoy solita,\nY mi madre está en la calle;\nLe pondré á usté una sillita,\nQue nadie se come á nadie.",210,0,-1,203,"",0,4,"ae",-1,0,-1,0,374,374,"","",0,"rm_t2","","",2,0,0,[],"",""],["lafuente_madrid-p0374-04",15,"Agua menudita llueve,\nY ya corren las canales:\nAbreme la puerta, cielo,\nQue soy aquel que tú sabes.",210,0,-1,203,"",0,4,"ae",-1,0,-1,0,374,374,"","",0,"palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0374-06",15,"Si conforme cantas, hilas,\n¡Adios, libreta de estopa!\nLa madre de esta muchacha\nEstará con ella loca.",210,0,-1,203,"",0,4,"oa",-1,0,-1,0,374,374,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0374-07",15,"Así que me dé la mina,\nTe he de comprar un refajo,\nY unas naguas blancas finas,\nQue te asomen por debajo.",210,0,-1,203,"",0,4,"ao",168,0,-1,0,374,374,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0375-01",15,"Si yo tuviera dinero,\nTe comprara un delantal,\nPero como no lo tengo.....\nNo te lo puedo comprar.",210,0,-1,203,"",0,4,"a",-1,0,-1,0,375,375,"","",0,"palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0375-02",15,"Siempre vienes, vida mia,\nSiempre vienes cuando cierno;\nSi vinieras cuando amaso,\nTe convidara á pan tierno.",210,0,-1,203,"",0,4,"eo",225,0,-1,0,375,375,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0375-03",15,"Aunque seas guapa chica,\nBlanca y rubia lo bastante.\nTe convidaré al café\nÁ tomar el chocolate.",210,0,-1,203,"",0,4,"ae",-1,0,-1,0,375,375,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0375-04",15,"Ole, con ole, con ole,\nOle de la neveria;\nEchele usted á esa serrana\nDe mi cuenta lo que pida.",210,0,-1,203,"",5,4,"ia",-1,0,-1,0,375,375,"","",0,"","","",7,0,0,[],"",""],["lafuente_madrid-p0375-05",15,"El cencerro de la vaca\nDe tu madre, que está en gloria,\nLo traigo ponido al cuello,\nPor tenerte en la memoria.",210,0,-1,203,"",0,4,"oa",126,0,-1,0,375,375,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0375-06",15,"Si me das porque te dé,\nYa te entenderé la maña;\nTomaré lo que me des,\nY yo no te daré nada.",210,0,-1,203,"",0,4,"aa",-1,0,-1,0,375,375,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0376-01",15,"Pasea la calle, mozo,\nQue tú te la llevarás....\nLa montera en la cabeza,\nSi te la dejan llevar.",210,0,-1,203,"",0,4,"a",-1,0,-1,0,376,376,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0376-02",15,"Dicen que ya no me quieres,\nPorque no tengo qué dar;\nEn mi casa tengo un chavo\nMetido en un mechinal.",210,0,-1,203,"",0,4,"a",-1,0,-1,0,376,376,"","",0,"palau_cantares","","",9,0,0,[],"",""],["lafuente_madrid-p0376-03",15,"Cuando yo te festejaba,\nTe peinabas à menudo;\nY ahora que no te veo,\nPareces perro lanudo.",210,0,-1,203,"",0,4,"uo",191,0,-1,0,376,376,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0376-04",15,"¿Te acuerdas, María Medina,\nLa noche del velatorio,\nQue te quedaste dormida\nY te quitaron el novio?",210,0,-1,203,"",0,4,"oo",-1,0,-1,0,376,376,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0376-05",15,"Por mucho que usté me quiera\nNo se acerque usté á mi cama;\nQue soy como Cartagena,\nQue toda está amurallada.",210,0,-1,203,"",0,4,"aa",-1,0,-1,0,376,376,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0376-06",15,"Por una triste peineta\nQue me diste para el pelo,\nMe quieres tener sujeta,\nComo anillito en el dedo.",210,0,-1,203,"",0,4,"eo",-1,0,-1,0,376,376,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0376-07",15,"La cinta que te truji,\nSi yo lo juera supio,\nEn esa endina cintura\nNo te la jueras ponio.",210,0,-1,203,"",5,4,"oo",-1,0,-1,0,376,376,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0377-02",15,"Yo no digo que lo seas,\nNi que lo dejes de ser;\nPero con esos ojillos\nMe lo estás dando á entender",210,0,-1,203,"",0,4,"e",20,0,-1,0,377,377,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0377-03",15,"Ayer tarde me dijeron\nQue era usté liebre corrida.\nÁ la liebre corredora\nLa escopeta prevenida",210,0,-1,203,"",0,4,"ia",37,0,-1,0,377,377,"","",0,"rm_t4","","",4,0,0,[],"",""],["lafuente_madrid-p0377-04",15,"Á mí me llaman el tonto,\nPorque me falta un sentido,\nÁ ti te falta otra cosa,\nY el tonto se la ha comido.",210,0,-1,203,"",0,4,"io",101,0,-1,0,377,377,"","",0,"","","",8,0,0,[],"",""],["lafuente_madrid-p0377-05",15,"Ya no tengo mas paciencia,\nQue es la virtud del borrico;\nEn cuanto vuelvo la espalda,\nEntra tu primo Perico.",210,0,-1,203,"",0,4,"io",141,0,-1,0,377,377,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0377-06",15,"Me dijiste que era un gato\nLo que entró por tu ventana:\nEn mi vida he visto gatos\nCon bandolera de guardia.",210,0,-1,203,"",0,4,"aa",-1,0,-1,0,377,377,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0378-01",15,"Mariquita, Mariquita,\nYo se lo diré á tu abuela,\nQue andas por esos corrales,\nComo vaca sin cencerra.",210,0,-1,203,"",0,4,"ea",-1,0,-1,0,378,378,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0378-02",15,"En tu casa llora un niño,\nY tú casada no estás;\nTu padre no tiene yerno....\nEl niño ¿de quién será?",210,0,-1,203,"",0,4,"a",-1,0,-1,0,378,378,"","",0,"rm_t4","","",2,0,0,[],"",""],["lafuente_madrid-p0378-04",15,"Á tu puerta hemos llegado\nCuatrocientos en cuadrilla;\nSi quieres que te cantemos,\nSaca cuatrocientas sillas.",210,0,-1,203,"",0,4,"ia",-1,0,-1,0,378,378,"","",0,"palau_cantares, fernan_caballero","","",5,0,0,[],"",""],["lafuente_madrid-p0378-05",15,"Á tu puerta estamos cuatro,\nTodos rendidos de sueño;\nBaja niña tus enaguas,\nPor no dormir en el suelo.",210,0,-1,203,"",0,4,"eo",-1,0,-1,0,378,378,"","",0,"palau_cantares","","",8,0,0,[],"",""],["lafuente_madrid-p0378-06",15,"Á tu puerta hemos llegado\nCuatrocientos muertos de hambre,\nSi quieres que te cantemos,\nSaca cuatrocientos panes.",210,0,-1,203,"",0,4,"ae",-1,0,-1,0,378,378,"","",0,"palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0379-01",15,"Tú estarás en tu camilla,\nAbrigadilla y caliente:\nYo ando por las esquinillas,\nPegando diente con diente.",210,0,-1,203,"",0,4,"ee",15,0,-1,0,379,379,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0379-03",15,"Asómate á esa ventana,\nCara de medio candil.\nNarices de chimenea\nY cuerpo de tamborin.",210,0,-1,203,"",5,4,"oi",-1,0,-1,0,379,379,"","",0,"","","",50,0,0,[],"",""],["lafuente_madrid-p0379-04",15,"Asómate á esa ventana\nCara de sardina frita:\nQue cada vez que te ven\nSe me rovuelven las tripas.",210,0,-1,203,"",0,4,"ia",-1,0,-1,0,379,379,"","",0,"","","",50,0,0,[],"",""],["lafuente_madrid-p0379-05",15,"Asómate á esa ventana,\nCara de cuerno quemado,\nY verás á tu querido\nDe penillas traspasado.",210,0,-1,203,"",0,4,"ao",14,0,-1,0,379,379,"","",0,"palau_cantares","","",50,0,0,[],"",""],["lafuente_madrid-p0380-01",15,"Asómate á esa ventana,\nRetrato de la herejía:\nEl que madrugó por verte,\n¡Qué poco sueño tendria!",210,0,-1,203,"",0,4,"ia",0,0,-1,0,380,380,"","",0,"palau_cantares","","",50,0,0,[],"",""],["lafuente_madrid-p0380-02",15,"Asómate á esa ventana,\nCara de pastel podrido;\nQue despues que estás borracha,\nDices que te amarga el vino.",210,0,-1,203,"",0,4,"io",-1,0,-1,0,380,380,"","",0,"palau_cantares","","",50,0,0,[],"",""],["lafuente_madrid-p0380-03",15,"Asómate á esa vergüenza,\nCara de poca ventana,\nY dáme un poco de sed,\nQue vengo muerto de agua.",210,0,-1,203,"",0,4,"aa",-1,0,-1,0,380,380,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0380-04",15,"Asómate á esa ventana,\nSi no, por ese agujero,\nCara de sarten roñosa,\nRopilla sin atadero.",210,0,-1,203,"",0,4,"eo",38,0,-1,0,380,380,"","",0,"","","",50,0,0,[],"",""],["lafuente_madrid-p0380-05",15,"Echemos la despedida,\nLa que Cristo echó en el rio:\nLos pájaros piden agua,\nY las muchachas marido.",210,0,-1,203,"",0,4,"io",-1,0,-1,0,380,380,"","",0,"fernan_caballero","","",18,0,0,[],"",""],["lafuente_madrid-p0380-06",15,"Echemos la despedida,\nQue ya nos vamos á ir;\nEn los hierros de tu reja\nSe queda mi corbatin.",210,0,-1,203,"",0,4,"i",-1,0,-1,0,380,380,"","",0,"","","",18,0,0,[],"",""],["lafuente_madrid-p0380-07",15,"Este verano me caso,\nLo he tomado con empeño;\nPero no puedo vender (1)\nCuatro gallinas que tengo.",210,0,-1,203,"",0,4,"eo",-1,0,-1,0,380,380,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0381-01",15,"Yo tengo un perro de caza,\nUna gallina y un cuervo,\nY todo lo he de vender\nPara casarme este invierno.",210,0,-1,203,"",0,4,"eo",-1,0,-1,0,381,381,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0381-02",15,"Ya no quedan en mi casa\nNi clavos en la pared,\nLa chaqueta y el sombrero\nLos acabo de vender",210,0,-1,203,"",0,4,"e",-1,0,-1,0,381,381,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0381-03",15,"Voy buscando una mujer,\nY si esta no sale fina,\nYo la enseñaré á querer\nCon una vara de encina.",210,0,-1,203,"",1,4,"ia",11,0,-1,0,381,381,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0381-04",15,"Cásate, y tendrás mujer,\nY vivirás santamente;\nLlegarás á Coronel,\nSin haber sido Teniente.",210,0,-1,203,"",0,4,"ee",15,0,-1,0,381,381,"","",0,"","","",5,0,0,[],"",""],["lafuente_madrid-p0381-05",15,"Mire usté, yo me casara,\nQue es una cosa muy buena,\nPero le temo á un lugar\nQue hay entre Cabra y Lucena.",210,0,-1,203,"",0,4,"ea",59,0,-1,0,381,381,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0381-06",15,"Si te casas, llevarás\nDe san Marcos la bandera,\nQue es larga la cofradía,\nY hay muchos cabos de vera.",210,0,-1,203,"",0,4,"ea",44,0,-1,0,381,381,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0381-07",15,"El demonio de la corte\nEn todo es particular;\nPues allí hasta los maridos\nNo son como en mi lugar.",210,0,-1,203,"",0,4,"a",21,0,-1,0,381,381,"","",0,"preciso_coleccion","","",2,0,0,[],"",""],["lafuente_madrid-p0382-01",15,"Si el casarse fuera un dia,\nUna semanita, ó dos.....\n¡Pero por toda la vida,\nEso nunca lo haré yo!",210,0,-1,203,"",0,4,"o",-1,0,-1,0,382,382,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0382-02",15,"Una niña me dió á mí\nPalabra de casamiento,\nY luego se arrepintió:\nYo bailaba de contento.",210,0,-1,203,"",0,4,"eo",94,0,-1,0,382,382,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0382-03",15,"Todas las chicas me dicen:\n¿Por qué no te casas, Juan?\n-La que me dan, no la quiero,\nLa que quiero, no me dan.",210,0,-1,203,"",0,4,"a",147,0,-1,0,382,382,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0382-04",15,"No me casaria yo\nCon la hija del Alcalde,\nPorque tiene un «¡quita, quita!\nQuita..... que viene mi padre!....»",210,0,-1,203,"",0,4,"ae",-1,0,-1,0,382,382,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0382-05",15,"Fui ayer á confesar\nCon un fraile capuchino,\nY me echó por penitencia\nQue me casara contigo.",210,0,-1,203,"",0,4,"io",-1,0,-1,0,382,382,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0382-06",15,"Soy soldado de á caballo,\nLo que quieras te daré;\nPero en tocando á casaca,\nNo quiere mi coronel.",210,0,-1,203,"",0,4,"e",-1,0,-1,0,382,382,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0383-01",15,"Yo me casé con un calvo,\nQue me lo dió mi fortuna;\nLa noche que no hay aceite,\nLa calavera me alumbra.",210,0,-1,203,"",0,4,"ua",-1,0,-1,0,383,383,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0383-02",15,"Me casé con un enano\nPor hartarme de reir;\nLe puse la cama en alto,\nY no se pudo subir.",210,0,-1,203,"",0,4,"i",157,0,-1,0,383,383,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0383-03",15,"Yo me casé con usté,\nPor dormir en buena cama;\nY ahora salimos con que\nEl colchon no tiene lana.",210,0,-1,203,"",3,4,"aa",-1,0,-1,0,383,383,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0383-04",15,"Yo me casé con usté,\nY usté se casó conmigo;\nUsté por tener mujer,\nY yo por tener marido.",210,0,-1,203,"",0,4,"io",-1,0,-1,0,383,383,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0383-05",15,"El que se casa vereis\nAl principio muy gustoso:\nVosotros no lo entendeis,\n¡Ay de mí, quién fuera mozo",210,0,-1,203,"",0,4,"oo",156,0,-1,0,383,383,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0383-06",15,"¿Habrá perro que se case,\nPara verse como yo,\nSin pretina en los calzones,\nNi cuello en el camison?",210,0,-1,203,"",0,4,"o",-1,0,-1,0,383,383,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0383-07",15,"Mal haya quien me casó\nCon una mujer tan fea,\nQue no la puedo llevar\nDonde las gentes la vean.",210,0,-1,203,"",0,4,"ea",-1,0,-1,0,383,383,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0384-01",15,"Al amanecer, por seda\nMandó á su mujer un sastre,\nY no la halló del color\nHasta las tres de la tarde.",210,0,-1,203,"",0,4,"ae",-1,0,-1,0,384,384,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0384-02",15,"Para alivio de mis penas\nMe dió Dios una tontona;\nCuando le pego, se rie;\nCuando la acaricio, llora.",210,0,-1,203,"",0,4,"oa",-1,0,-1,0,384,384,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0384-03",15,"Los enemigos del alma\nTodos dicen que son tres,\nY yo digo que son cuatro,\nPorque cuento á mi mujer.",210,0,-1,203,"",0,4,"e",-1,0,-1,0,384,384,"","",0,"palau_cantares","","",8,0,0,[],"",""],["lafuente_madrid-p0384-04",15,"Amigo Blas, he intentado\nPoner mi mujer en venta,\nPara comprar un caballo,\nQue me sale mejor cuenta.",210,0,-1,203,"",0,4,"ea",229,0,-1,0,384,384,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0384-05",15,"Soy zapatero de viejo,\nY no tengo que comer;\nEstoy por cerrar mi tienda\nY abrir la de mi mujer.",210,0,-1,203,"",0,4,"e",20,0,-1,0,384,384,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0384-06",15,"Mi marido fué á las Indias,\nY me trajo una navaja\nCon un letrero que dice:\nSi quieres comre, trabaja.",210,0,-1,203,"",0,4,"aa",393,0,-1,0,384,384,"","",0,"","","",9,0,0,[],"",""],["lafuente_madrid-p0384-07",15,"De dos que se quieren bien\nCon uno que coma basta,\nY que sea la mujer,\nPor ser la parte mas flaca.",210,0,-1,203,"",0,4,"aa",-1,0,-1,0,384,384,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0385-01",15,"Mi marido fué á las Indias,\nPor acrecer su caudal:\nTrajo mucho que decir,\nPero poco que contar.",210,0,-1,203,"",0,4,"a",-1,0,-1,0,385,385,"","",0,"palau_cantares","","",9,0,0,[],"",""],["lafuente_madrid-p0385-02",15,"Á morir se va de flaco\nTu marido, que era gordo;\nPero fuerzas no le faltan,\nQue lo tienes hecho un toro.",210,0,-1,203,"",0,4,"oo",-1,0,-1,0,385,385,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0385-04",15,"Asómate á esa ventana,\nSi te quieres asomar,\nY verás á tu marido\nDe una carreta tirar.",210,0,-1,203,"",0,4,"a",21,0,-1,0,385,385,"","",0,"","","",50,0,0,[],"",""],["lafuente_madrid-p0385-05",15,"Más valiera ser soldado,\nÓ en algun convento fraile,\nQue no mantener mujer\nAl precio que el trigo vale,",210,0,-1,203,"",0,4,"ae",-1,0,-1,0,385,385,"","",0,"rm_t4, fernan_caballero","","",3,0,0,[],"",""],["lafuente_madrid-p0385-06",15,"Permita Dios que diluvie\nComo en tiempo de Noé,\nY que se lleve á mi suegra\nMi cuñada y mi mujer.",210,0,-1,203,"",0,4,"e",-1,0,-1,0,385,385,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0385-07",15,"Mi suegra me quiere dar\nUna cruz para un rosario,\nY tengo yo con su hija\nPeana, cruz y calvario.",210,0,-1,203,"",0,4,"ao",25,0,-1,0,385,385,"","",0,"palau_cantares, fernan_caballero","","",3,0,0,[],"",""],["lafuente_madrid-p0386-01",15,"Mañana me voy á Cádiz\nCon intencion de volver,\nCuando se muera mi suegra,\nY entierren á mi mujer.",210,0,-1,203,"",0,4,"e",20,0,-1,0,386,386,"","",0,"palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0386-02",15,"El dia que yo me case,\nTengo que alquilar un coche,\nPara llevar á mi suegra\nDesde la iglesia al garrote.",210,0,-1,203,"",0,4,"oe",-1,0,-1,0,386,386,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0386-03",15,"Mi suegra me quiere mucho,\nPorque le guardo la viña:\n¡No sabe la pobre vieja\nPor donde va la vendimia.",210,0,-1,203,"",0,4,"ia",-1,0,-1,0,386,386,"","",0,"palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0386-04",15,"Mi suegra me quiere mucho,\nPorque le guardo el tejado:\n¡No sabe la pobre vieja\nLas tejas que le he quebrado!",210,0,-1,203,"",0,4,"ao",14,0,-1,0,386,386,"","",0,"palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0386-05",15,"El que quisiere mandar\nMemorias para el infierno.\nLa ocasion está en la mano:\nMi suegra se está muriendo.",210,0,-1,203,"",0,4,"eo",-1,0,-1,0,386,386,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0386-06",15,"Glorioso san Sebastian\nTodo lleno de saetas:\nMi alma como la tuya,\nComo tu cuerpo, mi suegra.",210,0,-1,203,"",0,4,"ea",-1,0,-1,0,386,386,"","",0,"fernan_caballero, palau_cantares","","",9,0,0,[],"",""],["lafuente_madrid-p0386-07",15,"Del hueso de una aceituna\nHe de hacer un barquichuelo,\nPara mandar á mi suegra\nÁ los profundos infiernos.",210,0,-1,203,"",0,4,"eo",-1,0,-1,0,386,386,"","",0,"rm_t4","","",6,0,0,[],"",""],["lafuente_madrid-p0387-01",15,"Mi suegra me quiere mucho;\nPermita Dios que le dure,\nComo una libra de estopa\nArrimadilla á la lumbre.",210,0,-1,203,"",0,4,"ue",-1,0,-1,0,387,387,"","",0,"","","",6,0,0,[],"",""],["lafuente_madrid-p0387-03",15,"No me mire usted á la cara,\nQue soy recien casadita,\nY mi marido es celoso:\nLa sangre me tiene frita.",210,0,-1,203,"",0,4,"ia",50,0,-1,0,387,387,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0387-04",15,"Si tu marido es celoso,\nNo te apures ni te enfades;\nMira que el campo no tiene\nPuertas, cerrojos, ni llaves.",210,0,-1,203,"",0,4,"ae",-1,0,-1,0,387,387,"","",0,"","","",7,0,0,[],"",""],["lafuente_madrid-p0387-05",15,"Mi marido bebe y juega,\nY se va con la vecina;\nY yo que me estoy en casa,\nDice que soy una indina.",210,0,-1,203,"",0,4,"ia",11,0,-1,0,387,387,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0387-06",15,"Mi marido es un bribon,\nNo me deja ir á la calle,\nPorque yo le cosa en casa\nLo que él rompe en otra parte",210,0,-1,203,"",0,4,"ae",-1,0,-1,0,387,387,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0388-01",15,"Mi marido es un celoso,\nY á puros celos me mata;\nCelos, si me voy á misa,\nCelos, si me quedo en casa.",210,0,-1,203,"",0,4,"aa",-1,0,-1,0,388,388,"","",0,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0388-02",15,"Mi marido está malito,\nYo estoy á la cabecera\nCon un rosario en la mano\nPidiendo à Dios que se muera.",210,0,-1,203,"",0,4,"ea",44,0,-1,0,388,388,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0388-03",15,"Ya se murió mi marido,\nYa se murió aquel borracho,\nYa no tengo quien me tire\nÁ la cabeza el cenacho.",210,0,-1,203,"",0,4,"ao",310,0,-1,0,388,388,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0388-04",15,"Mi marido se murió\nNo por falta de alimento,\nQue á la cabecera tuvo\nUna ristra de pimientos.",210,0,-1,203,"",0,4,"eo",-1,0,-1,0,388,388,"","",0,"palau_cantares","","",12,0,0,[],"",""],["lafuente_madrid-p0388-05",15,"Mi marido se murió,\nY lo enterré en la cocina;\nDe lástima que me dió\nMe puse á bailar encima.",210,0,-1,203,"",0,4,"ia",-1,0,-1,0,388,388,"","",0,"palau_cantares","","",12,0,0,[],"",""],["lafuente_madrid-p0388-06",15,"Murió mi mujer en marzo,\nÁ mediados de Cuaresma,\nY quíso Dios en un año\nDarme dos Carnestolendas.",210,0,-1,203,"",0,4,"ea",-1,0,-1,0,388,388,"","",0,"palau_cantares, fernan_caballero","","",3,0,0,[],"",""],["lafuente_madrid-p0388-07",15,"Estando en gracia de Dios\nMaté á mi mujer de un palo;\nSi esto fué en gracia de Dios,\n¡Qué fuera en gracia del diablo!",210,0,-1,203,"",0,4,"ao",-1,0,-1,0,388,388,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0389-01",15,"Una viudita lloraba\nLa muerte de su marido,\nY debajo de la cama\nTenia el majo escondido.",210,0,-1,203,"",0,4,"io",101,0,-1,0,389,389,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0389-02",15,"Suspiraba una viudita\nCon suspiritos muy tiernos,\nMás por cariño del vivo,\nQue por lástima del muerto.",210,0,-1,203,"",0,4,"eo",-1,0,-1,0,389,389,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0389-03",15,"Los ojos de la viuda\nVan diciendo por la calle:\n¡Quién quiere alquilar el cuarto\nPorque no le habita nadie?",210,0,-1,203,"",0,4,"ae",-1,0,-1,0,389,389,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0389-04",15,"Para el Obispo la mitra,\nPara el notario el tintero,\nPara los chicos las chicas,\nPara los frailes..... un cuerno.",210,0,-1,203,"",0,4,"eo",-1,0,-1,0,389,389,"","",0,"rm_t4","","",2,0,0,[],"",""],["lafuente_madrid-p0389-05",15,"Los frailes de San Francisco\nHan sembrado un melonar;\nEl demonio de los frailes\n¡Que melones comerán!",210,0,-1,203,"",0,4,"a",-1,0,-1,0,389,389,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0389-06",15,"De San Francisco salieron\nCuatro reverendos padres:\nFray Pimiento, fray Cebolla,\nFray Aceite y fray Vinagre.",210,0,-1,203,"",0,4,"ae",-1,0,-1,0,389,389,"","",0,"rm_t4","","",2,0,0,[],"",""],["lafuente_madrid-p0390-01",15,"Un fraile fué á un peluquero\nÁ que le hiciera los rizos,\nY tenia la cabeza\nComo un melon invernizo.",210,0,-1,203,"",0,4,"io",-1,0,-1,0,390,390,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0390-02",15,"Un fraile cenó chanfaina,\nY luego bebió agua fria,\nY toda la noche anduvo:\n¡Barriga del alma mia!",210,0,-1,203,"",0,4,"a",0,0,-1,0,390,390,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0390-03",15,"Yo me arrimé á una beata,\nPor tener algo de Dios;\nÁ ella se la llevó el diablo,\nY á mí poco me faltó.",210,0,-1,203,"",0,4,"o",-1,0,-1,0,390,390,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0390-04",15,"Un fraile me pidió un beso\nUn lunes por la mañana;\nYo le dije: Padre mio,\n¡Buen principio de semana!",210,0,-1,203,"",1,4,"aa",4,0,-1,0,390,390,"","",0,"rm_t4","","",4,0,0,[],"",""],["lafuente_madrid-p0390-05",15,"Un fraile me pidió un beso,\nY no se lo quise dar,\nQue los besos de los frailes\nSaben á huevos sin sal.",210,0,-1,203,"",0,4,"a",-1,0,-1,0,390,390,"","",0,"","","",4,0,0,[],"",""],["lafuente_madrid-p0390-06",15,"Un fraile me dijo un dia:\nDáme la mano, salero;\nYo le dije: Padre mio,\nTome usté la del mortero.",210,0,-1,203,"",0,4,"eo",38,0,-1,0,390,390,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0391-01",15,"Si el querer que puse en ti\nLo hubiera puesto en un fraile,\nYa me lo hubiera pagado\nEn visitas por las tardes.",210,0,-1,203,"",0,4,"ae",-1,0,-1,0,391,391,"","",0,"rm_t3","","",3,0,0,[],"",""],["lafuente_madrid-p0391-02",15,"¿Qué te puede dar un fraile,\nGrandísima picarona,\nSi le hacen de por Dios\nEl cerquillo y la corona?",210,0,-1,203,"",0,4,"oa",7,0,-1,0,391,391,"","",0,"rm_t4","","",3,0,0,[],"",""],["lafuente_madrid-p0391-03",15,"Señor Cura, usté procura\nLlevar mi mujer al huerto;\nSeñor Cura, usté procura\nQue yo le caliente el cuerpo.",210,0,-1,203,"",0,4,"eo",-1,0,-1,0,391,391,"","",0,"rm_t4","","",2,0,0,[],"",""],["lafuente_madrid-p0391-04",15,"Más vale un jaleo pobre,\nY unos pimientos asados,\nQue no tener un usia\nEsaborio á mi lado.",210,0,-1,203,"",0,4,"ao",-1,0,-1,0,391,391,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0391-05",15,"Á una niña en la Carrera\nSe le cayó el abanico,\nY fueron á recogerlo\nEntre cuatro señoritos.",210,0,-1,203,"",0,4,"io",-1,0,-1,0,391,391,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0391-06",15,"Á una niña en el paseo\nSe le cayó el miriñaque,\nY le dijo un currutaco:\n¿Quiere usté que se lo ate?",210,0,-1,203,"",0,4,"ae",-1,0,-1,0,391,391,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0391-07",15,"Una niña se murió,\nY dejó en su testamento,\nQue la echarán en la caja\nCon el miriñaque puesto.",210,0,-1,203,"",0,4,"eo",-1,0,-1,0,391,391,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0392-01",15,"Al salir de la comedia\nUn borrico rebuznó,\nY respondió un lechuguino:\nEse canta como yo.",210,0,-1,203,"",0,4,"o",2,0,-1,0,392,392,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0392-02",15,"Por la calle abajo va\nUn currutaco ligero,\nQue gasta mucha fachenda,\nY tiene poco dinero.",210,0,-1,203,"",0,4,"eo",38,0,-1,0,392,392,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0392-03",15,"Ayer tarde en el paseo\nMe dijo uno, presumida:\nNo quisiera ser tan guapa,\nPor no estar tan perseguida.",210,0,-1,203,"",0,4,"ia",37,0,-1,0,392,392,"","",0,"palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0392-04",15,"Ayer tarde en el paseo\nUna muchacha encontré,\nQue á todo me respondia:\n¡Qué pícaro que es usté!",210,0,-1,203,"",0,4,"e",77,0,-1,0,392,392,"","",0,"","","",6,0,0,[],"",""],["lafuente_madrid-p0392-05",15,"Los mocitos de hoy en dia,\nCuando tienen un realillo,\nToico lo cambian en chavos\nPa que suenen los bolsillos.",210,0,-1,203,"",0,4,"io",-1,0,-1,0,392,392,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0392-06",15,"Las manolas de Madrid,\nCuando van á misa en coche,\nLo primero que preguntan\nSi es bonito el sacerdote.",210,0,-1,203,"",0,4,"oe",-1,0,-1,0,392,392,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0393-01",15,"Mata un médico al enfermo\nCon un récipe no más;\nY despues porque le ha muerto,\nSe lo tienen que pagar.",210,0,-1,203,"",0,4,"a",-1,0,-1,0,393,393,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0393-02",15,"Médicos y cirujanos\nNo van á misa mayor,\nPorque los difuntos dicen:\nEse fué quien me mató.",210,0,-1,203,"",0,4,"o",-1,0,-1,0,393,393,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0393-03",15,"Un pájaro con cien plumas.\nNo se puede mantener,\nY un escribano con una\nMantiene casa y mujer.",210,0,-1,203,"",0,4,"e",20,0,-1,0,393,393,"","",0,"palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0393-04",15,"La mujer del escribano\nLleva vestido de indiana;\n¡El demonio de la pluma\nCuánto dinero que gana!",210,0,-1,203,"",0,4,"aa",4,0,-1,0,393,393,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0393-05",15,"Primero que suba al cielo\nEl alma de un escribano,\nTintero, papel y pluma\nHan de bailar el fandango.",210,0,-1,203,"",0,4,"ao",-1,0,-1,0,393,393,"","",0,"rm_t4, palau_cantares, fernan_caballero","","",4,0,0,[],"",""],["lafuente_madrid-p0393-06",15,"Un escribano y un gato\nSe cayeron en un pozo;\nComo los dos eran gatos\nSe arañaban uno á otro.",210,0,-1,203,"",0,4,"oo",-1,0,-1,0,393,393,"","",0,"palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0393-07",15,"En-el cielo hay un racimo,\nQue es para los escribanos;\nComo no sube ninguno,\nNo le falta ningun grano.",210,0,-1,203,"",0,4,"ao",-1,0,-1,0,393,393,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0394-01",15,"En la ciudad de Tortosa\nSe está muriendo un notario;\nLos demonios del infierno\nDe alegría van bailando.",210,0,-1,203,"",0,4,"ao",-1,0,-1,0,394,394,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0394-02",15,"El reloj y el escribano\nSon de un mismo movimiento,\nQue en faltándoles la cuerda,\nLos dos se paran á un tiempo.",210,0,-1,203,"",0,4,"eo",-1,0,-1,0,394,394,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0394-03",15,"Un zapatero, y un sastre,\nY un oficial de barbero,\nSon tres personas distintas,\nY ninguno verdadero.",210,0,-1,203,"",0,4,"eo",38,0,-1,0,394,394,"","",0,"carrizo_salta, palau_cantares, fernan_caballero","","",9,0,0,[],"",""],["lafuente_madrid-p0394-04",15,"Un zapatero y un sastre\nFueron al infierno juntos;\nEl une se fué por varas,\nY el otro se fué por puntos.",210,0,-1,203,"",0,4,"uo",296,0,-1,0,394,394,"","",0,"","","",9,0,0,[],"",""],["lafuente_madrid-p0394-05",15,"Soy sastre, y tengo conciencia,\nY tengo temor á Dios;\nÁ nadie le quito nada,\nSino de tres varas, dos.",210,0,-1,203,"",0,4,"o",87,0,-1,0,394,394,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0394-06",15,"-¡Válgame Santo Tomé!\nDecia un sastre cortando;\nY el marchante le decia:\n-De aquí no, que hay poco paño.",210,0,-1,203,"",0,4,"ao",-1,0,-1,0,394,394,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0394-07",15,"Las tijeras de los sastres\nVan diciendo: rapa, rapa;\nCon este pedazo y otro\nTenemos para una capa.",210,0,-1,203,"",0,4,"aa",297,0,-1,0,394,395,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0395-01",15,"Un cojo cayó en un pozo,\nY otro cojo lo miraba,\nY otro cojo le decia:\nCojo, que te coge el agua.",210,0,-1,203,"",0,4,"aa",-1,0,-1,0,395,395,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0395-02",15,"Veinticinco Migueletes\nCon veinticinco escopetas,\nNo pudieron alcanzar\nÁ un cojo con dos muletas.",210,0,-1,203,"",0,4,"ea",525,0,-1,0,395,395,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0395-03",15,"Si vieras á un tuerto bueno,\nEscríbelo por milagro,\nY házle la cruz á los cojos,\nY no te fies de calvos.",210,0,-1,203,"",0,4,"ao",-1,0,-1,0,395,395,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0395-04",15,"Leche y agua van diciendo,\nY yo creo que dirán:\nEl lechero una mentira,\nY el aguador la verdad.",210,0,-1,203,"",0,4,"a",-1,0,-1,0,395,395,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0395-05",15,"Yo he visto á un hombre llorar\nÁ la puerta de un estanco;\nQue tambien los hombres lloran\nCuando no tienen tabaco.",210,0,-1,203,"",0,4,"ao",-1,0,-1,0,395,395,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0395-06",15,"Yo he visto á un hombre llorar\nÁ la puerta de una casa;\nQue tambien los hombres lloran,\nCuando les dan calabazas.",210,0,-1,203,"",0,4,"aa",-1,0,-1,0,395,395,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0396-01",15,"Por la mañana galbana,\nA medio dia calor,\nPor la tarde los mosquitos.\nNo quiero ser labrador.",210,0,-1,203,"",0,4,"o",72,0,-1,0,396,396,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0396-02",15,"- Á mí me llaman Peneque,\nSeñor alcalde, ¿qué haré?\n-Vaya usté con Dios, Peneque,\nQue yo lo remediaré.",210,0,-1,203,"",1,4,"e",77,0,-1,0,396,396,"","",0,"rm_t4","","",3,0,0,[],"",""],["lafuente_madrid-p0396-03",15,"Á mí me llaman Calores,\nY yo me muero de frio,\nY las mozuelas me dicen.\nCalores, vamos al rio.",210,0,-1,203,"",0,4,"o",3,0,-1,0,396,396,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0396-04",15,"-Para no llegar á viejo\n¿Qué remedio me darás?\n-Métete á servir á un amo,\nY siempre mozo serás.",210,0,-1,203,"",0,4,"a",51,0,-1,0,396,396,"","",0,"palau_cantares, fernan_caballero","","",3,0,0,[],"",""],["lafuente_madrid-p0396-05",15,"En medio de un olivar\nTengo un ochavo escondido,\nNo se lo digas á nadie,\nMira que somos perdidos.",210,0,-1,203,"",0,4,"io",-1,0,-1,0,396,396,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0396-06",15,"Caballito como el mio\nNo lo tiene el rey de España,\nQue para mover un pié\nNecesita una semana.",210,0,-1,203,"",0,4,"aa",-1,0,-1,0,396,396,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0396-07",15,"Un navío, dos navíos,\nTres navíos por la mar;\nSi hubiera cuatro navíos\nHubiera un navío más.",210,0,-1,203,"",0,4,"a",-1,0,-1,0,396,396,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0397-01",15,"Haré una torre que llegue\nAl cielo con su campana,\nY en medio colocaré\nAl que me diere la gana.",210,0,-1,203,"",1,4,"aa",4,0,-1,0,397,397,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0397-02",15,"Á conejo te convido,\nMañana voy á cazar;\nSi le tiro y no le mato,\nTe vuelvo á desconvidar.",210,0,-1,203,"",0,4,"a",21,0,-1,0,397,397,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0397-03",15,"¿No hay quien me pegue un tirito,\nAunque sea de molletes,\nCon los tacos de manteca\nY municion de aguardiente?",210,0,-1,203,"",0,4,"ee",-1,0,-1,0,397,397,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0397-04",15,"Hágame usté una escopeta:\nDe longaniza el cañon,\nDe pan blanco la Laqueta,\nY la caja de jamon,\nDe vino la cazoleta.",210,0,-1,203,"",7,5,"ea",200,0,-1,0,397,397,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0397-05",15,"Si la mar fuera de vino,\nY las montañas molletes,\nY la tierra fuera queso,\n¡Qué tragos y qué zoquetes!",210,0,-1,203,"",0,4,"ee",505,0,-1,0,397,397,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0397-06",15,"Si la mar fuera de leche,\nY los navíos de azúcar,\nMe embarcaria yo, madre,\nEn el puerto de San Lucar.",210,0,-1,203,"",5,4,"a",-1,0,-1,0,397,397,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0397-07",15,"Cuando Juanillo se pone\nLa camisa de la boda,\nSe pone su cuerpecito\nMás ancho que una amapola.",210,0,-1,203,"",0,4,"oa",-1,0,-1,0,397,397,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0398-01a",15,"Lo que priva en este mundo\nEs un pantalon de pana,\nUn sombrero calañés,\nY una capa jerezana.",210,0,-1,203,"",0,4,"aa",4,0,-1,0,398,398,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0398-01b",15,"Del año de la Nanica\nBien te debes acordar,\nQue costaban cuatro cuartos\nLas dos libritas de pan.",210,0,-1,203,"",0,4,"a",-1,0,-1,0,398,398,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0398-02",15,"Ya mi madre no se alumbra\nCon aceite de comer,\nQue se alumbra con el gas\nDe frábica del Inglés.",210,0,-1,203,"",0,4,"e",-1,0,-1,0,398,398,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0398-03",15,"La gorda va á ser mañana,\nMañana va á ser la gorda,\nQue no tengo en el bolsillo\nDos cuartos para una rosca.",210,0,-1,203,"",0,4,"oa",-1,0,-1,0,398,398,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0398-04",15,"Los gitanos y gitanas\nCuando estrenan un vestido,\nNo se lo quitan del cuerpo\nHasta que lo ven rompido.",210,0,-1,203,"",0,4,"io",101,0,-1,0,398,398,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0398-05",15,"Los gallegos en Galicia\nCuando se van a casar,\nLlevan la tripilla llena\nDe mendruguillos de pan.",210,0,-1,203,"",0,4,"a",-1,0,-1,0,398,398,"","",0,"palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0398-06",15,"No siento yo la caída,\nNi que me vieras las piernas;\nSiento sí los cinco duros\nQue me costó la peineta",210,0,-1,203,"",0,4,"ea",-1,0,-1,0,398,398,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0399-01",15,"Corre que te pilla el toro\nLa capa, y no tienes otra,\nY luego te llamarán\nEl de la capilla rota.",210,0,-1,203,"",0,4,"oa",-1,0,-1,0,399,399,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0399-02",15,"Canto, bailo y represento,\nY tambien hago pelucas;\nY con tanta habilidad\nNo tengo dos cuartos nunca.",210,0,-1,203,"",0,4,"ua",-1,0,-1,0,399,399,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0399-03",15,"-¿Cuándo llega Narizotas?-\nLe pregunté á la criada.\n-Las narices llegan hoy,\nEl amo llega mañana.",210,0,-1,203,"",0,4,"aa",-1,0,-1,0,399,399,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0399-04",15,"Los perros tras de los lobos\nEn el campo van corriendo,\nY en Madrid veo correr\nLos lobos tras de los perros.",210,0,-1,203,"",0,4,"eo",-1,0,-1,0,399,399,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0399-05",15,"Si canto, me llaman loca,\nY si no canto la séria:\nÁ todo el que me murmura\nBuena pepita en la lengua.",210,0,-1,203,"",0,4,"ea",-1,0,-1,0,399,399,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0399-06",15,"Cuando yo voy á una fiesta\nTengo el gustillo cifrado\nEn meterme en los rincones\nPor ver los amartelados.",210,0,-1,203,"",0,4,"ao",-1,0,-1,0,399,399,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0400-01",15,"Una vez que me prestó\nMi vecina las tenazas,\nQuiere que le dé yo ahora\nTodo lo que tengo en casa.",210,0,-1,203,"",0,4,"aa",-1,0,-1,0,400,400,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0400-02",15,"En toda mi vida he visto\nJustillo de mejor tela\nQue aquel que te están cortando\nEn el corrillo, Manuela.",210,0,-1,203,"",0,4,"ea",167,0,-1,0,400,400,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0400-03",15,"Las vecinas de mi calle\nTodas se juntan en corro,\nY me cortan un vestido,\nEse dinero me ahorro.",210,0,-1,203,"",0,4,"oo",301,0,-1,0,400,400,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0400-04",15,"Ya vienen, vienen los rusos\nPor las ventas de Alcorcon,\nY los rusos que venian\nEran cargas de carbon.",210,0,-1,203,"",5,4,"ao",-1,0,-1,0,400,400,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0400-05",15,"Si quieres que te lo diga\nVen acá y te lo diré:\nTu padre y tu madre fueron....\nUn hombre y una mujer.",210,0,-1,203,"",0,4,"e",-1,0,-1,0,400,400,"","",0,"palau_cantares","","",9,0,0,[],"",""],["lafuente_madrid-p0400-06",15,"Te han dicho que he dicho un dicho,\nDicho que no he dicho yo,\nQue si yo lo hubiera dicho,\nNo hubiera dicho que no.",210,0,-1,203,"",1,4,"o",2,0,-1,0,400,400,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0400-07",15,"El sereno de mi calle\nEs un picaro embustero,\nQue dice que está nublado,\nY ha amanecido lloviendo.",210,0,-1,203,"",0,4,"eo",-1,0,-1,0,400,400,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0402-01",15,"Un ciego estaba mirando\nComo se quema una casa,\nUn mudo llamaba gente,\nY un cojo llevaba el agua.",210,0,-1,204,"",0,4,"aa",-1,0,-1,0,402,402,"","",0,"machado_venezuela, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0402-02",15,"¿Te acuerdas, ingratisíma,\nLa noche de san Lazáro,\nQue te dí pa una sabána\nDoce varas de cañámo?",210,0,-1,204,"",0,4,"ao",-1,0,-1,0,402,402,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0402-03",15,"Estaba la Virgen Mária.\nY los santos apostóles\nComiendose unos pajáros\nDebajo de unos arbóles.",210,0,-1,204,"",0,4,"oe",27,0,-1,0,402,402,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0402-04",15,"Estaba san Juan de Dios\nSubido en una higuera\nCon un retaco en la mano\nApuntándole á una breva.",210,0,-1,204,"",0,4,"ea",-1,0,-1,0,402,402,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0402-05",15,"En San Juan de Dios, en Cádiz,\nHay un raton con viruelas,\nY un gato caritativo\nLe está echando sanguijuelas..",210,0,-1,204,"",0,4,"ea",605,0,-1,0,402,402,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0403-01",15,"En San Juan de Dios, en Cádiz,\nHay un raton con tercianas,\nY un gato caritativo\nLe está encomendando el alma.",210,0,-1,204,"",0,4,"aa",-1,0,-1,0,403,403,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0403-02",15,"De las álas de un mosquito\nHizo mi morena un manto,\nY le salió tan bonito\nQue lo estrenó en Viernes santo.",210,0,-1,204,"",1,4,"ao",30,0,-1,0,403,403,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0403-03",15,"Un pájaro entelerido\nLlegó á la puerta de un sastre,\nÁ que le hiciera un vestido\nDe la tela de un tomate.",210,0,-1,204,"",0,4,"ae",-1,0,-1,0,403,403,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0403-04",15,"Yo he visto á un pavo segar,\nÁ un gallo coger espigas,\nY á una gallina trillar.\nNo lo creas, que es mentira.",210,0,-1,204,"",0,4,"ia",-1,0,-1,0,403,403,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0403-05",15,"Yo he visto á un monte volar,\nY á una torre andar á gatas,\nY en lo profundo del mar\nÁ un burro asando patatas.",210,0,-1,204,"",1,4,"aa",328,0,-1,0,403,403,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0403-06",15,"Dél vientre de una sardina\nSalió un caballo á galope,\nÁ confesar á una esquina,\nQue estando comiendo arrope,\nSe le atravesó una espina.",210,0,-1,204,"",7,5,"ia",11,0,-1,0,403,403,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0404-01",15,"Á la una nací yo,\nÁ las dos me bautizaron,\nÁ las tres tenia novio,\nY á las cuatro me casaron.",210,0,-1,204,"",0,4,"ao",41,0,-1,0,404,404,"","",0,"","","",7,0,0,[],"",""],["lafuente_madrid-p0404-02",15,"Cuando me parió mi madre,\nMe parió en un campanario;\nCuando vino la comadre,\nEstaba yo repicando.",210,0,-1,204,"",0,4,"ao",-1,0,-1,0,404,404,"","",0,"fernan_caballero","","",8,0,0,[],"",""],["lafuente_madrid-p0405-01",15,"Por esos aires subia\nUn serafin á los cielos,\nY al ver esta tierra, dijo:\nNo subo, que aqui me quedo.",210,0,-1,205,"",0,4,"eo",-1,0,-1,0,405,405,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0405-02",15,"La mar cubierta de sangre,\nLos montes echando humo,\nEl inglés tirando bombas,\nY España rumbo que rumbo.",210,0,-1,205,"",0,4,"uo",-1,0,-1,0,405,405,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0405-03",15,"Todos le temen á Francia,\nComo si en la Francia hubiera\nAlgun animal feroz\nQue los hombres se comtera.",210,0,-1,205,"",0,4,"ea",44,0,-1,0,405,405,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0405-04",15,"En Francia dicen mon diú,\nY en Italia, insto chielo,\nY aquí decimos: ¡caramba!\nY se junde el mundo entero.",210,0,-1,205,"",3,4,"eo",-1,0,-1,0,405,405,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0406-01",15,"Napoleon subió al cielo\nÁ pedirle á Dios la España,\nY le respondió san Pedro:\n¿Quieres que te rompa el alma?",210,0,-1,205,"",0,4,"aa",-1,0,-1,0,406,406,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0406-02",15,"Napoleon Bonaparte:\n¿Qué tal te parece España?\nYa tienes en tu presencia\nAl marqués de la Romana.",210,0,-1,205,"",0,4,"aa",-1,0,-1,0,406,406,"","",0,"rm_t4","","",2,0,0,[],"",""],["lafuente_madrid-p0406-03",15,"Los rusos vienen por tierra,\nLos ingleses por el agua;\nY yo, que soy español,\nMe estoy tumbado en la cama.",210,0,-1,205,"",0,4,"aa",-1,0,-1,0,406,406,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0406-04",15,"La Habana se va á perder,\nLa culpa tiene el dinero;\nLos negros se vuelven blancos,\nY los blancos aduaneros.",210,0,-1,205,"",0,4,"eo",-1,0,-1,0,406,406,"","",0,"rm_t4, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0406-05",15,"Sevilla para el regalo,\nMadrid para la grandeza,\nPara tropas Barcelona,\nPara jardines Valencia.",210,0,-1,205,"",0,4,"ea",-1,0,-1,0,406,406,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0406-06",15,"Campana la de Toledo,\nCatedral la de Leon,\nReloj el de Benavente,\nY Rollo el de Villalon.",210,0,-1,205,"",5,4,"ao",-1,0,-1,0,406,406,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0407-01",15,"Málaga tiene un castillo,\nGranada tiene su Alhambra,\nY Zaragoza su Coso,\nY el Coso zaragozanas.",210,0,-1,205,"",0,4,"aa",-1,0,-1,0,407,407,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0407-02a",15,"Yo voy á Guadix por peras,\nA Sevilla por manzanas,\nÁ las Indias por dinero,\nY á la sierra por serranas.",210,0,-1,205,"",0,4,"aa",263,0,-1,0,407,407,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0407-02b",15,"Por las calles de Madrid\nSe pasea un valenciano,\nCon un clavel en la boca\nY una rosa en cada mano.",210,0,-1,205,"",0,4,"ao",81,0,-1,0,407,407,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0407-03",15,"Venga el gallego á segar,\nMiserable jornalero,\nQue los hombres de Castilla\nTienen el trabajo á menos.",210,0,-1,205,"",0,4,"eo",-1,0,-1,0,407,407,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0407-04",15,"En Madrid, con ser Madrid,\nSe levantan de mañana,\nY comen, si tienen qué,\nY almuerzan, si tienen gana.",210,0,-1,205,"",0,4,"aa",4,0,-1,0,407,407,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0407-05",15,"Castellano, castellano,\nNo te vayas à Castilla,\nQue tienes en Aragon\nQuíen te quiere y quien te estima.",210,0,-1,205,"",3,4,"ia",-1,0,-1,0,407,407,"","",0,"rm_t4, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0407-06",15,"En teniendo el castellano\nVino, ajos, trigo y cebada,\nNo deja la plaza en julio,\nNi en el enero la capa.",210,0,-1,205,"",0,4,"aa",-1,0,-1,0,407,407,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0408-01",15,"Los gallegos en Galicia,\nCuando van en procesion,\nLlevan un gato por santo,\nY una vieja por pendon.",210,0,-1,205,"",0,4,"eo",-1,0,-1,0,408,408,"","",0,"rm_t4","","",6,0,0,[],"",""],["lafuente_madrid-p0408-02",15,"Los gallegos en Galicia\nDicen que no beben vino,\nY con el vino que beben\nPuede moler un molino.",210,0,-1,205,"",0,4,"io",199,0,-1,0,408,408,"","",0,"rm_t4","","",6,0,0,[],"",""],["lafuente_madrid-p0408-03",15,"Á Sevilla me he de ir\nÁ buscar un sevillano\nQue los mozos de Madrid\nMucha paja y poco grano.",210,0,-1,205,"",0,4,"ao",81,0,-1,0,408,408,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0408-04",15,"En Sevilla las campanas\nNo le doblan á los muertos,\nPorque á la señora Infanta\nLe da mucho sentimiento.",210,0,-1,205,"",0,4,"eo",-1,0,-1,0,408,408,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0408-05",15,"¡Sevilla del alma mia!\n¡Sevilla de mi consuelo!\n¡Quién estuviera en Sevilla,\nAunque durmiera en el suelo!",210,0,-1,205,"",0,4,"eo",10,0,-1,0,408,408,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0408-06",15,"Si yo tuviera dinero,\nComo tiene el rey de España,\nMandara hacer una rosc\nDel vuelo de la Giralda.",210,0,-1,205,"",0,4,"aa",-1,0,-1,0,408,408,"","",0,"","","",6,0,0,[],"",""],["lafuente_madrid-p0409-01",15,"Un hombre tropezó en Cádiz,\nY en Sevilla se cayó;\nFué rodando hasta Madrid,\nY en Francia se levantó.",210,0,-1,205,"",0,4,"o",2,0,-1,0,409,409,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0409-02",15,"En Cádiz tengo la muerte,\nEn Sevilla la mortaja,\nY en la isla de Leon\nMe están haciendo la caja.",210,0,-1,205,"",0,4,"aa",393,0,-1,0,409,409,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0409-03",15,"Viva Cádiz, porque tiene\nLas murallas hácia el mar,\nY cañones apuntando\nAl peñon de Gibraltar.",210,0,-1,205,"",0,4,"a",21,0,-1,0,409,409,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0409-04",15,"Viva Cádiz, porque tiene\nLas murallas á la mar;\nVivan los cuerpos bonitos,\nVivan las hembras saláas.",210,0,-1,205,"",5,4,"aa",-1,0,-1,0,409,409,"","",0,"","","",4,0,0,[],"",""],["lafuente_madrid-p0409-05",15,"¡Viva Cádiz! ¡Viva el Puerto!\n¡Vivan las hembras y el vino!\n¡Y vivan los mozos buenos\nQue andan por esos caminos!",210,0,-1,205,"",0,4,"io",-1,0,-1,0,409,409,"","",0,"palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0409-06",15,"Quiero entrar y no me dejan,\nQuiero salir y no puedo;\nCádiz no se llama Cádiz,\nQue se llama susto y miedo.",210,0,-1,205,"",0,4,"eo",304,0,-1,0,409,409,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0409-07",15,"Cádiz no se llama Cádiz,\nQue se llama relicario,\nPorque tiene por patrona\nÁ la Virgen del Rosaria.",210,0,-1,205,"",5,4,"aa",-1,0,-1,0,409,409,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0410-02",15,"Á Roma se va por bulas,\nPor tabaco á Gibraltar,\nPor manzanilla á San Lucar,\nY á Cádiz se va por sal.",210,0,-1,205,"",0,4,"a",-1,0,-1,0,410,410,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0410-03",15,"Mañana me voy á Cádiz,\nPasar el rio no puedo;\nPásame, Pepe del alma,\nEn tu caballo ligero.",210,0,-1,205,"",0,4,"eo",-1,0,-1,0,410,410,"","",0,"palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0410-04",15,"En el mar hay un pescado\nQue le llaman el inglés;\nTiene un letrero, que dice:\n¡Viva el vino de Jeréz!",210,0,-1,205,"",0,4,"e",150,0,-1,0,410,410,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0410-05",15,"¡Viva Medina-Sidonia\nY Jeréz de la Frontera,\nY tambien digo que viva\nSan Lucar de Barrameda!",210,0,-1,205,"",0,4,"ea",-1,0,-1,0,410,410,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0410-06",15,"Un hombre sabio de Rota\nEstaba pensando un dia,\nQue si no hubiera tomates,\nEl mundo se acabaria.",210,0,-1,205,"",0,4,"ia",0,0,-1,0,410,410,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0410-07",15,"Los Roteños á sus novias\nAcostumbran regalar\nPepitas de calabaza,\nQue son confites allá.",210,0,-1,205,"",0,4,"a",-1,0,-1,0,410,410,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0411-01",15,"No se ha podido saber,\nNi se sabrá á punto fijo,\nLos borricos que hay en Rota,\nPorque llega á lo infinito.",210,0,-1,205,"",0,4,"io",-1,0,-1,0,411,411,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0411-02",15,"Cuatro cosas tiene Ceuta\nQue no las tiene Madrid:\nEl Bonito, la Caballa,\nEl Hacho y el Rebellin.",210,0,-1,205,"",5,4,"ei",-1,0,-1,0,411,411,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0411-03",15,"Á San Roque lo comparo\nCon el reves de una taza;\nTodas son cuestas arriba\nHasta llegar á la plaza.",210,0,-1,205,"",0,4,"aa",307,0,-1,0,411,411,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0411-04",15,"Á Ronda, que es tierra honda,\nY es tierra de regadío;\nVámonos, serrana, á Ronda,\nQue en Ronda tengo yo un tio.",210,0,-1,205,"",1,4,"o",3,0,-1,0,411,411,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0411-05",15,"Si yo tuviera un ochavo\nTe comprara medio Rute,\nY las huertas de la Granja,\nY los cortijos del Duque.",210,0,-1,205,"",0,4,"ue",-1,0,-1,0,411,411,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0411-06",15,"Antequera está en un hoyo.\nY Mollina entre olivares,\nY la triste de Pedrera\nNo tiene más que una calle.",210,0,-1,205,"",0,4,"ae",-1,0,-1,0,411,411,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0411-07",15,"En Málaga está la planta,\nEn Antequera el rosal,\nY en Archidona la rosa\nQue me tengo de llevar.",210,0,-1,205,"",0,4,"a",-1,0,-1,0,411,411,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0412-01",15,"En Málaga venden uvas,\nEn Torremolinos peros,\nEn la Pizarra naranjas,\nY en Almojía sombreros.",210,0,-1,205,"",0,4,"eo",22,0,-1,0,412,412,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0412-02",15,"De Torrox la caña dulce,\nY de Nerja las batatas,\nDe Velez el boqueron,\nDe Málaga las muchachas.",210,0,-1,205,"",0,4,"aa",-1,0,-1,0,412,412,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0412-03",15,"Málaga tiene la fama\nDe las muchachas bonitas;\nY no es el leon tan fiero\nComo las gentes lo pintan.",210,0,-1,205,"",0,4,"ia",-1,0,-1,0,412,412,"","",0,"","","",6,0,0,[],"",""],["lafuente_madrid-p0412-04",15,"Si no es el leon tan fiero\nComo las gentes lo pintan,\nMálaga tiene muchachas\nQue á los hombres dan penitas.",210,0,-1,205,"",0,4,"ia",-1,0,-1,0,412,412,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0412-05",15,"Málaga tiene la fama\nDel vino y del aguardiente,\nDe las muchachas bonitas,\nY de los hombres valientes.",210,0,-1,205,"",0,4,"ee",-1,0,-1,0,412,412,"","",0,"palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0412-06",15,"Málaga, fuerte muralla\nQue contiene el mar soberbio;\nEl mejor puerto de mar\nQue tiene el rey en su reino.",210,0,-1,205,"",0,4,"eo",-1,0,-1,0,412,412,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0413-01",15,"Á Málaga me he de ir\nAunque no tenga dinero,\nQue allí no me ha de faltar\nRopa para andar en cueros.",210,0,-1,205,"",0,4,"eo",-1,0,-1,0,413,413,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0413-02",15,"Tienen las malagueñitas\nLa sal de Dios en los labios,\nY en la punta de la lengua\nAzúcar, canela y clavo.",210,0,-1,205,"",0,4,"ao",-1,0,-1,0,413,413,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0413-03",15,"Malaguilla, Malaguilla,\nEl rey te quiere vender;\nEl que á Malaguilla compre,\nDineros ha de tener!",210,0,-1,205,"",0,4,"e",-1,0,-1,0,413,413,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0413-04",15,"Adios, Málaga la bella,\nTierra donde yo naci;\nPara todos fuiste madre,\nY madrastra para mí.",210,0,-1,205,"",0,4,"i",23,0,-1,0,413,413,"","",0,"palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0413-05",15,"Adios, Málaga la bella,\nLa tierra de los encantos;\nEl que te llegare á ver\nTiene que pensar cien años.",210,0,-1,205,"",0,4,"ao",-1,0,-1,0,413,413,"","",0,"palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0413-06",15,"Adios, Málaga la bella,\nÁ popa te voy mirando,\nCon el trinquete á la vela,\nY la verga mareando.",210,0,-1,205,"",0,4,"ao",33,0,-1,0,413,413,"","",0,"palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0413-07",15,"Desde la Cruz de la Legua\nVolví la cara llorando.\n¡Adios! Málaga la bella,\nQué lejos te vas quedando!",210,0,-1,205,"",0,4,"ao",33,0,-1,0,413,413,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0414-01",15,"En Málaga los serenos\nVan diciendo por la calle:\nDuerma quien tuviere sueño,\nQue yo no dispierto á nadie.",210,0,-1,205,"",0,4,"ae",-1,0,-1,0,414,414,"","",0,"","","",4,0,0,[],"",""],["lafuente_madrid-p0414-02",15,"En Málaga no hay sereno\nY está bien dispuesto así:\nEl que quiera madrugar,\nQue no se acueste á dormir.",210,0,-1,205,"",0,4,"i",-1,0,-1,0,414,414,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0414-03",15,"En Málaga me embarqué\nEn un casco de cebolla,\nY vine á desembarcar\nEn la puerta de mi novia.",210,0,-1,205,"",0,4,"oa",-1,0,-1,0,414,414,"","",0,"palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0414-04",15,"El castillo Gibralfaro\nSe está muriendo de risa,\nDe ver á las malagueñas\nCon peineta y sin camisa.",210,0,-1,205,"",0,4,"ia",68,0,-1,0,414,414,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0414-05",15,"Una vez que me arresté\nÁ saber lo que era mundo\nEn el barrio del Perchel\nMe la jugaron de puños.",210,0,-1,205,"",0,4,"uo",-1,0,-1,0,414,414,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0414-06",15,"La malagueñita nueva\nHa venido de Madrid;\nDesde Madrid vino á Cádiz\nY desde Cádiz aquí.",210,0,-1,205,"",0,4,"i",-1,0,-1,0,414,414,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0415-01",15,"La rondeña malagueña\nNadie la sabe cantar,\nSino los malagueñitos,\nQue tienen sandunga y sal.",210,0,-1,205,"",0,4,"a",-1,0,-1,0,415,415,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0415-02",15,"Más vale una victoriana ()\nQue doscientas percheleras,\nQue las victorianas tienen\nLa sandunga de la tierra.",210,0,-1,205,"",0,4,"ea",-1,0,-1,0,415,415,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0415-03",15,"¡Adios, torre de la Mar,\nCastillo de san Lorenzo!\n¡Adios, Anita María\nQue por tí me llevan preso!",210,0,-1,205,"",0,4,"eo",-1,0,-1,0,415,415,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0415-04",15,"Quiero vivir en Granada\nPorque me gusta el oir\nLa campana de la Vela,\nCuando me voy á dormir.",210,0,-1,205,"",0,4,"i",157,0,-1,0,415,415,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0415-05",15,"Mira si he corrido tierras\nQue he estado en el Albaicin,\nEn la carrera de Darro,\nY en la puente de Genil.",210,0,-1,205,"",5,4,"i",-1,0,-1,0,415,415,"","",0,"palau_cantares","","",15,0,0,[],"",""],["lafuente_madrid-p0416-01",15,"Tres cosas tiene Granada\nQue no las tiene Madrid:\nEl Zacatin y la Alhambra,\nY la puente de Genil.",210,0,-1,205,"",0,4,"i",-1,0,-1,0,416,416,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0416-02",15,"Á la entrada de Granada,\nCalle de los Herradores,\nEstá la Virgen del Triunfo,\nCon veinticinco faroles.",210,0,-1,205,"",0,4,"oe",-1,0,-1,0,416,416,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0416-03",15,"Fuí al Triunfo y le recé\nÁ la Virgen una salve,\nY luego la encomendé\nPor el alma de quien sabes.",210,0,-1,205,"",0,4,"ae",-1,0,-1,0,416,416,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0416-04",15,"Á los Cármenes del Darro\nMe tengo de ir á vivir,\nPorque dicen que se goza\nLa gloria antes de morir.",210,0,-1,205,"",0,4,"i",157,0,-1,0,416,416,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0416-05",15,"Vámonos al Avellano\nÁ beber agua fresquita,\nPorque dicen que allí está\nLa flor de la canelita.",210,0,-1,205,"",0,4,"ia",50,0,-1,0,416,416,"","",0,"rm_t4, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0416-06",15,"¡Qué buena noche que hace\nPara ir al Algibillo, (2)\nCon una buena guitarra,\nY tres pares de palillos!",210,0,-1,205,"",0,4,"io",-1,0,-1,0,416,416,"","",0,"","","",5,0,0,[],"",""],["lafuente_madrid-p0417-01",15,"Pensamiento tiene Darro\nDe casarse con Genil,\nY le ha de llevar en dote\nPlaza Nueva y Zacatin.",210,0,-1,205,"",0,4,"i",-1,0,-1,0,417,417,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0417-02",15,"¡Adios, calle de Mesones,\nConsuelo de mi barriga,\nQue por cuatro cuartos dan\nCaldo, chanfaina y morcilla!",210,0,-1,205,"",0,4,"ia",-1,0,-1,0,417,417,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0418-01",15,"Barrio de San Nicolás,\nBarrio de las Comuneras,\nQue debajo de los poyos\nEstá puesta la bandera.",210,0,-1,205,"",0,4,"ea",-1,0,-1,0,418,418,"","",0,"rm_t4","","",2,0,0,[],"",""],["lafuente_madrid-p0418-02",15,"En Granada están las flores,\nEn Motril las malas lenguas,\nY en llegando á la Alpujarra...\n¡Viva la gente morena!",210,0,-1,205,"",0,4,"ea",-1,0,-1,0,418,418,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0418-03",15,"Antes brujo que gallego,\nAntes gallego que fraile,\nAntes fraile que de Pitres (2),..\nPorque de Pitres no hay antes.",210,0,-1,205,"",0,4,"ae",-1,0,-1,0,418,418,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0419-01",15,"Tres cosas tiene Zuheros,\nQue no las tiene Madrid:\nCharco hondo, la Atalaya,\nY la peña de Parir.",210,0,-1,205,"",0,4,"i",-1,0,-1,0,419,419,"","",0,"rm_t4","","",2,0,0,[],"",""],["lafuente_madrid-p0419-02",15,"Alcázar y los Bargises\nSon pueblos de mi respeto;\nPero le temo á los nabos,\nPorque ¡son tan indigestos!",210,0,-1,205,"",0,4,"eo",-1,0,-1,0,419,419,"","",0,"rm_t4","","",2,0,0,[],"",""],["lafuente_madrid-p0419-03",15,"Viva Gualchos, que es mi tierra,\nSan Miguel, que es mi patron;\nViva la gente morena,\nQue morenita soy yo.",210,0,-1,205,"",0,4,"o",-1,0,-1,0,419,419,"","",0,"rm_t4","","",2,0,0,[],"",""],["lafuente_madrid-p0419-04",15,"Mañana voy á Jolúcar\nÁ ver á san Cayetano\nÁ queme preste dinero\nPara casarme el verano.",210,0,-1,205,"",0,4,"ao",81,0,-1,0,419,419,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0419-05",15,"Á la entrada del Padul\nY á la salida de Dúrcal\nHay un letrero que dice:\nLa cosa está como nunca.",210,0,-1,205,"",0,4,"ua",-1,0,-1,0,419,419,"","",0,"rm_t4","","",2,0,0,[],"",""],["lafuente_madrid-p0420-01",15,"Sabrás que vengo de Dilar,\nY te traigo un estadal,\nY unos garbanzos tostados.....\nPero no los probarás.",210,0,-1,205,"",0,4,"a",-1,0,-1,0,420,420,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0420-01-e2",15,"Yo tenia unos amores\nDe pepitas de melon,\nY vino un aire solano,\nY se los llevó á Albuñol.",210,0,-1,205,"",0,4,"o",-1,0,-1,0,420,420,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0420-01-e3",15,"El sacristan de Albolote\nY el cura de Maracena,\nIban cantando y diciendo:\nDios nos la depare buena.",210,0,-1,205,"",0,4,"ea",59,0,-1,0,420,420,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0420-01-e4",15,"Mira si he corrido tierras\nCuando he estado en la Raijana\nEn el barranco del Negro\nY en la ramblita del Agua.",210,0,-1,205,"",0,4,"aa",-1,0,-1,0,420,420,"","",0,"rm_t4, palau_cantares","","",15,0,0,[],"",""],["lafuente_madrid-p0420-01-e5",15,"En Olíar y Fregenite\nAlcázar y Torviscon:\nEn estos cuatro lugares\nTengo yo mi corazon.",210,0,-1,205,"",5,4,"ao",-1,0,-1,0,420,420,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0420-01-e6",15,"Buena vega tiene Lújar,\nY buen zacatin Rubite,\nYbuenas muchachas rubias\nOlíar y Fregenite.",210,0,-1,205,"",0,4,"ie",315,0,-1,0,420,420,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0421-01",15,"Almejijar y Notaéz,\nCástaras y Torviscon,\nY la santa cruz de Murtas\nNos echen su bendicion.",210,0,-1,205,"",0,4,"io",-1,0,-1,0,421,421,"","",0,"rm_t4","","",2,0,0,[],"",""],["lafuente_madrid-p0421-02",15,"En Santafé de Almería\nLe salió á una fea un novio,\nY fué tanta su alegria\nQue se la llevó el demonio.",210,0,-1,205,"",0,4,"oo",-1,0,-1,0,421,421,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0421-03",15,"Quédate con Dios, Motril,\nCon tu palma y tu palmito,\nQue me voy á la Mamola\nÁ comer pescado frito.",210,0,-1,205,"",0,4,"io",119,0,-1,0,421,421,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0421-04",15,"No te fies de Motril,\nAunque digan bien te quiero;\nPues por una caña dulce\nMataron á un artillero.",210,0,-1,205,"",0,4,"eo",38,0,-1,0,421,421,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0421-05",15,"Cartagena me da pena\nY Murcia me da dolor:\n¡Cartagena de mi vida!\n¡Murcia de mi corazon!",210,0,-1,205,"",0,4,"o",-1,0,-1,0,421,421,"","",0,"rm_t4, carrizo_salta, palau_cantares, murciano_antiguo","","",5,0,0,[],"",""],["lafuente_madrid-p0421-06",15,"Vámonos á Cartagena\nA ver el mar y sus olas;\nA ver los barcos del rey,\nCon banderas españolas.",210,0,-1,205,"",0,4,"oa",317,0,-1,0,421,421,"","",0,"rm_t4, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0422-01",15,"Á la una me embarqué,\nÁ las dos me hice á la vela,\nÁ las tres en Alicante,\nÁ las cuatro en Cartagena.",210,0,-1,205,"",0,4,"ea",-1,0,-1,0,422,422,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0422-02",15,"¡Cartagena de levante,\nPuerto de mar venturoso,\nDescanso de los navios,\nY de los hombres reposo!",210,0,-1,205,"",0,4,"oo",160,0,-1,0,422,422,"","",0,"rm_t4, palau_cantares","","",7,0,0,[],"",""],["lafuente_madrid-p0422-03",15,"Cartagena de levante,\nBien te puedes celebrar,\nQue Murcia con ser tan grande\nNo tiene puerto de mar.",210,0,-1,205,"",0,4,"a",21,0,-1,0,422,422,"","",0,"palau_cantares","","",7,0,0,[],"",""],["lafuente_madrid-p0422-04",15,"Buena tierra es Cartagena\nPorque tiene cerca el monte,\nPero es mejor Alicante\nPor el barrio de San Roque.",210,0,-1,205,"",0,4,"oe",-1,0,-1,0,422,422,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0422-05",15,"En el muelle de Alicante\nHay una hermosa farola,\nPara alumbrar á mi amante\nQue viene de Barcelona.",210,0,-1,205,"",0,4,"oa",-1,0,-1,0,422,422,"","",0,"rm_t4, palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0422-06",15,"Adios, Alicante hermoso,\nCon castillo y estandarte:\nAdios, puerta de la reina,\nDonde yo solia hablarte.",210,0,-1,205,"",0,4,"ae",8,0,-1,0,422,422,"","",0,"palau_cantares, fernan_caballero","","",3,0,0,[],"",""],["lafuente_madrid-p0423-01",15,"Alicante por su muelle,\nMurcia por sus arrabales,\nOrihuela por su huerta,\nElche por sus palmerales.",210,0,-1,205,"",0,4,"ae",26,0,-1,0,423,423,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0423-02",15,"Adios, arenal de Murcia,\nPaseo de militares,\nDonde se pasean damas\nAl lado de sus galanes.",210,0,-1,205,"",0,4,"ae",-1,0,-1,0,423,423,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0423-03",15,"En Elche está Calandura\nEn Villena el Orejon,\nY en Caudete está la mona\nPara tocar el reloj.",210,0,-1,205,"",5,4,"o",-1,0,-1,0,423,423,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0423-04",15,"Quedate con Dios, Jaen,\nY tambien puerta barrera;\nQue me voy á Leganés\nA batallar con Cabrera.",210,0,-1,205,"",0,4,"ea",44,0,-1,0,423,423,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0423-05",15,"El aguardiente de Ocaña\nLo llevan á Puerto-Rico,\nY repican las campanas\nComo si fuera el Obispo.",210,0,-1,205,"",0,4,"io",-1,0,-1,0,423,423,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0424-01",15,"Tres cosas tiene Cazorla\nQue no las tiene Baeza:\nSan Isicio, Monte Sion,\nLa virgen de la Cabeza.",210,0,-1,205,"",0,4,"ea",108,0,-1,0,424,424,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0424-02",15,"Dicen que Valencia es,\nJardin de todas las flores;\nYo digo que en Aragon\nSe crian mas y mejores.",210,0,-1,205,"",0,4,"oe",5,0,-1,0,424,424,"","",0,"rm_t4, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0424-03",15,"Viva Valencia y Murviedro\nY Castellon de la Plana,\nY vivan los cuerpos buenos\nDe las chicas valencianas.",210,0,-1,205,"",0,4,"aa",-1,0,-1,0,424,424,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0424-04",15,"Las muchachitas de Alcoy\nCuando van por agua al rio\nSe dicen unas á otras:\n¿Cuando tendremos marido?",210,0,-1,205,"",0,4,"io",-1,0,-1,0,424,424,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0424-05",15,"No compres mula en Teruel,\nNi en Albarracin ganado,\nNi en Francia tomes mujer,\nQue todo te saldrá malo.",210,0,-1,205,"",0,4,"ao",-1,0,-1,0,424,424,"","",0,"rm_t4","","",2,0,0,[],"",""],["lafuente_madrid-p0424-06",15,"Son las niñas valencianas\nEstrellitas de la mar,\nQue hacen la guerra á los hombres\nCon su gracioso mirar.",210,0,-1,205,"",0,4,"a",21,0,-1,0,424,424,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0424-07",15,"Todos los aragoneses\nLlevan al pecho colgada\nLa imágen de su patrona,\nCon una cinta morada.",210,0,-1,205,"",0,4,"aa",49,0,-1,0,424,424,"","",0,"rm_t4, palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0425-01",15,"No me gusta el rigodon\nNi la galop, ni la polka,\nComo soy aragones\nSolo me gusta la jota.",210,0,-1,205,"",0,4,"oa",-1,0,-1,0,425,425,"","",0,"rm_t4","","",3,0,0,[],"",""],["lafuente_madrid-p0425-02a",15,"Todos los navarros, madre,\nCantan la jota navarra,\nY yo como aragones,\nCanto la zaragozana.",210,0,-1,205,"",0,4,"aa",-1,0,-1,0,425,425,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0425-02b",15,"En tu vida te enamores\nDe mozos aragoneses,\nQue son como las nogueras,\nMucho ruido y pocas nueces.",210,0,-1,205,"",0,4,"ee",196,0,-1,0,425,425,"","",0,"rm_t4, palau_cantares","","",7,0,0,[],"",""],["lafuente_madrid-p0425-03",15,"La vírgen del Pilar dice\nQue no quiere ser francesa,\nQue quiere ser capitana\nDe la tropa aragonesa.",210,0,-1,205,"",0,4,"ea",201,0,-1,0,425,425,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0425-04",15,"¡Que gusto es en Zaragoza\nOir un niño cantar,\nCon la bandurria tocando,\nSi serena noche está!",210,0,-1,205,"",0,4,"a",-1,0,-1,0,425,425,"","",0,"","","",5,0,0,[],"",""],["lafuente_madrid-p0425-05",15,"Que gusto es en Zaragoza\nEl salir à pasear,\nCon una dama preciosa\nPor llevar toda la sal.",210,0,-1,205,"",0,4,"a",-1,0,-1,0,425,425,"","",0,"palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0425-06",15,"Navarrito, navarrito,\nNo seas tan fanfarron,\nQue los cuartos de Navarra,\nNo pasan en Aragon.",210,0,-1,205,"",0,4,"ao",31,0,-1,0,425,425,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0426-01",15,"Amores tengo en San Pablo,\nTambien en la Magdalena;\nPero los del arrabal\nSon los que me dan más pena,",210,0,-1,205,"",0,4,"ea",59,0,-1,0,426,426,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0426-02",15,"Zaragoza, Zaragoza,\nZaragoza de los diablos;\nUna vez que estuve en ella,\n¡Qué bien me enzaragozaron!",210,0,-1,205,"",0,4,"ao",-1,0,-1,0,426,426,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0426-03",15,"Camino de Zaragoza,\nCamino carreteril,\nPor donde van las noticias\nDe Zaragoza á Madrid.",210,0,-1,205,"",0,4,"i",-1,0,-1,0,426,426,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0426-04",15,"Adios Zaragoza noble,\nAdios pulido arrabal,\nAdios Cristo de la Seo,\nAdios Vírgen del Pilar.",210,0,-1,205,"",0,4,"a",-1,0,-1,0,426,426,"","",0,"rm_t4, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0426-05",15,"Adios, noble Zaragoza,\nAdios los siete portales,\nAdios la calle del Coso,\nQue es paseo de galanes.",210,0,-1,205,"",0,4,"ae",-1,0,-1,0,426,426,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0426-06",15,"Gallo de la Magdalena,\nCuida de la plaza un rato,\nQue nos vamos á rondar\nÁ la parroquia del Gancho. (1)",210,0,-1,205,"",0,4,"ao",-1,0,-1,0,426,426,"","",0,"","","",5,0,0,[],"",""],["lafuente_madrid-p0427-01",15,"Gallo de la Magdalena\nYa te puedes poner luto,\nPorque el gancho de san Pablo\nEstá en la cama difunto.",210,0,-1,205,"",0,4,"uo",-1,0,-1,0,427,427,"","",0,"","","",5,0,0,[],"",""],["lafuente_madrid-p0427-02",15,"Gallo de la Magdalena\nYa te lo puedes quitar,\nPorque el gancho de san Pablo\nHa vuelto á resucitar.",210,0,-1,205,"",0,4,"a",21,0,-1,0,427,427,"","",0,"","","",5,0,0,[],"",""],["lafuente_madrid-p0427-03a",15,"Ni san Miguel con la espada,\nNi el gancho con tanta broma,\nLes han de ganar al gallo\nMientras haya una persona.",210,0,-1,205,"",0,4,"oa",-1,0,-1,0,427,427,"","",0,"rm_t4","","",2,0,0,[],"",""],["lafuente_madrid-p0427-03b",15,"Al otro lado del Ebro\nTengo mis amores, madre,\nY á la vírgen del Pilar\nLe pido que me los guarde",210,0,-1,205,"",0,4,"ae",-1,0,-1,0,427,427,"","",0,"rm_t4","","",3,0,0,[],"",""],["lafuente_madrid-p0427-04",15,"En la plaza del Obispo\nHay una piedra redonda\nCon un letrero que dice:\nAquí se pára la ronda.",210,0,-1,205,"",0,4,"oa",182,0,-1,0,427,427,"","",0,"rm_t4","","",2,0,0,[],"",""],["lafuente_madrid-p0428-01",15,"En la plaza de san Pedro\nSe crian los ababoles;\nEn la plaza de Santiago\nUnas chicas como soles.",210,0,-1,205,"",0,4,"oe",27,0,-1,0,428,428,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0428-02",15,"Zaragoza, Burgo y Fuentes,\nQuinto, la Zayda y Samper,\nAlcañiz y Valdealgorfa:\n¿Cuándo os volveré á ver?",210,0,-1,205,"",0,4,"e",20,0,-1,0,428,428,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0428-03",15,"Santa Ana está en el Pozuelo,\nSan Severino en Ainzon,\nLos capuchinos en Borja,\nLa cruz en Fuendejalon.",210,0,-1,205,"",0,4,"ao",-1,0,-1,0,428,428,"","",0,"rm_t4","","",2,0,0,[],"",""],["lafuente_madrid-p0428-04",15,"Aunque me gusta Alcañiz\nPor su calle de Vicente,\nPrefiero á Castelserás\nPor su placica del Puente.",210,0,-1,205,"",0,4,"ee",15,0,-1,0,428,428,"","",0,"rm_t4","","",2,0,0,[],"",""],["lafuente_madrid-p0428-05",15,"En Calanda venden cócios,\nEn Alcorisa pucheros,\nEn Alcañiz buenas chicas,\nY en Caspe buenos mancebos.",210,0,-1,205,"",0,4,"eo",-1,0,-1,0,428,428,"","",0,"rm_t4","","",2,0,0,[],"",""],["lafuente_madrid-p0429-02",15,"Mucho vale Zaragoza\nCon su Coso y su arrabal;\nPero mas vale Daroca\nCon su hermosa colegial.",210,0,-1,205,"",0,4,"a",1,0,-1,0,429,429,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0429-02-e2",15,"Mucho me quiere Daroca,\nSu puerta baja (2) me llama,\nY sus muchachas hermosas\nMe dicen que no me vaya.",210,0,-1,205,"",0,4,"aa",-1,0,-1,0,429,429,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0429-02-e3",15,"Plaza de la Colegial\nCon tu cárcel y tu cambra,\nEres de Daroca encanto\nY de sus hermosas sala.",210,0,-1,205,"",0,4,"aa",-1,0,-1,0,429,429,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0429-02-e4",15,"Cobertizos de la plaza\nFrente de la colegial,\nPor algo Daroca os puso\nTan cerca el santo hospital.",210,0,-1,205,"",0,4,"a",1,0,-1,0,429,429,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0429-02-e5",15,"Un muro tiene Daroca\nEn que nadie rindió al Jaque;\nÁ mí me rinden tus ojos\nMirándome y sin mirarme.",210,0,-1,205,"",0,4,"ae",-1,0,-1,0,429,429,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0430-01",15,"Solo quiero que te vuelvas\nComo el Mambrú (1) de la fuente,\nSi me dejaras por otro\nCuando tanto sé quererte.",210,0,-1,205,"",0,4,"ee",-1,0,-1,0,430,430,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0430-02",15,"Fuente de los veinte caños\nDonde tanto se murmura:\n¿Has oido si me quiere\nLa sobrinica del cura?",210,0,-1,205,"",0,4,"ua",17,0,-1,0,430,430,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0430-03",15,"Arbolicos de la vega,\nMolinicos del paseo:\nHaced que no me oiga el padre\nDe la niña que yo quiero.",210,0,-1,205,"",0,4,"eo",-1,0,-1,0,430,430,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0430-04",15,"En la plaza de Santiago\nTiene un mercado Daroca,\nY una fuente donde abrasan\nLos corazones sus mozas.",210,0,-1,205,"",0,4,"oa",-1,0,-1,0,430,430,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0430-05",15,"Como aquel hombre de piedra\nQue en la Trinidad está,\nQuiero que te vuelvas tú\nSi no dices la verdad.",210,0,-1,205,"",0,4,"a",-1,0,-1,0,430,430,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0431-01",15,"Fuentes con sus miradores,\nCon sus molinos la Villa,\nNo valen lo que tus ojos\nY tu graciosa sonrisa.",210,0,-1,205,"",0,4,"ia",-1,0,-1,0,431,431,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0431-03",15,"Vega hermosa del Jiloca\nCon tus sombrios nogales\nNo envidies á la del Ebro;\nMas que ella mil veces vales.",210,0,-1,205,"",0,4,"ae",26,0,-1,0,431,431,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0431-04",15,"Anento tiene agua-llueve,\nY laguna Gallocanta,\nDaroca tiene su mina\nY cien muros que la ensalzan.",210,0,-1,205,"",0,4,"aa",-1,0,-1,0,431,431,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0432-01",15,"Muro rajado que miras\nDe escolapios al colegio: (1)\nDí á una rubia de estos barrios\nQue de amor por e la muero.",210,0,-1,205,"",0,4,"eo",-1,0,-1,0,432,432,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0432-01-e2",15,"Muro roto de las Almas\nQue tanta tierra dominas:\nDi á mi niña que la espera\nÁ la entrada de la Mina.",210,0,-1,205,"",0,4,"ia",-1,0,-1,0,432,432,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0432-02a",15,"En Burbáguena hay hermosas,\nEn Báguena bullangueras,\nEn San Martin salerosas,\nEn Daroca retrecheras.",210,0,-1,205,"",1,4,"ea",103,0,-1,0,432,432,"","",0,"rm_t4","","",2,0,0,[],"",""],["lafuente_madrid-p0432-02b",15,"Calatorao tiene un cristo,\nY otro cristo Balaguer;\nDaroca sus corporales,\nY sus amantes, Teruel.",210,0,-1,205,"",0,4,"e",-1,0,-1,0,432,432,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0432-02c",15,"Adios, puente de Tudela,\nPor debajo pasa el Ebro,\nPor encima mis amores\nQue van al humilladero.",210,0,-1,205,"",0,4,"eo",-1,0,-1,0,432,432,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0432-02d",15,"Calle de Predicadores,\nCon santo Domingo hermoso:\nSolo te falta la cruz\nPara ser calle del Coso.",210,0,-1,205,"",0,4,"oo",160,0,-1,0,432,432,"","",0,"rm_t4","","",2,0,0,[],"",""],["lafuente_madrid-p0433-01",15,"No compres leña en Cosuenda,\nNi en Aguaron compres pan,\nNi mujer en Cariñena,\nQue todo te saldrá mal.",210,0,-1,205,"",0,4,"a",-1,0,-1,0,433,433,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0433-02",15,"No te cases, niña, en Córtes,\nNi en Fréscano, ni en Mallen;\nCasate, niña, en Tabuenca,\nQue es lugar de mucha miel.",210,0,-1,205,"",5,4,"e",-1,0,-1,0,433,433,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0433-03",15,"¡Adios, Tortosa famosa,\nRodeada de balcones,\nEn medio una rica fuente,\nEncima un ángel de amores",210,0,-1,205,"",0,4,"oe",-1,0,-1,0,433,433,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0433-04",15,"El cielo de la Navarra\nEstá vestido de azul,\nPor eso las navarritas\nTienen la sal de Jesus.",210,0,-1,205,"",0,4,"u",-1,0,-1,0,433,433,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0433-05",15,"Navarritos son mis ojos,\nNavarritos han de ser,\nHan salido de Navarra\nY á Navarra han de volver",210,0,-1,205,"",0,4,"e",20,0,-1,0,433,433,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0433-06",15,"Madre por una Navarra\nDiera todo cuanto tengo,\nSolo por tener amores\nAl otro lado del Ebro.",210,0,-1,205,"",0,4,"eo",-1,0,-1,0,433,433,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0434-01",15,"Dicen que las andaluzas (1)\nVan derramando la sal,\nNosotras, las catalanas,\nCanela pura, que es más.",210,0,-1,205,"",0,4,"a",-1,0,-1,0,434,434,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0434-02",15,"Para fuentes, Montellano,\nMontellano para sol,\nMontellano para todo\nLo bueno que Dios crió.",210,0,-1,205,"",0,4,"o",-1,0,-1,0,434,434,"","",0,"rm_t4","","",2,0,0,[],"",""],["lafuente_madrid-p0434-03",15,"Las Casas y Seldortun,\nAvellanal y Acabajo,\nForman un ramo de flores\nQue se llama Montellano.",210,0,-1,205,"",0,4,"ao",-1,0,-1,0,434,434,"","",0,"rm_t4","","",2,0,0,[],"",""],["lafuente_madrid-p0434-04",15,"¡Cuánto vale un mozo bueno\nPuesto en una boca-calle\nCon un retaco en la mano:\nPor aquí no pasa nadie.",210,0,-1,206,"",0,4,"ae",-1,0,-1,0,434,434,"","",0,"rm_t4","","",3,0,0,[],"",""],["lafuente_madrid-p0435-01",15,"No le temo á la justicia,\nNi á trabucos, ni á puñales, (1)\nNi á hombres de vara y media,\nNi de dos varas cabales.",210,0,-1,206,"",0,4,"ae",26,0,-1,0,435,435,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0435-02",15,"Si se me ahuma el pescao\nY desenvaino el flamenco,\nCon cuarenta puñalás\nSe va á rematar el cuento.",210,0,-1,206,"",0,4,"eo",-1,0,-1,0,435,435,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0435-03",15,"El cuerpo me huele á plomo\nY el corazon á puñales,\nY la sangre de mis venas\nRabiando porque no sale.",210,0,-1,206,"",0,4,"ae",-1,0,-1,0,435,435,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0435-04",15,"Veinticinco muertes tengo,\nY no cuento los piquillos.....\nQue en una fiesta, bailando,\nMaté una mujer y un niño.",210,0,-1,206,"",0,4,"io",-1,0,-1,0,435,435,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0435-05",15,"Una daga y un puñal\nSon las armas de un valiente;\nUn trabuco, dos pistolas,\nUn caballo, y venga gente.",210,0,-1,206,"",0,4,"ee",15,0,-1,0,435,435,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0435-06",15,"Sanson dicen fué valiente,\nY Oliveros y Roldan:\nÁ todos les diera muerte\nSi pudieran pelear.",210,0,-1,206,"",5,4,"a",-1,0,-1,0,435,435,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0436-01",15,"Yo soy el hombre mas fuerte\nDe cuantos hay en el mundo;\nHe corrido mucha tierra,\nY asi no tiemblo á ninguno.",210,0,-1,206,"",0,4,"uo",-1,0,-1,0,436,436,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0436-02",15,"Ni de dia, ni de noche,\nÁ ningun hombre le temo;\nPorque siempre me acompaña\nUna varita de almendro.",210,0,-1,206,"",0,4,"eo",-1,0,-1,0,436,436,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0436-03",15,"Yo me doy de puñaladas\nCon el hombre mas valiente,\nQue este pellejito mio\nNo ha de servir para aceite.",210,0,-1,206,"",0,4,"ee",-1,0,-1,0,436,436,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0436-04",15,"Yo soy como aquel torito\nQue está en medio de la plaza,\nQue despues que se halla herido\nVa buscando su venganza.",210,0,-1,206,"",0,4,"aa",-1,0,-1,0,436,436,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0436-05",15,"¡Sujétame, que me pierdo!\nComo me llegue á enfadar,\nÁ los hombres rebaneo\nComo rebaneo el pan.",210,0,-1,206,"",0,4,"a",-1,0,-1,0,436,436,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0436-06",15,"Yo fui subiendo y subí\nHasta el último elemento,\nY puse la fama mia\nDonde ninguno la ha puesto.",210,0,-1,206,"",0,4,"eo",-1,0,-1,0,436,436,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0436-07",15,"Todo cuanto quiero alcanzo,\nNo me quejo de mi estrella;\nPorque no intento cosilla\nQue no me salga con ella.",210,0,-1,206,"",0,4,"ea",6,0,-1,0,436,436,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0437-01",15,"Nadie me tosa en el mundo,\nNi me levante la voz;\nYo soy más duro que el bronce\nY más valiente que Dios.",210,0,-1,206,"",0,4,"o",87,0,-1,0,437,437,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0437-02",15,"Salid, mocitos, salid,\nÁ la esquina de la plaza,\nY alli veréis relucir\nLa punta de mi navaja.",210,0,-1,206,"",0,4,"aa",-1,0,-1,0,437,437,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0437-03",15,"Por aquella calle abajo\nTengo que formar un puente\nCon las costillas de un guapo\nY los brazos de un valiente.",210,0,-1,206,"",0,4,"ee",15,0,-1,0,437,437,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0437-04",15,"Ninguno por ser valiente\nEche votos temerarios,\nQue á ningun potro le viene\nLa silla de mi caballo.",210,0,-1,206,"",0,4,"ao",-1,0,-1,0,437,437,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0438-01",15,"El que no quiera morir\nAl tiro de mi pistola,\nMe deje la calle libre,\nQue la necesito toda.",210,0,-1,206,"",0,4,"oa",-1,0,-1,0,438,438,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0438-02",15,"En este pueblo hay un guapo\nQue presume de valiente,\nCon una espada en la mano\nEn una calle sin gente.",210,0,-1,206,"",0,4,"ee",15,0,-1,0,438,438,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0438-03",15,"Por tu calle voy entrando,\nCabellos de emperadora:\nSi tienes los novios guapos,\nDíles que salgan ahora.",210,0,-1,206,"",0,4,"oa",107,0,-1,0,438,438,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0438-04",15,"Un pollito me pitea\nSabiendo que soy el gallo;\nComo la gallina es mia\nPor eso me aguanto y callo.",210,0,-1,206,"",0,4,"ao",102,0,-1,0,438,438,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0438-05",15,"¡Qué penilla será el ver\nLa prenda que un hombre estima\nEn manos de otro gaché,\nPor ser un hombre gallina!",210,0,-1,206,"",0,4,"ia",-1,0,-1,0,438,438,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0438-06",15,"Hombres hay en este mundo\nQue se precian de ser hombres,\nY entre gallos son gallinas,\nY entre gallinas, capones.",210,0,-1,206,"",0,4,"oe",-1,0,-1,0,438,438,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0438-07",15,"No me ande usté con pinturas,\nQue yo pinturas no quiero,\nQue le cortaré la cara\nAl que fuere pinturero.",210,0,-1,206,"",0,4,"eo",38,0,-1,0,438,438,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0439-01",15,"Tengo yo unas tijeritas,\nQue tambien las traigo aquí,\nPara cortarle la lengua\nAl que hablare mal de mí.",210,0,-1,206,"",0,4,"i",23,0,-1,0,439,439,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0439-02",15,"Tira la espada, cobarde,\nY arrástrala por el suelo;\nYa que no mates á nadie,\nAl menos meterás miedo.",210,0,-1,206,"",0,4,"eo",-1,0,-1,0,439,439,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0439-03",15,"¡Á la cama, chavalillos!\nEsta noche no rondais,\nQue esta noche rondo yo\nY no rondan los chavales.",210,0,-1,206,"",5,4,"ae",-1,0,-1,0,439,439,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0439-04",15,"Cuatro chavales venimos\nTodos sin pelo de barba;\nY si hay alguno valiente\nQue salga por la guitarra.",210,0,-1,206,"",0,4,"aa",-1,0,-1,0,439,439,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0440-01",15,"¿De qué te sirve traer\nEl sombrero á lo gachon,\nY la mano en la cintura,\nSi no tienes corazon?",210,0,-1,206,"",0,4,"ao",-1,0,-1,0,440,440,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0440-02",15,"Tengo que pasarme al moro,\nY tengo que renegar,\nY tengo que ser mas malo\nQue Barceló por la mar.",210,0,-1,206,"",0,4,"a",21,0,-1,0,440,440,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0440-03",15,"Aquel lucerito, madre,\nQue va detrás de la luna,\nEs el que á mí me acompaña\nLa noche que voy de tuna.",210,0,-1,206,"",0,4,"ua",56,0,-1,0,440,440,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0440-04",15,"Esta noche, si Dios quiere,\nYo me voy á divertir\nCon licencia del alcalde\nY de la guardia civil.",210,0,-1,206,"",0,4,"i",-1,0,-1,0,440,440,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0440-05",15,"Esta noche voy de tuna\nCon mi capa y mi sombrero,\nY al revolver de una esquina\nPuñalada y tente, perro.",210,0,-1,206,"",0,4,"eo",-1,0,-1,0,440,440,"","",0,"palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0440-06",15,"Esta noche voy de tuna\nCon mi capa y mi zamarra,\nY el que quisiere cané\nQue salga por la guitarra.",210,0,-1,206,"",0,4,"aa",308,0,-1,0,440,440,"","",0,"palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0441-01",15,"Esta noche ha de llover,\nQue esté raso, que esté nublo;\nHan de llover buenos palos\nEn las costillas de alguno.",210,0,-1,206,"",0,4,"uo",-1,0,-1,0,441,441,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0441-02",15,"Compañero canta, canta,\nY no le temas á nadie,\nQue en la punta de mi espada\nTraigo á la Vírgen del Cármen.",210,0,-1,206,"",0,4,"ae",-1,0,-1,0,441,441,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0441-03",15,"Canta, compañero, canta,\nNo temas á los miñones;\nSi no tienes corazon,\nYo tengo corazon doble.",210,0,-1,206,"",0,4,"oe",-1,0,-1,0,441,441,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0441-04",15,"Canta, compañero, canta,\nY no le temas á nadie,\nPorque nunca se han escrito\nValentías de un cobarde.",210,0,-1,206,"",0,4,"ae",-1,0,-1,0,441,441,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0441-05",15,"El mozo que está cantando\nNo tiene pelo de barba;\nPero si se ofrece un lance\nTiene pelos en el alma.",210,0,-1,206,"",0,4,"aa",-1,0,-1,0,441,441,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0441-06",15,"Corre, que viene la ronda,\nY comienza el tiroteo;\nYo no lo siento por mí,\nSino por mi compañero.",210,0,-1,206,"",0,4,"eo",-1,0,-1,0,441,441,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0442-01",15,"¿Qué te sirve ser buen mozo\nY llevar trabuco nuevo,\nSi no tienes corazon\nPara darle mecha al fuego?",210,0,-1,206,"",0,4,"eo",-1,0,-1,0,442,442,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0442-02",15,"Diga usté, seo pinturero,\nPrepárese usté á morir,\nPorque tiene mi trabuco\nCuatro balas de fusil.",210,0,-1,206,"",0,4,"i",-1,0,-1,0,442,442,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0442-03",15,"Apúntame bien al pecho,\nMira que si no me das,\nMas chispas te voy á hacer\nQue arenas tiene la mar.",210,0,-1,206,"",0,4,"a",-1,0,-1,0,442,442,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0442-04",15,"Salid, mozos, á rondar,\nLos de la guitarra nueva,\nY veréis qué gusto tienen\nLos palos de avellanera.",210,0,-1,206,"",0,4,"ea",-1,0,-1,0,442,442,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0442-05",15,"En la esquina del Campillo\nMe quisieron dar la muerte;\nEché mano á mi cuchillo\nY corrieron los valientes.",210,0,-1,206,"",0,4,"ee",-1,0,-1,0,442,442,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0442-06",15,"Dígale usté á ese mocito\nQue anda por la callejuela,\nQue si no se quita pronto\nLe he de romper la montera.",210,0,-1,206,"",0,4,"ea",-1,0,-1,0,442,442,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0442-07",15,"En esta calle hay un guapo\nQue dice que ha de beber\nSangre de un amigo mio:\nSalga, y verémos á ver.",210,0,-1,206,"",0,4,"e",20,0,-1,0,442,442,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0443-01",15,"En esta calle se suena\nQue me han de matar de un tiro:\nNunca llueve cuando truena;\nCon esa esperanza vivo.",210,0,-1,206,"",0,4,"io",-1,0,-1,0,443,443,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0443-02",15,"Si Málaga tiene un muelle,\nMi navaja tiene cinco;\nComo te se arrime alguno\nNo le vale san Francisco.",210,0,-1,206,"",0,4,"io",-1,0,-1,0,443,443,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0443-03",15,"En tu reja dice un guapo\nQue me ha de matar de un tire,\nY el guapo me ve en tu reja\nY dice que no me ha visto.",210,0,-1,206,"",5,4,"io",-1,0,-1,0,443,443,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0443-04",15,"Para pasear tu calle\nNo necesito cuchillo,\nPorque el novio que tú tienes\nMe lo meto en el bolsillo.",210,0,-1,206,"",0,4,"io",228,0,-1,0,443,443,"","",0,"palau_cantares","","",8,0,0,[],"",""],["lafuente_madrid-p0443-05",15,"Si quieres hacer fortuna\nQuítate los pantalones,\nY encomiéndate á san Rorre,\nPatron de los maricones.",210,0,-1,206,"",0,4,"oe",-1,0,-1,0,443,443,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0443-06",15,"Aquel que fuere gallina\nAprenda de mis lecciones,\nQue traigo pólvora fina\nPara matar gorriones.",210,0,-1,206,"",1,4,"oe",34,0,-1,0,443,443,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0443-07",15,"Me llamo Félix Pastor,\nSoy capitan de ladrones,\nY á nadie tengo temor\nAunque vengan batallones.",210,0,-1,206,"",1,4,"oe",34,0,-1,0,443,443,"","",0,"rm_t4, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0444-01",15,"Contrabandista es mi padre,\nContrabandista es mi hermano,\nContrabandista ha de ser\nAquel á quien dé mi mano.",210,0,-1,207,"",0,4,"ao",81,0,-1,0,444,444,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0444-02",15,"Los hombres de corazon\nSe aficionan al tabaco;\nPonen su administracion,\nY lo venden sin estanco.",210,0,-1,207,"",0,4,"ao",-1,0,-1,0,444,444,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0444-03",15,"En montando en mi caballo\nNo temo á ningun valiente:\nUn retaco, dos pistolas,\nUn cuchillo, y venga gente.",210,0,-1,207,"",0,4,"ee",15,0,-1,0,444,444,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0444-04",15,"Es mucho lo que me gusta\nUna canana corrida,\nQue aunque falte algun cartucho\nSiempre queda prevenida.",210,0,-1,207,"",0,4,"ia",37,0,-1,0,444,444,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0444-05",15,"A pesar de los miñones,\nContrabandista he de ser;\nY he de vender el tabaco\nÁ la puerta del cuartel.",210,0,-1,207,"",0,4,"e",-1,0,-1,0,444,444,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0445-01",15,"Todos los contrabandistas\nSon hombres de corazon;\nLo cargan en Cataluña,\nLo venden en Aragon.",210,0,-1,207,"",0,4,"ao",31,0,-1,0,445,445,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0445-02",15,"Dicen los contrabandistas\nCuando salen al barranco:\nVámonos de aquí á Bayona\nPor muselina y tábaco.",210,0,-1,207,"",0,4,"ao",-1,0,-1,0,445,445,"","",0,"rm_t4","","",7,0,0,[],"",""],["lafuente_madrid-p0445-03",15,"Dicen los contrabandistas\nCuando salen á la playa:\nDios nos libre de sop'ones,\nCarabineros y guardas.",210,0,-1,207,"",0,4,"aa",-1,0,-1,0,445,445,"","",0,"","","",7,0,0,[],"",""],["lafuente_madrid-p0445-04",15,"Mal haya el contrabandista\nQue á mí me enseñó á fumar,\nQue por un triste cigarro\nMe llevan á Gibraltar.",210,0,-1,207,"",0,4,"a",21,0,-1,0,445,445,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0445-05",15,"-Contrabandista valiente:\n¿Qué tienes que tanto lloras?\n- Se me ha muerto mi caballo,\nYa se acabaron mis glorias.",210,0,-1,207,"",0,4,"oa",-1,0,-1,0,445,445,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0445-06",15,"Mi mujer y mi caballo\nSe me murieron á un tiempo:\n¡Qué mujer, ni qué demonio!\n¡Mi caballo es lo que siento!",210,0,-1,207,"",0,4,"eo",-1,0,-1,0,445,445,"","",0,"carrizo_salta, palau_cantares, isaacs_colombia","","",9,0,0,[],"",""],["lafuente_madrid-p0446-01",15,"Mi caballo me costó\nCiento cincuenta doblones,\nY mi mujer solamente\nDichos y amonestaciones.",210,0,-1,207,"",0,4,"oe",34,0,-1,0,446,446,"","",0,"carrizo_salta, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0446-02",15,"¡Arriba, caballo moro,\nSácame de este barranco!\nQue me viene persiguiendo\nEl del caballito blanco.",210,0,-1,207,"",0,4,"ao",303,0,-1,0,446,446,"","",0,"palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0446-03",15,"¡Arriba, caballo moro,\nSácame de este arenal!\nQue me vienen persiguiendo\nLos del águila imperial.",210,0,-1,207,"",0,4,"a",1,0,-1,0,446,446,"","",0,"palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0446-04",15,"Me metí á contrabandista\nDe tabaco y de aguardiente,\nY me pillaron los guardas:\n¡Ahora sí que sale fuerte!",210,0,-1,207,"",0,4,"ee",-1,0,-1,0,446,446,"","",0,"palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0446-05",15,"Me metí á contrabandista\nPor ver si ganaba algo,\nY he perdido el corazon,\nY tambien el contrabando.",210,0,-1,207,"",0,4,"ao",-1,0,-1,0,446,446,"","",0,"rm_t4, palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0446-06",15,"¿Dónde están los cuerpos buenos\nQue los busco y no los hallo?\nUnos están en presidio,\nLos otros al contrabando.",210,0,-1,207,"",0,4,"ao",-1,0,-1,0,446,446,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0447-01",15,"Ya mataron á Frangollo,\nEl guapo de Encinas Reales,\nEl que venia vendiendo\nTabaco por los lugares.",210,0,-1,207,"",0,4,"ae",-1,0,-1,0,447,447,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0447-02",15,"Á aquel que quiere y no puede\nGozar de su libertad,\nNo es menester que lo entierren;\nQue enterrado en vida está.",210,0,-1,208,"",0,4,"a",-1,0,-1,0,447,447,"","",0,"rm_t4","","",3,0,0,[],"",""],["lafuente_madrid-p0447-03",15,"¿De qué le sirve al cautivo\nTener los grillos de plata\nY las cadenas de oro,\nSi la libertad le falta?",210,0,-1,208,"",0,4,"aa",-1,0,-1,0,447,447,"","",0,"rm_t4, palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0447-04",15,"Maldita sea la cárcel\nY el que la labró de piedra;\nA las doce de la noche\nMe metieron dentro de ella.",210,0,-1,208,"",0,4,"ea",-1,0,-1,0,447,447,"","",0,"rm_t4","","",4,0,0,[],"",""],["lafuente_madrid-p0448-01",15,"Ministriles y alguaciles,\nToda la justicia plena,\nMe vinieron á prender\nEn casa de mi morena.",210,0,-1,208,"",0,4,"ea",59,0,-1,0,448,448,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0448-02",15,"Á las doce de la noche,\nNiña, me llevaron preso,\nY para mayor dolor\nMe ataron con tu pañuelo.",210,0,-1,208,"",0,4,"eo",-1,0,-1,0,448,448,"","",0,"rm_t4, palau_cantares","","",8,0,0,[],"",""],["lafuente_madrid-p0448-03",15,"Salí al patio de la cárcel,\nMiré al cielo, y dí un suspiro:\n¿Dónde está mi libertad\nQue tan pronto la he perdido? ('",210,0,-1,208,"",5,4,"",-1,0,-1,0,448,448,"","",0,"rm_t4","","",3,0,0,[],"",""],["lafuente_madrid-p0448-04",15,"Yo perdí mi libertad,\nLa prenda que mas queria,\nYa no puedo perder más,\nAunque perdiera la vida.",210,0,-1,208,"",0,4,"ia",-1,0,-1,0,448,448,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0448-05",15,"Estaré siempre llorando\nMi triste cautividad,\nHasta que del cielo baje\nMi carta de libertad.",210,0,-1,208,"",0,4,"a",16,0,-1,0,448,448,"","",0,"rm_t4, carrizo_salta, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0448-06",15,"Si hubiera alguno en el mundo\nQue la libertad me diera,\nMe echara un hierro en la cara\nY esclavito suyo fuera.",210,0,-1,208,"",0,4,"ea",44,0,-1,0,448,448,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0449-01",15,"Pulidita carcelera,\nSácame de esta prision;\nTe daré el anillo de oro\nQue me dió el bien de mi amor.",210,0,-1,208,"",0,4,"o",-1,0,-1,0,449,449,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0449-02",15,"El anillo que me diste\nSe lo dí á la carcelera,\nQue me quitase los grillos\nY la libertad me diera.",210,0,-1,208,"",0,4,"ea",44,0,-1,0,449,449,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0449-03",15,"Estas rejas son de bronce\nY estas paredes de piedra,\nMis amigos son de vidrio.....\nPor no quebrarse no llegan.",210,0,-1,208,"",0,4,"ea",-1,0,-1,0,449,449,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0449-04",15,"¡En libertad me querias,\nY ahora, preso, me aborreces!\n¡Desgraciado aquel que vive\nÁ voluntad de los jueces!",210,0,-1,208,"",3,4,"ee",196,0,-1,0,449,449,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0449-05",15,"¡Preso en la cárcel estoy\nAmarrado á una columna,\nY no me vienes á ver,\nCorazon de piedra dura!",210,0,-1,208,"",0,4,"ua",-1,0,-1,0,449,449,"","",0,"palau_cantares, murciano_antiguo","","",9,0,0,[],"",""],["lafuente_madrid-p0449-06",15,"Preso en la cárcel estoy\nY no me vienes á ver:\nDigo que no tienes alma\nNi corazon de mujer.",210,0,-1,208,"",0,4,"e",20,0,-1,0,449,449,"","",0,"","","",9,0,0,[],"",""],["lafuente_madrid-p0450-01",15,"¿Eras tú la que decias\nEn varias conversaciones,\nQue me habias de amparar\nSi me vieras en prisiones?",210,0,-1,208,"",0,4,"oe",34,0,-1,0,450,450,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0450-02",15,"Aunque estoy prisionerillo\nYo tendré mi libertad;\nY esos gustos que has tenido\nTe se han de volver pesar.",210,0,-1,208,"",0,4,"a",-1,0,-1,0,450,450,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0450-03",15,"Yo no siento el estar preso,\nNi en calabozo dormir;\nPero siento las razones\nQue me mandas á decir.",210,0,-1,208,"",0,4,"i",157,0,-1,0,450,450,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0450-04",15,"Á las rejas de la cárcel\nNo me vengas á llorar;\nYa que no me quites penas,\nNo me las vengas á dar.",210,0,-1,208,"",0,4,"a",21,0,-1,0,450,450,"","",0,"palau_cantares, fernan_caballero","","",5,0,0,[],"",""],["lafuente_madrid-p0450-05",15,"El pajarito en la jaula\nSe divierte en el alambre;\nAsí me divierto yo\nEn las rejas de la cárcel.",210,0,-1,208,"",0,4,"ae",-1,0,-1,0,450,450,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0451-01",15,"Cuando la requisa viene\nAl cuarto de mi prision,\nEstá desechando llaves\nDos horitas de reló.",210,0,-1,208,"",0,4,"o",-1,0,-1,0,451,451,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0451-02",15,"¿Quién le llevará la nueva\nÁ la triste de mi madre,\nQue en un calabozo oscuro\nMe están echando la llave?",210,0,-1,208,"",0,4,"ae",-1,0,-1,0,451,451,"","",0,"rm_t4","","",3,0,0,[],"",""],["lafuente_madrid-p0451-03",15,"Ya no tengo en este mundo\nSi no es á la madre mia,\nQue va pidiendo limosna\nPara libertar su vida.",210,0,-1,208,"",0,4,"ia",-1,0,-1,0,451,451,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0451-04",15,"Preso estoy en tierra estraña:\nPor ver á mi madre, diera\nUn dedito de la mano,\nEl que mas falta me hiciera. (1)",210,0,-1,208,"",0,4,"ea",44,0,-1,0,451,451,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0451-05",15,"Si la madrecita mia\nViera lo que estoy pasando,\nCon lágrimas de sus ojos\nLa calle fuera regando.",210,0,-1,208,"",0,4,"ao",33,0,-1,0,451,451,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0451-06",15,"Hablar contigo quisiera\nPara vivir sin cuidado,\nPero ya sabes que estoy\nDe la libertad privado.",210,0,-1,208,"",0,4,"ao",14,0,-1,0,451,451,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0452-01",15,"Ahora sí que estamos bien,\nTú presa y yo prisionero;\nTú con cadena de amor,\nYo con cadena de hierro.",210,0,-1,208,"",0,4,"eo",-1,0,-1,0,452,452,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0452-02",15,"En una torre me encuentro\nCon una cadena atado:\nTodo lo llevo con gusto\nPor tenerte á tí á mi lado.",210,0,-1,208,"",0,4,"ao",14,0,-1,0,452,452,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0452-03",15,"Como el aguardiente claro\nQue sale del alambique,\nYo me voy purificando\nEn esta cárcel de Ubrique.",210,0,-1,208,"",0,4,"ie",311,0,-1,0,452,452,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0452-04",15,"La puerta del calabozo\nLa siento abrir y cerrar;\nÁ voces llamo al llavero,\nPorque quiero confesar.....\nRubita, lo que te quiero.",210,0,-1,208,"",7,5,"eo",38,0,-1,0,452,452,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0452-05",15,"Estoy en un calabozo\nLleno de abominaciones;\nYa me suben, ya me bajan\nÁ tomar declaraciones.",210,0,-1,208,"",0,4,"oe",34,0,-1,0,452,452,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0452-06",15,"Me preguntó el señor juez\nQue de qué me mantenia:\nDe comer y de beber,\nComo se mantiene usía.",210,0,-1,208,"",0,4,"ia",0,0,-1,0,452,452,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0453-01",15,"Si te meten en la cárcel\nY te amarran bien los piés,\nY te pregunta el notario.....\nResponde siempre al revés.",210,0,-1,208,"",0,4,"e",218,0,-1,0,453,453,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0453-02",15,"Si te llevan á la cárcel\nNunca digas la mentira;\nLa verdad por las espaldas,\nY el escribano que escriba.",210,0,-1,208,"",0,4,"ia",-1,0,-1,0,453,453,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0453-03",15,"En la torre de Serranos,\nEn la segunda escalera,\nHay un letrero que dice:\nAquí la verdad se niega.",210,0,-1,208,"",0,4,"ea",-1,0,-1,0,453,453,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0453-04",15,"Centinela, vive alerta,\nQue hay presos que son muy pillos,\nY vigilan mas que tú\nPor si tienes un descuido.",210,0,-1,208,"",0,4,"io",-1,0,-1,0,453,453,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0453-05",15,"Echa grillos, carcelera,\nY aprieta bien los candados,\nQue paguen estos piés mios\nLos malos pasos que han dado",210,0,-1,208,"",0,4,"ao",-1,0,-1,0,453,453,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0453-06",15,"¡Ay cárcel, qué mala eres!\n¡Siempre te maldeciré!\n¡Entré sin pelo de barba,\nY capuchino saldré!",210,0,-1,208,"",0,4,"e",77,0,-1,0,453,453,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0453-07",15,"Maldita sea la cárcel,\nY tambien el carcelillo;\nEl que no lleva cadena\nLleva dos pares de grillos.",210,0,-1,208,"",0,4,"io",-1,0,-1,0,453,453,"","",0,"rm_t4","","",4,0,0,[],"",""],["lafuente_madrid-p0454-01",15,"Veinticinco calobozos\nTiene la cárcel de Utrera;\nVeinticuatro llevo andados,\nY el mas oscuro me queda.",210,0,-1,208,"",0,4,"ea",-1,0,-1,0,454,454,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0454-02",15,"Si el rey de España supiera\nLo que á los presos les pasa,\nDe cárcel en cárcel fuera\nEchándolos á sus casas.",210,0,-1,208,"",0,4,"aa",-1,0,-1,0,454,454,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0454-03",15,"La cárcel es el infierno,\nEl carcelero es el diablo,\nLos jueces los que condenan,\nY ellos son los condenados.",210,0,-1,208,"",0,4,"ao",-1,0,-1,0,454,454,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0454-04",15,"Me metieron en la cárcel\nPor hacer un san Miguel;\nAsí que me echaron fuera\nHice un san Bartolomé.",210,0,-1,208,"",0,4,"e",-1,0,-1,0,454,454,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0454-05",15,"Dos años estuve preso\nEn la cárcel de Antequera,\nY á la calle no salí.....\nHasta que me echaron fuera.",210,0,-1,208,"",0,4,"ea",44,0,-1,0,454,454,"","",0,"rm_t4","","",2,0,0,[],"",""],["lafuente_madrid-p0455-01",15,"Por decirle al señor juez:\nBaje usté, que yo no subo,\nMe metieron en la cárcel\nY me costó quince duros.",210,0,-1,208,"",0,4,"uo",-1,0,-1,0,455,455,"","",0,"rm_t4","","",2,0,0,[],"",""],["lafuente_madrid-p0455-02",15,"Porque dije: ¡viva el lujo!\nMe metieron en la cárcel.\n¡Viva el lujo y quien lo trujo!\nNo faltará quien me saque.",210,0,-1,208,"",0,4,"ae",-1,0,-1,0,455,455,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0455-03",15,"Porque le dije á una niña:\n¡Ay lo que te ví, Jesús!\nMe metieron en la cárcel,\nDonde no viera la luz.",210,0,-1,208,"",0,4,"u",109,0,-1,0,455,455,"","",0,"rm_t4","","",4,0,0,[],"",""],["lafuente_madrid-p0455-04",15,"Otras veces los gitanos\nGastaban medias de seda;\nY ahora por su desgracia\nGastan grillos y cadenas.",210,0,-1,208,"",0,4,"ea",-1,0,-1,0,455,455,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0455-05",15,"-Gitano, ¿por qué vas preso?\n-Señor, por cosa ninguna.\nPorque he cogido un ramal\nY detrás vino una mula.",210,0,-1,208,"",0,4,"ua",-1,0,-1,0,455,455,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0455-06",15,"Caminito de Antequera\nPreso llevan á un gitano,\nPorque se encontró una capa\nAntes de perderla el amo.",210,0,-1,208,"",0,4,"ao",-1,0,-1,0,455,455,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0456-01",15,"Preso en la cárcel estoy,\nNo tengas pena por eso;\nNo dejo de ser quien soy,\nNi yo soy el primer preso.",210,0,-1,208,"",1,4,"eo",48,0,-1,0,456,456,"","",0,"palau_cantares","","",9,0,0,[],"",""],["lafuente_madrid-p0456-02",15,"Tres fincas tengo en Madrid\nSiendo un pobre militar:\nLa cárcel, el cementerio,\nY tambien el hospital.",210,0,-1,208,"",0,4,"a",-1,0,-1,0,456,456,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0456-03",15,"Mi madre me lo decia,\nQue me tenia que ver\nEn la cárcel de Almería\nPreso por una mujer.",210,0,-1,208,"",1,4,"e",20,0,-1,0,456,456,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0456-04",15,"Dame la mano y saldré\nDe este oscuro calabozo,\nQue me están acumulando\nUn casamiento forzoso.",210,0,-1,208,"",0,4,"oo",160,0,-1,0,456,456,"","",0,"rm_t4","","",3,0,0,[],"",""],["lafuente_madrid-p0456-05",15,"Cuando yo estaba en prisiones,\nSolito me divertia\nEn contar los eslabones\nQue mi cadena tenia.",210,0,-1,208,"",1,4,"ea",0,0,-1,0,456,456,"","",0,"palau_cantares","","",10,0,0,[],"",""],["lafuente_madrid-p0456-06",15,"Á la cárcel de Motril\nPreso llevan á mi padre,\nSiendo un pobrecito viejo\nQue no se mete con nadie.",210,0,-1,208,"",0,4,"ae",-1,0,-1,0,456,456,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0456-07",15,"Acaban de dar las doce\nEn el reló de la Audiencia;\nEntre jueces y escribanos\nMe han leido la sentencia.",210,0,-1,208,"",0,4,"ea",46,0,-1,0,456,456,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0457-01",15,"Mi causa ya se acabó,\nYa se cerraron mis autos;\nYa ha salido la sentencia\nDe presidio por diez años.",210,0,-1,208,"",0,4,"ao",-1,0,-1,0,457,457,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0457-02",15,"Adios, cárcel de Guadix,\nSepultura de hombres vivos,\nDonde se amansan los guapos\nY se olvidan los amigos.",210,0,-1,208,"",0,4,"io",-1,0,-1,0,457,457,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0457-03",15,"Camino de Cartagena\nMuchos pobrecitos van,\nDesterrados hijos de Eva\nPor las hijitas de Adan.",210,0,-1,208,"",0,4,"a",147,0,-1,0,457,457,"","",0,"rm_t4, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0457-04",15,"Vírgen del portal de Ceuta,\nAmparo de presidiarios,\nAmparadme á mí que vengo\nÁ presidio por diez años.",210,0,-1,208,"",0,4,"ao",-1,0,-1,0,457,457,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0457-05",15,"Ceuta tiene buena entrada,\nPero muy mala salida;\nY aquel que se pasa al moro\nTiene pena de la vida.",210,0,-1,208,"",0,4,"ia",37,0,-1,0,457,457,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0457-06",15,"¡Pobrecitos de la cárcel!\nYa tendrán algun consuelo.\n¡Ay pobrecito de mí!\nNi lo tengo, ni lo espero.",210,0,-1,208,"",0,4,"eo",-1,0,-1,0,457,457,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0458-01",15,"Lo mismo me importa á mi\nComer pan en esta tierra,\nQue comerlo en el presidio\nArrastrando una cadena.",210,0,-1,208,"",0,4,"ea",-1,0,-1,0,458,458,"","",0,"rm_t4","","",2,0,0,[],"",""],["lafuente_madrid-p0458-02",15,"Si Dios me saca con bien\nDe la Alhambra y su gobierno,\nHaré juicio que he salido\nDe los profundos infiernos.",210,0,-1,208,"",0,4,"eo",-1,0,-1,0,458,458,"","",0,"","","",6,0,0,[],"",""],["lafuente_madrid-p0458-03",15,"El que quiera ver penitas\nVaya al campillo de Arenas,\nY verá los presidiarios\nCargaditos de cadenas.",210,0,-1,208,"",0,4,"ea",62,0,-1,0,458,458,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0458-04",15,"Si algun mortal por aquí\nPasa por casualidad,\nSocorra á los infelices\nQue en este desierto están.",210,0,-1,208,"",0,4,"a",-1,0,-1,0,458,458,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0458-05",15,"Para los hombres se han hecho\nLos grillos y las cadenas,\nY para las buenas mozas\nSan Fernando y la Galera.",210,0,-1,208,"",0,4,"ea",-1,0,-1,0,458,458,"","",0,"rm_t4, palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0459-01",15,"Para los hombres se han hecho\nLos grillos y las cadenas,\nCeuta, el Peñon y Melilla,\nChafarinas y Alhucemas.",210,0,-1,208,"",0,4,"ea",-1,0,-1,0,459,459,"","",0,"rm_t4","","",6,0,0,[],"",""],["lafuente_madrid-p0459-02",15,"Soy hombre, vengan fatigas,\nNací para padecer;\nLos grillos y las cadenas\nNo me caben en los piés.",210,0,-1,208,"",0,4,"e",-1,0,-1,0,459,459,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0459-03",15,"Yo me llamo Pepe Cándio,\nQuerío de la Melera;\nSoy un probe presiario\nDel Peñon de la Gomera.",210,0,-1,208,"",0,4,"ea",44,0,-1,0,459,459,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0459-04",15,"Vale más un estudiante\nQue estudia filosofía,\nQue todos los mequetrefes\nQue están en las oficinas.",210,0,-1,209,"",0,4,"ia",-1,0,-1,0,459,459,"","",0,"rm_t4","","",2,0,0,[],"",""],["lafuente_madrid-p0459-05",15,"Un estudiantillo, madre,\nMe dijo si lo queria,\nY yo le dije que no:\n¡Mal haya mi tontería!",210,0,-1,209,"",0,4,"ia",0,0,-1,0,459,459,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0460-01",15,"Yo no sé qué tienen, madre,\nLa sotana y el manteo,\nQue en viendo yo un estudiante\nTodita me zarandeo.",210,0,-1,209,"",0,4,"eo",66,0,-1,0,460,460,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0460-02",15,"Los estudiantes en clase\nSe dicen unos á otros:\nTodas las niñas bonitas\nSe crian para nosotros.",210,0,-1,209,"",0,4,"oo",306,0,-1,0,460,460,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0460-03",15,"Madre, con los estudiantes\nNo me lleve usté á paseo,\nQue como soy chiquitita\nMe tapan con el manteo.",210,0,-1,209,"",0,4,"eo",66,0,-1,0,460,460,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0460-04",15,"La mujer que no ha tenido\nAmor con un estudiante,\nNo sabe lo que es canela,\nNi tampoco chocolate.",210,0,-1,209,"",0,4,"ae",-1,0,-1,0,460,460,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0460-05",15,"-Rosita del mes de mayo,\n¿Quién te ha quitado el color?\n-Un estudiante tunante\nCon palabritas de amor.",210,0,-1,209,"",0,4,"o",72,0,-1,0,460,460,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0460-06",15,"Si en mi libro hubiera damas\nComo las que estoy mirando,\nToda la noche de Dios\nMe la llevara estudiando.",210,0,-1,209,"",0,4,"ao",33,0,-1,0,460,460,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0460-07",15,"Los estudiantillos, madre,\nCuando salen del estudio,\nSe van á los arrabales\nY allí la juegan de puño.",210,0,-1,209,"",0,4,"uo",-1,0,-1,0,460,460,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0461-01",15,"Un estudiante á una niña\nLe estaba dando besitos,\nY su madre les decia:\n¡Miren qué par de angelitos!",210,0,-1,209,"",0,4,"io",254,0,-1,0,461,461,"","",0,"rm_t4, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0461-02",15,"El otro dia en paseo\nSe ha perdido un estudiante,\nY ha venido á parecer\nDebajo de un miriñaque.",210,0,-1,209,"",0,4,"ae",-1,0,-1,0,461,461,"","",0,"rm_t4, fernan_caballero","","",3,0,0,[],"",""],["lafuente_madrid-p0461-03",15,"De una cuchara de palo\nQue tenia un estudiante,\nSe fabricaron las puertas\nDel castillo de Alicante.",210,0,-1,209,"",0,4,"ae",47,0,-1,0,461,461,"","",0,"rm_t4","","",3,0,0,[],"",""],["lafuente_madrid-p0461-04",15,"Cuando un estudiante llega\nÁ la esquina de una plaza,\nDicen las revendedoras:\nFuera ese perro de caza.",210,0,-1,209,"",0,4,"aa",307,0,-1,0,461,461,"","",0,"rm_t4, palau_cantares, fernan_caballero","","",4,0,0,[],"",""],["lafuente_madrid-p0461-05",15,"Estudiante soy tunante\nQue voy corriendo la tuna,\nEngañando á las mujeres,\nSin casarme con ninguna.",210,0,-1,209,"",0,4,"ua",56,0,-1,0,461,461,"","",0,"rm_t4","","",3,0,0,[],"",""],["lafuente_madrid-p0461-06",15,"La capa del estudiante\nParece jardin de flores,\nToda llena de remiendos\nDe diferentes colores.",210,0,-1,209,"",0,4,"oe",5,0,-1,0,461,461,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0461-07",15,"Las armas del estudiante\nYo te diré cuales son:\nLa sotana y el manteo,\nLa cuchara y el perol.",210,0,-1,209,"",0,4,"o",-1,0,-1,0,461,461,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0462-01",15,"Á los estudiantes, niña,\nCompara con las sardinas:\nSaladitas, con escamas,\nPoca carne y mucha espina.",210,0,-1,209,"",0,4,"ia",-1,0,-1,0,462,462,"","",0,"rm_t4, palau_cantares, fernan_caballero","","",4,0,0,[],"",""],["lafuente_madrid-p0462-02",15,"Si quereis saber, señora,\nLa vida del estudiante,\nComer poco y andar mucho,\nLa miseria por delante.",210,0,-1,209,"",0,4,"ae",47,0,-1,0,462,462,"","",0,"fernan_caballero","","",2,0,0,[],"",""],["lafuente_madrid-p0462-03",15,"Caballero generoso,\nDénos usté una peseta,\nQue tenemos la barriga\nComo cañon de escopeta.",210,0,-1,209,"",0,4,"ea",200,0,-1,0,462,462,"","",0,"rm_t4","","",3,0,0,[],"",""],["lafuente_madrid-p0462-04",15,"Á estos pobres estudiantes\nDe cuchara y aceituna,\nDéles usté una peseta,\nQue van corriendo la tuna.",210,0,-1,209,"",0,4,"ua",56,0,-1,0,462,462,"","",0,"rm_t4, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0462-05",15,"Desde que soy estudiante,\nDesde que llevo manteos,\nNo he comido más que sopas\nCon suelas de zapatero.",210,0,-1,209,"",0,4,"eo",-1,0,-1,0,462,462,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0462-06",15,"Es tanta la hambre que tengo,\nQue me apura y me sofoca;\nDesde que soy estudiante\nNo he comido mas que sopas.",210,0,-1,209,"",0,4,"oa",-1,0,-1,0,462,462,"","",0,"rm_t4","","",4,0,0,[],"",""],["lafuente_madrid-p0462-07",15,"Tres meses ha que no como;\nMe tiene abatido el hambre;\nMe pongo en las piernas plomo,\nPorque no me lleve el aire.",210,0,-1,209,"",0,4,"ae",-1,0,-1,0,462,462,"","",0,"carrizo_salta","","",4,0,0,[],"",""],["lafuente_madrid-p0463-01",15,"De la mucha hambre que tengo,\nSantísima Encarnacion,\nTengo las tripas torcidas\nComo cuerdas de violon.",210,0,-1,209,"",0,4,"o",31,0,-1,0,463,463,"","",0,"rm_t4","","",3,0,0,[],"",""],["lafuente_madrid-p0463-03",15,"Es tanta la hambre que tengo,\nQue ahora mismo me comiera\nLos hierros de ese balcon\nY el cuerpo de mi morena.",210,0,-1,209,"",0,4,"ea",-1,0,-1,0,463,463,"","",0,"","","",4,0,0,[],"",""],["lafuente_madrid-p0463-04",15,"Un estudiante tunante\nSe puso á pintar el sol,\nY de hambre que tenia\nPintó un pan de municion.",210,0,-1,209,"",0,4,"o",-1,0,-1,0,463,463,"","",0,"rm_t4, palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0464-01",15,"Primer domingo de abril,\n¡Qué dia tan señalado!\nMetí la mano, y saqué\nEl número de soldado.",210,0,-1,210,"",0,4,"ao",14,0,-1,0,464,464,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0464-02",15,"Adios, padre, y adios, madre,\nAdios, hacienda y dinero;\nMe voy a pagar al rey\nSeis añitos que le debo.",210,0,-1,210,"",0,4,"eo",-1,0,-1,0,464,464,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0464-03",15,"Soldado soy, ¿qué remedio?\nAsí lo quiso mi suerte;\nY no me pesa el fusil,\nPero sí dejar de verte.",210,0,-1,210,"",0,4,"ee",134,0,-1,0,464,464,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0464-04",15,"Los quintos se van mañana,\nSe llevan los escogidos,\nY las muchachas se quedan\nCon los que el rey no ha querido.",210,0,-1,210,"",0,4,"io",-1,0,-1,0,464,464,"","",0,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0465-01",15,"Cállate, morena mia,\nCállate, y no tengas pena,\nQue en siendo yo coronel,\nTú serás la coronela.",210,0,-1,210,"",0,4,"ea",-1,0,-1,0,465,465,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0465-02",15,"Si te preguntan: ¿quién vive?\nResponde con ligereza:\nLos quintos de Pinos-Puente,\nVoluntarios á la fuerza.",210,0,-1,210,"",0,4,"ea",-1,0,-1,0,465,465,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0465-03",15,"Mañana se van los quintos,\nY con ellos va mi Pepe;\nYa no tengo quien me traiga\nHorquillas para el rodete.",210,0,-1,210,"",0,4,"ee",-1,0,-1,0,465,465,"","",0,"rm_t2, palau_cantares","","",10,0,0,[],"",""],["lafuente_madrid-p0465-04",15,"¡Ya se van los quintos, madre,\nPor la puerta de Alcalá;\nYa se van los quintos, madre,\nSabe Dios si volverán!",210,0,-1,210,"",0,4,"a",-1,0,-1,0,465,465,"","",0,"rm_t2, palau_cantares","","",8,0,0,[],"",""],["lafuente_madrid-p0465-05",15,"Ya sabrás que salí quinto\nY no tengo escarapela;\nDame una gota de sangre\nDe tu corazon, morena.",210,0,-1,210,"",0,4,"ea",-1,0,-1,0,465,465,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0465-06",15,"Mañana se van los quintos,\nYa se va mi corazon;\nLa vírgen de los Dolores\nLes eche su bendicion.",210,0,-1,210,"",0,4,"o",31,0,-1,0,465,465,"","",0,"rm_t2, palau_cantares","","",10,0,0,[],"",""],["lafuente_madrid-p0465-07",15,"No siento la escarapela,\nNi tampoco ser soldado;\nLo que siento es mi morena\nQue no la tengo á mi lado.",210,0,-1,210,"",0,4,"ao",14,0,-1,0,465,465,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0466-01",15,"Quien te quiso mozo y libre\nTambien te querrá soldado:\n¿Cómo quieres que desprecie\nLo que el rey no ha despreciado?",210,0,-1,210,"",0,4,"ao",14,0,-1,0,466,466,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0466-02",15,"Mi padre me pega palos\nPorque quiero á un granadero,\nY al son de los palos digo:\n¡Viva la gorra de pelo!",210,0,-1,210,"",0,4,"eo",-1,0,-1,0,466,466,"","",0,"","","",12,0,0,[],"",""],["lafuente_madrid-p0466-03",15,"Soldado tengo de ser\nMientras pueda mascar agua,\nQue no quiero más mujer\nQue el fusil y la canana.",210,0,-1,210,"",0,4,"aa",-1,0,-1,0,466,466,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0466-04",15,"Más vale servir al rey\nY ganar los cuatro cuartos,\nQue no que me pidan pan\nLa mujer y los muchachos.",210,0,-1,210,"",0,4,"ao",-1,0,-1,0,466,466,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0466-05",15,"¡Qué bien parece un soldado\nEn la puerta del cuartel,\nCon el cigarro en la mano,\nAguardando al coronel!",210,0,-1,210,"",0,4,"e",32,0,-1,0,466,466,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0466-06",15,"El que quisiere saber\nDe qué color es la pena,\nSiente plaza de soldado,\nY se ausente de su tierra.",210,0,-1,210,"",0,4,"ea",-1,0,-1,0,466,466,"","",0,"rm_t4, palau_cantares","","",5,0,0,[],"",""],["lafuente_madrid-p0466-07",15,"Senté plaza de soldado\nSolo por no trabajar,\nY ahora me están fastidiando\nCon el paso regular.",210,0,-1,210,"",3,4,"a",21,0,-1,0,466,466,"","",0,"rm_t4, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0467-01",15,"El cuerpo me huele á rancho,\nY los hombros á fusil,\nLas espaldas á morral,\nY el pescuezo á corbatin.",210,0,-1,210,"",0,4,"i",-1,0,-1,0,467,467,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0467-02",15,"Con un pan de municion\nQue el rey de España me da,\nToda la noche me tiene:\n¡Centinela, alerta está!",210,0,-1,210,"",0,4,"a",9,0,-1,0,467,467,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0467-03",15,"Estando de centinela\nEn la garita del campo,\nVinieron á relevarme\nCuatro soldados y un cabo.",210,0,-1,210,"",0,4,"ao",-1,0,-1,0,467,467,"","",0,"rm_t4","","",5,0,0,[],"",""],["lafuente_madrid-p0467-04",15,"Estando de centinela\nEsta mañana en la viña,\nSi no bajo la cabeza,\nUna bala me vendimia.",210,0,-1,210,"",0,4,"ia",-1,0,-1,0,467,467,"","",0,"","","",5,0,0,[],"",""],["lafuente_madrid-p0467-05",15,"Guando estoy de centinela\nY te vienes junto á mí,\nSe me olvida la consigna,\nY se dispara el fusil.",210,0,-1,210,"",0,4,"i",-1,0,-1,0,467,467,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0467-06",15,"Cuatro cuartos me da el rey,\nY con ellos me mantengo,\nLe pago á la lavandera,\nY me quedan tres y medio.",210,0,-1,210,"",0,4,"eo",-1,0,-1,0,467,467,"","",0,"palau_cantares","","",6,0,0,[],"",""],["lafuente_madrid-p0468-01",15,"El pan y los cuatro cuartos\nNunca me podrán faltar\nEn Melilla, en el Peñon,\nÓ en los presidios de Oran.",210,0,-1,210,"",5,4,"oa",-1,0,-1,0,468,468,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0468-02",15,"Ya no me quiere mi cabo,\nMi sargento ni mi alferez,\nPorque soy aficionado\nUn poquillo á las mujeres.",210,0,-1,210,"",0,4,"ee",55,0,-1,0,468,468,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0468-03",15,"Es tanta la fantasía\nDe mi sargento primero,\nQue le pido unos zapatos\nY me da vestido nuevo.",210,0,-1,210,"",0,4,"eo",-1,0,-1,0,468,468,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0468-04",15,"El cuartel es una venta,\nEl sargento es el ventero,\nLos soldados son los burros,\nLos cabos los arrieros.",210,0,-1,210,"",0,4,"eo",-1,0,-1,0,468,468,"","",0,"rm_t4, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0468-05",15,"Los cuarteles son iglesias,\nLos soldados son los santos,\nLos cabos son los faroles\nQue alumbran de cuando en cuando",210,0,-1,210,"",0,4,"ao",-1,0,-1,0,468,468,"","",0,"fernan_caballero","","",3,0,0,[],"",""],["lafuente_madrid-p0468-06",15,"Para borracho, un francés;\nPara ladron, un ventero;\nPara mandar y dar palos,\nUn cabo de escuadra, nuevo.",210,0,-1,210,"",0,4,"eo",-1,0,-1,0,468,468,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0468-07",15,"La vida de los soldados\nEs andar por los lugares,\nDormir en cama prestada,\nMorir en los hospitales.",210,0,-1,210,"",0,4,"ae",-1,0,-1,0,468,468,"","",0,"rm_t4, palau_cantares, fernan_caballero","","",4,0,0,[],"",""],["lafuente_madrid-p0469-01",15,"Soldadito soy del rey,\nAquí traigo mi registro;\nY si muero en la batalla,\nMuero por la fé de Cristo.",210,0,-1,210,"",0,4,"io",-1,0,-1,0,469,469,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0469-02",15,"En la plaza se oyen tiros;\nEn la plaza se ha de entrar::\nPena de la vida tiene\nAquel que se vuelva atrás..",210,0,-1,210,"",0,4,"a",-1,0,-1,0,469,469,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0469-03",15,"Adelante, batidores,\nDad ejemplo al batallon,\nQue la gente de vigote\nDebe ser gente de pró.",210,0,-1,210,"",0,4,"o",-1,0,-1,0,469,469,"","",0,"","","",4,0,0,[],"",""],["lafuente_madrid-p0469-05",15,"Ciento cincuenta cartuchos\nTengo yo en mi cartuchera,\nPara matar las facciones\nQue defienden á Cabrera.",210,0,-1,210,"",0,4,"ea",44,0,-1,0,469,469,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0469-06",15,"Si Dios me saca con bien\nDel servicio militar,\nHaré cuenta que me he muerto\nY he vuelto á resucitar.",210,0,-1,210,"",0,4,"a",21,0,-1,0,469,469,"","",0,"rm_t4, fernan_caballero","","",6,0,0,[],"",""],["lafuente_madrid-p0469-07",15,"Si Dios me deja salir\nDe Cataluña y su reino,\nHaré cuenta que he salido,\nDe los profundos infiernos.",210,0,-1,210,"",0,4,"eo",-1,0,-1,0,469,469,"","",0,"rm_t4","","",2,0,0,[],"",""],["lafuente_madrid-p0470-01",15,"El amor del militar\nEs como un plato de arena,\nEn poniéndolo en la calle,\nViene el viento, y se lo lleva.",210,0,-1,210,"",0,4,"ea",-1,0,-1,0,470,470,"","",0,"palau_cantares, fernan_caballero","","",3,0,0,[],"",""],["lafuente_madrid-p0470-02",15,"Con todos los militares\nPoquita conversacion,\nPorque se van alabando\nDe cositas que no son.",210,0,-1,210,"",0,4,"o",31,0,-1,0,470,470,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0470-03",15,"Un soldado me dió un ramo,\nYo lo recibí con pena,\nQue de manos del soldado\nNunca vino cosa buena.",210,0,-1,210,"",0,4,"ea",59,0,-1,0,470,470,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0470-04",15,"-Isabel, Isabelita,\n¿Qué tienes en tu tejado?\n-Claveles y miraveles,\nY suspiros de un soldado.",210,0,-1,210,"",0,4,"ao",14,0,-1,0,470,470,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0470-05",15,"¿Cómo quieres que te quiera,\nSi no te puedo querer,\nSi no traigo la licencia\nDe mi señor coronel?",210,0,-1,210,"",0,4,"e",-1,0,-1,0,470,470,"","",0,"palau_cantares","","",16,0,0,[],"",""],["lafuente_madrid-p0470-06",15,"Valen más el garbo y talle\nDe mi querida patrona,\nQue todo el oro y la plata\nQue se labra en Barcelona.",210,0,-1,210,"",0,4,"oa",7,0,-1,0,470,470,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0471-01",15,"Dicen que los migueletes\nTienen la vida vendida:\nLa tengan ó no la tengan,\n¡Migueletes de mi vida!",210,0,-1,210,"",0,4,"ia",37,0,-1,0,471,471,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0471-02",15,"No quieras á ese soldado,\nQue es cazador de Madrid,\nY en tomando la licencia\nSe marcha, y te deja aquí.",210,0,-1,210,"",3,4,"i",-1,0,-1,0,471,471,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0471-03",15,"No se admire usté, señora,\nQue un soldado es el que canta;\nCon el pan de municion\nTengo mala la garganta.",210,0,-1,210,"",0,4,"aa",148,0,-1,0,471,471,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0471-04",15,"De las patillas de un moro\nTengo que hacer una escobá,\nPara que barra el cuartel\nLa infantería española.",210,0,-1,210,"",5,4,"oa",-1,0,-1,0,471,471,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0471-05",15,"De las costillas de un moro\nMe atrevo á formar un puente,\nPara que pase la España,\nY su ejército valiente.",210,0,-1,210,"",0,4,"ee",15,0,-1,0,471,471,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0471-06",15,"Al pié de Sierra Bullones\nUna morita decia:\nYa viene la flor de España;\nYa dió fin la morería.",210,0,-1,210,"",0,4,"ia",0,0,-1,0,471,471,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0471-07",15,"¡Centinela, centinela,\nCentinela del Serrallo,\nAlerta, alerta, que vienen\nLos moritos de á caballo!",210,0,-1,210,"",0,4,"ao",102,0,-1,0,471,471,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0472-01",15,"Preso al moro me llevaron;\nY al subir por la escalera,\nVolví la carita á España\nPara despedirme de ella.",210,0,-1,210,"",0,4,"ea",-1,0,-1,0,472,472,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0472-02",15,"¿Quién me compra una chinela\nDel hermano del Sultan,\nQue se le cayó al salir\nHuyendo de Tetuan?",210,0,-1,210,"",5,4,"ea",-1,0,-1,0,472,472,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0472-03",15,"¿De qué le sirve á Marruecos\nTener bombas y cañones,\nSi han perdido á Tetuan,\nDespues de Sierra Bullones?",210,0,-1,210,"",0,4,"oe",34,0,-1,0,472,472,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0472-04",15,"Del dia seis de febrero\nNos tenemos que acordar,\nQue entraron los españoles\nEn la plaza de Tetuan.",210,0,-1,210,"",5,4,"ea",-1,0,-1,0,472,472,"","",0,"rm_t4","","",3,0,0,[],"",""],["lafuente_madrid-p0472-05",15,"Marinero soy, señora,\nEn el gorro llevo el ancla,\nY en perdiéndose el barquillo\nDoy fondo con mi esperanza.",210,0,-1,211,"",0,4,"aa",-1,0,-1,0,472,472,"","",0,"rm_t4, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0473-01",15,"¡Con qué pena vivirá\nLa mujer del marinero,\nQue al pié del palo mayor\nTiene pagado el entierro!",210,0,-1,211,"",0,4,"eo",-1,0,-1,0,473,473,"","",0,"palau_cantares, fernan_caballero","","",4,0,0,[],"",""],["lafuente_madrid-p0473-02",15,"Para los marineritos\nSe crian las buenas mozas;\nPara la gente del campo\nLas calabazas pecosas.",210,0,-1,211,"",0,4,"oa",61,0,-1,0,473,473,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0473-03",15,"Un carpintero me quiere,\nUn sastre me solicita,\nY un marinero ha de ser\nDueño de mi personita..",210,0,-1,211,"",0,4,"ia",50,0,-1,0,473,473,"","",0,"rm_t2, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0473-04",15,"Morenita resalada\nMe llaman los marineros;\nOtra vez que me lo llamen\nMe tengo de ir con ellos.",210,0,-1,211,"",0,4,"eo",-1,0,-1,0,473,473,"","",0,"palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0473-05",15,"Un marinerito, madre,\nMe tiene robada el alma;\nSi no me caso con él,\nMuero moza y llevo palma.",210,0,-1,211,"",0,4,"aa",125,0,-1,0,473,473,"","",0,"rm_t2, palau_cantares, fernan_caballero","","",4,0,0,[],"",""],["lafuente_madrid-p0473-06",15,"Al marinero en el mar\nNunca le falta una pena;\nYa se le rompe el timon,\nÓ se le rifa la vela.",210,0,-1,211,"",0,4,"ea",-1,0,-1,0,473,473,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0473-07",15,"En el cielo está mi Dios,\nEn el mar está mi dicha,\nEn el aire mi esperanza,\nY en tierra quedó mi vida..",210,0,-1,211,"",0,4,"ia",-1,0,-1,0,473,473,"","",0,"rm_t4","","",3,0,0,[],"",""],["lafuente_madrid-p0474-01",15,"Marinero es el que canta,\nMarinero es el que toca,\nMarinerito ha de ser\nAquel que bese mi boca.",210,0,-1,211,"",0,4,"oa",178,0,-1,0,474,474,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0474-02",15,"Hermosa virgen de Gádor\nQue estás al pié de la sierra,\nRuega por los mineritos\nQue están debajo de tierra.",210,0,-1,212,"",0,4,"ea",80,0,-1,0,474,474,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0474-03",15,"Valiente ignorante es\nEl que á las minas se va,\nCuando las minas mejores\nSe quedan en el lugar.",210,0,-1,212,"",0,4,"a",-1,0,-1,0,474,474,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0474-04",15,"Los señores de la mina\nNo cesan de preguntar,\nY los mineritos dicen:\nYa va pintando en metal.",210,0,-1,212,"",0,4,"a",-1,0,-1,0,474,474,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0474-05",15,"Guardillon y sal de lobo\nEs la seña del metal,\nY la piedra franciscana\nEs dura de barrenar.",210,0,-1,212,"",0,4,"a",-1,0,-1,0,474,474,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0475-01",15,"En diciendo: gente al torno,\nTodos los mineros tiemblan;\nViendo que se han de poner\nÁ voluntad de una cuerda.",210,0,-1,212,"",0,4,"ea",-1,0,-1,0,475,475,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0475-02",15,"Los torneros son los guapos,\nLos picadores valientes,\nY los pobres de la gavia\nSon los que aprietan los dientes.",210,0,-1,212,"",0,4,"ee",252,0,-1,0,475,475,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0475-03",15,"De capataces de gavia\nEstaba el infierno lleno,\nY en el último rincon\nEstaban los cocineros.",210,0,-1,212,"",0,4,"eo",-1,0,-1,0,475,475,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0475-04",15,"Dáme machota y barrena,\nAguja y atacador,\nCartuchos, pajuela y mecha,\nQue voy á echar un boton.",210,0,-1,212,"",0,4,"o",-1,0,-1,0,475,475,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0476-01",15,"Cuando Jesucristo vino,\nVino por el chaparral;\nVino repartiendo vino....\nPero el vino ¿dónde está?",210,0,-1,213,"",0,4,"a",-1,0,-1,0,476,476,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0476-02",15,"Mi compadre se ahogó\nEn un tinajon de vino.\n¡Compadre del alma mia,\nQuién se ahogara contigo!",210,0,-1,213,"",0,4,"io",-1,0,-1,0,476,476,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0476-03",15,"Bendito sea Noé,\nEl que las viñas plantó,\nPues que de un triste sarmiento\nSale tan dulce licor.",210,0,-1,213,"",0,4,"o",-1,0,-1,0,476,476,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0476-04",15,"Con un vasito de vino,\nY otro vaso de aguardiente,\nY otro vaso de mistela,\nSe pone un hombre caliente.",210,0,-1,213,"",0,4,"ee",15,0,-1,0,476,476,"","",0,"rm_t4","","",2,0,0,[],"",""],["lafuente_madrid-p0476-05",15,"Con esta no canto más,\nPorque me duelen los dientes\nPorque no veo venir\nEl vaso del aguardiente.",210,0,-1,213,"",0,4,"ee",-1,0,-1,0,476,476,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0476-06",15,"María del alma mia,\nMucho te quiero y te estimo,\nLa garganta tengo mala,\nAcláramela con vino.",210,0,-1,213,"",0,4,"io",-1,0,-1,0,476,476,"","",0,"rm_t4","","",6,0,0,[],"",""],["lafuente_madrid-p0477-01",15,"Cuando mi marido viene\nAndando de medio lado,\nÁ Dios me encomiendo entonces;\nSeñal que viene achispado.",210,0,-1,213,"",0,4,"ao",14,0,-1,0,477,477,"","",0,"rm_t4","","",2,0,0,[],"",""],["lafuente_madrid-p0477-02",15,"Lunes y martes, de chispa;\nMiércoles, la están durmiendo;\nJueves, viernes, mala gana,\nY el sábado entra el estruendo.",210,0,-1,213,"",0,4,"eo",52,0,-1,0,477,477,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0477-03",15,"Un borracho se murió\nY dejó en su testamento:\nQue lo enterraran en viña\nPara chupar los sarmientos.",210,0,-1,213,"",0,4,"eo",-1,0,-1,0,477,477,"","",0,"rm_t4, palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0477-04",15,"Madre mia, si me muero,\nEnterradme en la bodega;\nAbridme la sepultura\nAl pié de la cuba nueva.",210,0,-1,213,"",0,4,"ea",-1,0,-1,0,477,477,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0477-05",15,"Cualesquiera beben vino,\nCualesquiera se emborrachan,\nY cualesquiera echan novia,\nY cualesquiera se casan.",210,0,-1,213,"",0,4,"aa",-1,0,-1,0,477,477,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0477-06",15,"¡Jesús, qué borracho estoy!\n¡Que no me puedo tener!\nÉcheme usté otra gotilla\nÁ ver si logro caer.",210,0,-1,213,"",0,4,"e",20,0,-1,0,477,477,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0477-07",15,"La guitarra está borracha,\nY el que la toca tambien,\nY los dos que están bailando\nNo se pueden mantener.",210,0,-1,213,"",0,4,"e",-1,0,-1,0,477,477,"","",0,"","","",3,0,0,[],"",""],["lafuente_madrid-p0478-01",15,"Dicen que el ápio es caliente,\nY el rábano y el pepino,\nY yo digo que es mentira:\nQue más caliente es el vino.",210,0,-1,213,"",3,4,"io",199,0,-1,0,478,478,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0478-02",15,"Me convidas á correr\nPorque tengo los piés malos;\nConvídame á beber vino,\nQue tengo el gaznate sano.",210,0,-1,213,"",0,4,"ao",-1,0,-1,0,478,478,"","",0,"rm_t4, palau_cantares","","",3,0,0,[],"",""],["lafuente_madrid-p0478-03",15,"Esta noche es Noche Buena,\nY mañana Navidad;\nSaca la bota, morena,\nQue me quiero emborrachar.",210,0,-1,213,"",0,4,"a",-1,0,-1,0,478,478,"","",0,"","","",5,0,0,[],"",""],["lafuente_madrid-p0478-04",15,"El aguardiente me gusta,\nY el vino tambien lo bebo;\nPero en llegando al rosoli,\n¡Salero, por tí me muero!",210,0,-1,213,"",0,4,"eo",-1,0,-1,0,478,478,"","",0,"palau_cantares","","",4,0,0,[],"",""],["lafuente_madrid-p0478-05",15,"Echa vino, montañés,\nQue el agua me jace mal;\nMás quiero morir borracho,\nQue oir las ranas cantar.",210,0,-1,213,"",0,4,"a",-1,0,-1,0,478,478,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0478-06",15,"Ya no me quiere mi novia\nPorque bebo mucho vino;\nVaya mi novia con Dios:\nEche usté medio cuartillo",210,0,-1,213,"",0,4,"io",-1,0,-1,0,478,478,"","",0,"rm_t4","","",2,0,0,[],"",""],["lafuente_madrid-p0479-01",15,"De la raiz del olivo (1)\nSalió mi madre gitana;\nY yo, como soy su hijo,\nNací de la misma rama.",210,0,-1,214,"",0,4,"aa",-1,0,-1,0,479,479,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0479-02",15,"Dale, muchacho á la fragua,\nQue yo le daré al martillo,\nPara ganarles el pan\nÁ esos pobres gitanillos.",210,0,-1,214,"",0,4,"io",-1,0,-1,0,479,479,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0479-03",15,"Aunque canto á lo gitano\nNo soy gitanillo, no;\nPero de andar con gitanos\nEl canto se me pegó.",210,0,-1,214,"",0,4,"o",2,0,-1,0,479,479,"","",0,"","","",4,0,0,[],"",""],["lafuente_madrid-p0479-04",15,"Yo me ausenté de mi patria:\n¡Qué dolor de patria mia!\n¿Dónde está el árbol mejor\nQue en la tierra en que se cria?",210,0,-1,214,"",0,4,"a",0,0,-1,0,479,479,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0479-05",15,"Más valiera á un hombre ser\nLadron en Sierra Morena,\nQue no venir á tener\nAmores en tierra ajena.",210,0,-1,214,"",1,4,"ea",59,0,-1,0,479,479,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0480-01",15,"Ventanas de cara al cierzo,\n¡Á cuántos harás penar!\n¡Á unos por haber entrado,\nY á otros por querer entrar!",210,0,-1,214,"",0,4,"a",21,0,-1,0,480,480,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0480-02",15,"No te estiendas, verdolaga,\nArrecógete un poquito,\nQue no es la huerta tan grande,\nNi el hortelano tan rico,",210,0,-1,214,"",0,4,"io",-1,0,-1,0,480,480,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0480-03",15,"La sirena de la mar\nEs una preciosa dama,\nQue por una maldicion\nLa tiene Dios en el agua.",210,0,-1,214,"",0,4,"aa",-1,0,-1,0,480,480,"","",0,"","","",7,0,0,[],"",""],["lafuente_madrid-p0480-04",15,"Todas las flores del año\nLas cautiva el mes de enero;\nEn llegando el mes de mayo\nSalen de su cautiverio.",210,0,-1,214,"",0,4,"eo",-1,0,-1,0,480,480,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0480-05",15,"El sol le dijo á la luna\nQue se fuera á recoger,\nQue á deshora de la noche\nNo andan mujeres de bien.",210,0,-1,214,"",0,4,"e",-1,0,-1,0,480,480,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0480-06",15,"Los pájaros son clarines\nEntre los cañaverales,\nQue le dan los buenos dias\nAl rayo del sol que sale.",210,0,-1,214,"",0,4,"ae",-1,0,-1,0,480,480,"","",0,"","","",4,0,0,[],"",""],["lafuente_madrid-p0480-07",15,"Ya cantan los pajarillos,\nYa viene la primavera,\nYa os podeis alegrar,\nMuchachas de la ribera.",210,0,-1,214,"",0,4,"ea",44,0,-1,0,480,480,"","",0,"","","",2,0,0,[],"",""],["lafuente_madrid-p0481-01",15,"Si yo fuera zahorí\nLos pensamientos calara,\nY supiera el porvenir,\nY en ninguna cosa errara.",210,0,-1,214,"",0,4,"aa",57,0,-1,0,481,481,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0481-02",15,"Mariquita me dió á mí\nAgua en un cántaro nuevo;\nEl cántaro se quebró\nY el agua cayó en el suelo.",210,0,-1,214,"",0,4,"eo",-1,0,-1,0,481,481,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0481-03",15,"Sobre mi gusto, canela;\nSobre mi gusto, azafran;\nSobre mi gusto ha de ser,\nSobre mi gusto será.",210,0,-1,214,"",0,4,"a",-1,0,-1,0,481,481,"","",0,"rm_t2","","",2,0,0,[],"",""],["lafuente_madrid-p0481-04",15,"La Cómoda va delante,\nEl Salero va detrás,\nLos rondines van diciendo:\n¿Quién se quiere pasear?",210,0,-1,214,"",0,4,"a",-1,0,-1,0,481,481,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0481-05",15,"Mis amigos son muy buenos,\nYo no digo que son malos;\nCuando me dieron el tiro\nSe fueron y me dejaron.",210,0,-1,214,"",0,4,"ao",-1,0,-1,0,481,481,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0482-01",15,"Caballo que en treinta pasos\nVa á galope, trota y corre,\nMerecia este caballo\nTener la cebada doble.",210,0,-1,214,"",0,4,"oe",-1,0,-1,0,482,482,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0482-02",15,"Para cantar quiere gana,\nPara bailar quiere brío,\nPara tocar la guitarra\nQuiere tener buen oido.",210,0,-1,214,"",0,4,"io",-1,0,-1,0,482,482,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0482-03",15,"Las cuerdas de mi vihuela\nYo te diré cuántas son:\nPrima, segunda, tercera,\nCuarta, quinta y el bordon.",210,0,-1,214,"",0,4,"o",31,0,-1,0,482,482,"","",0,"palau_cantares","","",2,0,0,[],"",""],["lafuente_madrid-p0482-04",15,"Mañana me voy á Cádiz\nCon mi hermana Mariquita,\nÁ que me compre un vestido\nDe la tela mas bonita.",210,0,-1,214,"",0,4,"ia",50,0,-1,0,482,482,"","",0,"","","",5,0,0,[],"",""],["lafuente_madrid-p0482-05",15,"Anoche á la media noche\nEché mi barquillo al mar,\nPensando que era poniente\nY se volvió vendabal.",210,0,-1,214,"",0,4,"a",-1,0,-1,0,482,482,"","",0,"","","",4,0,0,[],"",""],["lafuente_madrid-p0482-06",15,"No me mire usté á la cara,\nQue soy un poco morena;\nMireme usté á la cintura,\nVerá usté cosita buena.",210,0,-1,214,"",0,4,"ea",59,0,-1,0,482,482,"","",0,"","","",1,0,0,[],"",""],["lafuente_madrid-p0482-07",15,"Isabelita me llamo,\nSoy hija de labrador;\nAunque voy y vengo al campo,\nNo le tengo envidia al sol.",210,0,-1,214,"",0,4,"o",-1,0,-1,0,482,482,"","",0,"","","",1,0,0,[],"",""],["malaret_americanismos-00001",16,"Quien ha tomado en la noche\ndemasiado la bebida,\namanece al otro día\nhecho un triste y abombado.",211,1,-1,-1,"ABOMBARSE",5,4,"ao",-1,0,-1,0,1,1,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00002",16,"Al saltar una acequia\ndijo una coja,\nagárrame la pta\nque se me moja.",212,9,-1,-1,"ACEQUIA",6,4,"oa",146,0,-1,0,1,1,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00003",16,"Mi esposa es tan chiquitica\nque, cuando vamos por agua,\nyo la llevo acotejada\nen el canto de la ruana.",213,3,-1,-1,"ACOTEJAR",0,4,"aa",-1,0,-1,0,1,1,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00004",16,"Acotéjate al momento\ncuando no hay na que esperar,\nquien tiene jambre no pone\nplátanos a amarillar.",214,10,-1,-1,"ACOTEJAR",0,4,"a",21,0,-1,0,1,1,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00005",16,"Acotéjalo al principio\nsi algo tiene que arreglar,\nes mejor coser a tiempo\nque tener que remendar.",214,10,-1,-1,"ACOTEJAR",0,4,"a",21,0,-1,0,1,1,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00006",16,"El que se la da de fino\nporque un día comió bizcocho,\npa laborar en el campo\nno es aguají ni sancocho.",214,10,-1,-1,"ACHIRA",0,4,"oo",424,0,-1,0,2,2,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00007",16,"El trapiche pide caña,\nlos jondos piden guarapo,\nla parrilla pide leña\ny el hornero pide ajiaco.",213,3,-1,-1,"AJIACO",0,4,"ao",-1,0,-1,0,2,2,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00008",16,"Allá arriba en aquel alto\nme llamaron a almorzar,\nun ajiaco e papa verde\ny un pollo a medio pelar.",213,3,-1,-1,"AJIACO",0,4,"a",21,0,-1,0,2,2,"","",75,"","","",10,0,0,[],"",""],["malaret_americanismos-00009",16,"Estaba San Juan de Dios\ncomiéndose un alfandoque,\ncon la jeringa en la mano\napuntándole a San Roque.",213,3,-1,-1,"ALFANDOQUE",0,4,"oe",718,0,-1,0,2,2,"","",75,"","","",3,0,0,[],"",""],["malaret_americanismos-00010",16,"Para qué quiero muchila\ncon tantos amarradijos?\nNo quiero mujer soltera,\nsoltera y con tantos hijos.",213,3,-1,-1,"AMARRADIJO",0,4,"io",377,0,-1,0,3,3,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00011",16,"Es un hombre muy honrao\nen su trato y en su porte;\nen siendo pa los negocios\nes como el andullo al corte",214,10,-1,-1,"ANDULLO",0,4,"oe",402,0,-1,0,3,3,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00012",16,"El novillo por el cacho,\nel caballo por la arción,\nlaguna que no tiene agua\nno la visita gorzón.",213,3,-1,-1,"AQUERENCIARSE",0,4,"o",31,0,-1,0,4,4,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00013",16,"Las mujeres son el diablo,\nparientes de los diablitos,\nque se rompen las orejas\npa ponerse los aritos.",213,3,-1,-1,"ARITO",0,4,"io",254,0,-1,0,4,4,"","",75,"","","",8,0,0,[],"",""],["malaret_americanismos-00014",16,"Qué lindo este pajarito\ncon sus plumas azulejas.\nSi se mueren las muchachas,\nqué haremos con toas las viejas.",213,3,-1,-1,"AZULEJO",0,4,"ea",496,0,-1,0,5,5,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00015",16,"Remen bien esa tambora,\ntambora de coconuco,\nmi pareja está ganosa\nde una mano de bambuco.",213,3,-1,-1,"BAMBUCO",0,4,"uo",659,0,-1,0,5,5,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00016",16,"Torbellino está muy malo,\nquién sabe de qué accidente,\nen la cabecera tiene\ncacha y media de aguardiente.",213,3,-1,-1,"CACHA",0,4,"ee",-1,0,-1,0,8,8,"","",75,"","","",2,0,0,[],"",""],["malaret_americanismos-00017",16,"A mi Dios le dejo el alma,\nmi cuerpo a la guatecana,\ny al diablo le dejo un cacho\npara que toque la diana.",213,3,-1,-1,"CACHO",0,4,"aa",4,0,-1,0,8,8,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00018",16,"El caballo, por la rienda,\ndel toro, la vuelta al cacho,\nsi son flores, las recojo,\ny si son piedras, me agacho.",213,3,-1,-1,"CACHO",0,4,"ao",310,0,-1,0,8,8,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00019",16,"De la caña sale el dulce;\ndel dulce, las panelitas;\nde las calentanas grandes\nsalen las calentanitas.",213,3,-1,-1,"CALENTANO, NA",0,4,"ia",258,0,-1,0,9,9,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00020",16,"No porque yo sea viejo\nte pongas haciendo cruces,\nsi entoavía tiene juerzas\nño Juan en los caracuces.",211,1,-1,-1,"CARACú",0,4,"ue",194,0,-1,0,10,10,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00022",16,"No te deje engatusar\ny en chisme nunca te metas,\nel que te trujo el mandao\nque le lleve la contesta.",214,10,-1,-1,"CONTESTA",0,4,"ea",-1,0,-1,0,12,12,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00023",16,"Ora es que la paja pica\ny que el gramalote corta,\ncomo no tengo conuco\nno le temo a la langosta.",213,3,-1,-1,"CONUCO",0,4,"oa",-1,0,-1,0,12,12,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00024",16,"Marrana, calla el hocico,\nque el cuchuco va pa allá,\nindio feo, callá la jeta\nque también pa vos habrá.",213,3,-1,-1,"CUCHUCO",0,4,"a",9,0,-1,0,12,12,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00025",16,"El plato e cuchuco, a peso,\ncon cola e marrano, a tres,\ncinco de papitas, ocho,\ny dos de la chicha, diez.",213,3,-1,-1,"CUCHUCO",0,4,"e",150,0,-1,0,12,12,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00026",16,"En la punta de este chaco\ntengo una chiva rosada,\nsaco leche y hago queso\ny entuavía sobra cuajada.",211,1,-1,-1,"CHACO",3,4,"aa",49,0,-1,0,13,13,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00027",16,"Corré, corré, potranquito,\nno te dejes alcanzar,\nporque vienen los vaqueros\ny te van a chalanear.",213,3,-1,-1,"CHALANEAR",0,4,"a",21,0,-1,0,13,13,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00028",16,"Cuando yo estaba chiquito\nme cargaban en los brazos,\ny ahora que ya estoy grande\nme cargan a chicotazos.",213,3,-1,-1,"CHICOTE",0,4,"ao",132,0,-1,0,15,15,"","",75,"","","",2,0,0,[],"",""],["malaret_americanismos-00028-e2",16,"Un indio topó en la plaza\nun chicote de tabaco\ny se vino echando jumo\nque ni todo un gran cachaco.",213,3,-1,-1,"CHICOTE",0,4,"ao",423,0,-1,0,15,15,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00029",16,"Tate queto, ñor mocito,\nno me toque mi chircate,\nporque mi niño es celoso\ny es resgoso que me mate.",213,3,-1,-1,"CHIRCATE",0,4,"ae",384,0,-1,0,16,16,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00030",16,"Aunque mi mama regañe\ny me rompa mi chircate,\nyo no dejo de bailar\nel torbellino a lo guate.",215,11,-1,-1,"CHIRCATE",0,4,"ae",384,0,-1,0,16,16,"","",75,"","","",2,0,0,[],"",""],["malaret_americanismos-00031",16,"Si un amigo te quitare\nla novia que tanto quieres,\nquema raíz de curare\ny volverán sus quereres.",213,3,-1,-1,"CURARE",1,4,"ee",55,0,-1,0,16,16,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00032",16,"Desde que pagas mi amor\ncon el odio y el desdén\nvoy buscando una dolama\nque me mate de una vez.",216,12,-1,-1,"DOLAMA",0,4,"e",-1,0,-1,0,18,18,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00033",16,"Cuando el pobre anda queriendo,\nviene el rico y me lo embroma,\ny se queda el pobrecito\ncomo avestruz en la loma.",211,1,-1,-1,"EMBROMAR",0,4,"oa",86,0,-1,0,18,18,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00034",16,"Con una lanza en la mano\ny un garrote encabuyao,\nyo soy más bravo que un toro\ny más ágil que un venao.",213,3,-1,-1,"ENCABUYAR",0,4,"ao",98,0,-1,0,19,19,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00035",16,"Margarita, Margarita,\ndel cabello encarrujado,\ndale un besito a tu amante,\nquítale lo enamorado.",213,3,-1,-1,"ENCARRUJAR",0,4,"ao",14,0,-1,0,19,19,"","",75,"frenk_t1","","",4,0,0,[],"",""],["malaret_americanismos-00036",16,"Por este llanu a lo largo,\njuyendo a los terronales,\na las niguas se les debe\nque enchueque los carcañales.",213,3,-1,-1,"ENCHUECAR",0,4,"ae",26,0,-1,0,19,19,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00037",16,"Enredista, bochinchosa,\nrevoltosa, tracalera,\nsólo vas de casa en casa\naveriguando vida ajena.",217,5,-1,-1,"ENREDISTA",0,4,"ea",-1,0,-1,0,19,19,"","",75,"","","",2,0,0,[],"",""],["malaret_americanismos-00038",16,"El trapiche muele caña,\nel jondo cocina miel,\nnosotros, a lo bobito,\nnos vamos queriendo bien.",213,3,-1,-1,"FONDO",0,4,"e",-1,0,-1,0,20,20,"","",75,"","","",2,0,0,[],"",""],["malaret_americanismos-00039",16,"El trapiche muele caña,\ny el jondo cocina miel,\nsi vas a vivir con otro,\n¡adiós! que te vaya bien.",213,3,-1,-1,"FONDO",0,4,"e",-1,0,-1,0,20,20,"","",75,"","","",2,0,0,[],"",""],["malaret_americanismos-00041a",16,"Aunque mi mama regañe\ny me rompa el camisón,\nyo no dejo de bailar\ntorbellino y galerón.",214,10,-1,-1,"GALERóN",0,4,"o",31,0,-1,0,20,20,"","",75,"","","",2,0,0,[],"",""],["malaret_americanismos-00041b",16,"Hay que echar siempre pa alante,\nasina cueste trabajo,\npues las gallinas de arriba\nensucian a las de abajo.",214,10,-1,-1,"GALERóN",0,4,"ao",168,0,-1,0,20,20,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00042",16,"Suspiraba un chirlosbirlo\na la orilla de un maizal:\nDios nos libre y nos defienda\ndel terrible gamonal.",213,3,-1,-1,"GAMONAL",0,4,"a",1,0,-1,0,20,20,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00044",16,"Aquí me pongo a cantar\nabajo de aquestos talas\ndel maior guaina del mundo\nlos triunfos y las hazañas.",211,1,-1,-1,"GUAINA",0,4,"aa",-1,0,-1,0,21,21,"","",75,"","","",18,0,0,[],"",""],["malaret_americanismos-00045",16,"Más vale querer a un viejo\nque sabe lo que es amor,\nque no querer a un guainita\nque anda como picaflor.",212,9,-1,-1,"GUAINA",0,4,"o",72,0,-1,0,21,21,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00046",16,"Los foscanos se conocen\nsiá a la carrera o al paso,\nporque llevan su guambía\nterciada debajo el brazo.",213,3,-1,-1,"GUAINA",0,4,"ao",43,0,-1,0,21,21,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00047",16,"Yo tengo un trapiche e palo\nque lo hice en la montaña,\nlo verán echar guarapo\nsin yo meterle la caña.",217,5,-1,-1,"GUARAPO",0,4,"aa",213,0,-1,0,22,22,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00048",16,"Yo jamás tomo tu chicha\nporque la chicha emborracha,\ny eso sienta a la guaricha\npero nunca a la muchacha.",213,3,-1,-1,"GUARICHA",1,4,"aa",556,0,-1,0,22,22,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00049",16,"Avemaría, dijo el diablo\nen la puerta e la cocina;\nmentira, que son guayabas,\nque el diablo no dijo asina.",213,3,-1,-1,"GUAYABA",0,4,"ia",11,0,-1,0,22,22,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00050",16,"Al árbol tras de una loma\nno lo mueve el huracán;\nmis esperanzas, perdidas,\nmis ilusiones, se van.",213,3,-1,-1,"HURACAN",0,4,"a",147,0,-1,0,23,23,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00052",16,"Ya se van los españoles\ncon su bandera amarilla\njuyéndole a cuatro gatos\nque salen de la manigua.",214,10,-1,-1,"MANIGUA",0,4,"ia",-1,0,-1,0,26,26,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00054",16,"No se puede creer en todo\nlo que diga el parejero;\nmanque tu lo veas saltando\nel maco no es maromero.",214,10,-1,-1,"MAROMA",0,4,"eo",38,0,-1,0,26,26,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00055",16,"Yo fuí matrero de ley\ny naides me pudo hallar;\ny únicamente tus ojos\nme llegaron a agarrar.",219,13,-1,-1,"MATRERO, RA",0,4,"a",21,0,-1,0,27,27,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00056",16,"Soy el pájaro matrero\nque hace su nido muy alto;\na la joven que yo quiero,\nla quiero y nunca le falto.",220,2,-1,-1,"MATRERO, RA",1,4,"ao",417,0,-1,0,27,27,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00057",16,"En presencia e la cajera\nmozos y mozas pelean,\ny si no se esconde a tiempo\npus también la mechonean.",213,3,-1,-1,"MECHONEAR",0,4,"ea",390,0,-1,0,27,27,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00058",16,"Mira que te está mirando\nesa niña, que es su esposa;\nmira que te mechonea\nsi no te hace algotra cosa.",213,3,-1,-1,"MECHONEAR",0,4,"oa",63,0,-1,0,27,27,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00059",16,"Una vieja de metida\nse nos quiso entrometer;\nguay, velay, velay, mi vida,\nlo que vale no entender.",211,1,-1,-1,"METIDO, DA",1,4,"e",20,0,-1,0,27,27,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00060",16,"Una negra de mota\nle dijo a su amo:\nque le comprara un gorro\npara el verano.",211,1,-1,-1,"MOTA",6,4,"ao",-1,0,-1,0,28,28,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00061",16,"De la palma soy palmero,\ndel palmiche, palmichero,\nde to las bonitas que hay\nyo soy el que más las quero.",213,3,-1,-1,"PALMICHE",0,4,"eo",38,0,-1,0,29,29,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00062",16,"Yo creya que casarse uno\nera comer quesadilla,\ny ahora las están pagando\nlas pobres de mis costillas.",213,3,-1,-1,"QUESADILLA",3,4,"ia",-1,0,-1,0,32,32,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00063",16,"Silleta sobre silleta,\nsobre silleta un balcón,\nsobre el balcón una niña,\nsobre la niña, una flor.",212,9,-1,-1,"SILLERO",0,4,"o",-1,0,-1,0,34,34,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00064a",16,"Yo te ví mirar pa el monte,\ny ajustarte las chancletas;\ncuando acabe la payada\nhacete humo en un sotreta.",211,1,-1,-1,"SOTRETA",0,4,"ea",-1,0,-1,0,34,34,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00064b",16,"Sí, yo soy linda potranca\npero soy dura de jeta;\ny sépalo, que en mis ancas\nno sube ningún sotreta.",211,1,-1,-1,"SOTRETA",0,4,"ea",200,0,-1,0,34,34,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00065",16,"Esa sí se alcanza a ver,\nesa no se quedó sute,\nde puro gorda provoca\nmatarla para hacer mute.",213,3,-1,-1,"SUTE",0,4,"ue",719,0,-1,0,34,34,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00066",16,"Musiú, déjese de idea,\nmire que yo soy buen taco,\ny si usté se vuelve maco\npuede haber hasta pelea.",214,10,-1,-1,"TACO",11,4,"ea",54,0,-1,0,34,34,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00067",16,"Niña, no escupe pa lo alto\nporque le caye en la cara;\nperro que saca la lengua\nmete la lengua en tapara,\nque el que la saca, la saca,\ny el que no, no saca nada.",213,3,-1,-1,"TAPARA",9,6,"aa",-1,0,-1,0,35,35,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00068",16,"Señor San Joaquín,\ntoca tu violín\nporque el niño llora\npor un volantín.",212,9,-1,-1,"VOLANTíN",0,4,"i",211,0,-1,0,36,36,"","",75,"","","",4,0,0,[],"",""],["malaret_americanismos-00069",16,"Para yapar su acullico,\nque bien escaso venía,\nsaca el hombre de su chuspa\ncontadas, verdes hojillas.",211,1,-1,-1,"YAPAR",0,4,"ia",-1,0,-1,0,36,36,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00070",16,"Hay yuyos que hacen al cuerpo\nsi son bien administrados,\nmejor que las porquerías\nque prepara el boticario.",211,1,-1,-1,"YUYO",0,4,"ao",-1,0,-1,0,37,37,"","",75,"","","",1,0,0,[],"",""],["malaret_americanismos-00071",16,"Dicen que las heladas\nsecan los yuyos,\nasí me voy secando\nde amores tuyos.",211,1,-1,-1,"YUYO",6,4,"uo",495,0,-1,0,37,37,"","",75,"","","",2,0,0,[],"",""],["murciano_antiguo-n0001",17,"Dicen que no nos queremos\nporque no nos ven hablar;\na tu corazón y al mío\nse lo pueden preguntar.",221,0,34,215,"",0,4,"a",21,0,-1,0,67,67,"1","",0,"rm_t2, lafuente_madrid, barcenas_marinera, palau_cantares","","",11,0,0,[],"",""],["murciano_antiguo-n0002",17,"Tus ojos y los míos\nse miran y hablan,\npero los corazones\nno se declaran;\nmas te prevengo\nque si tú no te explicas\nyo no te entiendo.",221,0,34,215,"",4,7,"eo",-1,0,-1,0,67,67,"2","",0,"rm_t2, palau_cantares","","",7,0,0,[],"",""],["murciano_antiguo-n0003",17,"Las mirás y los recaos\nno bastan pa mi querer;\nel agua bebía a morro\nes la que quita la sé.",221,0,34,215,"",0,4,"e",-1,0,-1,0,68,68,"3","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0004",17,"Quisiera que me dijeras\nel pensamiento que tienes,\npor ver si venían bien\ntu gusto y mis pareceres.",221,0,34,215,"",0,4,"ee",-1,0,-1,0,68,68,"4","",0,"","","",3,0,0,[],"",""],["murciano_antiguo-n0005",17,"Tengo vergüenza y lo callo,\ntengo pena y no lo digo;\nyo no sé cómo decirte:\n¿te quieres venir conmigo?",221,0,34,215,"",0,4,"io",106,0,-1,0,68,68,"5","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0006",17,"Tengo vergüenza y me callo\ncuando platico contigo,\ny siempre pienso decirte\n¿te quieres salir conmigo?",221,0,34,215,"",0,4,"io",106,0,-1,0,68,68,"6","",0,"","","",6,0,0,[],"",""],["murciano_antiguo-n0007",17,"Ole con ole con ole,\nserrana, vente conmigo,\nnos comeremos la pava\na la sombra del olivo.",221,0,34,215,"",0,4,"io",-1,0,-1,0,69,69,"7","",0,"","","",7,0,0,[],"",""],["murciano_antiguo-n0008",17,"Sepas que s'han platicao\nnuestros ojos en mirarse;\nlos míos ¿se pué pasar?\ny los tuyos ¡pasa alante!",221,0,34,215,"",0,4,"ae",-1,0,-1,0,69,69,"8","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0009",17,"En el entierro de Cristo\nme miraste y te miré;\ncadenas de amor me echaste,\ncadenas de amor te eché.",221,0,34,215,"",0,4,"e",77,0,-1,0,69,69,"9","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0010",17,"En Cartagena nací,\ndentro del mar me metieron,\ny las olas me sacaron\npara adorarte, ángel bello.",221,0,34,215,"",0,4,"eo",-1,0,-1,0,69,69,"10","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0011",17,"Alábega en tu pecho\nquisiera sembrar,\npara los pajaritos\nque a la vega van.",221,0,34,215,"",0,4,"a",-1,0,-1,0,70,70,"11","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0012",17,"Amores si quisiera\ntengo a manojos,\npero en ti, vida mía,\npuse los ojos.",221,0,34,215,"",6,4,"oo",99,0,-1,0,70,70,"12","",0,"rm_t2","","",2,0,0,[],"",""],["murciano_antiguo-n0013",17,"No sé qué tenía el agua\nque me distes a beber\nque a toas las aborrezco\ny a ti no ha podido ser.",221,0,34,215,"",0,4,"e",20,0,-1,0,70,70,"13","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0014",17,"Dices que me quieres mucho,\nyo te quiero mucho más;\npongámonos en un peso,\nveremos quién pesa más.",221,0,34,215,"",0,4,"a",-1,0,-1,0,70,70,"14","",0,"","","",13,0,0,[],"",""],["murciano_antiguo-n0015",17,"Sólo con verte en tu puerta\nme se encandilan los ojos,\nla boca me se hace yesca\nmirando tu rostro hermoso.",221,0,34,215,"",0,4,"oo",-1,0,-1,0,71,71,"15","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0016",17,"Nos han pasao tantas cosas,\nque al trompezarnos los dos,\ntú te pones colorá\ny yo pierdo la color.",221,0,34,215,"",0,4,"o",-1,0,-1,0,71,71,"16","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0017",17,"Envidia tengo a la tierra,\na las estrellas y al sol,\ny a los ojos hechiceros\nde tu cara, Encarnación.",221,0,34,215,"",0,4,"o",-1,0,-1,0,71,71,"17","",0,"","","",6,0,0,[],"",""],["murciano_antiguo-n0018",17,"Dame un diente de tu boca\nde esos que llevas delante,\nme lo pondré en la pechera\nque me sirva de diamante.",221,0,34,215,"",0,4,"ae",47,0,-1,0,71,71,"18","",0,"","","",5,0,0,[],"",""],["murciano_antiguo-n0019",17,"Te comiera y te bebiera\ny te hiciera un cariñito\ny te rechupeteara\ncomo a niño pequeñito.",221,0,34,215,"",0,4,"io",119,0,-1,0,72,72,"19","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0020",17,"Papelico venturoso,\nquién fuera dentro de ti,\npara darle mil abrazos\nal ángel que te ha de abrir.",221,0,34,215,"",0,4,"i",-1,0,-1,0,72,72,"20","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0021",17,"Soy yo mismo y no me entiendo...\nqué me has de entender tú a mí;\nte digo que no te quiero,\ny estoy muriendo por ti.",221,0,34,215,"",0,4,"i",23,0,-1,0,72,72,"21","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0022",17,"Te voy aborreciendo\ncomo la gallina al trigo,\nel gato a la longaniza\ny los borrachos al vino.",221,0,34,215,"",0,4,"io",-1,0,-1,0,72,72,"22","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0023",17,"Estoy tan separado\nde las mujeres,\ncomo las estampiquias\nde las paredes.",221,0,34,215,"",6,4,"ee",-1,0,-1,0,73,73,"23","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0024",17,"Quisiá tan apartaiquia\nde mí tenerte,\ncomo las estampiquias\nde las paeres.",221,0,34,215,"",6,4,"ee",-1,0,-1,0,73,73,"24","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0025",17,"Voy a misa primera\npor ver mi amor,\ny si allí no lo veo\nvuelvo a la mayor.",221,0,34,215,"",6,4,"o",72,0,-1,0,73,73,"25","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0026",17,"A los cielos se remontan\nlas alas de mi albedrío,\ny mientras dure la pompa,\nte he de querer, dueño mío.",221,0,34,215,"",0,4,"io",3,0,-1,0,73,73,"26","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0027",17,"Te quiero más que a mi vida,\nmás que a mi padre y mi madre,\ny si pecado no fuera,\nmás que a la Virgen del Carmen.",221,0,34,215,"",0,4,"ae",-1,0,-1,0,74,74,"27","",0,"","","",8,0,0,[],"",""],["murciano_antiguo-n0028",17,"La canela está en la Habana,\nla pimienta está en Madrid,\ny la dama que yo adoro\nla tengo al lado de mí.",221,0,34,215,"",0,4,"i",-1,0,-1,0,74,74,"28","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0029",17,"No he visto rosa más guapa\nni clavel más encarnao,\nni moza más de mi gusto\nque la que tengo a mi lao.",221,0,34,215,"",0,4,"ao",98,0,-1,0,74,74,"29","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0030",17,"Las jarras de tu jarrero,\nzagala, quisiá yo ser,\npa besarte yo en la boca\ncuando jueras a beber.",221,0,34,215,"",0,4,"e",20,0,-1,0,74,74,"30","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0031",17,"Te presinas y me ocurre\nquién te pudiera besar,\nande dices \"enemigos\"\nimpués de \"por la señal\".",221,0,34,215,"",0,4,"a",-1,0,-1,0,75,75,"31","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0032",17,"Tengo en el arma dos besos\nque no me ejan sosegar;\nuno que ya me lo distes,\ny otro que te quiero dar.",221,0,34,215,"",0,4,"a",21,0,-1,0,75,75,"32","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0033",17,"Si me quieres dame un beso,\nque me voy a confesar;\nsi er cura lo echa a lo malo,\nya te se degorverá.",221,0,34,215,"",0,4,"a",-1,0,-1,0,75,75,"33","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0034",17,"Le pedí a San Cayetano\ndarte un beso en ca lunar;\n¡así tengas más lunares\nque arenas tiene la mar!",221,0,34,215,"",0,4,"a",21,0,-1,0,75,75,"34","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0035",17,"Poiqu'un beso me diste,\nrabia tu maere;\ntoma otra vez tu beso\npa que no rabie.",221,0,34,215,"",6,4,"ae",-1,0,-1,0,75,75,"35","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0036",17,"En menos que canta un pollo\nme atrevo a darte\nmás besos que pepitas\ntiene un tomate.",221,0,34,215,"",6,4,"ae",-1,0,-1,0,76,76,"36","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0037",17,"Dicen que las Dolores\ntienen espinas;\nya te tengo en el arma,\nno me lastimas:\ny er estribillo:\ntu paere con tu maere\ny tú conmigo.",221,0,34,215,"",4,7,"io",-1,0,-1,0,76,76,"37","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0038",17,"Camino e tu barraca\n¡muleta mía!\nse m'hace cuesta abajo\nla cuesta arriba;\ny cuando sargo\nse m'hace cuesta arriba\nla cuesta abajo.",221,0,34,215,"",4,7,"ao",-1,0,-1,0,76,76,"38","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0039",17,"No te fíes de los hombres,\nde mí el primero;\nmira que te lo digo\nporque te quiero.",221,0,34,215,"",6,4,"eo",38,0,-1,0,76,76,"39","",0,"","","",16,0,0,[],"",""],["murciano_antiguo-n0040",17,"No te fíes de los hombres,\nde mi er primero;\nmira que somos todos\nmuy embusteros.",221,0,34,215,"",6,4,"eo",-1,0,-1,0,77,77,"40","",0,"","","",16,0,0,[],"",""],["murciano_antiguo-n0041",17,"María llevas por nombre,\npor apellido Lucero,\nvale más tu sobrenombre\nque las estrellas del cielo.",221,0,34,215,"",0,4,"eo",-1,0,-1,0,77,77,"41","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0042",17,"En la calle donde vives\ntodos te dicen la perla,\ny yo por engrandecerte\nte digo perla y diamela.",221,0,34,215,"",0,4,"ea",-1,0,-1,0,77,77,"42","",0,"","","",3,0,0,[],"",""],["murciano_antiguo-n0043",17,"Tienes el nombre a mi gusto\ny el apellido también,\nbendito aquel que te puso\nen el bautismo Isabel.",221,0,34,215,"",0,4,"e",-1,0,-1,0,77,77,"43","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0044",17,"Cada vez que voy a verte\nle doy un cuarto al barquero...\nlos amores de mi niña\ntodo me cuesta dinero.",221,0,34,215,"",0,4,"eo",38,0,-1,0,78,78,"44","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0045",17,"Aboa por venir aquí\nl'he pagao un cuarto al barquero;\naún no ha empezao tu querer\ny ya me cuesta dinero.",221,0,34,215,"",3,4,"eo",38,0,-1,0,78,78,"45","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0046",17,"Las barandillas del Puente\nse menean cuando paso;\na ti solica te quiero,\nde las demás no hago caso.",221,0,34,215,"",0,4,"ao",145,0,-1,0,78,78,"46","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0047",17,"Las barandillas der Puente\nse menean cuando pasas;\nsi al hierro le pasa eso\n¡qué le pasará a mi arma!",221,0,34,215,"",0,4,"aa",-1,0,-1,0,79,79,"47","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0048",17,"De las uvas sale er vino,\nde las olivas aceite,\ny de to mi cuerpo sale\ner bustiquio pa quererte.",221,0,34,215,"",0,4,"ee",-1,0,-1,0,79,79,"48","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0049",17,"Si er cielo allega a faltar,\nsin cielo yo no me queo;\ntanimientras vivas tú,\npa qué quiero yo más cielo.",221,0,34,215,"",0,4,"eo",-1,0,-1,0,79,79,"49","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0050",17,"Yo salté la muralla\npor vesitarte,\nesto sólo lo hace\nun fiel amante.",221,0,34,215,"",6,4,"ae",-1,0,-1,0,79,79,"50","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0051",17,"He sartao la muralla\npor vesitarte,\nesto lo hace tan sólo\nun güen amante;\néchame en tierra,\ny patéame el arma\ndista que muera.",221,0,34,215,"",4,7,"ea",-1,0,-1,0,80,80,"51","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0052",17,"Me lo ijiste, Facorra,\njunto a la higuera:\ncomo por ti no quee\npor mí no quea;\nyo respondí\ncomo por ti no quee\nno quea por mí.",221,0,34,215,"",4,7,"i",23,0,-1,0,80,80,"52","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0053",17,"Si mi amor juera e piedra,\njuera e mármol,\ny los picapedreros\nquisián picallo,\nyo haría una ermita\npa que mi Faca juera\na oyir la misa.",221,0,34,215,"",4,7,"ia",-1,0,-1,0,80,80,"53","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0054",17,"Quisiera poderte dar\nlo que merecido tienes,\ny una corona imperial\npara coronar tus sienes.",221,0,34,215,"",0,4,"ee",120,0,-1,0,81,81,"54","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0055",17,"María, si fueras mía,\nte vistiera de oro y plata,\ny te pusiera en el pecho\nuna cruz de Caravaca.",221,0,34,215,"",0,4,"aa",-1,0,-1,0,81,81,"55","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0056",17,"Sabiendo que te gustaba\nel sombrero calañés,\ndomingo por la mañana\nfui a San Pedro y lo compré.",221,0,34,215,"",0,4,"e",-1,0,-1,0,81,81,"56","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0057",17,"El tallito de azadar\nque me distes ayer tarde,\ndentro de mi pecho está:\ntoma tú la llave y abre,\ny allí dentro lo verás.",221,0,34,215,"",7,5,"a",-1,0,-1,0,81,81,"57","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0058",17,"Quisiá yo gorverme pulga,\npa dalle güerta a tu cuerpo;\nsi impués me dabas uñate,\nyo me moriba contento.",221,0,34,215,"",0,4,"eo",-1,0,-1,0,82,82,"58","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0059",17,"¡Quién juera pulga o mosquito\ngrande como una lechuga,\npa darte güenos bocaos\npor la noche en la pechuga!",221,0,34,215,"",0,4,"ua",468,0,-1,0,82,82,"59","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0060",17,"Tienes carita de sí,\nojitos de no negarlo,\nme tienes que dar el sí\nantes que llegue el verano,\ny el verano ya está aquí.",221,0,34,215,"",7,5,"i",23,0,-1,0,82,82,"60","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0061",17,"Quiéreme que tengo capa,\npantalón de paño fino,\nbotonadura de plata\ny chaleco de merino\ny mi camisón con tapa.",221,0,34,215,"",7,5,"aa",-1,0,-1,0,82,82,"61","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0062",17,"Anoche soñaba yo\nque dos moros me pillaban,\ny eran tus hermosos ojos\nque enojados me miraban.",221,0,34,215,"",0,4,"aa",39,0,-1,0,83,83,"62","",0,"","","",9,0,0,[],"",""],["murciano_antiguo-n0063",17,"Anoche tuve un ensueño,\nno sabes lo que soñé,\nque me habías olvidado,\nno sabes lo que lloré.",221,0,34,215,"",0,4,"e",77,0,-1,0,83,83,"63","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0064",17,"¡Anoche soñé un ensueño,\nojalá y juera verdá!\nque te estaba desatando\nla cinta del delantal.",221,0,34,215,"",0,4,"a",-1,0,-1,0,83,83,"64","",0,"","","",7,0,0,[],"",""],["murciano_antiguo-n0065",17,"Asín que llego a tu puerta\nparo, porque no me atrevo,\nni a gorver pasos atrás,\nni a seguir pasos aentro.",221,0,34,215,"",0,4,"eo",-1,0,-1,0,83,83,"65","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0066",17,"Sin ti no puedo vivir,\nhermosa luna brillante,\ndame de tu boca un sí\nque deseo ser tu amante,\ncarita de serafín.",221,0,34,215,"",7,5,"i",-1,0,-1,0,84,84,"66","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0067",17,"Determínate a quererme,\nno me seas temerosa;\nde lo que te sobrevenga\nyo te saco victoriosa.",221,0,34,215,"",0,4,"oa",63,0,-1,0,84,84,"67","",0,"","","",4,0,0,[],"",""],["murciano_antiguo-n0068",17,"Son tus labios dos cortinas\nbordadas de carmesí;\nentre cortina y cortina\nestoy aguardando un sí\nde tu boca peregrina.",221,0,34,215,"",7,5,"ia",11,0,-1,0,84,84,"68","",0,"","","",5,0,0,[],"",""],["murciano_antiguo-n0069",17,"Ni en la Francia ni en la Italia,\nni en Rusia ni en Berbería,\nhay una niña tan guapa\ncomo la murciana mía.",221,0,34,215,"",0,4,"ia",0,0,-1,0,84,84,"69","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0070",17,"Manojito de alfileres\nme parecen tus pestañas;\ny cada vez que me miras\nme los clavas en el alma.",221,0,34,215,"",0,4,"aa",-1,0,-1,0,85,85,"70","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0071",17,"Son tus hermosos ojos\ndos picaportes;\ncada vez que los cierras\nsiento los golpes.",221,0,34,215,"",6,4,"oe",-1,0,-1,0,85,85,"71","",0,"","","",4,0,0,[],"",""],["murciano_antiguo-n0072",17,"Quisiera ser el oro\nde tus zarcillos,\nporque llegan y besan\na tus carrillos.",221,0,34,215,"",6,4,"io",161,0,-1,0,85,85,"72","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0073",17,"Mira cómo corre el agua\npor la raíz del tomate;\nasí corre la hermosura\npor la cara de mi amante.",221,0,34,215,"",0,4,"ae",-1,0,-1,0,86,86,"73","",0,"","","",8,0,0,[],"",""],["murciano_antiguo-n0074",17,"Clavellina, rosa y lirio\nme has parecido al mirarte,\ny ahora me has parecido\ndos perlas en un diamante.",221,0,34,215,"",0,4,"ae",-1,0,-1,0,86,86,"74","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0075",17,"Cómo quieres, lucerito,\nque yo me aparte de tí,\nteniendo contrata hecha\nde quererte hasta morir.",221,0,34,215,"",0,4,"i",-1,0,-1,0,86,86,"75","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0076",17,"Debajo de tus cejas\nse pone oscuro;\nya pueden las campanas\ntocar a nulo.",221,0,34,215,"",6,4,"uo",-1,0,-1,0,86,86,"76","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0077",17,"Amor, si fueras tan firme\ncomo la palma en verano,\nyo te daría las llaves\nde mi pecho soberano.",221,0,34,215,"",0,4,"ao",81,0,-1,0,87,87,"77","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0078",17,"Encima de tu rodete\nestá la luna parada,\ny no la deja correr\nla hermosura de tu cara.",221,0,34,215,"",0,4,"aa",-1,0,-1,0,87,87,"78","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0079",17,"Quién fuera collar de perlas\nde tu hermosa gargantilla,\ny al medio día clavel,\na la noche clavellina,\ny lirio al amanecer.",221,0,34,215,"",7,5,"e",-1,0,-1,0,87,87,"79","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0080",17,"Cuando te veo llorosa\nmi corazón suda a mares;\nno llores, cara de rosa,\nque todo el mundo lo sabe\nque has de ser mi amada esposa.",221,0,34,215,"",7,5,"oa",63,0,-1,0,87,87,"80","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0081",17,"Tienes en la cara pecas,\ny en la garganta lunares,\ny en el pecho más virtudes\nque rosas en los rosales.",221,0,34,215,"",0,4,"ae",-1,0,-1,0,88,88,"81","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0082",17,"Es tu cara un cristal fino,\ntu cabeza una naranja,\ntu pecho un ramo de flores\ndonde mi alma descansa.",221,0,34,215,"",0,4,"aa",-1,0,-1,0,88,88,"82","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0083",17,"María, paloma mía,\nplumaje de mi sombrero,\nmañana es la Candelaria,\nvamos a coger romero.",221,0,34,215,"",0,4,"eo",38,0,-1,0,88,88,"83","",0,"","","",4,0,0,[],"",""],["murciano_antiguo-n0084",17,"Soy más rico siendo pobre\nque Martínez el pañero;\ntengo la novia bonita,\npara qué quiero el dinero.",221,0,34,215,"",0,4,"eo",38,0,-1,0,89,89,"84","",0,"","","",3,0,0,[],"",""],["murciano_antiguo-n0085",17,"Eres el jardín de Venus\nque todas las flores cría;\neres sol y eres lucero,\ny por eso, vida mía,\npor ti peno y por ti muero.",221,0,34,215,"",7,5,"eo",38,0,-1,0,89,89,"85","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0086",17,"Eres la rosa notable,\nla hermosura en ti paró,\neres sol en tu linaje,\ny por eso, blanca flor,\npor ti derramo mi sangre.",221,0,34,215,"",7,5,"ae",-1,0,-1,0,89,89,"86","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0087",17,"Mi novia no tiene pelo,\ncon el tiempo le saldrá;\ny si acaso no le sale,\na mí me gusta pelá.",221,0,34,215,"",0,4,"a",9,0,-1,0,89,89,"87","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0088",17,"Tienes labios de adivina,\nmejillas de soberana,\ntodo mi querer se inclina\nen ti, reina soberana.",221,0,34,215,"",1,4,"aa",-1,0,-1,0,90,90,"88","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0089",17,"Eres la palma gallarda,\nla maere de los parmitos,\ny en los rincones del alma\nme das con los cobollicos.",221,0,34,215,"",0,4,"io",-1,0,-1,0,90,90,"89","",0,"","","",4,0,0,[],"",""],["murciano_antiguo-n0090",17,"Como valiente guerrero\na la montaña subí,\namolando mis aceros\ny siempre pensando en ti,\nhermosísimo lucero.",221,0,34,215,"",7,5,"eo",-1,0,-1,0,90,90,"90","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0091",17,"Encima de tu rodete\nse para y canta un canario,\ny se baja por tu frente\na beber agua en tus labios,\nestrellita reluciente.",221,0,34,215,"",7,5,"ee",15,0,-1,0,91,91,"91","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0092",17,"Cuatro cosas m'henchizan\nen mi morena:\nla cara, los andares,\ner pie y la pierna;\n¡Ole con ole!\nOtras cosiquias tiene\nque son mejores.",221,0,34,215,"",4,7,"oe",-1,0,-1,0,91,91,"92","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0093",17,"El hoyiquio de tu barba\na tanto me compromete,\nque si juera sepoltura\nyo mesmo me diá la muerte.",221,0,34,215,"",0,4,"ee",-1,0,-1,0,91,91,"93","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0095",17,"Cuando te miro, Pepa,\nno quisiá icillo,\nse m'allenan los ojos\nde vesivillos;\n¡Juy! ¡qu'amargura!\ntanto busto pa ejallos\nimpués a escuras.",221,0,34,215,"",4,7,"ua",-1,0,-1,0,92,92,"95","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0096",17,"Las estrellas de los cielos\nvoy esta noche a contar;\nuna y dos... que hay en tus ojos...\ny arriba están las demás.",221,0,34,215,"",0,4,"a",-1,0,-1,0,92,92,"96","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0097",17,"Las estrellas der cielo\nno están cabales;\nque tú tiés en tu cara\nlas prencipales.\nEsto es tan cierto\ncomo el querer no quita\nconocimiento.",221,0,34,215,"",4,7,"eo",-1,0,-1,0,92,92,"97","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0098",17,"Tiés una centuriquia\nque se menea\nigual que los claveles\nque se mimbrean;\ny er estribillo:\ndenguno se m'ocurre,\ndenguno digo.",221,0,34,215,"",4,7,"io",-1,0,-1,0,93,93,"98","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0099",17,"Con la luna de enero\ntiés semejanza,\nqu'es de tuisquias las lunas\nla qu'es más clara;\nYo m'anquivoco,\nel sol paece tu cara,\nla luna es poco.",221,0,34,215,"",4,7,"oo",152,0,-1,0,93,93,"99","",0,"","","",4,0,0,[],"",""],["murciano_antiguo-n0100",17,"Por la mañana eres rosa,\nal medio día clavel,\npor la tarde eres jazmín,\ny lirio al anochecer.",221,0,34,215,"",0,4,"e",-1,0,-1,0,93,93,"100","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0101",17,"Tienes el moño de a libra\ncon rizos de a cuarterón,\ny tienes cuerpo d'anguila\ny el caráuter como er sol.\nY el estribillo:\npa ca chocolatera,\nsu molinillo.",221,0,34,215,"",4,7,"io",228,0,-1,0,93,93,"101","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0102",17,"Dos cosas hay en tu cara\nque m'están gurviendo loco:\nla una es un ojazo negro,\ny la otra cosa... es el otro.",221,0,34,215,"",0,4,"oo",-1,0,-1,0,94,94,"102","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0103",17,"Tienes pecas en la cara\ncomo huevos de perdiz;\nen cada peca, una rosa;\nen medio, una flor de lis.",221,0,34,215,"",0,4,"i",58,0,-1,0,94,94,"103","",0,"","","",4,0,0,[],"",""],["murciano_antiguo-n0104",17,"En el cielo de tu cama\nno dejarás de tener\nalguna clavellinita,\nsiendo tú hermoso clavel.",221,0,34,215,"",0,4,"e",-1,0,-1,0,94,94,"104","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0105",17,"Mi novia es una morena,\npor eso la quiero tanto;\nque la tierra qu'es morena\nse señala por to el campo.",221,0,34,215,"",0,4,"ao",-1,0,-1,0,94,94,"105","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0106",17,"Los ojos de Juensanta\nlloran sardinas,\ny los míos aceite\ncon qué freíllas:\néchame cuatro,\ny pan en las alforjas,\nque voy ar campo.",221,0,34,215,"",4,7,"ao",-1,0,-1,0,95,95,"106","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0107",17,"Aunque vayas y te bañes\na los bañitos de Archena,\nno te se caerá la mancha\nque tienes de pinturera.",221,0,34,215,"",0,4,"ea",-1,0,-1,0,95,95,"107","",0,"","","",3,0,0,[],"",""],["murciano_antiguo-n0108",17,"Una cartagenera\nme dio un pitiquio;\nyo le di una navaja\nde golpeciquio.",221,0,34,215,"",6,4,"io",720,0,-1,0,96,96,"108","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0109",17,"A esta cartagenera\nquisiera yo ver,\nque le di una navaja\ncon el cascabel.",221,0,34,215,"",0,4,"e",-1,0,-1,0,96,96,"109","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0110",17,"Un pajarito de oro\npuesto en la orilla de un tren,\nmira si está remonono;\nmás remonona está usté.",221,0,34,215,"",0,4,"e",-1,0,-1,0,96,96,"110","",0,"","","",3,0,0,[],"",""],["murciano_antiguo-n0111",17,"A bailar han salido\nlos cuatro soles;\nen sus caras les veo\nlos resplandores;\ny er estribillo:\nmemorias a Facorra\ny a su chiquillo.",221,0,34,215,"",4,7,"io",228,0,-1,0,96,96,"111","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0112",17,"¡Como vienes del monte\nvienes airosa,\nvienes coloradita\ncomo una rosa!",221,0,34,215,"",6,4,"oa",63,0,-1,0,97,97,"112","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0113",17,"Eres como la lima\nde la limera:\namarilla por dentro,\nverde por fuera.",221,0,34,215,"",6,4,"ea",44,0,-1,0,97,97,"113","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0114",17,"Eres como la lima\nde la limera:\namarilla por dentro,\nverde por juera;\nmujer y lima,\nescoge er que lo sabe\nla que es más fina.",221,0,34,215,"",4,7,"ia",-1,0,-1,0,97,97,"114","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0115",17,"A San Juan y San Pedro\ncumplen los mozos;\na buscar amor nuevo\nse van mis ojos.",221,0,34,215,"",6,4,"oo",-1,0,-1,0,97,97,"115","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0116",17,"A San Juan y San Pedro\ncumplen los mozos;\na buscar querer nuevo\nse van mis ojos.",221,0,34,215,"",6,4,"oo",-1,0,-1,0,98,98,"116","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0117",17,"Con una caña larga\nse alcanza un jazmín,\ny una buena muchacha\ncon ir y venir.",221,0,34,215,"",0,4,"i",-1,0,-1,0,98,98,"117","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0118",17,"Atame con un cabello\na los bancos de tu cama,\nque aunque el cabello se rompa\nseguro estoy no me vaya.",221,0,34,215,"",0,4,"aa",-1,0,-1,0,98,98,"118","",0,"","","",5,0,0,[],"",""],["murciano_antiguo-n0119",17,"Más quisiá yo, zagala,\ndormir contigo,\nque tener dos orones\nllenos de trigo.\nY alluego impués,\nmás quisiá los orones\nque la mujer.",221,0,34,215,"",4,7,"e",-1,0,-1,0,98,98,"119","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0120",17,"La noche e Santa Teresa\nm'arrejunté con mi novia,\npa si era la fin der mundo,\nestar cerca de la gloria.",221,0,34,215,"",0,4,"oa",-1,0,-1,0,99,99,"120","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0121",17,"La noche e la inundación\nme fi en casa e la que quiero:\nque si era la fin der mundo\nme pillara junto ar cielo.",221,0,34,215,"",0,4,"eo",-1,0,-1,0,99,99,"121","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0122",17,"Dende aquí veo, madre,\nen dónde habita;\naunque no veo al santo\nveo la ermita.",221,0,34,215,"",6,4,"ia",50,0,-1,0,99,99,"122","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0123",17,"Por allí veo, madre,\nlo que bien quiero:\nla carreta, los bueyes\ny el carretero.",221,0,34,215,"",6,4,"eo",38,0,-1,0,99,99,"123","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0124",17,"Por allí viene, maere,\nlo que bien quiero:\nla carreta, los güeyes\ny er carretero;\n¡Ay! maere, ténme,\nque me fartan las juerzas\npa el sustenerme.",221,0,34,215,"",4,7,"ee",-1,0,-1,0,100,100,"124","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0125",17,"Pasa alante que estoy sola,\ny mi maere en er corral;\npasa alante y toma silla,\n¡que tú no me comerás!",221,0,34,215,"",0,4,"a",-1,0,-1,0,100,100,"125","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0126",17,"A San Juan hará un año\nque te quería;\nmás firme estoy ahora\nque el primer día.",221,0,34,215,"",6,4,"ia",0,0,-1,0,100,100,"126","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0127",17,"A San Juan hace un año\nque te queriba;\nmás firme estoy ahora\nque er primer día.\n¡Ay, Pepe, Pepe!\nque en un rincón del arma\nte tengo siempre.",221,0,34,215,"",4,7,"ee",-1,0,-1,0,100,100,"127","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0128",17,"A San Juan hará un año\nque te quería.\nA San Juan hará un año,\nbien de mi vida.",221,0,34,215,"",6,4,"ia",-1,0,-1,0,101,101,"128","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0129",17,"Cuando te veo venir\ncon la manta morellana\nme se pone el corazón\ntierno como una avellana.",221,0,34,215,"",0,4,"aa",4,0,-1,0,101,101,"129","",0,"","","",5,0,0,[],"",""],["murciano_antiguo-n0130",17,"Cuando te veo venir\ncon la manta y la corvilla,\nno lo puedo remediar,\nel cuerpo me hace cosquillas.",221,0,34,215,"",0,4,"ia",-1,0,-1,0,101,101,"130","",0,"","","",5,0,0,[],"",""],["murciano_antiguo-n0131",17,"Cuando te veo devenir\ncon la soga y la corvilla,\nno lo pueo remediar,\nel cuerpo m'hace cosquillas.",221,0,34,215,"",0,4,"ia",-1,0,-1,0,101,101,"131","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0132",17,"Yo no sé qué me da\ncuando te veo venir,\ny te sientas en el poyo,\ngrandísimo galopín.",221,0,34,215,"",0,4,"i",-1,0,-1,0,102,102,"132","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0133",17,"No me mires, no me mires,\nno me mires, mozo güeno;\ntengo el corazón de cera,\ny tu mirar echa juebo.",221,0,34,215,"",0,4,"eo",-1,0,-1,0,102,102,"133","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0134",17,"Debajo de la hoja\ndel verde alimón,\nestá mi amante malo,\n¡Jesús, qué dolor!; (¡Quién juera Dotor!)\n¡Ay! que le ha dao\ncalentura, y con verme\nse l'ha quitao.",221,0,34,215,"",4,7,"ao",98,0,-1,0,102,102,"134","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0135",17,"Tú fuiste mi amor primero,\nla piedra fundamental,\nme enseñastes a querer,\nno me enseñes a olvidar.",221,0,34,215,"",0,4,"a",-1,0,-1,0,103,103,"135","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0136",17,"De San Juan Evangelista\nla palma me he de llevar;\nJuan se llama el bien que adoro,\nJuan ha sido, y Juan será.",221,0,34,215,"",0,4,"a",-1,0,-1,0,103,103,"136","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0137",17,"San Miguel en el cielo\npesa las almas;\nel que la mía pesa\nMiguel se llama.",221,0,34,215,"",6,4,"aa",-1,0,-1,0,103,103,"137","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0138",17,"Por un Pedro doy un cuarto,\npor un Antonio un doblón,\ny por uno de mi gusto\nalma, vida y corazón.",221,0,34,215,"",0,4,"o",31,0,-1,0,104,104,"138","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0139",17,"Un colegial Fulgencio\nme dijo un día\nque con su beca verde\nme taparía;\npues es sabido\nque el colegial Fulgencio\nes muy cumplido.",221,0,34,215,"",4,7,"io",101,0,-1,0,104,104,"139","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0140",17,"Cuándo llegará el día\ny aquella feliz mañana,\nque nos lleven a los dos\nel chocolate a la cama.",221,0,34,215,"",0,4,"aa",-1,0,-1,0,104,104,"140","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0141",17,"Cuándo llegará el día\ny aquella noche feliz\nque te tire de la armilla;\nde la chaqueta tú a mí.",221,0,34,215,"",0,4,"i",-1,0,-1,0,105,105,"141","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0142",17,"Cuándo querrá la Virgen\nde la Fuensanta,\nque tu ropa y la mía\nduerma en un arca.",221,0,34,215,"",6,4,"aa",-1,0,-1,0,105,105,"142","",0,"","","",6,0,0,[],"",""],["murciano_antiguo-n0143",17,"Cuándo querrá la Virgen\nde la Juensanta,\nque tu ropa y la mía\nvayan a un arca;\ntoma tomates,\ntómalos de mi güerto,\npa que los cates.",221,0,34,215,"",4,7,"ae",283,0,-1,0,105,105,"143","",0,"","","",6,0,0,[],"",""],["murciano_antiguo-n0144",17,"Cuándo querrá la Virgen,\ncuándo querrá Dios,\nque del pan que tú comes\ncomamos los dos.",221,0,34,215,"",0,4,"o",87,0,-1,0,105,105,"144","",0,"","","",6,0,0,[],"",""],["murciano_antiguo-n0145",17,"¡Maere mía e la Juensanta!\nte pido por esta salve,\nque no se yele la planta\ny que el novio no me plante.",221,0,34,215,"",0,4,"ae",-1,0,-1,0,106,106,"145","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0146",17,"Mi novia me dice 'nene'\ny yo le digo 'nenica',\ny mi cuñada me dice:\ncásate con mi hermanica.",221,0,34,215,"",0,4,"ia",174,0,-1,0,106,106,"146","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0147",17,"Catalina, flor de harina,\nramillete de abercoques,\nsi te casas con mi hermano\nte daré el burro rabote.",221,0,34,215,"",0,4,"oe",-1,0,-1,0,106,106,"147","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0149",17,"Este verano me caso,\nlo he tomado con empeño,\naunque tenga que vender\nlos tres cochinos que tengo.",221,0,34,215,"",0,4,"eo",-1,0,-1,0,107,107,"149","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0150",17,"A casarse, mociquios,\nno temáis tanto,\nque una vara en la plaza\nvale dos cuartos.",221,0,34,215,"",6,4,"ao",-1,0,-1,0,107,107,"150","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0151",17,"A casarse, mociquios,\nno temáis tanto,\nque una vara en er Puente\ndan por dos cuartos;\ny esto es tan cierto\ncomo el Ave María\ny el Paere Nuestro.",221,0,34,215,"",4,7,"eo",-1,0,-1,0,107,107,"151","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0154",17,"Pequeñica como un huevo\ny ya te quieres casar;\nmás valía que tu madre\nte enseñara a remendar.",221,0,34,215,"",0,4,"a",21,0,-1,0,108,108,"154","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0155",17,"El día que me case\nseré la novia:\ntomaré chocolate\ncomo señora.",221,0,34,215,"",6,4,"oa",-1,0,-1,0,109,109,"155","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0156",17,"Mi padre me pone guardias\ncomo si fuera castillo;\naunque me ponga murallas\nhe de seguir en lo mismo.",221,0,34,215,"",0,4,"io",-1,0,-1,0,109,109,"156","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0157",17,"¡Mi padre me pone guardia\ncomo si yo juá castillo!\nY por más guardias que ponga\nme voy a salir contigo.",221,0,34,215,"",0,4,"io",-1,0,-1,0,109,109,"157","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0158",17,"Es tu madre la que dice\nque no la dejo dormir;\ndentro de su cuarto tiene\nla que no me deja a mí.",221,0,34,215,"",0,4,"i",-1,0,-1,0,110,110,"158","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0159",17,"Tu maere estará diciendo\nque no la ejo dormir;\npos ella tiene a su lao\nla que no m'eja a mí.",221,0,34,215,"",0,4,"i",-1,0,-1,0,110,110,"159","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0160",17,"Ni tu padre ni tu madre,\nni San Antonio bendito,\nme pueden quitar a mí\nel que te quiera un poquito.",221,0,34,215,"",0,4,"io",119,0,-1,0,110,110,"160","",0,"","","",10,0,0,[],"",""],["murciano_antiguo-n0161",17,"Se lo dije a tu madre\npor el postigo;\nel cochino y la burra\nfueron testigos.",221,0,34,215,"",6,4,"io",-1,0,-1,0,110,110,"161","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0162",17,"Se lo ije a tu maere\njunto ar postigo;\nla cochina y la burra\njueron testigos.\nEl estribillo:\nbucharas, bucharones\ny un molinillo.",221,0,34,215,"",4,7,"io",228,0,-1,0,111,111,"162","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0163",17,"Maire, no me eche usté ojicos,\nporque mi gusto ha e ser\ncasarme con Jusepico,\naunque no lo quiera usté.",221,0,34,215,"",0,4,"e",-1,0,-1,0,111,111,"163","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0164",17,"¿De qué le sirve a mi suegra\nmachacar en hierro frío,\nsi me quiera o no me quiera\nme tié que tragar lo mismo?",221,0,34,215,"",0,4,"io",-1,0,-1,0,111,111,"164","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0165",17,"Cuando paso por tu puerta\ncompro pan y voy comiendo,\nporque no diga tu madre\nque de verte me mantengo.",221,0,34,215,"",0,4,"eo",-1,0,-1,0,111,111,"165","",0,"palau_cantares","","",17,0,0,[],"",""],["murciano_antiguo-n0166",17,"Cuando paso por tu senda\ncompro pan y voy comiendo,\npa que tu maere no iga\nque de verte me mantengo.",221,0,34,215,"",0,4,"eo",-1,0,-1,0,112,112,"166","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0167",17,"A mí me llaman 'callando',\ny callar es lo que vale;\ntoa la noche he estao en tu puerta\ny no m'ha sentío tu maere.",221,0,34,215,"",3,4,"ee",-1,0,-1,0,112,112,"167","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0168",17,"Se jué mi maere a misa,\nvino mi novio;\n¡así jueran las misas\nde San Gregorio!",221,0,34,215,"",6,4,"oo",-1,0,-1,0,112,112,"168","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0169",17,"Un claver y una rosa\nestán bailando;\nencarnaiquia es la rosa,\ny el clavel blanco;\nvuelvo la cara,\ny veo que vié tu paere\ncon una vara.",221,0,34,215,"",4,7,"aa",57,0,-1,0,112,112,"169","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0170",17,"Mi paere me pega palos,\nmi maere me crucifica;\nyo ar son de los palos canto,\n¡sarna con gusto no pica!",221,0,34,215,"",0,4,"ia",174,0,-1,0,113,113,"170","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0171",17,"En mi casa me dicen\nque no te quiera,\ncuanto más me lo dicen\nmás t'arrecuerdan.\n¿Sabes qué digo?\nQue si m'aprietan mucho\nme voy contigo.",221,0,34,215,"",4,7,"io",106,0,-1,0,113,113,"171","",0,"","","",11,0,0,[],"",""],["murciano_antiguo-n0172",17,"¿De qué le sirve a tu maere\nechar la llave ar corral?\nSi t'has de salir conmigo\npor la puerta prencipal.",221,0,34,215,"",0,4,"a",1,0,-1,0,114,114,"172","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0173",17,"Tu paere me dio un revés,\ny tu maere un escobazo;\nsi eso m'hacen y me quieres\n¡qu'harán al que no hagas caso!",221,0,34,215,"",0,4,"ao",145,0,-1,0,114,114,"173","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0174",17,"Echale pan ar perro\nsi viés a verme,\npoique tiene mi maere\nsueño de liebre.",221,0,34,215,"",6,4,"ee",-1,0,-1,0,114,114,"174","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0175",17,"Cuando vengas a verme\nven por lo escuro,\npor si mi maere dice;\nya está ahí el burro.",221,0,34,215,"",6,4,"uo",-1,0,-1,0,114,114,"175","",0,"","","",4,0,0,[],"",""],["murciano_antiguo-n0176",17,"Cuando vengas a verme\nven por lo escuro,\nqu'haga juicio mi maere\nqu'eres el burro;\nandar, andiche,\ncon un peaciquio e caña\ns'hace un caliche.",221,0,34,215,"",4,7,"ie",721,0,-1,0,115,115,"176","",0,"","","",4,0,0,[],"",""],["murciano_antiguo-n0177",17,"Benditos los nueve meses\nque tu paere te tuvió\nen er vientre de tu maere\npara casarte con yo.",221,0,34,215,"",0,4,"o",2,0,-1,0,115,115,"177","",0,"","","",3,0,0,[],"",""],["murciano_antiguo-n0178",17,"Manque diga tu maere\nque soy mu bruto,\nno t'arrancan, Facorra,\nde mi volunto;\naupa, aupa,\nno es tu maere pantasma\nqu'a mí me asusta.",221,0,34,215,"",4,7,"ua",-1,0,-1,0,115,115,"178","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0179",17,"Manque en mi casa s'arme\nca día un trimurto,\nno t'arrancan, Facorro,\nde mi volunto;\néchame en tierra\ny patéame el arma\ndista que muera.",221,0,34,215,"",4,7,"ea",-1,0,-1,0,116,116,"179","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0180",17,"María, tú eres la lima,\ny tu paere es el limón,\ny tu madre la naranja;\n¡mira qué comparación!",221,0,34,215,"",0,4,"o",31,0,-1,0,116,116,"180","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0181",17,"Yo no sé por qué cosica\ntu madre no me querrá,\nsiendo yo tan bien nacido\ncomo su hija será.",221,0,34,215,"",0,4,"a",9,0,-1,0,116,116,"181","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0182",17,"Anda diciendo tu madre\nque no me quiere por nuera,\n¿en qué libro habrá leído\nque yo la quiero por suegra?",221,0,34,215,"",0,4,"ea",-1,0,-1,0,117,117,"182","",0,"","","",23,0,0,[],"",""],["murciano_antiguo-n0183",17,"Me han dicho que tu madre\nno me quiere a mí;\nyo tampoco la quiero,\nque te quiero a ti.",221,0,34,215,"",0,4,"i",23,0,-1,0,117,117,"183","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0184",17,"No dirán que no me quiere\nla maere de mi mujer;\nla ciega tanto er cariño\nque no me puede ni ver.",221,0,34,215,"",0,4,"e",20,0,-1,0,117,117,"184","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0185",17,"Si me quieres, dímelo;\ny si no, dame un veneno:\nverás como se lo largo\na mi suegra y a mi suegro.",221,0,34,215,"",0,4,"eo",-1,0,-1,0,117,117,"185","",0,"","","",17,0,0,[],"",""],["murciano_antiguo-n0186",17,"Es mi novia la más curra\nque se pasea en el Barrio;\nsu madre tiene la culpa,\nyo con ella no me hablo.",221,0,34,215,"",0,4,"ao",-1,0,-1,0,118,118,"186","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0187",17,"Tu maere quié pa ti un rey,\ny en la baraja tié cuatro:\nel de oros y el de copas,\nel de espadas y el de bastos.",221,0,34,215,"",0,4,"ao",-1,0,-1,0,118,118,"187","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0188",17,"Tu madre lo quiere rico\ny en el pueblo no lo hay;\nque te monte en un borrico\ny te lleve al Verdolay\ny te dé cuatro bañicos.",221,0,34,215,"",7,5,"io",-1,0,-1,0,119,119,"188","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0189",17,"Si tu maere aspera un rico,\nen la Huerta ya no hay;\nque aparejen er borrico\ny t'alleve al Verdolay,\na darte cuatro bañicos.",221,0,34,215,"",7,5,"io",-1,0,-1,0,119,119,"189","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0190",17,"Si tu madre no me quiere\nno lo puedo remediar;\nme pondré a partir cebolla\ny el zumo me hará llorar.",221,0,34,215,"",0,4,"a",21,0,-1,0,119,119,"190","",0,"","","",5,0,0,[],"",""],["murciano_antiguo-n0191",17,"Mi novia me ha despedido,\nmi suegra me echa a la calle;\neso lo habrán gobernado\nentre la hija y la madre.",221,0,34,215,"",0,4,"ae",-1,0,-1,0,120,120,"191","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0192",17,"Hay muchisma diferiencia\nentre tu paere y un gallo:\ner gallo tie sus dos patas\ny tu paere tiene cuatro.",221,0,34,215,"",3,4,"ao",-1,0,-1,0,120,120,"192","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0193",17,"Icen que ice tu maere\nque eres pequeña entavía,\ny yo también soy pequeño,\nque no allego a la midía;\npero te digo\nque pa olivas gustosas\nlas der cuquillo.",221,0,34,215,"",4,7,"io",-1,0,-1,0,120,120,"193","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0194",17,"Ya se van los quintos, madre,\npor la Puerta de Orihuela,\n¡cuántas madres llorarán!\ny la mía, la primera.",221,0,34,215,"",0,4,"ea",-1,0,-1,0,121,121,"194","",0,"","","",8,0,0,[],"",""],["murciano_antiguo-n0195",17,"A servir al rey me voy\nporque la suerte me allega;\nsi güervo y estás casá,\nleña que paliza llevas.",221,0,34,215,"",0,4,"ea",-1,0,-1,0,121,121,"195","",0,"","","",5,0,0,[],"",""],["murciano_antiguo-n0196",17,"Me quisiste mozo libre,\ntamién me querrás sordao,\nque tú no pués despreciar\nlo que el Rey no ha despreciao.",221,0,34,215,"",0,4,"ao",98,0,-1,0,121,121,"196","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0197",17,"Ojos que te vieron ir\npor aquellos olivares,\n¿cuándo te verán venir\npara alivio de mis males?",221,0,34,215,"",0,4,"ae",-1,0,-1,0,122,122,"197","",0,"","","",12,0,0,[],"",""],["murciano_antiguo-n0198",17,"Ojos que te vieron ir\ncamino de Cartagena,\n¿cuándo te verán gorver\npara alivio de mis penas?",221,0,34,215,"",0,4,"ea",-1,0,-1,0,122,122,"198","",0,"","","",12,0,0,[],"",""],["murciano_antiguo-n0199",17,"Qué ganas tengo de ver\na mi padre y a mi madre,\na mis hermanos del alma,\ny a mi amante más que a nadie.",221,0,34,215,"",0,4,"ae",-1,0,-1,0,122,122,"199","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0200",17,"Estando ausente de ti,\nmuerto te consideraba;\nno hay más gloria para mí\nque el estar viendo tu cara.",221,0,34,215,"",0,4,"aa",-1,0,-1,0,122,122,"200","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0201",17,"Detrás de ti, vida mía,\nmis ojos llorando van,\ncomo soldado a la guerra\ndetrás de su capitán.",221,0,34,215,"",0,4,"a",147,0,-1,0,123,123,"201","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0202",17,"Quisiá que pudiera ser\npor algún arte partirme;\ncon una mitá quearme,\ny con la otra mitá dirme.",221,0,34,215,"",0,4,"ie",184,0,-1,0,123,123,"202","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0203",17,"A América van los hombres\npa traerse un capital;\ny la América está en Murcia\npa el que quiera trebajar.",221,0,34,215,"",0,4,"a",-1,0,-1,0,123,123,"203","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0204",17,"Ni me lavo, ni me peino,\nni me pongo clavellinas,\nmientras no vea venir\na mi amante de las minas.",221,0,34,215,"",0,4,"ia",243,0,-1,0,124,124,"204","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0205",17,"Ni me lavo ni me peino,\nni me pongo clavellinas,\ntanimientras que no venga\naquer que se jue a las minas.",221,0,34,215,"",0,4,"ia",243,0,-1,0,124,124,"205","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0206",17,"No me visto ni me peino,\nni me pongo clavellinas,\nmientras no vea venir\na mi amante de las minas.",221,0,34,215,"",0,4,"ia",243,0,-1,0,125,125,"206","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0207",17,"No tengo ganas de hilar,\nni de darle vuelta al torno,\nni de lavarme las manos,\nmientras no venga mi novio.",221,0,34,215,"",0,4,"oo",-1,0,-1,0,125,125,"207","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0208",17,"Mis amores son del campo\ny no vienen al lugar;\nmis suspiros son correos:\nunos vienen y otros van.",221,0,34,215,"",0,4,"a",-1,0,-1,0,125,125,"208","",0,"rm_t3","","",6,0,0,[],"",""],["murciano_antiguo-n0209",17,"Dices que me quieres mucho,\ny es mentira, que me engañas;\nen un corazón tan chico\nno pueden caber dos almas.",221,0,34,216,"",0,4,"aa",-1,0,-1,0,125,125,"209","",0,"rm_t3, carrizo_salta","","",13,0,0,[],"",""],["murciano_antiguo-n0210",17,"Yo te quería a ti sola\ny tú querías a dos:\ntú querías repicar\ny estar en la procesión.",221,0,34,216,"",0,4,"o",-1,0,-1,0,126,126,"210","",0,"","","",3,0,0,[],"",""],["murciano_antiguo-n0211",17,"Yo tenía una escopeta\ny en ella mis esperanzas;\ntiré un tiro y no salió,\n¡malhaya las que son falsas!",221,0,34,216,"",0,4,"aa",-1,0,-1,0,126,126,"211","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0212",17,"¿Cómo quieres que una luz\nalumbre dos aposentos?\n¡Cómo quieres que yo quiera\ndos corazones a un tiempo!",221,0,34,216,"",0,4,"eo",-1,0,-1,0,126,126,"212","",0,"frenk_t1","","",7,0,0,[],"",""],["murciano_antiguo-n0213",17,"Si me quieres, te advierto\nque sola he de ser,\ncomo reina en la colmena\nque otra no ha de haber.",221,0,34,216,"",0,4,"e",20,0,-1,0,126,126,"213","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0214",17,"Mira bien que lo he jurao,\nno me fartes al querer;\nque si me fartas lo pongo\nen el Diario de Tornel.",221,0,34,216,"",0,4,"e",-1,0,-1,0,127,127,"214","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0215",17,"Si mi corazón tuviera\nventaniquias de cristal,\nde seguro tú lo vieras\nlo dolorío que está.",221,0,34,216,"",0,4,"a",-1,0,-1,0,127,127,"215","",0,"","","",4,0,0,[],"",""],["murciano_antiguo-n0216",17,"Aunque me tiren más balas\nque cañas tiene un cañar,\ntengo de seguir mi rumbo,\npor ver el pago que dan\nlas mujeres en el mundo.",221,0,34,216,"",7,5,"uo",-1,0,-1,0,127,127,"216","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0217",17,"Levántame la chaqueta\ny mírame en el costado,\ny mira por tu querer\nqué puñalada me han dado.",221,0,34,216,"",0,4,"ao",14,0,-1,0,127,127,"217","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0218",17,"Eres hermosa y Dios guarde,\ny a los pies llevas la luna,\nacaba de sentenciarme,\nmira que ha dado la una\ny trato de retirarme.",221,0,34,216,"",7,5,"ae",35,0,-1,0,128,128,"218","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0219",17,"Quisiera ser tu lacayo\ny que me echaras el hierro,\nhermoso clavel de mayo,\npor lo mucho que te quiero.",221,0,34,216,"",0,4,"eo",-1,0,-1,0,128,128,"219","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0220",17,"Con esa cruz de azabache\nque llevas colgada al cuello,\naquí mataron a un hombre,\nparece que vas diciendo.",221,0,34,216,"",0,4,"eo",-1,0,-1,0,128,128,"220","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0221",17,"Pégame una puñalada\nen medio del corazón\ny regístrame la sangre;\nverás si te tengo amor.",221,0,34,216,"",0,4,"o",-1,0,-1,0,128,128,"221","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0222",17,"No me tires, que soy de Elche,\ny tengo el corazón sano;\ntengo unas oliveriquias\nallá arriba en el secano.",221,0,34,216,"",0,4,"ao",81,0,-1,0,129,129,"222","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0223",17,"Me voy a las Herrerías\na hablar con el comisario;\nla noche la vuelvo día\ncuando monto en mi caballo\ny hablo con Ana María.",221,0,34,216,"",7,5,"ia",0,0,-1,0,129,129,"223","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0224",17,"En la calle de Canales\nmi caballo me tiró,\nvaya una moza juncale\nque de mí se adoleció\ncomo si fuera mi madre.",221,0,34,216,"",7,5,"ae",-1,0,-1,0,129,129,"224","",0,"","","",3,0,0,[],"",""],["murciano_antiguo-n0225",17,"Tres puñaladas me han dado\nal lado del corazón,\ny ninguna me ha llegado\na donde tengo mi amor.",221,0,34,216,"",0,4,"o",-1,0,-1,0,130,130,"225","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0226",17,"Madre, madre, que me matan\ny no me puedo valer;\nson dos ojos asesinos\nlos ojos de esa mujer.",221,0,34,216,"",0,4,"e",20,0,-1,0,130,130,"226","",0,"","","",3,0,0,[],"",""],["murciano_antiguo-n0227",17,"Los ojitos de mi cara\ntienen los cristales muertos;\nse han metido en el querer,\nno saben lo que se han hecho.",221,0,34,216,"",0,4,"eo",-1,0,-1,0,130,130,"227","",0,"","","",13,0,0,[],"",""],["murciano_antiguo-n0228",17,"La alfalfa en el río nace,\nde verde se va vistiendo,\npor delante buen semblante,\npor detrás me va vendiendo\nel pícaro de mi amante.",221,0,34,216,"",7,5,"ae",47,0,-1,0,130,130,"228","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0229",17,"De tu ventana a la mía\nme tirastes un limón,\ny el limón me dio en el pecho\ny el agrio en el corazón.",221,0,34,216,"",0,4,"o",31,0,-1,0,131,131,"229","",0,"","","",10,0,0,[],"",""],["murciano_antiguo-n0230",17,"En el Paraíso aleve\nAdán se vido abatido;\nson las penas más crueles\nque a mí me lleva perdido\nel garbo de las mujeres.",221,0,34,216,"",7,5,"ee",-1,0,-1,0,131,131,"230","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0231",17,"A Cartagena me llevan,\nno me llevan por ladrón;\nme llevan porque he robado\na una niña el corazón.",221,0,34,216,"",0,4,"o",31,0,-1,0,131,131,"231","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0232",17,"Dentro de mi pecho habita\nuna penita mortal,\nporque quiero a una rubita\ny no me la quieren dar,\n¡vaya una puñaladita!",221,0,34,216,"",7,5,"ia",50,0,-1,0,132,132,"232","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0233",17,"Subí a contar a la luna\nlas penas que tú me das;\ny abajé como subí:\nqu'a naide hago yo penar.",221,0,34,216,"",0,4,"a",-1,0,-1,0,132,132,"233","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0234",17,"Haré un hoyico en la arena,\nmeteré mi corazón,\ndejaré la lengua fuera\nque publique mi dolor,\nmi sentimiento y mi pena.",221,0,34,216,"",7,5,"ea",-1,0,-1,0,132,132,"234","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0235",17,"Cómo quieres que te olvide\nsi has sido mi consejera,\ny me has criado raíces\ncomo la planta en la tierra.",221,0,34,216,"",0,4,"ea",-1,0,-1,0,133,133,"235","",0,"","","",6,0,0,[],"",""],["murciano_antiguo-n0236",17,"Dentro de mi pecho tengo\nuna mesa de nogal,\nen donde juegan a ratos\nmi amor y tu falsedad.",221,0,34,216,"",0,4,"a",-1,0,-1,0,133,133,"236","",0,"","","",32,0,0,[],"",""],["murciano_antiguo-n0237",17,"Haré por ti una fineza,\nlo que tú por mí no harás:\nquererte aunque no me quieras,\n¿quieres que te quiera más?",221,0,34,216,"",0,4,"a",51,0,-1,0,133,133,"237","",0,"","","",4,0,0,[],"",""],["murciano_antiguo-n0238",17,"Por las calles y las plazas\nsiempre pensando en tu amor,\ncomo no me valen trazas\nle digo a mi corazón:\n¿qué es esto que por mí pasa?",221,0,34,216,"",7,5,"aa",-1,0,-1,0,133,133,"238","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0239",17,"Válgame Dios de los cielos,\nqué grande es la pena mía,\nque me he caído en un pozo\ny no encuentro la salida.",221,0,34,216,"",0,4,"ia",-1,0,-1,0,134,134,"239","",0,"palau_cantares, lafuente_madrid","","",33,0,0,[],"",""],["murciano_antiguo-n0240",17,"Tengo yo mi corazón,\nque si lo vieras, morena,\ncomo los niños del limbo,\nque ni está en gloria ni en pena.",221,0,34,216,"",0,4,"ea",59,0,-1,0,134,134,"240","",0,"","","",14,0,0,[],"",""],["murciano_antiguo-n0241",17,"Alábega de la fina\nSanta Rita la florece;\nla palabra de los hombres\nse ha perdido y no parece.",221,0,34,216,"",0,4,"ee",64,0,-1,0,134,134,"241","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0242",17,"Ya no puedo cantar claro\ny tengo el corazón triste;\nme pasa lo que al canario\ncuando le falta el alpiste.",221,0,34,216,"",0,4,"ie",153,0,-1,0,134,134,"242","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0243",17,"Algún día en tu huerto\nera yo el amo,\ny ahora no me quieres\npor hortelano.",221,0,34,216,"",6,4,"ao",-1,0,-1,0,135,135,"243","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0244",17,"Le pedí a Dios que la vida\nen faltarte me quitara;\nno hace na ni cosa d'años\nque debí estirar la pata.",221,0,34,216,"",0,4,"aa",-1,0,-1,0,135,135,"244","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0245",17,"Amante mío del alma,\nbien te lo decía yo,\nque tú a mí me olvidarías\ny me decías que no.",221,0,34,216,"",0,4,"o",2,0,-1,0,135,135,"245","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0246",17,"La raíz de mi querer\nla partí por la mitá\ny se la di a una mujer;\nno sé si la guardará.",221,0,34,216,"",1,4,"a",9,0,-1,0,135,135,"246","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0247",17,"Tú me distes un clavel,\nyo te di una pasionera;\nel clavel ya se secó\ny la pasión siempre queda.",221,0,34,216,"",0,4,"ea",-1,0,-1,0,136,136,"247","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0248",17,"Si quieres que prevalique\ny que me lleven atado,\npara que diga la gente:\npor ahí va el prevalicado.",221,0,34,216,"",0,4,"ao",14,0,-1,0,136,136,"248","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0249",17,"Pégame una puñalá\ndonde remedio no tenga,\ny sal a la calle y di:\nyo maté a mi dulce prenda.",221,0,34,216,"",0,4,"ea",-1,0,-1,0,136,136,"249","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0250",17,"Me quitaste el corazón,\ny er tuyo me lo has de dar;\nqu'aquer que quita lo ajeno\ncon lo suyo ha de pagar.",221,0,34,216,"",0,4,"a",21,0,-1,0,136,136,"250","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0251",17,"Preso en la cárcel estoy\namarrado a una columna,\ny no me vienes a ver,\ncorazón de piedra dura.",221,0,34,216,"",0,4,"ua",-1,0,-1,0,137,137,"251","",0,"palau_cantares, lafuente_madrid","","",9,0,0,[],"",""],["murciano_antiguo-n0252",17,"Llevas armilla de vuelo,\nguardapiés de barandilla\ny refajo totanero,\ny con ese tupé, niña,\nno eres pa ningún minero.",221,0,34,216,"",7,5,"eo",38,0,-1,0,137,137,"252","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0253",17,"Voy al monte y lo derribo,\na una vara y la mimbreo,\na un fuerte león amanso,\ny a ti, morena, no puedo.",221,0,34,216,"",0,4,"eo",-1,0,-1,0,137,137,"253","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0254",17,"En el hospital herido\ny mi sangre derramando,\nno tendrías otro gusto\nque verme venir penando.",221,0,34,216,"",0,4,"ao",33,0,-1,0,137,137,"254","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0255",17,"Mala puñalá te peguen\nque te revuelques en sangre,\nque tú me vendes a mí\ncomo la mesa a la carne.",221,0,34,216,"",0,4,"ae",-1,0,-1,0,138,138,"255","",0,"","","",3,0,0,[],"",""],["murciano_antiguo-n0256",17,"La palabra que me distes\nencima del Malecón,\ncomo estábamos en alto\nel aire se la llevó.",221,0,34,216,"",0,4,"o",-1,0,-1,0,138,138,"256","",0,"","","",3,0,0,[],"",""],["murciano_antiguo-n0257",17,"Si te vas a Cartagena\ntan sólo por olvidarme,\npermita el cielo divino\nque se abra el mar y te trague.",221,0,34,216,"",0,4,"ae",-1,0,-1,0,138,138,"257","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0258",17,"Jue tu cariño, Pepa,\nflor del almendro:\ns'empavesa de pronto,\nse hiela presto;\ner mío es de priedra:\nandequiá que lo pongo,\nallí se quea.",221,0,34,216,"",4,7,"ea",-1,0,-1,0,138,138,"258","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0259",17,"En Cartagena se suena\nque te has ido y me has dejado;\ntengo que ponerme luto\nde tafetán encarnado.",221,0,34,216,"",0,4,"ao",14,0,-1,0,139,139,"259","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0260",17,"A la flor del baladre\nte he comparado,\nque es hermosa y no llega\nningún ganado.",221,0,34,216,"",6,4,"ao",14,0,-1,0,139,139,"260","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0261",17,"A la flor del baladre\nte he comparao:\nhermosa y no la quiere\ndengún ganao:\nanda que tienes\nla cara de domingo,\ngenio de viernes.",221,0,34,216,"",4,7,"ee",-1,0,-1,0,139,139,"261","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0262",17,"Er sarmiento en la lumbre\ny er que enamora,\npor un lao se emprienden,\npor otro lloran;\ntú eres lo propio,\nni lloras ni te empriendes,\nqu'eres de corcho.",221,0,34,216,"",4,7,"oo",-1,0,-1,0,139,139,"262","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0263",17,"Yo te quería creyendo\nqu'eras una clavellina;\npero m'has salío un cardo\ncon muchísimas espinas.",221,0,34,216,"",0,4,"ia",-1,0,-1,0,140,140,"263","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0264",17,"Eres hermosa en extremo,\npero tienes una falta:\nque en el campo hay muchas flores\ny tú también eres varia.",221,0,34,216,"",0,4,"aa",-1,0,-1,0,140,140,"264","",0,"","","",7,0,0,[],"",""],["murciano_antiguo-n0265",17,"Ya sé que tú quieres ser\nla mejor de to este campo,\ny eres como la olivera:\nmuncha muestra y poco grano.",221,0,34,216,"",0,4,"ao",-1,0,-1,0,140,140,"265","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0266",17,"Eres parpallota falsa\ny eres chavo segoviano:\nhas corrido todo el mundo\npara volver a mi mano.",221,0,34,216,"",0,4,"ao",81,0,-1,0,140,140,"266","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0267",17,"Ejalos que igan, que igan,\nde ti no puén ya decir;\nqu'el árbol que está cogío\nno tié pa qué sacudir.",221,0,34,216,"",0,4,"i",157,0,-1,0,141,141,"267","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0268",17,"Sólo por conocerte\nvengo a buscarte,\nqu'en la güerta tiés fama\npor tuisquias partes;\npero arrepara,\nque la fama que tienes\nes mala fama.",221,0,34,216,"",4,7,"aa",-1,0,-1,0,141,141,"268","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0269",17,"He pasao a beber agua\nfría u caliente,\nque el agua es lo e menos\ny entro por verte;\npero que sepas\nque he bebío en cinco jarras\nantes que en esta.",221,0,34,216,"",4,7,"ea",-1,0,-1,0,141,141,"269","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0271",17,"Me han dicho que tú has dicho\nque eres mi novia;\nmira no te se asiente\ncomo cebolla.",221,0,34,216,"",6,4,"oa",-1,0,-1,0,142,142,"271","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0272",17,"M'han dicho que tú has dicho\nqu'eres mi novia;\nmira no te s'asiente\ncomo cebolla;\ny er estribillo:\npa hacer el chicoflaute\nun molinillo.",221,0,34,216,"",4,7,"io",228,0,-1,0,142,142,"272","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0273",17,"En la mañá voy a Murcia\na ver echar el sorteo;\nsi no m'allega la suerte,\ndiré que por ti me queo.",221,0,34,216,"",0,4,"eo",66,0,-1,0,142,142,"273","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0274",17,"Dicen que no me quieres\nporque soy alta;\nmás altos son los pinos\nde la Fuensanta.",221,0,34,216,"",6,4,"aa",-1,0,-1,0,142,142,"274","",0,"","","",18,0,0,[],"",""],["murciano_antiguo-n0275",17,"Icen que no me quieres\nporque soy alta;\nmás altos son los pinos\nde la Juensanta.\n¡Anda, salero!\nque pa lo que tú vales\ndemás te quiero.",221,0,34,216,"",4,7,"eo",38,0,-1,0,143,143,"275","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0276",17,"Dicen que no me quieres;\ntoavía no he ido yo\na decirte a tu puerta:\nquiéreme, por Dios.",221,0,34,216,"",0,4,"o",-1,0,-1,0,143,143,"276","",0,"","","",18,0,0,[],"",""],["murciano_antiguo-n0277",17,"Dicen que no me quieres\nporque no tengo\nla cintura delgada\ny el pie pequeño.",221,0,34,216,"",6,4,"eo",-1,0,-1,0,143,143,"277","",0,"","","",18,0,0,[],"",""],["murciano_antiguo-n0278",17,"Pasea la calle, guapo,\nque tú te la llevarás...\nla montera en la cabeza\nsi te la ejan llevar.",221,0,34,216,"",0,4,"a",-1,0,-1,0,143,143,"278","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0279",17,"Un amor tenía yo\nque trataba de olvidarme;\nyo me comí el pan primero,\nantes que viniera el hambre.",221,0,34,216,"",0,4,"ae",-1,0,-1,0,144,144,"279","",0,"","","",4,0,0,[],"",""],["murciano_antiguo-n0280",17,"Tú de mí ya no harás caso,\nyo sin ti sabré pasarme;\npues si me olvidas, te olvido;\nno vengas luego a buscarme.",221,0,34,216,"",1,4,"ae",35,0,-1,0,144,144,"280","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0282",17,"Que soy fea, bien lo sé;\nque soy pobre, ya está claro;\nusté no me quiere a mí\ny a mí no me da cuidado.",221,0,34,216,"",0,4,"ao",-1,0,-1,0,144,144,"282","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0283",17,"Dicen que no me has querido,\namante mío, por dama;\nyo soy la que no ha querido,\ntronco de tan baja rama.",221,0,34,216,"",1,4,"aa",90,0,-1,0,145,145,"283","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0284",17,"El querer que te tenía\nera poco y se acabó,\nera un castillo de plumas\ny el aire se lo llevó.",221,0,34,216,"",0,4,"o",2,0,-1,0,145,145,"284","",0,"","","",4,0,0,[],"",""],["murciano_antiguo-n0285",17,"Es verdad que te he querido,\nque te he querido y te quiero,\npero fue sacando burla\nentonces, ahora y luego.",221,0,34,216,"",0,4,"eo",-1,0,-1,0,145,145,"285","",0,"","","",4,0,0,[],"",""],["murciano_antiguo-n0286",17,"Es verdá que te quisí,\nque te he querío y te quiero,\npero haz cuenta que jue groma,\nentonces, abora y luego.",221,0,34,216,"",0,4,"eo",-1,0,-1,0,145,145,"286","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0287",17,"Me pensastes engañar,\npero distes con un pillo\nque te sabía sacar\nlas coplicas del bolsillo.",221,0,34,216,"",1,4,"io",228,0,-1,0,146,146,"287","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0288",17,"Anda burra y no te pares,\nque aquí no venden esparto,\nque las mozas de esta calle\ntienen el moño muy alto.",221,0,34,216,"",0,4,"ao",-1,0,-1,0,146,146,"288","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0289",17,"Arre, burra, y no te pares\nque aquí no venden panizo,\nque las mozas de esta calle\ntienen el moño postizo.",221,0,34,216,"",0,4,"io",95,0,-1,0,146,146,"289","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0290",17,"Yo me enamoré de noche,\ny la luna me engañó;\nla luna no engaña a naide,\nque el engañado fui yo.",221,0,34,216,"",0,4,"o",2,0,-1,0,146,146,"290","",0,"","","",9,0,0,[],"",""],["murciano_antiguo-n0291",17,"Me enamoré de noche\nde tus pestañas,\ncreyendo que eran perlas\ny eran lagañas.",221,0,34,216,"",6,4,"aa",42,0,-1,0,147,147,"291","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0292",17,"A la luz de las estrellas\nme gustaste y te lo ije;\nqu'a esa luz no sabe uno\nqué le gusta ni qué dice.",221,0,34,216,"",0,4,"ie",-1,0,-1,0,147,147,"292","",0,"","","",3,0,0,[],"",""],["murciano_antiguo-n0293",17,"Yo me enamoré del aire\ndel aire de una mujer;\ncomo la mujer es aire\nen el aire me quedé.",221,0,34,216,"",0,4,"e",-1,0,-1,0,147,147,"293","",0,"rm_t3, palau_cantares, isaacs_colombia, lafuente_madrid, fernan_caballero","","",9,0,0,[],"",""],["murciano_antiguo-n0294",17,"No sé yo por qué cosita\nme murmuran en el Barrio;\ntengo yo una posticita\nque al son que me tocan bailo.",221,0,34,216,"",0,4,"ao",-1,0,-1,0,147,147,"294","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0295",17,"Premita er Dios de los cielos\nque te cayas y te mates,\ny que sea yo la peña\nen que los sesos te sartes.",221,0,34,216,"",0,4,"ae",-1,0,-1,0,148,148,"295","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0296",17,"Premita er cielo celeste,\nsi tu amor no es verdadero,\nque en tu cuerpo salga usagre\ny en tu nuca un avispero.",221,0,34,216,"",0,4,"eo",38,0,-1,0,148,148,"296","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0297",17,"Llegué una noche a tu era\ny entre galveras te vi;\nmira si yo te querré,\nqu'estabas sola y me fi.",221,0,34,216,"",0,4,"i",23,0,-1,0,148,148,"297","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0298",17,"Tu maere nunca jue güena\ny tú nunca lo serás:\nde mal trigo, mala harina;\nde mala harina, mal pan.",221,0,34,216,"",0,4,"a",-1,0,-1,0,148,148,"298","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0299",17,"Yo tenía una novia\nque en los garrones\ncriaba chirivías\nnabos y coles.",221,0,34,216,"",6,4,"oe",-1,0,-1,0,149,149,"299","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0300",17,"Yo tenía una novida\nque en los garrones\ncriaba chirividas\ny coliflores.\nYo tenía un novido\nque por tuiquio su cuerpo\ncriaba de todito.",221,0,34,216,"",4,7,"io",-1,0,-1,0,149,149,"300","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0301",17,"Llevas rizos como platos,\ny la basura en la puerta;\nvámonos de aquí, muchachos,\nque está la cochina suelta.",221,0,34,216,"",0,4,"ea",-1,0,-1,0,149,149,"301","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0302",17,"Estás tú tan repeiná\ny tiés sin barrer la puerta;\nvámonos de aquí muchachos,\nque está la marrana suerta.",221,0,34,216,"",0,4,"ea",267,0,-1,0,149,149,"302","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0303",17,"No premitas al zagal\nqu'ande siempre por la cuadra,\nporque tié poca malicia\ny pué comerse la paja.",221,0,34,216,"",0,4,"aa",-1,0,-1,0,150,150,"303","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0304",17,"Si piensas que pienso en ti\nni lo pienso ni imagino,\npor otra cequia más honda\nle va el agua a mi molino.",221,0,34,216,"",0,4,"io",199,0,-1,0,150,150,"304","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0305",17,"No pienses que pienso en ti,\nque ni siquiá lo imagino;\npor otra cieca más honda\nl'entra el agua a mi molino.",221,0,34,216,"",0,4,"io",199,0,-1,0,150,150,"305","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0306",17,"Una viuda me prosigue\n¡cudiao que yo no la busco!\nqu'en la viña vendimiá\nno m'entro yo por rebuscos.",221,0,34,216,"",0,4,"uo",-1,0,-1,0,150,150,"306","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0307",17,"Anda y vete, moño hueco,\nno vengas detrás de mí,\nno te metas en honduras\ndonde no puedas salir.",221,0,34,216,"",0,4,"i",-1,0,-1,0,150,150,"307","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0308",17,"Pensaba el tonto, pensaba\nque por él me moriría:\nla cosa más olvidada\nque mi corazón tenía.",221,0,34,216,"",0,4,"ia",0,0,-1,0,151,151,"308","",0,"","","",3,0,0,[],"",""],["murciano_antiguo-n0309",17,"Si piensas que no lo sé,\ntodito me lo han contado;\nde tu bien me alegraré\nDios te haga bien casado\ny hazlo bien con tu mujer.",221,0,34,216,"",7,5,"e",-1,0,-1,0,151,151,"309","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0310",17,"Te has echado manta fina\nchaqueta con alamares;\nahora para hablar contigo\nnecesitas memoriales.",221,0,34,216,"",0,4,"ae",-1,0,-1,0,151,151,"310","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0311",17,"A mi casa has de venir,\ndueño de mis alpargates,\nque te quiero tanto a ti\ncomo el gato a los tomates.",221,0,34,216,"",0,4,"ae",283,0,-1,0,151,151,"311","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0312",17,"A mi casa has dao en venir,\nmozo de los alpargates;\ny me gustas tanto a mí,\ncomo ar gato los tomates.",221,0,34,216,"",0,4,"ae",283,0,-1,0,152,152,"312","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0313",17,"Si piensas que yo te quiero\nporque te miro y me río...\nSoy un poquico fijona,\ny tú no lo has comprendido.",221,0,34,216,"",0,4,"io",-1,0,-1,0,152,152,"313","",0,"","","",7,0,0,[],"",""],["murciano_antiguo-n0314",17,"Estás tú muy desanchá,\ny entavía no fi yo\na pedírtelo en tu puerta,\nque me quisieras por Dios.",221,0,34,216,"",0,4,"o",-1,0,-1,0,152,152,"314","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0315",17,"Si yo lo hubiera sabido\nlo falso que era tu pecho,\njamás me hubiera metido\nen callejón tan estrecho.",221,0,34,216,"",1,4,"eo",60,0,-1,0,152,152,"315","",0,"","","",3,0,0,[],"",""],["murciano_antiguo-n0316",17,"Eché tierra en tu terrado\npensando que llovería,\ny el viento se la ha llevado;\neso es lo que yo quería.",221,0,34,216,"",1,4,"ia",0,0,-1,0,152,152,"316","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0317",17,"No me venga usté tirando\nchinicas al cantarillo;\nsi a usted se le fue el amor,\na mí el amor y el cariño.",221,0,34,216,"",0,4,"io",-1,0,-1,0,153,153,"317","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0318",17,"Tienes cara de chaqueta,\ncumplimientos de chaleco,\ny las partidas que tienes\nson de pantalón estrecho.",221,0,34,216,"",0,4,"eo",-1,0,-1,0,153,153,"318","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0319",17,"Si piensas que por ti son\nlos colores que me salen,\nno me he enamorado yo\nde hombre que tan poco vale.",221,0,34,216,"",0,4,"ae",-1,0,-1,0,153,153,"319","",0,"","","",4,0,0,[],"",""],["murciano_antiguo-n0320",17,"El día que me dijeron\nque usté a mí no me quería,\ndista el perro de mi casa\nme miraba y se reía.",221,0,34,216,"",0,4,"ia",0,0,-1,0,153,153,"320","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0321",17,"Mi novia me ha despedido\ny del susto se ha sangrado;\nella se pone la venda\nsiendo yo el descalabrado.",221,0,34,216,"",0,4,"ao",14,0,-1,0,153,153,"321","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0322",17,"Yo quería cambiar,\nyo quise y ella no quiso,\nun pañuelo de lunares\npor otro de raso liso.",221,0,34,216,"",0,4,"io",92,0,-1,0,154,154,"322","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0323",17,"En mi vida he sido yo\nplato de segunda mesa,\ny ahora me quieres dar\nlas sobras que otro se deja.",221,0,34,216,"",0,4,"ea",-1,0,-1,0,154,154,"323","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0324",17,"Aunque me ves pequeñica\ncon senaguas de algodón,\nno me ha criado mi madre\npara ningún galopón.",221,0,34,216,"",0,4,"o",31,0,-1,0,154,154,"324","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0325",17,"Aunque me ves pequeñica\ncon senaguas de bayeta,\nno me ha criado mi madre\npa ninguno de la Huerta.",221,0,34,216,"",0,4,"ea",-1,0,-1,0,154,154,"325","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0326",17,"Asómate a esa ventana,\ncara de sardina frita,\nque cada vez que te asomas\nme se revuelven las tripas.",221,0,34,216,"",0,4,"ia",-1,0,-1,0,155,155,"326","",0,"","","",50,0,0,[],"",""],["murciano_antiguo-n0327",17,"Eres más fea que aquel\nque lleva el farol del óleo,\ny si me andas repretando,\nmás fea que los demonios.",221,0,34,216,"",0,4,"oo",-1,0,-1,0,155,155,"327","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0328",17,"Eres más fea que el hambre,\nmás negra que la morcilla;\nel día que tú naciste\nnació la sarna y la tiña.",221,0,34,216,"",0,4,"ia",-1,0,-1,0,155,155,"328","",0,"palau_cantares, lafuente_madrid","","",3,0,0,[],"",""],["murciano_antiguo-n0329",17,"Tengo juramento hecho\na los pies de un abanico,\nde no casarme con tuerto\nni con hombre pequeñico.",221,0,34,216,"",0,4,"io",141,0,-1,0,155,155,"329","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0330",17,"¡Qué bonico que no eres!\n¡Qué gracia que no me haces!\nPor Dios te lo pido, nene,\nque por mi puerta no pases.",221,0,34,216,"",0,4,"ae",287,0,-1,0,156,156,"330","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0331",17,"¡Qué bonico que no eres!\n¡Qué gracia que no me haces!\nPor Dios te pido, güen mozo,\nque por mi puerta no pases.",221,0,34,216,"",0,4,"ae",287,0,-1,0,156,156,"331","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0332",17,"Te despides de una dama\ny vienes a hablar conmigo;\ny yo no soy suplefaltas...\n¿nenico, lo has entendido?",221,0,34,216,"",0,4,"io",-1,0,-1,0,156,156,"332","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0333",17,"Al salir del arrabal\nle eché a mi gargo una liebre,\ndéjalas que güenas van:\nel que la sigue la entiende\ny a la casa gorverán.",221,0,34,216,"",7,5,"a",147,0,-1,0,156,156,"333","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0334",17,"Cómo quieres comparar\nun charco con una fuente:\nsale el sol, se seca el charco\ny la fuente premanece.",221,0,34,216,"",0,4,"ee",-1,0,-1,0,157,157,"334","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0335",17,"Si tuvieras olivares\ncomo tienes fantesía,\nel río Manzanares\npor tu puerta pasaría.",221,0,34,216,"",1,4,"ia",0,0,-1,0,157,157,"335","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0336",17,"Mi novia ya no me quiere\nporque bebo mucho vino;\nvaya a la porra mi novia\ny écheme usté otro cuartillo.",221,0,34,216,"",0,4,"io",-1,0,-1,0,157,157,"336","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0337",17,"Ole con ole con ole,\nole qué quieres que tenga:\n¡que te has ido y me has dejado\ny yo me muero de pena!",221,0,34,216,"",0,4,"ea",-1,0,-1,0,157,157,"337","",0,"","","",7,0,0,[],"",""],["murciano_antiguo-n0338",17,"Eres serafín sin fin,\nserafín que fin no tienes,\nserafín que te entretienes\nen darle fin a otro fin.",221,0,34,216,"",11,4,"i",-1,0,-1,0,158,158,"338","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0339",17,"¡Cómo quieres que te quiera\nsi tú no me puedes dar\nalivio para mis penas,\nconsuelo para mi mal!",221,0,34,216,"",0,4,"a",-1,0,-1,0,158,158,"339","",0,"","","",16,0,0,[],"",""],["murciano_antiguo-n0340",17,"Salero, por tu salero,\na la mar me tiraría,\npero por otro salero,\nen mi casa me estaría.",221,0,34,216,"",1,4,"ia",0,0,-1,0,158,158,"340","",0,"","","",4,0,0,[],"",""],["murciano_antiguo-n0341",17,"Ayer tarde me dijeron\nque V. ya no me quería,\ny se me quedó la cara\ndel color que la tenía.",221,0,34,216,"",0,4,"ia",0,0,-1,0,158,158,"341","",0,"","","",4,0,0,[],"",""],["murciano_antiguo-n0342",17,"Premita Dios que te vea\nsin chaqueta y sin carzones,\nen lo arto d'una palera\nespantando los gurriones.",221,0,34,216,"",0,4,"oe",34,0,-1,0,159,159,"342","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0343",17,"El caso qu'hago de ti\nlo echaré en una arcancía,\ny nunca s'allenará,\ny siempre estará vacía.",221,0,34,216,"",0,4,"ia",0,0,-1,0,159,159,"343","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0344",17,"Tu nombre, si tú tiés nombre,\nvoy a buscar quien lo escriba,\nen la suela un alpargate\npa que sea más la iznominia.",221,0,34,216,"",0,4,"ia",-1,0,-1,0,159,159,"344","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0345",17,"Tu nombre y tus apellíos\nvoy a buscar quien escriba\nen la suela e mi arpargate\npara mayor iznominia.",221,0,34,216,"",0,4,"ia",-1,0,-1,0,159,159,"345","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0346",17,"Aunque tu maere no quiera\nte lo tengo de dicir:\nla paeces al tío que vende\ntinta fina de escrebir.",221,0,34,216,"",3,4,"i",157,0,-1,0,160,160,"346","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0347",17,"Aunque tu madre te venda\nal precio que dan los nabos,\nno te tengo que comprar\nporque lo barato es caro.",221,0,34,216,"",0,4,"ao",-1,0,-1,0,160,160,"347","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0348",17,"Manque tu maere te venda\nal precio que dan los nabos,\nnaide te tié que comprar\npoique lo barato es caro.",221,0,34,216,"",0,4,"ao",-1,0,-1,0,160,160,"348","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0349",17,"Aunque tu madre me diera\nla carreta y el buey rojo,\nno me he de casar contigo,\nporque eres tuerta de un ojo.",221,0,34,216,"",0,4,"oo",400,0,-1,0,160,160,"349","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0350",17,"Aunque tu madre te ponga\nal pie del altar mayor\ncon un ramico de flores,\nno eres tú mejor que yo.",221,0,34,216,"",0,4,"o",-1,0,-1,0,161,161,"350","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0351",17,"Te debían tener tus paeres\nencerrá dentro d'un arca;\nporque eres una arbullosa,\ny un repoquitiquio mala.",221,0,34,216,"",3,4,"aa",-1,0,-1,0,161,161,"351","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0352",17,"A la una de la noche,\ncuando la luna está en calma,\nse dan las satisfacciones\nlos dos amantes del alma.",221,0,34,217,"",0,4,"aa",125,0,-1,0,161,161,"352","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0353",17,"Antes de que rompa er día,\ncuando la güerta está en carma,\nvengo a dar satisfacciones\na mi querer de mi arma;\ndel arma y la vida mía.",221,0,34,217,"",7,5,"ia",0,0,-1,0,162,162,"353","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0354",17,"Dueño mío, vienes tarde\ny te quieres ir temprano:\nmira que no quiero yo\nvisitas de cirujano.",221,0,34,217,"",0,4,"ao",81,0,-1,0,162,162,"354","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0355",17,"Entre espinas y abreojos,\nmadama, me atrevo a entrar\na quitarte los enojos\ny a que me vuelvas a hablar,\nhechicera de mis ojos.",221,0,34,217,"",7,5,"oo",99,0,-1,0,162,162,"355","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0356",17,"A las tres de la mañana,\nde la mañana sería,\nen tu jarra bebí agua\nporque teniba sequía.",221,0,34,217,"",0,4,"ia",0,0,-1,0,162,162,"356","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0357",17,"Compañerica del alma,\nanoche en tu puerta estuve;\nestabas en la ventana\ny no me dijistes 'sube'.",221,0,34,217,"",0,4,"ue",208,0,-1,0,163,163,"357","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0358",17,"Agua menudita llueve,\npronto caerán las canales;\nábreme la puerta, nena,\nque soy aquel que tú sabes.",221,0,34,217,"",0,4,"ae",-1,0,-1,0,163,163,"358","",0,"","","",6,0,0,[],"",""],["murciano_antiguo-n0359",17,"La noche entavía está negra,\nla mollina ni ha calao;\nlevanta y abre tu puerta,\nque me tienes ambustiao;\nábreme la puerta, nena.",221,0,34,217,"",7,5,"ea",-1,0,-1,0,163,163,"359","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0360",17,"A la una entré en tu calle\ny ya van a dar las dos;\ndile al sereno que calle,\nque vamos a hablar los dos\ncositas que nadie sabe.",221,0,34,217,"",7,5,"ae",-1,0,-1,0,163,163,"360","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0361",17,"A la una estaba yo\njunto ar quijero el azarbe,\ny apenas sentí las dos\nvine pa que t'alevantes:\nque t'alevantes y hablemos\ncosiquias que naide sabe.",221,0,34,217,"",9,6,"ae",-1,0,-1,0,164,164,"361","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0362",17,"A las dos de la mañana,\npublicando mi alegría,\nse quedó mi amor en calma,\ncalle de la Platería.",221,0,34,217,"",0,4,"ia",0,0,-1,0,164,164,"362","",0,"","","",7,0,0,[],"",""],["murciano_antiguo-n0363",17,"Ya que no tienes ventana\nni tu paere te la hizo,\nescucha cuatro palabras\npor este triste cañizo.",221,0,34,217,"",0,4,"io",95,0,-1,0,164,164,"363","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0364",17,"Ya que no tienes ventana,\nporque tu paere no la hizo\nescucha lo que cantamos,\npor las claras del cañizo.",221,0,34,217,"",0,4,"io",95,0,-1,0,164,164,"364","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0365",17,"En aquel balcón sin luz\nya se estarán acostando;\nmi corazón está dentro\ny mi alma está penando.",221,0,34,217,"",0,4,"ao",33,0,-1,0,165,165,"365","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0366",17,"La despedida te doy\npor debajo de la parra:\nadiós, luna, y adiós, sol,\ny adiós, María del alma.",221,0,34,217,"",0,4,"aa",-1,0,-1,0,165,165,"366","",0,"","","",9,0,0,[],"",""],["murciano_antiguo-n0367",17,"La despedida te doy\npor debajo de la parra;\nquédate con Dios, morena,\nque me llevo la guitarra.",221,0,34,217,"",0,4,"aa",308,0,-1,0,165,165,"367","",0,"","","",9,0,0,[],"",""],["murciano_antiguo-n0368",17,"La despedida te doy\npor debajo de la parra;\nduérmete pensando en mí,\nque te quiero más que a mi arma.",221,0,34,217,"",0,4,"aa",-1,0,-1,0,165,165,"368","",0,"","","",9,0,0,[],"",""],["murciano_antiguo-n0369",17,"La despedía te doy\nebajiquio de la parra;\nquéate con Dios, morena,\nque se va er de la guitarra.",221,0,34,217,"",0,4,"aa",308,0,-1,0,166,166,"369","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0370",17,"Debajo de tu ventana\nme dio sueño y me dormí,\nme despertaron los gallos\ncantando el qui qui ri qui.",221,0,34,217,"",0,4,"i",23,0,-1,0,166,166,"370","",0,"","","",29,0,0,[],"",""],["murciano_antiguo-n0371",17,"Si la lámpara del Carmen\nestuviera enguarnecida\nde perlas y de diamantes,\npor aquella ventanica\nyo hablaría con mi amante.",221,0,34,217,"",7,5,"ae",-1,0,-1,0,166,166,"371","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0372",17,"Ya que no te puedo ver\nni a lo claro ni a lo oscuro,\nme alegro de ver salir\npor tu chimenea el humo.",221,0,34,217,"",0,4,"uo",-1,0,-1,0,166,166,"372","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0373",17,"Anoche en tu ventana\npuse un cigarro\ny esta noche que viene\nvuelvo a buscarlo;\ny si lo encuentro\nes señal que no ha habido\notro en mi puesto.",221,0,34,217,"",4,7,"eo",-1,0,-1,0,167,167,"373","",0,"","","",3,0,0,[],"",""],["murciano_antiguo-n0374",17,"Por tu calle voy entrando,\nprenda del alma quería;\nya sabes a lo que vengo,\ndespierta si estás dormía.",221,0,34,217,"",0,4,"ia",0,0,-1,0,167,167,"374","",0,"","","",4,0,0,[],"",""],["murciano_antiguo-n0375",17,"A las dos de la mañana\nserían cuando llegó\nmi corazón a tu cama\ny te dijo en alta voz:\ndispierta, rosa trempana.",221,0,34,217,"",7,5,"aa",-1,0,-1,0,167,167,"375","",0,"","","",7,0,0,[],"",""],["murciano_antiguo-n0376",17,"Ya sé que estás en camisa,\ny que no te duermes, no;\nya sé que estás ascuchando\nlas coplas que canto yo.",221,0,34,217,"",0,4,"o",2,0,-1,0,168,168,"376","",0,"","","",3,0,0,[],"",""],["murciano_antiguo-n0377",17,"Son las tres de la mañana,\nque las dio la Catreal,\ndispiértate ya, zagala,\nqu'er que canta es tu zagal;\ndispierta, rosa trempana.",221,0,34,217,"",7,5,"aa",-1,0,-1,0,168,168,"377","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0378",17,"A las tres justas llegó\nmi cantar dista tu cama;\ndispierta y abrígalo,\nque en mi cantar pone mi alma\npeacicos del corazón.",221,0,34,217,"",7,5,"o",-1,0,-1,0,168,168,"378","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0379",17,"Esta noche, si Dios quiere,\ntengo que cantar yo aquí,\ncon premiso del Alcarde\ny de la Guardia Cevil.",221,0,34,217,"",0,4,"i",-1,0,-1,0,168,168,"379","",0,"","","",4,0,0,[],"",""],["murciano_antiguo-n0380",17,"La luna para salir\nar sol le pide licencia;\ny para cantar yo aquí,\nla pido con reverencia.",221,0,34,217,"",0,4,"ea",46,0,-1,0,169,169,"380","",0,"","","",14,0,0,[],"",""],["murciano_antiguo-n0381",17,"Pa comenzar a cantar\nlicencia s'ha de pidir,\nar señor cura, al alcarde,\ny hasta a la Guardia Cevil.",221,0,34,217,"",0,4,"i",-1,0,-1,0,169,169,"381","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0382",17,"La luna que va a salir\nlicencia le pide ar cielo;\ny para cantar yo aquí\nlicencia pido primero.",221,0,34,217,"",0,4,"eo",-1,0,-1,0,169,169,"382","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0383",17,"Canto esta copla y na más,\nporque me voy a dormir;\nque mañana, si Dios quiere,\nnaide ha de velar por mí.",221,0,34,217,"",0,4,"i",-1,0,-1,0,169,169,"383","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0384",17,"Las piedras rulan a l'hondo,\ner humo sube hasta er cielo;\ny yo me voy a acostar\npoique me cayo de sueño.",221,0,34,217,"",0,4,"eo",-1,0,-1,0,169,169,"384","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0385",17,"Esta noche, si Dios quiere,\nme tengo que devertir,\ncon premiso del arcarde\ny de la guardia cevil.",221,0,34,217,"",0,4,"i",-1,0,-1,0,170,170,"385","",0,"","","",4,0,0,[],"",""],["murciano_antiguo-n0386",17,"En diciendo que es de noche\ntomo la manta y me chalo,\nv no tengo quién me diga\nsi vengo tarde o temprano.",221,0,34,217,"",0,4,"ao",-1,0,-1,0,170,170,"386","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0387",17,"A las dos de la mañana\nle eché a mi caballo el freno,\nque a las dos de la mañana\nsalen los caballos buenos.",221,0,34,217,"",0,4,"eo",-1,0,-1,0,170,170,"387","",0,"","","",7,0,0,[],"",""],["murciano_antiguo-n0388",17,"Aquel lucerito, madre,\nque va al lado de la luna,\nes el que a mí me acompaña\nla noche que voy de tuna.",221,0,34,217,"",0,4,"ua",56,0,-1,0,170,170,"388","",0,"","","",3,0,0,[],"",""],["murciano_antiguo-n0389",17,"Canta tú y cantaré yo,\ncantaremos a porfía;\ntú le cantas a tu novia,\nyo le cantaré a la mía.",221,0,34,217,"",0,4,"ia",0,0,-1,0,170,170,"389","",0,"","","",6,0,0,[],"",""],["murciano_antiguo-n0390",17,"Quién la música te trujo\nno te lo quisiá icir;\npero está tan retirao\ncomo la ropa de mí.",221,0,34,217,"",0,4,"i",-1,0,-1,0,171,171,"390","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0391",17,"Esta noche, moreniquia,\nnos vamos a devertir,\ncon una música buena,\nla guitarra y el violín.",221,0,34,217,"",0,4,"i",-1,0,-1,0,171,171,"391","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0392",17,"La guitarra y el violín\nte dicen que te levantes...\n¿no te quieres levantar?\nla música va a otra parte.",221,0,34,217,"",0,4,"ae",-1,0,-1,0,171,171,"392","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0393",17,"Guitarros y vigulines\nte icen que t'alevantes;\nsi no te quiés levantar\nnos iremos a otra parte.",221,0,34,217,"",0,4,"ae",-1,0,-1,0,171,171,"393","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0394",17,"La guitarra pide vino\ny las cuerdas aguardiente,\ny el muchacho que las toca\nmuchachas de quince a veinte.",221,0,34,217,"",0,4,"ee",-1,0,-1,0,171,171,"394","",0,"","","",3,0,0,[],"",""],["murciano_antiguo-n0395",17,"La guitarra pide vino,\nel violín pide aguardiente;\ny los dos que las tocamos\nzagalas de quince a veinte.",221,0,34,217,"",0,4,"ee",-1,0,-1,0,172,172,"395","",0,"","","",3,0,0,[],"",""],["murciano_antiguo-n0396",17,"Si me estuviera muriendo\ny sintiera una guitarra,\nme levantara corriendo\ny una malagueña echara.",221,0,34,217,"",0,4,"aa",-1,0,-1,0,172,172,"396","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0397",17,"El tocar la guitarra\nno quiere cencia,\nque quiere juerza en brazo\ny habilitrencia.",221,0,34,217,"",6,4,"ea",46,0,-1,0,172,172,"397","",0,"","","",3,0,0,[],"",""],["murciano_antiguo-n0398",17,"El tocar la guitarra\nno quiere cencia,\nsino juerza en los deos\ny habilidencia;\neste es er dengue:\nlo demás, chicoflaute\ny agua de nieve.",221,0,34,217,"",4,7,"ee",-1,0,-1,0,172,172,"398","",0,"","","",3,0,0,[],"",""],["murciano_antiguo-n0399",17,"Dame de tu moño pelos\npa encordar esta guitarra;\nque s'acaban de sartar\nla prima, tercera y cuarta.",221,0,34,217,"",0,4,"aa",-1,0,-1,0,173,173,"399","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0400",17,"Ande usté por los caireles\nque a todo el mundo iluminan,\nque en diciendo 'moros vienen'\nhasta el alma me se anima.",221,0,34,217,"",0,4,"ia",-1,0,-1,0,173,173,"400","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0401",17,"Por bailar las parrandas\ndel pan torrao,\nmira qué pantorrillas\nque me han queao.",221,0,34,217,"",6,4,"ao",98,0,-1,0,173,173,"401","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0402",17,"Por bailar las parrandas,\nniña, contigo,\nme llevan a la casa\ndel poco trigo.",221,0,34,217,"",6,4,"io",106,0,-1,0,173,173,"402","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0403",17,"Anteayer, ayer y hoy,\nrazón es que me convengo,\na echar un cigarro voy,\nque ganas de fumar tengo.",221,0,34,217,"",1,4,"eo",124,0,-1,0,174,174,"403","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0404",17,"Echa vino, tabernero,\ny enjuaga bien los cristales,\nque venimos a beber\ncuatro mocitos juncales.",221,0,34,217,"",0,4,"ae",26,0,-1,0,174,174,"404","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0405",17,"Anteanoche fui al teatro\ny vide a la emperatriz,\nplatiqué con ella un rato,\ny me dijo la infeliz:\nya murió Pedro el Morato.",221,0,34,217,"",7,5,"ao",19,0,-1,0,174,174,"405","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0406",17,"Dicen que Pedro Morato\nes un hombre trovador,\npero dicen los muchachos:\nPedro Morato murió\nen la taberna borracho.",221,0,34,217,"",7,5,"ao",-1,0,-1,0,174,174,"406","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0407",17,"Ya no cantará Chilares\nen los bañitos de Archena,\nporque le dieron un tiro\nentre Murcia y Cartagena.",221,0,34,217,"",0,4,"ea",59,0,-1,0,175,175,"407","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0408",17,"Me llamo Pedro (el Morato),\nhijo natural de Vera,\ny estoy loquito perdío\npor una cartagenera.",221,0,34,217,"",0,4,"ea",44,0,-1,0,175,175,"408","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0409",17,"En la calle de Canales\ncantaba Paco el Herrero,\nle acompañaba Chilares\ny el Moratillo el pequeño;\nla rubia de los lunares.",221,0,34,217,"",7,5,"ae",164,0,-1,0,175,175,"409","",0,"","","",3,0,0,[],"",""],["murciano_antiguo-n0410",17,"Cuando el Morato se pone\ncon la guitarra en la mano,\nvenga tela, venga tela,\nvenga tela de verano.",221,0,34,217,"",0,4,"ao",81,0,-1,0,175,175,"410","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0411",17,"Adiós, Facorro del alma,\nque me voy a Zaraiche;\nya no jugaremos más\na las chapas y al caliche.",221,0,34,217,"",5,4,"ie",-1,0,-1,0,176,176,"411","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0413",17,"En la Puerta de Castilla\ny en to er partío e Zaraiche,\nes ande mejor se jueba\na las chapas y ar caliche.",221,0,34,217,"",5,4,"ie",-1,0,-1,0,176,176,"413","",0,"","","",3,0,0,[],"",""],["murciano_antiguo-n0415",17,"Si te quieres devertil\nasómate a la muralla;\nverás el ferrocarril\nqué sereniquio que anda\ncuando sale pa Madrid.",221,0,34,217,"",7,5,"i",-1,0,-1,0,177,177,"415","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0416",17,"Mi madre me dice pillo\nporque llevo atrás la gorra,\ny yo digo: madre mía,\nel ser pillo no es deshonra.",221,0,34,217,"",0,4,"oa",-1,0,-1,0,177,177,"416","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0417",17,"A la puerta d'un sordo\ncantaba un mudo,\ny un ciego los miraba\ncon desimulo.\nY aquí el estilo\nes querer a las chiquias\nmás que a los chiquios.",221,0,34,217,"",4,7,"io",-1,0,-1,0,177,177,"417","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0418",17,"Una pulga saltando\nrompió un lebrillo,\nuna chocolatera\ny un molinillo.",221,0,34,217,"",6,4,"io",228,0,-1,0,177,177,"418","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0419",17,"Al perro de San Roque\nl'han levantao\nun farso testimonio:\nqu'está preñao;\n¡Jesús, qué mundo!\nque ni er perro e San Roque\nestá seguro.",221,0,34,217,"",4,7,"uo",-1,0,-1,0,178,178,"419","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0420",17,"Un gorrión y un gato\nse han hecho amigos\ny han ido a pasearse\npor Capuchinos.\n¡Quién lo dijera,\nque un gorrión y un gato\namigos fueran!",221,0,34,217,"",4,7,"ea",-1,0,-1,0,178,178,"420","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0421",17,"Cuando los cánticos gallan,\ny cuando los ladros perran,\ntengo los tiesos tan deos,\nqu'hasta las tiemblas me piernan.",221,0,34,217,"",0,4,"ea",-1,0,-1,0,178,178,"421","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0422",17,"Nominativo turronis,\ngenitivo mantecatis,\nacusativo morconis,\ny ablativo pollo asatis.",221,0,34,217,"",1,4,"ai",722,0,-1,0,178,178,"422","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0423",17,"El palacio del obispo\nse fue una noche al sermón,\nal tiempo que al Arenal\nle dio mal de corazón.",221,0,34,217,"",0,4,"o",31,0,-1,0,179,179,"423","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0424",17,"Ciento cincuenta años\ntiene mi novia,\ny no quiere casarse\npor novachona.",221,0,34,217,"",6,4,"oa",-1,0,-1,0,179,179,"424","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0425",17,"Yo tenía un gallo inglés\ny lo llevé al reñidero,\ny en la primera pelea\nperdí el gallo y el dinero.",221,0,34,217,"",0,4,"eo",38,0,-1,0,179,179,"425","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0426",17,"Tres fiestas en el año\ncausan prestigio:\nNavidad, Corpus Christi\ny el Asensicio.",221,0,34,217,"",6,4,"io",-1,0,-1,0,179,179,"426","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0427",17,"Cuando un panocho en la huerta\nquiere a una moza rondar,\nse abalanza a una morera\ny emprencipia a relinchar.",221,0,34,217,"",0,4,"a",21,0,-1,0,179,179,"427","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0428",17,"Panocho que va de ronda\ny se quié sinificar,\ns'agarra de una morera\ny suerta una relinchá.",221,0,34,217,"",0,4,"a",-1,0,-1,0,180,180,"428","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0429",17,"Si pasas por la verea,\nrelincha que t'oya yo,\npoique metía en la barraca\nno sé si pasas u no.",221,0,34,217,"",0,4,"o",2,0,-1,0,180,180,"429","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0430",17,"Er novio mira a su novia\ny le paece que es devina;\nlo mesmo piensa er cochino\ncuando mira a su cochina.",221,0,34,217,"",0,4,"ia",11,0,-1,0,180,180,"430","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0431",17,"Esta noche vendré tarde,\nque mi burro me perdió;\nsi sientes pisás de burro,\nasómate que soy yo.",221,0,34,217,"",0,4,"o",2,0,-1,0,180,180,"431","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0432",17,"En esta calle a lo largo\ntengo de formar un puente\ncon las costillas de un guapo\ny la sangre de un valiente.",221,0,34,217,"",0,4,"ee",15,0,-1,0,180,180,"432","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0433",17,"En esta esquina me paro\ny aquí planto mi bandera,\ny el que quiera llevar palos\nya está saliendo pa afuera.",221,0,34,217,"",3,4,"ea",44,0,-1,0,181,181,"433","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0434",17,"He de poner un letrero\nen lo arto d'esta barraca,\nque diga que naide se pare,\nqu'ar que se para lo matan.",221,0,34,217,"",0,4,"aa",-1,0,-1,0,181,181,"434","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0435",17,"Para pasear tu calle\nno necesito cuchillo,\nque ese novio que tú tienes\nme lo meto en el bolsillo.",221,0,34,217,"",0,4,"io",228,0,-1,0,181,181,"435","",0,"","","",8,0,0,[],"",""],["murciano_antiguo-n0436",17,"Para pasear tu calle\nno necesito navaja,\nque ese novio que tú tienes\nme lo meto entre la faja.",221,0,34,217,"",0,4,"aa",393,0,-1,0,181,181,"436","",0,"","","",8,0,0,[],"",""],["murciano_antiguo-n0437",17,"Pa rondarte no es mester\nllevar pistola ni faca;\nque los novios que tú tienes\nme los meto yo en la faja.",221,0,34,217,"",0,4,"aa",-1,0,-1,0,182,182,"437","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0438",17,"Si la novia que yo tengo\notro me la camelara,\nsacara mi pistolica\ny un tirito le pegara.",221,0,34,217,"",0,4,"aa",57,0,-1,0,182,182,"438","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0439",17,"Icen que no me quieres\npoco ni muncho;\nm'has de querer por juerza,\nsi no te puncho.",221,0,34,217,"",6,4,"uo",723,0,-1,0,182,182,"439","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0440",17,"Vivan los mozos del Barrio\ny los que gastan cuchillo;\ntambién los que se emborrachan\ny escupen por el colmillo.",221,0,34,217,"",0,4,"io",228,0,-1,0,182,182,"440","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0441",17,"De la mañana a la una,\nde la mañana a las dos,\ntengo la pistola, padre,\ny el buchillico de Dios.",221,0,34,217,"",0,4,"o",87,0,-1,0,183,183,"441","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0442",17,"En Cartagena se suena\nque me han de matar de un tiro;\nnunca llueve cuando truena,\nyo con la esperanza vivo.",221,0,34,217,"",0,4,"io",-1,0,-1,0,183,183,"442","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0443",17,"Me dejaron mal herido\nencomedio de la calle;\nlas baldosas las regué\ncon mi colorada sangre.",221,0,34,217,"",0,4,"ae",-1,0,-1,0,183,183,"443","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0444",17,"Válgame san válgame,\ncuántas luces y linternas;\nsin haber bebido vino,\ncómo me tiemblan las piernas.",221,0,34,217,"",0,4,"ea",690,0,-1,0,183,183,"444","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0445",17,"Yo me morí, reviví,\ny gorví a resucitar,\ny a mi cabecera vide\nquién me quiso bien o mal.",221,0,34,217,"",0,4,"a",-1,0,-1,0,184,184,"445","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0446",17,"Yo quisiera al morirme\nsentir los dobles,\npara ver quién decía:\nDios te perdone.",221,0,34,217,"",6,4,"oe",-1,0,-1,0,184,184,"446","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0447",17,"Tengo yo un cofrecico\nque voy echando\npenas y pesadumbres\nque me van dando;\npero algún día\nse abrirá el cofrecico;\nserá la mía.",221,0,34,217,"",4,7,"ia",0,0,-1,0,184,184,"447","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0448",17,"A las dos de la mañana\ntengo lo que usté no tiene:\nun reló que da la hora\ny un moliniquio que muele.",221,0,34,217,"",0,4,"ee",-1,0,-1,0,184,184,"448","",0,"","","",7,0,0,[],"",""],["murciano_antiguo-n0449",17,"Los enemigos del arma\nm'enseñaron que son tres;\ny yo digo que son cuatro,\nque también la cuento a' osté,\nmaere de mi fino encanto.",221,0,34,217,"",7,5,"ao",-1,0,-1,0,185,185,"449","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0450",17,"Cantar que del alma sale\nes pájaro que no muere:\nvolando de boca en boca\ncorre mucho y vive siempre.",221,0,34,218,"",0,4,"ee",-1,0,-1,0,185,185,"450","",0,"","","",4,0,0,[],"",""],["murciano_antiguo-n0451",17,"Amigo qu'es güen amigo\nha de ser como la sangre,\nqu'acude ande s'hace hería\ny no es mester que lo llames.",221,0,34,218,"",0,4,"ae",-1,0,-1,0,185,185,"451","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0452",17,"No te enamores, niña,\nde los que andan\ncon el garrote al hombro:\n'¡ven acá, cabra!'",221,0,34,218,"",6,4,"",-1,0,-1,0,186,186,"452","",0,"","","",4,0,0,[],"",""],["murciano_antiguo-n0453",17,"No te enamores, niña,\nde lo barato:\nveinticico alfileres\ndan por un cuarto.",221,0,34,218,"",6,4,"ao",-1,0,-1,0,186,186,"453","",0,"","","",4,0,0,[],"",""],["murciano_antiguo-n0454",17,"En tu vida te enamores\nde mozo que no ha rondao;\nque el que no ronda de mozo,\nronda después de casao.",221,0,34,218,"",0,4,"ao",98,0,-1,0,186,186,"454","",0,"","","",7,0,0,[],"",""],["murciano_antiguo-n0455",17,"Er viejo que se casa\ncon una moza,\nér cautiva la tierra\npa que otro coja.",221,0,34,218,"",6,4,"oa",-1,0,-1,0,186,186,"455","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0456",17,"Espiga que tié grano\ndobla hacia la tierra,\ny la que está falluta\ns'empina tiesa:\nese es er mundo:\nhumirde aquel que vale,\ntieso el falluto.",221,0,34,218,"",4,7,"uo",-1,0,-1,0,187,187,"456","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0457",17,"Hombres hay por esos mundos\nque se la echan muncho d'hombres;\ny entre gallos son gallinas,\ny entre gallinas, capones.",221,0,34,218,"",0,4,"oe",-1,0,-1,0,187,187,"457","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0458",17,"Puse el pie sobre una piedra\na desatarme una liga:\nquien bien ata bien desata;\nquien bien quiere, tarde olvida.",221,0,34,218,"",0,4,"ia",-1,0,-1,0,187,187,"458","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0459",17,"Vale usted más dineritos\nque el reloj de Puerto Velo;\nestamos en un mundito\nque no se aprecia lo bueno.",221,0,34,218,"",0,4,"eo",-1,0,-1,0,188,188,"459","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0460",17,"Más vale una mirada\ncuando hay ocasión,\nque toda una mañana\nde conversación.",221,0,34,218,"",0,4,"o",31,0,-1,0,188,188,"460","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0461",17,"Todos los que llevan pello\ny chaqueta de alamares,\nse ponen en las esquinas...\nvivan las mozas juncales.",221,0,34,218,"",0,4,"ae",-1,0,-1,0,188,188,"461","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0462",17,"Viva la feria de Vélez\ndonde van las andaluzas\ntodas llenas de caireles,\ny a los murcianos les gustan.",221,0,34,218,"",0,4,"ua",-1,0,-1,0,188,188,"462","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0463",17,"La mujer que es habladora\nle paece a las gallinas,\nque por gusto d'escarbar\nse tira la tierra encima.",221,0,34,218,"",0,4,"ia",-1,0,-1,0,188,188,"463","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0464",17,"El querer de la mujer\nle paece ar de la gallina,\nque en fartándole su gallo,\na cualquier pollo s'arrima.",221,0,34,218,"",0,4,"ia",-1,0,-1,0,189,189,"464","",0,"","","",3,0,0,[],"",""],["murciano_antiguo-n0465",17,"El querer de la mujer\ntamién le paece al del perro,\nqu'a palos y puntapiés\ntoman su querencia ar dueño.",221,0,34,218,"",0,4,"eo",-1,0,-1,0,189,189,"465","",0,"","","",3,0,0,[],"",""],["murciano_antiguo-n0466",17,"Una mujer seca, seca,\nseca, seca, se casó\ny como estaba tan seca,\nseca, seca se quedó.",221,0,34,218,"",1,4,"o",2,0,-1,0,189,189,"466","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0467",17,"El amor para ser bueno\nha de pasar penas muchas,\nha de dormir al sereno,\nque no se cogen las truchas\ncon las manos en el seno.",221,0,34,218,"",7,5,"eo",76,0,-1,0,189,189,"467","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0468",17,"El hombre, dice un sabio,\nque es una bestia,\nsi antes que cierre un trato\nno mira y piensa;\nque no conviene\nalquilar una casa\nque tenga duende.",221,0,34,218,"",4,7,"ee",-1,0,-1,0,190,190,"468","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0469",17,"El querer es un cigarro\nque t'hace gastar saliva;\nlo apuras hasta quemarte\ny lluego dimpués lo tiras.",221,0,34,218,"",0,4,"ia",-1,0,-1,0,190,190,"469","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0470",17,"El querer qu'emprencipia\ny er zagaliquio,\npa sustenello basta\ncon mu poquiquio.\nPero en creciendo,\ncuanti más le vas dando\nmás va pidiendo.",221,0,34,218,"",4,7,"eo",52,0,-1,0,190,190,"470","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0471",17,"El querer y la naranja\ntambién se paecen an argo:\nque la naranja más durce\ntiene su puntiquia de agro.",221,0,34,218,"",0,4,"ao",-1,0,-1,0,190,190,"471","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0472",17,"No te tires, no te tires,\nque romperás el farol,\ny te mancharás de aceite\ny no tendrás pa jabón.",221,0,34,218,"",0,4,"o",-1,0,-1,0,191,191,"472","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0473",17,"La experencia y la cencia\ny la gramancia,\nhacen al hombre supio\npor la estudancia;\necha y no errames,\nque en sabiendo er Riparda\nbastante sabes.",221,0,34,218,"",4,7,"ae",-1,0,-1,0,191,191,"473","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0474",17,"Nunca pidas, nunca debas,\nnunca a naide le hagas mal,\nmira y remira, oye y calla;\ny las gracias me darás.",221,0,34,218,"",3,4,"a",-1,0,-1,0,191,191,"474","",0,"","","",4,0,0,[],"",""],["murciano_antiguo-n0475",17,"Los naipes, la bebía\ny los cigarros,\nnaide los deja, y munchos\nquieren ejallos;\ny si los dejan\ngüerven impués a ellos\ncon mayor juerza.",221,0,34,218,"",4,7,"ea",-1,0,-1,0,192,192,"475","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0476",17,"La mañana de San Juan\ncuando la zorra madruga,\nel que con vino se acuesta\ncon agua se desayuna.",221,0,34,218,"",0,4,"ua",-1,0,-1,0,192,192,"476","",0,"","","",3,0,0,[],"",""],["murciano_antiguo-n0477",17,"Cantaré que estoy alegre\ncomo la fresca mañana;\nalgún día lloraré,\nque ahora no tengo gana.",221,0,34,218,"",0,4,"aa",4,0,-1,0,192,192,"477","",0,"","","",3,0,0,[],"",""],["murciano_antiguo-n0478",17,"A cerezas en montón\ntengo comparás las penas;\nque con ca una, enredás,\netrás sale media ocena.",221,0,34,218,"",0,4,"ea",-1,0,-1,0,193,193,"478","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0479",17,"Por haber muerto mi madre\nestoy pasando fatigas,\ny no lloro por la calle\nporque la gente no diga.",221,0,34,218,"",0,4,"ia",-1,0,-1,0,193,193,"479","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0480",17,"Pequeñiquia y llevas luto,\ndime quién te se murió;\nsi te se ha muerto tu amante,\nno llores que aquí estoy yo.",221,0,34,218,"",0,4,"o",2,0,-1,0,193,193,"480","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0481",17,"Como las esperanzas\nson los laureles;\nque nunca llevan fruto,\nsiempre están verdes.",221,0,34,218,"",6,4,"ee",-1,0,-1,0,193,193,"481","",0,"","","",3,0,0,[],"",""],["murciano_antiguo-n0482",17,"Salomón siendo un sabio\nun templo formó,\ny Sansón siendo fuerte\nse lo derribó.",221,0,34,218,"",0,4,"o",2,0,-1,0,194,194,"482","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0483",17,"Pruhibe er sabio Salomón\nsacar la cara por naide;\nar que le duele una muela\nque se l'arranque y que rabie.",221,0,34,218,"",0,4,"ae",-1,0,-1,0,194,194,"483","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0484",17,"Dijo er sabio Salomón\nque toa la gente se guarde\nde hombre a quien no sale barba\ny de mujer a quien sale.",221,0,34,218,"",0,4,"ae",-1,0,-1,0,194,194,"484","",0,"","","",3,0,0,[],"",""],["murciano_antiguo-n0485",17,"Para reinar, un David;\npara saber, Salomón;\npara llorar, Jeremías;\ny para fuerza, Sansón.",221,0,34,218,"",0,4,"o",31,0,-1,0,194,194,"485","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0486",17,"Un sabio de Ingalaterra\nandaba pensando un día\nqu'en fartando los tomates\nel mundo s'acabaría.",221,0,34,218,"",0,4,"ia",0,0,-1,0,194,194,"486","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0487",17,"Yo m'arrimé a un burro negro\np'ampararme contra el frío,\ny er burro me dio una coz\nde paere y mu señor mío.",221,0,34,218,"",3,4,"io",3,0,-1,0,195,195,"487","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0488",17,"A la una canta el gallo,\na las dos la tutuvía,\na las tres el ruiseñor\ny a las cuatro ya es de día.",221,0,34,218,"",0,4,"ia",0,0,-1,0,195,195,"488","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0489",17,"A la una canta er gallo,\na las dos la totuvía,\na las tres tuisquios los pájaros,\ny a las cuatro ya es de día\nsi es en tiempo de verano.",221,0,34,218,"",7,5,"ao",-1,0,-1,0,195,195,"489","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0490",17,"Cuando la perdiz canta,\nnublado viene;\nno hay mejor seña de agua\nque cuando llueve.",221,0,34,218,"",6,4,"ee",-1,0,-1,0,195,195,"490","",0,"","","",4,0,0,[],"",""],["murciano_antiguo-n0491",17,"Sale el sol por la mañana\nmuy triste y muy macilento;\nconforme va entrando el día\nse va poniendo contento.",221,0,34,218,"",0,4,"eo",94,0,-1,0,196,196,"491","",0,"","","",5,0,0,[],"",""],["murciano_antiguo-n0492",17,"Con er tiempo, tú sabrás\ntodo lo que vale el tiempo;\nlo malo es que entonces, ya,\nde na te sirve el sabello.",221,0,34,218,"",0,4,"eo",-1,0,-1,0,196,196,"492","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0493",17,"A la una nací yo,\na las dos me bautizaron,\na las tres tenía novia\ny a las cuatro me casaron.",221,0,34,218,"",0,4,"ao",41,0,-1,0,196,196,"493","",0,"","","",7,0,0,[],"",""],["murciano_antiguo-n0494",17,"Tres cosas en el mundo\ncausan espante:\nterretremos, trimulto\ny el alifante.\nAupa, aupa,\nno es usté la pantasma\nque a mí me asusta.",221,0,34,218,"",4,7,"ua",-1,0,-1,0,197,197,"494","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0495",17,"Tres cosas en er mundo\nme dan espante:\nterretremos, trimultos\ny el alifante;\nanda y no cenes,\nverás por la mañana\nqué cara tienes.",221,0,34,218,"",4,7,"ee",120,0,-1,0,197,197,"495","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0496",17,"Tres cosas en er mundo\nme dan espante:\nterretremo, trimulto\ny el alifante:\na éstos arrima\nel colero, las suegras\ny la morisma.",221,0,34,218,"",4,7,"ia",-1,0,-1,0,197,197,"496","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0497",17,"Tengo yo cuatro cosas\nque no tiés tú:\nexperencia, telutria,\njuerza y salú.",221,0,34,218,"",6,4,"u",73,0,-1,0,198,198,"497","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0498",17,"Lo que priva en este mundo\nes un pañuelo francés,\nuna manta morellana\ny un sombrero calañés.",221,0,34,218,"",0,4,"e",218,0,-1,0,198,198,"498","",0,"","","",4,0,0,[],"",""],["murciano_antiguo-n0499",17,"Lo que priva en este mundo\nes un pañuelo francés,\nuna manta morellana\ny un sombrero cordobés.",221,0,34,218,"",0,4,"e",218,0,-1,0,198,198,"499","",0,"","","",4,0,0,[],"",""],["murciano_antiguo-n0500",17,"Pañuelo a la cabeza,\npañuelo al cuello,\npañuelo en la cintura,\nson tres pañuelos.",221,0,34,218,"",6,4,"eo",-1,0,-1,0,198,198,"500","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0501",17,"¡Válgame Dios del cielo!\n—dijo una niña—\n'¡Lo que descansa un alma\ncuando suspira!'",221,0,34,218,"",6,4,"",-1,0,-1,0,198,198,"501","",0,"rm_t3, palau_cantares","","",8,0,0,[],"",""],["murciano_antiguo-n0502",17,"En mi vida he visto yo\nlo que he visto esta mañana:\nun pajarito en la torre\nrepicando las campanas.",221,0,34,218,"",0,4,"aa",-1,0,-1,0,199,199,"502","",0,"","","",5,0,0,[],"",""],["murciano_antiguo-n0503",17,"Hay salericos de a cuarto,\ny saleros de a real,\ny saleros de a peseta;\nesos sí que tienen sal.",221,0,34,218,"",0,4,"a",1,0,-1,0,199,199,"503","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0504",17,"Compañerica del alma,\nel dinero es muy bonito,\ny a aquel que tiene dinero\nle llaman el señorito.",221,0,34,218,"",0,4,"io",119,0,-1,0,199,199,"504","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0505",17,"El agua si es que s'errama\nnaide la pue recoger,\nni er humo que va po el aire\nni la honra d'una mujer.",221,0,34,218,"",0,4,"e",20,0,-1,0,199,199,"505","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0506",17,"Cuando los de la huerta\nsacan la capa,\ncasamiento, bautizo,\nentierro o trampa.",221,0,34,218,"",6,4,"aa",-1,0,-1,0,200,200,"506","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0507",17,"Cuando los de la huerta\nsacan la capa,\ncasamiento, bautizo,\nentierro o trampa;\ny esto es tan cierto\ncomo pagan al amo\ncon er pimiento.",221,0,34,218,"",4,7,"eo",-1,0,-1,0,200,200,"507","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0508",17,"Aquer que se dé a mujeres\nno llegará a hacer caudal,\nni cosa que menos varga,\nni cosa que cueste más.",221,0,34,218,"",0,4,"a",-1,0,-1,0,200,200,"508","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0509",17,"Hombre qu'alpargates use\ny a la mujer no haga caso,\nnunca tendrá cinco duros\ny siempre andará descarzo.",221,0,34,218,"",0,4,"ao",-1,0,-1,0,200,200,"509","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0510",17,"Er que siempre tuvo un duro\ncree que tiene veinte riales;\ner que lo pidió prestao\nes quien sabe lo que vale.",221,0,34,218,"",0,4,"ae",-1,0,-1,0,201,201,"510","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0511",17,"En una cosa se paecen\ner dinero y la vergüenza:\nqu'ar que la tiene, el guardalla\nmuncho trebajo le cuesta.",221,0,34,218,"",0,4,"ea",-1,0,-1,0,201,201,"511","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0512",17,"Tan probe es quien no tie un duro\ncomo er que lo tie y lo guarda;\nel dinero que no rula\nes como si juá una chapa.",221,0,34,218,"",0,4,"aa",-1,0,-1,0,201,201,"512","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0513",17,"Las del moño zorongo\nduermen en catre,\nporque el moño zorongo\nno se esfarate.",221,0,34,218,"",6,4,"ae",-1,0,-1,0,201,201,"513","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0514",17,"Hay muchas que tienen fea\nla cara, y el cuerpo no;\npero yo lo tengo todo:\nDios de mí no se acordó.",221,0,34,218,"",0,4,"o",2,0,-1,0,202,202,"514","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0515",17,"Me dicen que soy fea,\nyo no me enojo,\nque las feas se llevan\nlos buenos mozos.",221,0,34,218,"",6,4,"oo",-1,0,-1,0,202,202,"515","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0516",17,"La cruz del matrimonio\nes muy pesada,\ny por eso se juntan\ndos a llevarla.",221,0,34,218,"",6,4,"aa",-1,0,-1,0,202,202,"516","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0517",17,"Dice la que no es casada:\n¡qué gusto será el casarse!\nY la casadita dice:\n¡Quién pudiera descasarse!",221,0,34,218,"",0,4,"ae",250,0,-1,0,202,202,"517","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0518",17,"Las mujeres ar mundo\nperdío lo tienen,\ny los hombres ar mundo\ny a las mujeres;\nde esta manera,\nmundo, mujeres y hombres\nperdíos se quean.",221,0,34,218,"",4,7,"ea",-1,0,-1,0,203,203,"518","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0519",17,"A zagales y zagalas\ndos cosas los estropean:\na las zagalas el baile,\ny a los mozos la taberna.",221,0,34,218,"",0,4,"ea",-1,0,-1,0,203,203,"519","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0520",17,"Como la mesma rosa\nson las zagalas:\ncudiao que si las tocas\nno deshojallas;\ny no las tocas\ny rosas y zagalas\nellas s'eshojan.",221,0,34,218,"",4,7,"oa",-1,0,-1,0,203,203,"520","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0521",17,"A las mujeres querellas,\nofrecellas y no dalles,\ntomar lo que quieran ellas,\ny ar mejor tiempo fartalles,\nantes que nos farten ellas.",221,0,34,218,"",7,5,"ea",-1,0,-1,0,204,204,"521","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0522",17,"La mujer es lo mesmo\nque leña verde;\nmuncho humea y muncho llora,\ny ar fin s'empriende;\ny ya encendía,\nsi pierde la vergüenza\n¡Dios nos asista!",221,0,34,218,"",4,7,"ia",-1,0,-1,0,204,204,"522","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0523",17,"Impués qu'hizo Dios al hombre\nle frabicó una mujer;\nprimero es hacer la torre\ny la veleta es pa impués.",221,0,34,218,"",0,4,"e",-1,0,-1,0,204,204,"523","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0524",17,"Quien se fía de mujeres\nd'este mundo poco sabe;\nno hay que fiar de una puerta,\nque tos tenemos la llave.",221,0,34,218,"",0,4,"ae",69,0,-1,0,204,204,"524","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0525",17,"El querer de la mujer\ns'empriende como pajuela:\narde mucho, dura poco,\nmal alumbra y muncho quema.",221,0,34,218,"",0,4,"ea",-1,0,-1,0,205,205,"525","",0,"","","",3,0,0,[],"",""],["murciano_antiguo-n0526",17,"Como las cañas huecas\nson las mujeres,\nque se llenan de aire\ncuando las quieren.",221,0,34,218,"",6,4,"ee",-1,0,-1,0,205,205,"526","",0,"rm_t4, palau_cantares, fernan_caballero","","",4,0,0,[],"",""],["murciano_antiguo-n0527",17,"La mujer y las cuerdas\nde la guitarra,\nsa menester su cencia\npara templallas;\nflojas, no suenan,\ny sartan en siguía\nque las aprietas.",221,0,34,218,"",4,7,"ea",-1,0,-1,0,205,205,"527","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0528",17,"La moza qu'es desanchá\nla comparo a la aceituna:\nque la que crees qu'está verde\npue ser qu'esté más maúra.",221,0,34,218,"",0,4,"ua",-1,0,-1,0,205,205,"528","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0529",17,"No hay qu'acordarse pa na\nde la mujer que fartó;\n¿pa qué es el mirar la piedra\nimpués que se tropezó?",221,0,34,218,"",0,4,"o",2,0,-1,0,206,206,"529","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0530",17,"Quien tie mujer güena moza\ny viña en camino real,\nsi es que las quie pa ér solo\nmuncho tie que vregilar.",221,0,34,218,"",0,4,"a",-1,0,-1,0,206,206,"530","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0531",17,"Los dos trebajos más grandes\nson tener y no tener:\nel tener la mujer fea\ny el no tener qué comer.",221,0,34,218,"",0,4,"e",20,0,-1,0,206,206,"531","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0532",17,"La mujer que sale mala\nno reñille ni pegalle;\nechalla el ramal al cuello\ny ecilla que Dios l'ampare.",221,0,34,218,"",0,4,"ae",-1,0,-1,0,206,206,"532","",0,"","","",7,0,0,[],"",""],["murciano_antiguo-n0533",17,"Manque la mar juera e tinta\ny er cielo juera papel,\nfaltaría pa escrebir\nlo farsa qu'es la mujer.",221,0,34,218,"",0,4,"e",-1,0,-1,0,207,207,"533","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0534",17,"La mujer moza y la pulga\ntién la mesma condición:\npor lo que cuesta er cogellas\ny por picantes que son.",221,0,34,218,"",0,4,"o",31,0,-1,0,207,207,"534","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0535",17,"La vieja es como la pasa\nsi es de güena calidá:\nque tie to su dulzor\nmanque la veas arrugá.",221,0,34,218,"",0,4,"a",9,0,-1,0,207,207,"535","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0536",17,"La mujer y la habichuela\ntienen er mesmo defleuto:\ny es que pa hincalles er diente\nhay que ablandallas primero.",221,0,34,218,"",0,4,"eo",-1,0,-1,0,207,207,"536","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0537",17,"A la mujer cuando es mala\nno la ablandas con cariño:\n¿quién ablandaría una piedra\nremojándola en el río?",221,0,34,218,"",0,4,"io",-1,0,-1,0,208,208,"537","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0538",17,"S'arruga y s'echa a perder\nuna mujer sin cariño:\nson lo mesmo que la bota\nque nesita tener vino.",221,0,34,218,"",0,4,"io",-1,0,-1,0,208,208,"538","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0539",17,"Er mesmo caráuter tienen\nla mujer y la ensalá:\npa encontrallas más bustosas\nhan de estar aderezás.",221,0,34,218,"",0,4,"a",-1,0,-1,0,208,208,"539","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0540",17,"L'aceituna y la mujer\ntienen una mesma farta:\nsi no las cogen a tiempo,\noliva y mujer se pasan.",221,0,34,218,"",0,4,"aa",-1,0,-1,0,208,208,"540","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0541",17,"Las mociquias de hoy en día\nson como las avellanas:\npartes una, partes dos,\ny tuisquias te salen fallas.",221,0,34,218,"",0,4,"aa",-1,0,-1,0,208,208,"541","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0542",17,"El rosal cría sus rosas,\nclavellinas el calvel,\ncomo el padre cría sus hijas\nsin que sepa para quién.",221,0,34,218,"",0,4,"e",-1,0,-1,0,209,209,"542","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0543",17,"Mujer que no tiene hombre\nno pue estar bien aunque quiera;\nson pucheros pa guisar\ny no tienen cobertera.",221,0,34,218,"",0,4,"ea",44,0,-1,0,209,209,"543","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0544",17,"Morena tiene que ser\nla tierra para ser buena;\ny la mujer para el hombre\ntambién ha de ser morena.",221,0,34,218,"",0,4,"ea",59,0,-1,0,209,209,"544","",0,"rm_t2, carrizo_salta, palau_cantares","","",9,0,0,[],"",""],["murciano_antiguo-n0545",17,"Plantón qu'esté bien plantao\nserá una güena olivera;\nla mociquia bien casá\npaece que sigue doncella.",221,0,34,218,"",0,4,"ea",-1,0,-1,0,209,209,"545","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0546",17,"Pa diez gallinas un gallo\ny pa una mujer un hombre;\nlas gallinas van contentas,\nla mujer no está conforme.",221,0,34,218,"",0,4,"oe",-1,0,-1,0,210,210,"546","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0547",17,"De solteras las mujeres\ntién dos onzas de vergüenza,\nimpués que se casan, una;\ny en cuanti que enviudan, media.",221,0,34,218,"",0,4,"ea",-1,0,-1,0,210,210,"547","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0548",17,"La aceituna en er olivo\nsi no la cogen se pasa;\nlo mesmo le está pasando\na la moza de esta casa.",221,0,34,218,"",0,4,"aa",123,0,-1,0,210,210,"548","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0549",17,"Una mujer en pelota\nle paece a un saco e melones,\nque to son bultos y huecos,\nabujeros y rincones.",221,0,34,218,"",0,4,"oe",34,0,-1,0,210,210,"549","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0550",17,"Valen más los zaragüeles\nde los mozos de la huerta,\nque todos los pantalones\nque pasean la Glorieta.",221,0,34,218,"",0,4,"ea",-1,0,-1,0,210,210,"550","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0551",17,"Valen más los zaragüelles\nde los mozos de la güerta,\nque tuisquios los pantalones\nque pasean la Glorieta.",221,0,34,218,"",0,4,"ea",-1,0,-1,0,211,211,"551","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0552",17,"Aquel que lleva levita\ny zapatos de charol,\nel hambre que lleva encima\nno se la quita ni Dios.",221,0,34,218,"",0,4,"o",-1,0,-1,0,211,211,"552","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0553",17,"¡Válgame Dios del cielo!\n—dijo una tuerta—,\n¡La vista recogida\ncuánto penetra!",221,0,34,218,"",6,4,"ea",-1,0,-1,0,211,211,"553","",0,"","","",8,0,0,[],"",""],["murciano_antiguo-n0554",17,"¡Válgame Dios del cielo!\n—dijo un colegial—\n¡Lo que abriga la seda!\ny llevaba un ojal.",221,0,34,218,"",0,4,"a",1,0,-1,0,211,211,"554","",0,"","","",8,0,0,[],"",""],["murciano_antiguo-n0555",17,"Comienzo en nombre de Dios\ny de la Virgen María,\npor ser la primera copla\nque he cantado en este día.",221,0,34,219,"",0,4,"ia",0,0,-1,0,212,212,"555","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0556",17,"Comienzo la primera\nen nombre de Dios;\nperderé la vergüenza\ny alzaré la voz.",221,0,34,219,"",0,4,"o",280,0,-1,0,212,212,"556","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0557",17,"Comienzo la primera\ndiciendo ¡Jesús!\ncomo los escribanos\nhaciendo la cruz.",221,0,34,219,"",0,4,"u",109,0,-1,0,212,212,"557","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0558",17,"La Virgen de la Fuensanta\ncuando pasa por el Puente\nle dice a la Peligrosa:\nsi te quieres venir, vente.",221,0,34,219,"",0,4,"ee",15,0,-1,0,212,212,"558","",0,"","","",3,0,0,[],"",""],["murciano_antiguo-n0559",17,"La Virgen de la Fuensanta\nle dice a la de la Luz:\n¡qué afligido va tu hijo\ncon el peso de la cruz!",221,0,34,219,"",0,4,"u",109,0,-1,0,213,213,"559","",0,"","","",3,0,0,[],"",""],["murciano_antiguo-n0560",17,"Morena es la Virgen de Elche,\nmorena la del Pilar;\npara morena con gracia\nla que hay en la Catedral.",221,0,34,219,"",0,4,"a",-1,0,-1,0,213,213,"560","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0561",17,"La Virgen de la Fuensanta,\nla que está en la Catedral,\nle está pidiendo a su hijo\nque nos libre de este mal.",221,0,34,219,"",0,4,"a",1,0,-1,0,213,213,"561","",0,"","","",3,0,0,[],"",""],["murciano_antiguo-n0562",17,"La Virgen de los Peligros,\nla que está encima del Puente,\nle está pidiendo a su hijo\npor tanto niño inocente.",221,0,34,219,"",0,4,"ee",15,0,-1,0,213,213,"562","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0563",17,"¡Viva San Antonio el Pobre\ny la Virgen de la Luz,\nla Virgen de la Fuensanta,\ny Nuestro Padre Jesús.",221,0,34,219,"",0,4,"u",270,0,-1,0,214,214,"563","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0564",17,"Eres María del Carmen,\ndel Carmen carmelitana;\ndame tus escapularios\nque yo te daré mi alma.",221,0,34,219,"",0,4,"aa",-1,0,-1,0,214,214,"564","",0,"rm_t4","","",2,0,0,[],"",""],["murciano_antiguo-n0565",17,"Tiene la Virgen del Carmen\nen medio de su corona\ndos águilas imperiales\ny el Padre Santo de Roma.",221,0,34,219,"",0,4,"oa",-1,0,-1,0,214,214,"565","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0566",17,"Hermosa Virgen del Carmen,\nvente conmigo a vivir\nmientras que los albañiles\nte arreglan tu camarín.",221,0,34,219,"",0,4,"i",-1,0,-1,0,214,214,"566","",0,"","","",3,0,0,[],"",""],["murciano_antiguo-n0567",17,"¡Cómo quieres que tenga\nrubio el cabello,\nsi la Virgen del Carmen\nlo tiene negro.",221,0,34,219,"",6,4,"eo",-1,0,-1,0,215,215,"567","",0,"","","",14,0,0,[],"",""],["murciano_antiguo-n0569",17,"Virgen del Carmen, valedme;\nSan Antonio, que me muero,\nque tengo una puñalada\nen este ladito izquierdo.",221,0,34,219,"",0,4,"eo",-1,0,-1,0,215,215,"569","",0,"","","",4,0,0,[],"",""],["murciano_antiguo-n0570",17,"A la Virgen del Carmen\nquiero y adoro,\nporque saca las almas\ndel Purgatorio.",221,0,34,219,"",6,4,"oo",-1,0,-1,0,215,215,"570","",0,"palau_cantares, fernan_caballero","","",5,0,0,[],"",""],["murciano_antiguo-n0571",17,"Te quiero como a la Virgen\nqu'está en el altar mayor;\ntú me quiés como la Virgen,\nque ni dice sí ni no.",221,0,34,219,"",0,4,"o",-1,0,-1,0,216,216,"571","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0572",17,"Cuando voy a misa al Carmen\na todos los santos rezo,\ny en llegando a San Antonio\nallí el corazón dejo.",221,0,34,219,"",0,4,"eo",-1,0,-1,0,216,216,"572","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0573",17,"San Antonio de Padua\ntiene un niñito\nque come corazones\ny es muy gordito.",221,0,34,219,"",6,4,"io",119,0,-1,0,216,216,"573","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0574",17,"De San Juan quiero la palma,\nde San Francisco el cordón,\nde Santa Rita la espina;\nde mi amante, el corazón.",221,0,34,219,"",0,4,"o",31,0,-1,0,216,216,"574","",0,"fernan_caballero","","",4,0,0,[],"",""],["murciano_antiguo-n0575",17,"A los pies de Santa Rita\nme quisieron dar la muerte,\ny la Santa milagrosa\nle dijo al traidor: 'detente'.",221,0,34,219,"",0,4,"ee",-1,0,-1,0,217,217,"575","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0576",17,"¿A qué santo llamaré\nque me saque de esta pena?\nLlamaré a San Isidoro\nque es patrón de Cartagena.",221,0,34,219,"",0,4,"ea",59,0,-1,0,217,217,"576","",0,"","","",4,0,0,[],"",""],["murciano_antiguo-n0577",17,"Si vas a San Antolín\ny a la derecha te inclinas,\nverás en su camarín\na la Pastora divina.",221,0,34,219,"",0,4,"ia",-1,0,-1,0,217,217,"577","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0578",17,"Si vas a San Cayetano\ntráeme un San Cayetanico,\nno me lo traigas muy grande\nque lo quiero pequeñico.",221,0,34,219,"",0,4,"io",141,0,-1,0,217,217,"578","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0579",17,"De San Cayetano vengo\nde cumplir una promesa,\ny ahora que vengo santo\ndame la mano, Teresa.",221,0,34,219,"",0,4,"ea",201,0,-1,0,218,218,"579","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0580",17,"Toda mi vida rezando\npara la gloria alcanzar,\ny ahora me he condenado\n¡para qué tanto rezar!",221,0,34,219,"",0,4,"a",21,0,-1,0,218,218,"580","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0581",17,"Un paere cura m'ha dicho\nque me condeno por ti;\nmirosté qu'es juerte cosa,\nvivir mal y mal morir.",221,0,34,219,"",0,4,"i",-1,0,-1,0,218,218,"581","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0582",17,"Por el Cristo de las Penas,\nque está en el monte Calvario,\nsi tú te mantienes firme\nmira que yo no me caigo.",221,0,34,219,"",0,4,"ao",-1,0,-1,0,218,218,"582","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0583",17,"Republicanos valientes,\nandaver a San Antón,\na cortarle la cabeza\nal que levante la voz.",221,0,34,220,"",0,4,"o",-1,0,-1,0,219,219,"583","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0584",17,"Antonete está en la sierra\ny no se quiere entregar,\ny sus hijas le decían:\nentréguese usted, papá.",221,0,34,220,"",0,4,"a",-1,0,-1,0,219,219,"584","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0585",17,"Ya va el batallón de Reus\na la Cruz de Miravete,\nen busca de un cabecilla\nque le llaman Antonete.",221,0,34,220,"",0,4,"ee",285,0,-1,0,219,219,"585","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0586",17,"En la Plaza de Palacio\nhan puesto ya un calamar,\ncon un letrero que dice:\nAmadeo que se va.",221,0,34,220,"",0,4,"a",-1,0,-1,0,220,220,"586","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0587",17,"Hasta la Virgen del Carmen\nse ha vuelto republicana,\nporque no quiere que manden\nlos carlistas en España.",221,0,34,220,"",0,4,"aa",-1,0,-1,0,220,220,"587","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0588",17,"¡Cartagena, Cartagena,\nno supieron darte nombre,\npues te debieron llamar\ndefensa de los cantones!",221,0,34,220,"",0,4,"oe",-1,0,-1,0,220,220,"588","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0589",17,"La muralla en Cartagena\nestá toda coroná\nde cañones de remington\npara el cantón federal.",221,0,34,220,"",0,4,"a",-1,0,-1,0,220,220,"589","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0590",17,"Vámonos a Cartagena\na ver la estrella con rabo,\ny veremos pelear\na Antonete con Serrano.",221,0,34,220,"",0,4,"ao",-1,0,-1,0,221,221,"590","",0,"","","",4,0,0,[],"",""],["murciano_antiguo-n0591",17,"¡Cuándo querrá Dios del cielo\nque se vayan los rurales,\nque vayamos a la huerta\na comer higos verdales!",221,0,34,220,"",0,4,"ae",26,0,-1,0,221,221,"591","",0,"","","",11,0,0,[],"",""],["murciano_antiguo-n0592",17,"Tiene usté más fantesía\nque el coche del intendente,\ny usté no vale un cigarro\nni ninguno de su gente.",221,0,34,220,"",0,4,"ee",15,0,-1,0,221,221,"592","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0593",17,"El día que a mí me digan\nque la Numancia se va,\nmis ojos serán dos ríos\ny mi casa un hospital.",221,0,34,220,"",0,4,"a",-1,0,-1,0,221,221,"593","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0594",17,"Los del Barrio, liberales;\nlos de San Antón facciosos;\ny los de San Antolín,\nrepublicanos hermosos.",221,0,34,220,"",0,4,"oo",186,0,-1,0,222,222,"594","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0595",17,"Yo nací en el Garbanzal,\nbautizao en las Herrerías,\ny al que pregunte por mí:\nme llamo José María,\nde Antonete cornetín.",221,0,34,220,"",7,5,"i",-1,0,-1,0,222,222,"595","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0596",17,"Si el castillo de Talayo\nse pudiera derribar,\na mi amante que está allí\nle diera la libertad.",221,0,34,220,"",0,4,"a",-1,0,-1,0,222,222,"596","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0597",17,"Castillo de la Rivera,\nmira cómo no disparas,\nque ya no pasa mi amante\ncon banderas encarnadas.",221,0,34,220,"",0,4,"aa",-1,0,-1,0,223,223,"597","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0599",17,"Voy a pedille una gracia\nabora que manda Antón:\nque por medio e mis bancales\nvaya la Cieca Mayor.",221,0,34,220,"",0,4,"o",-1,0,-1,0,223,223,"599","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0600",17,"Antonete en Cartagena\ntie tres fragatas chapás,\ny una bandera que dice:\n'República federal'.",221,0,34,220,"",0,4,"a",-1,0,-1,0,223,223,"600","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0601",17,"Soy choripé y no lo niego,\ncuando monto en mi caballo\naunque me peguen un tiro\nmuero por los columnarios.",221,0,34,220,"",0,4,"ao",-1,0,-1,0,224,224,"601","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0602",17,"Por decir 'alza pilille'\nme metieron en la cárcel;\nalza pilille y no temas,\nno faltará quién te saque.",221,0,34,220,"",0,4,"ae",-1,0,-1,0,224,224,"602","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0603",17,"Dengún hombre hay en er mundo\nque sin trabajos se encuentre:\nqu'hasta el que no tie trabajo\nbastante trabajo tiene.",221,0,34,221,"",0,4,"ee",-1,0,-1,0,224,224,"603","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0604",17,"Madre mía, los mineros\nqué buenos mozos que son,\npero tienen una falta:\nque mueren sin confesión.",221,0,34,221,"",0,4,"o",31,0,-1,0,224,224,"604","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0605",17,"Quiéreme que soy minero\nde las minas de Portmán,\ny en ganando una peseta\nya tengo pa comprar pan.",221,0,34,221,"",0,4,"a",147,0,-1,0,225,225,"605","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0606",17,"Quiéreme que soy minero\nde las minas de allí enfrente,\ny me he de casar contigo\naunque no quiera tu gente.",221,0,34,221,"",0,4,"ee",15,0,-1,0,225,225,"606","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0607",17,"Es mi marido minero\nque trabaja en una mina,\ny a mí me entrega el dinero\nporque soy canela fina.",221,0,34,221,"",1,4,"ia",11,0,-1,0,225,225,"607","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0608",17,"Herrerías, Herrerías,\nHerrerías de Cartagena,\nel que no ha sido minero\nno sabe lo que son penas.",221,0,34,221,"",0,4,"ea",-1,0,-1,0,225,225,"608","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0609",17,"Parecen las pulidoras\ncuando salen de pulir\na los toritos navarros\ncuando salen del toril.",221,0,34,221,"",0,4,"i",-1,0,-1,0,226,226,"609","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0610",17,"El farol de mi placeta\nse está muriendo de risa\nde ver las alpargateras,\ntalle alto y sin camisa.",221,0,34,221,"",0,4,"ia",68,0,-1,0,226,226,"610","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0611",17,"Lo quiero carpintero\nque saque astillas.\nSí, hija, que las saque\nde tus costillas.",221,0,34,221,"",6,4,"ia",294,0,-1,0,226,226,"611","",0,"","","",3,0,0,[],"",""],["murciano_antiguo-n0612",17,"Llevan los basureros\ndentro la faja\nuna vara de freno\ny una navaja.",221,0,34,221,"",6,4,"aa",393,0,-1,0,226,226,"612","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0613",17,"Soy basurero con honra,\ny anque anguna ves m'escurra,\nni le farto a las criás\nni a mi probetiquia burra.",221,0,34,221,"",0,4,"ua",724,0,-1,0,226,226,"613","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0614",17,"Hay en Murcia, señores,\nun confitero\nque pa er trabajo el hombre\nno tiene pero;\npero en Zeneta\ner sacristán y er cura\nhacen carceta.",221,0,34,221,"",4,7,"ea",200,0,-1,0,227,227,"614","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0615",17,"Panadero soy, señora,\ntrabajo en el Horno Nuevo;\nde día te vengo a ver,\nporque de noche no puedo.",221,0,34,221,"",0,4,"eo",-1,0,-1,0,227,227,"615","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0616",17,"Los currillos panaderos,\nllevan rico pantalón,\ny a las dos de la mañana\nmaldicen al artesón.",221,0,34,221,"",0,4,"o",31,0,-1,0,227,227,"616","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0617",17,"La despedida te doy,\nla que da el mozo del horno,\ncon la rosquilla en la mano;\n¿la quieres o me la como?",221,0,34,221,"",0,4,"oo",-1,0,-1,0,227,227,"617","",0,"","","",9,0,0,[],"",""],["murciano_antiguo-n0618",17,"Toma, niña, esa tumbaga,\nque te la da un panadero,\ny mira no te se vuelva\nel artesón y el caldero.",221,0,34,221,"",0,4,"eo",38,0,-1,0,228,228,"618","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0619",17,"Hágame usted unos zapatos\ncon el tacón que levante,\nque soy pequeña y no alcanzo\na los brazos de mi amante.",221,0,34,221,"",0,4,"ae",47,0,-1,0,228,228,"619","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0620",17,"Hágame usté unos zapatos\nde Alicante, alicantinos;\nsi son de Murcia, murcianos,\ny si de Lorca, lorquinos.",221,0,34,221,"",0,4,"io",206,0,-1,0,228,228,"620","",0,"","","",4,0,0,[],"",""],["murciano_antiguo-n0621",17,"Por allí viene mi barco,\nque lo conozco en la vela,\ny en el palo mayor trae\nmemorias de mi morena.",221,0,34,221,"",0,4,"ea",-1,0,-1,0,228,228,"621","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0622",17,"A los carabineros\nno les des agua,\nporque con el bigote\nrompen la jarra.",221,0,34,221,"",6,4,"aa",-1,0,-1,0,229,229,"622","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0623",17,"No tiene el Príncipe Alfonso\nen medio de su jardín\nuna flor que brille tanto\ncomo la Guardia Civil.",221,0,34,221,"",0,4,"i",-1,0,-1,0,229,229,"623","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0624",17,"Acaba de dar, acaba,\nreloj de la Catedral,\nque está mi amante de guardia\ny lo van a relevar.",221,0,34,221,"",0,4,"a",-1,0,-1,0,229,229,"624","",0,"","","",8,0,0,[],"",""],["murciano_antiguo-n0629",17,"Yo no sé cavar ni arar,\nni tampoco coger yerba;\ncásate, niña, conmigo,\nverás qué gandul te llevas.",221,0,34,221,"",0,4,"ea",-1,0,-1,0,231,231,"629","",0,"","","",5,0,0,[],"",""],["murciano_antiguo-n0630",17,"Yo no sé cavar ni arar\nni tampoco coger yerba;\ncásate, Paca, conmigo,\nverás qué gandul te llevas.",221,0,34,221,"",0,4,"ea",-1,0,-1,0,231,231,"630","",0,"","","",5,0,0,[],"",""],["murciano_antiguo-n0631",17,"Yo no sé cavar ni arar,\nni tampoco segar trigo;\nbuen mindanguico se lleva\nla que se case conmigo.",221,0,34,221,"",0,4,"io",106,0,-1,0,231,231,"631","",0,"","","",5,0,0,[],"",""],["murciano_antiguo-n0633",17,"A curro no hay quien me gane\nni a ponerme la montera,\npero en llegando al trabajo\ntengo muy mala manera.",221,0,34,221,"",0,4,"ea",44,0,-1,0,232,232,"633","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0634",17,"Si er pijotero der sol\nse metiera a jornalero,\nno madrugaría tanto\ny andaría más ligero.",221,0,34,221,"",0,4,"eo",38,0,-1,0,232,232,"634","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0635",17,"No hay mejor tierra en er mundo\nque la tierra cuando es negra,\nni reja con más virtú\nque la reja sanjuanera.",221,0,34,221,"",0,4,"ea",-1,0,-1,0,232,232,"635","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0636",17,"Munchos hay en este mundo\nque quién coger sin sembrar;\ner que no siembra, no coge;\nque ya lo dice un refrán.",221,0,34,221,"",0,4,"a",-1,0,-1,0,232,232,"636","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0637",17,"De cinco, marrará una\nel que hace siembra trempano;\ny aquer que siembra tardío,\nde cinco marra las cuatro.",221,0,34,221,"",0,4,"ao",-1,0,-1,0,233,233,"637","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0638",17,"Er que siembra mala tierra\nmal fruto habrá de coger;\nel trigo se güerve piedras\ny no pue prevalecer.",221,0,34,221,"",0,4,"e",20,0,-1,0,233,233,"638","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0639",17,"Soy labrador y tengo\ntahúlla y media,\ny le digo a mi perro:\nanda a la hacienda.",221,0,34,221,"",6,4,"ea",-1,0,-1,0,233,233,"639","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0640",17,"Soy labraor y tengo\ntahúlla y media,\ny le igo a mi perro:\n¡vete a la hacienda!",221,0,34,221,"",6,4,"ea",-1,0,-1,0,233,233,"640","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0641",17,"El que labra con burras\ny come bollo,\nno pasa por las penas\ndel purgatorio.",221,0,34,221,"",6,4,"oo",-1,0,-1,0,234,234,"641","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0642",17,"To aquer que labra con burras,\ny a to comer, come bollo,\nse muere y se va a la gloria;\nqu'aquí pasó er purgatorio.",221,0,34,221,"",0,4,"oo",-1,0,-1,0,234,234,"642","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0643",17,"Con burras hago el surco\nde mis barbechos;\nvenga a ver el que quiera\nsi están derechos;\ny no hay más cencia\npa sacarlos asina\nque la pacencia.",221,0,34,221,"",4,7,"ea",46,0,-1,0,234,234,"643","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0644",17,"Una estrella en la frente\ntiene mi burra;\nhasta los animales\ntienen fortuna.",221,0,34,221,"",6,4,"ua",-1,0,-1,0,234,234,"644","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0645",17,"Una estrella en la frente\ntiene mi burra;\ndista los alimales\ntienen fortuna.\nYo soy der campo,\ny gano una peseta\ncuando trabajo.",221,0,34,221,"",4,7,"ao",-1,0,-1,0,235,235,"645","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0646",17,"Yo soy amo de mi burra\ny hace lo que mando yo;\ncuando quiero, digo: ¡arre!;\nsi me parece, digo: ¡sooo!",221,0,34,221,"",3,4,"oo",-1,0,-1,0,235,235,"646","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0647",17,"Las penas que pasa un perro\ncuando le cortan el rabo,\nesas mesmas paso yo\nen ca cornijal que saco.",221,0,34,221,"",0,4,"ao",2,0,-1,0,235,235,"647","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0648",17,"¡Várgame Dios de los cielos,\nqué penosiquio alimal!\nSi no le pegas, no alantas;\nsi le pegas s'hace atrás.",221,0,34,221,"",0,4,"a",-1,0,-1,0,235,235,"648","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0649",17,"Aquer que labra con mulas\nno diga que pasa penas,\ny aquel que labra con burras,\ntrebaja tanto como ellas.",221,0,34,221,"",0,4,"ea",-1,0,-1,0,236,236,"649","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0650",17,"Pa el oficio de labraor\nsa mester poca arvirtencia;\nqu'en el labrar yunto y hondo\nestá encerrá toa la cencia.",221,0,34,221,"",0,4,"ea",46,0,-1,0,236,236,"650","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0651",17,"¡Acaba de dar, acaba,\nreló de la Catedral!\nque está mi novio regando\ny su tanda va a acabar.",221,0,34,221,"",0,4,"a",-1,0,-1,0,236,236,"651","",0,"","","",8,0,0,[],"",""],["murciano_antiguo-n0652",17,"Incia San Juan de junio\ntrilla del güertano,\ny en er tiempo e la trilla\ns'asan los pájaros:\n¡Arre, Pulía!\nsi pa ti no es la parva\ntampoco es mía.",221,0,34,221,"",4,7,"ia",0,0,-1,0,236,236,"652","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0653",17,"La Pulía y la Gitana\ns'asan trillando,\nsin saber que pa ellas\nno quea ni un grano:\n¡Arre, alimales!\nque también trilla y s'asa\ner que lo sabe.",221,0,34,221,"",4,7,"ae",-1,0,-1,0,237,237,"653","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0654",17,"Er tendero y er méico,\nlas contriuciones,\nel albéitar, las Animas,\naflegiores:\n¡Arre, Gitana!\nCuántos son pa comerse\nmi probe parva.",221,0,34,221,"",4,7,"aa",-1,0,-1,0,237,237,"654","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0655",17,"Más de milenta hombres\nqu'están trillando\npiensan en lo que piensa\neste güertano:\npiensa ca uno\nen que será un milagro\nsi le quea un duro.",221,0,34,221,"",4,7,"uo",-1,0,-1,0,237,237,"655","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0656",17,"Ninguno plante viña\njunto a camino,\nporque to el que pasa\ncorta un racimo.",221,0,34,221,"",6,4,"io",-1,0,-1,0,238,238,"656","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0657",17,"Denguno plante viña\njunto a una senda,\npoique to aquer que pasa\ncoge y se lleva.",221,0,34,221,"",6,4,"ea",-1,0,-1,0,238,238,"657","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0658",17,"A Santiago y Santa Ana\npintan las uvas,\ny a la Virgen de agosto\nya están maduras.",221,0,34,221,"",6,4,"ua",-1,0,-1,0,238,238,"658","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0659",17,"Por San Juan y San Pedro\npintan las uvas,\ny pa er quince d'agosto\nya están maúras.",221,0,34,221,"",6,4,"ua",-1,0,-1,0,238,238,"659","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0660",17,"Las uviquias de tu parra\nestán gritando: ¡comerme!,\npero los pámpanos dicen:\n¡que viene el guarda, que viene!",221,0,34,221,"",0,4,"ee",-1,0,-1,0,239,239,"660","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0661",17,"Mi amante está segando\ncon tanto calor,\n¿quién pudiera ponerle\ncortinas al sol?",221,0,34,221,"",0,4,"o",-1,0,-1,0,239,239,"661","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0662",17,"Mi novio está segando\ncon esta calor,\n¡quién pudiá ponelle\ncortinilla ar sol!",221,0,34,221,"",0,4,"o",-1,0,-1,0,239,239,"662","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0663",17,"A las olivericas\nvoy esta tarde,\na ver cómo menea\nla oliva el aire.",221,0,34,221,"",6,4,"ae",-1,0,-1,0,239,239,"663","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0664",17,"A los higos de pala\nle llaman chumbos,\ny a los de las higueras\nhigos maduros.",221,0,34,221,"",6,4,"uo",-1,0,-1,0,239,239,"664","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0665",17,"A los higos de pala\nles llaman chumbos,\ny a los de las higueras\nhigos maúros.\nY er estribillo:\ntanimientras m'acuerdo\ndenguno digo.",221,0,34,221,"",4,7,"io",-1,0,-1,0,240,240,"665","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0667",17,"Verde ha de ser el pimiento\ny er tomate colorao,\ner pepino gordo y liso\ny el higo negro y rayao.",221,0,34,221,"",3,4,"ao",98,0,-1,0,240,240,"667","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0668",17,"¡Lo que siente un melonero\nque le cojan un melón,\ny más si lo está guardando\ndesde la primera flor!",221,0,34,221,"",0,4,"o",-1,0,-1,0,240,240,"668","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0669",17,"En los granos de un buen año\nse remedian tres de daño;\ny en cada cinco, hay contaos\nuno tal cual, otro bueno\ny tres malos remataos.",221,0,34,221,"",7,5,"ao",342,0,-1,0,241,241,"669","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0670",17,"A mi trigo le ha dao roya;\na mi panizo, busano;\na mi novia calenturas;\nya no me caso ogaño.",221,0,34,221,"",0,4,"ao",-1,0,-1,0,241,241,"670","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0671",17,"Salero, viva el potaje\ny mueran las habichuelas,\nque ayer tarde supe yo\nque se guisan con acelgas.",221,0,34,221,"",0,4,"ea",-1,0,-1,0,241,241,"671","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0672",17,"Si tuviéramos aceite,\najos, cominos y sal,\nharíamos una sopica...\n¡pero si nos falta el pan!",221,0,34,221,"",0,4,"a",-1,0,-1,0,241,241,"672","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0673",17,"Una recién casada\npuso una olla,\ncon un cántaro de agua\ny una cebolla.",221,0,34,221,"",6,4,"oa",453,0,-1,0,242,242,"673","",0,"","","",4,0,0,[],"",""],["murciano_antiguo-n0674",17,"Releñe, qué gordo estoy,\nque tengo cara de tolmo;\ntengo que icille a mi madre\nque no amase tanto bollo.",221,0,34,221,"",0,4,"oo",-1,0,-1,0,242,242,"674","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0675",17,"Barriendo no se canta,\ncosiendo menos;\nporque el cantar se guarda\npara en cerniendo.",221,0,34,221,"",6,4,"eo",-1,0,-1,0,242,242,"675","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0676",17,"En un arroyo de agua\nlavaba la chacha mía,\ny yo de verla lavar\nla baba me se caía.",221,0,34,221,"",0,4,"ia",0,0,-1,0,242,242,"676","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0677",17,"Paso río, paso fuentes,\nsiempre te encuentro lavando;\neres el hechizo mío,\nque me vas aniquilando.",221,0,34,221,"",0,4,"ao",33,0,-1,0,243,243,"677","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0678",17,"Por debajo de esta puerta\nse ven los ojos de un gato;\nesta sí que es buena casa,\nque nos darán pan y blanco.",221,0,34,221,"",0,4,"ao",-1,0,-1,0,243,243,"678","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0679",17,"Por debajo de esta puerta\nse ve un montón de ceniza;\nesta sí que es buena casa,\nque nos darán longaniza.",221,0,34,221,"",0,4,"ia",420,0,-1,0,243,243,"679","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0680",17,"Si mi marido se muere\nno es por falta de alimento,\nque a la cabecera tiene\ndos tomates y un pimiento.",221,0,34,221,"",0,4,"eo",94,0,-1,0,243,243,"680","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0681",17,"Si tu marío te se muere\nno es por farta d'alimento;\nqu'a a la cabecera tiene\ndos tomates y un pimiento.",221,0,34,221,"",0,4,"eo",94,0,-1,0,244,244,"681","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0682",17,"En la huerta de Murcia\npor un chaviquio,\nme llenan de tomates\nel canastiquio.",221,0,34,222,"",6,4,"io",720,0,-1,0,244,244,"682","",0,"","","",4,0,0,[],"",""],["murciano_antiguo-n0683",17,"En la güerta de Murcia\npor un chavíquio\nte llenan la montera\nde tomatiquios.",221,0,34,222,"",6,4,"io",-1,0,-1,0,244,244,"683","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0684",17,"En la güerta de Murcia\npor un chaviquio\nte jartas de tomates\ny pimentiquios.",221,0,34,222,"",6,4,"io",-1,0,-1,0,244,244,"684","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0685",17,"En la huerta de Murcia,\ncomo hay moreras,\nse crían las muchachas\nmuy sandungueras.",221,0,34,222,"",6,4,"ea",103,0,-1,0,245,245,"685","",0,"","","",4,0,0,[],"",""],["murciano_antiguo-n0686",17,"En la huerta de Murcia,\ncomo hay moreras,\nse crían unas mozas\nmu sandungueras;\nandar, andicho,\nsi tú no lo sabías,\nya te lo han dicho.",221,0,34,222,"",4,7,"io",623,0,-1,0,245,245,"686","",0,"","","",4,0,0,[],"",""],["murciano_antiguo-n0687",17,"En el campo se cría\nla mejorana,\ny en la huerta de Murcia\nla mejor dama.",221,0,34,222,"",6,4,"aa",-1,0,-1,0,245,245,"687","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0688",17,"Cuatro cosas tiene Murcia\nque no las hay en España:\nel Malecón, la Glorieta,\nel casino y las muchachas.",221,0,34,222,"",0,4,"aa",-1,0,-1,0,245,245,"688","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0689",17,"¡Si el río Segura\nfuera de vino,\ny la torre de Murcia\nfuera cuartillo!",221,0,34,222,"",6,4,"io",-1,0,-1,0,246,246,"689","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0690",17,"Poique tienen las murcianas\nla mier de Dios en los labios,\ny en la puntiquia e la lengua\nazúcar, canela y clavo.",221,0,34,222,"",0,4,"ao",-1,0,-1,0,246,246,"690","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0691",17,"Llevan las cartageneras\nla sal de Dios en los labios,\ny en la punta de la lengua\nazúcar, canela y clavo.",221,0,34,222,"",0,4,"ao",-1,0,-1,0,246,246,"691","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0692",17,"Por esta calle que vamos\ntiran agua y salen rosas,\ny por eso la llamamos\nla calle de las hermosas.",221,0,34,222,"",1,4,"oa",61,0,-1,0,246,246,"692","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0693",17,"A la calle de la Gloria\nme tengo de ir a vivir,\nporque dicen que se gana\nla gloria antes de morir.",221,0,34,222,"",0,4,"i",157,0,-1,0,247,247,"693","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0694",17,"En la calle de la Gloria\nhay un farol encendido,\ny lo tengo que apagar\naunque me peguen un tiro.",221,0,34,222,"",0,4,"io",-1,0,-1,0,247,247,"694","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0695",17,"En la calle de la Gloria\nhay toreros y toreras,\ny en el callejón del Moro\nestán las banderilleras.",221,0,34,222,"",0,4,"ea",103,0,-1,0,247,247,"695","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0696",17,"Viva mi barrio florido,\nla calle de la Morera,\ncallejón de San Benito,\nCuesta de la Magdalena.",221,0,34,222,"",0,4,"ea",-1,0,-1,0,247,247,"696","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0697",17,"Viva mi barrio lucido,\nbarrio de la Trinidad,\ny también digo que viva\nquien es causa de mi mal.",221,0,34,222,"",0,4,"a",-1,0,-1,0,248,248,"697","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0698",17,"Las muchachas del Barrio\nson el demonio;\nal Berrugo del Carmen\nle han hecho un moño.",221,0,34,222,"",6,4,"oo",-1,0,-1,0,248,248,"698","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0699",17,"Dicen que van a quitar\nlas campanitas del Carmen;\neste año no será;\nel que viene, Dios lo sabe.",221,0,34,222,"",0,4,"ae",-1,0,-1,0,248,248,"699","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0700",17,"El Señor murió en el árbol,\nen el árbol de la cruz;\nyo vivo calle del Arbol,\nsólo porque vives tú.",221,0,34,222,"",0,4,"u",-1,0,-1,0,248,248,"700","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0701",17,"Las Ericas no me quieren,\nla Puerta Nueva me llama,\ny el Barrio de San Benito\nme dice que no me vaya.",221,0,34,222,"",0,4,"aa",-1,0,-1,0,249,249,"701","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0702",17,"A la subida del Puente\nunos ojos negros vi;\nde quién eran, no me acuerdo;\nque me cautivaron, sí.",221,0,34,222,"",0,4,"i",23,0,-1,0,249,249,"702","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0703",17,"En la Puerta de Castilla\ny barrio de San Andrés,\nhan sacado un estribillo:\n'¡anda que te quiero ver!'",221,0,34,222,"",5,4,"",-1,0,-1,0,249,249,"703","",0,"","","",3,0,0,[],"",""],["murciano_antiguo-n0704",17,"En la Puerta de Castilla\ny barrio de San Antón,\nhan sacado un estribillo:\n'¡anda, que te vea yo!'",221,0,34,222,"",5,4,"",-1,0,-1,0,250,250,"704","",0,"","","",3,0,0,[],"",""],["murciano_antiguo-n0705",17,"En la calle de la Aurora\ndicen que no vive nadie:\nvive la luna y el sol\ny el lucero cuando sale.",221,0,34,222,"",0,4,"ae",-1,0,-1,0,250,250,"705","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0706",17,"Mira si he corrido tierras,\nque he estado en el Arenal,\nen la Puerta de Castilla\ny en la calle de la Sal.",221,0,34,222,"",0,4,"a",1,0,-1,0,250,250,"706","",0,"","","",15,0,0,[],"",""],["murciano_antiguo-n0707",17,"Mira si he corrido tierras,\nque he estado en San Antolín,\nen la calle de la Sal\ny en las Eras del Belchí.",221,0,34,222,"",0,4,"i",-1,0,-1,0,251,251,"707","",0,"","","",15,0,0,[],"",""],["murciano_antiguo-n0708",17,"Calle de San Antolín,\ncuántas veces te he rondado,\ny las que te rondaré\nsi no me llevan soldado.",221,0,34,222,"",0,4,"ao",14,0,-1,0,251,251,"708","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0709",17,"Viva mi barrio lucido,\nbarrio de la Condomina,\ndonde tengo mis amigos,\nmis amores y mis primas.",221,0,34,222,"",0,4,"ia",-1,0,-1,0,251,251,"709","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0710",17,"Vente conmigo, chavala,\na la Puerta de Orihuela,\ny serás bien recibida\npor toda mi parentela.",221,0,34,222,"",0,4,"ea",167,0,-1,0,251,251,"710","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0711",17,"La Fábrica de la Seda,\nel día que se quemó,\nestaba el obispo Barrio\nechando la bendición.",221,0,34,222,"",0,4,"o",-1,0,-1,0,252,252,"711","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0712",17,"Adiós, Fábrica de Seda,\ncon ventanas y balcones;\nadiós, Antonia del alma,\nque robas los corazones.",221,0,34,222,"",0,4,"oe",34,0,-1,0,252,252,"712","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0713",17,"La calle de la Morera\nno la pasean chavales,\nla pasean buenos mozos\ncon navajas y puñales.",221,0,34,222,"",0,4,"ae",26,0,-1,0,252,252,"713","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0714",17,"Esta guitarra es de pino\ny la tapa es de nogal,\ny el muchacho que la toca\nes del barrio de San Juan.",221,0,34,222,"",0,4,"a",-1,0,-1,0,252,252,"714","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0715",17,"¡Adiós, calle de Victorio,\nPlaceta de la Merced,\nPlaza de Santo Domingo!\n¿cuándo te volveré a ver?",221,0,34,222,"",0,4,"e",-1,0,-1,0,253,253,"715","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0716",17,"La calle de la botica\nle he de poner a tu calle;\nmira bien con quién platicas\ny no murmures de nadie.",221,0,34,222,"",0,4,"ae",-1,0,-1,0,253,253,"716","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0717",17,"En la calle de Canales\nme se cayó la montera,\ny la recogí diciendo:\nen callando no hay quimera.",221,0,34,222,"",0,4,"ea",44,0,-1,0,253,253,"717","",0,"","","",3,0,0,[],"",""],["murciano_antiguo-n0718",17,"Esta calle es la del Cuerno,\nsi la vista no me engaña:\nsoldados en las esquinas\ny monas en las ventanas.",221,0,34,222,"",0,4,"aa",-1,0,-1,0,253,253,"718","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0719",17,"No semos de la Alboleja,\nni tampoco de Belchí;\nsemos de la Albatalía\ny venimos por aquí.",221,0,34,222,"",0,4,"i",23,0,-1,0,254,254,"719","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0720",17,"No semos de la Arboleja,\nni tampoco de Belchí;\nsemos de la Albatalía\nlos que venimos aquí.",221,0,34,222,"",0,4,"i",23,0,-1,0,254,254,"720","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0721",17,"Las muchachas de La Ñora\nhan comido pimentones,\ny toda la noche están\ncon el cuerpo a restregones.",221,0,34,222,"",0,4,"oe",34,0,-1,0,254,254,"721","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0722",17,"Las zagalas de La Ñora\nhan comío pimentones,\ny por la noche s'están\neshaciendo a restregones.",221,0,34,222,"",0,4,"oe",34,0,-1,0,254,254,"722","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0723",17,"Las zagalas del Rincón\nviven bien arrinconás;\nque en los rincones se crían\nlas mejores ensalás.",221,0,34,222,"",0,4,"a",51,0,-1,0,255,255,"723","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0724",17,"¡Si serán güenos mozos\nlos de la Herrera,\nque cogen los tomates\ncon escalera!",221,0,34,222,"",6,4,"ea",44,0,-1,0,255,255,"724","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0725",17,"En Espinardo, tenajas;\nen Maciascoque, librillos;\nen La Ñora, pimentones;\ny en er Javalí, cochinos.",221,0,34,222,"",0,4,"io",-1,0,-1,0,255,255,"725","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0726",17,"En er Cabezo de Torres\nhay una juente que mana\nfantesía, poca ropa,\npoco pan y muncha gana.",221,0,34,222,"",0,4,"aa",4,0,-1,0,256,256,"726","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0727",17,"En er Cabezo de Torres\nhay una juente que mana\nfantesía y pocos cuartos,\npoco pan y muncha gana.",221,0,34,222,"",0,4,"aa",4,0,-1,0,256,256,"727","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0728",17,"¡Villanueva y Ulea,\nOjós y Blanca!\nQué cuatro lugariquios\npara una trampa.",221,0,34,222,"",6,4,"aa",-1,0,-1,0,256,256,"728","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0729",17,"En la Alberca sale el sol\ny en Algezares la luna,\ny en el Lugar de Don Juan\nno sale cosa denguna.",221,0,34,222,"",0,4,"ua",56,0,-1,0,256,256,"729","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0730",17,"Beniaján y Los Garres\ny Torreagüera.\nVaya tres lugariquios\nsi el rey los viera.",221,0,34,222,"",6,4,"ea",44,0,-1,0,257,257,"730","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0731",17,"Llevan las de Algezares\nen el delantal\nun letrero que dice:\n¡Viva Gibraltar!",221,0,34,222,"",0,4,"a",-1,0,-1,0,257,257,"731","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0732",17,"El camino de los Garres\nlo tengo que enladrillar,\ncon clavellinas de a cuarto\ny rosicas de a real.",221,0,34,222,"",0,4,"a",-1,0,-1,0,257,257,"732","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0733",17,"Ya no voy a Pozo Estrecho,\nni a Pacheco ni a La Palma,\nporque las mozas de aquí\nme llevan robada el alma.",221,0,34,222,"",0,4,"aa",125,0,-1,0,257,257,"733","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0734",17,"Ya han puesto reló en Sucina\npor tener comodidá,\npa saber la hora qu'es\ncuando se van a acostar.",221,0,34,222,"",0,4,"a",-1,0,-1,0,258,258,"734","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0735",17,"Al pasar por la Marina\nvuelvo los ojos llorando...\n¡Ay, mocicas de Sucina,\nqué lejos os vais quedando!",221,0,34,222,"",1,4,"ao",33,0,-1,0,258,258,"735","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0736",17,"Vámonos al Avellano\na beber agua fresquita,\nque han dicho que tiene usted\nla flor de la canelita.",221,0,34,222,"",0,4,"ia",50,0,-1,0,258,258,"736","",0,"","","",4,0,0,[],"",""],["murciano_antiguo-n0737",17,"Cartagena me da pena\ny Murcia me da dolor;\nCartagena de mi vida,\nMurcia de mi corazón.",221,0,34,222,"",0,4,"o",-1,0,-1,0,258,258,"737","",0,"rm_t4, carrizo_salta, palau_cantares, lafuente_madrid","","",5,0,0,[],"",""],["murciano_antiguo-n0738",17,"¡Cartagena, Cartagena,\nbien te puedes alabar,\nque siendo Murcia tan grande\nno tiene puerto de mar!",221,0,34,222,"",0,4,"a",21,0,-1,0,259,259,"738","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0739",17,"Entre Cartagena y Murcia\nse me perdió el corazón;\nyo lo buscaba en er Muelle\ny estaba en el Malecón.",221,0,34,222,"",0,4,"o",31,0,-1,0,259,259,"739","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0740",17,"Cartagena con su Muelle,\nMurcia con su Malecón,\nno tienen tanta firmeza\ncomo pa quererte yo.",221,0,34,222,"",0,4,"o",-1,0,-1,0,259,259,"740","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0741",17,"Cartagena y sus castillos,\nMurcia con su Malecón,\nno arrejuntan tanta juerza\ncomo pa quererte yo.",221,0,34,222,"",0,4,"o",-1,0,-1,0,259,259,"741","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0742",17,"Cartagena con su Muelle,\nMurcia con sus morerales,\nOrihuela con sus huertos,\ny Elche con sus palmerales.",221,0,34,222,"",0,4,"ae",26,0,-1,0,260,260,"742","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0743",17,"Camino de Cartagena\nme puse a echar un cigarro;\nme acordé de mi morena,\nse me cayó de la mano.",221,0,34,222,"",0,4,"ao",-1,0,-1,0,260,260,"743","",0,"","","",4,0,0,[],"",""],["murciano_antiguo-n0744",17,"Adiós, Cartagena hermosa,\nplaceta de la Merced,\ncalle de los Cuatro Santos,\n¿cuándo te volveré a ver?",221,0,34,222,"",0,4,"e",-1,0,-1,0,260,260,"744","",0,"","","",2,0,0,[],"",""],["murciano_antiguo-n0745",17,"A Cartagena me voy\na ver el mar y sus olas,\ny a ver los barcos del rey\ncon banderas españolas.",221,0,34,222,"",0,4,"oa",317,0,-1,0,260,260,"745","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0746",17,"Cartagenita se quema,\ny el barrio de los Palmares,\ny las pobres doncellitas\ndeseando que se acabe.",221,0,34,222,"",0,4,"ae",-1,0,-1,0,261,261,"746","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0747",17,"Santa María la Vieja,\ncalle de los Cuatro Santos,\nmi amor está en un castillo;\nyo quiero subir más alto.",221,0,34,222,"",0,4,"ao",-1,0,-1,0,261,261,"747","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0748",17,"En Cartagena hay un barrio\nque le llaman la Serreta,\ndonde van los buenos mozos\na gastarse las pesetas.",221,0,34,222,"",0,4,"ea",-1,0,-1,0,261,261,"748","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0749",17,"Dicen las cartageneras\nal pie del carro triunfante:\nal castillo de Galeras\nno quiero vaya mi amante,\npues me moriré de pena.",221,0,34,222,"",7,5,"ea",-1,0,-1,0,261,261,"749","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0750",17,"Mira si he corrido tierras\nque he estado en Quitapellejos,\nSan Antón, Santa Lucía,\ny en el Matadero Viejo.",221,0,34,222,"",0,4,"eo",-1,0,-1,0,262,262,"750","",0,"","","",15,0,0,[],"",""],["murciano_antiguo-n0751",17,"Cartagena para mí,\ny Murcia para mi hermano;\ny el que no sepa escribir\nque vaya ca un escribano\ny lo enseñe como a mí.",221,0,34,222,"",7,5,"i",-1,0,-1,0,262,262,"751","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0752",17,"Cartagena, quién te viera\ny tus calles paseara,\ny a Santo Domingo fuera\na misa de madrugada.",221,0,34,222,"",0,4,"aa",-1,0,-1,0,262,262,"752","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0753",17,"Cartagena de Levante,\npuerto de mar venturoso,\nrefugio de los navíos,\ny de los hombres reposo.",221,0,34,222,"",0,4,"oo",160,0,-1,0,262,262,"753","",0,"","","",7,0,0,[],"",""],["murciano_antiguo-n0754",17,"En Santa María vivo\njunto a la Virgen de Gracia;\nayer tarde me perdí,\n¿no hay quién me lleve a mi casa?",221,0,34,222,"",0,4,"aa",-1,0,-1,0,263,263,"754","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0755",17,"Salgo por las Herrerías\ny entro por el Garbanzal;\nno eches vino, que me ahogo\ny no puedo beber más.",221,0,34,222,"",0,4,"a",-1,0,-1,0,263,263,"755","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0756",17,"En Cartagena se quema\nel barrio de los Palmares,\ny van las cartageneras\ncon agua para apagarle.",221,0,34,222,"",0,4,"ae",-1,0,-1,0,263,263,"756","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0757",17,"De Cartagena a Herrerías\nhan formado una pared;\nsobre la pared la vía,\ny sobre la vía el tren;\nsobre el tren, la nena mía.",221,0,34,222,"",7,5,"ia",0,0,-1,0,263,263,"757","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0758",17,"De Alicante voy a Elche,\nde Elche voy a Orihuela,\nde Orihuela voy a Murcia,\ny de Murcia a Cartagena.",221,0,34,222,"",0,4,"ea",-1,0,-1,0,264,264,"758","",0,"","","",1,0,0,[],"",""],["murciano_antiguo-n0759",17,"De Alicante se va a Elche,\ny de Elche se va a Orihuela,\nde Orihuela se va a Murcia,\ny en Murcia el alma se queda.",221,0,34,222,"",0,4,"ea",-1,0,-1,0,264,264,"759","",0,"","","",1,0,0,[],"",""],["preciso_coleccion-p0059-01",18,"La dulce tiranía\nde la hermosura\nrinde, triunfa, avasalla,\nmas poco dura:\ny es la desgracia\nque pasa desde el trono\ná ser esclava.",222,0,-1,223,"",4,7,"aa",-1,0,-1,0,59,59,"","",76,"palau_cantares","","",2,0,0,[],"",""],["preciso_coleccion-p0059-02",18,"Es amor un deseo\nque durar suele\nel tiempo que se goza\nlo que se quiere:\npero en logrando,\nlo que antes agradaba\nva fastidiando.",222,0,-1,223,"",4,7,"ao",33,0,-1,0,59,59,"","",76,"rm_t4","","",2,0,0,[],"",""],["preciso_coleccion-p0060-01",18,"Nace amor como planta\nen el corazon,\nel cariño la riega,\nla seca el rigor:\ny si se arraiga,\nse arranca al apartarle\nparte del alma.",222,0,-1,223,"",4,7,"aa",-1,0,-1,0,60,60,"","",76,"palau_cantares","","",4,0,0,[],"",""],["preciso_coleccion-p0060-02",18,"Soñé que me querias\nla otra mañana,\ny soñé al mismo tiempo\nque lo soñaba:\nque á un infelice\naun las dichas soñadas\nson imposibles.",222,0,-1,223,"",4,7,"ie",-1,0,-1,0,60,60,"","",76,"fernan_caballero","","",4,0,0,[],"",""],["preciso_coleccion-p0060-03",18,"Ojos mios, lloremos,\nque es el arbitrio\nque les queda á los tristes\npara su alivio:\nlloremos tanto\nque se aneguen mis ansias\nen vuestro llanto.",222,0,-1,223,"",4,7,"ao",30,0,-1,0,60,60,"","",76,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["preciso_coleccion-p0061-01",18,"Tengo en el pecho escritas\ntus falsedades,\ntengo de publicarlas\nmas que te enfades:\npues no creyera\nque me hubieras vendido\nde esta manera.",222,0,-1,223,"",4,7,"ea",44,0,-1,0,61,61,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0061-02",18,"Ay de mí! que te amo,\nay! que te quiero,\nay! que tú me aborreces,\nay! que yo muero:\nreniego en vano\nde quien soy, de quien eres,\ny de mi estado.",222,0,-1,223,"",4,7,"ao",-1,0,-1,0,61,61,"","",76,"palau_cantares","","",3,0,0,[],"",""],["preciso_coleccion-p0061-03",18,"Pensamiento que vuelas\nmas que las aves,\nllévale ese suspiro\ná quien tu sabes:\ny dile á mi amor\nque tengo su retrato\nen mi corazon.",222,0,-1,223,"",4,7,"ao",-1,0,-1,0,61,61,"","",76,"","","",4,0,0,[],"",""],["preciso_coleccion-p0062-01",18,"Hazme, mi bien, desdenes,\nque todo el tiempo\nque se tarda la dicha\nvive el deseo:\ny en mi amor noble\nsuponen esperanzas\nmas que favores.",222,0,-1,223,"",4,7,"oe",-1,0,-1,0,62,62,"","",76,"rm_t2, palau_cantares","","",3,0,0,[],"",""],["preciso_coleccion-p0062-02",18,"Finezas y desprecios\nno los archivo,\nque los vuelvo al instante\nque los recibo:\nde esta manera\ná cada uno le pago\nen su moneda.",222,0,-1,223,"",4,7,"ea",-1,0,-1,0,62,62,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0062-03",18,"El amor que te tengo\nparece sombra,\nmientras mas apartado\nmas cuerpo toma:\ny de esta forma\nmientras mas te retiras\nmas me enamoras.",222,0,-1,223,"",4,7,"oa",-1,0,-1,0,62,62,"","",76,"","","",10,0,0,[],"",""],["preciso_coleccion-p0063-01",18,"Puesto en zancos un hombre\nde baxa esfera\nes insolente y vano,\naunque él no quiera:\nnadie lo ignore,\nporque es fuerza que tire\nla cabra al monte.",222,0,-1,223,"",4,7,"oe",-1,0,-1,0,63,63,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0063-02",18,"Un páxaro en la mano\nyo bien le tuve,\nle dexé que se fuera,\n¡qué tonta anduve!\nmas si él volviera,\npor vida de mi nombre\nque no se fuera.",222,0,-1,223,"",4,7,"ea",44,0,-1,0,63,63,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0063-03",18,"¡O cruel rigurosa\nfortuna mia!\n¿quando de ser humana\nllegará el dia?\n¿quando tu rueda\nparará la inconstancia\nde su carrera?",222,0,-1,223,"",4,7,"ea",-1,0,-1,0,63,63,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0064-01",18,"Si un afligido pecho\nno suspirára,\nel rigor de su pena\nlo devorára:\nque los suspiros\nno son la menor parte\npara el alivio.",222,0,-1,223,"",4,7,"io",-1,0,-1,0,64,64,"","",76,"palau_cantares","","",2,0,0,[],"",""],["preciso_coleccion-p0064-02",18,"¡O muerte que en mis dichas\neres tirana!\n¿por qué en mis tristes penas\nno me acompañas?\npero ya advierto\nque para un infelice\nno hay muerte á tiempo.",222,0,-1,223,"",4,7,"eo",-1,0,-1,0,64,64,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0064-03",18,"Solo por un efecto\nde mi cariño\npudieron tolerarse\ntus desvarios:\ny aun de este modo\ná tus locas ideas\nno me acomodo.",222,0,-1,223,"",4,7,"oo",261,0,-1,0,64,64,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0065-01",18,"Si la pasion te ciega,\nmira primero\ndonde pones los ojos,\nno llores luego:\nlos ojos abre,\nmira que quando acuerdes\nya será tarde.",222,0,-1,223,"",4,7,"ae",-1,0,-1,0,65,65,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0065-02",18,"Acuérdome de un tiempo\nque en tí vivia,\ny por tí hago memoria\nque me moria:\nno hay bien estable;\nsépase que no hay cosa\nque no se pase.",222,0,-1,223,"",4,7,"ae",-1,0,-1,0,65,65,"","",76,"palau_cantares","","",2,0,0,[],"",""],["preciso_coleccion-p0065-03",18,"La mucha confianza\nentibia el amor,\ny su fuego se apaga\ncon la posesion:\npara avivarle\nunos zelos á tiempo\nsuelen bastarle.",222,0,-1,223,"",4,7,"ae",473,0,-1,0,65,65,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0066-01",18,"El que jura ser firme\ny eterno en amar,\ncuenta con que su gusto\nno se ha de acabar:\nmas luego el tiempo\nle muda, y lo jurado\nlo lleva el viento.",222,0,-1,223,"",4,7,"eo",-1,0,-1,0,66,66,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0066-02",18,"Herido de las flechas\ndel niño ciego\nestuve muchos años\nen cautiverio:\npero he logrado\nescapar por la puerta\ndel desengaño.",222,0,-1,223,"",4,7,"ao",-1,0,-1,0,66,66,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0066-03",18,"Ví tu hermosura, y luego\nque tus ojos ví,\ncon un suspiro dixe:\n¡ay triste de mí!\nque prisionero\ntan solo por mirarte\nahora me veo.",222,0,-1,223,"",4,7,"eo",-1,0,-1,0,66,66,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0067-01",18,"Algun dia sentia\ntus esquiveces,\ny hoy me son tus finezas\nindiferentes:\nde esta mudanza\npregúntate á tí misma\nqual es la causa.",222,0,-1,223,"",4,7,"aa",-1,0,-1,0,67,67,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0067-02",18,"Llora una dama hermosa\nporque dió oidos\ná las falsas cautelas\ndel dios Cupido:\ny al ver que yerra,\ndice anegada en llanto:\n¡quién lo creyera!",222,0,-1,223,"",4,7,"ea",-1,0,-1,0,67,67,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0067-03",18,"Llevo bandera roxa,\nporque es mi intento\nhacer guerra á Cupido\ná sangre y fuego:\ny es el motivo\nque él y los zelos siempre\nestán unidos.",222,0,-1,223,"",4,7,"io",-1,0,-1,0,67,67,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0068-01",18,"No fies en halagos\ndel dios Cupido,\naunque veas dulzuras\nen el camino:\nserán cautelas\npara ponerte á riesgo\nde que te pierdas.",222,0,-1,223,"",4,7,"ea",-1,0,-1,0,68,68,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0068-02",18,"Siempre que de tu vista\nme aparto, lloro\ntemiendo que mis dichas\nlas logre otro:\nque en mis pesares\nlas dichas son ligeras,\nlargos los males.",222,0,-1,223,"",4,7,"ae",-1,0,-1,0,68,68,"","",76,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["preciso_coleccion-p0068-03",18,"A la rama mas alta\nde tu amor subí,\nvino un ayre contrario,\ny al suelo caí:\nque esto sucede\nal que en alas de cera\nal sol se atreve.",222,0,-1,223,"",4,7,"ee",-1,0,-1,0,68,68,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0069-01",18,"No hay cosa en este mundo\nque no se mude;\nel que hoy está abatido,\nmañana sube:\nque la fortuna\ncomo viene de prisa,\nasí se muda.",222,0,-1,223,"",4,7,"ua",-1,0,-1,0,69,69,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0069-02",18,"Va un gilguerillo alegre\ná saciar la sed,\ny el cazador astuto\nle coge en la red:\n¡ó quantas veces\nbusca un hombre su alivio,\ny halla su muerte!",222,0,-1,223,"",4,7,"ee",-1,0,-1,0,69,69,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0070-02",18,"Yo sembré una mirada,\nnació un deseo,\nfloreció una esperanza,\ncogí un afecto:\nfeliz quien siembra,\nsi al fin de sus trabajos\ntiene cosecha.",222,0,-1,223,"",4,7,"ea",-1,0,-1,0,70,70,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0070-03",18,"De todas tres potencias\nque el alma tiene,\nsola una me ha quedado,\nquál es la infiere:\npero has de advertir\nque me la he reservado\npor no estar sin tí.",222,0,-1,223,"",4,7,"i",-1,0,-1,0,70,70,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0071-01",18,"Cupido, dios de amores,\ndispató diestro\nde su aljaba una flecha\ncon que me ha muerto:\ntú eres Cupido,\nyo blanco á quien dirige\ntu flecha el tiro.",222,0,-1,223,"",4,7,"io",-1,0,-1,0,71,71,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0071-02",18,"Calla, no te disculpes,\nque el cargo es justo;\nsufre, que te convenza\nde que te sufro:\nno satisfaces,\ny me quitas el gusto\nde perdonarte.",222,0,-1,223,"",4,7,"ae",-1,0,-1,0,71,71,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0071-03",18,"Se parece á la vida\nnuestro amor loco,\nmuchos años de afanes,\nal cabo un soplo:\nda buenos ratos,\npero todos acaban\ncon desengaños.",222,0,-1,223,"",4,7,"ao",-1,0,-1,0,71,71,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0072-01",18,"Enamorado y cuerdo\nnunca le he hallado,\nporque no hay hombre cuerdo\npuesto á caballo:\npor varios modos\ndel carro de los necios\ntiramos todos.",222,0,-1,223,"",4,7,"oo",418,0,-1,0,72,72,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0072-02",18,"Es á amor la polilla\nmuy semejante,\npues solo se alimenta\nde lo que nace:\nporque royendo\nestá siempre la causa\nque fué su engendro.",222,0,-1,223,"",4,7,"eo",-1,0,-1,0,72,72,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0072-03",18,"El que pone los ojos\nen imposibles,\nno extrañe que sus penas\nsean terribles:\ny es necesario\nque padezca quien quiso\nser temerario.",222,0,-1,223,"",4,7,"ao",25,0,-1,0,72,72,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0073-01",18,"Dicen regularment\nque una esperanza\nposesion suele hacerse\nbien cultivada:\npero yo he visto\nfloridas esperanzas\nque se han perdido.",222,0,-1,223,"",4,7,"io",-1,0,-1,0,73,73,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0073-02",18,"Caminaba la ausencia\nprecipitada,\nsiguiéndola el olvido\nen sus pisadas:\nque es consiguiente\nque á la ausencia el olvido\nla siga siempre.",222,0,-1,223,"",4,7,"ee",-1,0,-1,0,73,73,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0073-03",18,"Nadie de amor se burle,\ny en mí escarmiente,\nporque el amor se burla\nde sus rebeldes:\nque yo me acuerdo\nque desprecié sus grillos,\ny ahora los beso.",222,0,-1,223,"",4,7,"eo",-1,0,-1,0,73,73,"","",76,"palau_cantares","","",3,0,0,[],"",""],["preciso_coleccion-p0074-01",18,"¿A dónde me encaminas,\namor tirano?\nno des materia al fuego\nque está apagado:\nque he discurrido\nsatisfacer agravios\ncon el olvido.",222,0,-1,223,"",4,7,"io",101,0,-1,0,74,74,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0074-02",18,"En la cárcel del alma\nse encierra el amor:\ncausa disgusto preso,\ny al salir dolor:\nporque quien ama\nle dá, siempre que olvida,\ntormento á el alma.",222,0,-1,223,"",4,7,"aa",-1,0,-1,0,74,74,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0074-03",18,"Por las simples visitas\nempieza un trato,\ncon las continuaciones\nse adquiere el mando:\ny de este modo\nse logra en poco tiempo\nmandarlo todo.",222,0,-1,223,"",4,7,"oo",261,0,-1,0,74,74,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0075-01",18,"Como la mariposa\nsoy en quererte,\nque en la luz de tus ojos\nbusco mi muerte:\ny es cosa dura\nque prevenga en mis gustos\nla sepultura.",222,0,-1,223,"",4,7,"ua",17,0,-1,0,75,75,"","",76,"","","",6,0,0,[],"",""],["preciso_coleccion-p0075-02",18,"Si el amor que está preso\nsu fin no alcanza,\nse lima la cadena\ncon la esperanza:\nsigue llorando,\nporque hasta las prisiones\nablanda el llanto.",222,0,-1,223,"",4,7,"ao",-1,0,-1,0,75,75,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0075-03",18,"Te entraste por los ojos\ncon tal estrago,\nque del amor herido\nciego he quedado:\ny si algo veo\nson las dichas en sombras,\nclaros los zelos.",222,0,-1,223,"",4,7,"eo",-1,0,-1,0,75,75,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0076-01",18,"El que suspira piensa\nque así descansa,\ny si es de amor, aviva\nmejor la llama:\nse inflama el pecho,\ny quanto mas suspira\ntoma mas cuerpo.",222,0,-1,223,"",4,7,"eo",-1,0,-1,0,76,76,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0076-02",18,"Te quise en el concepto\nde que tu pecho\nqual tortolilla simple\nme amaba tierno:\npero ya miro\nque fué tu amor el llanto\ndel crocodilo.",222,0,-1,223,"",4,7,"io",-1,0,-1,0,76,76,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0077-01",18,"Yo no sé si me quieres\nó si me olvidas,\nsolo sé que yo vivo\nquando me miras:\ny así te pido\nno olvides el remedio\ncon que yo vivo.",222,0,-1,223,"",4,7,"io",-1,0,-1,0,77,77,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0077-02",18,"Loco es quien á Cupido\nciego le llama,\nque el amor por la vista\nentra en el alma:\nquien es el ciego,\nes el que por Cupido\npierde el sosiego.",222,0,-1,223,"",4,7,"eo",29,0,-1,0,77,77,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0077-03",18,"Es el amor gusano\nque el alma anima,\nel corazon engendra,\ny el pecho abriga:\ny el que le tiene\nsuele vivir muriendo\nde lo que quiere.",222,0,-1,223,"",4,7,"ee",-1,0,-1,0,77,77,"","",76,"rm_t4","","",2,0,0,[],"",""],["preciso_coleccion-p0078-01",18,"La gloria de mirarte\nserá un infierno,\nsi se van tus miradas\nhácia otro dueño:\nque es muy amargo\nver en poder ageno\nun bien logrado.",222,0,-1,223,"",4,7,"ao",-1,0,-1,0,78,78,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0078-02",18,"Pensativa en mi quarto\nmil veces digo:\nausente de quien amo\n¿cómo es que vivo?\n¿por qué conserva\nel amor esta vida\npara mas penas?",222,0,-1,223,"",4,7,"ea",-1,0,-1,0,78,78,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0078-03",18,"Nace amor de la vista,\ncrece del trato,\nse alimenta de zelos,\nmuere de agravios:\ny el que lo dude,\nque sufra lo que sufro,\nluego lo apure.",222,0,-1,223,"",4,7,"ue",-1,0,-1,0,78,78,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0079-01",18,"Por las puertas del alma\ncon gran recato\npasan los pensamientos\nde contrabando:\nporque sus guardas\nal soborno del gusto\ndan puerta franca.",222,0,-1,223,"",4,7,"aa",-1,0,-1,0,79,79,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0079-02",18,"Los zelos no son nada\nmas que sospechas:\nsi es algo, no son zelos,\nson evidencias:\ny así el amante\nno confunda aprensiones\ncon realidades.",222,0,-1,223,"",4,7,"ae",-1,0,-1,0,79,79,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0079-03",18,"El que fino idolatra\ny ausente vive,\nno tiene otro consuelo\nque quando escribe:\nque al fin la pluma\nhace mas tolerable\nla ausencia dura.",222,0,-1,223,"",4,7,"ua",-1,0,-1,0,79,79,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0080-01",18,"Has puesto mi memoria\nde tal manera,\nque de puro olvidarse\nnada me acuerda:\ntan fuera de sí,\nque á quanto la pregunto\nresponde de tí.",222,0,-1,223,"",4,7,"i",23,0,-1,0,80,80,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0080-02",18,"Me dices que á otro quieres,\npero lo dudo,\nque muger tan constante\nfingir no pudo:\npero te advierto\nque deseo con ansia\nsaber si es cierto.",222,0,-1,223,"",4,7,"eo",88,0,-1,0,80,80,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0080-03",18,"Al contemplar, bien mio,\nque he de ausentarme,\ntodas las penas vienen\ná atormentarme:\n¡Ay desdichado\ndel amor que á la ausencia\nse vé obligado!",222,0,-1,223,"",4,7,"ao",14,0,-1,0,80,80,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0081-01",18,"Sin interes te quiero\nsolo por querer:\nno hay hombre que tal haga\ncon una muger:\ny aun no merezco\nque una triste esperanza\ndes á mi afecto.",222,0,-1,223,"",4,7,"eo",-1,0,-1,0,81,81,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0081-02",18,"La que hiciese almoneda\nde sus favores,\nmire que ha de fiarlos\nal que los cobre:\nporque el secreto\nha de correr de cuenta\ndel pregonero.",222,0,-1,223,"",4,7,"eo",-1,0,-1,0,81,81,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0081-03",18,"Si piensas castigarme\ncon genio adusto,\nyo no doy gusto á nadie\nsino á mi gusto:\ny si no es bueno,\ntambien sé yo á mi gusto\nponerle freno.",222,0,-1,223,"",4,7,"eo",76,0,-1,0,81,81,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0082-01",18,"Porque ven que te quiero\nlos envidiosos,\nlevantan al cariño\nmil testimonios:\ny sus mentiras\nacrisolan finezas\ntuyas y mias.",222,0,-1,223,"",4,7,"a",-1,0,-1,0,82,82,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0082-02",18,"Corresponde á mis ansias,\nque es tiranía\nno aplicar el remedio\nquien da la herida:\ny aun es mas grave\nherida que penetra\nsin verter sangre.",222,0,-1,223,"",4,7,"ae",-1,0,-1,0,82,82,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0082-03",18,"Te ví, te amé, y al punto\nllegó la ausencia:\n¡qué dolor para un alma\nsensible y tierna!\ny mas sabiendo\nqué parto para siempre,\ny no hay remedio.",222,0,-1,223,"",4,7,"eo",-1,0,-1,0,82,82,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0083-01",18,"Amor une los lazos\nde la sociedad,\ny el que no es insensible\nnació para amar:\nnací sensible\ny amo; ¿pero á quién amo?\ná un imposible.",222,0,-1,223,"",4,7,"ie",259,0,-1,0,83,83,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0083-02",18,"En la cama me siento\ntodas las noches\ncansada de mis muchas\ncavilaciones:\ny aunque cavilo,\nno puede hallar descanso\nel pecho mio.",222,0,-1,223,"",4,7,"o",-1,0,-1,0,83,83,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0083-03",18,"Porque callo no creas\nque yo te olvido,\nque á la que menos hablo\nmas á esa estimo:\npues aun callando\nno cabe en el silencio\nlo que te amo.",222,0,-1,223,"",4,7,"ao",-1,0,-1,0,83,83,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0084-01",18,"No temas que otro pueda\nrecelo darte,\nque es conocer muy poco\nlo que tú vales:\nno son tus prendas\npara apelar á sala\nde competencias.",222,0,-1,223,"",4,7,"ea",-1,0,-1,0,84,84,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0084-02",18,"En el templo de Venus\nhay una antorcha,\nla encendió mi constancia\ny arde á mi costa:\ny el simulacro\nle componen dichosos\ny desdichados.",222,0,-1,223,"",4,7,"ao",-1,0,-1,0,84,84,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0084-03",18,"De pasadas borrascas\nescarmentado,\nindeciso en el puerto\nni entro ni salgo:\nporque los ayres,\naunque afables se muestran\nsuelen mudarse.",222,0,-1,223,"",4,7,"ae",-1,0,-1,0,84,84,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0085-01",18,"Ya se marchitó el árbol\nde mi esperanza:\nun traidor le ha cortado\nsus verdes ramas;\npero él no advierte\nque mudando terreno\nmejor florece.",222,0,-1,223,"",4,7,"ee",-1,0,-1,0,85,85,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0085-02",18,"Para aliviar mis penas\nyo necesito\ná cambio de memorias\ncomprar olvidos:\nque la memoria\nno importa que se pierda\nquando no importa.",222,0,-1,223,"",4,7,"oa",-1,0,-1,0,85,85,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0085-03",18,"Desiste de tus necias\ncabilaciones,\nmira que van erradas\ntus presunciones:\npues mi cariño\npara tí será siempre\nconstante y fino.",222,0,-1,223,"",4,7,"io",-1,0,-1,0,85,85,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0086-01",18,"Manda el señor Cupido\nque en sus milicias\nhaya pocas ausencias,\nmuchas revistas:\npues es constante\nque la plaza que vaca\nse da al instante.",222,0,-1,223,"",4,7,"ae",47,0,-1,0,86,86,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0086-02",18,"Por las cinco ventanas\nde mis sentidos\nte entrastes en mi pecho\nsin ser sentido:\npero has de advertir\nque sin sentir no puedes\nvolver á salir.",222,0,-1,223,"",4,7,"i",157,0,-1,0,86,86,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0086-03",18,"Facilitas los medios,\ny al conseguirlos\nsiempre hay casualidades\npara impedirlos:\ny de este modo\nentretienes el tiempo\nque yo malogro.",222,0,-1,223,"",4,7,"oo",-1,0,-1,0,86,86,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0087-01",18,"Siente un pecho afligido,\ny en su tormento\nviene á ser su verdugo\nel pensamiento:\npues vigilante\nno aparta la memoria\nni un solo instante.",222,0,-1,223,"",4,7,"ae",47,0,-1,0,87,87,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0087-02",18,"Lloró mi pecho un tiempo,\npero advertido\nen risa trocó el llanto\ncon el olvido:\nque hay ocasiones\nque nos da la experiencia\nbuenas lecciones.",222,0,-1,223,"",4,7,"oe",34,0,-1,0,87,87,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0087-03",18,"En confusas quimeras\nmi pensamiento\nvacilante discurre\ncon el tormento:\nsiente y padece,\ntristes sombras le afligen,\npero no muere.",222,0,-1,223,"",4,7,"ee",-1,0,-1,0,87,87,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0088-01",18,"No me culpes, tirana,\nque mi constancia\nsi falta en el cariño\ntú eres la causa:\ny así no digas\nsi en mí mudanza adviertes\npor tus intrigas.",222,0,-1,223,"",4,7,"ia",114,0,-1,0,88,88,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0088-02",18,"Suele ser la memoria\ncruel materia,\nque en el entendimiento\nforma su idea:\ny luego de ésta\nla voluntad aviva\nlo que aparenta.",222,0,-1,223,"",4,7,"ea",-1,0,-1,0,88,88,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0088-03",18,"Por tí vivo en la calle\nde la amargura:\ntú en la de los preciados\nvives segura:\ny aunque estoy loco,\npienso á la del acuerdo\nmudarme pronto.",222,0,-1,223,"",4,7,"oo",-1,0,-1,0,88,88,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0089-01",18,"En insufrible fuego\nde zelos ardo;\npor eso determino\nmorir matando:\nporque me alivia\nver á la que me mata\ntambien herida.",222,0,-1,223,"",4,7,"ia",-1,0,-1,0,89,89,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0089-02",18,"Muchos hay que no pueden\ndecir sus penas,\npues al querer decirlas\nse ahogan con ellas:\ny así las mias\nni podrás comprenderlas,\nni yo decirlas.",222,0,-1,223,"",4,7,"ia",-1,0,-1,0,89,89,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0089-03",18,"Solo quiero me digas\nsi te ha quedado\nalgun triste recuerdo\nde lo pasado:\npero me temo\nque ya de tu memoria\nno serás dueño.",222,0,-1,223,"",4,7,"eo",-1,0,-1,0,89,89,"","",76,"rm_t3, palau_cantares","","",3,0,0,[],"",""],["preciso_coleccion-p0090-01",18,"Tus exterioridades\nno son del caso,\nporque obras son amores\ndice el adagio:\ny si has pensado\nque con eso me engañas,\nte has engañado.",222,0,-1,223,"",4,7,"ao",14,0,-1,0,90,90,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0090-02",18,"Solo tus bellos ojos\nhacer pudieron\nque algun dia mis ojos\nquedasen ciegos:\npues ciego vivo,\nsé tú, dueño adorado,\nmi lazarillo.",222,0,-1,223,"",4,7,"io",-1,0,-1,0,90,90,"","",76,"palau_cantares","","",3,0,0,[],"",""],["preciso_coleccion-p0090-03",18,"Como de tu hermosura\nsabes el valor,\nno haces mayor aprecio\nde mi fiel pasion;\ny así es que dices:\nsi este amante me dexa\ntendré otros quince.",222,0,-1,223,"",4,7,"ie",-1,0,-1,0,90,90,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0091-01",18,"Páxaro que pretendes\nhacer tu nido,\nántes de llevar paja\nmira el peligro:\nluego no llores\nque te arrojen del nido\nfalsas traiciones.",222,0,-1,223,"",4,7,"oe",-1,0,-1,0,91,91,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0091-02",18,"Qual nave combatida\nse halla mi pecho\nnaufragando en las olas\nde tus desprecios:\ncon la esperanza\nque he de llegar al puerto\nde la bonanza.",222,0,-1,223,"",4,7,"aa",163,0,-1,0,91,91,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0091-03",18,"En tus aras humilde\nrendí mi pecho\ncreyendo mereciese\nalgun aprecio:\npero ¡qué dolor!\nque aun viéndome rendido\nno cesa el rigor.",222,0,-1,223,"",4,7,"o",72,0,-1,0,91,91,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0092-01",18,"No creo á los impulsos\nde mi corazon,\nque me dicen que es falsa\ntoda tu pasion:\npues segun veo\ndeben de ser engaños\nde mi deseo.",222,0,-1,223,"",4,7,"eo",66,0,-1,0,92,92,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0092-02",18,"Sin esperanza alguna\nde merecerte,\npendiente de tu gusto\ndexé mi suerte:\nde que has de inferir\nque en querer tú consiste\nel ser yo feliz.",222,0,-1,223,"",4,7,"i",-1,0,-1,0,92,92,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0092-03",18,"Si te pagas de un pecho\nconstante y fino,\ncreo que no has de hallarle\nqual es el mio:\npues en firmeza\ncon el mas fuerte muro\nva á competencia.",222,0,-1,223,"",4,7,"ea",-1,0,-1,0,92,92,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0093-01",18,"Dos afectos contrarios\nmi pecho inquietan,\nuno me dice.... sigue,\notro.... no.... cesa:\n¿dime tú qué haré?\npro.eguirc en amane?\n¿no te cansaré?",222,0,-1,223,"",4,7,"e",77,0,-1,0,93,93,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0093-02",18,"Un incendio amoroso\nmi pecho abrasa,\n¡ay de mí! si resistes\necharme al agua:\nbien que yo creo\nque no hay agua bastante\npara este incendio.",222,0,-1,223,"",4,7,"eo",-1,0,-1,0,93,93,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0093-03",18,"Quando logré la dicha\nde ver tu cielo,\nte aseguro, bien mio,\nque quedé ciego:\npero es el caso\nque no pido limosna\npor no ir tentando.",222,0,-1,223,"",4,7,"ao",-1,0,-1,0,93,93,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0094-01",18,"Déxame, pensamiento,\nno le disculpes,\nolvídale; memoria,\nvoluntad huye:\nlas tres potencias\ná las ingratitudes\ndeclaren guerra.",222,0,-1,223,"",4,7,"ea",-1,0,-1,0,94,94,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0094-02",18,"El alma me has robado,\ny así en castigo\nte he metido en la cárcel\ndel pecho mio:\ny ten paciencia,\nporque no he de soltarte\naunque te mueras.",222,0,-1,223,"",4,7,"ea",-1,0,-1,0,94,94,"","",76,"","","",5,0,0,[],"",""],["preciso_coleccion-p0094-03",18,"Un corazon sensible\nque fino te ama,\n¿cómo ha de estar contento\nsin ver tu cara?\npermita el cielo\nque yo mude de suerte,\nó tú de genio.",222,0,-1,223,"",4,7,"eo",-1,0,-1,0,94,94,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0095-01",18,"Tres dias ha que como\nlágrimas no mas,\neste es el alimento\nque tu amor me dá:\nno quiera el cielo\nque te vean mis ojos\ncomo me veo.",222,0,-1,223,"",4,7,"eo",-1,0,-1,0,95,95,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0095-02",18,"El piloto prudente\nquando hay tormenta,\npara librar la nave\narría vela:\ny en despejando\nse aprovecha aquel tiempo\ndesperdiciado.",222,0,-1,223,"",4,7,"ao",-1,0,-1,0,95,95,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0095-03",18,"Qué bien dicen que el trato\nengendra afecto:\ndígalo yo pues claro\ntengo el exemplo:\npues he logrado\nlo que no con finezas\nsolo con trato.",222,0,-1,223,"",4,7,"ao",-1,0,-1,0,95,95,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0096-01",18,"Neutral es mi bandera,\nporque conozco\nque una firme alianza\nla observan pocos:\nde esta manera\npienso estar hasta que halle\nfé verdadera.",222,0,-1,223,"",4,7,"ea",44,0,-1,0,96,96,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0096-02",18,"Si pretendes que te ame,\ndame al momento\nla voluntad, memoria\ny entendimiento,\nque me robaste;\nquando por verme fino\nme abandonaste.",222,0,-1,223,"",4,7,"ae",212,0,-1,0,96,96,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0096-03",18,"No me llamen dichoso,\ndesdichado sí,\npues solo con perderte\nmi dicha perdí:\npenas bien habrá,\npero como las mias\ndificil será.",222,0,-1,223,"",4,7,"a",-1,0,-1,0,96,96,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0097-01",18,"Tú te ves elevada\ny yo abatido,\nseñal que estuve en alto\nquando he caido:\nten cuenta tambien,\nque no faltará alguno\nque te haga caer.",222,0,-1,223,"",4,7,"e",-1,0,-1,0,97,97,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0097-02",18,"Rayo fuiste que al verte\nardió en mi pecho,\nfaltaste y ha quedado\nperenne el fuego:\nporque esta llama\nsolo apagarla puede\nlo que la inflama.",222,0,-1,223,"",4,7,"aa",90,0,-1,0,97,97,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0097-03",18,"La pretension infausta\nde mi deseo,\nmausoléo fué antes\nque no himenéo:\n¡ó suerte adversa!\napenas mi amor nace\nya nace á penas.",222,0,-1,223,"",4,7,"ea",-1,0,-1,0,97,97,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0098-01",18,"¿Es posible, tirana,\nque no merezco\nque me escuches piadosa\nquando padezco?\nmírame afable,\ny así será mi pena\nmas tolerable.",222,0,-1,223,"",4,7,"ae",322,0,-1,0,98,98,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0098-02",18,"Pienso en tí solamente,\nsola te quiero,\ny solo en mis tristezas\nde tí me acuerdo:\nesta es fineza\ntener en tí empleadas\nlas tres potencias.",222,0,-1,223,"",4,7,"ea",-1,0,-1,0,98,98,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0098-03",18,"Del dios Cupido huyendo\nme rendí al verte,\nque es su imperio en las almas\nmucho mas fuerte:\ny ahora Cupido\ncon tu desden se venga\nde mi cariño.",222,0,-1,223,"",4,7,"io",-1,0,-1,0,98,98,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0099-01",18,"Es el amor mundano\ntodo apariencia,\nsustos, disgustos, zelos,\né inconseqüencias:\nsiendo lo peor\nlas penas que se sienten\npasado el amor.",222,0,-1,223,"",4,7,"o",72,0,-1,0,99,99,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0099-02",18,"Son tus ojos dos negros\ncon arco y flechas,\nque aun dormidos disparan\ny al pecho aciertan:\ndígalo el mio,\nque lo mismo fué verlos\nque hallarse herido.",222,0,-1,223,"",4,7,"io",-1,0,-1,0,99,99,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0099-03",18,"El que no logra, espera,\ny así descansa,\ny yo triste no logro\nni aun esperanzas:\namarga suerte\ndel que no halla remedio\nsino en la muerte.",222,0,-1,223,"",4,7,"ee",134,0,-1,0,99,99,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0100-01",18,"Es el amor á veces\nmonte elevado,\nque á la cumbre se sube\ncon gran trabajo:\ny estando arriba\nes peligrosa y fácil\nqualquier caida.",222,0,-1,223,"",4,7,"aa",-1,0,-1,0,100,100,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0100-02",18,"Pecho de amor herido\ntarde se alivia,\nsi no pone el remedio\nquien dió la herida:\nmas sus dolores\nen no viendo la causa\nse hacen mayores.",222,0,-1,223,"",4,7,"oe",5,0,-1,0,100,100,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0100-03",18,"Fabio, Fabio, te nombra\nmi triste pecho\nentre las sombras tristes\nde mi tormento:\npues de tí ausente\ntu nombre en mi memoria\nmi mal divierte.",222,0,-1,223,"",4,7,"ee",-1,0,-1,0,100,100,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0101-01",18,"Ya para mí mas glorias\nno hay en el mundo,\nque todas se volviéron\npavesa y humo:\ny en tanto daño\nsolo el remedio encuentro\nde un desengaño.",222,0,-1,223,"",4,7,"ao",40,0,-1,0,101,101,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0101-02",18,"Si á quererme no aciertas\nguíate por mí,\nque aunque de amor soy ciego,\nte llevaré al fin:\nporque ya vemos\nque un ciego por la calle\nguia á otro ciego.",222,0,-1,223,"",4,7,"eo",-1,0,-1,0,101,101,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0101-03",18,"Solo para tí he sido\nfirme en el mundo:\nque aunque tú te has mudado\nyo no me mudo:\nque nunca olvido\nlos favores que hiciste\ná mi cariño.",222,0,-1,223,"",4,7,"io",-1,0,-1,0,101,101,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0102-01",18,"Nada me aflige, y tengo\nmelancolía:\nyo no sé de qué nace\nla pena mia:\nsolo me alivio\nquando rindo holocaustos\nal dios Cupido.",222,0,-1,223,"",4,7,"io",-1,0,-1,0,102,102,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0102-03",18,"Una pasion amante\nque es cuerda y sabia,\ncon todo se conforma,\nnada la agravia:\nque amor perfecto\nes solícito, sabio,\nsolo y secreto.",222,0,-1,223,"",4,7,"eo",-1,0,-1,0,102,102,"","",76,"rm_t4","","",2,0,0,[],"",""],["preciso_coleccion-p0103-01",18,"Mi corazon le tienes\nallá en tu poder,\ntrátale con cariño\ny mira por él:\ncomo yo hiciera\ncon gusto con el tuyo\nsi mio fuera.",222,0,-1,223,"",4,7,"ea",44,0,-1,0,103,103,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0103-03",18,"Albricias, desengaño,\npues ha tenido\nla dicha de encont rarle\nquien te ha perdido:\nno te me alejes,\nporque si tú me faltas\ncierta es mi muerte.",222,0,-1,223,"",4,7,"ee",-1,0,-1,0,103,103,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0104-01",18,"Solicita el alivio\nquien zelos tiene,\ny en el bien que desea\nsu daño viene:\nporque acabados\nlos zelos, le resultan\nnuevos cuidados.",222,0,-1,223,"",4,7,"ao",18,0,-1,0,104,104,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0104-02",18,"¿Qué importa que llorando\nsuspire por tí,\nsi tu correspondencia\nno he de conseguir?\nporque tu pecho\ntiene puestas las miras\nen otro objeto.",222,0,-1,223,"",4,7,"eo",-1,0,-1,0,104,104,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0104-03",18,"Han jurado mis ojos\ncegar primero,\nque ofenderte en ausencia\ncon otro dueño:\ny á jurar vuelvo\nfirme por la firmeza\nque en tu amor veo.",222,0,-1,223,"",4,7,"eo",-1,0,-1,0,104,104,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0105-01",18,"Hace el enamorado\npúblico el querer,\nporque piensa que todos\nson ciegos como él:\ny quando acuerda\nve que su pasion se halla\nbien descubierta.",222,0,-1,223,"",4,7,"ea",-1,0,-1,0,105,105,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0105-02",18,"Quando se va apagando\nde amor el fuego,\nla competencia de otro\nsuele encenderlo:\npero conozco\nque esto mas que cariño\nes amor propio.",222,0,-1,223,"",4,7,"oo",-1,0,-1,0,105,105,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0105-03",18,"Aunque andes por el mundo\ndando mil vueltas,\nimposible es que encuentres\nquien mas te quiera:\ntambien te juro\nque hasta el último aliento\nhe de ser tuyo,",222,0,-1,223,"",4,7,"uo",-1,0,-1,0,105,105,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0106-01",18,"Las plazas de Cupido\npara asaltarlas,\nno han de ser sus conquistas\ná fuerza de armas:\nque como es niño\nse asusta y estremece\nquando oye tiros.",222,0,-1,223,"",4,7,"io",-1,0,-1,0,106,106,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0106-02",18,"A dos que en larga ausencia\nfinos se quieren,\nes sola la esperanza\nquien los mantiene:\ny de este modo\nse va pasando el tiempo\npoquito á poco.",222,0,-1,223,"",4,7,"oo",-1,0,-1,0,106,106,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0106-03",18,"Todas quantas finezas\nhaces conmigo,\nson prolixos ensayos\nde otro cariño:\ny yo no quiero\nvestirme con alhaja\nque es de otro dueño.",222,0,-1,223,"",4,7,"eo",-1,0,-1,0,106,106,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0107-01",18,"Quien desconfia agravia\nal dueño amado,\npero muchos se pierden\nde confiados:\nno descuidarse\nque tal vez el mas listo\nsuele engañarse.",222,0,-1,223,"",4,7,"ae",250,0,-1,0,107,107,"","",76,"","","",2,0,0,[],"",""],["preciso_coleccion-p0107-02",18,"Soy yo tan desgraciado\nen mis amores,\nque hasta me son contrarias\nlas ocasiones:\npues á no serlo\nhubiera ya logrado\nlo que apetezco.",222,0,-1,223,"",4,7,"eo",-1,0,-1,0,107,107,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0107-03",18,"Tus ójos á mis ojos\nmiran atentos,\ny callando se dicen\nsus sentimientos:\ncosa es bien rara\nque sin hablar se entiendan\nnuestras dos almas.",222,0,-1,223,"",4,7,"aa",-1,0,-1,0,107,107,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0108-01",18,"Solo llevo en mi ausencia\npor compañero\nel recuerdo terrible\nde un bien que pierdo:\n¡qué feliz fuera\nsi pasadas memorias\nborrar pudiera!",222,0,-1,223,"",4,7,"ea",44,0,-1,0,108,108,"","",76,"","","",3,0,0,[],"",""],["preciso_coleccion-p0108-02",18,"Causa una ausencia larga\nterrible afliccion,\ny si es la ausencia eterna\ndesesperacion:\nasí sucede\ná quien se ausenta y piensa\nnunca mas verte.",222,0,-1,223,"",4,7,"ee",-1,0,-1,0,108,108,"","",76,"","","",1,0,0,[],"",""],["preciso_coleccion-p0108-03",18,"Triste estabas un dia\nquando yo llegué,\ny consternado al verte,\nmi bien, me quedé:\nmas mi tormento\nuna sonrisa tuya\ncalmó al momento.",222,0,-1,223,"",4,7,"eo",94,0,-1,0,108,108,"","",76,"","","",1,0,0,[],"",""]]);
